var e=JSON.parse(`[{"id":"advanced-mayuan-test1-1","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试一","chapterKey":"综合测试一","n":1,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试一 第 1 题"},"stem":"“两个世纪过去了，人类社会发生了巨大而深刻的变化，但马克思的名字依然在世界各地受到人们的尊敬，马克思的学说依然闪烁着耀眼的真理光芒！”马克思主义是基本立场、基本观点和基本方法的有机统一。从基本立场来看，马克思主义","choices":[{"id":"A","text":"以人民为中心，一切为了人民，一切依靠人民"},{"id":"B","text":"是关于自然、社会和人类思维发展一般规律的科学认识"},{"id":"C","text":"是实践基础上科学性和革命性的统一"},{"id":"D","text":"是建立在辩证唯物主义和历史唯物主义世界观和方法论基础上的思想方法和工作方法"}],"answer":["A"],"analysis":{"point":"本题考查马克思主义的基本立场。题干中最后的提问词是“基本立场”，所谓立场问题，就是为什么人、跟什么人站在一起的问题，在四个选项中，只有选项A提到了“人民”。因此，选项A正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"是从马克思主义的内容方面，或者说是从“基本观点”方面来解释马克思主义是什么，而不是从基本立场方面。故不选。","C":"马克思主义是实践基础上科学性与革命性的统一，这是马克思主义的基本特征，而不是基本立场。故不选。","D":"是从马克思主义的“基本方法”方面来解释马克思主义是什么，而不是从基本立场方面。故不选。"}}},{"id":"advanced-mayuan-test1-2","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试一","chapterKey":"综合测试一","n":2,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试一 第 2 题"},"stem":"恩格斯把费尔巴哈等旧唯物主义者称为“半截子”唯物主义者，并指出真正的唯物主义者在理解现实世界（自然界和历史）时是“按照它本身在每一个不以先入为主的唯心主义怪想来对待它的人面前所呈现的那样来理解……除此以外，唯物主义并没有别的意义”。这里的“半截子”主要是指","choices":[{"id":"A","text":"在坚持唯物论的同时，没有把唯物论和辩证法相结合"},{"id":"B","text":"在承认物质决定意识的同时，否认物质与意识的同一性"},{"id":"C","text":"在自然观上是唯物主义的，在历史观上则陷入唯心主义"},{"id":"D","text":"把客观事物看作既成的事实，但不承认事物的变化发展"}],"answer":["C"],"analysis":{"point":"本题考查对“半截子”唯物主义的理解。辩证唯物主义是彻底的唯物主义，在自然观上是唯物主义的，在历史观上也是唯物主义的。而本题中的“半截子”唯物主义是指费尔巴哈等人在唯物主义的立场上所表现出来的不彻底性，也就是没有把唯物主义贯彻到社会历史领域，即在自然观上是唯物主义的，在历史观上则陷入唯心主义。因此，选项C正确。","options":{"A":"“半截子”唯物主义通常不懂得将唯物论和辩证法相结合，但这并不是“半截子”唯物主义的本质特征，只是它的一种表现。故不选。","B":"无论是否为“半截子”唯物主义，唯物主义者都承认物质与意识的同一性。故不选。","C":"（正确选项，分析见“解题思路”）","D":"表述与选项A一致，不懂得辩证法，自然就不懂得事物的变化发展，但这并不是“半截子”唯物主义的本质特征。故不选。"}}},{"id":"advanced-mayuan-test1-3","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试一","chapterKey":"综合测试一","n":3,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试一 第 3 题"},"stem":"通过互联网，有人发起“超能力”的培训课程，教授学员利用“本我的意念”来移动物体的位置，甚至直接改变物质结构。这是信奉","choices":[{"id":"A","text":"精神主宰客观物质世界的主观唯心主义"},{"id":"B","text":"精神是脱离人脑独立存在的客观唯心主义"},{"id":"C","text":"人的思想是特殊物质的机械唯物主义"},{"id":"D","text":"人具有主观能动性的辩证唯物主义"}],"answer":["A"],"analysis":{"point":"本题考查对唯心主义的理解。抓住题干中的关键词“本我的意念”，即可直接判断题干中的行为信奉的是“主观唯心主义”。因此，选项A正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"客观唯心主义是唯心主义哲学的两种基本形式之一，认为精神是世界的本原，是第一性的，但精神并非个人的主观意识，而是存在于宇宙空间的一种神秘的、客观的精神，而题干中的“本我的意念”是人的主观精神，并非客观精神。故不选。","C":"机械唯物主义就是形而上学唯物主义，辩证唯物主义是辩证法与唯物论的结合，但题干强调的是唯心主义，并没有涉及唯物主义。故不选。","D":"机械唯物主义就是形而上学唯物主义，辩证唯物主义是辩证法与唯物论的结合，但题干强调的是唯心主义，并没有涉及唯物主义。故不选。"}}},{"id":"advanced-mayuan-test1-4","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试一","chapterKey":"综合测试一","n":4,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试一 第 4 题"},"stem":"恩格斯指出：“物、物质无非是各种物的总和，而这个概念就是从这一总和中抽象出来的。”这就是说，自然科学关于具体的物质形态和物质结构与哲学物质概念之间的关系是","choices":[{"id":"A","text":"个性与共性的关系"},{"id":"B","text":"形式与内容的关系"},{"id":"C","text":"要素与系统的关系"},{"id":"D","text":"现象与本质的关系"}],"answer":["A"],"analysis":{"point":"本题考查哲学中的物质概念。自然科学所讲的物质形态和物质结构是具体的，并非抽象的；是多种多样的，并非单一的。而哲学物质概念是物质世界的本原，是抽象的、单一的，也是所有具体物质形态共同的、内在的本质属性，即二者之间是个性与共性的关系。因此，选项A正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"内容是构成事物一切要素的总和，形式是内容诸要素相互结合的结构和表现方式。与题意不符，故不选。","C":"在联系的观点中，系统就是整体，是由各种各样的要素构成的。而很难说自然科学的具体物质形态构成了抽象的物质概念。与题意不符，故不选。","D":"现象是事物的外部联系和表面特征，人们可以通过感官来感知；本质是事物的内在联系和根本性质，只有通过理性思维才能把握。现象与本质是揭示客观事物的外在表现与内在联系相互关系的范畴。与题意不符，故不选。"}}},{"id":"advanced-mayuan-test1-5","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试一","chapterKey":"综合测试一","n":5,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试一 第 5 题"},"stem":"“城门失火，殃及池鱼”这一典故包含的哲学寓意是","choices":[{"id":"A","text":"事物的联系是事物本身所固有的"},{"id":"B","text":"一切事物都是变化发展的"},{"id":"C","text":"事物的现象是本质的表现"},{"id":"D","text":"任何事物都不能孤立存在，都同其他事物处于一定的联系之中"}],"answer":["D"],"analysis":{"point":"本题考查联系的观点。城门起火了，人们要用池子里的水灭火，所以池子里的鱼就遭殃了。比喻两个本来毫不相干的事物，因为某一事件而联系在一起。联系是普遍存在的，任何事物都不能孤立存在，都同其他事物处于一定的联系之中。因此，选项D正确。","options":{"A":"是联系的客观性，而题干主要强调的是联系的普遍性，与题意不符，故不选。","B":"是发展的观点，与题意不符，故不选。","C":"是现象和本质的关系，与题意不符，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-mayuan-test1-6","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试一","chapterKey":"综合测试一","n":6,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试一 第 6 题"},"stem":"虎求百兽而食之，得狐。狐曰：“子无敢食我也。天帝使我长百兽，今子食我，是逆天帝命也。子以我为不信，吾为子先行，子随我后，观百兽之见我而敢不走乎！”虎以为然，故遂与之行。兽见之皆走。虎不知兽畏己而走也，以为畏狐也。虎之所以犯这种错误，是因为其割裂了","choices":[{"id":"A","text":"必然与偶然之间的关系"},{"id":"B","text":"内容与形式之间的关系"},{"id":"C","text":"现象与本质之间的关系"},{"id":"D","text":"可能与现实之间的关系"}],"answer":["C"],"analysis":{"point":"本题考查现象与本质的关系。通过“狐假虎威”这则寓言故事，我们可以认识到，百兽害怕老虎是事物的本质，而害怕狐狸只是本质的一种表现，即现象，并且是一种假象。因此，选项C正确。","options":{"A":"百兽害怕老虎不一定是必然的，而害怕狐狸也不一定是偶然的，它们之间并非必然与偶然的关系。故不选。","B":"内容是构成事物的一切要素的总和，而形式是把诸要素统一起来的结构或表现内容的方式，并不能说害怕狐狸是害怕老虎的形式，因为“害怕狐狸”本身就是一个假命题，它是一种假象，而不是某种形式。故不选。","C":"（正确选项，分析见“解题思路”）","D":"不管是百兽害怕老虎的“本质”，还是害怕狐狸的“假象”，这些都是客观存在的，并不是某种可能，因此，“狐假虎威”的故事表达的不是“可能与现实”之间的辩证关系。故不选。"}}},{"id":"advanced-mayuan-test1-7","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试一","chapterKey":"综合测试一","n":7,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试一 第 7 题"},"stem":"中医在实践中逐渐形成了一种“取类比象”的思维方法：“取类”，把长期实践中积累的经验集中起来，发现事物之间的相类性，“观其所聚，而天地万物之情可见矣”；“比象”，在对“类”有了认识之后，“引而伸之，触类而长之”。中医“取类比象”的思维方法说明","choices":[{"id":"A","text":"抓住主要矛盾即可获得实践的成功"},{"id":"B","text":"矛盾同一性与斗争性无法共存"},{"id":"C","text":"矛盾的普遍性与矛盾的特殊性是相互联结的"},{"id":"D","text":"从整体着眼可以把握事物部分的性质"}],"answer":["C"],"analysis":{"point":"本题考查矛盾的普遍性和特殊性的辩证关系原理。矛盾的普遍性是指矛盾存在于一切事物中，存在于一切事物发展过程的始终，即所谓“矛盾无处不在，矛盾无时不有”。矛盾的特殊性是指各个具体事物的矛盾、每一矛盾的各个方面在发展的不同阶段上各有其特点。矛盾的普遍性即矛盾的共性，矛盾的特殊性即矛盾的个性。矛盾的共性和个性相统一的关系，既是客观事物固有的辩证法，也是科学的认识方法。人的认识的一般规律就是由个别上升到一般，再由一般到个别的辩证发展过程。中医中“取类”是为了发现事物之间的“普遍性”，“比象”则是为了解决“特殊性”的问题。因此，选项C正确。","options":{"A":"虽然主要矛盾在矛盾体系中处于支配地位，对事物发展起决定作用，但并不是说抓住了主要矛盾就可以获得实践的成功。故不选。","B":"同一性和斗争性是矛盾的两种基本属性，是矛盾双方相互联系的两个方面，矛盾的同一性和斗争性是相互联结、相互制约的。故不选。","C":"（正确选项，分析见“解题思路”）","D":"从内部根本矛盾出发才能把握事物的性质，与整体没有直接关系。故不选。"}}},{"id":"advanced-mayuan-test1-8","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试一","chapterKey":"综合测试一","n":8,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试一 第 8 题"},"stem":"在《论语·颜渊》中，卫国的大夫棘子成对子贡说：“君子质而已矣，何以文为？”对此，子贡驳斥道：“文犹质也，质犹文也。虎豹之鞟，犹犬羊之鞟。”后人注解称：“皮去毛曰鞟。虎豹与犬羊别者，正以毛文异耳。今使文质同者，何以别虎豹与犬羊邪？”这说明","choices":[{"id":"A","text":"形式对内容的发展起着积极的推动作用"},{"id":"B","text":"内容和形式是一一对应、不可分割的"},{"id":"C","text":"要根据内容的需要决定形式的取舍"},{"id":"D","text":"当内容相近时，形式是区别事物的主要方面"}],"answer":["D"],"analysis":{"point":"本题考查内容和形式。题干中，棘子成和子贡的辩论实质上是在讨论内容和形式的关系。“质”即内容，“文”即形式。棘子成认为君子只需要注重内容，不需要在意形式。但子贡以“虎豹”和“犬羊”为例加以反驳，认为内容和形式是相互依赖、不可分割的，内容如果脱离了形式，就像是去掉了毛的兽皮一样，无法区分。子贡的观点充分说明了当内容相近时，形式是区别事物的主要方面。因此，选项D正确。","options":{"A":"形式反作用于内容，只有当形式适合内容时，才对内容的发展起着积极的推动作用，当形式不适合内容时，就会起到消极的阻碍作用。故不选。","B":"内容和形式不是一一对应的关系，同一种内容可以采取不同的形式，同一种形式也可以表现不同的内容。故不选。","C":"题干主要强调形式的重要性，而非强调内容对形式的决定作用。故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-mayuan-test1-9","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试一","chapterKey":"综合测试一","n":9,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试一 第 9 题"},"stem":"列宁说：“人不能完全地把握—反映—描绘整个自然界、它的‘直接的总体’，人只能通过创立抽象、概念、规律、科学的世界图景等等永远地接近于这一点。”这句话表明","choices":[{"id":"A","text":"真理是相对性和绝对性的统一"},{"id":"B","text":"真理只能是主观对客观事物近似正确即相对正确的反映"},{"id":"C","text":"真理是无条件的、无限的"},{"id":"D","text":"真理是不能把握和认识的"}],"answer":["B"],"analysis":{"point":"本题考查真理的相对性。马克思主义的真理观认为真理是客观事物及其规律在人们头脑中的正确反映，或者是人们对客观事物及其规律的正确反映。真理的内容是客观的，但形式是主观的，对真理的认识是不断深化的，是由相对走向绝对的过程。列宁的这句话主要是为了说明真理是有条件的、有限的，它只是对客观世界一定程度、一定层次的近似正确的认识，有待于深化。因此，选项B正确。","options":{"A":"表述正确，但本题侧重于考查对真理相对性的理解，并没有涉及真理绝对性的内容。与题意不符，故不选。","B":"（正确选项，分析见“解题思路”）","C":"表述错误，真理是有条件的、具体的，脱离条件来谈真理将失去意义，故不选。","D":"表述错误，该说法是不可知论的观点，故不选。"}}},{"id":"advanced-mayuan-test1-10","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试一","chapterKey":"综合测试一","n":10,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试一 第 10 题"},"stem":"唐代白居易的《放言五首·其三》中写道：“试玉要烧三日满，辨材须待七年期。”这句话给我们的启示是","choices":[{"id":"A","text":"实践检验真理是一个过程，不是一次完成的"},{"id":"B","text":"实践是检验真理的唯一标准，此外无别的标准"},{"id":"C","text":"凡经实践证明的认识都不可推翻"},{"id":"D","text":"实践受社会历史条件的制约"}],"answer":["A"],"analysis":{"point":"本题考查实践检验真理的辩证发展过程。题干这句话的意思是：检验玉的真假需要烧满三天，辨别木材好坏要等七年以后。这意味着实践检验真理是一个过程，不是一次完成的，是实践检验标准不确定的表现。因此，选项A正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"本身说法正确，但与题干无关，故不选。","C":"实践能够检验一切认识，即使当前的实践还不能加以判定，最终也会被以后的实践作出裁决。本身说法正确，但与题干无关，故不选。","D":"人的实践活动受到社会历史条件的制约，具有社会历史性。本身说法正确，但与题干无关，故不选。"}}},{"id":"advanced-mayuan-test1-11","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试一","chapterKey":"综合测试一","n":11,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试一 第 11 题"},"stem":"下列属于社会意识范畴，但不属于上层建筑范畴的是","choices":[{"id":"A","text":"政治法律思想"},{"id":"B","text":"宗教思想"},{"id":"C","text":"自然科学"},{"id":"D","text":"国家政治制度和政权机构"}],"answer":["C"],"analysis":{"point":"本题考查社会意识范畴和上层建筑范畴的划分。作答这类题目可以分步骤进行：第一步，从四个选项中选出属于社会意识的范畴，经过分析可知，选项A、B、C均属于社会意识，排除选项D。第二步，在选项A、B、C中选出哪一项不属于上层建筑，上层建筑是建立在经济基础之上的，即它必与经济基础有关。通过分析可知，政治法律思想和宗教思想都是带有阶级性的，因此都属于上层建筑。排除选项A、B。因此，选项C正确。","options":{"A":"政治法律思想和宗教思想属于社会意识范畴，也属于观念上层建筑，故不选。","B":"政治法律思想和宗教思想属于社会意识范畴，也属于观念上层建筑，故不选。","C":"（正确选项，分析见“解题思路”）","D":"国家政治制度和政权机构属于政治上层建筑，但不属于社会意识范畴，故不选。"}}},{"id":"advanced-mayuan-test1-12","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试一","chapterKey":"综合测试一","n":12,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试一 第 12 题"},"stem":"“历史，并不是把人当作达到自己目的的工具来利用的某种特殊的人格。历史不过是追求着自己目的的人类的活动而已。”这句话反映出","choices":[{"id":"A","text":"社会历史发展受人的主体选择性的影响"},{"id":"B","text":"人类的活动目的本身就是历史规律"},{"id":"C","text":"历史的发展归根到底是一种精神现象"},{"id":"D","text":"人民群众的意志就是历史的发展方向"}],"answer":["A"],"analysis":{"point":"本题考查社会历史发展与人的主体选择性的关系。题干中这句话的含义就在于“历史不过是追求着自己目的的人类的活动而已”，这充分说明了社会历史规律实现的特点：客观规律性与主体选择性的统一，即可以说“社会历史发展受人的主体选择性的影响”。因此，选项A正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"关键词“目的”二字表明这个选项是错误的。人类的活动目的属于社会意识的范畴，它不能等同于客观存在的历史规律。虽然说社会历史规律体现着人们的目的，但是不能说“目的就是规律”。故不选。","C":"属于唯心史观的观点，与题干的唯物史观的观点相反，故不选。","D":"说法错误，属于唯心史观的观点，夸大了主体的目的和意志在历史发展中的作用，故不选。"}}},{"id":"advanced-mayuan-test1-13","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试一","chapterKey":"综合测试一","n":13,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试一 第 13 题"},"stem":"马克思指出：“如果物没有用，那么其中包含的劳动也就没有用，不能算作劳动，因此不形成价值。”这段话说明","choices":[{"id":"A","text":"价值的存在以物的有用性为前提"},{"id":"B","text":"价值的存在与物的有用性互为前提"},{"id":"C","text":"只要物是有用的，它就有价值"},{"id":"D","text":"物越是有用就越有价值"}],"answer":["A"],"analysis":{"point":"本题考查商品的二因素。商品的前提条件有两个：一是劳动产品，具有使用价值；二是必须用于交换，劳动产品才能转变为商品，成为商品时价值才能实现。所以，价值的存在以物的有用性（使用价值）为前提。因此，选项A正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"价值的存在是以物的有用性为前提的，但使用价值并不是以价值为前提的，故不选。","C":"物的有用性即使用价值只是商品具有价值的第一个前提，还有一个前提就是用于交换，故不选。","D":"商品价值量的大小是由生产商品所需的社会必要劳动时间决定的，故不选。"}}},{"id":"advanced-mayuan-test1-14","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试一","chapterKey":"综合测试一","n":14,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试一 第 14 题"},"stem":"数字人民币，又称e-CNY，是由中国人民银行发行的数字形式的法定货币，由指定运营机构参与运营并向公众兑换。数字人民币就是数字化的人民币，其同样是由国家信用进行背书的，具有强制性和法偿性，可以作为一般支付工具使用的法定货币。其中，数字货币能充当商品交换的媒介，这执行的货币的职能是","choices":[{"id":"A","text":"贮藏手段"},{"id":"B","text":"流通手段"},{"id":"C","text":"价值尺度"},{"id":"D","text":"世界货币"}],"answer":["B"],"analysis":{"point":"本题考查货币的职能。数字人民币具有流通手段的职能，即数字人民币具有充当商品交换媒介的职能。在商品交换过程中，商品出卖者可以把商品转化为数字人民币，然后再用数字人民币去购买商品。因此，选项B正确。","options":{"A":"贮藏手段的职能，指的是货币退出流通领域，作为社会财富的一般代表贮藏起来，与题干要求不符，故不选。","B":"（正确选项，分析见“解题思路”）","C":"价值尺度的职能，指的是货币自身也有价值，能用来衡量和表现其他商品的价值，与题干要求不符，故不选。","D":"数字人民币的世界货币职能，指的是其在世界市场上执行一般等价物的职能。传统观念认为，要作为世界货币，必须是足值的金和银，且必须脱去铸币的地域性外衣，以金块、银块的形状出现。而在当前经济全球化和信息化时代，数字人民币同样承担着作为世界货币的职能，在我国政府和中国人民银行的大力推动下，数字人民币的海外支付和结算将会更加便捷可靠。与题干要求不符，故不选。"}}},{"id":"advanced-mayuan-test1-15","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试一","chapterKey":"综合测试一","n":15,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试一 第 15 题"},"stem":"劳动力使用价值的特殊性在于，它在使用过程中","choices":[{"id":"A","text":"能转移和保存自身的价值"},{"id":"B","text":"能转移自身的价值"},{"id":"C","text":"能创造出比自身价值更大的价值"},{"id":"D","text":"随着使用价值的消失，其价值也消失"}],"answer":["C"],"analysis":{"point":"本题考查劳动力商品。劳动力商品具有使用价值与价值，其使用价值（劳动）是一般商品价值的源泉，它在使用过程中能够创造出新的价值，而且这个新的价值比劳动力本身的价值更大。这个新的价值其实就是剩余价值，而资本家就是看中这一点才去购买劳动力商品的。因此，选项C正确。","options":{"A":"劳动力自身的价值是通过工人的抽象劳动创造到一般商品中去的，并不是“转移”的，故不选。","B":"劳动力自身的价值是通过工人的抽象劳动创造到一般商品中去的，并不是“转移”的，故不选。","C":"（正确选项，分析见“解题思路”）","D":"劳动力商品的价值是由生产、发展、维持和延续劳动力所必需的生活必需品的价值决定的。它包括三个部分：一是维持劳动者本人生存所必需的生活资料的价值；二是维持劳动者家属的生存所必需的生活资料的价值；三是劳动者接受教育和训练所支出的费用。所以即使是劳动力商品的价值也不是由其使用价值决定的。故不选。"}}},{"id":"advanced-mayuan-test1-16","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试一","chapterKey":"综合测试一","n":16,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试一 第 16 题"},"stem":"马克思认为资本主义制度下的工资掩盖了资本主义剥削的本质，这是因为工资","choices":[{"id":"A","text":"是劳动者的必要劳动创造的价值"},{"id":"B","text":"是劳动力的价值"},{"id":"C","text":"是劳动力的价格"},{"id":"D","text":"表现为劳动的价格"}],"answer":["D"],"analysis":{"point":"本题考查资本主义制度下的工资。资本主义工资的本质是劳动力的价值或价格，但它表现为劳动的价值或价格，也就是说“表现”和“本质”不一样，使得看上去好像没有剥削一样。正是因为这样，才说工资掩盖了资本主义社会剥削的本质。因此，选项D正确。","options":{"A":"关于工资的表述没有问题，劳动者的必要劳动创造的价值，被称为劳动力价值，它在量上与工资等值。但本题并不是问工资是什么，而是问工资为什么掩盖了剥削，该选项并没有回答这个问题，故不选。","B":"工资的本质就是劳动力的价值或价格，但本题并不是问工资是什么，而是问工资为什么掩盖了剥削，故不选。","C":"工资的本质就是劳动力的价值或价格，但本题并不是问工资是什么，而是问工资为什么掩盖了剥削，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-mayuan-test1-17","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试一","chapterKey":"综合测试一","n":17,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试一 第 17 题"},"stem":"20世纪的社会主义制度对人类社会历史的发展作出了巨大的历史贡献，社会主义开始作为一种新的社会制度发挥历史作用。主要表现在，社会主义国家的存在及其在经济、政治、外交、军事上的影响，改变了世界的政治格局，在很大程度上遏制了资本主义和霸权主义在全世界的扩张，还表现在","choices":[{"id":"A","text":"社会主义力量坚定地支持被压迫民族的民族解放运动"},{"id":"B","text":"经济全球化对社会主义的发展既是机遇又是挑战"},{"id":"C","text":"社会主义的发展出现了曲折甚至是暂时的倒退"},{"id":"D","text":"各国的社会主义发展道路具有多样性"}],"answer":["A"],"analysis":{"point":"本题考查20世纪社会主义制度对人类历史发展的巨大贡献。20世纪的社会主义制度对人类社会历史的发展作出了巨大的历史贡献，社会主义力量坚定地支持被压迫民族和被压迫人民，推动着世界和平与发展的时代潮流。同时，社会主义在当代引导着世界人民的前进方向。因此，选项A正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"本题问的是“社会主义制度对人类历史发展的贡献”，而不是“社会主义自身发展的曲折性和多样性”，故不选。","C":"本题问的是“社会主义制度对人类历史发展的贡献”，而不是“社会主义自身发展的曲折性和多样性”，故不选。","D":"本题问的是“社会主义制度对人类历史发展的贡献”，而不是“社会主义自身发展的曲折性和多样性”，故不选。"}}},{"id":"advanced-mayuan-test1-18","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试一","chapterKey":"综合测试一","n":18,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试一 第 18 题"},"stem":"列宁指出：“马克思丝毫不想制造乌托邦，不想凭空猜测无法知道的事情。马克思提出共产主义的问题，正像一个自然科学家已经知道某一新的生物变种是怎样产生以及朝着哪个方向演变才提出该生物变种的发展问题一样。”这句话表明马克思","choices":[{"id":"A","text":"在揭示人类社会发展一般规律的基础上指明社会发展的方向"},{"id":"B","text":"在剖析资本主义社会旧世界中阐发未来新世界的特点"},{"id":"C","text":"立足于揭示未来社会的一般特征"},{"id":"D","text":"对未来社会不作详尽的细节描绘"}],"answer":["A"],"analysis":{"point":"本题考查预见未来社会的方法论原则。马克思、恩格斯站在无产阶级立场上，运用科学的方法，致力于研究人类社会特别是资本主义社会，第一次揭示了人类社会发展的一般规律和资本主义社会发展的特殊规律，从而对共产主义社会作出了科学展望。马克思、恩格斯认为，人类社会的发展像自然界的发展一样，具有自己的客观规律，揭示这些规律，就能为正确理解过去、把握现在和展望未来提供向导。因此，选项A正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"说法正确，但是题干主要强调的是马克思在揭示人类社会发展规律的基础上“指明社会发展的方向”，并没有涉及“剖析资本主义社会旧世界”“揭示未来社会的一般特征”“对未来社会不作详尽的细节描绘”等问题。与题意不符，故不选。","C":"说法正确，但是题干主要强调的是马克思在揭示人类社会发展规律的基础上“指明社会发展的方向”，并没有涉及“剖析资本主义社会旧世界”“揭示未来社会的一般特征”“对未来社会不作详尽的细节描绘”等问题。与题意不符，故不选。","D":"说法正确，但是题干主要强调的是马克思在揭示人类社会发展规律的基础上“指明社会发展的方向”，并没有涉及“剖析资本主义社会旧世界”“揭示未来社会的一般特征”“对未来社会不作详尽的细节描绘”等问题。与题意不符，故不选。"}}},{"id":"advanced-mayuan-test1-19","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试一","chapterKey":"综合测试一","n":19,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试一 第 19 题"},"stem":"发现于20世纪80年代的低频准周期振荡，是一种在X射线双星中普遍存在的时变现象，表现为光变曲线上出现类似周期性但是并非精确周期性的调制信号。中国科学院高能物理研究所利用慧眼卫星在高于200千电子伏特的能段发现了黑洞双星系统的低频准周期振荡，这是迄今为止发现的能量最高的低频准周期振荡现象，对于研究黑洞附近的广义相对论效应、物质动力学过程和辐射机制等具有重大意义。这一发现表明","choices":[{"id":"A","text":"世界是物质的，但也呈现多样性的特点"},{"id":"B","text":"整个物质世界是可知的"},{"id":"C","text":"人们通过自觉活动能够认识规律和利用规律"},{"id":"D","text":"整个物质世界的时空是有限的"}],"answer":["A","B","C"],"analysis":{"point":"本题考查世界的物质统一性原理。黑洞属于物质，但是和其他常见的物质有所不同，选项A正确。人们可以观测到黑洞，说明整个物质世界是可知的，选项B正确。低频准周期振荡现象对研究广义相对论、物质动力学和辐射机制理论都具有重大意义，说明人们不仅可以认识规律，还能够利用规律，选项C正确。因此，选项A、B、C正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"具体物质形态的时空是有限的，而整个物质世界的时空是无限的，故不选。"}}},{"id":"advanced-mayuan-test1-20","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试一","chapterKey":"综合测试一","n":20,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试一 第 20 题"},"stem":"张载《正蒙·太和篇》中云：“两不立，则一不可见；一不可见，则两之用息。”这句话包含的哲学原理有","choices":[{"id":"A","text":"矛盾的斗争性离不开同一性，斗争性寓于同一性之中"},{"id":"B","text":"矛盾的同一性是以差别和对立为前提的，是包含差别和对立的同一"},{"id":"C","text":"矛盾的同一性离不开斗争性，任何同一性都以斗争性的存在为前提和基础"},{"id":"D","text":"矛盾的普遍性不能直接存在，要通过特殊性体现出来"}],"answer":["A","B","C"],"analysis":{"point":"本题考查矛盾的同一性和斗争性及其辩证关系原理。“两不立，则一不可见”，说明斗争性是同一性存在的前提，差别和对立是任何两个事物存在的前提；“一不可见，则两之用息”，说明同一性是斗争性存在的前提。辩证法中的同一性，是指对立面的统一，并不是完全相同、等同的意思，而形而上学的同一性是完全等同的意思。因此，选项A、B、C正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"表述正确，矛盾的普遍性寓于特殊性之中，普遍性本身不能直接存在，而要通过特殊性体现出来。但与题干无关，题干中的名言讲的是矛盾的同一性和斗争性的辩证关系原理，故不选。"}}},{"id":"advanced-mayuan-test1-21","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试一","chapterKey":"综合测试一","n":21,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试一 第 21 题"},"stem":"台上，歌手变换虚拟造型穿梭于不同场景；台下，观众在会场内360度自由移动、多视角切换，或撒花欢呼，或靠近互动。有别于传统演唱会，通过VR接口，每个人都可以随时随地进入虚拟世界，选择并获取自己的专属虚拟形象，真正沉浸于虚拟场景。虚拟现实技术所构造的虚拟环境说明","choices":[{"id":"A","text":"人们可以通过实践创造出自然界原本不存在的现实状态"},{"id":"B","text":"虚拟实践是人类最基本的实践活动"},{"id":"C","text":"人类的实践活动是一个主体客体化的过程"},{"id":"D","text":"虚拟实践为人的生存与发展提供了多样的自由空间"}],"answer":["A","C","D"],"analysis":{"point":"本题考查虚拟现实技术。主体客体化，是人通过实践使自己的本质力量作用于客体，使其按照主体的需要发生结构和功能上的变化，形成了世界上本来不存在的对象物。它是人的体力和智力的物化体现，是主体的本质力量通过实践活动积淀、凝聚和物化在客体中。实际上，人类的实践活动是一个主体客体化的过程。所以，人们可以通过实践创造出自然界原本不存在的现实状态。虚拟实践是实践活动的派生形式，为人的生存与发展提供了多样的自由空间，极大地提升了人的活动的自主性、创造性。因此，选项A、C、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"物质生产实践是人类最基本的实践活动。","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-mayuan-test1-22","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试一","chapterKey":"综合测试一","n":22,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试一 第 22 题"},"stem":"新时期我国农村改革是在不断总结经验的基础上逐步展开、递次推进的，它经历了从“大包干”到税费改革，再到包括乡镇机构和管理体制等在内的综合改革、全面推进乡村振兴，继续深化农村改革等过程，从而大大促进了我国农村经济的发展。我国农村改革的历程表明","choices":[{"id":"A","text":"实践是客观见之于主观的活动"},{"id":"B","text":"人类实践活动具有社会历史性"},{"id":"C","text":"认识的发展是一个螺旋式上升的过程"},{"id":"D","text":"只有亲身参加社会实践才能获得正确认识"}],"answer":["B","C"],"analysis":{"point":"本题考查实践观。我国农村改革的历程说明人的实践活动具有社会性、历史性，人的实践活动受到一定社会历史条件的制约。在农村改革的历程中获得的认识是一个不断扩展、深化、向前推移的辩证发展过程，是像前进的波浪和上升的螺旋曲线一样发展的。因此，选项B、C正确。","options":{"A":"说法错误，实践是主观见之于客观的活动，即主观与客观相统一的活动，故不选。","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"说法错误，人们获得正确认识除亲身实践外，还可以通过间接经验，故不选。"}}},{"id":"advanced-mayuan-test1-23","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试一","chapterKey":"综合测试一","n":23,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试一 第 23 题"},"stem":"美国哲学家约翰·杜威认为，观念、概念、理论的真理并不在于它们是否符合客观实际，而在于它们是否能有效地充当人们行为的工具。我国实用主义者胡适说，真理是“人造出来供人用的，是因为它们大有用处，所以才给它们‘真理’的美名的”。他认为，真理如同粉笔、黑板、茶杯一样，“是人的一种工具”。上述观点的错误之处在于","choices":[{"id":"A","text":"否定了真理的客观性"},{"id":"B","text":"否定了真理的有用性"},{"id":"C","text":"肯定了真理必然是有用的"},{"id":"D","text":"否定了真理的一元性"}],"answer":["A","D"],"analysis":{"point":"本题考查对真理的理解。无论是杜威，还是胡适，他们的观点都属于实用主义学派，即认为“有用即真理”。实用主义真理观认为，检验一个认识是否是真理主要看它对人是否有用，因而否定了真理的客观性。真理的客观性一旦被否定，真理的一元性也就必然被否定了，因为真理不再具有客观标准，而变成了因人而异的东西。因此，选项A、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"实用主义的真理观，并没有否定真理的有用性，反而夸大了这一点。故不选。","C":"该选项干扰性较强。“实用主义真理观，肯定了真理的有用性”，这种说法是正确的，它并不是胡适等人观点的错误，因为“真理是有用的”这种观点本来就是正确的，这是胡适等人观点中正确的一面，而本题要选择的是他们观点中错误的一面。故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-mayuan-test1-24","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试一","chapterKey":"综合测试一","n":24,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试一 第 24 题"},"stem":"一方水土孕育一方文化。很早以前，人们就在平原、高原、山地、河谷、海域等广阔的地理空间发展出农耕、渔猎、游牧等不同经济形态，进而形成具有明显地域差别的文化。高铁、互联网等虽然极大消除了不同地域空间之间的界限，加速地域文化的同质性转化，但地域文化并没有消失，还在持续对当代社会发展产生重要影响。“一方水土孕育一方文化”表明","choices":[{"id":"A","text":"社会经济状况决定文化发展形态"},{"id":"B","text":"自然地理空间影响文化的外在特征"},{"id":"C","text":"文化是人类社会发展的决定力量"},{"id":"D","text":"不同形态文化的发展具有相对独立性"}],"answer":["A","B","D"],"analysis":{"point":"本题考查社会存在。“一方水土孕育一方文化”表明各地的文化受到社会经济状况与自然地理环境的影响。同时，尽管高铁、互联网等虽然极大消除了不同地域空间之间的界限，加速了地域文化的同质性转化，但是文化的多样性、地域性依然存在，说明文化具有相对独立性。因此，选项A、B、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"生产力或生产方式是人类社会发展的决定力量，而非文化。故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-mayuan-test1-25","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试一","chapterKey":"综合测试一","n":25,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试一 第 25 题"},"stem":"鲁迅先生说：“穷人绝无开交易所折本的懊恼，煤油大王哪会知道北方捡煤渣老婆子深受的酸辛，灾区的饥民，大约总不会去种兰花，像阔老太爷一样……”这句话蕴含的哲理有","choices":[{"id":"A","text":"社会存在决定社会意识"},{"id":"B","text":"社会意识是社会存在的反映"},{"id":"C","text":"社会意识内部各种形式之间相互影响"},{"id":"D","text":"社会意识内部各种形式之间具有历史继承性"}],"answer":["A","B"],"analysis":{"point":"本题考查社会存在和社会意识的辩证关系原理，属于分析理解题。题干中鲁迅先生的话的意思是，“穷人”“煤油大王”“捡煤渣老婆子”“饥民”等经济地位不同的人，有其特有的生活与思想。结合教材理论，这段话体现了社会存在决定社会意识，社会意识是社会存在的反映的原理。社会存在是社会意识内容的客观来源，社会意识是社会物质生活过程及其条件的主观反映；社会意识是人们进行社会物质交往的产物；随着社会存在的发展，社会意识也相应地或早或迟地发生变化和发展。因此，选项A、B正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"表述正确，但这是社会意识相对独立性的具体表现，题干并未涉及相关内容，故不选。","D":"表述正确，但这是社会意识相对独立性的具体表现，题干并未涉及相关内容，故不选。"}}},{"id":"advanced-mayuan-test1-26","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试一","chapterKey":"综合测试一","n":26,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试一 第 26 题"},"stem":"“革命是历史的火车头”，这是马克思在总结欧洲1848年革命经验时提出的科学论断。革命引起事物从旧质到新质的飞跃，是推动事物发生的根本变革。马克思主义认为，社会革命","choices":[{"id":"A","text":"对人类社会的发展具有重要的推动作用"},{"id":"B","text":"是新、旧社会形态实现更替的重要手段"},{"id":"C","text":"是阶级斗争的最高形式"},{"id":"D","text":"是解决社会危机的唯一途径"}],"answer":["A","B","C"],"analysis":{"point":"本题考查社会革命在阶级社会发展中的作用。阶级斗争发展到一定阶段，必然导致社会革命。社会革命是阶级斗争的最高形式，是社会形态的质变。社会革命的实质是革命阶级推翻反动阶级的统治，用新的社会制度代替旧的社会制度，解放生产力，推动社会发展。社会革命是实现社会形态更替的重要手段和决定性环节，这也是革命在社会发展中的重要作用之一。因此，选项A、B、C正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"社会基本矛盾具有不同的表现形式和解决方式，并从根本上影响和促进社会形态的变化和发展。一般来说，解决社会矛盾和社会危机的方式是暴力的社会革命或阶级斗争，但也有非暴力的改革方式。故不选。"}}},{"id":"advanced-mayuan-test1-27","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试一","chapterKey":"综合测试一","n":27,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试一 第 27 题"},"stem":"马克思批判地继承了古典政治经济学关于劳动创造价值的原理，创立了劳动二重性学说。具体劳动是指在各种具体形式下进行的劳动。抽象劳动是指撇开劳动的具体形式的、无差别的一般人类劳动。下列说法正确的有","choices":[{"id":"A","text":"具体劳动是使用价值的唯一源泉"},{"id":"B","text":"具体劳动是商品价值的实体"},{"id":"C","text":"抽象劳动是价值的唯一源泉"},{"id":"D","text":"具体劳动创造商品的使用价值"}],"answer":["C","D"],"analysis":{"point":"本题考查劳动的二重性。抽象劳动形成商品的价值，是价值的唯一源泉。科技等要素参与了商品价值创造，但其本身并不创造价值。具体劳动结合自然物质创造了商品的使用价值。因此，选项C、D正确。","options":{"A":"具体劳动必须结合自然物质，必须作用于自然物质才能产生使用价值。所以，使用价值的源泉有两个：一个是具体劳动；另一个是自然物质。故不选。","B":"抽象劳动形成商品的价值，是价值的唯一源泉。商品价值的实体是抽象劳动，劳动凝结为商品价值，如同水是冰的实体，冰是水的凝结一样。故不选。","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-mayuan-test1-28","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试一","chapterKey":"综合测试一","n":28,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试一 第 28 题"},"stem":"绝对剩余价值是在必要劳动时间不变的条件下，由于工作日长度的绝对延长而生产的剩余价值。相对剩余价值是指在工作日长度不变的条件下，由于缩短必要劳动时间，相对延长剩余劳动时间而生产的剩余价值。二者的区别在于","choices":[{"id":"A","text":"是否延长了剩余劳动时间"},{"id":"B","text":"是否增加了剩余价值量"},{"id":"C","text":"是否提高了社会劳动生产率"},{"id":"D","text":"是否追逐超额剩余价值"}],"answer":["C","D"],"analysis":{"point":"本题考查绝对剩余价值和相对剩余价值。绝对剩余价值是由于工作日长度的绝对延长而生产的剩余价值；相对剩余价值是通过提高社会劳动生产率，缩短社会必要劳动时间，从而使剩余劳动时间相对延长所生产的剩余价值。另外，追逐超额剩余价值是每个资本家改进生产技术的直接动机，各个资本家为了追逐超额剩余价值，竞相提高各自的个别劳动生产率，最终使全社会劳动生产率提高，从而使整个资产阶级普遍获得相对剩余价值。因此，选项C、D正确。","options":{"A":"无论是绝对剩余价值生产还是相对剩余价值生产，都延长了剩余劳动时间，增加了剩余价值量，只不过绝对剩余价值是通过延长工作日长度而获得的，相对剩余价值是通过压缩必要劳动时间而相对延长剩余劳动时间获得的。与题干无关，故不选。","B":"无论是绝对剩余价值生产还是相对剩余价值生产，都延长了剩余劳动时间，增加了剩余价值量，只不过绝对剩余价值是通过延长工作日长度而获得的，相对剩余价值是通过压缩必要劳动时间而相对延长剩余劳动时间获得的。与题干无关，故不选。","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-mayuan-test1-29","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试一","chapterKey":"综合测试一","n":29,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试一 第 29 题"},"stem":"马克思说：“一切现实的危机的最终原因始终是：群众贫穷和群众的消费受到限制，而与此相对立，资本主义生产却竭力发展生产力，好像只有社会的绝对的消费能力才是生产力发展的界限。”这段论述表明","choices":[{"id":"A","text":"社会的绝对的消费能力导致了经济危机的发生"},{"id":"B","text":"经济危机的发生根本上在于资本主义的基本矛盾"},{"id":"C","text":"经济危机的发生与群众的贫穷及其消费能力受到限制有关"},{"id":"D","text":"资本积累与无限扩大生产也是经济危机发生的原因"}],"answer":["B","C","D"],"analysis":{"point":"本题考查资本主义的经济危机。经济危机的发生，根本上在于资本主义的基本矛盾，同时群众的贫穷及其消费能力受到限制，生产相对过剩就难以消化。此外，资本积累与无限扩大生产最终导致资本有机构成的变化以及相对过剩人口（失业人口）的产生也是经济危机发生的原因。因此，选项B、C、D正确。","options":{"A":"表述错误，经济危机发生的原因是资本主义的基本矛盾。","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-mayuan-test1-30","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试一","chapterKey":"综合测试一","n":30,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试一 第 30 题"},"stem":"垄断资本的实质在于获取垄断利润，垄断利润主要通过垄断组织制定的垄断价格来实现。垄断价格包括垄断高价和垄断低价两种形式。垄断高价和垄断低价并不否认价值规律，是因为","choices":[{"id":"A","text":"垄断价格的出现并没有改变价值规律作用的表现形式"},{"id":"B","text":"垄断高价和垄断低价不能完全背离商品的价值"},{"id":"C","text":"从整个社会来看，商品的价格总额仍然等于商品的价值总量"},{"id":"D","text":"垄断价格只是对商品价值和剩余价值作了有利于垄断资本的再分配"}],"answer":["B","C","D"],"analysis":{"point":"本题考查垄断利润。垄断高价和垄断低价虽然长期背离生产价格和价值，但并不能完全背离商品的价值。从全社会看，垄断价格既不能增加也不能减少整个社会所生产的价值总量，垄断企业通过垄断价格多得的利润，正是其他商品生产者和消费者失去的价值部分。所以从整个社会来看，商品的价格总额仍然等于商品的价值总量。商品的价值总量没有变，垄断价格只是对商品价值和剩余价值作了有利于垄断资本的再分配，通过垄断的形式获得别人的部分利润。因此，选项B、C、D正确。","options":{"A":"说法错误，在简单商品经济时期，价值规律的表现形式是价格围绕价值自发波动；在垄断资本主义时期，价值规律表现为价格围绕垄断价格上下波动。所以，垄断价格的出现改变了价值规律作用的表现形式。故不选。","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-mayuan-test2-1","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试二","chapterKey":"综合测试二","n":1,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试二 第 1 题"},"stem":"马克思指出：“哲学家们只是用不同的方式解释世界，而问题在于改变世界。”习近平进一步提出：“马克思主义不仅致力于科学‘解释世界’，而且致力于积极‘改变世界’。”这体现出","choices":[{"id":"A","text":"马克思主义具有科学的世界观和方法论基础"},{"id":"B","text":"马克思主义首要的和基本的观点是实践观点"},{"id":"C","text":"马克思主义的鲜明特色是敢于斗争、善于斗争"},{"id":"D","text":"马克思主义具有与时俱进的理论品质"}],"answer":["B"],"analysis":{"point":"本题考查马克思主义的基本特征。“改变世界”就是要去实践、去做。从马克思主义的内容来看，实践观点是马克思主义首要的和基本的观点，这一基本观点体现在马克思主义全部思想内容之中。马克思主义具有突出的实践精神，它始终强调理论与实践的统一，始终坚持与社会主义实际运动紧密结合。因此，选项B正确。","options":{"A":"马克思主义具有科学的世界观和方法论基础，即辩证唯物主义和历史唯物主义，这是马克思主义的一个突出特征和理论优势。与题干无关，故不选。","B":"（正确选项，分析见“解题思路”）","C":"运用矛盾的同一性和斗争性辩证关系原理指导实践，还要大力发扬斗争精神。敢于斗争、善于斗争是马克思主义的鲜明特色，是中国共产党人的鲜明品格。与题干无关，故不选。","D":"马克思主义是不断发展的开放的学说，具有与时俱进的理论品质。马克思主义是时代的产物，并随着时代、实践和科学的发展而不断发展。与题干无关，故不选。"}}},{"id":"advanced-mayuan-test2-2","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试二","chapterKey":"综合测试二","n":2,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试二 第 2 题"},"stem":"世界分化为客观世界和主观世界。客观世界是不依赖于人的思想意识而存在的现实世界。主观世界是指人的意识、观念世界，是人的头脑反映和把握物质世界的精神活动的总和。下列关于客观世界和主观世界的说法，正确的是","choices":[{"id":"A","text":"客观世界中的一切都是自发产生的"},{"id":"B","text":"主观世界是一个独立存在的实体，具有相对独立性"},{"id":"C","text":"客观世界和主观世界是绝对对立的"},{"id":"D","text":"主观世界根源于客观世界"}],"answer":["D"],"analysis":{"point":"本题考查物质世界的二重化。世界分化为客观世界和主观世界。客观世界是不依赖于人的思想意识而存在的现实世界，包括自然界和人类社会。主观世界从客观世界中分化出来，具有相对独立性。客观世界和主观世界的关系实际上就是物质和意识的关系，所以主观世界根源于客观世界。因此，选项D正确。","options":{"A":"客观世界包含人类社会和自然界，其中只有自然界中的一切是自发产生的，人类社会的产生是人类实践活动的结果。故不选。","B":"主观世界不是一个独立存在的实体，它依赖于客观世界，又有自己的发展规律，具有相对独立性。故不选。","C":"客观世界和主观世界既有区别，又有联系，是斗争同一的，并不是绝对对立的。故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-mayuan-test2-3","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试二","chapterKey":"综合测试二","n":3,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试二 第 3 题"},"stem":"当“新视野”号穿越漫无边际的孤寂与黑暗，把冥王星的清晰照片传回地球，似乎所有清澈的眼睛，都把目光投向深不可测的鸿蒙太空。沸腾在人们心里的，不仅是对天文的好奇，更有一种难言的感动。最遥远的行星，在人们心里引起最切近的感动。正如网友所言，这是无可救药的泪点，若宇宙浪漫，便感动何妨？下列对于“感动”判断正确的是","choices":[{"id":"A","text":"人脑是“感动”的源泉"},{"id":"B","text":"“感动”的内容和形式都是客观的"},{"id":"C","text":"“感动”是客观内容和主观形式的统一"},{"id":"D","text":"“感动”是对浪漫宇宙的直观反映"}],"answer":["C"],"analysis":{"point":"本题考查意识的本质。题干中的“感动”是指人的思想意识、情感，因而是人脑对客观世界的主观反映。意识在内容上是客观的，而在形式上是主观的，所以意识是客观内容和主观形式的统一。因此，选项C正确。","options":{"A":"人脑是产生意识的物质器官，不是意识的源泉，故不选。","B":"“感动”的内容是客观的，形式是主观的，故不选。","C":"（正确选项，分析见“解题思路”）","D":"“感动”是对浪漫宇宙的能动反映，故不选。"}}},{"id":"advanced-mayuan-test2-4","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试二","chapterKey":"综合测试二","n":4,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试二 第 4 题"},"stem":"云南省地处我国边陲，气候温暖湿润，是我国少数民族最多的省份。该省经过分析认为，虽然具有资源、气候、区位三大优势，但也有基础产业薄弱、经济结构单一、居民文化素质较低三大劣势。根据这种状况，该省制定了自己的发展战略，即建设绿色经济强省、民族文化大省和中国面向东南亚的国际大通道。云南省制定的这一发展战略，体现了","choices":[{"id":"A","text":"事物是运动、变化、发展的"},{"id":"B","text":"一切从实际出发，实事求是"},{"id":"C","text":"矛盾的主要方面和次要方面的辩证关系"},{"id":"D","text":"事物发展过程是前进性和曲折性的统一"}],"answer":["B"],"analysis":{"point":"本题考查一切从实际出发，实事求是。题干中云南省正确分析了本省的实际情况，从实际出发制定了本省的发展战略，反映的就是一切从实际出发，实事求是。因此，选项B正确。","options":{"A":"表述正确，但题干中并没有体现，故不选。","B":"（正确选项，分析见“解题思路”）","C":"表述正确，但题干中并没有体现，故不选。","D":"表述正确，但题干中并没有体现，故不选。"}}},{"id":"advanced-mayuan-test2-5","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试二","chapterKey":"综合测试二","n":5,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试二 第 5 题"},"stem":"“橘生淮南则为橘，生于淮北则为枳，叶徒相似，其实味不同。所以然者何？水土异也。”“橘逾淮为枳”说明了","choices":[{"id":"A","text":"事物的发展变化以时间、地点和条件为转移"},{"id":"B","text":"事物的普遍联系是通过中介来实现的"},{"id":"C","text":"任何具体事物都是普遍联系之网上的一个网结"},{"id":"D","text":"事物的变化和发展是一个过程"}],"answer":["A"],"analysis":{"point":"本题考查联系和发展的观点。本题题干中引用的文句讲的是，同样品种的橘子，生长在不同的地方，就会得到不同口味的果实。这体现了事物的发展变化，与时间、地点和条件都有关联。因此，选项A正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"说法本身均正确，都符合马克思主义哲学原理，但是与本题题干契合度不高，橘子种在淮南和淮北的差别与“中介”“网络”无关，也并不是什么“过程”问题，故不选。","C":"说法本身均正确，都符合马克思主义哲学原理，但是与本题题干契合度不高，橘子种在淮南和淮北的差别与“中介”“网络”无关，也并不是什么“过程”问题，故不选。","D":"说法本身均正确，都符合马克思主义哲学原理，但是与本题题干契合度不高，橘子种在淮南和淮北的差别与“中介”“网络”无关，也并不是什么“过程”问题，故不选。"}}},{"id":"advanced-mayuan-test2-6","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试二","chapterKey":"综合测试二","n":6,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试二 第 6 题"},"stem":"一根筷子放入盛满清水的杯中，看上去像被折断了一样。关于这一现象，下列说法正确的是","choices":[{"id":"A","text":"通过感官感知到的都是对客观事物真实的反映"},{"id":"B","text":"人们看到筷子像被折断了一样完全是一种主观的错觉"},{"id":"C","text":"筷子的本质无法通过现象表现出来"},{"id":"D","text":"这是一种用歪曲形式表现本质的现象"}],"answer":["D"],"analysis":{"point":"本题考查现象与本质的关系。“一根筷子放入盛满清水的杯中，看上去像被折断了一样。”这是一种用歪曲形式表现本质的现象，即假象，“看上去像被折断了一样”的假象歪曲了“筷子本身并没有断”这一本质。因此，选项D正确。","options":{"A":"如果通过感官感知到的都是对事物正确的、真实的反映的话，那么理性思维就显得没有必要了。因此，这种观点是错误的，事物的本质往往会隐藏起来，或者通过一些现象（包括假象）表现出来。故不选。","B":"说法错误，错觉是一种主观的错误感知，而本题所描述的“筷子被折断了”并不是主观的，因为通过光的折射，人们看到的的确是“折断了的筷子”，这是客观存在的。故不选。","C":"说法错误，没有不表现为现象的本质，也没有不表现本质的现象。因此，筷子的本质是一定可以通过现象表现出来的，无论是真象还是假象。故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-mayuan-test2-7","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试二","chapterKey":"综合测试二","n":7,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试二 第 7 题"},"stem":"《百喻经》中有一则寓言：有一个愚人到别人家去做客，他嫌菜没有味道，主人就给他加了点盐。菜里加盐以后，味道好极了。愚人就想：“菜之所以鲜美，是因为有了盐。加一点点就如此鲜美，如果加更多的盐，岂不更加好吃？”回家之后，他把一把盐放进嘴里，结果又苦又咸。这则寓言给我们的启示是","choices":[{"id":"A","text":"持续的量变会引起事物发生质的变化"},{"id":"B","text":"在认识和处理问题时要掌握适度的原则"},{"id":"C","text":"在事物的发展过程中要时时注意事物的自我否定"},{"id":"D","text":"不可能通过一些现象而去认识某个事物的本质"}],"answer":["B"],"analysis":{"point":"本题考查量变质变规律。这是历年考研真题中反复考查的高频考点，考生应予以重视。题干中的关键词“更多的盐”与适度原则相对应。因此，选项B正确。","options":{"A":"质变是量变的必然结果，说法正确，但与题意不符。","B":"（正确选项，分析见“解题思路”）","C":"“在事物的发展过程中要时时注意事物的自我否定”是正确的观点，体现了辩证法的否定观，但与题意不符。","D":"说法错误，事物的本质都是通过现象表现出来的。"}}},{"id":"advanced-mayuan-test2-8","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试二","chapterKey":"综合测试二","n":8,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试二 第 8 题"},"stem":"哲学家康德认为，人类最高层次的知识是天才头脑中创造的，而“天才有天赋的才能”，具有“天生的心灵禀赋”。这种观点属于","choices":[{"id":"A","text":"唯意志论"},{"id":"B","text":"朴素唯物主义"},{"id":"C","text":"唯心主义先验论"},{"id":"D","text":"宿命论"}],"answer":["C"],"analysis":{"point":"本题考查对唯心主义的理解。唯心主义哲学把认识看作先于物质、先于实践经验的东西。题干中康德离开实践去寻找认识的来源，从人类“先验的结构”“天赋的能力”中去寻找认识的来源，属于唯心主义先验论的观点。因此，选项C正确。","options":{"A":"唯意志论是过分夸大意识的能动作用，而本题探讨的是认识的来源问题。与题意不符，故不选。","B":"朴素唯物主义依据对自然现象的笼统直观，把哲学的抽象范畴“物质”归结为物质的具体形态。与题意不符，故不选。","C":"（正确选项，分析见“解题思路”）","D":"宿命论过分夸大客观规律性，否定人的意识的能动作用，与康德的观点刚好相反。与题意不符，故不选。"}}},{"id":"advanced-mayuan-test2-9","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试二","chapterKey":"综合测试二","n":9,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试二 第 9 题"},"stem":"马克思在《资本论》中指出：“每一种这样的物都是许多属性的总和，因此可以在不同的方面有用。发现这些不同的方面，从而发现物的多种使用方式，是历史的事情。”这说明作为反映主体和客体之间意义关系的价值具有","choices":[{"id":"A","text":"主体性"},{"id":"B","text":"客观性"},{"id":"C","text":"主观性"},{"id":"D","text":"多维性"}],"answer":["D"],"analysis":{"point":"本题考查价值的基本特性。价值的多维性是指每个主体的价值关系具有多样性，同一客体相对于主体的不同需要会产生不同的价值。因此，选项D正确。","options":{"A":"与题干无关，故不选。","B":"与题干无关，故不选。","C":"价值不具有主观性，而是具有主体性，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-mayuan-test2-10","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试二","chapterKey":"综合测试二","n":10,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试二 第 10 题"},"stem":"有一种观点认为，“自由不在于幻想中摆脱自然规律而独立，而在于认识这些规律，从而能够有计划地使自然规律为一定的目的服务”。还有一种观点认为，“‘自由’倒过来就是‘由自’，因此‘自由’等于‘由自’，‘由自’即是随心所欲”。这两种关于自由的观点","choices":[{"id":"A","text":"前者是唯物辩证法的观点，后者是唯意志论的观点"},{"id":"B","text":"前者是机械唯物主义的观点，后者是唯心主义的观点"},{"id":"C","text":"前者是历史唯心主义的观点，后者是历史唯物主义的观点"},{"id":"D","text":"前者是主观唯心主义的观点，后者是唯物辩证法的观点"}],"answer":["A"],"analysis":{"point":"本题考查马克思主义的自由观。马克思主义认为自由不是绝对的自由，而是有前提条件的：一是不以牺牲别人的自由为条件；二是以坚持“必然”也就是自然规律为前提条件。夸大必然否定自由将导致“宿命论”，而夸大自由否定必然将导致“唯意志论”。题干中，前一种观点属于唯物辩证法的正确观点，以既主张自由又不否认自然规律为前提；后一种观点则属于过分夸大自由的唯意志论的观点。因此，选项A正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"唯意志论的自由观属于唯心主义，辩证唯物主义的自由观与机械唯物主义的自由观则是对立的，不能等同，故不选。","C":"前一种观点既是辩证唯物主义的，也是历史唯物主义的；后一种观点是唯意志论，属于历史唯心主义的观点。选项C说反了，故不选。","D":"前一种观点是唯物辩证法；后一种观点是唯意志论，归根到底属于历史唯心主义，同时也属于主观唯心主义。选项D说反了，故不选。"}}},{"id":"advanced-mayuan-test2-11","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试二","chapterKey":"综合测试二","n":11,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试二 第 11 题"},"stem":"有一个部落位于沼泽地边缘，经常出现人和牲畜陷入沼泽溺亡的事，导致该部落人口稀少，经常被其他部族欺负。为了摆脱这种局面，全族人迁到了一片水草肥美的草原。环境的改变导致该部落人口大量增加，马匹牲畜也膘肥体壮，逐渐吞并了其他部落成为草原的霸主，并最终入主中原，导致了朝代的更迭。这个故事说明","choices":[{"id":"A","text":"自然地理环境和人口因素决定社会发展"},{"id":"B","text":"外因是事物变化的根本原因"},{"id":"C","text":"自然地理环境和人口因素是社会存在和发展的必要条件"},{"id":"D","text":"实践是推动社会发展的根本动力"}],"answer":["C"],"analysis":{"point":"本题考查社会存在的相关内容。根据题干可以定位本题考查“历史唯物主义”，基本观点是社会存在和社会意识的辩证关系，其中自然地理环境和人口因素是社会存在和发展的必要条件。因此，选项C正确。","options":{"A":"表述错误，自然地理环境和人口因素作为社会存在的重要组成部分，并不对社会发展起决定作用，故不选。","B":"表述错误，内因是事物发展的根本原因，外因是事物变化发展的条件，故不选。","C":"（正确选项，分析见“解题思路”）","D":"表述错误，历史唯物主义认为，社会基本矛盾是推动社会发展的根本动力，故不选。"}}},{"id":"advanced-mayuan-test2-12","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试二","chapterKey":"综合测试二","n":12,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试二 第 12 题"},"stem":"资本家总是非常关心自己所生产的商品的效能，利用各种技术手段来检测商品是否合格、是否满足消费者的需求。资本家关心商品使用价值的根本原因在于","choices":[{"id":"A","text":"资本家觉悟高，能从社会利益的角度考虑问题"},{"id":"B","text":"迫于资本主义国家法律、法令的要求"},{"id":"C","text":"使用价值是价值的物质承担者，商品的使用价值影响着资本循环能否正常进行"},{"id":"D","text":"商品性能越好，使用价值越高，所含价值量就越高，从而一定能卖出更好的价钱"}],"answer":["C"],"analysis":{"point":"本题考查使用价值和价值的关系。使用价值和价值是商品的两种基本属性，对于商品而言，二者缺一不可，但也相互对立，不可兼得，资本家要想获得商品的价值，就必须让渡商品的使用价值，因为使用价值是价值的物质承担者。若商品的使用价值不达标，则可能导致商品交换失败，进而影响资本循环的正常进行。因此，选项C正确。","options":{"A":"完全偏离了资本主义自私自利的本质，故不选。","B":"是资本主义发展的附加条件，不符合题意，故不选。","C":"（正确选项，分析见“解题思路”）","D":"逻辑有问题，使用价值并不能决定商品的价值量，商品的价值量是由生产商品的社会必要劳动时间决定的，故不选。"}}},{"id":"advanced-mayuan-test2-13","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试二","chapterKey":"综合测试二","n":13,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试二 第 13 题"},"stem":"在相同的劳动时间里，复杂劳动创造的价值大于简单劳动创造的价值。在以私有制为基础的商品经济条件下，复杂劳动转化为简单劳动是","choices":[{"id":"A","text":"市场管理部门事先规定的"},{"id":"B","text":"商品生产者自觉计算出来的"},{"id":"C","text":"商品生产者协商出来的"},{"id":"D","text":"商品交换过程中市场机制自发实现的"}],"answer":["D"],"analysis":{"point":"本题考查简单劳动和复杂劳动。商品的价值量同简单劳动和复杂劳动密切相关。简单劳动是指不需要经过专门训练和培养的一般劳动者都能从事的劳动；复杂劳动是指需要经过专门训练和培养，具有一定文化知识和技术专长的劳动者所从事的劳动。商品的价值量是以简单劳动为尺度计量的，复杂劳动等于自乘的或多倍的简单劳动。复杂劳动换算为简单劳动，是在商品交换过程中自发实现的。因此，选项D正确。","options":{"A":"复杂劳动换算为简单劳动，是在商品交换过程中自发实现的，这是市场规律的作用，并非人为规定。故不选。","B":"复杂劳动换算为简单劳动，是在商品交换过程中自发实现的，这是市场规律的作用，并非人为规定。故不选。","C":"复杂劳动换算为简单劳动，是在商品交换过程中自发实现的，这是市场规律的作用，并非人为规定。故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-mayuan-test2-14","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试二","chapterKey":"综合测试二","n":14,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试二 第 14 题"},"stem":"价值形式，就是商品价值的表现形式，也就是交换价值。在商品交换的发展过程中，价值形式的发展经历了四个阶段。其中不存在等价物的价值形式是","choices":[{"id":"A","text":"简单的或偶然的价值形式"},{"id":"B","text":"总和的或扩大的价值形式"},{"id":"C","text":"一般价值形式"},{"id":"D","text":"货币形式"}],"answer":["A"],"analysis":{"point":"本题考查价值形式的发展。简单的或偶然的价值形式是在原始公社之间发生的。原始部落都处于自给自足的自然经济中，由于自然环境、生产条件不同，偶尔会发生互相交换余缺产品的行为，可用以下等式来表示：2只羊=1把斧子。这是商品交换处于萌芽阶段的价值表现形式，它属于物物直接交换，不存在等价物。因此，选项A正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"总和的或扩大的价值形式可用以下等式来表示：2只羊=1把斧子，或=1担谷，或=1包盐，等等。这一价值形式反映了在生产力发展和社会分工形成的条件下日益扩大的商品交换关系，此时，羊已经成为货物流通的等价物了。故不选。","C":"一般价值形式，这一阶段商品交换的特点，就是出现了表现一切商品价值的一般等价物。一般等价物出现以后，一切商品的价值都通过它来表现。千千万万种商品的价值，有了一般的即统一的表现形式，因此称作一般价值形式。故不选。","D":"货币形式，货币是固定地充当一般等价物的金（或银）。自从出现了货币，一切商品首先同货币相交换，用货币表现自己的价值，从而出现了价值的货币形式。故不选。"}}},{"id":"advanced-mayuan-test2-15","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试二","chapterKey":"综合测试二","n":15,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试二 第 15 题"},"stem":"影响资本周转快慢的因素有很多，关键的因素有两个：一是资本周转时间；二是生产资本中固定资本和流动资本的构成。下列既属于可变资本又属于流动资本的是","choices":[{"id":"A","text":"用于支付工人工资的部分"},{"id":"B","text":"用于购买原料和燃料的部分"},{"id":"C","text":"用于购买机器设备的部分"},{"id":"D","text":"用于出售商品实现价值的部分"}],"answer":["A"],"analysis":{"point":"本题考查资本的划分。可变资本是用于购买劳动力的那部分资本，在生产过程中，工人的劳动不仅可以再生产出自身劳动力的价值而且会创造出大于这一价值的价值，使得这部分预付资本的价值量发生了变化。流动资本是指用于购买原料、燃料等劳动资料和用于购买劳动力的那部分生产资本。综上所述，选项A既是可变资本又是流动资本。因此，选项A正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"按照定义属于流动资本，但它属于不变资本，不变资本就是用于购买生产资料的那部分资本。在生产过程中，借助工人的具体劳动，把原有的价值转移到新产品中，其价值量没有发生变化。故不选。","C":"属于不变资本和固定资本，固定资本是以机器、设备、厂房和工具等劳动资料形式存在的生产资本。它的物质形态全部参加生产过程，虽然受到磨损，但仍然长期保持固定的物质形态。它的价值不是一次全部转移的，而是在生产过程中通过工人的具体劳动并随着磨损一部分一部分地转移到新产品中。故不选。","D":"用于出售商品实现价值的部分，是在资本循环中的售卖阶段，资本执行商品资本的职能，发挥实现剩余价值的职能。与题意不符，故不选。"}}},{"id":"advanced-mayuan-test2-16","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试二","chapterKey":"综合测试二","n":16,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试二 第 16 题"},"stem":"某企业投资汽车生产，生产一辆汽车所耗费的生产资料价值为15万元，支付给工人的工资为5万元，假定市场的平均利润率为10%，那么，在自由竞争条件下，该汽车的生产价格是","choices":[{"id":"A","text":"20万元"},{"id":"B","text":"20.5万元"},{"id":"C","text":"21.5万元"},{"id":"D","text":"22万元"}],"answer":["D"],"analysis":{"point":"本题考查生产价格的计算。根据马克思主义政治经济学的基本知识可知，生产价格 = 成本价格（预付资本）+ 平均利润。由题干可知，不变资本 c 为 15 万元，可变资本 v 为 5 万元，可以得出成本价格（预付资本）为 20 万元。由于平均利润率是 10%，因此，投入 20 万元获得的平均利润就是 2 万元，成本价格（预付资本）与平均利润相加，可计算出生产价格为 22 万元。因此，选项 D 正确。","options":{"A":"均计算错误。","B":"均计算错误。","C":"均计算错误。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-mayuan-test2-17","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试二","chapterKey":"综合测试二","n":17,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试二 第 17 题"},"stem":"列宁指出，不能“为死教条而牺牲活的马克思主义”。习近平全面总结社会主义历史进程，得出“社会主义从来都是在开拓中前进的”。这些表述对我们的深刻启示是","choices":[{"id":"A","text":"必须始终“坚持科学社会主义基本原则”"},{"id":"B","text":"要把科学社会主义基本原则与本国实际相结合"},{"id":"C","text":"科学社会主义基本原则要紧跟时代和实践的发展而发展"},{"id":"D","text":"时代和实践的不断发展使社会主义发展道路具有多样性"}],"answer":["C"],"analysis":{"point":"本题考查正确把握科学社会主义基本原则。紧跟时代和实践的发展，在不断总结新鲜经验中进一步丰富和发展科学社会主义基本原则。因此，选项 C 正确。","options":{"A":"强调马克思主义必须随着时代的发展而发展，必须以坚持基本原则为前提，故不选。","B":"把科学社会主义基本原则与本国实际相结合，创造性地回答和解决社会主义革命、建设、改革中的重大问题，与题意不符，故不选。","C":"（正确选项，分析见“解题思路”）","D":"强调社会主义发展道路的多样性，不符合题意，故不选。"}}},{"id":"advanced-mayuan-test2-18","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试二","chapterKey":"综合测试二","n":18,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试二 第 18 题"},"stem":"共产主义社会是人类社会发展的最高社会形态，这一社会实现的必要条件是","choices":[{"id":"A","text":"社会关系的高度和谐"},{"id":"B","text":"人自由而全面的发展"},{"id":"C","text":"生产力的高度发展"},{"id":"D","text":"阶级和国家的消亡"}],"answer":["C"],"analysis":{"point":"本题考查实现共产主义社会的必要条件。共产主义是人类社会发展的必然趋势，是由人类社会发展的客观规律决定的。人类社会的发展，是生产力和生产关系矛盾运动的结果。生产关系一定要适合生产力的发展状况，是一切社会发展的普遍规律。社会发展归根结底是由生产力发展水平决定的，只有生产力高度发达，共产主义社会才能够实现。社会生产力高度发展，产品极大丰富，是实现共产主义社会的必要条件。因此，选项 C 正确。","options":{"A":"选项 A、B 属于共产主义社会的基本特征，选项 D 是选项 A 的表现之一，即选项 D 包含于选项 A 中，但题干强调的是实现共产主义社会的必要条件。与题意不符，故不选。","B":"选项 A、B 属于共产主义社会的基本特征，选项 D 是选项 A 的表现之一，即选项 D 包含于选项 A 中，但题干强调的是实现共产主义社会的必要条件。与题意不符，故不选。","C":"（正确选项，分析见“解题思路”）","D":"选项 A、B 属于共产主义社会的基本特征，选项 D 是选项 A 的表现之一，即选项 D 包含于选项 A 中，但题干强调的是实现共产主义社会的必要条件。与题意不符，故不选。"}}},{"id":"advanced-mayuan-test2-19","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试二","chapterKey":"综合测试二","n":19,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试二 第 19 题"},"stem":"列宁指出，“马克思和恩格斯在他们的著作中特别强调的是‘辩证’唯物主义，而不是辩证‘唯物主义’，特别坚持的是‘历史’唯物主义，而不是历史‘唯物主义’”。下列关于马克思主义的理解正确的有","choices":[{"id":"A","text":"马克思主义哲学与旧唯物主义有着本质的区别"},{"id":"B","text":"马克思主义具有科学的世界观和方法论基础，即辩证唯物主义和历史唯物主义"},{"id":"C","text":"马克思主义实现了唯物辩证的自然观和历史观的统一"},{"id":"D","text":"马克思主义哲学坚持自然规律与社会历史规律是相同的"}],"answer":["A","B","C"],"analysis":{"point":"本题考查马克思主义。列宁的这一论述特别强调了马克思、恩格斯唯物主义哲学的“辩证”属性和“历史”属性，并以此作为与以往唯物主义哲学的区别，旨在说明马克思主义哲学是辩证唯物主义和历史唯物主义的高度统一，与“半截子”的旧唯物主义思想有着本质区别。因此，选项 A、B、C 正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"马克思主义认为，规律分为自然规律和社会历史规律，二者都是客观的，各自具有其自身的特点。故不选。"}}},{"id":"advanced-mayuan-test2-20","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试二","chapterKey":"综合测试二","n":20,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试二 第 20 题"},"stem":"中国古代朴素辩证法思想认为，事物转化要经历一个过程，如“合抱之木，生于毫末；九层之台，起于累土；千里之行，始于足下”，所以要“图难于其易，为大于其细”。这在哲学上体现了","choices":[{"id":"A","text":"量变是质变的必要准备"},{"id":"B","text":"事物是由一种质态向另一种质态的飞跃"},{"id":"C","text":"事物发展渐进过程的连续性"},{"id":"D","text":"在总的量变过程中有阶段性和局部性的部分质变"}],"answer":["A","C"],"analysis":{"point":"本题考查量变质变规律。题干出自老子的《道德经》，意思是合抱的大树，生长于细小的幼苗；九层的高台，筑起于每一堆泥土；千里的远行，是从脚下第一步开始走出来的，强调量的积累的重要性。所谓量变就是事物数量的增减和组成要素排列次序的变动，是保持事物质的相对稳定性的不显著变化，体现了事物发展渐进过程的连续性。因此，选项A、C正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"质变是事物性质的根本变化，是事物由一种质态向另一种质态的飞跃，体现了事物发展渐进过程和连续性的中断。题干强调的是量变，故不选。","C":"（正确选项，分析见“解题思路”）","D":"表述正确。一方面，量变和质变是相互渗透的，在总的量变过程中有阶段性和局部性的部分质变；另一方面，在质变过程中也有旧质在量上的收缩和新质在量上的扩张。但没有特别强调量变的重要性，不符合题意，故不选。"}}},{"id":"advanced-mayuan-test2-21","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试二","chapterKey":"综合测试二","n":21,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试二 第 21 题"},"stem":"“概念的辩证法本身就变成只是现实世界的辩证运动的自觉的反映，从而黑格尔的辩证法就被倒转过来了。”这句话表明","choices":[{"id":"A","text":"客观辩证法采取外部必然性的形式"},{"id":"B","text":"主观辩证法采取逻辑的形式"},{"id":"C","text":"客观辩证法离开人的意识而存在"},{"id":"D","text":"主观辩证法以概念为基础"}],"answer":["A","B","C","D"],"analysis":{"point":"本题考查客观辩证法与主观辩证法。客观辩证法采取外部必然性的形式，离开人的意识、思维而独立存在，不以人的意志为转移；主观辩证法则采取观念的、逻辑的形式，是同人类思维的自觉活动相联系的，是以概念为基础的辩证思维规律。因此，选项A、B、C、D正确。\\n无干扰选项。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-mayuan-test2-22","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试二","chapterKey":"综合测试二","n":22,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试二 第 22 题"},"stem":"感知热、冷和触觉的能力对于生存至关重要，这是人类与周围世界互动的基础。比如，眼睛可以检测光线，声波可以影响内耳，不同的化合物可以与鼻子和嘴巴中的感受器相互作用，产生嗅觉和味觉。人们还通过其他方式来感知周围的世界，在炎热的夏天赤脚走过草坪，人们可以感受到太阳的热力、风对皮肤的摩擦等。对温度、触觉和运动的感知至关重要，是人们得以适应不断变化的环境的基础。人们对于“感觉”和“触觉”的研究表明","choices":[{"id":"A","text":"感性认识是用具体的、生动的形象直接反映事物本质的认识"},{"id":"B","text":"事物因人的感觉而存在"},{"id":"C","text":"人的认识是主体与客体相互作用的过程和结果"},{"id":"D","text":"能动反映的创造性对于人的认识的形成、发展和运用尤为重要"}],"answer":["C","D"],"analysis":{"point":"本题考查认识的本质及过程。辩证唯物主义认识论认为，认识的本质是主体在实践基础上对客体的能动反映。这种能动反映不但具有反映客体内容的反映性特征，而且具有实践所要求的主体能动的、创造性的特征。总之，能动反映的创造性对于人的认识的形成、发展和运用尤为重要。因此，选项C、D正确。","options":{"A":"感性认识是用具体的、生动的形象直接反映外部世界，以事物的现象即外部联系为内容，还没有深入到对事物本质的认识，必须进一步上升到理性认识。故不选。","B":"属于唯心主义的观点，故不选。","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-mayuan-test2-23","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试二","chapterKey":"综合测试二","n":23,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试二 第 23 题"},"stem":"古希腊哲学家恩培多克勒提出“流溢说”，认为认识是从物体流溢出来的物质经过感官通道引起的。德谟克利特则提出“影像说”，认为感觉和思想是物体的影像到达感官所引起的。近代唯物主义者培根认为“知识就是存在的映象”。他们的错误在于","choices":[{"id":"A","text":"认为人的认识是对客观事物消极、被动的反映"},{"id":"B","text":"认为人的认识是一个由不知到知、由浅入深的过程"},{"id":"C","text":"没有以实践的观点阐述人的认识活动及其规律"},{"id":"D","text":"认为人对事物的反映不是直观的反映而是创造性的反映"}],"answer":["A","C"],"analysis":{"point":"本题考查旧唯物主义认识论。旧唯物主义认识论即形而上学唯物主义的认识论，把人的认识看成是对外界对象消极、被动的反映；把人对客观事物能动的、创造性的反映等同于动物的无意识的、消极的、直观的反映。选项A正确。辩证唯物主义认识论把实践的观点引入认识论，以实践的观点阐述人的认识活动及其规律，科学地规定了认识的主体和客体及其相互关系，对认识的发生和发展、认识的目的和作用、认识正确与否的检验标准等一系列重要认识论问题，作出了同旧唯物主义认识论完全不同的科学解释。选项C正确。因此，选项A、C正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"是辩证唯物主义的观点，辩证唯物主义把辩证法应用于反映论，把认识看作一个由不知到知、由浅入深的充满矛盾的能动的过程。与题干无关，故不选。","C":"（正确选项，分析见“解题思路”）","D":"是辩证唯物主义的观点，辩证唯物主义认为认识是主体在实践基础上对客体的能动反映，并非直观的反映，而是一种具有创造性的反映。与题干无关，故不选。"}}},{"id":"advanced-mayuan-test2-24","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试二","chapterKey":"综合测试二","n":24,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试二 第 24 题"},"stem":"正如达尔文发现了有机界的规律一样，马克思发现了人类社会发展的客观规律，科学地解决了社会存在与社会意识的关系问题，创立了唯物史观。与唯心史观相比，唯物史观的进步性在于","choices":[{"id":"A","text":"正确地解释了人类社会及其赖以生存的自然界运转的客观规律"},{"id":"B","text":"认为人类社会的发展是由精神力量和物质力量共同决定的"},{"id":"C","text":"深入探究了人类社会发展的物质动因和经济根源"},{"id":"D","text":"提出人类历史是由人民群众创造的"}],"answer":["C","D"],"analysis":{"point":"本题考查唯物史观和唯心史观。唯心史观的主要缺陷：其一，旧的社会历史理论在说明社会历史时，只停留在历史活动的表面，它至多考察人的活动的思想动机，而没有进一步考究思想动机背后的物质动因和经济根源；其二，旧的社会历史理论否认人民群众在社会历史发展中的决定作用，把社会历史看作少数历史人物活动的结果。而唯物史观弥补了这两方面的缺陷，这也正是唯物史观的进步性所在。因此，选项C、D正确。","options":{"A":"说法错误，唯物史观解释的是社会发展的客观规律，并不涉及自然界运转的客观规律，故不选。","B":"唯物史观认为人类社会的发展是由物质力量决定的，同时还受精神力量的影响，“共同决定”的说法错误，故不选。","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-mayuan-test2-25","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试二","chapterKey":"综合测试二","n":25,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试二 第 25 题"},"stem":"列宁指出：“世界历史发展的一般规律，不仅丝毫不排斥个别发展阶段在发展的形式或顺序上表现出特殊性，反而是以此为前提的。”这说明社会发展不仅具有统一性，还具有多样性的特点。下列能体现社会形态更替具有多样性特征的有","choices":[{"id":"A","text":"不同的民族可以超越一种或几种社会形态而跳跃式地向前发展"},{"id":"B","text":"某些民族实现跳跃式发展的方向可以和人类社会发展的总体方向不一致"},{"id":"C","text":"对于不同的民族而言，同样的社会形态可能会有不同的表现形式"},{"id":"D","text":"当社会形态更替实现跳跃式发展时，说明此时社会的发展已经突破了生产力水平的制约"}],"answer":["A","C"],"analysis":{"point":"本题考查社会形态更替的多样性。题干中指出“个别发展阶段在发展的形式或顺序上表现出特殊性”指的就是不同的民族可以超越一种或几种社会形态而跳跃式地向前发展。同样是社会主义，中国和朝鲜的表现形式不一样；同样是资本主义，美国和日本的表现形式也不一样。因此，选项A、C正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"说法错误，虽然某些民族可以实现跳跃式发展，超越一种或几种社会形态，但是和历史大方向还是保持一致的。故不选。","C":"（正确选项，分析见“解题思路”）","D":"说法错误，无论人类社会如何发展，都无法突破生产力水平的制约，这就是社会规律的客观性所在。故不选。"}}},{"id":"advanced-mayuan-test2-26","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试二","chapterKey":"综合测试二","n":26,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试二 第 26 题"},"stem":"生产力与生产关系的矛盾、经济基础与上层建筑的矛盾被称为人类社会发展的两对基本矛盾。社会基本矛盾是社会发展的根本动力，它在社会发展中的作用主要表现在","choices":[{"id":"A","text":"社会基本矛盾运动中最基本的动力因素——生产力，是人类社会发展和进步的最终决定力量"},{"id":"B","text":"社会基本矛盾特别是生产力与生产关系的矛盾，是“一切历史冲突的根源”，决定着社会中其他矛盾的存在和发展"},{"id":"C","text":"社会基本矛盾都可以通过自我完善和自我发展的方式加以解决"},{"id":"D","text":"社会基本矛盾的不同表现形式和解决方式从根本上影响和促进社会形态的变化和发展"}],"answer":["A","B","D"],"analysis":{"point":"本题考查社会基本矛盾。社会基本矛盾是社会历史发展的根本动力，它决定着社会其他矛盾的存在和发展，它的解决方式影响和促进整个社会形态的变化和发展。在这两对社会基本矛盾中，生产力和生产关系的矛盾又是更基本的，其中生产力是社会历史发展的最基本的动力因素和最终决定力量。因此，选项A、B、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"说法错误，当社会基本矛盾的性质属于“非对抗性矛盾”的时候，可以通过社会的自我完善和发展加以解决，然而，当社会基本矛盾属于“对抗性矛盾”的时候，则必须通过社会革命等对抗形式加以解决。故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-mayuan-test2-27","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试二","chapterKey":"综合测试二","n":27,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试二 第 27 题"},"stem":"马克思认为，“商品形式的奥秘不过在于：商品形式在人们面前把人们本身劳动的社会性质反映成劳动产品本身的物的性质，反映成这些物的天然的社会属性，从而把生产者同总劳动的社会关系反映成存在于生产者之外的物与物之间的社会关系。由于这种转换，劳动产品成了商品，成了可感觉而又超感觉的物或社会的物”。这表明","choices":[{"id":"A","text":"商品本质上体现的是人与人之间的关系"},{"id":"B","text":"商品把人与人之间的关系物化了"},{"id":"C","text":"商品的“天然的社会属性”就在于人们本身劳动的社会性质"},{"id":"D","text":"商品之所以成为商品是因为它是劳动产品"}],"answer":["A","B","C"],"analysis":{"point":"本题考查商品的相关内容。劳动产品在交换中取得了商品的形式，商品交换的过程不但是人们交换使用价值的过程，也是人们相互比较自身劳动（商品价值）的过程。这一过程表面上是物物交换（使用价值的交换），实际上则反映了商品生产者之间的社会关系。因此，可以说商品把人与人之间的关系物化了，商品本质上体现的是人与人之间的关系，而商品的“天然的社会属性”就在于人们本身劳动的社会性质。因此，选项A、B、C正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"说法错误，劳动产品天然并非商品，只有用于交换的劳动产品才是商品，故不选。"}}},{"id":"advanced-mayuan-test2-28","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试二","chapterKey":"综合测试二","n":28,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试二 第 28 题"},"stem":"超额剩余价值是个别资本家提高劳动生产率，使其产品的个别价值低于社会价值而得到的更多的剩余价值。下列关于超额剩余价值的表述，正确的有","choices":[{"id":"A","text":"超额剩余价值的源泉是雇佣工人的剩余劳动"},{"id":"B","text":"超额剩余价值是个别资本家提高劳动生产率的结果"},{"id":"C","text":"超额剩余价值是全社会劳动生产率提高的结果"},{"id":"D","text":"超额剩余价值是所有资本家都能获得的"}],"answer":["A","B"],"analysis":{"point":"本题考查超额剩余价值。超额剩余价值是个别资本家提高劳动生产率，使其产品的个别价值低于社会价值而得到的更多的剩余价值，其源泉是雇佣工人的剩余劳动。在资本主义社会，各个资本家企业采用先进生产技术来提高劳动生产率的直接动机是追逐超额剩余价值。因此，选项A、B正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"表述错误，追逐超额剩余价值是每个资本家改进生产技术的直接动机，为了追逐超额剩余价值，每个资本家都设法提高劳动生产率，最后的结果是全社会的劳动生产率提高，使得整个资本家阶级普遍获得相对剩余价值。故不选。","D":"超额剩余价值只是暂时的，当各个资本家都提高各自的技术时，普遍获得的是相对剩余价值，故不选。"}}},{"id":"advanced-mayuan-test2-29","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试二","chapterKey":"综合测试二","n":29,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试二 第 29 题"},"stem":"资本主义政治制度本质上是资产阶级进行政治统治和社会管理的手段和方式，不可避免地有其历史的和阶级的局限性。下列说法能够体现这种局限性的有","choices":[{"id":"A","text":"资本主义的民主是金钱操纵下的民主，实际是资产阶级精英统治下的民主"},{"id":"B","text":"资本主义法律名义上的平等掩盖着事实上的不平等"},{"id":"C","text":"资本主义政治制度扩大了民众的政治参与权利"},{"id":"D","text":"资本主义政治制度本质上是为资产阶级专政服务的"}],"answer":["A","B","D"],"analysis":{"point":"本题考查资本主义政治制度的局限性。就资本主义的政体而言，资本主义的民主是金钱操纵下的民主，实际是资产阶级精英统治下的民主；法律名义上的平等掩盖着事实上的不平等；资本主义国家的政党制仍然是资产阶级选择自己的国家管理者、实现其内部利益平衡的政治机制，是一种维护资产阶级政治统治的制度。资本主义政治制度本质上是资产阶级进行政治统治和社会管理的方式和手段，是为资产阶级专政服务的，是资产阶级对民众进行政治统治的手段。因此，选项A、B、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"说法错误，从形式上看，资本主义政治制度好像扩大了民众的政治参与权利，但是实质上并没有。如果考生不能从这个角度分析出该选项错误，至少应该判断出“扩大政治参与权利”并非题干问的“局限性”，同样可以排除。故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-mayuan-test2-30","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试二","chapterKey":"综合测试二","n":30,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试二 第 30 题"},"stem":"与第二次世界大战之前的资本主义相比，当代资本主义生产关系中的社会阶层、阶级结构发生了许多新的变化，主要表现在","choices":[{"id":"A","text":"高级职业经理成为资本主义社会大公司经营活动的实际控制者"},{"id":"B","text":"资本家由从前的直接生产经营者变成了以剪息票为生的食利者"},{"id":"C","text":"职工持股和参与决策使得劳动者成为资本家集团的重要力量"},{"id":"D","text":"知识型和服务型劳动者数量随科技革命不断深入而持续地增加"}],"answer":["A","B","D"],"analysis":{"point":"本题考查第二次世界大战后资本主义发生的新变化。在当代资本主义生产关系中，社会阶层、阶级结构发生了新的变化：一是资本家的地位和作用发生了很大的变化。资本所有权和经营权发生分离，拥有所有权的资本家一般不再直接经营和管理企业，而是靠拥有的企业股票等有价证券的利息收入为生，最终成为以剪息票为生的食利者。二是高级职业经理成为大公司经营活动的实际控制者。三是知识型和服务型劳动者的数量不断增加，劳动方式发生了新变化。因此，选项A、B、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"“职工持股和参与决策”确实是第二次世界大战后资本主义发生的新变化，但这是劳资关系的变化，不是社会阶层、阶级结构的变化，并且这并不意味着工人就变成了资本家，工人并不会成为资本家集团的重要力量，二者有本质区别，故排除。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-mayuan-test3-1","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试三","chapterKey":"综合测试三","n":1,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试三 第 1 题"},"stem":"《诗经》有云：“君子如届，俾民心阕。君子如夷，恶怒是违。”《尚书》亦言：“民惟邦本，本固邦宁。”新时代以来，习近平总书记创造性地提出并强调“民心是最大的政治”。“民心是最大的政治”体现了","choices":[{"id":"A","text":"马克思主义创新发展的基本路径"},{"id":"B","text":"马克思主义的内在品质"},{"id":"C","text":"马克思主义首要的和基本的观点"},{"id":"D","text":"马克思主义哲学的根本价值指向"}],"answer":["D"],"analysis":{"point":"本题考查马克思主义的基本特征。人民性是马克思主义的本质属性，人民至上是马克思主义的政治立场。“民心是最大的政治”体现了马克思主义哲学的根本价值指向。因此，选项D正确。","options":{"A":"本土化和时代化是马克思主义创新发展的基本路径，故不选。","B":"革命性是马克思主义的内在品质，故不选。","C":"实践观点是马克思主义首要的和基本的观点，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-mayuan-test3-2","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试三","chapterKey":"综合测试三","n":2,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试三 第 2 题"},"stem":"在二维平面上模拟三维空间效果一直是人类视觉艺术的焦点问题，3D 街头地画可看作这一艺术逻辑在当代的重要发展和延伸。所谓 3D 街头地画，顾名思义就是将画作展示于地面以求获得立体的艺术效果。它以室外地面为媒介，利用平面透视的原理，制造出视觉上的虚拟立体效果，令参观者有一种身临其境的感觉。景物立体、细腻、逼真，往往能达到以假乱真的艺术效果。虽然画是二维的，只是三维现实空间中实际物体的一部分，但人脑能通过这个部分将其想象成完整情形。这表明","choices":[{"id":"A","text":"空间具有三维性"},{"id":"B","text":"意识是对客观对象的能动反映"},{"id":"C","text":"意识是人脑产生的特殊物质"},{"id":"D","text":"意识无法如实地反映物质"}],"answer":["B"],"analysis":{"point":"本题考查意识的本质。题干中关键句“人脑能通过这个部分将其想象成完整情形”的意思是，意识作为人脑的机能和属性，具有主观能动性。因此，选项B正确。","options":{"A":"表述正确，但是题干并没有强调空间的特性，与题意不符，故不选。","B":"（正确选项，分析见“解题思路”）","C":"表述错误，意识是人脑的特有机能，并不属于“物质”范畴，故不选。","D":"表述错误，马克思主义认为意识可以正确地反映物质，故不选。"}}},{"id":"advanced-mayuan-test3-3","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试三","chapterKey":"综合测试三","n":3,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试三 第 3 题"},"stem":"某地区进入供暖季后常常出现雾霾，而一旦出现大风天气或等到春暖花开后，雾霾就会散去或减少。从该地区较长时间的数据变化看，经过人们努力治霾，污染物排放总量在持续走低；但在某些时段，环境空气质量污染指数会迅速攀升，甚至“爆表”。这种看似“矛盾”的现象凸显了大气污染防治的一个特点：天帮忙很重要，但人努力才是根本。“人努力”与“天帮忙”之间的关系对我们正确处理主观能动性和客观规律性之间辩证关系的启示是","choices":[{"id":"A","text":"尊重事物的客观规律是正确发挥主观能动性的前提"},{"id":"B","text":"人类有意识的思想活动是掌握客观规律的根本前提"},{"id":"C","text":"认识活动是客观规律性与主观能动性相统一的基础"},{"id":"D","text":"尚未认识的外在自然规律对人的实践活动起着至关重要的作用"}],"answer":["A"],"analysis":{"point":"本题考查客观规律性与主观能动性的辩证关系。本题题干指出，“天帮忙很重要，但人努力才是根本”。“天帮忙”隐喻客观规律性，“人努力”对应主观能动性。结合考点：第一，必须尊重客观规律，发挥人的主观能动性必须以承认规律的客观性为前提。第二，在尊重客观规律的基础上，要充分发挥主观能动性，实践是我们解决问题的根本方法。作答时要遵循两个原则：一是选项与题意相符；二是选项本身说法正确。因此，选项A正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"在认识论中掌握规律的前提是实践，而“思想活动”不能作为前提。故不选。","C":"客观规律性与主观能动性相统一的基础是实践，而不是“认识”。","D":"规律对于人的实践活动是很重要的，不过这里的规律既包括自然规律，也包括社会规律；既包括已经认识的规律，也包括尚未认识的规律。选项D过分夸大了尚未认识的自然规律的作用。"}}},{"id":"advanced-mayuan-test3-4","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试三","chapterKey":"综合测试三","n":4,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试三 第 4 题"},"stem":"有人认为，既然人的意识是对客观外部世界的反映，那么人脑里的“鬼”“神”意识就是对外在世界上鬼、神真实存在的反映。这种观念的错误在于","choices":[{"id":"A","text":"夸大了意识的能动作用"},{"id":"B","text":"把意识看成物质的产物"},{"id":"C","text":"认为意识是对存在的直观反映"},{"id":"D","text":"混淆了人类意识自然演化的阶段"}],"answer":["C"],"analysis":{"point":"本题考查意识的本质和能动反映论。鬼、神在客观世界中原本就是不存在的，人的头脑中之所以会有鬼、神的观念，是因为对外部世界产生了歪曲的反映。本题题干中“‘鬼’‘神’意识就是对外在世界上鬼、神真实存在的反映”，是一种直观反映论的观点，即认为头脑中的观念只能对外部世界进行简单机械的直观反映，而不能进行加工改造。因此，选项C正确。","options":{"A":"题干中的观点并没有夸大意识的能动作用，反而是缩小了意识的能动作用，故不选。","B":"“把意识看成物质的产物”观点本身正确，但本题要选的是观点的错误之处。与题意不符，故不选。","C":"（正确选项，分析见“解题思路”）","D":"意识的形成和发展经历了三个阶段，即由一切物质所具有的反应特性到低等生物的刺激感应性，再到高等动物的感觉和心理，最终发展为人类的意识。与题意不符，故不选。"}}},{"id":"advanced-mayuan-test3-5","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试三","chapterKey":"综合测试三","n":5,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试三 第 5 题"},"stem":"唐代诗人王勃在《滕王阁序》中写道“闲云潭影日悠悠，物换星移几度秋”，这形象地说明了时间和空间是相互依存的。时空是","choices":[{"id":"A","text":"运动着的物质的特殊状态"},{"id":"B","text":"运动着的物质的普遍状态"},{"id":"C","text":"运动着的物质的基本存在形式"},{"id":"D","text":"运动着的物质的观念形式"}],"answer":["C"],"analysis":{"point":"本题考查时空观。时空是物质运动的时空，物质运动是时空中的物质运动，时间和空间是运动着的物质的基本存在形式。题干中诗句的翻译为：自在的白云，悬映在深深的潭水里，影影绰绰，迎朝露，送秋辉。季节景物在不知不觉中转换，日月星辰在无声无息中移动。作者生动形象地描述出“时空”的特点。因此，选项C正确。","options":{"A":"静止是物质运动的特殊状态，故不选。","B":"运动是物质存在的基本形式（方式）和普遍状态，故不选。","C":"（正确选项，分析见“解题思路”）","D":"表述错误，时空是客观存在的，不是一种观念形式，故不选。"}}},{"id":"advanced-mayuan-test3-6","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试三","chapterKey":"综合测试三","n":6,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试三 第 6 题"},"stem":"“芳林新叶催陈叶，流水前波让后波”体现了新旧事物之间的辩证关系。区分新旧事物是理解辩证法的关键，二者的区别在于","choices":[{"id":"A","text":"出现时间的先后"},{"id":"B","text":"形式的新旧"},{"id":"C","text":"力量大小的对比"},{"id":"D","text":"是否符合客观规律和发展的必然趋势"}],"answer":["D"],"analysis":{"point":"本题考查新旧事物的区别。唯物辩证法认为，新事物是指符合客观发展规律、具有强大生命力和远大发展前途的东西；旧事物是指那些同客观规律背道而驰、丧失历史必然性、日趋灭亡的东西。区分新旧事物的根本标准，是看它是否符合客观规律，有没有强大的生命力和远大的发展前途。因此，选项D正确。","options":{"A":"只能说“新事物往往产生于旧事物之后”，但这不是绝对的，不能把产生时间的先后作为判断新旧事物的标准。故不选。","B":"一般情况下，事物的内容和形式是一致的，但也有相对脱离的情况，在现实生活中，我们经常看到旧事物为了证明自己的“新”而采取新的形式，所以，不能以形式的新旧作为判断新旧事物的标准。故不选。","C":"新事物在开始时力量一般都是比较弱小的，处于被支配的地位，而与其对立的旧事物则还保持着较为强大的力量，处于支配的地位。所以，不能以力量的大小作为判断新旧事物的标准。故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-mayuan-test3-7","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试三","chapterKey":"综合测试三","n":7,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试三 第 7 题"},"stem":"如果把一只青蛙直接放进热水锅里，它会迅速跳出锅外；如果把一只青蛙放进冷水锅里，慢慢地加温，青蛙并不会立即跳出锅外，水温逐渐提高的最终结局是青蛙被煮死了，这是因为等水温高到青蛙无法忍受时，它已经来不及或者说没有能力跳出锅外了。这说明","choices":[{"id":"A","text":"否定因素是事物发展的动力"},{"id":"B","text":"事物发展是量变与质变的统一"},{"id":"C","text":"偶然决定事物的发展方向"},{"id":"D","text":"联系是无条件的、主观的"}],"answer":["B"],"analysis":{"point":"本题考查量变质变规律，属于分析理解题。由于任何事物都是质和量的统一体，因而事物的变化表现为量变和质变两种运动状态。量变是事物数量的增减和组成要素排列次序的变动，是保持事物的质的相对稳定的不显著的变化，体现了事物渐进过程的连续性。质变是事物性质的根本变化，是事物由一种质态向另一种质态的飞跃，体现了事物渐进过程和连续性的中断。区分量变和质变的根本标志是事物的变化是否超出度，在度的范围内的变化是量变，超出度的范围的变化是质变。因此，选项B正确。","options":{"A":"与题意不符且表述错误，矛盾推动事物的发展，说明事物发展的根本原因不在于事物的外部，而在于事物内部的矛盾性，并不是否定因素。故不选。","B":"（正确选项，分析见“解题思路”）","C":"与题意不符且表述错误，必然在事物发展中居于支配地位，决定着事物发展的方向；偶然居于从属地位，对发展的必然过程起促进或延缓作用，使发展的确定趋势带有一定的特点和偏差。故不选。","D":"与题意不符且表述错误，事物的联系是事物本身所固有的，具有客观性，不是主观臆造的。世界的普遍联系是通过“中介”来实现的。所谓中介，就是事物相互联系的媒介、环节或桥梁。因此，联系是有条件的。故不选。"}}},{"id":"advanced-mayuan-test3-8","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试三","chapterKey":"综合测试三","n":8,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试三 第 8 题"},"stem":"列宁说：“没有‘人的感情’，就从来没有也不可能有人对于真理的追求。”这句话肯定了","choices":[{"id":"A","text":"认识过程中理性因素的作用"},{"id":"B","text":"认识过程中非理性因素的作用"},{"id":"C","text":"认识过程中直接经验的作用"},{"id":"D","text":"认识过程中间接经验的作用"}],"answer":["B"],"analysis":{"point":"本题考查非理性因素在认识活动中的作用。情感、意志、欲望和需要等非理性因素，对人的认识活动的发动与停止、对主体认识能力的发挥与抑制起着重要的控制和调节作用。列宁的话肯定了认识过程中非理性因素的作用。因此，选项B正确。","options":{"A":"理性因素是指人的理性直观、理性思维等能力，而题干主要强调“感情”这一非理性因素，与题干无关，故不选。","B":"（正确选项，分析见“解题思路”）","C":"直接经验就是通过亲身实践得到的经验，题干并未涉及，故不选。","D":"间接经验是指从他人那里得来的知识，特别是前人通过总结实践经验而得出的科学理论知识，题干并未涉及，故不选。"}}},{"id":"advanced-mayuan-test3-9","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试三","chapterKey":"综合测试三","n":9,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试三 第 9 题"},"stem":"德米特里·门捷列夫是19世纪俄国化学家。他发现了元素周期律，并就此发表了世界上第一份元素周期表。他曾说：“一个人要发现卓有成效的真理，需要千百万个人在失败的探索和悲惨的毛病中毁掉自己的生命。”这句话说明了","choices":[{"id":"A","text":"真理是主观与客观相符合的哲学范畴，与谬误相对立"},{"id":"B","text":"真理和谬误是相互等同、相互转化的"},{"id":"C","text":"在批判谬误中发展真理，是谬误向真理转化的一种形式"},{"id":"D","text":"只要在谬误中总结教训，就能达到对真理的认识"}],"answer":["C"],"analysis":{"point":"本题考查真理和谬误的关系。真理同谬误是相比较而存在、相斗争而发展的，真理和谬误在一定条件下可以相互转化。谬误转化为真理有三种情况：①超出一定的条件和范围，真理就会变成谬误。那么，只要原来的条件和范围得到恢复，谬误回到原来的条件和范围之内，它又会变成真理。②人们在社会实践中，有成功也有失败，只要善于在失败中分析犯错误的原因，总结失败的教训，就可能达到对于事物的正确认识，使错误转化为正确，使谬误转化为真理。③在批判谬误中发展真理。题干中“一个人要发现卓有成效的真理，需要千百万个人在失败的探索和悲惨的毛病中毁掉自己的生命”，说明在批判谬误中发展真理，是谬误向真理转化的一种形式。因此，选项C正确。","options":{"A":"本题题干侧重于表达真理和谬误之间的转化问题，而不是强调二者之间的对立，故不选。","B":"说法错误，在一定范围内，真理和谬误有原则的界限，不能混淆。真理和谬误在一定条件下可以相互转化，但并不是相互等同的，故不选。","C":"（正确选项，分析见“解题思路”）","D":"错在“只要”二字，谬误在一定条件下可以转化为真理，但并不是说只要总结教训就能达到对真理的认识，还要依赖于条件和范围等因素的转换，故不选。"}}},{"id":"advanced-mayuan-test3-10","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试三","chapterKey":"综合测试三","n":10,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试三 第 10 题"},"stem":"中国工程院院士袁隆平曾结合自己的科研经历，语重心长地对年轻人说：“书本知识非常重要，电脑技术也很重要，但是书本电脑里面种不出水稻来，只有在田里才能种出水稻来。”这表明","choices":[{"id":"A","text":"实践是人类认识的基础和来源"},{"id":"B","text":"实践水平的提高有赖于认识水平的提高"},{"id":"C","text":"理论对实践的指导作用没有正确与错误之分"},{"id":"D","text":"由实践到认识的第一次飞跃比认识到实践的第二次飞跃更重要"}],"answer":["A"],"analysis":{"point":"本题是一道“认识论”的多考点综合性考题，主要考查“认识（理论）与实践具体的、历史的统一以及实践对认识的决定作用”，即实践是认识的基础和来源。袁隆平的话表明，只有通过实践才能获得认识，即实践是认识的来源。因此，选项A正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"实践水平受认识水平的影响，但是“有赖于”的说法过于绝对。故不选。","C":"理论包含科学的理论与非科学的理论，因此指导作用也有正确与错误之分。故不选。","D":"表述错误，从认识到实践的第二次飞跃比从实践到认识的第一次飞跃更重要。故不选。"}}},{"id":"advanced-mayuan-test3-11","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试三","chapterKey":"综合测试三","n":11,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试三 第 11 题"},"stem":"马克思指出，判断一个变革时代不能以该时代的意识为依据，相反，这个意识必须从物质生活的矛盾中去解释。这里的“物质生活的矛盾”从根本上说是","choices":[{"id":"A","text":"社会生产力与生产关系的现存冲突"},{"id":"B","text":"经济基础与上层建筑的现存冲突"},{"id":"C","text":"人类社会与自然界的现存冲突"},{"id":"D","text":"社会存在与社会意识的现存冲突"}],"answer":["A"],"analysis":{"point":"本题考查社会基本矛盾。本题的关键词是“物质生活的矛盾”，所以正确选项中提及的概念，必须都属于“社会物质生活”。从这一点考虑，正确答案应该在A、C选项中产生。在诸多矛盾中，生产力与生产关系的矛盾是最根本的矛盾，它决定着其他矛盾的产生和发展。因此，选项A正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"本题考查“物质生活的矛盾”，而“上层建筑”这个概念不完全属于物质范畴，故不选。","C":"“人类社会”和“自然界”都属于物质范畴，确实也是一对矛盾体，但与选项A相比较，它不是最根本的矛盾，而是选项A的派生矛盾，故不选。","D":"本题考查“物质生活的矛盾”，“社会意识”这个概念不属于物质范畴，故不选。"}}},{"id":"advanced-mayuan-test3-12","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试三","chapterKey":"综合测试三","n":12,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试三 第 12 题"},"stem":"流通手段是货币的重要职能之一，作为流通手段的货币必须是","choices":[{"id":"A","text":"足值的货币"},{"id":"B","text":"现实中的货币"},{"id":"C","text":"观念上的货币"},{"id":"D","text":"纸币"}],"answer":["B"],"analysis":{"point":"本题考查货币的职能。货币在执行流通手段职能时，必须是现实的货币。消费者只有付出真金白银（现实的货币），才能将想要的货物买走。因此，选项B正确。","options":{"A":"货币在执行流通手段职能的时候，仅仅是一个媒介，因此可以不足值，故不选。","B":"（正确选项，分析见“解题思路”）","C":"货币在执行流通手段职能时，必须是现实的货币，不能是观念上的货币，要真实地付出金钱，才能将商品买走，故不选。","D":"执行流通手段职能的货币可以是纸币，但并非题干要求的“必须是”，故不选。"}}},{"id":"advanced-mayuan-test3-13","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试三","chapterKey":"综合测试三","n":13,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试三 第 13 题"},"stem":"某企业新投资了一家工厂，花费100万元购买土地和厂房之后，又花费了100万元购买机器、原材料。经过分析，该企业的资本有机构成为4：1。在经过一轮的生产之后，企业资本金上涨到400万元。该工厂的剩余价值率为","choices":[{"id":"A","text":"50%"},{"id":"B","text":"100%"},{"id":"C","text":"200%"},{"id":"D","text":"300%"}],"answer":["D"],"analysis":{"point":"本题考查剩余价值率，属于理解计算题。根据题干可知：$c=100+100=200$（万元）；$c:v=4:1$，可得$v=50$（万元）；$m=400-200-50=150$（万元）。综上所述，$m'=m/v=150/50=300\\\\%$。因此，选项D正确。","options":{"A":"与计算结果不符，故不选。","B":"与计算结果不符，故不选。","C":"与计算结果不符，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-mayuan-test3-14","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试三","chapterKey":"综合测试三","n":14,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试三 第 14 题"},"stem":"在资本主义的商品生产过程中，土地、设备和原材料等生产资料的价值借助生产者的","choices":[{"id":"A","text":"具体劳动而实现了价值增殖"},{"id":"B","text":"具体劳动转移到新产品中"},{"id":"C","text":"抽象劳动而实现了价值增殖"},{"id":"D","text":"抽象劳动转移到新产品中"}],"answer":["B"],"analysis":{"point":"本题考查劳动的二重性。在资本主义的生产过程中，土地、设备和原材料等生产资料原有的价值借助工人的具体劳动转移到新的劳动产品中。因此，选项B正确。","options":{"A":"错误有二：第一，土地、设备、原材料等生产资料并不能发生价值增殖，它们只是实现了价值转移；第二，具体劳动生产商品的使用价值，并不生产价值，就更谈不上实现“价值增殖”。故不选。","B":"（正确选项，分析见“解题思路”）","C":"错误有二：第一，土地、设备、原材料等生产资料并不能发生价值增殖，它们只是实现了价值转移；第二，具体劳动生产商品的使用价值，并不生产价值，就更谈不上实现“价值增殖”。故不选。","D":"土地等生产资料的价值“转移到新产品中”的说法正确，但这并不是借助抽象劳动，而是借助具体劳动实现的。故不选。"}}},{"id":"advanced-mayuan-test3-15","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试三","chapterKey":"综合测试三","n":15,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试三 第 15 题"},"stem":"下列关于剩余价值和利润的不同之处，表述正确的是","choices":[{"id":"A","text":"剩余价值是由工人的剩余劳动创造的，而利润不是"},{"id":"B","text":"利润被看作全部预付资本的产物，而剩余价值不是"},{"id":"C","text":"剩余价值和利润在量上是相等的"},{"id":"D","text":"剩余价值和利润归根结底都是由工人的劳动创造出来的"}],"answer":["B"],"analysis":{"point":"本题考查剩余价值和利润的区别。剩余价值和利润在质上是相同的，剩余价值是利润的本质，利润是剩余价值的表现形式，并且二者在量上也是相等的。剩余价值和利润所不同的是，剩余价值是针对可变资本而言的，利润是针对全部预付资本而言的。因此，选项B正确。","options":{"A":"说法错误，剩余价值是由工人的剩余劳动创造的，利润也是工人的剩余劳动创造的，故不选。","B":"（正确选项，分析见“解题思路”）","C":"是二者的相同之处，故不选。","D":"是二者的相同之处，故不选。"}}},{"id":"advanced-mayuan-test3-16","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试三","chapterKey":"综合测试三","n":16,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试三 第 16 题"},"stem":"列宁指出：“物质是标志客观实在的哲学范畴，这种客观实在是人通过感觉感知的，它不依赖于我们的感觉而存在，为我们的感觉所复写、摄影、反映。”这句话表明","choices":[{"id":"A","text":"物质就是各种实物的总和"},{"id":"B","text":"不能把物质的具体形态同物质混为一谈"},{"id":"C","text":"物质都是人们感官可以直接感觉的"},{"id":"D","text":"辩证唯物主义物质范畴体现了自然观与历史观的统一"}],"answer":["B","D"],"analysis":{"point":"本题考查物质观。辩证唯物主义从无限多样的物质现象中抽象出共同的特性，从哲学上作了最高概括，指出客观实在性是物质的本质规定；哲学上的物质范畴与物质的具体形态是共性与个性的关系，不能把物质的具体形态同物质本身混为一谈。马克思主义把实践纳入对物质的理解，既把物质范畴拓展到社会历史领域，又深化了对自然物质的理解，实现了唯物主义自然观与唯物主义历史观的统一。因此，选项B、D正确。","options":{"A":"不能将物质简单地理解为各种实物的总和，因为从广度上来看，物质还包括很多非实物性的东西，如“人的阶级性”等。故不选。","B":"（正确选项，分析见“解题思路”）","C":"物质是客观的，是可以被人们所认知的，但并不都是可以被“直接感觉”的，有些可以通过直接的感官认知，有些需要通过理性的思维才能把握。故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-mayuan-test3-17","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试三","chapterKey":"综合测试三","n":17,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试三 第 17 题"},"stem":"意识和物质的对立只有在非常有限的范围内才有绝对的意义，超出这个范围，其对立便是相对的。这是因为","choices":[{"id":"A","text":"意识根源于物质"},{"id":"B","text":"意识不能代替物质，物质也不能代替意识"},{"id":"C","text":"意识是物质的根本属性和存在方式"},{"id":"D","text":"意识可以转化为物质"}],"answer":["A","D"],"analysis":{"point":"本题考查物质和意识的关系。“意识和物质的对立只有在非常有限的范围内才有绝对的意义，超出这个范围，其对立便是相对的”，因为物质和意识之间还有“统一”的一面，因此，只要在四个选项中选出表述正确，且表达二者之间相互统一关系的选项即可。因此，选项A、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"表述正确，但是体现的是物质和意识之间相互对立的一面，故不选。","C":"表述错误，运动是物质的根本属性和存在方式，而不是意识，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-mayuan-test3-18","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试三","chapterKey":"综合测试三","n":18,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试三 第 18 题"},"stem":"北京时间2019年4月10日21时，“事件视界望远镜”项目在全世界多地同时召开发布会，公布了人类首次拍到的黑洞照片。这是继2015年人类通过引力波探测“听到”两个“黑洞”合体之后，证明黑洞存在的直接“视界”证据。有科学家认为，这张看起来有点模糊的照片意义非凡，它再次验证了爱因斯坦广义相对论的预言是对的，并将进一步帮助科学家解答星系演化等一系列宇宙本质问题。人类首次“看到”黑洞正面照表明","choices":[{"id":"A","text":"空间的性质依赖于物质的分布及其运动状态"},{"id":"B","text":"世界是物质的统一体"},{"id":"C","text":"物质世界的客观存在与人的实践和认识水平有关"},{"id":"D","text":"空间的观念随着人的认识发展而拓展"}],"answer":["A","B","D"],"analysis":{"point":"本题考查物质运动与时空。空间具有相对性，空间的具体特性会随着物质的分布及其运动状态而变化；不论是黑洞还是引力波，都具有客观实在性，都属于物质，世界是物质的统一体；随着科学的发展，人们对空间的认识也在不断拓展。因此，选项A、B、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"说法错误，物质世界是客观的，与人的认识水平无关。故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-mayuan-test3-19","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试三","chapterKey":"综合测试三","n":19,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试三 第 19 题"},"stem":"马克思在《关于费尔巴哈的提纲》中写道：“从前的一切唯物主义（包括费尔巴哈的唯物主义）的主要缺点是：对事物、现实、感性，只是从客体的或者直观的形式去理解，而不是把它们当作人的感性活动……去理解。”马克思主义哲学与旧唯物主义的区别在于它","choices":[{"id":"A","text":"从实践的角度去理解社会生活"},{"id":"B","text":"认为物质第一性、意识第二性"},{"id":"C","text":"把认识看成直观、被动的反映"},{"id":"D","text":"用辩证法来考察认识问题"}],"answer":["A","D"],"analysis":{"point":"本题考查马克思主义哲学与旧唯物主义的区别。马克思主义哲学与其他一切哲学相比，最显著的特点在于实践性。马克思主义哲学从实践的角度去理解社会生活，认为社会生活本质上也是实践的。选项A正确。旧唯物主义哲学离开辩证法来考察认识问题，不了解认识的辩证性质，不能把认识看作不断发展的过程，而认为认识是一次性完成的，把复杂的认识过程简单化。而马克思主义哲学用辩证法来考察认识问题，认为认识是一个不断发展的过程，是循环往复的过程。选项D正确。因此，选项A、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"属于马克思主义哲学与旧唯物主义哲学的共同点，凡是唯物主义哲学都认为物质第一性、意识第二性，即物质决定意识。故不选。","C":"马克思主义哲学认为认识是认识主体在实践基础上对客体的能动的、创造性的反映，而旧唯物主义哲学把人的认识看成直观、被动的反映，忽视了人的能动性作用。故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-mayuan-test3-20","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试三","chapterKey":"综合测试三","n":20,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试三 第 20 题"},"stem":"恩格斯指出：“物质的任何有限的存在方式，不论是太阳或星云，个别的动物或动物种属，化学的化合或分解，都同样是暂时的，而且除永恒变化着、永恒运动着的物质以及这一物质运动和变化所依据的规律外，再没有什么永恒的东西了。”在永恒存在着的世界上，任何事物都是暂时的，任何事物都是由其他事物转化而来的，并且必将转化为另外的事物。由此可见，事物是由可能到现实的过程。这给我们的启示是","choices":[{"id":"A","text":"没有可能就没有现实"},{"id":"B","text":"可能包含着现实的因素和根据"},{"id":"C","text":"抽象的可能也必将实现"},{"id":"D","text":"事物发展一定是好的可能"}],"answer":["A","B"],"analysis":{"point":"本题考查现实与可能的关系。现实与可能既有区别又有联系。没有现实就没有可能，反过来，没有可能就没有现实，它们在一定条件下相互转化。选项A正确。可能与现实具有辩证关系：一方面，现实蕴藏着未来的发展方向，会不断产生新的可能；另一方面，可能包含着发展成为现实的因素和根据，一旦主客观条件成熟，可能就转化为现实。选项B正确。因此，选项A、B正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"现实的可能是理论上可行，也具有实现的现实条件；而抽象的可能在理论上可行，但缺乏现实条件。所以，“抽象的可能也必将实现”说法错误，故不选。","D":"说法错误，事物的发展不仅有好的可能，也有不好的可能。请注意，这里所谓的“好的可能”是针对作为主体的人来说的，也就是对人是否有利。此处考生可能会混淆。因为辩证法的发展观认为，发展就是向上的运动和顺应规律的变化，即事物的发展指的是向好的方面变化。那为什么关于选项D还存在着不好的可能呢？关键就在于，“事物的发展是向好的方面变化”，此处的“好”是符合、顺应规律的意思，而“事物的发展不仅有好的可能，也有不好的可能”，此处的“好”是对人是否有利的意思。故不选。"}}},{"id":"advanced-mayuan-test3-21","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试三","chapterKey":"综合测试三","n":21,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试三 第 21 题"},"stem":"母质、气候、生物、地形、时间是土壤形成的五大关键成土因素。母质是土壤形成的物质基础和初始无机养分的最初来源。气候导致矿物的风化和合成，有机质的形成和积累，土壤中物质的迁移、分解和合成。生物包括植物、动物和微生物等，是促进土壤发生发展最活跃的因素。地形可以使物质在地表进行再分配，使土壤及母质在接受光、热、水等条件方面发生差异。时间是阐明土壤形成发展的历史动态过程，母质、气候、生物和地形等对成土过程的作用随着时间延续而加强。土壤的生成过程说明","choices":[{"id":"A","text":"事物总是作为过程而存在"},{"id":"B","text":"时间是物质运动的存在形式"},{"id":"C","text":"事物的发展总是呈现线性上升的态势"},{"id":"D","text":"事物的产生是多种因素相互作用的结果"}],"answer":["A","B","D"],"analysis":{"point":"本题是一道多考点综合性考题。事物总是作为过程而存在，这是过程论的观点。选项A正确。时间和空间是物质运动的存在形式，这是唯物论的时空观。选项B正确。事物的产生是多种因素相互作用的结果，符合马克思主义的基本观点。选项D正确。因此，选项A、B、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"事物的发展是螺旋式上升或波浪式前进的过程，并不是线性上升，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-mayuan-test3-22","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试三","chapterKey":"综合测试三","n":22,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试三 第 22 题"},"stem":"17世纪末，牛顿提出了光的微粒说，认为光是由微粒状的物质组成的。不久，惠更斯提出了光的波动说，认为光是一种波。19世纪初，波动说又重新被提出，并用实验有力地否定了牛顿的微粒说。19世纪末，光电效应等一系列的实验向波动说提出了新的挑战。爱因斯坦最终冲破禁区，创立了光的量子力学，认为光既是波，又是微粒，既是连续的，又是不连续的。这段话说明","choices":[{"id":"A","text":"实践是认识发展的动力"},{"id":"B","text":"事物发展是前进性和曲折性的统一"},{"id":"C","text":"客观事物无法被认识"},{"id":"D","text":"认识的发展过程表现为认识过程的反复性和认识发展的无限性"}],"answer":["A","B","D"],"analysis":{"point":"本题考查实践与认识的相关内容。题干中描述的是关于“光”的一系列学说的提出、否定和进一步发展。在这个过程中，我们可以看到实践（题干中提到了实验）是认识发展的动力，事物发展是前进性和曲折性的统一，以及认识过程的反复性和无限性的规律（题干中提到了几代科学家的不断努力）。因此，选项A、B、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"认为客观事物无法被认识是不可知论的观点，说法错误，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-mayuan-test3-23","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试三","chapterKey":"综合测试三","n":23,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试三 第 23 题"},"stem":"基因编辑是应对遗传性疾病的一种潜在治疗办法，但其技术运用极具争议，这不仅是因为基因的变化会传给后代并最终有可能影响整个基因库，而且更重要的是基因编辑会产生长远而深刻的社会影响，可能衍生出一系列棘手的伦理、法律和安全难题。正因为如此，许多国家对人类基因编辑技术制定了相应的伦理、法律规范。人类严格控制基因编辑行为的原因在于","choices":[{"id":"A","text":"科学技术有时表现为异己的、敌对的力量"},{"id":"B","text":"基因编辑技术可能突破人类的伦理道德底线"},{"id":"C","text":"人的实践活动要遵循真理尺度与价值尺度的统一"},{"id":"D","text":"人的实践活动是合规律性与合目的性的统一"}],"answer":["A","B","C","D"],"analysis":{"point":"本题考查真理尺度和价值尺度的辩证关系、正确把握科学技术的作用。科学技术是一把“双刃剑”，有时对社会发展起推动作用，但有时也会对人类产生不利影响。选项A正确。基因编辑技术以人的基因为研究对象，如果控制不好可能会突破伦理道德底线。选项B正确。所谓的真理尺度就是要做对的事情，所谓的价值尺度就是要做有用的事情，人的实践活动必须遵循真理尺度和价值尺度的统一。选项C正确。所谓的合规律性就是按规律办事，所谓的合目的性就是办事要符合人的主观目的和意愿。人的实践活动，既要符合规律，又要满足目的。选项D正确。因此，选项A、B、C、D正确。\\n无干扰选项。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-mayuan-test3-24","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试三","chapterKey":"综合测试三","n":24,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试三 第 24 题"},"stem":"恩格斯在《家庭、私有制和国家的起源》中指出：“这个社会陷入了不可解决的自我矛盾，分裂为不可调和的对立面而又无力摆脱这些对立面，而为了使这些对立面，这些经济利益互相冲突的阶级，不致在无谓的斗争中把自己和社会消灭，就需要有一种表面上凌驾于社会之上的力量，这种力量应当缓和冲突，把冲突保持在‘秩序’的范围以内；这种从社会中产生但又居于社会之上并且日益同社会相异化的力量，就是国家。”这给我们的启示有","choices":[{"id":"A","text":"思想观念上层建筑在上层建筑中居于主导地位"},{"id":"B","text":"国家是阶级矛盾不可调和的产物"},{"id":"C","text":"上层建筑为自己的经济基础服务"},{"id":"D","text":"政治上层建筑中的政治法律思想是上层建筑的核心"}],"answer":["B","C"],"analysis":{"point":"本题考查上层建筑和国家的产生。题干的意思是：在阶级已经产生且阶级矛盾冲突愈演愈烈的形势下，为了把阶级斗争限制在一定“秩序”之内，国家作为强制性的力量应运而生。所以国家是阶级矛盾不可调和的产物，国家的实质是一个阶级统治另一个阶级的工具。选项B正确。经济基础与上层建筑之间的关系是辩证的，经济基础决定上层建筑，而上层建筑对经济基础具有反作用，上层建筑的反作用集中表现在为自己的经济基础服务。上层建筑反作用的性质，取决于它所服务的经济基础的性质，归根到底取决于它是否有利于生产力的发展。选项C正确。因此，选项B、C正确。","options":{"A":"在整个上层建筑中，政治上层建筑居于主导地位，以国家政权为核心，国家不是从来就有的，它是社会发展到一定历史阶段的产物，故不选。","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"政治法律思想属于观念上层建筑，国家政权是上层建筑的核心，故不选。"}}},{"id":"advanced-mayuan-test3-25","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试三","chapterKey":"综合测试三","n":25,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试三 第 25 题"},"stem":"社会形态的更替具有客观性和必然性，但这并不否定人们历史活动的能动性，并不排斥人们在遵循社会发展规律的基础上，对于某种社会形态的历史选择性。人们历史活动的能动性和选择性主要体现在","choices":[{"id":"A","text":"社会发展的客观必然性为人们的历史选择提供了基础、范围和可能性空间"},{"id":"B","text":"社会形态更替的过程是主体能动性与客观规律性相统一的过程"},{"id":"C","text":"人们的历史选择性归根结底是人民群众的选择性"},{"id":"D","text":"社会发展的客观过程由每一个参与历史活动的个人的主观意志所决定"}],"answer":["A","B","C"],"analysis":{"point":"本题考查社会形态更替的客观必然性与人们的历史选择性。唯物史观认为，社会历史发展具有客观必然性，也就是说，人不能随心所欲地决定历史如何发展，而必须顺应客观必然，在既定的范围内选择。选项A正确。社会历史的发展一方面遵循着必然性，另一方面又由人在其中参与完成，体现着人们的主体选择性。社会历史的发展是两方面相统一的过程。选项B正确。人们的历史选择性，这里的“人们”指的就是“人民群众”。选项C正确。因此，选项A、B、C正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"存在两处错误：第一，并不是“每一个参与历史活动的个人”，而应该是“人民群众”；第二，即便是“人民群众”，个人的主观意志也不能随意决定社会发展的客观过程，而需要遵循历史发展规律。故不选。"}}},{"id":"advanced-mayuan-test3-26","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试三","chapterKey":"综合测试三","n":26,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试三 第 26 题"},"stem":"恩格斯说：“在马克思看来，科学是一种在历史上起推动作用的、革命的力量……马克思把科学首先看成历史的有力杠杆，看成最高意义上的革命力量。”现代科技革命推动生产方式的变革，这主要表现在科技革命","choices":[{"id":"A","text":"改变了体力劳动与脑力劳动的比例"},{"id":"B","text":"改变了人们的劳动方式"},{"id":"C","text":"已经成为划分社会形态的根本标志"},{"id":"D","text":"改变了社会经济结构尤其是导致产业结构发生变革"}],"answer":["A","B","D"],"analysis":{"point":"本题考查科技革命。每一次科学技术革命，都不同程度地引起生产方式、生活方式、思维方式的深刻变化和社会的历史进步。现代科技革命推动了生产方式的变革。其一，改变了社会生产力的构成要素。科技发展使生产自动化程度提高，大大地改变了体力劳动与脑力劳动的比例，使劳动力结构向着智能化趋势发展。其二，改变了人们的劳动形式。微电子技术的出现和广泛应用，智能机器代替了人的部分脑力劳动，使人们的劳动方式经历了由机械自动化走向智能自动化、由局部自动化走向大系统管理和控制自动化的根本性变革。其三，改变了社会经济结构，特别是导致产业结构发生变革。新的技术革命在推动传统产业现代化的同时，使第三产业在国民经济中所占的比重日益提高。产业结构的变化又导致就业结构的变化，从事第三产业的人数比例迅速增长，科技人员和管理人员的比例日益增长。因此，选项A、B、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"说法错误，划分社会形态的根本标志，不是科技革命，而是生产资料所有制。故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-mayuan-test3-27","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试三","chapterKey":"综合测试三","n":27,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试三 第 27 题"},"stem":"简单劳动是指不需要经过专门训练和培养的一般劳动者都能从事的劳动。复杂劳动是指需要经过专门训练和培养，具有一定文化知识和技术专长的劳动者所从事的劳动。复杂程度不同的劳动生产的产品之所以在市场中能够按照一定比例相交换，是因为","choices":[{"id":"A","text":"复杂劳动等于自乘的或多倍的简单劳动"},{"id":"B","text":"形成商品价值量的劳动是以简单劳动为尺度的"},{"id":"C","text":"复杂程度不同的劳动生产的产品都具有价值"},{"id":"D","text":"复杂劳动决定所生产的单位商品的价值量更高"}],"answer":["A","B","C"],"analysis":{"point":"本题考查商品价值量的决定。形成商品价值量的劳动以简单劳动为尺度，复杂劳动等于自乘的或多倍的简单劳动，复杂劳动创造的价值可以等于倍加的简单劳动创造的价值。因而，复杂程度不同的劳动生产的产品在市场中能够按照一定比例相交换，这一交换比例是由自发的社会过程确定的。另外，商品之所以可以交换，是因为它们有一个共同的本质即价值。因此，选项A、B、C正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"单位商品的价值量的大小是由社会必要劳动时间决定的，并不是由劳动的技术水平的高低决定的，故不选。"}}},{"id":"advanced-mayuan-test3-28","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试三","chapterKey":"综合测试三","n":28,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试三 第 28 题"},"stem":"在其他条件不变的情况下，随着资本家不断进行资本积累，将会导致","choices":[{"id":"A","text":"可变资本在总资本中的比例降低"},{"id":"B","text":"资本有机构成提高"},{"id":"C","text":"平均利润率提高"},{"id":"D","text":"相对过剩人口的形成"}],"answer":["A","B","D"],"analysis":{"point":"本题考查资本积累。随着资本的积累，资本家会用越来越多的机器设备代替活劳动，也就是购买机器设备的不变资本越来越多，而购买活劳动的可变资本越来越少。资本有机构成从量上来看就是不变资本与可变资本的比例，根据上文分析，这个比例应该是提高的。由于越来越多的活劳动被机器设备替代，其结果就是不可避免地造成大批工人失业，形成相对过剩人口。因此，选项A、B、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"在预付资本中，能够带来利润的部分是可变资本，可变资本的比例越来越小，就决定了利润率乃至平均利润率将会越来越低，而不是越来越高。故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-mayuan-test3-29","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试三","chapterKey":"综合测试三","n":29,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试三 第 29 题"},"stem":"随着科学技术革命和生产力的发展，第二次世界大战后资本主义经济政治出现新变化，比如，生产资料所有制的变化、劳资关系和分配关系的变化、社会阶层和阶级结构的变化、经济调节机制和经济危机形态的变化以及政治制度的变化等，但是，第二次世界大战后资本主义发生的变化是在资本主义制度基本框架内的变化，并不意味着资本主义生产关系的根本性质发生了变化。这是因为","choices":[{"id":"A","text":"生产资料私有制仍然是资本主义基本经济制度"},{"id":"B","text":"资本追逐剩余价值的本性并没有改变"},{"id":"C","text":"导致财富占有两极分化的制度基础没有改变"},{"id":"D","text":"周期性经济危机仍然是资本主义基本经济特征"}],"answer":["A","B","C","D"],"analysis":{"point":"本题考查第二次世界大战后资本主义出现新变化的原因和实质。第二次世界大战后，资本主义发生的变化是在资本主义制度基本框架内的变化，并不意味着资本主义生产关系的根本性质发生了变化。从资本主义发展的实际情况来看，生产资料私有制仍然是资本主义基本经济制度，资本追逐剩余价值的本性并没有改变，改变的只是获取剩余价值的方式和方法。社会福利制度缓和了资本主义分配关系的矛盾，但并没有改变导致财富占有两极分化的制度基础。周期性经济危机仍然是资本主义基本经济特征。因此，选项A、B、C、D正确。\\n无干扰选项。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-mayuan-test3-30","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试三","chapterKey":"综合测试三","n":30,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试三 第 30 题"},"stem":"1516年，英国人托马斯·莫尔发表了《乌托邦》一书，标志着空想社会主义的诞生。1848年，马克思、恩格斯发表了《共产党宣言》，标志着科学社会主义的产生，社会主义实现了从空想到科学的历史性飞跃。科学社会主义超越空想社会主义之处在于","choices":[{"id":"A","text":"找到了实现理想社会的现实道路"},{"id":"B","text":"对未来社会进行了细致的描绘"},{"id":"C","text":"揭示了资本主义必然灭亡的经济根源"},{"id":"D","text":"对资本主义进行了无情的批判"}],"answer":["A","C"],"analysis":{"point":"本题考查马克思主义经典作家展望未来社会的科学立场和方法。空想社会主义的局限性主要表现在：空想社会主义者憧憬取代资本主义的理想社会，却找不到通往理想社会的现实道路；只看到了资本主义必然灭亡的命运，却未能揭示资本主义必然灭亡的经济根源。因此，选项A、C正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"科学社会主义对未来社会的一般特征作了阐述，但是没有对“细节”进行描绘，因此，“细致的描绘”是错误的说法。故不选。","C":"（正确选项，分析见“解题思路”）","D":"对资本主义进行批判是空想社会主义和科学社会主义的共同态度，而本题问的是科学社会主义超越空想社会主义之处，故排除。"}}},{"id":"advanced-mayuan-test4-1","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试四","chapterKey":"综合测试四","n":1,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试四 第 1 题"},"stem":"关于时间的宝贵，从古至今，名句频出。既有陶渊明“盛年不重来，一日难再晨。及时当勉励，岁月不待人”的诗句，也有鲁迅“时间就是生命”的名言；既有“一寸光阴一寸金，寸金难买寸光阴”的俗语，也有“时间就是金钱，效率就是生命”的口号。“盛年不重来，一日难再晨”“时间就是生命”表明时间具有","choices":[{"id":"A","text":"一维性"},{"id":"B","text":"三维性"},{"id":"C","text":"绝对性"},{"id":"D","text":"相对性"}],"answer":["A"],"analysis":{"point":"本题考查时空的特征。时间与空间是物质运动的存在方式，其中时间是指物质运动的持续性和顺序性，空间是指物质运动的广延性和伸张性。时间具有客观性和一维性，或不可逆性的特点，空间具有客观性和三维性的特点。“盛年不重来，一日难再晨”“时间就是生命”说明了时间的一维性，一去不复返。因此，选项A正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"三维性是空间的特点。","C":"不符合题干要求。","D":"不符合题干要求。"}}},{"id":"advanced-mayuan-test4-2","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试四","chapterKey":"综合测试四","n":2,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试四 第 2 题"},"stem":"《坛经》中记载：“时有风吹幡动，一僧曰风动，一僧曰幡动，议论不已。慧能进曰：‘不是风动，不是幡动，仁者心动。’”这段话表明慧能关于运动的基本观点是","choices":[{"id":"A","text":"运动是物质的根本属性"},{"id":"B","text":"运动和物质是不可分割的"},{"id":"C","text":"精神运动是物质运动的一种形式"},{"id":"D","text":"精神是运动的主体"}],"answer":["D"],"analysis":{"point":"本题考查对唯心主义的理解。题干中慧能的观点是，不是风动也不是幡动，是人的心在动。关键词“心”明确告诉我们这是典型的主观唯心主义，认为精神是世界的本原和运动的主体。因此，选项D正确。","options":{"A":"运动是物质的根本属性和存在方式，运动和物质不可分割，都是唯物主义观点，而题干中慧能的观点是唯心主义观点。故不选。","B":"运动是物质的根本属性和存在方式，运动和物质不可分割，都是唯物主义观点，而题干中慧能的观点是唯心主义观点。故不选。","C":"不符合慧能的观点，慧能的基本观点是精神是运动的主体，精神运动是运动的唯一形式，而不存在“物质运动”的观点，或者说他认为“物质在运动”的观点是绝对错误的。故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-mayuan-test4-3","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试四","chapterKey":"综合测试四","n":3,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试四 第 3 题"},"stem":"“凡事预则立，不预则废”在哲学上反映的是","choices":[{"id":"A","text":"可能和现实的辩证关系"},{"id":"B","text":"原因和结果的辩证关系"},{"id":"C","text":"现象和本质的辩证关系"},{"id":"D","text":"必然和偶然的辩证关系"}],"answer":["B"],"analysis":{"point":"本题考查因果联系。唯物辩证法认为任何现象都会引起其他现象的产生，任何现象的产生都是由其他现象所引起的。这种引起和被引起的关系，叫作因果联系。由于一定的原因必然引起一定的结果，这就要求人们应当根据某种原因，预见事物发展的结果。题干中的“预”和“不预”就是原因，“立”和“废”就是由它们引起的结果。“凡事预则立”告诉我们，有了对后果的科学预见，才能正确指导自己的具体行动，促使事物向人们所期望的方向发展。“不预则废”告诉我们，如果只顾眼前的利益，不顾长远的结果，必然会给工作和日常生活带来危害。因此，选项B正确。","options":{"A":"可能与现实是对立统一的关系，但题干主要强调的是因果联系，并没有涉及可能与现实的关系，故不选。","B":"（正确选项，分析见“解题思路”）","C":"现象与本质是既对立又统一的，二者相互依存、相互包含、相互转化，但题干并没有涉及现象与本质的关系，故不选。","D":"必然与偶然是辩证统一的，偶然中隐藏着必然，而任何偶然又总是服从于必然，二者在一定条件下可以相互转化，但题干并没有涉及必然与偶然的关系，故不选。"}}},{"id":"advanced-mayuan-test4-4","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试四","chapterKey":"综合测试四","n":4,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试四 第 4 题"},"stem":"“善泳者溺，善骑者堕，各以其所好反自为祸。”这句古话蕴含的哲理是","choices":[{"id":"A","text":"要透过现象认识事物的本质"},{"id":"B","text":"矛盾的主要方面决定事物的性质"},{"id":"C","text":"矛盾在一定条件下可以相互转化"},{"id":"D","text":"矛盾是事物发展的动力"}],"answer":["C"],"analysis":{"point":"本题考查矛盾的相关知识。题干中古话的意思是往往善于游泳的人易溺水，善于骑马的人易坠马，越是熟悉和擅长的东西越容易被忽视而出现祸事。这体现了辩证法中矛盾在一定条件下可以相互转化的观点。因此，选项C正确。","options":{"A":"说法正确，但“溺水”与“善于游泳”不是现象与本质的关系，与题意不符，故不选。","B":"表述不全面且与题干无关，应该是“主要矛盾的主要方面决定事物的性质”，故不选。","C":"（正确选项，分析见“解题思路”）","D":"说法正确，但是题干所强调的“善于游泳”或者是“溺水”均与事物发展的动力无关，故不选。"}}},{"id":"advanced-mayuan-test4-5","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试四","chapterKey":"综合测试四","n":5,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试四 第 5 题"},"stem":"马克思说：“一种科学只有在成功地运用数学时，才算达到了真正完善的地步。”这句话说明","choices":[{"id":"A","text":"认识量是认识和实践的起点和基础"},{"id":"B","text":"只有认识量才能区分事物"},{"id":"C","text":"只有认识量才能更深刻地把握质"},{"id":"D","text":"考察量是认识质的前提"}],"answer":["C"],"analysis":{"point":"本题考查认识量的意义。任何事物都是质和量的统一体。量是事物的规模、程度、速度以及它的构成成分在空间上的排列组合等可以用数量关系表示的规定性。认识量的意义就在于认识事物的量是认识的深化和精确化，只有认识量才能更深刻地把握质。因此，选项C正确。","options":{"A":"质是一事物区别于其他事物的内在规定性，是由事物内部矛盾的特殊性所决定的。认识质是认识和实践的起点和基础，只有认识质才能区分事物。故不选。","B":"质是一事物区别于其他事物的内在规定性，是由事物内部矛盾的特殊性所决定的。认识质是认识和实践的起点和基础，只有认识质才能区分事物。故不选。","C":"（正确选项，分析见“解题思路”）","D":"区分质是认识量的前提，考察量是认识质的深化。故不选。"}}},{"id":"advanced-mayuan-test4-6","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试四","chapterKey":"综合测试四","n":6,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试四 第 6 题"},"stem":"诗歌《圆的自白》：“圆，虽然完美，却从来不知满足。因为它知道，每一个终点，都是新的起点。”这给我们的启示是","choices":[{"id":"A","text":"肯定就是否定，终点就是起点"},{"id":"B","text":"辩证否定是事物发展的重要环节"},{"id":"C","text":"否定之否定阶段是向原来出发点的回复"},{"id":"D","text":"否定是绝对的否定，是不包含肯定的否定"}],"answer":["B"],"analysis":{"point":"本题考查辩证的否定观。事物内部都存在着肯定因素和否定因素。肯定因素是维持现存事物存在的因素，否定因素是促使现存事物灭亡的因素。否定是事物发展的环节，它是旧事物向新事物的转变，是从旧质到新质的飞跃。只有经过否定，旧事物才能向新事物转变。所以每个终点都是一个新的起点。因此，选项B正确。","options":{"A":"辩证的否定观认为要对一切事物采取科学的分析态度，既要看到事物的肯定方面，又要看到事物的否定方面，在肯定中看到否定，在否定中看到肯定，不能肯定一切或否定一切。但是，肯定和否定还是具有明确界限的，不能模糊二者的界限而犯诡辩论的错误。故不选。","B":"（正确选项，分析见“解题思路”）","C":"事物的辩证发展就是经过两次否定、三个阶段，形成一个周期，其中否定之否定阶段仿佛是向原来出发点的回复，但这是在更高阶段上的回复。选项C将其简单表述为“向原来出发点的回复”，说法错误，故不选。","D":"“否定是绝对的否定，是不包含肯定的否定”是一种典型的形而上学否定观。辩证的否定观认为，要在肯定中看到否定，在否定中看到肯定。故不选。"}}},{"id":"advanced-mayuan-test4-7","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试四","chapterKey":"综合测试四","n":7,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试四 第 7 题"},"stem":"1864年冬天的一个傍晚，在比利时根特大学的工作室里，凯库勒由于白天苦苦思索苯的结构而感到身心疲乏。他把椅子转向炉火打起瞌睡来。炉膛里燃烧的木炭所产生的火星，在他蒙眬的眼里变成了一个个原子，而这些原子又在眼前跳跃飞舞起来。它们一个个紧密靠近成一长行分子，盘绕、旋转，像蛇一样地运动着。一会儿，这条由长行分子化成的长蛇突然咬住自己的尾巴，呈现一种环形蛇并虚幻地在他的眼前旋转起来……这时，炉膛里燃烧的木炭发出的爆裂声把他从睡梦中惊醒。这种环形蛇的具体形象久久地在他的脑海里浮现。梦幻中的环形蛇的启发使得凯库勒兴奋得一夜未睡，开始构思起苯的分子结构来。他最终通过联想将咬尾蛇的形象抽象为苯的碳原子结构——苯环结构式。这个故事给我们的启示是","choices":[{"id":"A","text":"非理性因素在人的认识活动中起着基础性的作用"},{"id":"B","text":"联想和想象对科学发展起着预见作用"},{"id":"C","text":"非理性因素激发着人的想象力和创造力"},{"id":"D","text":"人的认识是永无止境的"}],"answer":["C"],"analysis":{"point":"本题考查非理性因素在认识活动中的作用。非理性因素是认识主体的情感和意志，还包括一些非逻辑性的认识形式如联想、想象、直觉、灵感等，对人的认识能力和认识活动起着激活、驱动作用，即激发人的想象力和创造力。因此，选项C正确。","options":{"A":"理性因素是指人的理性直观、理性思维等能力，它在认识活动中的作用主要有指导作用、解释作用和预见作用，所以在人的认识活动尤其是自然科学的研究中起着基础性的作用。故不选。","B":"理性因素具有预见作用，是利用科学知识进行预测，而不是靠主观臆想，联想和想象是非理性因素。故不选。","C":"（正确选项，分析见“解题思路”）","D":"人的认识具有无限性和反复性，是“实践—认识—再实践—再认识”的过程，认识运动不断反复和无限发展，这是人类认识运动的辩证发展过程，也是人类认识运动的基本规律。与题干无关，故不选。"}}},{"id":"advanced-mayuan-test4-8","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试四","chapterKey":"综合测试四","n":8,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试四 第 8 题"},"stem":"马克思说：“人的思维是否具有客观的真理性，这不是一个理论的问题，而是一个实践的问题。人应该在实践中证明自己思维的真理性，即自己思维的现实性和力量，自己思维的此岸性。关于思维——离开实践的思维——的现实性或非现实性的争论，是一个纯粹经院哲学的问题。”这一论断表明","choices":[{"id":"A","text":"认识是实践的先导"},{"id":"B","text":"实践使认识得以产生和发展"},{"id":"C","text":"实践作为检验真理的标准既是确定的，又是不确定的"},{"id":"D","text":"人只有在实践中才能检验认识的真理性"}],"answer":["D"],"analysis":{"point":"本题考查实践是检验认识真理性的唯一标准。题干强调“人的思维是否具有客观的真理性，这不是一个理论的问题，而是一个实践的问题”。“自己思维的此岸性”说明人应该在实践中证明自己思维的真理性，即自己思维的现实性和力量。题干强调只有实践才能证明思维的真理性。而实践是检验真理的唯一标准，人只有在实践中才能检验认识的真理性。因此，选项D正确。","options":{"A":"题干强调人只有在实践中才能检验认识的真理性，这三个选项虽然说法正确，但与题干无关，故不选。","B":"题干强调人只有在实践中才能检验认识的真理性，这三个选项虽然说法正确，但与题干无关，故不选。","C":"题干强调人只有在实践中才能检验认识的真理性，这三个选项虽然说法正确，但与题干无关，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-mayuan-test4-9","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试四","chapterKey":"综合测试四","n":9,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试四 第 9 题"},"stem":"马克思在《关于费尔巴哈的提纲》中指出：“全部社会生活在本质上是实践的。凡是把理论引向神秘主义的神秘东西，都能在人的实践中以及对这个实践的理解中得到合理的解决。”人是历史活动的主体，任何历史阶段，人的实践活动都贯穿始终，同时人的实践活动又受一定历史条件的制约。这体现了实践具有","choices":[{"id":"A","text":"客观实在性"},{"id":"B","text":"自觉能动性"},{"id":"C","text":"社会历史性"},{"id":"D","text":"客观物质性"}],"answer":["C"],"analysis":{"point":"本题考查实践的基本特征。马克思认为，社会生活在本质上是实践的。人是历史活动的主体，实践是社会生活的本质体现。人们的实践不是孤立的个人活动，人们总是结成一定的社会关系才能从事实践活动。实践的社会性也决定了它的历史性，因为实践的内容、性质、范围、水平都是受一定社会历史条件制约的，都是随着一定的社会历史条件的变化而变化的。因此，选项C正确。","options":{"A":"强调的是区别于主观认识活动的物质性，且实践的基本特征不包括客观物质性，不符合题意。实践是物质性的活动，具有客观实在性，只有通过实践才能把头脑中的观念转化为客观的现实，实践是同主观认识活动相区别的感性物质活动。故不选。","B":"强调的是能动性，与题干无关。实践是人类有意识的活动，体现了自觉能动性。人具有理性思维，所从事的是不同于动物的本能活动的有目的、有意识地改造世界的活动，只有这种人的自觉的、能动的活动才具有真正的实践的意义。故不选。","C":"（正确选项，分析见“解题思路”）","D":"强调的是区别于主观认识活动的物质性，且实践的基本特征不包括客观物质性，不符合题意。实践是物质性的活动，具有客观实在性，只有通过实践才能把头脑中的观念转化为客观的现实，实践是同主观认识活动相区别的感性物质活动。故不选。"}}},{"id":"advanced-mayuan-test4-10","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试四","chapterKey":"综合测试四","n":10,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试四 第 10 题"},"stem":"恩格斯说：“自由不在于幻想中摆脱自然规律而独立，而在于认识这些规律，从而能够有计划地使自然规律为一定的目的服务……自由就在于根据对自然界的必然性的认识来支配我们自己和外部自然界。”这句话的哲学启示是","choices":[{"id":"A","text":"必然是自由的前提条件"},{"id":"B","text":"自由是历史发展的产物"},{"id":"C","text":"自由是摆脱规律的制约"},{"id":"D","text":"必然是自觉自主的状态"}],"answer":["A"],"analysis":{"point":"本题考查自由与必然的关系。哲学上的自由是标示人的活动状态的范畴，指的是人在活动中通过认识和利用必然所表现出的一种自觉自主的状态。而必然指的是不依赖于人的意识而存在的自然和社会发展所固有的客观规律。所以，认识必然是实现自由的前提。因此，选项A正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"说法正确，但与题意不符。自由是有条件的，分别为认识条件和实践条件。意志自由是借助对事物的认识（必然）作出决定的能力。故不选。","C":"说法错误，规律是客观的，是不以人的意志为转移的。规律的存在一定会制约人的活动，即使是到了“自由王国”阶段，人们可以按照自己的意志创造历史，也无法摆脱规律的制约。故不选。","D":"说法错误，自由是指人在活动中通过认识和利用必然所表现出的一种自觉自主的状态，而必然指的是规律。故不选。"}}},{"id":"advanced-mayuan-test4-11","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试四","chapterKey":"综合测试四","n":11,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试四 第 11 题"},"stem":"“无论哪一个社会形态，在它所能容纳的全部生产力发挥出来以前，是决不会灭亡的；而新的更高的生产关系，在它存在的物质条件在旧社会的胎胞里成熟以前，是决不会出现的。”这段话说明","choices":[{"id":"A","text":"生产力的发展引起生产关系的改变，是不以人的意志为转移的客观过程"},{"id":"B","text":"生产关系的变革必须要通过社会革命才能完成"},{"id":"C","text":"生产关系的改变是一个无须人参与的自发过程"},{"id":"D","text":"生产力决定生产关系，生产关系对生产力具有反作用"}],"answer":["A"],"analysis":{"point":"本题考查生产力对生产关系的决定作用。这段“两个决不会”的论述充分说明了生产力是决定生产关系变革的关键因素，生产关系随生产力的变化而变化是一个不以人的意志为转移的客观过程。当它改变的时候，我们不想它变，它也会变；当它不改变的时候，我们要求它变，它也不会变。因此，选项A正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"社会革命是促进生产关系变革的一种重要手段，但不是“必须”的，这种观点夸大了社会革命的作用，故不选。","C":"生产关系的变革是由社会规律决定的，而社会规律起作用的特点就在于它需要人的参与才能完成，故不选。","D":"说法正确，但是题干的观点并没有突出生产关系是如何反作用于生产力的。与题意不符，故不选。"}}},{"id":"advanced-mayuan-test4-12","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试四","chapterKey":"综合测试四","n":12,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试四 第 12 题"},"stem":"投入某种商品生产过程中的活劳动量不变，如果个别劳动生产率提高，单位劳动时间内生产的商品数量和单位商品的价值量之间的变化表现为","choices":[{"id":"A","text":"商品数量增加，价值量不变"},{"id":"B","text":"商品数量不变，价值量增大"},{"id":"C","text":"商品数量增加，价值量减少"},{"id":"D","text":"商品数量增加，价值量增大"}],"answer":["A"],"analysis":{"point":"本题考查商品的价值量。按照题干的信息，活劳动量不变就是劳动力人数不变，个别劳动生产率提高，可以提高个别生产者的劳动效率，使商品数量增加，但是单位商品价值量的唯一决定因素是社会必要劳动时间，与个别劳动时间无关，所以，个别劳动生产率的改变不能改变单位商品的价值量。因此，选项A正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"商品的价值量是由社会必要劳动时间决定的，与个别劳动时间无关，故不选。","C":"商品的价值量是由社会必要劳动时间决定的，与个别劳动时间无关，故不选。","D":"商品的价值量是由社会必要劳动时间决定的，与个别劳动时间无关，故不选。"}}},{"id":"advanced-mayuan-test4-13","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试四","chapterKey":"综合测试四","n":13,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试四 第 13 题"},"stem":"在以私有制为基础的商品经济中，人与人的社会关系被物与物的关系所掩盖，从而使商品具有一种神秘的属性，似乎它具有决定商品生产者命运的神秘力量。马克思把商品世界的这种神秘性比喻为拜物教，称之为商品拜物教。其实决定商品生产者命运的是","choices":[{"id":"A","text":"私人劳动是否可以转化为社会劳动"},{"id":"B","text":"劳动力是否成为商品"},{"id":"C","text":"价值是否能转化为使用价值"},{"id":"D","text":"抽象劳动是否能转化为具体劳动"}],"answer":["A"],"analysis":{"point":"本题考查以私有制为基础的商品经济的基本矛盾。马克思曾经把商品转换成货币称为“商品的惊险的跳跃”，“这个跳跃如果不成功，摔坏的不是商品，但一定是商品占有者”，意思就是商品生产者的命运其实主要是由商品是否能顺利卖出决定的。而只有当商品顺利出售时，私人劳动才能转化为社会劳动。因此，选项A正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"劳动力成为商品是货币转化为资本的前提条件，劳动力成为商品，通过抽象劳动创造出剩余价值，当剩余价值投入下一轮扩大再生产，生产更多的剩余价值时，货币就转化成了资本。与题干无关，故不选。","C":"说法错误，商品顺利出售，是商品生产者让渡商品的使用价值给消费者，通过交换以货币的形式获得商品的价值，这一过程并没有体现价值转化为使用价值。故不选。","D":"不存在抽象劳动转化为具体劳动，故不选。"}}},{"id":"advanced-mayuan-test4-14","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试四","chapterKey":"综合测试四","n":14,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试四 第 14 题"},"stem":"某资本家经营的企业原来一天的工作时间为8小时，剩余价值率为100%。在其他条件不变的情况下，如果采取绝对剩余价值的生产方法将剩余价值率提高到200%，且不提高劳动强度的话，则工人一天的工作时间将变为","choices":[{"id":"A","text":"10小时"},{"id":"B","text":"12小时"},{"id":"C","text":"14小时"},{"id":"D","text":"16小时"}],"answer":["B"],"analysis":{"point":"本题考查剩余价值率的计算。题干中，原来一天的工作时间为8小时，根据剩余价值率= 剩余劳动时间 / 必要劳动时间 = 100% 可知，剩余劳动时间为4小时、必要劳动时间为4小时；当采用绝对剩余价值的生产方法时，即必要劳动时间不变，绝对延长剩余劳动时间，剩余价值率提高到200%，即新的剩余价值率= 剩余劳动时间 / 4 = 200%，得出新的剩余劳动时间为8小时。由此可知，工人一天的劳动时间将变为8 + 4 = 12（小时）。因此，选项B正确。","options":{"A":"与计算结果不符，故不选。","B":"（正确选项，分析见“解题思路”）","C":"与计算结果不符，故不选。","D":"与计算结果不符，故不选。"}}},{"id":"advanced-mayuan-test4-15","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试四","chapterKey":"综合测试四","n":15,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试四 第 15 题"},"stem":"第二次世界大战以后，资本主义国家经历了第三次科技革命，机器大工业发展到自动化阶段。智能化工厂创造出了较高的生产效率，显露出巨大的竞争力，企业在“机器换人”中取得了一定的经济效益。这意味着率先使用机器人的个别企业","choices":[{"id":"A","text":"资本技术构成的提高"},{"id":"B","text":"剩余价值来源的改变"},{"id":"C","text":"所生产商品价值的提高"},{"id":"D","text":"获得更多的社会平均利润"}],"answer":["A"],"analysis":{"point":"本题考查资本的技术构成、剩余价值的来源、平均利润，是一道综合性考题。资本技术构成可通俗地理解为“企业的机械化水平”，公式为c：v，机器人的使用会使资本技术构成中的劳动力数量降低，即v不断降低，所以会导致资本技术构成提高。因此，选项A正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"剩余价值的唯一来源是剩余劳动。","C":"商品的价值量是由生产商品的社会必要劳动时间决定的，题干中“率先使用”“个别企业”不能代表整个行业的社会必要劳动时间。","D":"题干中个别企业通过技术进步率先攫取的是超额剩余价值，即超额利润，不是社会平均利润。"}}},{"id":"advanced-mayuan-test4-16","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试四","chapterKey":"综合测试四","n":16,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试四 第 16 题"},"stem":"国家垄断资本主义是垄断资本主义的新发展，它对资本主义经济的发展产生了积极的作用。可以说，它的出现","choices":[{"id":"A","text":"在一定程度上促进了社会生产力的发展"},{"id":"B","text":"消除了资本主义的基本矛盾"},{"id":"C","text":"从根本上解决了社会问题"},{"id":"D","text":"使经济危机的出现频率降低"}],"answer":["A"],"analysis":{"point":"本题考查国家垄断资本主义。国家垄断资本主义的发展突破了私人垄断资本的狭隘界限，适应了生产力发展的需要，因而能够在一定程度上推动生产力的发展，推动现代化进程。因此，选项A正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"说法错误，国家垄断资本主义是资本主义基本矛盾进一步尖锐化的结果，并没有从根本上消除资本主义的基本矛盾，故不选。","C":"说法错误，关键词“从根本上”是该选项的错误所在，国家垄断资本主义并没有从根本上解决社会问题，故不选。","D":"说法错误，国家垄断资本主义并没有使经济危机的出现频率降低，反而使经济危机出现的频率提高了，故不选。"}}},{"id":"advanced-mayuan-test4-17","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试四","chapterKey":"综合测试四","n":17,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试四 第 17 题"},"stem":"鲁迅说：“描神画鬼，毫无对证，本可以专靠神思，所谓‘天马行空’地挥写了。然而他们写出来的却是三只眼、长脖子，也就是在正常的人体身上增加了眼睛一只，拉长了颈子二三尺而已。”这段话表明，人们头脑中的鬼神观念","choices":[{"id":"A","text":"是头脑中主观自生的"},{"id":"B","text":"是人脑对客观世界的歪曲反映"},{"id":"C","text":"是人脑对鬼神的虚幻反映"},{"id":"D","text":"可以从人世间找到它的原型"}],"answer":["B","D"],"analysis":{"point":"本题考查对意识的理解。题干中前一句话的意思是鬼神观念本来可以“天马行空”地自主构思，但结果却只是依照现实中人的模样进行歪曲、改造而已。这说明鬼神观念是人脑对客观世界的歪曲反映，可以从人世间找到它的原型。因此，选项B、D正确。","options":{"A":"说法错误，意识是物质的产物，是物质世界在人脑中的主观映象。人们头脑中的鬼神观念并不是头脑中主观自生的，可以从人世间找到它的原型。故不选。","B":"（正确选项，分析见“解题思路”）","C":"说法错误，鬼神并不存在，所以，人们头脑中的鬼神观念并不是对鬼神的虚幻或真实的反映，而是对客观物质世界的反映。故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-mayuan-test4-18","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试四","chapterKey":"综合测试四","n":18,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试四 第 18 题"},"stem":"2016年3月，谷歌“阿尔法狗”与李世石上演人机五番棋大战。最终，李世石以四负一胜的结局输给了“阿尔法狗”。人工智能在棋盘上战胜人类，这样的结果令人惊讶。这一事例给我们的启示有","choices":[{"id":"A","text":"电脑具有比人脑更高级的运动形式"},{"id":"B","text":"电脑是人脑的延伸，是人类扩展自己智力的工具"},{"id":"C","text":"电脑和机器人也能进行某些实践活动"},{"id":"D","text":"电脑是物化了的人的意识，电脑战胜人脑，实质上就是人类自己战胜了自己"}],"answer":["B","D"],"analysis":{"point":"本题考查对人工智能的理解。意识是人脑特有的机能，电脑只不过是人类思维在实践作用之下的工具，电脑战胜人脑，实质上就是人类自己战胜了自己。因此，选项B、D正确。","options":{"A":"说法错误，电脑是人制作出来的，人脑比电脑更高级。故不选。","B":"（正确选项，分析见“解题思路”）","C":"说法错误，实践是人所特有的活动，实践的主体只能是人，电脑和机器人并不能进行实践活动。故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-mayuan-test4-19","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试四","chapterKey":"综合测试四","n":19,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试四 第 19 题"},"stem":"《史记·孙子吴起列传第五》中记载了“田忌赛马”的故事，齐国大将田忌经常与齐国众公子赛马，设重金赌注。孙膑发现他们的马脚力都差不多，马分为上、中、下三等，于是便对田忌说：“您只管下大赌注，我能让您取胜。”田忌相信并答应了他，与齐威王和各位公子用千金作赌注。比赛即将开始，孙膑说：“现在用您的下等马对付他们的上等马，用您的上等马对付他们的中等马，用您的中等马对付他们的下等马。”三场比赛结束后，田忌一场败而两场胜，最终赢得千金赌注。因此田忌把孙膑推荐给齐威王。齐威王向他请教兵法，并封他为军师。这个故事给我们的启示有","choices":[{"id":"A","text":"任何事物的内容都有一定的表现形式"},{"id":"B","text":"当形式适合内容时，对内容的发展起着积极的推动作用"},{"id":"C","text":"形式的变化对内容的发展起着决定性的作用"},{"id":"D","text":"可以利用、改造和创造必要的形式为内容服务"}],"answer":["A","B","D"],"analysis":{"point":"本题考查内容与形式的关系。“田忌赛马”的故事体现的是内容与形式的辩证关系。上、中、下三等马是内容，而它们按什么顺序出场、按什么结构编排，则是形式。任何事物的内容都有一定的表现形式，内容是构成事物的一切要素的总和，是事物存在的基础；形式是把诸要素统一起来的结构或表现内容的方式。选项A正确。当形式适合内容时，对内容的发展起着积极的推动作用；当形式不适合内容时，对内容的发展起着消极的阻碍作用。选项B正确。可以根据内容的需要决定形式的取舍、改造和创新，利用和创造必要的形式，发挥形式的积极作用为内容服务。选项D正确。因此，选项A、B、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"说法错误，形式的变化可以影响内容的发展，但不能决定其发展。辩证法告诉我们，内容决定形式，形式反作用于内容。故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-mayuan-test4-20","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试四","chapterKey":"综合测试四","n":20,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试四 第 20 题"},"stem":"平衡是事物发展的一种状态。小到体操中人在平衡木上的行走，杂技中的骑车走钢丝、独轮车表演，直升机在空中的悬停等，大到人类的生存、地球的运转、天体的运行等，都是保持平衡的一种状态。世间的万事万物，之所以能不停地运动、发展、前进，一个重要原因就在于保持了平衡。要使“平衡”成为人们的“大智慧”，就要","choices":[{"id":"A","text":"精确把握事物的度"},{"id":"B","text":"准确掌握辩证否定的方式和方向"},{"id":"C","text":"善于协调事物内部各种因素的相互关系"},{"id":"D","text":"全面理解绝对运动和相对静止的辩证关系"}],"answer":["A","C","D"],"analysis":{"point":"本题是一道多考点综合性考题。本题以“平衡”为切入点，主要考查质、量、度以及物质运动的相关理论。“平衡”要精确把握事物的度，善于协调事物内部各种因素的相互关系，全面理解绝对运动和相对静止的辩证关系。因此，选项A、C、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"“准确掌握辩证否定的方式和方向”表述正确，但与本题所强调的“平衡”无关，“平衡”的关键在于度，而不是方式和方向问题，故不选。","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-mayuan-test4-21","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试四","chapterKey":"综合测试四","n":21,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试四 第 21 题"},"stem":"恩格斯说：“单凭观察所得的经验，是决不能充分证明必然性的。这是如此正确，以致不能从太阳总是在早晨升起来判断它明天会再升起。”这句话表明","choices":[{"id":"A","text":"感性认识有待于上升为理性认识"},{"id":"B","text":"事物的必然性与感性认识无关"},{"id":"C","text":"对于认识事物来说，观察是没有用的"},{"id":"D","text":"感性认识是有局限性的"}],"answer":["A","D"],"analysis":{"point":"本题考查感性认识。每天都看到太阳升起，获得的是感性认识。通过大量感性认识或者经验的积累，并不能推导出它一定就是正确的，即认为太阳明天还会升起。这说明感性认识具有局限性，必须通过理性认识来把握它升起的规律和原因，才能得出事物的必然性。感性认识有待于上升为理性认识。因此，选项A、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"说法错误，虽然不能直接由感性认识得出事物的必然性，但也不能说二者之间是无关的，故不选。","C":"说法错误，对于认识事物来说，观察是必要的，我们认识新事物都是从观察开始的，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-mayuan-test4-22","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试四","chapterKey":"综合测试四","n":22,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试四 第 22 题"},"stem":"关于“世界上最小的不可分的物质是什么？”这一问题，古希腊哲学家德谟克利特认为是原子，后来出现的“粒子学说”推翻了“原子论”，而现在的科学研究表明“夸克”才是世界上最小的不可分的物质。这给我们的哲学启示有","choices":[{"id":"A","text":"真理所反映客观对象的正确程度是有限的"},{"id":"B","text":"无数相对真理之和构成了绝对真理"},{"id":"C","text":"人的思维最终能够认识无限发展的世界"},{"id":"D","text":"真理处在由绝对到相对的转化和发展中"}],"answer":["A","B","C"],"analysis":{"point":"本题考查真理的绝对性和相对性。真理是个发展过程，既是绝对的，又是相对的。真理的相对性有两个方面的含义：一是真理所反映的对象是有条件的、有限的；二是真理反映客观对象的正确程度也是有条件的、有限的。选项A正确。绝对真理和相对真理是相互联系、相互包含的。绝对之中有相对，绝对真理通过相对真理表现出来，无数相对真理的总和构成绝对真理。题干中，对“世界上最小的不可分的物质是什么？”问题的回答，曾经出现过“原子论”“粒子学说”“夸克论”，这些都只是一定历史阶段的“相对真理”，最终将迈向“绝对真理”。选项B正确。马克思主义坚持可知论，认为人类的思维，按其本性、能力和可能性来说，是能够认识无限发展的物质世界的，这就是思维的至上性，同时也承认人的认识能力在一定的阶段是具有局限性的。选项C正确。因此，选项A、B、C正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"表述错误，真理是由相对走向绝对的永无止境的过程，任何真理性的认识都是由相对真理向绝对真理转化过程中的一个环节。故不选。"}}},{"id":"advanced-mayuan-test4-23","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试四","chapterKey":"综合测试四","n":23,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试四 第 23 题"},"stem":"中华人民共和国的成立和社会主义改造的基本完成，意味着中国人民选择并成功走上了社会主义道路。从社会发展的历史选择性的角度看，中国人民走上社会主义道路，其原因在于","choices":[{"id":"A","text":"社会主义符合中国人民根本利益的要求"},{"id":"B","text":"人们可以自由选择社会制度并决定社会发展的方向"},{"id":"C","text":"中国人民在国际交往中受到俄国社会主义革命的历史启示"},{"id":"D","text":"中国共产党对历史必然性和本国国情的正确把握"}],"answer":["A","C","D"],"analysis":{"point":"本题考查社会历史发展与人的主体选择性的关系。人们在进行历史选择的时候，通常受以下因素的影响：第一，本民族的利益；第二，国际交往中的类似经验；第三，对历史必然性及本民族特点的把握程度。因此，选项A、C、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"说法错误，尽管在历史发展的过程中，人们可以发挥自己的主观能动性，在历史的可能性空间中进行选择，但是这种选择并不是完全自由的，它必须以尊重社会历史发展规律为前提。故不选。","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-mayuan-test4-24","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试四","chapterKey":"综合测试四","n":24,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试四 第 24 题"},"stem":"19世纪初，英国的土地贵族和资产阶级争夺统治的斗争，是英国全部政治斗争的中心。从1830年起，在英国和法国，工人阶级已被承认是争夺统治的第三个阶级。恩格斯说：“这三大阶级的斗争和它们的利益冲突是现代历史的动力，至少是这两个最先进国家的现代历史的动力。”这说明","choices":[{"id":"A","text":"阶级斗争的实质是资本家掌握了劳动资料而占有其他人的劳动"},{"id":"B","text":"阶级斗争从根本上影响社会形态的更替"},{"id":"C","text":"阶级斗争是阶级社会发展的直接动力"},{"id":"D","text":"阶级斗争是社会基本矛盾在阶级社会中的直接表现"}],"answer":["C","D"],"analysis":{"point":"本题考查阶级斗争在阶级社会发展中的作用。阶级斗争是社会基本矛盾在阶级社会中的直接表现，是阶级社会发展的直接动力。因此，选项C、D正确。","options":{"A":"表述错误，阶级对立的实质是社会上一部分人拥有生产资料因而占有另一部分人的劳动，故不选。","B":"社会基本矛盾从根本上影响和促进社会形态的变化和发展，阶级斗争是社会基本矛盾在阶级社会中的直接表现，即在阶级社会中，生产力和生产关系、经济基础和上层建筑的矛盾必然会通过阶级斗争表现出来。但是阶级斗争并不能直接代表社会基本矛盾，故不选。","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-mayuan-test4-25","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试四","chapterKey":"综合测试四","n":25,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试四 第 25 题"},"stem":"唯物史观主张人民群众是历史的创造者，并不是否定个人在社会历史中的作用，而是要具体地分析个人及其作用的性质、大小以及个人与群众的关系。下列说法正确的有","choices":[{"id":"A","text":"社会历史发展是无数个人合力作用的结果"},{"id":"B","text":"历史人物不能决定和改变历史发展的总进程和总方向"},{"id":"C","text":"历史人物的出现体现了必然与偶然的统一"},{"id":"D","text":"历史人物对推动历史的发展起着进步作用"}],"answer":["A","B","C"],"analysis":{"point":"本题考查历史人物的作用。在社会发展中，所有个人都起到一定的作用。这不仅是因为全部人类历史的第一个前提无疑是有生命的个人的存在，而且社会历史过程本身也正是人们总是通过每一个人追求他自己的、自觉期望的目的而创造自己的历史过程，社会历史发展是无数个人合力作用的结果。选项A正确。不管什么样的历史人物，在历史上发挥了什么样的作用，都要受到社会发展客观规律的制约，而不能决定和改变历史发展的总进程和总方向。选项B正确。任何历史人物的出现，特别是杰出的政治人物的出现，都体现了必然与偶然的统一。“时势造英雄”，杰出人物的出现具有必然性。杰出人物会因其智慧、性格因素对社会进程产生影响，但这些作用仅仅是历史进程中的偶然现象，只能成为社会发展的个别原因。他们凭借自己的才能，虽然也能使具体历史事件的外貌或某些后果发生变化，但终究不能改变历史发展的基本方向。选项C正确。因此，选项A、B、C正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"历史人物对历史事件有着深刻的影响，甚至有时能够决定个别历史事件的结局，从而导致历史发展发生这样或那样的重大变化。按其发挥作用的性质，有些历史人物起推动历史前进的进步作用，有些起阻碍历史前进的反动作用。因此，并非所有的历史人物都对推动历史发展起着进步作用。故不选。"}}},{"id":"advanced-mayuan-test4-26","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试四","chapterKey":"综合测试四","n":26,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试四 第 26 题"},"stem":"资本主义生产方式占统治地位的社会的财富，表现为“庞大的商品堆积”，单个商品表现为这种财富的元素形式。下列属于商品的是","choices":[{"id":"A","text":"中世纪农民为神父生产纳什一税的粮食"},{"id":"B","text":"自然界中的空气、阳光和水分"},{"id":"C","text":"被资本家雇佣的劳动力"},{"id":"D","text":"奴隶社会中用于交换铜制三脚架的公牛"}],"answer":["C","D"],"analysis":{"point":"本题考查商品的含义。商品是用来交换、能满足人的某种需要的劳动产品。选项C，在资本主义时代，劳动力成为一种特殊的商品；选项D，人们用于交换的公牛，属于劳动产品，也属于商品。因此，选项C、D正确。","options":{"A":"什一税是欧洲基督教会向居民征收的宗教捐税，属于宗教势力和封建势力对农民阶级的剥削和压迫。农民生产的粮食仅仅是交给了教会，却未通过交换取得任何商品，故纳什一税的粮食不属于商品。故不选。","B":"自然界中的空气、阳光和水分与人类劳动无关，不属于劳动产品，也不是商品。故不选。","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-mayuan-test4-27","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试四","chapterKey":"综合测试四","n":27,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试四 第 27 题"},"stem":"在商品经济条件下，在价格形式中，价格背离价值量，并不是这种形式的缺点。相反，却使这种形式成为这样一种生产方式的适当形式，在这种生产方式下，规则只能作为没有规则性的盲目起作用的平均数规律来为自己开辟道路。商品的价格与价值不符说明","choices":[{"id":"A","text":"价值规律不是在任何时候都起作用"},{"id":"B","text":"这种现象并不是偶然的、个别的，而是经常发生的"},{"id":"C","text":"从长期来看，价格的上涨部分与下跌部分可以相互抵消，在一定时期内商品的平均价格与价值相等"},{"id":"D","text":"从孤立的一次商品交换来看，商品价格可能高于或者低于价值"}],"answer":["B","C","D"],"analysis":{"point":"本题考查商品价格以及价值规律的表现形式。商品价值的货币表现就是价格。商品的价格与价值经常性的不一致，这看似与价值规律不符，但并不意味着违背了价值规律。从孤立的一次商品交换来看，商品价格可能高于或者低于价值，但从长期来看，价格的上涨部分与下跌部分可以相互抵消，在一定时期内商品的平均价格与价值是相等的，二者是趋于一致的。从不同商品各自的价格变化来看，商品价格无论怎样涨落，都是以各自的价值为基础的。因此，选项B、C、D正确。","options":{"A":"价值规律是商品经济的基本规律，只要有商品生产和商品交换，价值规律就必然起作用。故不选。","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-mayuan-test4-28","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试四","chapterKey":"综合测试四","n":28,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试四 第 28 题"},"stem":"资本循环经过了三个阶段，执行了三种职能，实现了价值增殖，最后回到原来出发点。下列关于资本循环的说法，正确的有","choices":[{"id":"A","text":"货币资本职能处在生产阶段"},{"id":"B","text":"商品资本职能是为了实现价值和剩余价值"},{"id":"C","text":"生产资本职能表面上生产商品实际上是在生产剩余价值"},{"id":"D","text":"产业资本循环要求资本三种职能形式在时间上继起"}],"answer":["B","C","D"],"analysis":{"point":"本题考查资本循环。资本循环的三个阶段及三种职能形式：第一个阶段是购买阶段，即资本家用货币资本购买劳动力和生产资料。在这一阶段，资本执行货币资本的职能，为剩余价值生产准备条件。第二个阶段是生产阶段，即生产包含剩余价值的商品。在这一阶段，资本执行生产资本的职能，发挥生产剩余价值的职能。第三个阶段是售卖阶段，即销售产品，实现价值与剩余价值。在这一阶段，资本执行商品资本的职能，发挥实现价值和剩余价值的职能。选项B、C正确。产业资本循环要保持连续性，必须具备：第一，产业资本的三种职能形式必须在空间上并存；第二，产业资本的三种职能形式必须在时间上继起。产业资本的三种职能形式及其并列存在和相继运行，是产业资本保证正常、连续、循环运动的必要条件。选项D正确。因此，选项B、C、D正确。","options":{"A":"表述错误，产业资本执行货币资本职能是在第一个阶段即购买阶段，购买劳动力和生产资料。生产资本的职能才是处在生产阶段，生产商品的剩余价值。故不选。","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-mayuan-test4-29","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试四","chapterKey":"综合测试四","n":29,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试四 第 29 题"},"stem":"苏联模式，指苏联在长期的社会主义实践中形成的制度、体制以及建设社会主义的方针、政策，采用高度集中的经济政治体制进行社会主义建设的模式。其关键要害在于树立个人崇拜，无情践踏社会主义的民主和法制等基本原则，以长官意志取代社会主义性质的民主集中制。这个模式形成于斯大林时期，并不断得到强化和固化，延续至20世纪80年代中期。下列关于苏联模式的表述正确的有","choices":[{"id":"A","text":"苏联模式严重束缚了企业和劳动者的积极性"},{"id":"B","text":"苏联模式是一条完全适合俄国国情的社会主义道路"},{"id":"C","text":"苏联模式曾经促进了社会主义制度的巩固和发展"},{"id":"D","text":"苏联模式是特定历史条件下的产物，是社会主义的唯一模式"}],"answer":["A","C"],"analysis":{"point":"本题考查苏联模式。苏联模式重点发展重工业，搞单一的公有制，完全排斥市场的作用，因此严重束缚了企业和劳动者的积极性。但不可否认，在特定的历史条件下，苏联模式曾促进了社会主义制度的巩固和发展。因此，选项A、C正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"苏联模式是在特定历史条件下发展而来的，并不“完全”适合当时俄国的国情，只是在“当时”特定历史条件下发展的一种特殊模式，故不选。","C":"（正确选项，分析见“解题思路”）","D":"苏联模式是特定历史条件下的产物，并不是社会主义的唯一模式，故不选。"}}},{"id":"advanced-mayuan-test4-30","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试四","chapterKey":"综合测试四","n":30,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试四 第 30 题"},"stem":"马克思、恩格斯在《共产党宣言》中明确提出：“资产阶级的灭亡和无产阶级的胜利是同样不可避免的。”“资本主义必然灭亡，社会主义必然胜利”是科学社会主义的核心命题。这“两个必然”是他们研究人类历史发展，特别是资本主义历史发展所得出的基本结论。这一科学论断","choices":[{"id":"A","text":"在科学社会主义理论与实践巾具有首要和基础的地位"},{"id":"B","text":"是共产主义理想信念的核心要义"},{"id":"C","text":"是马克思主义追求的根本价值目标"},{"id":"D","text":"揭示了人类社会从资本主义向社会主义转变的历史必然性"}],"answer":["A","B","D"],"analysis":{"point":"本题考查“两个必然”。“两个必然”科学论断深刻揭示了人类社会从资本主义向社会主义转变的历史必然性，在科学社会主义理论与实践中具有首要和基础的地位，是共产主义理想信念的核心要义。因此，选项A、B、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"实现人的自由而全面的发展，是马克思主义追求的根本价值目标，也是共产主义社会的根本特征，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-mayuan-test5-1","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试五","chapterKey":"综合测试五","n":1,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试五 第 1 题"},"stem":"马克思主义的产生具有深刻的社会根源、阶级基础和思想渊源。其创始人马克思1818年5月5日出生在德国特利尔城的一个律师家庭，恩格斯1820年11月28日出生在德国巴门市的一个工厂主家庭，他们放弃了舒适安逸的生活，毅然选择了充满荆棘坎坷的革命道路，创立了科学社会主义。马克思、恩格斯之所以能够创立科学社会主义，主要是因为","choices":[{"id":"A","text":"他们拥有优良的家庭背景和教育经历"},{"id":"B","text":"他们对时代有着超越常人的认知能力"},{"id":"C","text":"社会历史条件和个人努力的相互作用"},{"id":"D","text":"德国是当时最为发达的资本主义国家"}],"answer":["C"],"analysis":{"point":"本题考查科学社会主义创立的背景。马克思、恩格斯之所以能够创立科学社会主义，主要是因为社会历史条件和个人努力的相互作用。当时正值资本主义快速发展的时期，马克思、恩格斯在对资本主义制度的分析中，阐发对未来社会的愿景，创立了科学社会主义理论。因此，选项C正确。","options":{"A":"他们拥有优良的家庭背景、教育经历以及超越常人的认知能力，都不是创立科学社会主义的主要理由和依据。应该说，每一位伟大的思想家都有超越常人的认知能力，而马克思、恩格斯能够取得这些成就必定不只是因为认知能力超越常人。","B":"他们拥有优良的家庭背景、教育经历以及超越常人的认知能力，都不是创立科学社会主义的主要理由和依据。应该说，每一位伟大的思想家都有超越常人的认知能力，而马克思、恩格斯能够取得这些成就必定不只是因为认知能力超越常人。","C":"（正确选项，分析见“解题思路”）","D":"“德国是当时最为发达的资本主义国家”的说法缺乏依据，那个时期英国的实力也非常强大。"}}},{"id":"advanced-mayuan-test5-2","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试五","chapterKey":"综合测试五","n":2,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试五 第 2 题"},"stem":"1972年，物理学家约瑟夫·黑费勒（Joseph Hafele）设计了一个实验，把铯原子钟装进喷气式客机里进行环球飞行。这个实验证明，当飞机上的乘客回家时，他们要比其他同龄人年轻“一个微乎其微但可以测量的瞬间”。这说明，时间具有","choices":[{"id":"A","text":"客观性"},{"id":"B","text":"相对性"},{"id":"C","text":"有限性"},{"id":"D","text":"一维性"}],"answer":["B"],"analysis":{"point":"本题考查时间的特性，属于分析理解题。题干描述的案例表明，不同的运动主体在一定条件下出现了时间快慢的差异。马克思主义认为，物质运动总是在一定的时间和空间中进行的，没有离开物质运动的“纯粹”时间和空间，也没有离开时间和空间的物质运动。物质运动的时间和空间的客观实在性是绝对的，物质运动的时间和空间的具体特性是相对的。本题正是体现了在特殊环境下，时间所具有的相对性。因此，选项B正确。","options":{"A":"物质运动与时间和空间的不可分割证明了时间和空间的客观性。与题意不符，故不选。","B":"（正确选项，分析见“解题思路”）","C":"马克思主义认为，具体物质形态的时空是有限的，而整个物质世界的时空是无限的。与题意不符，故不选。","D":"时间是指物质运动的持续性、顺序性，特点是一维性，即时间一去不复返。与题意不符，故不选。"}}},{"id":"advanced-mayuan-test5-3","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试五","chapterKey":"综合测试五","n":3,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试五 第 3 题"},"stem":"“我国发展仍处于可以大有作为的重要战略机遇期，既面临难得的历史机遇，也面对诸多可以预见和难以预见的风险挑战。我们要增强机遇意识和忧患意识。”从唯物辩证法的角度看，把握有利于事物发展的机遇，就是正确处理","choices":[{"id":"A","text":"原因和结果的辩证关系"},{"id":"B","text":"现象和本质的辩证关系"},{"id":"C","text":"必然和偶然的辩证关系"},{"id":"D","text":"可能和现实的辩证关系"}],"answer":["C"],"analysis":{"point":"本题考查必然与偶然的关系。必然是指事物联系和发展过程中一定要发生的、确定不移的趋势。偶然是指事物联系和发展过程中不确定的趋势。必然与偶然是对立统一的关系。抓住本题关键词“机遇”，就可以判断出本题强调的是必然和偶然的辩证关系，因为“机遇”就是偶然。因此，选项C正确。","options":{"A":"题干主要强调的是必然与偶然的辩证关系，并未涉及原因与结果、现象与本质、可能与现实的辩证关系。与题意不符，故不选。","B":"题干主要强调的是必然与偶然的辩证关系，并未涉及原因与结果、现象与本质、可能与现实的辩证关系。与题意不符，故不选。","C":"（正确选项，分析见“解题思路”）","D":"题干主要强调的是必然与偶然的辩证关系，并未涉及原因与结果、现象与本质、可能与现实的辩证关系。与题意不符，故不选。"}}},{"id":"advanced-mayuan-test5-4","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试五","chapterKey":"综合测试五","n":4,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试五 第 4 题"},"stem":"“马者所以命形也；白者所以命色也。命色者非命形也，故曰白马非马。”从唯物辩证法的观点看，“白马非马”这一命题的错误在于","choices":[{"id":"A","text":"模糊了事物本质和现象之间的联系"},{"id":"B","text":"割裂了事物共性和个性之间的联系"},{"id":"C","text":"混淆了事物内容和形式之间的区别"},{"id":"D","text":"颠倒了事物形态和功能之间的关系"}],"answer":["B"],"analysis":{"point":"本题考查矛盾的普遍性和特殊性的辩证关系原理。“马”是所有马的共性，“白马”属于马的一种，因此是一种个别的马。认为“白马非马”，就是将事物共性和个性之间的联系割裂开了。因此，选项B正确。","options":{"A":"现象与本质是揭示客观事物的外在表现和内在联系的一对范畴。例如，资本家给工人发工资是现象，但本质是资本家剥削了工人。而白马与马绝不是这种关系，故不选。","B":"（正确选项，分析见“解题思路”）","C":"内容与形式是从构成要素和表现方式上反映事物的一对范畴。例如，生产力是社会生产的物质内容，生产关系则是社会生产的组织形式。而白马与马绝不是这种关系，故不选。","D":"形态与功能指的是事物本身的呈现与它所具备的作用之间的关系。例如，马的外形就是马的形态，但是马能负重奔跑，这就是马的功能。而白马并不是马的功能，它只是一种马而已，故不选。"}}},{"id":"advanced-mayuan-test5-5","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试五","chapterKey":"综合测试五","n":5,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试五 第 5 题"},"stem":"恩格斯说：“实际上，蔑视辩证法是不能不受惩罚的。对一切理论思维尽可以表示那么多的轻视，可是没有理论思维，的确无法使自然界中的两件事联系起来或者洞察二者之间的既有的联系。”这说明","choices":[{"id":"A","text":"规律是事物运动发展中的本质的、必然的、稳定的联系"},{"id":"B","text":"人们在客观规律面前是消极被动、无所作为的"},{"id":"C","text":"正确的理论思维能使人们增强驾驭规律的能力"},{"id":"D","text":"客观性是规律的根本特性"}],"answer":["C"],"analysis":{"point":"本题考查唯物辩证法。题干中的“可是没有理论思维，的确无法使自然界中的两件事联系起来或者洞察二者之间的既有的联系”，表明理论思维是十分重要的，能够洞察事物之间的联系。规律是事物运动发展中的本质的、必然的、稳定的联系，正确的理论思维能使人们增强驾驭规律的能力，错误的理论思维会走向真理的反面。因此，选项C正确。","options":{"A":"说法正确但与题意不符，题干主要强调的是理论思维，并没有涉及规律的含义。故不选。","B":"说法错误，人们在实践中，透过大量的外部现象，可以发现或认识客观规律，并利用这种认识指导实践，达到改造自然、改造社会、为社会谋福利的目的。所以人们在客观规律面前并不是消极被动、无所作为的。故不选。","C":"（正确选项，分析见“解题思路”）","D":"说法正确但与题意不符，题干主要强调的是理论思维，并没有涉及规律的客观性。故不选。"}}},{"id":"advanced-mayuan-test5-6","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试五","chapterKey":"综合测试五","n":6,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试五 第 6 题"},"stem":"自然规律和社会规律之间有一定的联系和区别。二者之间的联系主要表现在","choices":[{"id":"A","text":"自然规律和社会规律都具有不以人的意志为转移的客观性"},{"id":"B","text":"自然规律是作为一种盲目的、无意识的力量起作用的"},{"id":"C","text":"社会规律是通过抱有一定目的和意图的人的有意识的活动实现的"},{"id":"D","text":"在社会规律中存在着主客观的相互制约关系，而自然规律没有"}],"answer":["A"],"analysis":{"point":"本题考查自然规律与社会规律的联系。自然规律是自然现象固有的、本质的、必然的、稳定的联系。社会规律是通过人们的活动表现出来的社会生活过程诸现象之间的本质的、必然的、稳定的联系。自然规律和社会规律都具有不以人的意志为转移的客观性，人不能任意改变、创造或消灭规律。因此，选项A正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"自然规律是作为一种盲目的、无意识的力量起作用的，社会规律则是通过抱有一定目的和意图的人的有意识的活动实现的。这是二者的区别，并不是联系，故不选。","C":"自然规律是作为一种盲目的、无意识的力量起作用的，社会规律则是通过抱有一定目的和意图的人的有意识的活动实现的。这是二者的区别，并不是联系，故不选。","D":"在社会规律中既存在着客观制约主观的关系，又存在着主观制约客观的关系。而自然规律中没有主观的因素，所以不存在主客观的相互制约。这是二者的区别，并不是联系，故不选。"}}},{"id":"advanced-mayuan-test5-7","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试五","chapterKey":"综合测试五","n":7,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试五 第 7 题"},"stem":"陶行知先生有句名言：“行动生困难；困难生疑问；疑问生假设；假设生试验；试验生断语；断语又生了行动，如此演进于无穷。”这句话给我们的启示是","choices":[{"id":"A","text":"感性认识是认识的基础"},{"id":"B","text":"认识决定实践的产生和发展"},{"id":"C","text":"怀疑是认识发展的根本动力"},{"id":"D","text":"认识过程是反复性与无限性的统一"}],"answer":["D"],"analysis":{"point":"本题考查认识的发展过程，属于分析理解题。题干所表述的意思是，实践与认识的辩证运动，是一个由感性认识到理性认识，又由理性认识到实践的飞跃，是“实践—认识—再实践—再认识”循环往复以至无穷的辩证发展过程。因此，选项D正确。","options":{"A":"表述错误，实践是认识的基础，故不选。","B":"表述错误，实践决定认识的产生和发展，实践是认识发展的动力，故不选。","C":"表述错误，实践决定认识的产生和发展，实践是认识发展的动力，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-mayuan-test5-8","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试五","chapterKey":"综合测试五","n":8,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试五 第 8 题"},"stem":"列宁说：“在这里不要忘记：实践标准实质上决不能完全地证实或驳倒人类的任何表象。这个标准也是这样的‘不确定’，以便不让人的知识变成‘绝对’，同时它又是这样的确定，以便同唯心主义和不可知论的一切变种进行无情的斗争。”实践标准的不确定性是指","choices":[{"id":"A","text":"实践作为检验真理标准的条件性"},{"id":"B","text":"实践作为检验真理标准的唯一性"},{"id":"C","text":"实践作为检验真理标准的最终性"},{"id":"D","text":"实践作为检验真理标准的归根到底性"}],"answer":["A"],"analysis":{"point":"本题考查实践标准的不确定性。实践标准的不确定性即相对性，是指实践作为检验真理标准的条件性。因此，选项A正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"实践标准的确定性即绝对性，是指实践作为检验真理标准的唯一性、归根到底性、最终性。故不选。","C":"实践标准的确定性即绝对性，是指实践作为检验真理标准的唯一性、归根到底性、最终性。故不选。","D":"实践标准的确定性即绝对性，是指实践作为检验真理标准的唯一性、归根到底性、最终性。故不选。"}}},{"id":"advanced-mayuan-test5-9","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试五","chapterKey":"综合测试五","n":9,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试五 第 9 题"},"stem":"如果不进行施工建设，图纸上的建筑物永远只会存在于图纸中，而绝不会变成现实中的高楼大厦。从哲学的角度来看，是因为实践具有","choices":[{"id":"A","text":"社会历史性"},{"id":"B","text":"客观规律性"},{"id":"C","text":"自觉能动性"},{"id":"D","text":"客观实在性"}],"answer":["D"],"analysis":{"point":"本题考查实践的基本特征。实践的客观实在性是指“实践可以将头脑中的事物变成现实的事物”。题干中的“如果不进行施工建设，图纸上的建筑物永远只会存在于图纸中，而绝不会变成现实中的高楼大厦”，体现的就是实践具有客观实在性。因此，选项D正确。","options":{"A":"实践的社会历史性是指实践是在一定时间、地点、条件下的实践，并且随着时间、地点、条件的改变而改变，是不断变化发展的，因而是历史的。题干主要强调的是实践是引起客观世界变化的活动，并没有涉及实践的社会历史性，故不选。","B":"实践的基本特征是客观实在性、自觉能动性、社会历史性，并没有客观规律性，故不选。","C":"实践的自觉能动性是指实践是人有意识的活动，不是盲目的，这是人的实践与动物本能的区别。题干主要强调的是实践的客观实在性，并没有涉及实践的自觉能动性，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-mayuan-test5-10","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试五","chapterKey":"综合测试五","n":10,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试五 第 10 题"},"stem":"马克思说：“手推磨产生的是封建主的社会，蒸汽磨产生的是工业资本家的社会。”这意味着","choices":[{"id":"A","text":"有什么样的生产力就有什么样的生产关系"},{"id":"B","text":"生产关系是社会关系中最基本的关系"},{"id":"C","text":"生产关系不适应生产力的发展会起消极作用"},{"id":"D","text":"生产关系的总和构成了经济基础"}],"answer":["A"],"analysis":{"point":"本题考查生产力和生产关系。题干中“手推磨”代表了生产力水平较低，只能产生相应的“封建主的社会”即封建主义的生产关系；“蒸汽磨”代表了生产力水平较高，产生了相应的“工业资本家的社会”即资本主义的生产关系。因此，选项A正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"生产关系是人们在物质生产过程中形成的不以人的意志为转移的经济关系。生产关系是社会关系中最基本的关系。表述正确，但与题干无关，故不选。","C":"生产力决定生产关系，生产关系反作用于生产力。当生产关系适合生产力发展的客观要求时，它对生产力的发展起推动作用；当生产关系不适合生产力发展时，就会阻碍生产力的发展。表述正确，但与题干无关，故不选。","D":"经济基础是指由社会一定发展阶段的生产力所决定的生产关系的总和。表述正确，但与题干无关，故不选。"}}},{"id":"advanced-mayuan-test5-11","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试五","chapterKey":"综合测试五","n":11,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试五 第 11 题"},"stem":"1893年10月10日，恩格斯在给俄国友人尼·丹尼尔逊的一封信中指出：“像你们的民族那样伟大的民族，是经得起任何危机的。没有哪一次巨大的历史灾难不是以历史的进步为补偿的。”这句话表明","choices":[{"id":"A","text":"社会意识对社会存在具有能动的反作用"},{"id":"B","text":"危机是事物发展的内在动力"},{"id":"C","text":"灾难是历史发展道路呈现多样性的内在原因"},{"id":"D","text":"社会历史发展是前进性与曲折性的统一"}],"answer":["D"],"analysis":{"point":"本题考查社会历史发展，属于分析理解题。社会形态的更替，表现为历史发展的前进性与曲折性、顺序性与跨越性的统一。社会形态更替的前进性和顺序性主要指五种社会形态依次演进的基本趋势，其历史过程是一个“扬弃”的过程。但它并不否认历史发展的曲折性和跨越性。社会发展过程的曲折性是指社会前进过程中所出现的反复、停滞和倒退现象。曲折前进是历史发展的普遍规律。因此，选项D正确。","options":{"A":"题干没有涉及社会意识的内容，与题干无关，故不选。","B":"表述错误，马克思主义认为，矛盾是事物发展的内在动力，故不选。","C":"表述错误，灾难是历史发展道路呈现多样性的外在影响因素，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-mayuan-test5-12","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试五","chapterKey":"综合测试五","n":12,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试五 第 12 题"},"stem":"在商品经济时代，两种不同的商品可以按一定比例互相交换的原因在于它们","choices":[{"id":"A","text":"对人们有共同的效用"},{"id":"B","text":"有不同的使用价值"},{"id":"C","text":"都是具体劳动的产物"},{"id":"D","text":"在生产中都耗费了无差别的一般人类劳动"}],"answer":["D"],"analysis":{"point":"本题考查商品的价值。不同商品的使用价值在质上是不同的，不同质的东西在量上无法进行比较。不同的商品之所以能够互相交换，是因为它们在生产中都耗费了无差别的一般人类劳动，都包含价值。因此，选项D正确。","options":{"A":"效用是一个非常主观的概念，例如，一杯水对于不渴的人来说没有多大效用，但对于口渴的人来说就非常有效用，因此，效用不能成为商品交换的原因。故不选。","B":"不同的使用价值不具有可比性，一只羊到底能换几台电脑呢？如果只是从它的使用价值来看，难以确定这个比例。故不选。","C":"两种不同的商品都是具体劳动的产物，这个说法本身没有问题，不过这不是它们能够交换的原因。因为具体劳动创造商品的使用价值，而决定商品能够交换的是它的价值，正因为不同的商品具有同样性质的价值，所以它们才能交换。故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-mayuan-test5-13","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试五","chapterKey":"综合测试五","n":13,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试五 第 13 题"},"stem":"马克思在《资本论》等著作中，从自然属性和社会属性两个角度对生产性劳动进行了分析。从社会属性角度，认为劳动总是在一定的生产关系下进行的，在资本主义条件下，劳动是否是生产性的，取决于","choices":[{"id":"A","text":"劳动是生产物质产品还是提供服务"},{"id":"B","text":"劳动能否为资本家带来剩余价值"},{"id":"C","text":"劳动能否满足社会全体成员日益增长的物质和文化需要"},{"id":"D","text":"劳动是否同时具备自然属性和社会属性"}],"answer":["B"],"analysis":{"point":"本题考查在当代条件下深化对马克思劳动价值论的认识。马克思在《资本论》等著作中，从自然属性和社会属性两个角度对生产性劳动进行了分析。从自然属性角度，认为劳动是人与自然之间的过程，劳动产品是该过程的结果，劳动资料和劳动对象表现为生产资料，劳动本身则表现为生产劳动；从社会属性角度，认为劳动总是在一定的生产关系下进行的，在资本主义条件下，劳动是否是生产性的，并不取决于劳动是生产物质产品还是提供服务，而取决于劳动能否为资本家带来剩余价值，只有创造剩余价值的劳动才是生产性劳动。在社会主义市场经济条件下，生产资料所有制关系发生了变化，社会生产的根本目的也发生了变化，因此，对于社会主义市场经济条件下的生产性劳动也需要作出新的认识和界定。因此，选项B正确。","options":{"A":"不符合题意，故不选。","B":"（正确选项，分析见“解题思路”）","C":"不符合题意，故不选。","D":"不符合题意，故不选。"}}},{"id":"advanced-mayuan-test5-14","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试五","chapterKey":"综合测试五","n":14,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试五 第 14 题"},"stem":"剩余价值的生产是资本主义经济的绝对规律，资本家为了获得更多的剩余价值通常采取“绝对剩余价值生产”和“相对剩余价值生产”这两种方法。这两种方法都","choices":[{"id":"A","text":"延长了剩余劳动时间"},{"id":"B","text":"缩短了必要劳动时间"},{"id":"C","text":"伴随着生产商品所需的“社会必要劳动时间”的缩短"},{"id":"D","text":"是资本家追逐超额剩余价值的结果"}],"answer":["A"],"analysis":{"point":"本题考查绝对剩余价值生产和相对剩余价值生产。绝对剩余价值生产是指在必要劳动时间不变的条件下，由于延长工作日的长度而绝对延长剩余劳动时间生产剩余价值的方法。相对剩余价值生产是指在工作日长度不变的条件下，通过缩短必要劳动时间而相对延长剩余劳动时间生产剩余价值的方法。这两种方法都延长了剩余劳动时间。因此，选项A正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"注意区分“必要劳动时间”和“社会必要劳动时间”，这两个概念看起来很接近，但并非一个意思。必要劳动时间指的是工人创造自己劳动力价值所需要的时间。社会必要劳动时间是指在现有的社会正常的生产条件下，在社会平均的劳动熟练程度和劳动强度下制造某种使用价值所需要的劳动时间。故不选。","C":"说法错误，生产相对剩余价值时社会必要劳动时间会缩短，但是生产绝对剩余价值时社会必要劳动时间不会缩短。故不选。","D":"资本家追逐超额剩余价值的结果是资本家普遍获得相对剩余价值，故不选。"}}},{"id":"advanced-mayuan-test5-15","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试五","chapterKey":"综合测试五","n":15,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试五 第 15 题"},"stem":"价值增殖过程是剩余价值的生产过程，这是资本主义生产过程的主要方面。资本主义价值增殖过程就是超过一定点而延长了的价值形成过程。这里的“一定点”指的是雇佣工人","choices":[{"id":"A","text":"创造新产品使用价值的时间"},{"id":"B","text":"转移劳动力价值的时间"},{"id":"C","text":"补偿劳动力自身价值的时间"},{"id":"D","text":"再生产生产资料价值的时间"}],"answer":["C"],"analysis":{"point":"本题考查资本主义生产过程的二重性。资本主义生产过程具有二重性：一方面是生产物质资料的劳动过程；另一方面是剩余价值的生产过程，即价值增殖过程。资本主义生产过程是劳动过程和价值增殖过程的统一。资本主义劳动过程是生产使用价值的过程。价值增殖过程，是超过劳动力价值的补偿这个一定点而延长了的价值形成过程。因此，选项C正确。","options":{"A":"新产品的使用价值，一部分是生产资料本身固有的，另一部分是工人的具体劳动为其新赋予的。但是题干中探讨的是“价值形成”的问题，而不是“使用价值”的来源问题。故不选。","B":"表述错误，劳动力价值不是像生产资料价值那样被转移到新商品中去的，而是由劳动力再创造出来的。故不选。","C":"（正确选项，分析见“解题思路”）","D":"表述错误，对于某个特定的企业来说，它的生产资料是由采购获得的，而不是自行生产出来的，商品才是最终生产出来的。故不选。"}}},{"id":"advanced-mayuan-test5-16","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试五","chapterKey":"综合测试五","n":16,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试五 第 16 题"},"stem":"某垄断企业投资生产商品，生产资料的价值为 15 万元，支付工人的工资为 5 万元，假设市场平均利润率为 10%，垄断利润为 10 万元。那么，该企业的垄断价格为","choices":[{"id":"A","text":"30 万元"},{"id":"B","text":"32 万元"},{"id":"C","text":"34 万元"},{"id":"D","text":"45 万元"}],"answer":["B"],"analysis":{"point":"本题考查垄断价格的计算。生产资料的价值为15万元，即c为15万元；支付工人的工资为5万元，即v为5万元。由此可知，成本价格=c+v=20（万元）。在利润率平均化的过程中，形成了社会的平均利润率，按照平均利润率计算和获得的利润，叫作平均利润。题干假设平均利润率为10%，那么平均利润=20×10%=2（万元），根据垄断价格=成本价格+平均利润+垄断利润，可得该企业的垄断价格=20+2+10=32（万元）。因此，选项B正确。","options":{"A":"与计算结果不符，故不选。","B":"（正确选项，分析见“解题思路”）","C":"与计算结果不符，故不选。","D":"与计算结果不符，故不选。"}}},{"id":"advanced-mayuan-test5-17","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试五","chapterKey":"综合测试五","n":17,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试五 第 17 题"},"stem":"人是追求意义的智慧生物，因此有自己的价值观。人工智能没有意义的概念，没有价值观，终究只能是人的工具，而不可能超越人类。人工智能之所以不能取代或者超越人类智能，是因为人工智能","choices":[{"id":"A","text":"不具备情感、信念、意志等人类意识形式"},{"id":"B","text":"不可能真正具备人类的社会属性"},{"id":"C","text":"难以完全具备理解自然语言真实意义的能力"},{"id":"D","text":"有比人脑更高级的运动形式"}],"answer":["A","B","C"],"analysis":{"point":"本题考查对人工智能的理解。人工智能不能取代或者超越人类智能的原因：第一，人类意识是知情意的统一体，而人工智能只是对人类的理性智能的模拟和扩展，不具备情感、信念、意志等人类意识形式。第二，社会性是人的意识所固有的本质属性，而人工智能不可能真正具备人类的社会属性。第三，人类的自然语言是思维的物质外壳和意识的现实形式，而人工智能难以完全具备理解自然语言真实意义的能力。第四，人工智能能够获得人类意识中可以化约为数字信号的内容，但人脑中总有许多东西是无法被化约的。因此，选项A、B、C正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"人工智能在有些方面的能力是超越人脑的，如运算速度和记忆储存量等，但是仍然有很多方面是不如人脑的，所以不能说人工智能比人脑更高级。故不选。"}}},{"id":"advanced-mayuan-test5-18","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试五","chapterKey":"综合测试五","n":18,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试五 第 18 题"},"stem":"赫拉克利特认为“人不能两次踏进同一条河流”，但他的学生反驳说“人一次也不能踏进同一条河流”。下列对这两种观点的理解，正确的有","choices":[{"id":"A","text":"前者是辩证法的观点"},{"id":"B","text":"后者是相对主义诡辩论"},{"id":"C","text":"前者肯定相对静止"},{"id":"D","text":"后者否定绝对运动"}],"answer":["A","B","C"],"analysis":{"point":"本题考查对运动和静止关系的理解。“人不能两次踏进同一条河流”体现的思想是物质是运动的，运动是物质的根本属性和存在方式，物质和运动是不可分割的。世界上的一切事物都处在运动变化之中，是辩证唯物主义思想。辩证唯物主义承认运动是绝对的，也承认相对静止。“人一次也不能踏进同一条河流”的思想过分地夸大了绝对运动，否认了相对静止的存在，把事物说成不可捉摸的东西，是相对主义诡辩论。因此，选项A、B、C正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"“人一次也不能踏进同一条河流”的思想否认相对静止的存在，但并没有否认绝对运动，反而夸大了绝对运动。故不选。"}}},{"id":"advanced-mayuan-test5-19","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试五","chapterKey":"综合测试五","n":19,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试五 第 19 题"},"stem":"在黑龙江伊春，天然林商业性采伐全面停止，良好的生态使这里成为旅游“打卡地”；在内蒙古鄂尔多斯，当地群众将库布其沙漠的漫漫黄沙变为高产良田，依靠种植、畜牧、光伏等产业增收致富；在江苏连云港，随着海域生态持续改善，渔获又丰富起来……新时代这十年，各地坚持在发展中保护、在保护中发展，实现百姓富、生态美的有机统一，绿水青山就是金山银山的理念在祖国大地上更加充分地展现出来。这一变化表明","choices":[{"id":"A","text":"实践是自然存在和社会存在区分与统一的基础"},{"id":"B","text":"人们可以改变规律作用的条件和形式"},{"id":"C","text":"生态环境已日益成为人类反思自身活动的重要前提"},{"id":"D","text":"尚未认识的外在自然规律对人的实践活动起着更为重要的作用"}],"answer":["A","B","C"],"analysis":{"point":"本题考查人与自然的关系。实践是使物质世界分化为自然界和人类社会的历史前提，又是使自然界和人类社会统一起来的现实基础。自然界是人类社会形成的自然基础，人类社会依赖于自然界，而人类社会的存在和发展又反过来影响并不断改变着自然界。规律是客观的，不能被改造和创造，但是人们可以利用规律，改变规律发生的条件和形式为自己的目的服务。生态环境已日益成为人类反思自身活动的重要前提。因此，选项A、B、C正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"过分夸大了尚未认识的自然规律的作用。"}}},{"id":"advanced-mayuan-test5-20","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试五","chapterKey":"综合测试五","n":20,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试五 第 20 题"},"stem":"2017年6月，我国科学家利用“墨子号”量子科学实验卫星在国际上率先成功实现了千公里级的星地双向量子纠缠分发。“量子纠缠”就是两个（或多个）粒子共同组成的量子状态，无论粒子之间相隔多远，测量其中一个粒子必然会影响其他粒子。“量子纠缠”现象虽然未被完全认知，但它仍然能够说明","choices":[{"id":"A","text":"物质世界联系的客观性和普遍性"},{"id":"B","text":"事物联系的主观性和偶然性"},{"id":"C","text":"事物联系的复杂性和多样性"},{"id":"D","text":"世界的真正统一性在于它的物质性"}],"answer":["A","C","D"],"analysis":{"point":"本题考查事物的普遍联系。“量子纠缠”现象体现了事物的普遍联系，联系具有普遍性、客观性、多样性、条件性。选项A、C正确。“量子纠缠”是物质世界的客观现象，不以人的意志为转移，体现了“世界统一于物质”的原理。选项D正确。因此，选项A、C、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"联系是客观的而不是主观的，是不以人的意志为转移的，故不选。","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-mayuan-test5-21","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试五","chapterKey":"综合测试五","n":21,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试五 第 21 题"},"stem":"解放战争时期，人民群众自发地推着小车支援前线。正如列宁在批判俄国经济主义“自发论”时提出来的“没有革命的理论，就不会有革命的运动”。这段话说明","choices":[{"id":"A","text":"社会意识对社会存在具有能动的反作用"},{"id":"B","text":"先进的革命理论一旦被群众掌握，就会促进社会的发展"},{"id":"C","text":"革命理论是革命运动的来源和决定力量"},{"id":"D","text":"革命理论可以不来自实践，但能指导实践"}],"answer":["A","B"],"analysis":{"point":"本题考查社会存在和社会意识的辩证关系。社会意识对社会存在具有能动的反作用。社会意识是一种巨大的精神力量，先进的、革命的、科学的社会意识对社会存在的发展具有巨大的推动作用；落后的、反动的、不科学的社会意识则阻碍社会存在的发展。题干中说“没有革命的理论，就不会有革命的运动”，体现了社会意识对社会存在具有能动的反作用。科学理论作为一种精神力量，能推动人们在实践中创新。正因为认识对实践具有能动的反作用，所以，先进的革命理论一旦被群众掌握，就会促进社会的发展。因此，选项A、B正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"说法错误，革命理论属于认识的范畴，革命运动属于实践的范畴，“认识是实践的来源和决定力量”不是马克思主义的观点，故不选。","D":"理论可以指导实践这一说法是正确的，但是理论一定来源于实践，所以该选项前半句表述错误，故不选。"}}},{"id":"advanced-mayuan-test5-22","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试五","chapterKey":"综合测试五","n":22,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试五 第 22 题"},"stem":"马克思在《〈黑格尔法哲学批判〉导言》中曾经指出：“批判的武器当然不能代替武器的批判，物质力量只能用物质力量来摧毁，但是理论一经群众掌握，也会变成物质力量。”这段话体现的哲学思想有","choices":[{"id":"A","text":"理论是巨大的物质力量"},{"id":"B","text":"理论对实践具有指导作用"},{"id":"C","text":"理论不能代替实践"},{"id":"D","text":"精神力量可以转化为物质力量"}],"answer":["B","C","D"],"analysis":{"point":"本题考查实践与理论（认识）的关系。“批判的武器当然不能代替武器的批判”中“批判的武器”指的是理论，“武器的批判”指的是实践，这句话的意思是理论不能代替实践。“理论一经群众掌握，也会变成物质力量”是说理论对实践具有指导作用，精神力量可以转化为物质力量。因此，选项B、C、D正确。","options":{"A":"说法错误，理论和实践紧密联系，但理论仍旧是意识而不是物质，而且理论只有运用于实践，才能转化为物质力量。故不选。","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-mayuan-test5-23","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试五","chapterKey":"综合测试五","n":23,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试五 第 23 题"},"stem":"2019年10月24日，中共中央政治局就区块链技术发展现状和趋势进行集体学习。习近平在主持学习时指出，我们要“提高运用和管理区块链技术能力，使区块链技术在建设网络强国、发展数字经济、助力经济社会发展等方面发挥更大作用”。有专家认为，基于区块链技术，人们可以构建在没有中介辅助下多个参与方之间的资产交易、价值传递的网络，通过建立执行智能合约，推动契约关系和规则的维护和履行，降低信用建立成本，营造良好市场环境。区块链技术所实现的人与人之间相互联系的延伸和变化，表明人们的现实社会关系","choices":[{"id":"A","text":"是一种单纯的经济和商业关系"},{"id":"B","text":"具有多样性和复杂性的特征"},{"id":"C","text":"归根到底受生产关系的制约"},{"id":"D","text":"是由信息技术构造的虚拟关系"}],"answer":["B","C"],"analysis":{"point":"本题考查生产关系。生产关系是各种社会关系中最基本的关系，人类现实社会关系归根到底是受社会生产关系制约的，是一种多样性和复杂性的关系。因此，选项B、C正确。","options":{"A":"说法错误，社会关系具有多样性，并非只是一种单纯的经济和商业关系。","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"说法错误，现实的社会关系具有客观性，并非虚拟的。"}}},{"id":"advanced-mayuan-test5-24","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试五","chapterKey":"综合测试五","n":24,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试五 第 24 题"},"stem":"“如果资本主义的灭亡是由科学保证了的，为什么还要费那么大的力气去为它安排葬礼呢？”这种观点的错误在于","choices":[{"id":"A","text":"抹杀了社会规律实现的特点"},{"id":"B","text":"否认革命在社会质变中的作用"},{"id":"C","text":"否认历史观上的决定论"},{"id":"D","text":"否认历史主体的能动作用"}],"answer":["A","B","D"],"analysis":{"point":"本题考查社会规律与历史主体能动作用的关系。题干的意思是资本主义灭亡既然是由规律决定的（科学总是反映规律的，故题干中用了“科学保证了的”），我们就不用花大力气为它安排葬礼了，让它自然灭亡就可以了。这种观点抹杀了社会规律实现的特点，否认革命在社会质变中的作用，否认历史主体的能动作用。社会规律是通过人们的有意识的活动表现出来的社会生活过程诸现象之间的本质的、必然的、稳定的联系。与作为一种盲目的、无意识的力量起作用的自然规律不同，社会规律是通过抱有一定目的和意图的人的有意识的活动实现的，是社会历史发展过程的客观规律与人的自觉活动的统一。在认识并遵循客观规律的基础上，人必须发挥主观能动性，才能把可能变成现实。因此，选项A、B、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"题干引文并没有否认历史观上的决定论，因为它承认“资本主义灭亡是由科学保证了的”，它否定的是历史主体的能动作用。不符合题意，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-mayuan-test5-25","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试五","chapterKey":"综合测试五","n":25,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试五 第 25 题"},"stem":"邓小平指出：“科学技术是第一生产力。”科学技术日益成为生产发展的决定性因素。科学技术之所以是第一生产力，是因为","choices":[{"id":"A","text":"科学技术引起了生产力中各要素的深刻变革"},{"id":"B","text":"科学技术应用于生产的组织管理，提高管理效率"},{"id":"C","text":"科学技术为劳动者所掌握，可以极大提高劳动生产率"},{"id":"D","text":"科学技术解决了生产力与生产关系之间的矛盾"}],"answer":["A","B","C"],"analysis":{"point":"本题考查科学技术。生产力中包含着科学技术，科学技术能够应用于生产过程，渗透在生产力诸要素之中而转化为实际生产能力。科学技术会引起劳动资料、劳动对象、劳动者素质的深刻变革和巨大进步；科学技术应用于生产的组织管理，能够大幅度提高管理效率；科学技术为劳动者所掌握，可以极大地提高劳动生产率。因此，选项A、B、C正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"社会基本矛盾包括生产力与生产关系、经济基础与上层建筑之间的矛盾，这一矛盾是贯穿社会发展过程始终的。社会基本矛盾的解决可采取阶级斗争、社会革命和改革等多种方式，正是在社会基本矛盾的表现形式和解决方式中，社会生活各个领域发生着深刻变化，使社会得到全面进步。科学技术不是解决社会基本矛盾的方式，故不选。"}}},{"id":"advanced-mayuan-test5-26","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试五","chapterKey":"综合测试五","n":26,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试五 第 26 题"},"stem":"马克思主义从必然性与偶然性的辩证统一中理解杰出人物的历史作用，认为","choices":[{"id":"A","text":"杰出人物能够改变历史发展的基本方向"},{"id":"B","text":"杰出人物的历史作用受到一定历史条件的制约"},{"id":"C","text":"杰出人物历史作用的形成和发挥与其顺应人民群众的意愿密不可分"},{"id":"D","text":"杰出人物会因其智慧、性格因素对社会进程发生影响"}],"answer":["B","C","D"],"analysis":{"point":"本题考查个人在社会历史中的作用。英雄人物或者杰出人物是人民群众的一员，他们与群众一起创造着历史，但他们的能力更强，影响力更大，甚至他们是一些重大历史事件的发起者与见证者，对历史发展有重要的影响作用。但是，他们仍要跟人民群众一起创造历史，他们创造历史的过程仍然要受社会历史规律的制约。因此，选项B、C、D正确。","options":{"A":"杰出人物对历史发展有重要的影响作用，但并不能决定和改变历史发展的基本方向和基本趋势，故不选。","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-mayuan-test5-27","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试五","chapterKey":"综合测试五","n":27,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试五 第 27 题"},"stem":"同一劳动在同一时间内，当全社会的劳动生产率提高时会使","choices":[{"id":"A","text":"单位商品的价值量降低"},{"id":"B","text":"该劳动者所生产商品的使用价值总量提高"},{"id":"C","text":"单位商品的价值量不变"},{"id":"D","text":"该劳动者所生产商品的总价值量提高"}],"answer":["A","B"],"analysis":{"point":"本题考查商品的价值量。当全社会的劳动生产率提高时，生产一种商品的社会必要劳动时间就相应地缩短了，因此，单位商品的价值量就降低了。但是对于某一个劳动者来说，他在同一时间内，生产的产品数量增加了，每个产品的使用价值量是不变的，因此，他生产商品的使用价值总量是提高的。因此，选项A、B正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"社会劳动生产率提高，单位商品的价值量是降低的，不是不变，故不选。","D":"对于某一个劳动者来说，他生产的单位商品的价值量降低了，但是由于社会劳动生产率提高，生产的商品数量也增加了。“产品数量增加的倍数”与“单位商品价值量降低的倍数”正好可以抵消，因此，商品的总价值量是不变的。故不选。"}}},{"id":"advanced-mayuan-test5-28","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试五","chapterKey":"综合测试五","n":28,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试五 第 28 题"},"stem":"利润转化为平均利润的过程，就是","choices":[{"id":"A","text":"资本家集团重新瓜分剩余价值的过程"},{"id":"B","text":"商品价值转化为生产价格的过程"},{"id":"C","text":"资本有机构成提高的过程"},{"id":"D","text":"资本在不同部门之间发生转移的过程"}],"answer":["A","B","D"],"analysis":{"point":"本题考查利润和平均利润。资本主义生产是为了获得利润，因此，不同部门之间如果利润率不同，资本家之间就会展开激烈的竞争，使资本从利润率低的部门转向利润率高的部门，从而导致利润率趋于平均化，不同部门的资本家按照等量资本获得等量利润的原则来瓜分剩余价值。选项D正确。随着利润转化为平均利润，商品价值就转化为生产价格，即商品的成本价格加平均利润。选项B正确。在利润率平均化的过程中，产业资本家获得产业利润，商业资本家获得商业利润，银行资本家获得银行利润，农业资本家获得农业利润。利润平均化规律反映在瓜分剩余价值上，资本家之间存在竞争和矛盾，但在加强对工人剥削以榨取更大量的剩余价值这一点上，资本家之间有着共同的阶级利益。所以，利润转化为平均利润的过程就是资本家集团重新瓜分剩余价值的过程。选项A正确。因此，选项A、B、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"按照平均利润率来计算和获得的利润，叫作平均利润。利润转化为平均利润的过程，是资本投资转移所带来的，与资本有机构成提高即技术提高无关。故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-mayuan-test5-29","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试五","chapterKey":"综合测试五","n":29,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试五 第 29 题"},"stem":"垄断资本向世界范围的扩展，会产生一系列的社会经济后果。下列关于后果的表述正确的有","choices":[{"id":"A","text":"资本输出国可能会通过垄断资本输出控制发展中国家的经济命脉"},{"id":"B","text":"对于资本输入国来说，垄断资本的扩张是一把“双刃剑”"},{"id":"C","text":"对于资本输入国来说，垄断资本的扩张只有积极作用，没有不利影响"},{"id":"D","text":"垄断资本的扩张，能够促进经济全球化的发展，从根本上说是有利于世界各国人民的"}],"answer":["A","B"],"analysis":{"point":"本题考查垄断资本向世界范围扩展的经济后果。垄断资本主义经济侵略的重要手段就是资本输出，即把资本家手中掌握和控制的大量资本输往国外，利用这些资本作武器，控制资本输入国的经济命脉，剥削、压迫这些国家的劳动人民，掠夺这些国家的自然资源和物质财富，最终用金融资本控制这些国家，形成金融资本的国际统治。对于资本输入国（主要是发展中国家）来说，资本输入对其经济和社会发展产生了一定的积极作用，但也带来了一定程度的不利影响，所以对于资本输入国来说，垄断资本的扩张是一把“双刃剑”。因此，选项A、B正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"说法错误，对于资本输入国（主要是发展中国家）来说，资本输入为其经济和社会发展带来了一定程度的不利影响，如付出了较大的经济代价和环境资源代价等。故不选。","D":"说法错误，垄断资本的扩张，能够促进经济全球化的发展，但从根本上说是为了维护资产阶级的利益，是为它们攫取高额垄断利润服务的，并不是有利于世界各国人民的。故不选。"}}},{"id":"advanced-mayuan-test5-30","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试五","chapterKey":"综合测试五","n":30,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试五 第 30 题"},"stem":"马克思、恩格斯创立科学社会主义学说的时候，是以高度社会化的资本主义大生产作为社会主义革命的物质前提。但是，后来社会主义革命并不是在生产社会化程度最高的资本主义国家首先实现的，而是首先在经济文化相对落后的国家取得胜利。这一事实","choices":[{"id":"A","text":"是由革命的客观形势和条件所决定的"},{"id":"B","text":"并没有违背生产关系一定要适合生产力状况的规律"},{"id":"C","text":"是一种反常现象"},{"id":"D","text":"是历史发展规律作用的结果"}],"answer":["A","B","D"],"analysis":{"point":"本题考查在实践中探索现实社会主义的发展规律。经济文化相对落后的国家可以先于发达资本主义国家进入社会主义，这是由革命的客观形势和条件所决定的。在经济文化相对落后的国家，社会矛盾特别尖锐，出现了很好的革命形势，以及革命的主观条件的成熟，使这些经济文化相对落后的国家率先进入社会主义。这并不违背生产关系一定要适合生产力状况的规律。总之，经济文化相对落后的国家率先进入社会主义，也是历史发展规律作用的结果。因此，选项A、B、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"说法错误，社会主义革命首先在经济文化相对落后的国家取得胜利并不是一种反常现象，其根本原因之一在于发达资本主义国家社会基本矛盾以及由此引发的其他社会矛盾空前激化，落后国家社会主义革命的胜利是发达资本主义国家通过战争向外转移危机和矛盾的必然结果。故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-mayuan-test6-1","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试六","chapterKey":"综合测试六","n":1,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试六 第 1 题"},"stem":"恩格斯曾说过：“我们不要过分陶醉于我们对自然界的胜利。对于每一次这样的胜利，自然界都报复了我们。每一次胜利，在第一步都确实取得了我们预期的结果，但是在第二步和第三步却有了完全不同的、出乎预料的影响，常常把第一个结果又取消了。美索不达米亚、希腊、小亚细亚以及其他地方的居民，为了得到耕地，把树都砍完了，但是他们做梦也想不到，这些地方今天竟因此成为荒芜不毛之地。”这段话说明","choices":[{"id":"A","text":"人与自然的和谐最终以恢复原始生态为归宿"},{"id":"B","text":"人们改造自然的行为都会遭到“自然界的报复”"},{"id":"C","text":"人在自然界面前总是处于被支配的地位"},{"id":"D","text":"人们应合理地调节人与自然之间的物质变换"}],"answer":["D"],"analysis":{"point":"本题考查人与自然的关系。题干中“美索不达米亚、希腊、小亚细亚以及其他地方的居民，为了得到耕地，把树都砍完了，但是他们做梦也想不到，这些地方今天竟因此成为荒芜不毛之地”，表明人们应合理地调节人与自然之间的物质变换。因此，选项D正确。","options":{"A":"人与自然共处于地球生物圈的统一体中，人类的繁衍与社会的发展离不开大自然，必须以大自然为依托，利用自然，改造自然。所以，“人与自然的和谐最终以恢复原始生态为归宿”的说法是错误的，故不选。","B":"说法错误，并不是所有改造自然的行为都会遭到“自然界的报复”。事实上，不断地改造自然正是人类社会存在和发展的重要特征，只要不是对自然进行“过分的、不合理的改造”，就不会遭到“自然界的报复”。故不选。","C":"说法错误，“人在自然界的面前总是处于被支配的地位”，这种说法否认了人的主观能动性。故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-mayuan-test6-2","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试六","chapterKey":"综合测试六","n":2,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试六 第 2 题"},"stem":"气温升高对人类社会到底意味着什么？除极端天气频发、两极冰川加速融化等环境问题外，大多数研究认为，在当前的气温水平下，假如气温进一步升高，全球整体经济生产力将有所下降。据法国央行研究，2060年全球GDP或因全球气温升高相对降低2.5%，到2100年这一相对降幅将扩大为12%。这表明","choices":[{"id":"A","text":"随着人类活动的发展，气温升高将是不可逆转的趋势"},{"id":"B","text":"自然界和人类社会是一个普遍联系的有机整体"},{"id":"C","text":"未来经济社会发展将主要取决于能否控制气温升高"},{"id":"D","text":"人类经济社会发展与自然环境的矛盾是不可调和的"}],"answer":["B"],"analysis":{"point":"本题考查人与自然的关系。自然界与人类社会是一个普遍联系的有机整体，人类活动影响自然环境，自然环境的变化也影响人类经济社会发展。因此，选项B正确。","options":{"A":"人的实践活动可以在一定程度上控制气温的变化，故不选。","B":"（正确选项，分析见“解题思路”）","C":"气温等自然条件不是社会发展的决定力量，故不选。","D":"通过人的努力，可以实现人与自然和谐共生，故不选。"}}},{"id":"advanced-mayuan-test6-3","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试六","chapterKey":"综合测试六","n":3,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试六 第 3 题"},"stem":"剪纸作为一种历史悠久的民间艺术形式，在我国大部分地区广为流传。民间艺人们按照自己的生活习俗以及审美特点进行创作，并融入自己的信念和情感，表达对生活的追求与向往，将美好的理想和心愿寄托在剪纸艺术之中。这段话反映的唯物辩证法思想是","choices":[{"id":"A","text":"必然和偶然的辩证统一"},{"id":"B","text":"内容和形式的辩证统一"},{"id":"C","text":"前进性和曲折性的辩证统一"},{"id":"D","text":"原因和结果的辩证统一"}],"answer":["B"],"analysis":{"point":"本题考查唯物辩证法的五对范畴。剪纸作为一种艺术形式，之所以广为流传，是因为它以各种形式反映人民大众的日常生活和美好理想、心愿。内容决定形式，形式反作用于内容。在生活实践中，既要重视内容，又要善于运用合适的形式促进内容的发展。因此，选项B正确。","options":{"A":"均属于唯物辩证法的范畴，但与题干无关，故不选。","B":"（正确选项，分析见“解题思路”）","C":"均属于唯物辩证法的范畴，但与题干无关，故不选。","D":"均属于唯物辩证法的范畴，但与题干无关，故不选。"}}},{"id":"advanced-mayuan-test6-4","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试六","chapterKey":"综合测试六","n":4,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试六 第 4 题"},"stem":"下列与“骏马能历险，耕田不如牛”蕴含的哲理相同的是","choices":[{"id":"A","text":"射人先射马，擒贼先擒王"},{"id":"B","text":"有无相生，难易相成，长短相形，高下相倾，音声相和，前后相随"},{"id":"C","text":"梅须逊雪三分白，雪却输梅一段香"},{"id":"D","text":"种瓜得瓜，种豆得豆"}],"answer":["C"],"analysis":{"point":"本题考查矛盾的特殊性。“骏马能历险，耕田不如牛”体现了矛盾的特殊性。梅与雪各具特色，有各自的比较优势，也体现了矛盾的特殊性。因此，选项C正确。","options":{"A":"突出的是“主次矛盾的原理”，故不选。","B":"突出的是“对立统一规律”，故不选。","C":"（正确选项，分析见“解题思路”）","D":"突出的是“因果关系”，故不选。"}}},{"id":"advanced-mayuan-test6-5","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试六","chapterKey":"综合测试六","n":5,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试六 第 5 题"},"stem":"主观辩证法是思维辩证法、逻辑辩证法。它与客观辩证法的关系是","choices":[{"id":"A","text":"反映与被反映的关系"},{"id":"B","text":"唯物主义与唯心主义的关系"},{"id":"C","text":"抽象与具体的关系"},{"id":"D","text":"唯心辩证法与唯物辩证法的关系"}],"answer":["A"],"analysis":{"point":"本题考查主观辩证法与客观辩证法的关系。客观辩证法是客观世界本身所固有的辩证运动和发展规律。主观辩证法是对客观辩证法的反映，是以概念、判断、推理等思维形式表现出来的思维发展的辩证法，可以概括地把主观辩证法称为概念辩证法。因此，选项A正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"主观辩证法与客观辩证法都是唯物主义的，故不选。","C":"辩证法都是抽象的，都是隐藏在事物内部的规律，故不选。","D":"主观辩证法与客观辩证法都是唯物的、正确的辩证法，而唯心辩证法是一种错误的辩证法，不能将主观辩证法等同于唯心辩证法，故不选。"}}},{"id":"advanced-mayuan-test6-6","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试六","chapterKey":"综合测试六","n":6,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试六 第 6 题"},"stem":"“追求真理比占有真理更宝贵。”德国诗人莱辛的这一著名诗句所蕴含的哲理是","choices":[{"id":"A","text":"认识经历着从感性认识到理性认识的发展"},{"id":"B","text":"认识的根本目的是透过现象认识本质"},{"id":"C","text":"改造世界比认识世界更重要"},{"id":"D","text":"认识不能停滞，而应该不断扩展和深化"}],"answer":["D"],"analysis":{"point":"本题考查对真理的理解。真理是人们对于客观事物及其规律的正确反映，是一种正确的认识。题干中“追求真理比占有真理更宝贵”说明认识是不断发展的，认识不能停滞，而应该不断扩展和深化。因此，选项D正确。","options":{"A":"说法正确但与题干无关，题干主要强调认识应该不断发展，不应该停滞，但没有涉及认识的发展过程，故不选。","B":"认识的根本目的是实践，而不是认识事物的本质，认识事物的本质是为了更好地实践，故不选。","C":"改造世界指的是人的实践活动，而认识世界指的是人的认识活动。我们可以说实践高于认识、实践先于认识、实践决定认识，但不能说实践比认识更重要。故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-mayuan-test6-7","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试六","chapterKey":"综合测试六","n":7,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试六 第 7 题"},"stem":"1845年，马克思在《关于费尔巴哈的提纲》中指出：“人的思维是否具有客观的真理性，这不是一个理论的问题，而是一个实践的问题。”实践之所以成为检验真理的唯一标准，是因为实践具有","choices":[{"id":"A","text":"客观实在性"},{"id":"B","text":"自觉能动性"},{"id":"C","text":"社会历史性"},{"id":"D","text":"主体目的性"}],"answer":["A"],"analysis":{"point":"本题考查实践的基本特征。实践是检验真理的唯一标准，这是由真理的本性和实践的特点所决定的。所谓检验认识的真理性，就是检验人的主观认识是否同客观对象相符合以及符合的程度。这种情况决定了检验真理的标准既不能在纯粹主观范围内去寻找，也不能在纯粹客观范围内去解决，而只能是把主观与客观联系起来加以比较对照，从而确定认识是否符合客观实在。实践是主观见之于客观的物质活动，是沟通主观和客观的桥梁，它具有客观实在性的特点和优点。只有实践才能把主观认识同客观实在联系起来加以对照，从而判明主观与客观是否相一致，判明认识是否具有真理性。因此，选项A正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"实践具有自觉能动性，强调的是人的活动是不同于动物的本能活动的有目的、有意识地改造世界的活动。与题意不符，故不选。","C":"实践的社会历史性，强调的是作为实践主体的人是社会的人，是处在一定社会关系中的人，人的实践活动要受一定社会历史条件的制约，并随着社会历史条件的变化而变化。与题意不符，故不选。","D":"实践的基本特征中没有这种说法，故不选。"}}},{"id":"advanced-mayuan-test6-8","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试六","chapterKey":"综合测试六","n":8,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试六 第 8 题"},"stem":"社会形态依次更替的过程和规律是客观的，但是社会发展的道路往往是有着多种选择的。下列符合历史发展规律的是","choices":[{"id":"A","text":"随机性选择的道路"},{"id":"B","text":"英雄人物选择的道路"},{"id":"C","text":"能够解放和发展生产力的道路"},{"id":"D","text":"多数人选择的道路"}],"answer":["C"],"analysis":{"point":"本题考查社会历史发展与人的主体选择性的关系。人类社会的发展是一个自然历史过程。实践是社会生活的本质和社会的存在方式。人们在物质资料的生产实践中，不断地提高并获得新的生产力；生产力的变化和发展，必然引起生产关系的变革和整个生产方式的变革，并最终引起上层建筑的变革，推动着人类社会由低级向高级的发展。因此，人们在创造历史的活动中，选择能够解放和发展生产力的道路，是与历史发展的规律相一致的。因此，选项C正确。","options":{"A":"“随机性选择的道路”不一定符合历史发展规律，故不选。","B":"“英雄人物选择的道路”不一定符合历史发展规律，孙中山算是英雄人物，但是其主张走资本主义道路。故不选。","C":"（正确选项，分析见“解题思路”）","D":"“多数人选择的道路”的命题，既没有表明“多数人”的性质，也没有表明所选择的是什么“道路”，这类命题在理论上是错误的，在实践上是有害的。故不选。"}}},{"id":"advanced-mayuan-test6-9","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试六","chapterKey":"综合测试六","n":9,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试六 第 9 题"},"stem":"货币所有者只有购买到劳动力这种特殊商品，货币才能转化为资本。这是因为","choices":[{"id":"A","text":"劳动力商品的价值大于其他一般商品"},{"id":"B","text":"劳动力商品既具有价值属性又具有使用价值属性"},{"id":"C","text":"劳动力自身的价值能够在消费过程中转移到新的商品中去"},{"id":"D","text":"劳动力商品在消费过程中能够创造出比自身价值更大的价值"}],"answer":["D"],"analysis":{"point":"本题考查货币转化为资本。资本是可以带来剩余价值的价值，这是资本的本质。劳动力商品在使用价值上有一个很大的特点，就是它的使用价值是价值的源泉，它在消费过程中能够创造新的价值，而且这个新的价值比劳动力本身的价值更大。货币所有者购买到这种特殊商品，能够获得剩余价值，货币也就转化为资本。因此，选项D正确。","options":{"A":"不论什么商品，它的价值量都是由社会必要劳动时间决定的，故不选。","B":"商品都具有使用价值和价值，具有使用价值和价值并不是劳动力这种特殊商品的独特之处，故不选。","C":"表述错误，劳动力自身的价值在消费过程中不是被转移到新产品中去，而是由工人的劳动再生产出来，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-mayuan-test6-10","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试六","chapterKey":"综合测试六","n":10,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试六 第 10 题"},"stem":"生产商品的时间有“个别劳动时间”和“社会必要劳动时间”之分，商品生产者要在市场竞争中处于有利地位，必须使自己生产商品所耗费的个别劳动时间","choices":[{"id":"A","text":"高于社会必要劳动时间"},{"id":"B","text":"低于社会必要劳动时间"},{"id":"C","text":"等于社会必要劳动时间"},{"id":"D","text":"低于最高个别劳动时间"}],"answer":["B"],"analysis":{"point":"本题考查商品生产者如何在市场竞争中处于有利地位。商品生产者要在竞争中处于有利地位，必须缩短个别劳动时间，使之低于社会必要劳动时间，只有这样才能获得更多的利润。因此，选项B正确。","options":{"A":"属于三种情况，并且生产者均不能在市场竞争中处于有利地位，脱颖而出。在选项A的情况下，生产者生产的速度太慢会被淘汰；在选项C的情况下，生产者可以生存，但是同别的生产者相比没有优势；在选项D的情况下，仅仅低于最高个别劳动时间，只能说明在竞争中可以战胜“最高个别劳动时间”的生产者，其他并无意义。故不选。","B":"（正确选项，分析见“解题思路”）","C":"属于三种情况，并且生产者均不能在市场竞争中处于有利地位，脱颖而出。在选项A的情况下，生产者生产的速度太慢会被淘汰；在选项C的情况下，生产者可以生存，但是同别的生产者相比没有优势；在选项D的情况下，仅仅低于最高个别劳动时间，只能说明在竞争中可以战胜“最高个别劳动时间”的生产者，其他并无意义。故不选。","D":"属于三种情况，并且生产者均不能在市场竞争中处于有利地位，脱颖而出。在选项A的情况下，生产者生产的速度太慢会被淘汰；在选项C的情况下，生产者可以生存，但是同别的生产者相比没有优势；在选项D的情况下，仅仅低于最高个别劳动时间，只能说明在竞争中可以战胜“最高个别劳动时间”的生产者，其他并无意义。故不选。"}}},{"id":"advanced-mayuan-test6-11","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试六","chapterKey":"综合测试六","n":11,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试六 第 11 题"},"stem":"1825年英国爆发了第一次全国性的经济危机，之后每隔十年左右，资本主义世界就周期性地爆发一次经济危机。正如马克思所指出的：“一切现实的危机的最终原因始终是：群众贫穷和群众的消费受到限制，而与此相对立，资本主义生产却竭力发展生产力，好像只有社会的绝对的消费能力才是生产力发展的界限。”这说明资本主义经济危机爆发的本质特征是","choices":[{"id":"A","text":"相对于劳动人民有支付能力的需求来说社会生产的商品的过剩"},{"id":"B","text":"相对于劳动人民的实际需要来说社会生产的商品的过剩"},{"id":"C","text":"资本主义的基本矛盾"},{"id":"D","text":"社会资本再生产的周期性"}],"answer":["A"],"analysis":{"point":"本题考查资本主义经济危机。资本主义发展到一定阶段，就会发生以生产过剩为基本特征（本质特征）的经济危机。生产过剩是资本主义经济危机的本质特征，但是这种过剩是相对过剩，即相对于劳动人民有支付能力的需求来说，社会生产的商品显得过剩。因此，选项A正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"与劳动人民的实际需要相比的过剩是绝对过剩。","C":"资本主义的基本矛盾是资本主义经济危机爆发的根本原因。","D":"资本主义经济危机周期性爆发的特点，使社会资本再生产也呈现周期性的特点。社会资本再生产的周期一般包括四个阶段，即危机、萧条、复苏和高涨。其中危机阶段是周期的基本阶段。"}}},{"id":"advanced-mayuan-test6-12","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试六","chapterKey":"综合测试六","n":12,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试六 第 12 题"},"stem":"资本主义基本矛盾“包含着现代的一切冲突的萌芽”，资本主义生产方式越是占统治地位，越是发展，“社会的生产和资本主义占有的不相容性，也必然越加鲜明地表现出来”。这表明","choices":[{"id":"A","text":"资本主义能够自己发展到社会主义"},{"id":"B","text":"资本主义的发展分为自由竞争和垄断两个阶段"},{"id":"C","text":"国家垄断资本主义是资本主义的最高形式"},{"id":"D","text":"资本主义的内在矛盾决定了资本主义必然被社会主义所代替"}],"answer":["D"],"analysis":{"point":"本题考查资本主义的基本矛盾。资本主义的内在矛盾决定了资本主义必然被社会主义所代替，表现在资本主义基本矛盾“包含着现代的一切冲突的萌芽”。因此，选项D正确。","options":{"A":"说法片面，资本主义最终一定会发展到社会主义，这是内因和外因共同作用的结果，仅仅夸大资本主义的内因是片面的，故不选。","B":"说法正确但与题意不符，题干主要强调的是资本主义的内在矛盾决定了资本主义必然被社会主义所代替，并没有涉及资本主义发展的两个阶段以及资本主义的最高形式，故不选。","C":"说法正确但与题意不符，题干主要强调的是资本主义的内在矛盾决定了资本主义必然被社会主义所代替，并没有涉及资本主义发展的两个阶段以及资本主义的最高形式，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-mayuan-test6-13","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试六","chapterKey":"综合测试六","n":13,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试六 第 13 题"},"stem":"在奥运会赛场上，我们经常可以看到运动员惊人的反应速度：羽毛球、乒乓球运动员需要在几百毫秒的时间内判断球的落点，并且快速移动到指定位置精确击球；自行车赛场上时常发生意外摔车事故，有些技术好的运动员可以迅速做出避险动作来进行躲避。奥运会赛场上的快速动作表明","choices":[{"id":"A","text":"特定条件下的运动可以脱离时间和空间的限制"},{"id":"B","text":"任何条件下的运动都是在时间和空间中的运动"},{"id":"C","text":"对于同一物体的运动，不同的人会有不同的认识和反应"},{"id":"D","text":"无论是快速运动还是其他运动，其主体都是物质"}],"answer":["B","C","D"],"analysis":{"point":"本题考查运动观、时空观以及意识的主观能动性。世界是物质的，物质是运动的。物质是一切运动变化和发展过程的承担者，世界上没有离开物质的运动，任何形式的运动都有它的物质载体。物质运动离不开时间和空间，物质运动总是在一定的时间和空间中进行的。认识带有主观性，不同主体对于同样的事物运动有不同的认识，进而产生不同的反应。因此，选项B、C、D正确。","options":{"A":"与正确选项B相矛盾，故不选。","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-mayuan-test6-14","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试六","chapterKey":"综合测试六","n":14,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试六 第 14 题"},"stem":"“物质的任何有限的存在方式，不论是太阳或星云，个别动物或动物种属，化学的化合或分解，都同样是暂时的，而且除永恒变化着的、永恒运动着的物质以及这一物质运动和变化所依据的规律外，再没有什么永恒的东西了。”这表明","choices":[{"id":"A","text":"世界上除了运动着的物质什么也没有"},{"id":"B","text":"世界是物质的，而物质是运动的"},{"id":"C","text":"物质世界的运动是绝对的"},{"id":"D","text":"世界的真正统一性在于它的物质性"}],"answer":["A","B","C","D"],"analysis":{"point":"本题考查物质运动。“除永恒变化着的、永恒运动着的物质以及这一物质运动和变化所依据的规律外，再没有什么永恒的东西了”，说明世界上除了运动着的物质什么也没有。“物质的任何有限的存在方式，不论是太阳或星云，个别动物或动物种属，化学的化合或分解，都同样是暂时的”，说明世界是物质的，而物质是运动的，物质世界的运动是绝对的。世界的物质统一性原理说明，世界上的一切事物和现象，归根到底都是物质的表现形态或物质的根本属性和存在方式。世界上的一切发展、变化和过程都是物质运动的具体表现，其原因在于物质世界自身。正如列宁所说的：“除了运动的物质以外，世界上什么也没有。”因此，选项A、B、C、D正确。\\n无干扰选项。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-mayuan-test6-15","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试六","chapterKey":"综合测试六","n":15,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试六 第 15 题"},"stem":"唐朝诗人张若虚《春江花月夜》中的“人生代代无穷已，江月年年望相似”两句诗蕴含着时间一维性的哲理。下列诗句中蕴含相同哲理的是","choices":[{"id":"A","text":"闲云潭影日悠悠，物换星移几度秋"},{"id":"B","text":"花开堪折直须折，莫待无花空折枝"},{"id":"C","text":"溪云初起日沉阁，山雨欲来风满楼"},{"id":"D","text":"黑发不知勤学早，白首方悔读书迟"}],"answer":["A","B","D"],"analysis":{"point":"本题考查时间的特点。“人生代代无穷已，江月年年望相似”体现了物是人非的变迁感。在哲学上体现了唯物论中时间的一维性。通过阅读判断，选项A、B、D均体现了时间的一维性。因此，选项A、B、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"体现了事物的普遍联系。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-mayuan-test6-16","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试六","chapterKey":"综合测试六","n":16,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试六 第 16 题"},"stem":"物联网是通过信息传感设备将各种物品与互联网连接起来，实现物品的自动识别、定位、跟踪、控制和信息的互联共享。近几年来，物联网技术开始越来越广泛地应用于经济和社会生活之中。这表明","choices":[{"id":"A","text":"人们可以根据自己的主观要求随意地创造事物间的联系"},{"id":"B","text":"联系具有普遍性，事物之间的联系形式是多样的"},{"id":"C","text":"人们可以根据事物固有的联系建立新的具体联系"},{"id":"D","text":"事物间的联系因具有“人化”的特点进而主观化"}],"answer":["B","C"],"analysis":{"point":"本题考查联系的观点。联系的普遍性是指世界上的任何事物都不能孤立地存在，都同周围的其他事物联系着；每一事物的各个要素也不能孤立地存在，都同其他要素联系着；整个世界就是一个相互联系的有机整体。而联系的形式是多样的，“物联网是通过信息传感设备将各种物品与互联网连接起来，实现物品的自动识别、定位、跟踪、控制和信息的互联共享”，表明了联系的普遍性，也表明了联系是客观的，但人们可以根据事物固有的联系建立新的具体联系。因此，选项B、C正确。","options":{"A":"人们确实可以根据已有的联系建立新的具体联系，但并不是根据自己的主观要求随意地创造事物间的联系。故不选。","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"联系是客观的，在任何情况下都不会被主观化，主观臆造联系是错误的。故不选。"}}},{"id":"advanced-mayuan-test6-17","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试六","chapterKey":"综合测试六","n":17,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试六 第 17 题"},"stem":"牛顿是一位伟大的科学家，他取得了巨大成就，走在时代前列，为全人类揭示了宇宙的本质和演化规律，但这些都离不开前人的智慧。所以他曾经说过：“假若我能比别人瞭望得略微远些，那是因为我站在巨人们的肩膀上。”这句话说明","choices":[{"id":"A","text":"认识具有历史继承性"},{"id":"B","text":"实践不是认识的唯一来源"},{"id":"C","text":"间接经验对认识发展有重要作用"},{"id":"D","text":"间接经验与直接经验无关"}],"answer":["A","C"],"analysis":{"point":"本题考查间接经验的作用。认识来源于实践并不否认学习间接经验的必要性和重要性。由于单个主体的生命和能力是有限的，不可能事事亲身实践，而且理论或认识本身也具有历史继承性，所以，主体可以也应该通过读书或传授等方式来获得间接经验，这是发展人类认识的必要途径。但是间接经验归根到底也是来源于前人或他人的实践，而且人们接受间接经验也要或多或少地以某种直接经验即实践为基础。只有把间接经验和直接经验结合起来，才能有比较完全的知识。因此，选项A、C正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"说法错误，马克思主义认为，实践是认识的唯一来源，无论是直接经验还是间接经验，都来自实践。故不选。","C":"（正确选项，分析见“解题思路”）","D":"直接经验和间接经验是“源”与“流”的关系，它们都来自实践，所以“间接经验与直接经验无关”这一说法是错误的。故不选。"}}},{"id":"advanced-mayuan-test6-18","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试六","chapterKey":"综合测试六","n":18,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试六 第 18 题"},"stem":"虚拟现实技术是一种运用计算机仿真系统创建多源信息融合的交互式三维动态实景以及动作仿真的技术，可以给使用者提供沉浸性、多感知性、交互性的互动体验。虚拟现实技术所构造的虚拟环境说明","choices":[{"id":"A","text":"信息是独立于物质和意识的第三种存在状态"},{"id":"B","text":"物质世界的存在形式具有多样性"},{"id":"C","text":"物质世界不再具有客观实在性"},{"id":"D","text":"人们可以通过实践创造出自然界原本不存在的现实状态"}],"answer":["B","D"],"analysis":{"point":"本题考查世界的物质统一性。“物质世界的存在形式具有多样性”表述正确，不以人的意志为转移的客观存在都属于物质，它可以是有形的，也可以是无形的，可以是由原子构成的，也可以不是。选项B正确。“人们可以通过实践创造出自然界原本不存在的现实状态”表述正确，例如，世界上本来没有飞机、轮船，人们通过实践把它们创造出来了。选项D正确。因此，选项B、D正确。","options":{"A":"“信息是独立于物质和意识的第三种存在状态”表述错误，不存在第三种状态，故不选。","B":"（正确选项，分析见“解题思路”）","C":"说法错误，物质的共同特性就是客观实在性，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-mayuan-test6-19","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试六","chapterKey":"综合测试六","n":19,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试六 第 19 题"},"stem":"孔子的一位学生在煮粥时，发现有异物掉进锅里去了。他正想把粥倒掉时，忽然想到，一粥一饭都来之不易，于是便把它吃了。刚巧孔子走进厨房，以为他在偷食，便教训了这位负责煮粥的同学。经过解释，大家恍然大悟。耳听为虚，然而眼见也未必为实。这说明","choices":[{"id":"A","text":"感性认识有待于进一步深化"},{"id":"B","text":"感性认识对获得真理毫无意义"},{"id":"C","text":"感性认识是认识的初级阶段"},{"id":"D","text":"经过了理性思考的认识才是正确的认识"}],"answer":["A","C"],"analysis":{"point":"本题考查感性认识与理性认识。感性认识是认识的初级阶段，具有不深刻的局限性。感性认识有待于发展和深化为理性认识。认识的任务，不是认识事物的表面和外部特征，而是达到对事物的质和规律性的认识。只有这样，才能正确地指导实践、变革现实、改造世界。孔子看到他的学生在喝粥，以为他偷食，后来才发现是自己错了，说明看事物不能只看表面，要深化认识。因此，选项A、C正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"说法错误，过分贬低感性认识，认识要经历感性认识和理性认识两个阶段，强调或者贬低任何一个阶段都是错误的，它们各有其重要性和作用。故不选。","C":"（正确选项，分析见“解题思路”）","D":"未经过理性思考的感性认识有可能是正确的，而经过理性思考的认识也有可能是错误的。故不选。"}}},{"id":"advanced-mayuan-test6-20","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试六","chapterKey":"综合测试六","n":20,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试六 第 20 题"},"stem":"马克思把主体理解为物质实体的人，他指出：“在黑格尔那里……人的实质本身仅仅被看作抽象的、能思维的实质，即自我意识……我们出发点是从事实际活动的人。”从满足人的需要出发的价值评价","choices":[{"id":"A","text":"是以主客体的价值关系为认识对象的"},{"id":"B","text":"要把客体属性和主体需要相统一"},{"id":"C","text":"依据主体的特点而转移"},{"id":"D","text":"依赖于主体的相关知识性认识"}],"answer":["A","B","C","D"],"analysis":{"point":"本题考查价值评价。价值评价是一种关于价值现象的评价性的认识活动，是主体在对客体属性、本质和规律认识的基础上，把自身需要的内在尺度运用于客体，对主体和客体价值关系进行评判。选项A正确。人们能否正确地作出价值判断，取决于人们所具有的相关知识性认识，包括对客体属性和主体需要两个方面的认识。所谓正确的价值评价，就是把客体属性与主体需要二者相统一。只有对主体和客体都有了正确的知识性认识，才能作出正确的价值评判。选项B、D正确。价值评价的结果与评价主体有直接联系，是依据主体的特点而转移的。主体的存在状态作为价值关系的构成要素必然会对评价结果产生直接影响，也使评价结果依据主体的具体特点而转移。选项C正确。因此，选项A、B、C、D正确。\\n无干扰选项。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-mayuan-test6-21","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试六","chapterKey":"综合测试六","n":21,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试六 第 21 题"},"stem":"“人类从必然王国进入自由王国”是指人们","choices":[{"id":"A","text":"摆脱了自然的奴役和社会的压迫"},{"id":"B","text":"摆脱了自然和社会规律的支配"},{"id":"C","text":"摆脱了盲目必然性的奴役"},{"id":"D","text":"获得了绝对完全的自由"}],"answer":["A","C"],"analysis":{"point":"本题考查对自由王国的理解。“从必然王国进入自由王国”是马克思对未来社会人的发展状态的预测。这里所说的“自由”指的是摆脱了自然的奴役和社会的压迫，摆脱了盲目必然性的奴役。但应注意的是摆脱奴役并不意味着摆脱“制约”，这两个词语的含义是不同的。无论什么时候，人类都不可能是“绝对自由”的，因为自由是以必然为前提和限度的。因此，选项A、C正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"无论什么样的社会形态，自然规律和社会规律的制约和支配都是存在的，只不过在自由王国，人们可以更好地认识和利用自然规律和社会规律，但仍然受其支配。故不选。","C":"（正确选项，分析见“解题思路”）","D":"无论什么时候，人类都不可能是“绝对自由”的，因为自由是以必然为前提和限度的。故不选。"}}},{"id":"advanced-mayuan-test6-22","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试六","chapterKey":"综合测试六","n":22,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试六 第 22 题"},"stem":"近年来，有些地区自然灾害频发，屡屡造成严重的经济社会损失，并威胁着人们的生命。下列关于社会发展中“自然地理环境”的作用的表述，正确的有","choices":[{"id":"A","text":"“自然地理环境”属于社会存在，是社会生活的物质方面"},{"id":"B","text":"在影响社会发展的几个因素中，“自然地理环境”比“人口因素”更重要"},{"id":"C","text":"“自然地理环境”已经日益成为社会发展的决定性因素"},{"id":"D","text":"“自然地理环境”可以从正反两方面对社会发展产生影响"}],"answer":["A","D"],"analysis":{"point":"本题考查社会存在的相关内容。社会存在是指社会物质生活条件，是社会生活的物质方面，主要包括物质生产方式、自然地理环境和人口因素。自然地理环境不只是人类历史活动的沉默背景和消极的旁观者，它本身就是人类历史创造活动的参与者，是这种活动的对象和材料。自然地理环境不仅为社会的发展提供有利的或不利的条件，它自身也在与人类活动的交互作用中不断地改变面貌。所以，“自然地理环境”可以从正反两方面对社会发展产生影响。因此，选项A、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"自然地理环境是人类物质生活的必要条件之一，但并不起决定作用。人口因素也是社会生活的必要条件之一，对社会发展起着促进或阻碍的作用，人口因素对社会发展不能起直接的决定作用。因此，并不能说“自然地理环境”比“人口因素”更重要。故不选。","C":"社会发展的决定性因素是物质生产方式，而不是自然地理环境，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-mayuan-test6-23","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试六","chapterKey":"综合测试六","n":23,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试六 第 23 题"},"stem":"马克思说：“不是意识决定生活，而是生活决定意识。”作为社会存在的“社会生活”对社会意识的决定性主要表现在","choices":[{"id":"A","text":"社会意识的内容来源于社会生活"},{"id":"B","text":"人们在社会物质交往过程中产生了社会意识"},{"id":"C","text":"社会生活发生变化时，会立刻在社会意识中反映出来"},{"id":"D","text":"社会意识对社会存在具有能动的反作用"}],"answer":["A","B"],"analysis":{"point":"本题考查社会存在和社会意识的辩证关系。社会存在决定社会意识，社会意识是社会存在的反映，有什么性质的社会存在，就有什么性质的社会意识与之相适应；由于生产力和生产关系矛盾运动的推动和社会存在的变化发展，社会意识便相应地变化发展。社会生活属于社会存在，所以社会意识的内容来源于社会生活，人们在社会物质交往过程中产生了社会意识。因此，选项A、B正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"关键词“立刻”二字是该选项的错误所在，社会生活变了，社会意识也会“或迟或早”地发生变化，而不是立刻，故不选。","D":"说法正确，但本题考查社会存在对社会意识的决定性方面。与题意不符，故不选。"}}},{"id":"advanced-mayuan-test6-24","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试六","chapterKey":"综合测试六","n":24,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试六 第 24 题"},"stem":"马克思、恩格斯指出，大工业“首次开创了世界历史，因为它使每个文明国家以及这些国家中的每一个人的需要的满足都依赖于整个世界，因为它消灭了以往自然形成的各国孤立的状态”，世界各个国家在经济上、政治上、文化上才真正有了密切的联系，人类历史才真正成为世界历史。这表明","choices":[{"id":"A","text":"生产关系是社会关系中最基本的关系"},{"id":"B","text":"劳动者在生产过程中的交往是生产关系的应有之义"},{"id":"C","text":"交往是世界历史发展的最终决定性因素"},{"id":"D","text":"普遍交往是世界历史的基本特征"}],"answer":["A","B","D"],"analysis":{"point":"本题考查生产关系与人类普遍交往。生产关系是人们在生产劳动中结成的物质关系，是全部社会关系中最基本的关系。选项A正确。“交往”属于生产关系的范畴，它是生产关系的应有之义。选项B正确。资本主义的发展推动历史进入世界历史阶段，普遍交往是世界历史的基本特征。选项D正确。因此，选项A、B、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"“交往”属于生产关系的范畴，它不是世界历史发展的最终决定性因素，生产力才是，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-mayuan-test6-25","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试六","chapterKey":"综合测试六","n":25,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试六 第 25 题"},"stem":"“无数相互交错的力量产生出一个总的结果，即历史事实，这个结果又可以看作一个作为整体的、不自觉地和不自主地起作用的力量的产物。所以以往的历史总是像一种自然过程一样地进行。”这说明","choices":[{"id":"A","text":"社会发展是由多种力量最终决定的"},{"id":"B","text":"社会发展规律是自发实现的"},{"id":"C","text":"社会发展并不是单一力量作用的结果"},{"id":"D","text":"社会发展像自然一样有自己的客观规律"}],"answer":["C","D"],"analysis":{"point":"本题考查社会发展规律。题干中说“无数相互交错的力量产生出一个总的结果”，这说明社会发展并不是单一力量作用的结果。“以往的历史总是像一种自然过程一样地进行”，体现的就是社会发展像自然一样有自己的客观规律。因此，选项C、D正确。","options":{"A":"说法错误，社会发展是由多种力量共同作用的结果，但是在这些力量中起决定性作用的只有一个，即“物质生产方式”，因此，不能说是由多种力量最终决定的。故不选。","B":"关键词“自发”二字是错误所在，自然规律是自发的，社会规律是自觉的，故不选。","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-mayuan-test6-26","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试六","chapterKey":"综合测试六","n":26,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试六 第 26 题"},"stem":"唯物史观在坚持人民群众是历史的创造者这一基本前提下，高度重视个人在历史上的作用。历史人物是一定历史事件的主要倡导者、组织领导者或思想理论、科学文化的重要代表人物。下列关于历史人物历史作用的认识正确的有","choices":[{"id":"A","text":"历史人物对历史发展的作用都是积极的"},{"id":"B","text":"历史人物会因其智慧、性格等因素对社会进程发生影响"},{"id":"C","text":"具有进步意义的历史人物往往能够首先发现或提出历史进程中新的历史任务"},{"id":"D","text":"历史人物不论发挥什么样的作用都不能决定和改变历史发展的总进程和总方向"}],"answer":["B","C","D"],"analysis":{"point":"本题考查个人在社会历史中的作用。虽然人民群众在创造历史过程中具有决定作用，但历史人物特别是杰出人物在社会发展过程中起着特殊的作用，主要表现在：历史人物是一定历史事件的发起者、当事者；历史人物是实现一定历史任务的组织者、领导者，他们能够在历史的重要节点上，认识把握历史的规律，认清历史发展趋势，提出新的历史任务。例如，邓小平在中国社会发展的转型期，提出改革开放的历史任务，思考中国特色社会主义的时代新问题。历史人物作为历史进程的影响者，可以加速或延缓历史任务的解决。因此，历史人物对历史发展的具体过程始终起着一定的作用，有时甚至对历史事件的进程和结局起着决定性的影响，但不能决定历史发展的基本趋势。因此，选项B、C、D正确。","options":{"A":"说法过于片面，历史人物对历史发展的影响有积极和消极之分。","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-mayuan-test6-27","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试六","chapterKey":"综合测试六","n":27,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试六 第 27 题"},"stem":"纺织厂的资本家购买的棉花属于","choices":[{"id":"A","text":"不变资本"},{"id":"B","text":"固定资本"},{"id":"C","text":"可变资本"},{"id":"D","text":"流动资本"}],"answer":["A","D"],"analysis":{"point":"本题考查资本的划分，属于分析理解题。不变资本是以生产资料形态存在的资本，它的价值通过工人的具体劳动转移到新产品中，不会发生增殖。流动资本是指生产资本中用于购买原料、燃料、辅助材料等劳动资料和用于购买劳动力的部分，它一次投入并一次转移到商品中。纺织厂的资本家购买的棉花，在生产中不会发生增殖，且一次投入并一次转移到商品中。因此，选项A、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"固定资本是指以厂房、机器、设备和工具等劳动资料的形式存在的生产资本。与题意不符，故不选。","C":"可变资本是用来购买劳动力的那部分资本，在生产过程中不是被转移到新产品中，而是由工人的劳动再生产出来。与题意不符，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-mayuan-test6-28","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试六","chapterKey":"综合测试六","n":28,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试六 第 28 题"},"stem":"资本主义的生产目的是追逐利润最大化。为了获得尽可能多的利润，分布在不同部门（行业）的资本家之间必然展开激烈的竞争，而竞争的结果必将导致利润率的平均化。利润率平均化的过程意味着","choices":[{"id":"A","text":"各部门资本家在加强对工人阶级的剥削上有着共同的阶级利益"},{"id":"B","text":"各部门内不同资本家的等量投资所得到的利润大体上均等"},{"id":"C","text":"某企业工人创造的剩余价值有被其他资本家侵占的可能"},{"id":"D","text":"不从事直接生产的银行资本家所获得的利润总是低于平均利润"}],"answer":["A","C"],"analysis":{"point":"本题考查利润率平均化。资本家剥削工人创造的剩余价值并对其进行分配，因此各部门的资本家在加强对工人阶级的剥削上，利益是一致的。选项A正确。资本家之间对获得的剩余价值进行分配，依据资本有机构成的情况、是否具有市场垄断力等因素，有些资本家可能会将自己获得的剩余价值让渡给其他资本家。选项C正确。因此，选项A、C正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"平均利润是不同部门或者不同行业的资本家竞争的结果，不是部门内不同资本家竞争的结果，说法错误，故不选。","C":"（正确选项，分析见“解题思路”）","D":"银行资本家的利润可能高于、低于或者等于平均利润，说法错误，故不选。"}}},{"id":"advanced-mayuan-test6-29","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试六","chapterKey":"综合测试六","n":29,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试六 第 29 题"},"stem":"与封建社会相比，资本主义的意识形态和政治制度作为上层建筑在战胜封建社会自给自足的小生产的生产方式，保护、促进和完善资本主义生产方式方面起着重要作用，从而推动了社会生产力的迅速发展，促进了社会进步。然而，资本主义的历史进步性并不能掩盖其自身的局限性。其局限性表现在","choices":[{"id":"A","text":"资本主义比以往社会创造了更大的物质文明"},{"id":"B","text":"资本主义的基本矛盾阻碍社会生产力的发展"},{"id":"C","text":"资本主义制度下财富占有两极分化，引发经济危机"},{"id":"D","text":"资产阶级支配和控制资本主义经济和政治的发展和运行，不断激化社会矛盾和冲突"}],"answer":["B","C","D"],"analysis":{"point":"本题考查资本主义自身的局限性。资本主义的历史进步性并不能掩盖其自身的局限性。其局限性表现在：第一，资本主义的基本矛盾阻碍社会生产力的发展；第二，资本主义制度下财富占有两极分化，引发经济危机；第三，资产阶级支配和控制资本主义经济和政治的发展和运行，不断激化社会矛盾和冲突。因此，选项B、C、D正确。","options":{"A":"属于资本主义的历史进步性的表现。","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-mayuan-test6-30","moduleId":"advanced","subjectId":"mayuan","chapter":"综合测试六","chapterKey":"综合测试六","n":30,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"马原 · 综合测试六 第 30 题"},"stem":"资本主义必然为社会主义所代替，并不意味着资本主义将在短期内自行消亡。资本主义向社会主义的过渡必然是一个复杂、长期的历史进程，其原因在于","choices":[{"id":"A","text":"资本主义社会具有一定的自我调节能力"},{"id":"B","text":"资本主义的发展具有不平衡性"},{"id":"C","text":"任何社会形态的存在都具有绝对稳定性"},{"id":"D","text":"当代资本主义的发展还显示出生产关系对生产力容纳的空间"}],"answer":["A","B","D"],"analysis":{"point":"本题考查“两个必然”和“两个决不会”。资本主义被社会主义取代是一个长期的过程，原因在于资本主义社会具有一定的自我调节能力，这在一定程度上缓解了资本主义的基本矛盾。选项A正确。资本主义发展的不平衡性决定了过渡的长期性，从世界范围看资本主义向社会主义过渡，必将是一个由个别国家逐步向更多国家扩展的相当长的历史过程。选项B正确。当今世界仍然存在资本主义国家，这一事实说明当代资本主义生产关系的发展还有可以容纳生产力发展的空间。选项D正确。因此，选项A、B、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"任何社会形态的存在都具有相对稳定性，而不是绝对稳定性，故排除。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-maozhongte-test1-1","moduleId":"advanced","subjectId":"maozhongte","chapter":"综合测试一","chapterKey":"综合测试一","n":1,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"毛中特 · 综合测试一 第 1 题"},"stem":"延安时期，为了解决党内存在的思想分歧、宗派主义等问题，我们党开展了大规模的整风运动，使全党达到了空前的团结和统一，为夺取抗战胜利和全国解放奠定了强大思想政治基础。从此，实事求是的思想路线在全党内确立起来。实事求是的思想路线是","choices":[{"id":"A","text":"我们党全部理论和实践的立足点"},{"id":"B","text":"我们党的基本思想方法、工作方法、领导方法"},{"id":"C","text":"我们党的生命线和根本工作路线"},{"id":"D","text":"中国共产党在中国革命中战胜敌人的三大法宝之一"}],"answer":["B"],"analysis":{"point":"本题考查实事求是的思想路线。习近平在纪念毛泽东诞辰120周年座谈会上的讲话中指出：“实事求是，是马克思主义的根本观点，是中国共产党人认识世界、改造世界的根本要求，是我们党的基本思想方法、工作方法、领导方法。不论过去、现在和将来，我们都要坚持一切从实际出发，理论联系实际，在实践中检验真理和发展真理。”因此，选项B正确。","options":{"A":"独立自主的探索和实践精神是我们党全部理论和实践的立足点，也是党和人民事业不断从胜利走向胜利的根本保证。故不选。","B":"（正确选项，分析见“解题思路”）","C":"群众路线是我们党的生命线和根本工作路线，是我们党永葆青春活力和战斗力的重要传家宝。故不选。","D":"毛泽东在《〈共产党人〉发刊词》一文中，总结了中国革命两次胜利和两次失败的经验教训，揭示了中国革命发展的客观规律，指出：“统一战线，武装斗争，党的建设，是中国共产党在中国革命中战胜敌人的三个法宝，三个主要的法宝。”“三大法宝”中并没有实事求是，故不选。"}}},{"id":"advanced-maozhongte-test1-2","moduleId":"advanced","subjectId":"maozhongte","chapter":"综合测试一","chapterKey":"综合测试一","n":2,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"毛中特 · 综合测试一 第 2 题"},"stem":"毛泽东认为中国革命必须分两个步骤。新民主主义革命是社会主义革命的必要准备，社会主义革命是新民主主义革命的必然趋势。只有认清民主革命和社会主义革命的区别，同时又认清二者的联系，才能正确地领导中国革命。中国革命分两步走从根源上说是因为","choices":[{"id":"A","text":"资产阶级的软弱性与妥协性"},{"id":"B","text":"新民主主义革命的性质是资产阶级民主革命"},{"id":"C","text":"近代中国半殖民地半封建的社会性质"},{"id":"D","text":"中国革命是最彻底的革命"}],"answer":["C"],"analysis":{"point":"本题考查中国革命分两步走的根源。根据近代中国半殖民地半封建的社会性质，毛泽东认为中国革命必须分两个步骤：第一步，反对帝国主义、封建主义和官僚资本主义，改变半殖民地半封建的社会性质，使中国成为一个独立的新民主主义国家；第二步，在新民主主义国家的基础上，使革命向前发展，通过社会主义革命，建立社会主义制度，使中国成为社会主义国家。因此，选项C正确。","options":{"A":"说法本身正确，但都不是中国革命分两步走的根本原因，故不选。","B":"说法本身正确，但都不是中国革命分两步走的根本原因，故不选。","C":"（正确选项，分析见“解题思路”）","D":"说法本身正确，但都不是中国革命分两步走的根本原因，故不选。"}}},{"id":"advanced-maozhongte-test1-3","moduleId":"advanced","subjectId":"maozhongte","chapter":"综合测试一","chapterKey":"综合测试一","n":3,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"毛中特 · 综合测试一 第 3 题"},"stem":"无论是“左”倾教条主义的“一次革命论”，还是右倾机会主义的“二次革命论”，它们的错误归根到底都是因为","choices":[{"id":"A","text":"中国共产党早期领导人的理论水平不高"},{"id":"B","text":"中国共产党面对的敌人实力过于强大"},{"id":"C","text":"中国共产党不善于将马克思列宁主义的基本原理同中国革命的实践相结合"},{"id":"D","text":"中国共产党放弃了对中国革命的领导权"}],"answer":["C"],"analysis":{"point":"本题考查中国共产党内反复出现“左”倾、右倾错误的原因。在党的历史上，“左”倾教条主义的“一次革命论”的错误在于，只看到了民主革命与社会主义革命的联系，而混淆了民主革命与社会主义革命的区别，主张把社会主义革命阶段的任务放在民主革命阶段来完成，在反帝反封建的同时，也反对民族资产阶级，使中国革命蒙受了重大损失。而右倾机会主义的“二次革命论”的错误在于，只看到了民主革命与社会主义革命的区别，而没有看到两个革命阶段的联系，主张在民主革命胜利后，建立一个资产阶级专政的资本主义国家，将来再进行社会主义革命，放弃党对民主革命的领导权，同样使中国革命遭受了严重损失。之所以会犯这两种错误，说到底是因为没能准确把握好中国的国情，没能将马克思列宁主义的基本原理同中国革命的实践结合起来。因此，选项C正确。","options":{"A":"以王明为代表的“左”倾教条主义和以陈独秀为代表的右倾机会主义，本质上都是主观主义错误的体现。王明、陈独秀都有留洋海外的经历，甚至能够背诵马克思列宁主义的经典著作，理论水平不可谓不高。之所以犯错误，恰恰是因为没能把理论与实践相结合。故不选。","B":"正是因为敌人过于强大，所以才不可能“毕其功于一役”。同理，面对强大的敌人，却把革命的领导权让给软弱的资产阶级，革命必然遭到挫折。故不选。","C":"（正确选项，分析见“解题思路”）","D":"右倾机会主义的“二次革命论”放弃了对革命的领导权，但“左”倾教条主义的“一次革命论”并没有放弃。故不选。"}}},{"id":"advanced-maozhongte-test1-4","moduleId":"advanced","subjectId":"maozhongte","chapter":"综合测试一","chapterKey":"综合测试一","n":4,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"毛中特 · 综合测试一 第 4 题"},"stem":"毛泽东建军思想是毛泽东思想和毛泽东军事思想的重要组成部分，它根植于中国共产党伟大的建军实践，它的形成与发展充分显示了前所未有的独创性。这一思想的核心是","choices":[{"id":"A","text":"全心全意为人民服务"},{"id":"B","text":"开展革命的政治工作"},{"id":"C","text":"坚持党对军队的绝对领导"},{"id":"D","text":"坚持正确的战略战术原则"}],"answer":["C"],"analysis":{"point":"本题考查党在新民主主义革命时期开展武装斗争的革命经验。总结党在新民主主义革命时期开展武装斗争的革命经验，建设人民军队，一要坚持党对军队的绝对领导，这是建设新型人民军队的根本原则，是保持人民军队无产阶级性质和建军宗旨的根本前提，也是毛泽东建军思想的核心；二要建设全心全意为人民服务的人民军队；三要开展革命的政治工作；四要坚持正确的战略战术原则。因此，选项C正确。","options":{"A":"均属于毛泽东建军思想的内容，但并不是建军思想的核心。","B":"均属于毛泽东建军思想的内容，但并不是建军思想的核心。","C":"（正确选项，分析见“解题思路”）","D":"均属于毛泽东建军思想的内容，但并不是建军思想的核心。"}}},{"id":"advanced-maozhongte-test1-5","moduleId":"advanced","subjectId":"maozhongte","chapter":"综合测试一","chapterKey":"综合测试一","n":5,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"毛中特 · 综合测试一 第 5 题"},"stem":"中国共产党之所以能够深入农村积蓄革命力量，建设农村革命根据地，最终实现农村包围城市并夺取政权，其根本原因是","choices":[{"id":"A","text":"全国革命形势的继续向前发展"},{"id":"B","text":"近代中国政治经济发展极端不平衡"},{"id":"C","text":"革命的群众基础好"},{"id":"D","text":"中国共产党领导的有力量及其政策的不错误"}],"answer":["B"],"analysis":{"point":"本题考查新民主主义革命道路形成的必然性。近代中国是一个政治、经济、文化发展极不平衡的半殖民地半封建大国。中国政治经济发展不平衡，没有统一的资本主义经济，自给自足的自然经济广泛存在，这就为在农村建立革命根据地提供了条件。由于中国是一个大国，革命力量大有回旋余地，而帝国主义国家的间接统治及相互间的矛盾和斗争，造成了军阀割据的局面和连绵不断的军阀混战，使红色政权获得存在和发展的缝隙。这是农村革命根据地能够在中国存在和发展的根本原因。因此，选项B正确。","options":{"A":"全国革命形势的继续向前发展，为在农村建设革命根据地提供了客观条件。故不选。","B":"（正确选项，分析见“解题思路”）","C":"近代中国的广大农村深受反动统治阶级的多重压迫和剥削，人民革命愿望强烈，加之经历过民主革命的洗礼，革命的群众基础好，但不是根本原因。故不选。","D":"中国共产党领导的有力量及其政策的不错误，为农村革命根据地建设和发展提供了重要的主观条件。故不选。"}}},{"id":"advanced-maozhongte-test1-6","moduleId":"advanced","subjectId":"maozhongte","chapter":"综合测试一","chapterKey":"综合测试一","n":6,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"毛中特 · 综合测试一 第 6 题"},"stem":"随着土地改革的基本完成，工人阶级和资产阶级的矛盾逐步成为国内的主要矛盾。而解决这一矛盾，必然要使中国社会实现","choices":[{"id":"A","text":"对官僚资本主义的消灭"},{"id":"B","text":"向新民主主义社会的转变"},{"id":"C","text":"工人阶级的领导"},{"id":"D","text":"对民族资产阶级的改造"}],"answer":["D"],"analysis":{"point":"本题考查新民主主义社会的性质和特点。从中华人民共和国成立到土地改革基本完成，这一时期，国内的主要矛盾是全国各族人民同帝国主义、封建主义和国民党残余势力之间的矛盾。1952年年底，随着土地改革的基本完成，工人阶级和资产阶级的矛盾逐步成为国内的主要矛盾。而解决这一矛盾，必然要使中国社会实现向社会主义的转变。对于工人阶级和社会主义革命来说，民族资产阶级作为一个剥削阶级是被消灭的对象；作为可以接受共产党和工人阶级领导的社会力量，民族资产阶级又是团结和改造的对象。因此，选项D正确。","options":{"A":"中华人民共和国成立初期已经基本实现了对官僚资本主义的消灭。故不选。","B":"1949年中华人民共和国的成立实现了向新民主主义社会的转变。故不选。","C":"1919年五四运动爆发后，中国革命已经有了工人阶级的领导，中华人民共和国成立后也不例外。故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-maozhongte-test1-7","moduleId":"advanced","subjectId":"maozhongte","chapter":"综合测试一","chapterKey":"综合测试一","n":7,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"毛中特 · 综合测试一 第 7 题"},"stem":"新中国的工业化是在苏联的影响下起步的。走中国工业化道路，是中国共产党初步探索我国社会主义建设道路的一个重要思想。当时所讲的工业化道路问题，主要是指","choices":[{"id":"A","text":"中央和地方的关系问题"},{"id":"B","text":"经济建设和国防建设的关系问题"},{"id":"C","text":"沿海工业和内地工业的关系问题"},{"id":"D","text":"重工业和轻工业、农业的发展关系问题"}],"answer":["D"],"analysis":{"point":"本题考查中国的工业化道路。中华人民共和国的工业化是在苏联的影响下起步的，加之当时我国的工业基础十分薄弱，因此党确定以工业化作为整个经济建设的主要任务。受苏联的影响，我国一度过多强调重工业和基础设施的发展，影响了农业和轻工业的发展，造成了一定程度的比例失调，这就促使党和毛泽东思考如何走中国工业化道路的问题。走中国工业化道路，是党探索我国社会主义建设道路的一个重要思想，强调正确处理重工业和轻工业、农业的关系，符合中国人口多、工业基础薄弱的实际，对于加快我国经济建设具有重要意义。因此，选项D正确。","options":{"A":"中央和地方的关系问题是《论十大关系》中所涉及的经济体制改革的问题。","B":"提及的两种关系都是开辟一条和苏联有所不同的中国工业化道路问题，但并非工业化道路问题的主要指向。","C":"提及的两种关系都是开辟一条和苏联有所不同的中国工业化道路问题，但并非工业化道路问题的主要指向。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-maozhongte-test1-8","moduleId":"advanced","subjectId":"maozhongte","chapter":"综合测试一","chapterKey":"综合测试一","n":8,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"毛中特 · 综合测试一 第 8 题"},"stem":"社会主义初级阶段是继新民主主义社会后的一个新的历史发展时期，它同新民主主义社会因为都存在多种经济成分而有某些相似之处，但它们之间在经济基础方面是有根本区别的。这表现为","choices":[{"id":"A","text":"社会主义公有制经济是否占据领导地位"},{"id":"B","text":"社会主义根本政治制度、基本政治制度是否确立"},{"id":"C","text":"公有制经济是否成为社会经济的主体"},{"id":"D","text":"中国共产党是否已经执政"}],"answer":["C"],"analysis":{"point":"本题考查社会主义初级阶段和新民主主义社会的区别。从经济基础方面看，社会主义初级阶段和新民主主义社会之间的根本区别在于：公有制经济是否成为社会经济的主体，从而整个经济社会生活是否牢牢建立在社会主义的经济基础之上。新民主主义社会，公有制经济虽然处于领导地位，但不是社会经济的主体，因此这个时期社会的阶级关系、主要矛盾也不同于社会主义初级阶段。因此，选项C正确。","options":{"A":"在新民主主义社会，社会主义性质的国营经济已占据领导地位。与题意不符，故不选。","B":"社会主义根本政治制度、基本政治制度是否确立是社会主义初级阶段和新民主主义社会在上层建筑方面的根本区别。与题意不符，故不选。","C":"（正确选项，分析见“解题思路”）","D":"在新民主主义社会和当前社会主义社会，中国共产党都处于执政地位。故不选。"}}},{"id":"advanced-maozhongte-test1-9","moduleId":"advanced","subjectId":"maozhongte","chapter":"综合测试一","chapterKey":"综合测试一","n":9,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"毛中特 · 综合测试一 第 9 题"},"stem":"1987 年党的十三大召开前夕，邓小平指出：“我们党的十三大要阐述中国社会主义是处在一个什么阶段，就是处在初级阶段，是初级阶段的社会主义。社会主义本身是共产主义的初级阶段，而我们中国又处在社会主义的初级阶段，就是不发达的阶段。”以上论述表明，社会主义初级阶段是","choices":[{"id":"A","text":"任何国家进入社会主义都会经历的起始阶段"},{"id":"B","text":"资本主义向社会主义过渡的阶段"},{"id":"C","text":"我国在生产力落后、商品经济不发达条件下建设社会主义必然要经历的特定阶段"},{"id":"D","text":"新民主主义向社会主义过渡的阶段"}],"answer":["C"],"analysis":{"point":"本题考查社会主义初级阶段的含义。党的十三大报告明确指出，社会主义初级阶段包括两层含义：第一，我国社会已经是社会主义社会；第二，我国的社会主义社会还处在初级阶段。社会主义初级阶段，不是泛指任何国家进入社会主义都会经历的起始阶段，而是特指我国在生产力落后、商品经济不发达条件下建设社会主义必然要经历的特定阶段。这个阶段，既不同于社会主义经济基础尚未确立的过渡时期，又不同于已经实现社会主义现代化的阶段。因此，选项C正确。","options":{"A":"社会主义初级阶段是生产力不发达国家进入社会主义的起始阶段。故不选。","B":"我国从未有独立发展资本主义的时期。故不选。","C":"（正确选项，分析见“解题思路”）","D":"新民主主义向社会主义过渡的阶段是指社会主义改造时期。故不选。"}}},{"id":"advanced-maozhongte-test1-10","moduleId":"advanced","subjectId":"maozhongte","chapter":"综合测试一","chapterKey":"综合测试一","n":10,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"毛中特 · 综合测试一 第 10 题"},"stem":"“什么是社会主义、怎样建设社会主义”是邓小平在领导改革开放的现代化建设这一新的革命过程中，不断提出和反复思考的首要的基本的理论问题。搞清楚这一问题的关键是","choices":[{"id":"A","text":"在认清基本国情的基础上进一步把握我国社会主义的发展阶段"},{"id":"B","text":"在正确分析我国社会主要矛盾的基础上进一步明确社会主义的根本任务"},{"id":"C","text":"在坚持我国社会主义基本制度的基础上进一步揭示社会主义的本质"},{"id":"D","text":"在总结我国社会主义历史经验的基础上进一步揭示社会主义社会发展的一般规律"}],"answer":["C"],"analysis":{"point":"本题考查邓小平理论首要的基本的理论问题。搞清楚“什么是社会主义、怎样建设社会主义”，关键是要在坚持社会主义基本制度的基础上进一步认清社会主义的本质。因此，选项C正确。","options":{"A":"与题干无关，故不选。","B":"与题干无关，故不选。","C":"（正确选项，分析见“解题思路”）","D":"与题干无关，故不选。"}}},{"id":"advanced-maozhongte-test1-11","moduleId":"advanced","subjectId":"maozhongte","chapter":"综合测试一","chapterKey":"综合测试一","n":11,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"毛中特 · 综合测试一 第 11 题"},"stem":"在当代中国，坚持一切从实际出发，就是要坚持以我国改革开放和现代化建设的实际问题、以我们正在做的事情为中心，着眼于马克思主义理论的运用，着眼于对实际问题的理论思考，着眼于新的实践和新的发展。我们讲一切从实际出发，其中最大的实际就是","choices":[{"id":"A","text":"到 2035 年基本实现社会主义现代化"},{"id":"B","text":"实现中华民族伟大复兴"},{"id":"C","text":"实现经济高质量发展"},{"id":"D","text":"我国仍处于并将长期处于社会主义初级阶段"}],"answer":["D"],"analysis":{"point":"本题考查我国最大的实际。我们讲一切从实际出发，其中最大的实际就是我国仍处于并将长期处于社会主义初级阶段。我们想问题、办事情、作决策，都必须从这个实际出发，而不能脱离这个实际。因此，选项D正确。","options":{"A":"属于“两个一百年”奋斗目标的规划。故不选。","B":"属于“两个一百年”奋斗目标的规划。故不选。","C":"属于中国经济的发展目标。故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-maozhongte-test1-12","moduleId":"advanced","subjectId":"maozhongte","chapter":"综合测试一","chapterKey":"综合测试一","n":12,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"毛中特 · 综合测试一 第 12 题"},"stem":"邓小平指出：“在改革中，我们始终坚持两条根本原则，一是以社会主义公有制经济为主体，一是共同富裕。”这两条根本原则揭示了中国特色社会主义与西方资本主义的本质区别，集中体现在","choices":[{"id":"A","text":"生产力与生产关系相互作用的机制不同"},{"id":"B","text":"生产资料所有制与发展目的不同"},{"id":"C","text":"国有企业与私营企业对经济社会发展的控制力不同"},{"id":"D","text":"公有制经济和非公有制经济的财富占比不同"}],"answer":["B"],"analysis":{"point":"本题考查中国特色社会主义的两条根本原则。按照马克思主义基本原理，生产资料所有制决定社会性质。没有社会主义公有制经济的主体地位，就不可能真正实行按劳分配，就不可能消灭剥削，消除两极分化，更不可能最终达到共同富裕。同样，共同富裕作为全体人民的奋斗目标，可以凝聚社会共识，团结力量，促进公有制经济的主体地位建立起广泛的社会基础。因此，邓小平提出的这两条原则是有机统一的，正是生产资料所有制与发展目的不同，从根本上体现着中国特色社会主义的本质特征，从而与资本主义区别开来。因此，选项B正确。","options":{"A":"生产力决定生产关系，生产关系对生产力的发展具有能动的反作用，二者相互作用的机制在任何一种社会形态中都是一致的，不能作为区别社会性质的标志。故不选。","B":"（正确选项，分析见“解题思路”）","C":"是杜撰选项，社会性质是由生产资料所有制决定的，与某种经济的控制力和财富占比无关。故不选。","D":"是杜撰选项，社会性质是由生产资料所有制决定的，与某种经济的控制力和财富占比无关。故不选。"}}},{"id":"advanced-maozhongte-test1-13","moduleId":"advanced","subjectId":"maozhongte","chapter":"综合测试一","chapterKey":"综合测试一","n":13,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"毛中特 · 综合测试一 第 13 题"},"stem":"1992年，邓小平在南方谈话中明确指出：“计划多一点还是市场多一点，不是社会主义与资本主义的本质区别。计划经济不等于社会主义，资本主义也有计划；市场经济不等于资本主义，社会主义也有市场。计划和市场都是经济手段。”这一精辟论述，从根本上","choices":[{"id":"A","text":"概括了党在社会主义初级阶段的奋斗目标、领导力量和依靠力量的基本方针"},{"id":"B","text":"解除了把计划经济和市场经济看作属于社会基本制度范畴的思想束缚"},{"id":"C","text":"摆脱了长期以来拘泥于具体模式而忽略社会主义本质的错误倾向"},{"id":"D","text":"确立了社会主义市场经济体制改革的目标"}],"answer":["B"],"analysis":{"point":"本题考查社会主义市场经济理论。这一精辟论述，从理论上突破了计划经济和市场经济是制度属性的观念，从根本上解除了把计划经济和市场经济看作属于社会基本制度范畴的思想束缚，标志着邓小平的社会主义市场经济理论的形成。因此，选项B正确。","options":{"A":"党的基本路线高度概括了党在社会主义初级阶段的奋斗目标、领导力量和依靠力量、基本途径和根本保证以及实现这一目标的基本方针。","B":"（正确选项，分析见“解题思路”）","C":"邓小平关于社会主义本质的概括，反映了人民的利益和时代的要求，廓清了不合乎时代进步和社会发展规律的模糊观念，摆脱了长期以来拘泥于具体模式而忽略社会主义本质的错误倾向。","D":"党的十四大确立了社会主义市场经济体制改革的目标。"}}},{"id":"advanced-maozhongte-test1-14","moduleId":"advanced","subjectId":"maozhongte","chapter":"综合测试一","chapterKey":"综合测试一","n":14,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"毛中特 · 综合测试一 第 14 题"},"stem":"邓小平指出：“改革的性质同过去的革命一样，也是为了扫除发展社会生产力的障碍，使中国摆脱贫穷落后的状态。从这个意义上说，改革也可以叫革命性的变革。”改革不是原有经济体制的细枝末节的修补，它的实质和目标是","choices":[{"id":"A","text":"消除社会主义社会的基本矛盾"},{"id":"B","text":"从根本上改变束缚生产力发展的经济体制"},{"id":"C","text":"一个阶级推翻另一个阶级"},{"id":"D","text":"让一部分人先富起来"}],"answer":["B"],"analysis":{"point":"本题考查社会主义改革开放理论。改革不是原有经济体制的细枝末节的修补，它的实质和目标是要从根本上改变束缚我国生产力发展的经济体制，建立充满生机和活力的社会主义新经济体制，同时相应地改革政治体制和其他方面的体制，以实现中国的社会主义现代化。因此，选项B正确。","options":{"A":"任何社会的社会基本矛盾都不能被消除，它伴随人类社会的始终。","B":"（正确选项，分析见“解题思路”）","C":"“一个阶级推翻另一个阶级”属于阶级革命，中国的改革并不是阶级革命的性质。","D":"“让一部分人先富起来”是改革开放初期我国在经济领域和民生领域的目标，并不是改革的实质。"}}},{"id":"advanced-maozhongte-test1-15","moduleId":"advanced","subjectId":"maozhongte","chapter":"综合测试一","chapterKey":"综合测试一","n":15,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"毛中特 · 综合测试一 第 15 题"},"stem":"邓小平曾说过：“一个党，一个国家，一个民族，如果一切从本本出发，思想僵化，迷信盛行，那它就不能前进，它的生机就停止了，就要亡党亡国。”这段话深刻阐明了","choices":[{"id":"A","text":"恢复实事求是思想路线的极端重要性"},{"id":"B","text":"坚持解放思想的极端重要性"},{"id":"C","text":"坚持与时俱进的极端重要性"},{"id":"D","text":"坚持求真务实的极端重要性"}],"answer":["B"],"analysis":{"point":"本题考查解放思想。邓小平特别强调解放思想的极端重要性。他指出：“一个党，一个国家，一个民族，如果一切从本本出发，思想僵化，迷信盛行，那它就不能前进，它的生机就停止了，就要亡党亡国。”他认为，在一切工作中要真正坚持实事求是，首先必须解放思想，只有思想解放了，才能正确地以马克思列宁主义、毛泽东思想为指导，解决过去遗留的问题和新出现的一系列问题。因此，选项B正确。","options":{"A":"反映了党的十一届三中全会重新恢复了毛泽东实事求是思想路线的史实。与题干无关，故不选。","B":"（正确选项，分析见“解题思路”）","C":"是江泽民对实事求是思想路线的发展。故不选。","D":"是胡锦涛对实事求是思想路线的发展。故不选。"}}},{"id":"advanced-maozhongte-test1-16","moduleId":"advanced","subjectId":"maozhongte","chapter":"综合测试一","chapterKey":"综合测试一","n":16,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"毛中特 · 综合测试一 第 16 题"},"stem":"恩格斯指出：“马克思的整个世界观不是教义，而是方法。它提供的不是现成的教条，而是进一步研究的出发点和供这种研究使用的方法。”这句话对我们正确对待马克思主义具有重要的指导意义，那就是","choices":[{"id":"A","text":"马克思主义作为科学真理，具有普遍的指导意义"},{"id":"B","text":"马克思主义的具体运用需要根据各国的具体情况"},{"id":"C","text":"要真正运用马克思主义来指导中国实际，必须实现马克思主义的中国化"},{"id":"D","text":"我们已经完成了马克思主义中国化的历史任务"}],"answer":["A","B","C"],"analysis":{"point":"本题考查马克思主义的指导意义。马克思主义作为科学真理，具有普遍的指导意义，但它的具体运用需要根据各国的具体情况。要真正运用马克思主义来指导中国革命、建设和改革，必须实现马克思主义的中国化。中国革命、建设和改革的实践也证明，马克思主义之所以能在中国发挥指导作用，就是因为它是科学、正确的方法，并且通过中国化为中国人民所掌握，从而满足了中国革命、建设和改革的需要。因此，选项A、B、C正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"不能说我们已经完成了马克思主义中国化的历史任务，马克思主义中国化是永无止境的发展过程。故不选。"}}},{"id":"advanced-maozhongte-test1-17","moduleId":"advanced","subjectId":"maozhongte","chapter":"综合测试一","chapterKey":"综合测试一","n":17,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"毛中特 · 综合测试一 第 17 题"},"stem":"习近平总书记在纪念毛泽东同志诞辰130周年座谈会上，深情回顾了毛泽东同志领导中国革命、建设的伟大实践，高度评价毛泽东同志为中华民族、中国人民建立的丰功伟绩。毛泽东同志的伟人表现在他带领人民","choices":[{"id":"A","text":"开创了马克思主义中国化的历史进程"},{"id":"B","text":"锻造了伟大光荣正确的中国共产党"},{"id":"C","text":"建立了人民当家作主的新中国"},{"id":"D","text":"开创了改革开放和社会主义现代化建设新局面"}],"answer":["A","B","C"],"analysis":{"point":"本题考查毛泽东的伟大功绩。毛泽东同志带领人民开创了马克思主义中国化的历史进程，锻造了伟大光荣正确的中国共产党，建立了人民当家作主的新中国，创建了先进的社会主义制度，缔造了战无不胜的新型人民军队，为中华民族、中国人民建立了不可磨灭的历史功勋，作出了光耀千秋的历史贡献。因此，选项A、B、C正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"不是毛泽东同志的伟大贡献，是邓小平同志带领党和人民开创了改革开放和社会主义现代化建设新局面。故不选。"}}},{"id":"advanced-maozhongte-test1-18","moduleId":"advanced","subjectId":"maozhongte","chapter":"综合测试一","chapterKey":"综合测试一","n":18,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"毛中特 · 综合测试一 第 18 题"},"stem":"“新民主主义革命，不是任何别的革命，它只能是和必须是无产阶级领导的，人民大众的，反对帝国主义、封建主义和官僚资本主义的革命。”毛泽东将“官僚资本主义”列为新民主主义革命对象的主要原因包括","choices":[{"id":"A","text":"它是资本主义"},{"id":"B","text":"它严重阻碍中国社会经济的发展"},{"id":"C","text":"它构成国民党反动统治的经济基础"},{"id":"D","text":"它具有买办性、封建性、妥协性"}],"answer":["B","C","D"],"analysis":{"point":"本题考查新民主主义革命的对象。新民主主义革命的性质是资产阶级民主革命，这就决定了革命的对象是帝国主义、封建主义和官僚资本主义。官僚资本主义之所以成为民主革命的对象，并非因为它是资本主义，而是因为这种资本主义同外国帝国主义、本国封建地主阶级紧密结合，是一种买办的、封建的国家垄断资本主义。官僚资本主义实际上成为以蒋介石为首的四大家族控制近代中国经济命脉的工具，构成了国民党反动统治的经济基础。官僚资本主义对广大劳动人民的残酷剥削和对民族工商业的巧取豪夺，严重束缚了中国社会生产力的发展，因此是中国革命的对象之一。因此，选项B、C、D正确。","options":{"A":"不是官僚资本主义被列为新民主主义革命对象的原因。故不选。","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-maozhongte-test1-19","moduleId":"advanced","subjectId":"maozhongte","chapter":"综合测试一","chapterKey":"综合测试一","n":19,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"毛中特 · 综合测试一 第 19 题"},"stem":"近代中国革命的性质不是无产阶级社会主义革命，而是资产阶级民主主义革命。这是因为","choices":[{"id":"A","text":"中国革命是为了终结半殖民地半封建的社会形态"},{"id":"B","text":"中国革命是反帝反封建的民族革命和民主革命"},{"id":"C","text":"中国革命不是一般地废除私有财产，而是一般地保护私有财产"},{"id":"D","text":"民族资产阶级始终在领导民主革命"}],"answer":["A","B","C"],"analysis":{"point":"本题考查中国革命的性质。毛泽东指出，既然中国还是一个封建经济占明显优势的半殖民地半封建社会，而现阶段的革命是为了终结这个半殖民地半封建的社会形态；既然中国革命的对象主要是帝国主义和封建主义势力，革命性质是为了推翻这两个主要敌人的民族革命和民主革命；既然这个革命还有资产阶级参加，它还曾领导过这个革命；既然这个革命的经济政策不是一般地废除私有财产，而是一般地保护私有财产，具体地说就是要把封建地主土地私有制变为农民土地所有制，为民族资本主义的发展扫清道路并保护之。所以，现阶段中国革命的性质，就不是无产阶级社会主义革命，而是资产阶级民主主义革命。因此，选项A、B、C正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"区别新旧两种不同范畴的民主主义革命的根本标志是革命的领导权是掌握在无产阶级手中还是掌握在资产阶级手中，新民主主义革命是由无产阶级领导的。故不选。"}}},{"id":"advanced-maozhongte-test1-20","moduleId":"advanced","subjectId":"maozhongte","chapter":"综合测试一","chapterKey":"综合测试一","n":20,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"毛中特 · 综合测试一 第 20 题"},"stem":"农村包围城市的革命新道路的开辟，无论在中国革命史上，还是在马克思列宁主义、毛泽东思想发展史上都具有十分重要的意义。因为农村包围城市的革命新道路","choices":[{"id":"A","text":"实现了中国革命重心由城市转向农村的历史性转变，保存和发展了革命力量"},{"id":"B","text":"揭示了中国革命发展的规律，指导中国革命取得了最后胜利"},{"id":"C","text":"丰富和发展了马克思主义关于暴力革命的学说，为半殖民地半封建国家的人民解放斗争提供了重要经验"},{"id":"D","text":"是马克思列宁主义普遍原理与中国革命具体实践相结合的光辉典范，是毛泽东思想形成的重要标志"}],"answer":["A","B","C","D"],"analysis":{"point":"本题考查中国革命新道路开辟的意义。农村包围城市这一革命新道路的开辟，无论在中国革命史上，还是在马克思列宁主义、毛泽东思想发展史上都具有十分重要的意义。第一，农村包围城市这一革命新道路的开辟，实现了中国革命重心由城市转向农村的历史性转变，保存和发展了革命力量。第二，农村包围城市、武装夺取政权的革命新道路，揭示了中国革命发展的规律，指导中国革命取得了最后胜利。第三，农村包围城市、武装夺取政权的革命新道路，丰富和发展了马克思主义关于暴力革命的学说，为半殖民地半封建国家的人民解放斗争提供了重要经验。第四，中国革命新道路的开辟，是马克思列宁主义普遍原理与中国革命具体实践相结合的光辉典范，是毛泽东思想形成的重要标志。因此，选项A、B、C、D正确。\\n无干扰选项。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-maozhongte-test1-21","moduleId":"advanced","subjectId":"maozhongte","chapter":"综合测试一","chapterKey":"综合测试一","n":21,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"毛中特 · 综合测试一 第 21 题"},"stem":"“有许多党员，在组织上入了党，思想上并没有完全入党，甚至完全没有入党。这种思想上没有入党的人，头脑里还装着许多剥削阶级的脏东西，根本不知道什么是无产阶级思想，什么是共产主义，什么是党。他们想：什么无产阶级思想，还不是那一套？他们哪里知道要得到这一套并不容易，有些人就是一辈子也没有共产党员的气味，只有离开党完事。”这段话表明","choices":[{"id":"A","text":"党的建设面临着严峻的形势和艰巨的任务"},{"id":"B","text":"“剥削阶级的脏东西”主要是指小资产阶级思想"},{"id":"C","text":"要着重从思想上建党，彻底改造各种非无产阶级思想"},{"id":"D","text":"需要加强党的思想建设"}],"answer":["A","C","D"],"analysis":{"point":"本题考查加强党的建设。加强党的建设，必须把思想建设始终放在首位，克服党内的非无产阶级思想。中国共产党要领导革命取得胜利，必须不断加强党的思想建设。其原因包括：第一，在半殖民地半封建的中国社会，无产阶级人数很少，农民和其他小资产阶级占人口的大多数，农民和小资产阶级出身的党员占多数；第二，长期处于农村游击战争的环境，党内无产阶级思想和非无产阶级思想之间的矛盾成为党内思想上的主要矛盾。因此，要建设一个广大群众性的、马克思主义的无产阶级政党，是一项伟大的工程，党的建设面临着严峻的形势和艰巨的任务。因此，选项A、C、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"表述错误，城市小资产阶级不是剥削阶级，而是被剥削阶级。题干中的剥削阶级主要是指地主阶级和民族资产阶级。故不选。","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-maozhongte-test1-22","moduleId":"advanced","subjectId":"maozhongte","chapter":"综合测试一","chapterKey":"综合测试一","n":22,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"毛中特 · 综合测试一 第 22 题"},"stem":"在半殖民地半封建的中国社会，诸多矛盾交织在一起，客观上为无产阶级及其政党利用这些矛盾建立和发展统一战线提供了可能性。这表现为","choices":[{"id":"A","text":"民族资产阶级可以参加统一战线"},{"id":"B","text":"官僚资产阶级绝对不可能参加统一战线"},{"id":"C","text":"一切爱国的、不愿受帝国主义奴役的人们都有参加统一战线的可能性"},{"id":"D","text":"地主阶级始终不可能参加统一战线"}],"answer":["A","C"],"analysis":{"point":"本题考查建立统一战线的可能性。近代中国社会最大的压迫是民族压迫，这就决定了无产阶级及其政党可以把一切爱国的、不愿受帝国主义奴役的人们团结在自己的周围。民族资产阶级深受帝国主义和封建主义的压迫，因而能够在一定时期和一定程度上参加反帝反封建的革命斗争。因此，选项A、C正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"当革命的锋芒主要是反对某一个帝国主义的时候，属于其他帝国主义阵营的官僚资产阶级集团也可能在一定程度上和一定时期内参加统一战线，地主阶级也有参加统一战线的可能性。故不选。","C":"（正确选项，分析见“解题思路”）","D":"当革命的锋芒主要是反对某一个帝国主义的时候，属于其他帝国主义阵营的官僚资产阶级集团也可能在一定程度上和一定时期内参加统一战线，地主阶级也有参加统一战线的可能性。故不选。"}}},{"id":"advanced-maozhongte-test1-23","moduleId":"advanced","subjectId":"maozhongte","chapter":"综合测试一","chapterKey":"综合测试一","n":23,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"毛中特 · 综合测试一 第 23 题"},"stem":"新民主主义社会不是一个独立的社会形态，而是由新民主主义转变到社会主义的过渡性的社会形态。其过渡性的表现包括","choices":[{"id":"A","text":"个体经济经由合作社经济向社会主义集体经济过渡"},{"id":"B","text":"私人资本主义经济由国家资本主义经济向社会主义国营经济过渡"},{"id":"C","text":"土地改革基本完成后必须解决工人阶级和资产阶级的矛盾"},{"id":"D","text":"国营经济成分不断扩大，掌握主要经济命脉，居于主体地位"}],"answer":["A","B","C"],"analysis":{"point":"本题考查新民主主义社会的性质和特点。新民主主义社会存在着五种经济成分：社会主义性质的国营经济、半社会主义性质的合作社经济、农民和手工业者的个体经济、私人资本主义经济和国家资本主义经济。半社会主义性质的合作社经济是个体经济向社会主义集体经济过渡的形式，国家资本主义经济是私人资本主义经济向社会主义国营经济过渡的形式。新民主主义社会要继续向前发展，就要不断扩大国营经济，同时逐步将资本主义经济和个体经济改造为社会主义经济，使社会主义经济逐步成为我国的经济基础。随着土地改革的基本完成，工人阶级和资产阶级的矛盾逐渐成为国内的主要矛盾。而解决这一矛盾，必然使中国社会实现向社会主义的转变。因此，选项A、B、C正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"说法错误，在新民主主义社会时期，国营经济等社会主义的因素，不论在经济上还是在政治上都已经居于领导地位，但还不能说是主体地位。故不选。"}}},{"id":"advanced-maozhongte-test1-24","moduleId":"advanced","subjectId":"maozhongte","chapter":"综合测试一","chapterKey":"综合测试一","n":24,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"毛中特 · 综合测试一 第 24 题"},"stem":"1956年年底，我国对农业、手工业和资本主义工商业的社会主义改造的基本完成，标志着社会主义基本制度在我国初步确立。其具体表现为","choices":[{"id":"A","text":"社会主义经济成分已占绝对优势"},{"id":"B","text":"广大劳动人民成为国家和社会的主人"},{"id":"C","text":"民族独立和人民解放的目标最终实现"},{"id":"D","text":"阶级剥削制度已经被基本消灭"}],"answer":["A","B","D"],"analysis":{"point":"本题考查社会主义改造基本完成的意义。1956年年底，我国对农业、手工业和资本主义工商业的社会主义改造的基本完成，使我国社会经济结构发生了根本变化，社会主义经济成分已占绝对优势，这标志着中国历史上长达数千年的阶级剥削制度的结束。广大劳动人民从此摆脱了被剥削被奴役的地位，成为掌握生产资料的国家和社会的主人以及掌握自己命运的主人。因此，选项A、B、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"民族独立和人民解放的目标是在1949年中华人民共和国成立时实现的，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-maozhongte-test1-25","moduleId":"advanced","subjectId":"maozhongte","chapter":"综合测试一","chapterKey":"综合测试一","n":25,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"毛中特 · 综合测试一 第 25 题"},"stem":"1956年4月，毛泽东在召集中央其他领导同志开会时就提出：“最重要的是要独立思考，把马列主义的基本原理同中国革命和建设的具体实际相结合。”为此，他先后在中央政治局扩大会议和最高国务会议上，作了《论十大关系》的报告。该报告","choices":[{"id":"A","text":"初步总结了我国社会主义建设的经验"},{"id":"B","text":"系统论述了社会主义社会矛盾的理论"},{"id":"C","text":"明确提出要以苏为鉴"},{"id":"D","text":"提出要独立自主地探索适合中国情况的社会主义建设道路"}],"answer":["A","C","D"],"analysis":{"point":"本题考查《论十大关系》。《论十大关系》的报告，初步总结了我国社会主义建设的经验，明确提出要以苏为鉴，独立自主地探索适合中国情况的社会主义建设道路。因此，选项A、C、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"毛泽东于1957年2月所作的《关于正确处理人民内部矛盾的问题》的报告，系统论述了社会主义社会矛盾的理论。不符合题意，故不选。","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-maozhongte-test1-26","moduleId":"advanced","subjectId":"maozhongte","chapter":"综合测试一","chapterKey":"综合测试一","n":26,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"毛中特 · 综合测试一 第 26 题"},"stem":"1987年召开的党的十三大标志着邓小平理论轮廓的形成，因为这次会议","choices":[{"id":"A","text":"第一次比较系统地论述了我国社会主义初级阶段理论"},{"id":"B","text":"明确概括和全面阐发了党的“一个中心、两个基本点”的基本路线"},{"id":"C","text":"第一次对中国特色社会主义理论的主要内容作了系统概括"},{"id":"D","text":"第一次提出了社会主义本质理论"}],"answer":["A","B","C"],"analysis":{"point":"本题考查中国特色社会主义理论体系的形成发展过程。1987年召开的党的十三大，第一次比较系统地论述了我国社会主义初级阶段理论，明确概括和全面阐发了党的“一个中心、两个基本点”的基本路线，从马克思主义哲学、政治经济学和科学社会主义等方面，第一次对中国特色社会主义理论的主要内容作了系统概括。因此，选项A、B、C正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"是在1992年邓小平南方谈话中提出的。"}}},{"id":"advanced-maozhongte-test1-27","moduleId":"advanced","subjectId":"maozhongte","chapter":"综合测试一","chapterKey":"综合测试一","n":27,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"毛中特 · 综合测试一 第 27 题"},"stem":"邓小平在认真总结国内外社会主义建设的经验教训，特别是在改革开放的实践经验的基础上，创造性地提出了社会主义本质理论。这一理论是对科学社会主义的重大发展，因为它","choices":[{"id":"A","text":"把我们对社会主义的认识提高到了一个新的科学水平"},{"id":"B","text":"明确了公有制的范围越大、程度越高，越有助于发展社会主义的认识"},{"id":"C","text":"摆脱了长期以来拘泥于具体模式而忽略社会主义本质的错误倾向"},{"id":"D","text":"进一步明确了建设社会主义的发展目标和根本目的"}],"answer":["A","C","D"],"analysis":{"point":"本题考查社会主义本质理论对科学社会主义的重大发展。社会主义本质理论是对科学社会主义的重大发展，把我们对社会主义的认识提高到了一个新的科学水平。这一理论把手段和目的统一起来，廓清了不合时代潮流和社会发展规律的模糊观念，摆脱了长期以来拘泥于具体模式而忽略社会主义本质的错误倾向，进一步明确了建设社会主义的发展目标和根本目的，为科学社会主义理论宝库增添了新的内容。因此，选项A、C、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"过去一段时期，我们曾脱离生产力发展水平和现实国情，片面强调公有制、按劳分配，认为公有制和按劳分配的范围越大、程度越高，越有助于发展社会主义，甚至脱离实际条件，盲目扩大公有制的范围，提高公有制的程度，使社会主义建设走了弯路。故不选。","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-maozhongte-test1-28","moduleId":"advanced","subjectId":"maozhongte","chapter":"综合测试一","chapterKey":"综合测试一","n":28,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"毛中特 · 综合测试一 第 28 题"},"stem":"1992年，邓小平在南方谈话中对社会主义本质作了总结性理论概括：“社会主义的本质，是解放生产力，发展生产力，消灭剥削，消除两极分化，最终达到共同富裕。”这一论断的意义在于","choices":[{"id":"A","text":"遵循了科学社会主义的基本原则，深化了对科学社会主义的认识"},{"id":"B","text":"廓清了不合乎时代进步和社会发展规律的模糊观念"},{"id":"C","text":"摆脱了长期以来拘泥于具体模式而忽略社会主义本质的错误倾向"},{"id":"D","text":"反映了人民的利益和时代的要求"}],"answer":["A","B","C","D"],"analysis":{"point":"本题考查社会主义的本质。搞清楚什么是社会主义、怎样建设社会主义，关键是要在坚持社会主义基本制度的基础上进一步认清社会主义的本质。邓小平根据马克思主义的基本原理和社会主义的实践经验，对这个问题进行了不懈的探索，作出了科学的回答。中华人民共和国成立后的一段时间里，我们片面追求“一大二公”，导致生产资料公有制程度大幅提高，但社会生产力并没有相应地提高，忽略了人民生活水平的改善。改革开放以来，我们强调解放和发展生产力，并将最终发展目标定位于实现共同富裕，这就既提高了社会生产力，又回应了人民的现实利益诉求，摆脱了一直困扰人们的姓“资”姓“社”的争论。因此，选项A、B、C、D正确。\\n无干扰选项。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-maozhongte-test1-29","moduleId":"advanced","subjectId":"maozhongte","chapter":"综合测试一","chapterKey":"综合测试一","n":29,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"毛中特 · 综合测试一 第 29 题"},"stem":"党的十九大报告对社会主义初级阶段的基本路线作出了修改，不仅将“美丽”纳入了基本路线，而且将“现代化国家”提升为“现代化强国”，扩展了党的基本路线的内涵，提升了社会主义初级阶段的奋斗目标。之所以在不同的历史阶段都反复强调坚持社会主义初级阶段基本路线的重要性，是因为党的基本路线","choices":[{"id":"A","text":"是党和国家的生命线、人民的幸福线"},{"id":"B","text":"紧紧抓住了中国现阶段的主要矛盾"},{"id":"C","text":"体现了运用社会主义社会基本矛盾运动的规律"},{"id":"D","text":"是全面推动历史进步，实现民富国强、民族振兴的要求"}],"answer":["A","B","C","D"],"analysis":{"point":"本题考查社会主义初级阶段的基本路线。主要矛盾决定根本任务，根本任务决定基本路线。无论是过去的主要矛盾——“人民日益增长的物质文化需要同落后的社会生产之间的矛盾”，还是党的十九大对社会主要矛盾的新判断——“人民日益增长的美好生活需要和不平衡不充分的发展之间的矛盾”，都决定了我国社会主义初级阶段的根本任务是发展生产力。这就决定了党的基本路线既不能动摇，也要随着经济社会发展的阶段性特征适时作出调整。因此，选项A、B、C、D正确。\\n无干扰选项。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-maozhongte-test1-30","moduleId":"advanced","subjectId":"maozhongte","chapter":"综合测试一","chapterKey":"综合测试一","n":30,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"毛中特 · 综合测试一 第 30 题"},"stem":"在纪念邓小平同志诞辰120周年座谈会上，习近平高度评价了邓小平同志的伟大历史功勋。邓小平同志带领党和人民实现了伟大历史转折，开辟了社会主义现代化建设新局面以及","choices":[{"id":"A","text":"推动实现了马克思主义中国化新的飞跃"},{"id":"B","text":"提出马克思主义同中国实际“第二次结合”"},{"id":"C","text":"确立了实现祖国完全统一的正确路径"},{"id":"D","text":"坚定捍卫了光辉的社会主义旗帜"}],"answer":["A","C","D"],"analysis":{"point":"本题考查邓小平同志的历史功勋。在纪念邓小平同志诞辰120周年座谈会上，习近平指出，邓小平同志作为党的第二代中央领导集体的核心，带领党和人民实现了伟大历史转折，推动实现了马克思主义中国化新的飞跃，开辟了社会主义现代化建设新局面，确立了实现祖国完全统一的正确路径，坚定捍卫了光辉的社会主义旗帜，成功开创中国特色社会主义。因此，选项A、C、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"马克思主义基本原理同中国具体实际“第二次结合”的任务是毛泽东同志提出的。","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-maozhongte-test2-1","moduleId":"advanced","subjectId":"maozhongte","chapter":"综合测试二","chapterKey":"综合测试二","n":1,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"毛中特 · 综合测试二 第 1 题"},"stem":"毛泽东思想是马克思列宁主义在中国的运用和发展，是被实践证明了的关于中国革命和建设的正确的理论原则和经验总结，是中国共产党集体智慧的结晶。中共十一届三中全会以后，对毛泽东和毛泽东思想的历史地位作出科学评价的历史文献是","choices":[{"id":"A","text":"《解放思想，实事求是，团结一致向前看》"},{"id":"B","text":"《全面开创社会主义现代化建设的新局面》"},{"id":"C","text":"《关于建国以来党的若干历史问题的决议》"},{"id":"D","text":"《关于若干历史问题的决议》"}],"answer":["C"],"analysis":{"point":"本题考查对毛泽东和毛泽东思想的科学评价。《关于建国以来党的若干历史问题的决议》（简称《历史决议》）对毛泽东和毛泽东思想的历史地位作出了科学的、符合客观实际的评价。《历史决议》提出，毛泽东同志的功绩是第一位的，错误是第二位的。坚持把经过长期历史考验形成科学理论的毛泽东思想，同毛泽东晚年所犯的错误区别开来，为我们正确评价毛泽东的历史地位，完整准确地理解、坚持和发展毛泽东思想指明了方向。因此，选项C正确。","options":{"A":"《解放思想，实事求是，团结一致向前看》是邓小平同志在1978年12月13日的中共中央工作会议闭幕会上的讲话。这次中共中央工作会议为之后中共十一届三中全会的召开作了充分准备。故不选。","B":"《全面开创社会主义现代化建设的新局面》是胡耀邦同志于1982年9月1日在中国共产党第十二次全国代表大会上所作的报告。故不选。","C":"（正确选项，分析见“解题思路”）","D":"《关于若干历史问题的决议》（简称《决议》）是在1945年4月召开的中共六届七中全会上通过的。该《决议》对以王明为代表、以教条主义为特征的“左”倾错误作了详细总结；肯定了党的六届三中全会及其后的中央对于停止当时党内存在的“左”倾冒险主义错误所起的积极作用；肯定了刘少奇在白区工作的正确路线；指出了党的六届四中全会、六届五中全会的错误；高度评价了毛泽东运用马克思列宁主义的理论和方法来解决中国革命问题的杰出贡献，指出了在全党确立毛泽东领导地位的重大意义。故不选。"}}},{"id":"advanced-maozhongte-test2-2","moduleId":"advanced","subjectId":"maozhongte","chapter":"综合测试二","chapterKey":"综合测试二","n":2,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"毛中特 · 综合测试二 第 2 题"},"stem":"1948年，毛泽东明确指出：“决定革命性质的力量是主要的敌人和主要的革命者。”中国革命的性质不是无产阶级社会主义革命，而是资产阶级民主主义革命。这是因为","choices":[{"id":"A","text":"新民主主义革命是世界无产阶级社会主义革命的一部分"},{"id":"B","text":"中国革命是反帝的民族革命和反封建的民主革命"},{"id":"C","text":"资产阶级民主主义革命是无产阶级社会主义革命的必要准备"},{"id":"D","text":"中国革命的前途是资本主义"}],"answer":["B"],"analysis":{"point":"本题考查中国革命的性质。中国是一个封建经济占明显优势的半殖民地半封建社会，革命是为了终结这个半殖民地半封建的社会形态；中国革命的对象主要是帝国主义和封建主义势力；革命的性质是为了推翻这两个主要敌人的民族革命和民主革命。因此，选项B正确。","options":{"A":"说法正确，但与题意不符，故不选。","B":"（正确选项，分析见“解题思路”）","C":"说法正确，但与题意不符，本题问为什么中国革命的性质是资产阶级民主主义革命，而不是两个革命之间的关系，故不选。","D":"表述错误，中国革命的前途是社会主义，故不选。"}}},{"id":"advanced-maozhongte-test2-3","moduleId":"advanced","subjectId":"maozhongte","chapter":"综合测试二","chapterKey":"综合测试二","n":3,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"毛中特 · 综合测试二 第 3 题"},"stem":"在半殖民地半封建的中国社会，内无民主制度而受封建主义的压迫，外无民族独立而受帝国主义的压迫。因此，中国的无产阶级必须","choices":[{"id":"A","text":"在城市经过长期的、公开的合法斗争"},{"id":"B","text":"经过长期合法斗争以进入起义和战争"},{"id":"C","text":"先占城市后取乡村"},{"id":"D","text":"以革命的武装消灭反革命的武装"}],"answer":["D"],"analysis":{"point":"本题考查新民主主义革命道路形成的必然性。在半殖民地半封建的中国社会，内无民主制度而受封建主义的压迫，外无民族独立而受帝国主义的压迫。中国革命的主要斗争形式只能是武装斗争，以革命的武装消灭反革命的武装，相应的主要组织形式必然是军队。因此，选项D正确。","options":{"A":"近代中国社会内无民主制度、外无民族独立，无产阶级根本不可能像在资本主义国家那样，先在城市经过长期的、公开的合法斗争，然后再组织武装起义、夺取政权，也不能先占领城市后夺取乡村，而应该走相反的道路。故不选。","B":"近代中国社会内无民主制度、外无民族独立，无产阶级根本不可能像在资本主义国家那样，先在城市经过长期的、公开的合法斗争，然后再组织武装起义、夺取政权，也不能先占领城市后夺取乡村，而应该走相反的道路。故不选。","C":"近代中国社会内无民主制度、外无民族独立，无产阶级根本不可能像在资本主义国家那样，先在城市经过长期的、公开的合法斗争，然后再组织武装起义、夺取政权，也不能先占领城市后夺取乡村，而应该走相反的道路。故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-maozhongte-test2-4","moduleId":"advanced","subjectId":"maozhongte","chapter":"综合测试二","chapterKey":"综合测试二","n":4,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"毛中特 · 综合测试二 第 4 题"},"stem":"毛泽东指出，“中国无产阶级应该懂得：他们自己虽然是一个最有觉悟性和最有组织性的阶级，但是如果单凭自己一个阶级的力量，是不能胜利的。而要胜利，他们就必须在各种不同的情形下团结一切可能的革命的阶级和阶层，组织革命的统一战线”。这是因为","choices":[{"id":"A","text":"近代中国社会是一个两头小中间大的社会"},{"id":"B","text":"中国革命的领导者是中国共产党"},{"id":"C","text":"中国革命必须走农村包围城市、武装夺取政权的道路"},{"id":"D","text":"近代中国社会内无民主制度、外无民族独立"}],"answer":["A"],"analysis":{"point":"本题考查建立统一战线的必要性。建立最广泛的统一战线，是由近代中国半殖民地半封建社会的阶级状况所决定的。毛泽东指出，近代中国社会是一个两头小中间大的社会，无产阶级和地主大资产阶级都只占少数，最广大的人民是农民、城市小资产阶级以及其他的中间阶级。作为无产阶级先锋队的中国共产党所领导的革命力量，要战胜作为地主阶级和官僚资产阶级集中代表的国民党所领导的强大的反革命力量，就必须把农民、城市小资产阶级以及其他的中间阶级都团结在自己的周围，结成最广泛的统一战线。因此，选项A正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"本题主要考查中国共产党组织革命统一战线的原因，中国革命的领导者是中国共产党和中国革命必须走农村包围城市、武装夺取政权的道路都不是中国共产党组织革命统一战线的原因。不符合题意，故不选。","C":"本题主要考查中国共产党组织革命统一战线的原因，中国革命的领导者是中国共产党和中国革命必须走农村包围城市、武装夺取政权的道路都不是中国共产党组织革命统一战线的原因。不符合题意，故不选。","D":"近代中国社会内无民主制度、外无民族独立，所以，无产阶级根本不可能像在资本主义国家那样，先在城市经过长期的、公开的合法斗争，然后再组织武装起义、夺取政权。中国革命的主要斗争形式只能是武装斗争，以革命的武装消灭反革命的武装，相应的主要组织形式必然是军队。不符合题意，故不选。"}}},{"id":"advanced-maozhongte-test2-5","moduleId":"advanced","subjectId":"maozhongte","chapter":"综合测试二","chapterKey":"综合测试二","n":5,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"毛中特 · 综合测试二 第 5 题"},"stem":"在中国革命和建设的长期实践中，以毛泽东同志为主要代表的中国共产党人，把马克思列宁主义基本原理同中国具体实际结合起来，形成了适合中国情况的科学指导思想，即毛泽东思想。在毛泽东思想的指导下，中国共产党团结带领中国人民，创造了新民主主义革命、社会主义革命和建设的伟大成就。其中，新民主主义革命的伟大成就，为实现中华民族伟大复兴创造了","choices":[{"id":"A","text":"根本社会条件"},{"id":"B","text":"根本政治前提和制度基础"},{"id":"C","text":"充满新的活力的体制保证和快速发展的物质条件"},{"id":"D","text":"更为完善的制度保证、更为坚实的物质基础、更为主动的精神力量"}],"answer":["A"],"analysis":{"point":"本题考查新民主主义革命胜利的历史意义。新民主主义革命的伟大成就，为实现中华民族伟大复兴创造了根本社会条件。因此，选项A正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"社会主义革命和建设的伟大成就，为实现中华民族伟大复兴奠定了根本政治前提和制度基础。","C":"改革开放和社会主义现代化建设的伟大成就，为实现中华民族伟大复兴提供了充满新的活力的体制保证和快速发展的物质条件。","D":"新时代中国特色社会主义的伟大成就，为实现中华民族伟大复兴提供了更为完善的制度保证、更为坚实的物质基础、更为主动的精神力量。"}}},{"id":"advanced-maozhongte-test2-6","moduleId":"advanced","subjectId":"maozhongte","chapter":"综合测试二","chapterKey":"综合测试二","n":6,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"毛中特 · 综合测试二 第 6 题"},"stem":"在新民主主义社会，本身并不代表一种独立的发展方向，既可以自发地走向资本主义，也可以被引导着走向社会主义的经济成分是","choices":[{"id":"A","text":"合作社经济"},{"id":"B","text":"私人资本主义经济"},{"id":"C","text":"国营经济"},{"id":"D","text":"个体经济"}],"answer":["D"],"analysis":{"point":"本题考查新民主主义社会的性质和特点。农民和手工业者的个体经济既可以自发地走向资本主义，也可以被引导着走向社会主义，其本身并不代表一种独立的发展方向。因此，选项D正确。","options":{"A":"合作社经济是个体经济向社会主义集体经济过渡的形式。故不选。","B":"私人资本主义经济具有资本主义私有性质。故不选。","C":"国营经济是社会主义公有制经济。故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-maozhongte-test2-7","moduleId":"advanced","subjectId":"maozhongte","chapter":"综合测试二","chapterKey":"综合测试二","n":7,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"毛中特 · 综合测试二 第 7 题"},"stem":"20世纪50年代末60年代初，毛泽东在读苏联《政治经济学教科书》时提出：“社会主义这个阶段，又可能分为两个阶段。”这“两个阶段”指的是","choices":[{"id":"A","text":"社会主义初级阶段和社会主义高级阶段"},{"id":"B","text":"社会主义初级阶段和共产主义阶段"},{"id":"C","text":"新民主主义社会和社会主义初级阶段"},{"id":"D","text":"不发达的社会主义和比较发达的社会主义"}],"answer":["D"],"analysis":{"point":"本题考查社会主义的“两个阶段”。20世纪50年代末60年代初，在初步总结社会主义建设的经验教训后，毛泽东认为：“社会主义这个阶段，又可能分为两个阶段，第一个阶段是不发达的社会主义，第二个阶段是比较发达的社会主义。后一阶段可能比前一阶段需要更长的时间。”因此，选项D正确。","options":{"A":"社会主义初级阶段是由邓小平同志最先提出的，不可能出现在毛泽东的论断中。故不选。","B":"社会主义初级阶段是由邓小平同志最先提出的，不可能出现在毛泽东的论断中。故不选。","C":"社会主义初级阶段是由邓小平同志最先提出的，不可能出现在毛泽东的论断中。故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-maozhongte-test2-8","moduleId":"advanced","subjectId":"maozhongte","chapter":"综合测试二","chapterKey":"综合测试二","n":8,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"毛中特 · 综合测试二 第 8 题"},"stem":"1956年，社会主义改造基本完成后，社会主要矛盾随之发生改变，由此决定了中国共产党接下来的中心任务是","choices":[{"id":"A","text":"调动一切积极因素，为社会主义事业服务"},{"id":"B","text":"正确处理人民内部矛盾，巩固社会主义制度"},{"id":"C","text":"加强和改进党的建设，巩固党的执政地位"},{"id":"D","text":"集中力量发展社会生产力，实现国家工业化"}],"answer":["D"],"analysis":{"point":"本题考查社会主义建设时期中国共产党的中心任务。主要矛盾决定党的中心任务，本题的解题关键是理解社会主义改造基本完成后的社会主要矛盾，1956年党的八大明确指出：“国内主要矛盾已经不再是工人阶级和资产阶级的矛盾，而是人民对于建立先进的工业国的要求同落后的农业国的现实之间的矛盾，已经是人民对于经济文化迅速发展的需要同当前经济文化不能满足人民需要的状况之间的矛盾。”基于这样的主要矛盾就决定了党的中心工作的转移，即集中力量发展社会生产力，实现国家工业化，逐步满足人民日益增长的物质和文化需要。因此，选项D正确。","options":{"A":"调动一切积极因素归根到底是为了发展社会生产力，故不选。","B":"正确处理人民内部矛盾是为了更好地促进生产力的发展，故不选。","C":"加强和改进党的建设属于完成党的中心任务的根本保证，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-maozhongte-test2-9","moduleId":"advanced","subjectId":"maozhongte","chapter":"综合测试二","chapterKey":"综合测试二","n":9,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"毛中特 · 综合测试二 第 9 题"},"stem":"1982年，邓小平在党的十二大开幕词中明确指出，我们党的全部理论和实践创新的主题是","choices":[{"id":"A","text":"改革开放"},{"id":"B","text":"中国特色社会主义"},{"id":"C","text":"社会主义初级阶段"},{"id":"D","text":"社会主义市场经济体制"}],"answer":["B"],"analysis":{"point":"本题考查中国特色社会主义理论体系的形成发展过程。1982年，邓小平在党的十二大开幕词中明确提出，走自己的道路，建设有中国特色的社会主义。从此，“中国特色社会主义”成为我们党的全部理论和实践创新的主题。因此，选项B正确。","options":{"A":"提出于1978年党的十一届三中全会。","B":"（正确选项，分析见“解题思路”）","C":"提出于1981年党的十一届六中全会。","D":"提出于邓小平南方谈话和党的十四大。"}}},{"id":"advanced-maozhongte-test2-10","moduleId":"advanced","subjectId":"maozhongte","chapter":"综合测试二","chapterKey":"综合测试二","n":10,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"毛中特 · 综合测试二 第 10 题"},"stem":"党的十三大召开前夕，邓小平强调指出：“社会主义本身是共产主义的初级阶段，而我们中国又处在社会主义的初级阶段，就是不发达的阶段。一切都要从这个实际出发，根据这个实际来制订规划。”这一论述","choices":[{"id":"A","text":"首次提出了社会主义初级阶段概念"},{"id":"B","text":"首次系统阐述了社会主义初级阶段理论"},{"id":"C","text":"首次把社会主义初级阶段作为事关全局的基本国情加以把握"},{"id":"D","text":"首次对社会主义发展阶段进行了划分"}],"answer":["C"],"analysis":{"point":"本题考查社会主义初级阶段理论。1987年党的十三大召开前夕，邓小平强调指出：“我们党的十三大要阐述中国社会主义是处在一个什么阶段，就是处在初级阶段，是初级阶段的社会主义。社会主义本身是共产主义的初级阶段，而我们中国又处在社会主义的初级阶段，就是不发达的阶段。一切都要从这个实际出发，根据这个实际来制订规划。”这个论述，第一次把社会主义初级阶段作为事关全局的基本国情加以把握，明确了这一基本国情是党制定路线、方针、政策的出发点和根本依据。因此，选项C正确。","options":{"A":"“首次提出了社会主义初级阶段概念”是在党的十一届六中全会上。","B":"“首次系统阐述了社会主义初级阶段理论”是在党的十三大上。","C":"（正确选项，分析见“解题思路”）","D":"“首次对社会主义发展阶段进行了划分”的是毛泽东，他在读苏联《政治经济学教科书》时提出了一个重要的观点，认为：“社会主义这个阶段，又可能分为两个阶段，第一个阶段是不发达的社会主义，第二个阶段是比较发达的社会主义。后一阶段可能比前一阶段需要更长的时间。”"}}},{"id":"advanced-maozhongte-test2-11","moduleId":"advanced","subjectId":"maozhongte","chapter":"综合测试二","chapterKey":"综合测试二","n":11,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"毛中特 · 综合测试二 第 11 题"},"stem":"21世纪以来，我国经济和社会发展呈现出一系列新的阶段性特征，但是，这些新的阶段性特征的出现并没有改变我国仍处于社会主义初级阶段这一基本事实。这表明，社会主义初级阶段是","choices":[{"id":"A","text":"社会性质与发展程度的有机统一过程"},{"id":"B","text":"长期性与阶段性统一的动态发展过程"},{"id":"C","text":"先进社会制度与落后社会生产的矛盾运动过程"},{"id":"D","text":"科学社会主义基本原则与时代精神相结合的过程"}],"answer":["B"],"analysis":{"point":"本题考查社会主义初级阶段的特征。社会主义初级阶段是长期性与阶段性统一的动态发展过程。理解社会主义初级阶段既要认识到其发展是一个相当长的历史阶段，又要认识到其在长期的发展进程中必然还要经历若干具体的阶段，不同时期会呈现不同的阶段性特征。因此，选项B正确。","options":{"A":"社会性质是社会主义，发展程度是初级阶段，二者的有机统一是社会主义初级阶段的内在含义。","B":"（正确选项，分析见“解题思路”）","C":"属于社会主义初级阶段的主要矛盾所反映的社会主义初级阶段的特殊本质。","D":"“四个全面”战略布局，既坚持科学社会主义的基本原则，又体现时代发展的最新要求。"}}},{"id":"advanced-maozhongte-test2-12","moduleId":"advanced","subjectId":"maozhongte","chapter":"综合测试二","chapterKey":"综合测试二","n":12,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"毛中特 · 综合测试二 第 12 题"},"stem":"邓小平指出：“切不要以为香港的事情全由香港人来管，中央一点都不管，就万事大吉了。这是不行的，这种想法不实际。”邓小平在这里重点强调的是","choices":[{"id":"A","text":"香港是中央管理下的特别行政区，中央对香港拥有全面管治权"},{"id":"B","text":"香港必须驻军，而且驻军应该适当参与特别行政区行政事务"},{"id":"C","text":"“一国两制”是为解决香港问题提出的，可以搞一点特殊"},{"id":"D","text":"必须确保香港的稳定和繁荣，这是回归的前提"}],"answer":["A"],"analysis":{"point":"本题考查“一国两制”。香港、澳门是中华人民共和国的特别行政区，享有不同于中国其他省、市、自治区的高度自治权。但与此同时，中央政府对香港、澳门也拥有全面管治权，维护中央权力与保障特别行政区高度自治权并不矛盾。题干引文出自1987年邓小平《会见香港特别行政区基本法起草委员会委员时的讲话》。邓小平未雨绸缪，预见了香港回归后可能会遇到的问题，强调“保持中央的某些权力，对香港有利无害”。因此，选项A正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"邓小平的确强调了香港必须驻军，但驻军是为了体现中国对香港行使国家主权，防止动乱，而不是为了参与特别行政区行政事务。故不选。","C":"表述错误，“一国两制”伟大构想是为解决台湾问题提出的。故不选。","D":"表述错误，香港回归的前提是坚持一个中国原则。故不选。"}}},{"id":"advanced-maozhongte-test2-13","moduleId":"advanced","subjectId":"maozhongte","chapter":"综合测试二","chapterKey":"综合测试二","n":13,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"毛中特 · 综合测试二 第 13 题"},"stem":"1985年，邓小平在会见日本自由民主党副总裁二阶堂进时提出，“改革是中国的第二次革命”。这里的“革命”是指","choices":[{"id":"A","text":"把一个半殖民地半封建的旧中国变成一个社会主义新中国"},{"id":"B","text":"把一个经济文化比较落后的社会主义中国变成一个现代化的社会主义国家"},{"id":"C","text":"把新民主主义国家变成社会主义国家"},{"id":"D","text":"把社会主义国家变成共产主义国家"}],"answer":["B"],"analysis":{"point":"本题考查社会主义改革。在邓小平看来，中国共产党领导中国人民进行了两次革命。第一次革命，把一个半殖民地半封建的旧中国变成一个社会主义新中国；第二次革命，把一个经济文化比较落后的社会主义中国变成一个现代化的社会主义国家。因此，选项B正确。","options":{"A":"指的是中国共产党领导中国人民进行的第一次革命，即新民主主义革命，把一个半殖民地半封建的旧中国变成一个社会主义新中国。故不选。","B":"（正确选项，分析见“解题思路”）","C":"指的是社会主义改造。故不选。","D":"是我们的奋斗目标。故不选。"}}},{"id":"advanced-maozhongte-test2-14","moduleId":"advanced","subjectId":"maozhongte","chapter":"综合测试二","chapterKey":"综合测试二","n":14,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"毛中特 · 综合测试二 第 14 题"},"stem":"习近平在主持中央政治局集体学习时强调：“在市场作用和政府作用的问题上，要讲辩证法、两点论，‘看不见的手’和‘看得见的手’都要用好，努力形成市场作用和政府作用有机统一、相互补充、相互协调、相互促进的格局，推动经济社会持续健康发展。”“看不见的手”和“看得见的手”实际上指的是","choices":[{"id":"A","text":"资源配置的不同方式"},{"id":"B","text":"经济制度的表现形式"},{"id":"C","text":"生产关系的具体范畴"},{"id":"D","text":"分配方式的主要类型"}],"answer":["A"],"analysis":{"point":"本题考查市场和政府对资源的配置。“看不见的手”和“看得见的手”，实际上指的是市场和政府对资源配置的不同调节方式。经济体制改革是全面深化改革的重点，其核心问题是处理好政府和市场的关系，使市场在资源配置中起决定性作用和更好发挥政府作用。因此，选项A正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"经济制度的表现形式包括公有制经济和非公有制经济。故不选。","C":"生产关系的具体范畴包括社会主义生产关系和资本主义生产关系。故不选。","D":"分配方式的主要类型包括按劳分配和按生产要素分配。故不选。"}}},{"id":"advanced-maozhongte-test2-15","moduleId":"advanced","subjectId":"maozhongte","chapter":"综合测试二","chapterKey":"综合测试二","n":15,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"毛中特 · 综合测试二 第 15 题"},"stem":"经济发展就是要提高资源尤其是稀缺资源配置的效率，以尽可能少的资源投入生产尽可能多的产品，获得尽可能大的效益。理论和实践证明，资源配置最有效率的形式是","choices":[{"id":"A","text":"资源完全自由配置"},{"id":"B","text":"资源计划配置"},{"id":"C","text":"政府配置资源"},{"id":"D","text":"市场配置资源"}],"answer":["D"],"analysis":{"point":"本题考查市场和政府对资源的配置。理论和实践证明，市场配置资源是最有效率的形式，市场决定资源配置是市场经济的一般规律，健全社会主义市场经济体制必须遵循这条规律，着力解决市场体系不完善、政府干预过多和监管不到位的问题。因此，选项D正确。","options":{"A":"资源完全自由配置是不可能的，任何国家都会通过宏观调控手段干预经济。故不选。","B":"资源计划配置不符合现代市场经济的规律。故不选。","C":"市场决定资源配置是市场经济的一般规律，而不是政府决定资源配置。故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-maozhongte-test2-16","moduleId":"advanced","subjectId":"maozhongte","chapter":"综合测试二","chapterKey":"综合测试二","n":16,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"毛中特 · 综合测试二 第 16 题"},"stem":"“实事求是”本是一句古老的中国格言，最早见于《汉书·河间献王传》，言称汉景帝之子河间献王刘德“修学好古，实事求是”。1941年5月，毛泽东在《改造我们的学习》一文中把这一原指治学态度的格言从哲学的高度作了新的解释，赋予了它新的含义。毛泽东指出，“实事”就是客观存在着的一切事物，“是”就是客观事物的内部联系，即规律性，“求”就是我们去研究。关于“实事求是”，下列表述正确的有","choices":[{"id":"A","text":"中共八大在全党确立了实事求是的思想路线"},{"id":"B","text":"中共十一届三中全会重新确立了实事求是的思想路线"},{"id":"C","text":"实事求是作为中国共产党的思想路线，始终是马克思主义中国化时代化理论成果的精髓和灵魂"},{"id":"D","text":"实事求是是中国共产党带领人民推动中国革命、建设和改革事业不断取得胜利的重要法宝"}],"answer":["B","C","D"],"analysis":{"point":"本题考查实事求是。在延安整风运动和中共七大时期，实事求是的思想路线在全党得到确立。中共十一届三中全会，解决了“文化大革命”期间党的思想上存在的问题，重新确立了实事求是的思想路线。实事求是作为党的思想路线，始终是马克思主义中国化时代化理论成果的精髓和灵魂，是党带领人民推动中国革命、建设和改革事业不断取得胜利的重要法宝。因此，选项B、C、D正确。","options":{"A":"实事求是的思想路线在全党范围得到确立是在延安整风运动和中共七大时期，而不是中共八大。故不选。","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-maozhongte-test2-17","moduleId":"advanced","subjectId":"maozhongte","chapter":"综合测试二","chapterKey":"综合测试二","n":17,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"毛中特 · 综合测试二 第 17 题"},"stem":"1979年，针对当时存在的是否还要坚持毛泽东思想的问题，邓小平指出：“有些同志说，我们只拥护‘正确的毛泽东思想’，而不拥护‘错误的毛泽东思想’。这种说法也是错误的。”“这种说法”之所以错误，是因为","choices":[{"id":"A","text":"没有把毛泽东思想与毛泽东的思想区分开"},{"id":"B","text":"没有把毛泽东思想与有中国特色社会主义理论区分开"},{"id":"C","text":"没有把毛泽东晚年的错误与毛泽东思想的科学体系区分开"},{"id":"D","text":"没有把毛泽东与党的其他领导人对毛泽东思想的贡献区分开"}],"answer":["A","C"],"analysis":{"point":"本题考查科学评价毛泽东和毛泽东思想。毛泽东思想是马克思列宁主义在中国的运用和发展，是被实践证明了的关于中国革命和建设的正确的理论原则和经验总结，是中国共产党集体智慧的结晶。在这个思想体系中，毛泽东同志的贡献最大。毛泽东的思想是指毛泽东个人的思想，包括毛泽东正确的思想，也包括毛泽东晚年的错误思想。我们必须把毛泽东思想与毛泽东的思想区分开来，把毛泽东晚年的错误与毛泽东思想的科学体系区分开来。因此，选项A、C正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"题干内容同“有中国特色社会主义理论”无关。","C":"（正确选项，分析见“解题思路”）","D":"题干主要要求我们区分毛泽东同志的正确思想和错误思想，并没有提及党的其他领导人对毛泽东思想的贡献。"}}},{"id":"advanced-maozhongte-test2-18","moduleId":"advanced","subjectId":"maozhongte","chapter":"综合测试二","chapterKey":"综合测试二","n":18,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"毛中特 · 综合测试二 第 18 题"},"stem":"党的六届六中全会上，毛泽东明确提出“马克思主义的中国化”命题，党的二十大明确把“不断谱写马克思主义中国化时代化新篇章”作为当代中国共产党人的庄严历史责任。党在不同时期不断强调和推进马克思主义中国化时代化的原因在于，马克思主义只有实现中国化时代化","choices":[{"id":"A","text":"才能为中国革命、建设和改革提供现实的发展模式"},{"id":"B","text":"才能不断发展自身，始终保持蓬勃生机和旺盛活力"},{"id":"C","text":"才能完全融入中华优秀传统文化"},{"id":"D","text":"才能真正解决中国的实际问题"}],"answer":["B","D"],"analysis":{"point":"本题考查马克思主义中国化时代化的重大意义。马克思主义必须中国化才能落地生根、本土化才能深入人心。马克思主义中国化同时包含着马克思主义时代化的意蕴。推进马克思主义中国化时代化，是马克思主义理论本身发展的内在要求。马克思主义只有实现中国化时代化，才能不断发展自身，始终保持蓬勃生机和旺盛活力。推进马克思主义中国化时代化，是解决中国实际问题的客观需要。只有与中国国情相结合、与时代发展同进步，马克思主义才能真正解决中国的实际问题。因此，选项B、D正确。","options":{"A":"马克思主义为我们提供的是一般理论原则和方法，而非具体的“现实的发展模式”。","B":"（正确选项，分析见“解题思路”）","C":"错在两个方面，一方面我们不是将马克思主义“完全融入中华优秀传统文化”，“结合”与“融入”是有区别的；另一方面，因果倒置，是马克思主义与中华优秀传统文化具有相融性，才使得二者具有结合的可能，而不是相反。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-maozhongte-test2-19","moduleId":"advanced","subjectId":"maozhongte","chapter":"综合测试二","chapterKey":"综合测试二","n":19,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"毛中特 · 综合测试二 第 19 题"},"stem":"“现时中国的资产阶级民主主义的革命，已不是旧式的一般的资产阶级民主主义的革命，这种革命已经过时了，而是新式的特殊的资产阶级民主主义的革命。”这种革命的“新式”和“特殊”表现在","choices":[{"id":"A","text":"以马克思列宁主义为指导思想"},{"id":"B","text":"无产阶级是革命领导力量"},{"id":"C","text":"革命的前途是社会主义"},{"id":"D","text":"是资产阶级民主主义革命"}],"answer":["A","B","C"],"analysis":{"point":"本题考查新民主主义革命与旧民主主义革命的区别。新民主主义革命与旧民主主义革命相比有其新的内容和特点，集中表现在：中国的新民主主义革命处于世界无产阶级社会主义革命的时代，是世界无产阶级社会主义革命的一部分；革命的领导力量是中国无产阶级及其先锋队——中国共产党；革命的指导思想是马克思列宁主义；革命的前途是社会主义而不是资本主义。因此，选项A、B、C正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"是新民主主义革命与旧民主主义革命的共同点。与题意不符，故不选。"}}},{"id":"advanced-maozhongte-test2-20","moduleId":"advanced","subjectId":"maozhongte","chapter":"综合测试二","chapterKey":"综合测试二","n":20,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"毛中特 · 综合测试二 第 20 题"},"stem":"民主革命时期，毛泽东从中国革命的现实国情出发，顺应新民主主义社会基础和社会发展规律的要求，主张保护民族工商业，正确回答了如何认识和处理民族资本主义的重大问题。在新民主主义条件下保护民族工商业，发展资本主义，是因为","choices":[{"id":"A","text":"民族资本主义不具有剥削性"},{"id":"B","text":"新民主主义革命不是简单地消灭资本主义和资产阶级"},{"id":"C","text":"民族工商业对发展现代技术、发展社会生产力具有积极作用"},{"id":"D","text":"民族资本主义同帝国主义和封建主义没有丝毫联系"}],"answer":["B","C"],"analysis":{"point":"本题考查保护民族工商业的原因。在新民主主义条件下保护民族工商业，发展资本主义，是由中国落后的生产力和新民主主义革命的性质所决定的。第一，新民主主义革命的对象是帝国主义、封建主义和官僚资本主义，而不是简单地消灭资本主义和资产阶级。同官僚资产阶级相比，民族资产阶级与帝国主义和封建主义联系较少。第二，民族资本主义经济是一种与新生产力相联系的先进的生产方式和经济成分，它对发展现代技术、发展社会生产力具有积极作用。因此，选项B、C正确。","options":{"A":"民族资本主义具有剥削性。故不选。","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"民族资本主义在经济上和政治上与帝国主义和封建主义有着千丝万缕的联系，所以，民族资产阶级没有彻底的反帝反封建的勇气，在革命的关键时刻表现出明显的动摇性。故不选。"}}},{"id":"advanced-maozhongte-test2-21","moduleId":"advanced","subjectId":"maozhongte","chapter":"综合测试二","chapterKey":"综合测试二","n":21,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"毛中特 · 综合测试二 第 21 题"},"stem":"1938年11月，毛泽东在《战争和战略问题》中明确指出：“共产党的任务，基本地不是经过长期合法斗争以进入起义和战争，也不是先占城市后取乡村，而是走相反的道路。”中国革命“走相反的道路”的原因有","choices":[{"id":"A","text":"半殖民地半封建的中国社会内无民主制度、外无民族独立"},{"id":"B","text":"近代中国是一个农业大国，农民占全国人口的绝大多数"},{"id":"C","text":"近代中国政治经济发展极端不平衡，存在不少的统治薄弱环节"},{"id":"D","text":"近代中国的广大农村深受压迫和剥削，人民革命愿望强烈"}],"answer":["A","B","C","D"],"analysis":{"point":"本题考查中国革命走农村包围城市、武装夺取政权道路的原因。中国革命必须走农村包围城市、武装夺取政权的道路，是由中国的具体国情决定的。第一，在半殖民地半封建的中国社会，内无民主制度而受封建主义的压迫，外无民族独立而受帝国主义的压迫。中国的无产阶级根本不可能像在资本主义国家那样，先在城市经过长期的、公开的合法斗争，然后再组织武装起义、夺取政权。中国革命的主要斗争形式只能是武装斗争，以革命的武装消灭反革命的武装，相应的主要组织形式必然是军队。第二，近代中国是一个农业大国，农民占全国人口的绝大多数，是无产阶级可靠的同盟军和革命的主力军。在中国开展革命斗争，必须充分地发动农民，凝聚农民阶级的革命力量，否则就无法摧毁帝国主义和封建地主阶级反动统治的基础。第三，近代中国是众多帝国主义间接统治的经济落后的半殖民地国家，社会政治经济发展极端不平衡，四分五裂，军阀割据，存在不少的统治薄弱环节，为党在农村开展革命斗争，建设革命根据地提供了缝隙和可能。第四，近代中国的广大农村深受反动统治阶级的多重压迫和剥削，人民革命愿望强烈，加之经历过民主革命的洗礼，革命的群众基础好。因此，选项A、B、C、D正确。\\n无干扰选项。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-maozhongte-test2-22","moduleId":"advanced","subjectId":"maozhongte","chapter":"综合测试二","chapterKey":"综合测试二","n":22,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"毛中特 · 综合测试二 第 22 题"},"stem":"1953年12月，由毛泽东审阅通过的中共中央宣传部编写的《为动员一切力量把我国建设成为一个伟大的社会主义国家而斗争——关于党在过渡时期总路线的学习和宣传提纲》指出，“我国由新民主主义社会逐步过渡到社会主义社会这一过渡历史时期之所以必要，并且需要一个相当长的时间”，是由于","choices":[{"id":"A","text":"个体农业和手工业及资本主义工商业占比很大"},{"id":"B","text":"民主革命遗留任务尚未完成"},{"id":"C","text":"我国经济和文化的落后"},{"id":"D","text":"当时的国际形势不利于中国向社会主义过渡"}],"answer":["A","C"],"analysis":{"point":"本题考查党在过渡时期的总路线的理论依据。1953年12月，毛泽东指出：“我国由新民主主义社会逐步过渡到社会主义社会这一过渡历史时期之所以必要，并且需要一个相当长的时间，是由于：一、我国经济和文化的落后，要求一个相当长的时期来创造为保证社会主义完全胜利所必要的经济上和文化上的前提；二、我国有极其广大的个体的农业和手工业及在国民经济中占很大一部分比重的资本主义工商业，要求一个相当长的时期来改造它们。”因此，选项A、C正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"表述错误，在过渡时期总路线提出之前，民主革命遗留任务就彻底完成了。","C":"（正确选项，分析见“解题思路”）","D":"表述错误，在当时的国际形势下，中苏关系友好发展，是有利于中国向社会主义过渡的。"}}},{"id":"advanced-maozhongte-test2-23","moduleId":"advanced","subjectId":"maozhongte","chapter":"综合测试二","chapterKey":"综合测试二","n":23,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"毛中特 · 综合测试二 第 23 题"},"stem":"毛泽东指出：“现在我们能造什么？能造桌子椅子，能造茶碗茶壶，能种粮食，还能磨成面粉，还能造纸，但是，一辆汽车、一架飞机、一辆坦克、一辆拖拉机都不能造。”社会主义改造的目的包括","choices":[{"id":"A","text":"变革旧的生产关系"},{"id":"B","text":"确立社会主义生产关系"},{"id":"C","text":"实现民族独立"},{"id":"D","text":"继续解放和发展生产力"}],"answer":["A","B","D"],"analysis":{"point":"本题考查社会主义改造的目的。社会主义改造的直接目的是建立社会主义经济制度。社会主义改造的基本完成，实现了生产资料的国家和集体所有，变革了旧的生产关系，确立了社会主义生产关系，为生产力的解放和发展扫清了障碍。1956年年底，我国对农业、手工业和资本主义工商业的社会主义改造的基本完成，标志着中国历史上长达数千年的阶级剥削制度的结束，实现了由新民主主义向社会主义的转变，社会主义基本制度在我国初步确立，我国进入了社会主义初级阶段。因此，选项A、B、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"民族独立在中华人民共和国成立时就实现了，不是社会主义改造的目的，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-maozhongte-test2-24","moduleId":"advanced","subjectId":"maozhongte","chapter":"综合测试二","chapterKey":"综合测试二","n":24,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"毛中特 · 综合测试二 第 24 题"},"stem":"中华人民共和国成立和社会主义制度确立以后，在我国，民族压迫和民族剥削已被消灭，但这并不意味着我国就没有民族问题了。社会主义制度下的民族问题与剥削制度下的民族问题在性质上是根本不同的，社会主义时期的民族问题的实质是","choices":[{"id":"A","text":"阶级矛盾和阶级斗争问题"},{"id":"B","text":"汉族和少数民族的尖锐矛盾"},{"id":"C","text":"各民族人民的内部矛盾"},{"id":"D","text":"各民族人民在根本利益一致基础上的矛盾"}],"answer":["C","D"],"analysis":{"point":"本题考查社会主义时期的民族问题的实质。社会主义制度下的民族问题与剥削制度下的民族问题在性质上是根本不同的，因此解决民族问题的方法也必然不同。社会主义时期的民族问题的实质，已经不是阶级矛盾和阶级斗争问题，而是各民族人民的内部矛盾，是各民族人民在根本利益一致基础上的矛盾，应该用正确处理人民内部矛盾的方法来加以解决。因此，选项C、D正确。","options":{"A":"社会主义时期的民族问题的实质，已经不是阶级矛盾和阶级斗争问题，故不选。","B":"汉族和少数民族的矛盾属于人民内部矛盾，不是尖锐矛盾，故不选。","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-maozhongte-test2-25","moduleId":"advanced","subjectId":"maozhongte","chapter":"综合测试二","chapterKey":"综合测试二","n":25,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"毛中特 · 综合测试二 第 25 题"},"stem":"毛泽东在《关于目前党的政策中的几个重要问题》中认为，中国革命的领导权是在与资产阶级争夺领导权的斗争中实现的，“领导的阶级和政党，要实现自己对于被领导的阶级、阶层、政党和人民团体的领导”，必须具备的条件包括","choices":[{"id":"A","text":"率领被领导者（同盟者）向着共同敌人作坚决的斗争，并取得胜利"},{"id":"B","text":"对被领导者给以物质福利，至少不损害其利益"},{"id":"C","text":"对被领导者给以政治教育"},{"id":"D","text":"对被领导者采取“有理、有利、有节”的斗争原则"}],"answer":["A","B","C"],"analysis":{"point":"本题考查新民主主义革命的领导权。无产阶级及其政党对中国革命的领导权不是自然而然得来的，而是在与资产阶级争夺领导权的斗争中实现的。毛泽东指出：“领导的阶级和政党，要实现自己对于被领导的阶级、阶层、政党和人民团体的领导，必须具备两个条件：（甲）率领被领导者（同盟者）向着共同敌人作坚决的斗争，并取得胜利；（乙）对被领导者给以物质福利，至少不损害其利益，同时对被领导者给以政治教育。没有这两个条件或两个条件缺一，就不能实现领导。”因此，选项A、B、C正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"“有理、有利、有节”是中国共产党在抗日战争时期同顽固派作斗争时所坚持的原则。与题意不符，故不选。"}}},{"id":"advanced-maozhongte-test2-26","moduleId":"advanced","subjectId":"maozhongte","chapter":"综合测试二","chapterKey":"综合测试二","n":26,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"毛中特 · 综合测试二 第 26 题"},"stem":"中华人民共和国成立后，以毛泽东为主要代表的中央领导集体对中国社会主义建设道路作出了孜孜不倦的思考和探索，虽然经历严重曲折，但也取得了独创性理论成果和巨大成就。回顾毛泽东对中国社会主义建设道路的探索成果，对于在新的历史起点上高举中国特色社会主义伟大旗帜，坚持和发展中国特色社会主义，具有的重要意义包括","choices":[{"id":"A","text":"标志着马克思主义基本原理和中国具体实际“第二次结合”任务的完成"},{"id":"B","text":"丰富了科学社会主义的理论和实践"},{"id":"C","text":"巩固和发展了中国特色社会主义制度"},{"id":"D","text":"为开创中国特色社会主义提供了重要的理论准备、宝贵经验和物质基础"}],"answer":["B","D"],"analysis":{"point":"本题考查毛泽东时期关于社会主义建设道路初步探索的意义。毛泽东提出了马克思主义与中国实际的“第二次结合”，却没有完成这个结合。以毛泽东同志为核心的第一代中央领导集体的探索成果丰富了科学社会主义的理论和实践，为开创中国特色社会主义提供了重要的理论准备、宝贵经验和物质基础。因此，选项B、D正确。","options":{"A":"毛泽东提出了马克思主义与中国实际的“第二次结合”，但没有完成这个结合，故不选。","B":"（正确选项，分析见“解题思路”）","C":"中国特色社会主义制度是改革开放的成果，毛泽东时期还没有这个提法，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-maozhongte-test2-27","moduleId":"advanced","subjectId":"maozhongte","chapter":"综合测试二","chapterKey":"综合测试二","n":27,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"毛中特 · 综合测试二 第 27 题"},"stem":"邓小平曾指出：“现在虽说我们也在搞社会主义，但事实上不够格。”所谓“不够格”，也就是不够马克思所讲的“共产主义低级阶段”即社会主义阶段的“资格”。这里的“不够格”主要是物质技术基础方面不够格，也表现为社会经济制度和上层建筑方面的不成熟和不完善。社会主义初级阶段的长期性，从根本上说取决于","choices":[{"id":"A","text":"中国进入社会主义的历史条件"},{"id":"B","text":"建成社会主义所需要的物质基础"},{"id":"C","text":"党的基本路线和基本纲领"},{"id":"D","text":"社会主义初级阶段的主要矛盾"}],"answer":["A","B"],"analysis":{"point":"本题考查社会主义初级阶段长期性的原因。从1956年生产资料私有制的社会主义改造基本完成，到21世纪中叶社会主义现代化的基本实现，社会主义初级阶段至少需要100年时间。社会主义初级阶段的长期性，从根本上说是由中国进入社会主义的历史条件和建成社会主义所需要的物质基础所决定的。因此，选项A、B正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"不是社会主义初级阶段长期性的根本原因。故不选。","D":"不是社会主义初级阶段长期性的根本原因。故不选。"}}},{"id":"advanced-maozhongte-test2-28","moduleId":"advanced","subjectId":"maozhongte","chapter":"综合测试二","chapterKey":"综合测试二","n":28,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"毛中特 · 综合测试二 第 28 题"},"stem":"市场经济作为资源配置的一种方式，本身不具有制度属性，可以和不同的社会制度结合，从而表现出不同的性质。社会主义与市场经济的结合，其基本特征主要体现在","choices":[{"id":"A","text":"所有制结构方面"},{"id":"B","text":"分配制度方面"},{"id":"C","text":"宏观调控方面"},{"id":"D","text":"资源配置方式方面"}],"answer":["A","B","C"],"analysis":{"point":"本题考查社会主义市场经济理论。市场经济和不同社会制度结合具有不同的性质。坚持社会主义与市场经济的结合，是社会主义市场经济的特色所在，社会主义市场经济的基本特征主要体现在所有制结构、分配制度、宏观调控三个方面。因此，选项A、B、C正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"市场配置资源是市场经济所具有的一般特征，并不是社会主义市场经济的特色所在。故不选。"}}},{"id":"advanced-maozhongte-test2-29","moduleId":"advanced","subjectId":"maozhongte","chapter":"综合测试二","chapterKey":"综合测试二","n":29,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"毛中特 · 综合测试二 第 29 题"},"stem":"习近平指出：“改革开放是决定当代中国命运的关键一招，也是决定实现‘两个一百年’奋斗目标、实现中华民族伟大复兴的关键一招。”因此，改革开放的意义在于","choices":[{"id":"A","text":"是决定当代中国命运的关键抉择"},{"id":"B","text":"是当代中国发展进步的活力之源"},{"id":"C","text":"是党和人民事业大踏步赶上时代的重要法宝"},{"id":"D","text":"是坚持和发展中国特色社会主义、实现中华民族伟大复兴的必由之路"}],"answer":["A","B","C","D"],"analysis":{"point":"本题考查改革开放。没有改革开放，就没有中国的今天。离开改革开放，也没有中国的明天。习近平总书记多次强调：“只有改革开放才能发展中国、发展社会主义、发展马克思主义。”从这个意义上讲，改革开放的意义怎么强调也不过分。因此，选项A、B、C、D正确。\\n无干扰选项。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-maozhongte-test2-30","moduleId":"advanced","subjectId":"maozhongte","chapter":"综合测试二","chapterKey":"综合测试二","n":30,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"毛中特 · 综合测试二 第 30 题"},"stem":"党的二十大报告提出我们要构建高水平社会主义市场经济体制，坚持和完善社会主义基本经济制度，毫不动摇巩固和发展公有制经济，毫不动摇鼓励、支持、引导非公有制经济发展。确立这一基本经济制度的基本依据包括","choices":[{"id":"A","text":"社会主义国家必须坚持公有制作为社会主义经济制度的基础"},{"id":"B","text":"社会主义初级阶段，生产力还不发达，发展还很不平衡"},{"id":"C","text":"一切符合“三个有利于”标准的所有制形式，都可以用来为社会主义服务"},{"id":"D","text":"公有制经济和非公有制经济都是我国经济的主体"}],"answer":["A","B","C"],"analysis":{"point":"本题考查确立社会主义基本经济制度的基本依据。以公有制为主体、多种所有制经济共同发展的基本经济制度，是由社会主义性质和社会主义初级阶段的基本国情决定的。其基本依据包括：第一，我国是社会主义国家，必须坚持公有制作为社会主义经济制度的基础；第二，我国还处在社会主义初级阶段，生产力还不发达，发展还很不平衡，需要在以公有制为主体的条件下发展多种所有制经济；第三，一切符合“三个有利于”标准的所有制形式，都可以而且应该用来为社会主义服务。因此，选项A、B、C正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"非公有制经济不是我国经济的主体。故不选。"}}},{"id":"advanced-xisixiang-test1-1","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试一","chapterKey":"综合测试一","n":1,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试一 第 1 题"},"stem":"历史和实践充分证明，只有社会主义才能救中国，只有社会主义才能发展中国，只有坚持和发展中国特色社会主义才能实现中华民族伟大复兴。一个国家实行什么样的主义，关键要看这个主义能否解决这个国家面临的","choices":[{"id":"A","text":"社会性课题"},{"id":"B","text":"政治性课题"},{"id":"C","text":"历史性课题"},{"id":"D","text":"文化性课题"}],"answer":["C"],"analysis":{"point":"本题考查中国特色社会主义具有深厚的历史渊源。一个国家实行什么样的主义，关键要看这个主义能否解决这个国家面临的历史性课题。因此，选项C正确。","options":{"A":"社会性、政治性和文化性都只是历史进程中的一个方面，不能代表历史的全部，故不选。","B":"社会性、政治性和文化性都只是历史进程中的一个方面，不能代表历史的全部，故不选。","C":"（正确选项，分析见“解题思路”）","D":"社会性、政治性和文化性都只是历史进程中的一个方面，不能代表历史的全部，故不选。"}}},{"id":"advanced-xisixiang-test1-2","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试一","chapterKey":"综合测试一","n":2,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试一 第 2 题"},"stem":"社会主义初级阶段基本经济制度，既包括作为社会主义经济基础的公有制经济，也包括非公有制经济。把非公有制经济纳入基本经济制度之中，是因为它们","choices":[{"id":"A","text":"具有社会主义性质"},{"id":"B","text":"是社会主义经济的重要组成部分"},{"id":"C","text":"为社会主义服务"},{"id":"D","text":"具有公有制的性质"}],"answer":["C"],"analysis":{"point":"本题考查非公有制经济。一切符合“三个有利于”标准的所有制形式，都可以而且应该用来为社会主义服务。社会主义初级阶段基本经济制度，既包括作为社会主义经济基础的公有制经济，也包括非公有制经济。把非公有制经济纳入基本经济制度之中，是因为它们同作为主体的公有制经济一样，也是为社会主义服务的。因此，选项C正确。","options":{"A":"公有制经济具有社会主义性质，非公有制经济不属于社会主义经济，故不选。","B":"非公有制经济是社会主义市场经济的重要组成部分，而不是社会主义经济的重要组成部分。社会主义经济一般指集中程度较高的公有制经济，其重要组成部分包括国有经济和集体经济。注意区分社会主义市场经济的重要组成部分和社会主义经济的重要组成部分，故不选。","C":"（正确选项，分析见“解题思路”）","D":"表述错误，非公有制经济不具有公有制性质，国有经济和集体经济才具有公有制性质，故不选。"}}},{"id":"advanced-xisixiang-test1-3","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试一","chapterKey":"综合测试一","n":3,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试一 第 3 题"},"stem":"习近平指出：“概括地说，新质生产力是创新起主导作用，摆脱传统经济增长方式、生产力发展路径，具有高科技、高效能、高质量特征，符合新发展理念的先进生产力质态。”发展新质生产力的基本路径是","choices":[{"id":"A","text":"全要素生产率大幅提升"},{"id":"B","text":"科技创新和产业创新"},{"id":"C","text":"深化供给侧结构性改革"},{"id":"D","text":"推动高质量发展"}],"answer":["B"],"analysis":{"point":"本题考查发展新质生产力的基本路径。2023年12月11日至12日，习近平总书记在中央经济工作会议上强调，深化供给侧结构性改革，核心是以科技创新推动产业创新，特别是以颠覆性技术和前沿技术催生新产业、新模式、新动能，发展新质生产力。2024年1月31日，习近平在二十届中央政治局第十一次集体学习的讲话中指出：“发展新质生产力是推动高质量发展的内在要求和重要着力点。”“概括地说，新质生产力是创新起主导作用，摆脱传统经济增长方式、生产力发展路径，具有高科技、高效能、高质量特征，符合新发展理念的先进生产力质态。它由技术革命性突破、生产要素创新性配置、产业深度转型升级而催生，以劳动者、劳动资料、劳动对象及其优化组合的跃升为基本内涵，以全要素生产率大幅提升为核心标志，特点是创新，关键在质优，本质是先进生产力。”2025年3月两会期间，习近平在参加江苏代表团审议时明确指出：“科技创新和产业创新，是发展新质生产力的基本路径。”因此，选项B正确。","options":{"A":"全要素生产率大幅提升是新质生产力的核心标志，故不选。","B":"（正确选项，分析见“解题思路”）","C":"深化供给侧结构性改革是高质量发展的主线，故不选。","D":"发展新质生产力是推动高质量发展的内在要求和重要着力点，故不选。"}}},{"id":"advanced-xisixiang-test1-4","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试一","chapterKey":"综合测试一","n":4,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试一 第 4 题"},"stem":"2025年5月17日，人社部、财政部、国资委联合印发《关于加大国有企业技能人才薪酬分配激励的通知》（简称《通知》）。《通知》强调，要建立健全国有企业技能导向的薪酬分配制度，推动建设与产业发展相适应的新时代高素质技能人才队伍。《通知》发布的举措","choices":[{"id":"A","text":"符合经济转型升级要求，确保国有企业直接配置资源"},{"id":"B","text":"进一步提升了国有企业在经济发展中的比重"},{"id":"C","text":"通过改变按劳分配的主体地位，调动劳动者的积极性和创造性"},{"id":"D","text":"通过利益分配机制的创新，引导技能人才自我提升"}],"answer":["D"],"analysis":{"point":"本题考查国有企业改革的内容。建立健全国有企业技能导向的薪酬分配制度，是利益分配机制的创新。劳动者为了获得更高的薪酬，会主动提升自己的技能水平，有利于推动建设新时代高素质技能人才队伍。因此，选项D正确。","options":{"A":"“确保国有企业直接配置资源”表述错误，应该是由市场配置资源，故不选。","B":"国有企业改革是要提升国企的效率而不是增大国企在经济中的占比，故不选。","C":"我国实行以按劳分配为主体、多种分配方式并存的分配制度，不允许改变按劳分配的主体地位，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-xisixiang-test1-5","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试一","chapterKey":"综合测试一","n":5,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试一 第 5 题"},"stem":"文脉千秋在，江河万古流。习近平总书记指出：“中华文明是世界上唯一绵延不断且以国家形态发展至今的伟大文明。”一系列考古发现表明，中华先民接续生活在古老的长江流域，繁衍生息、接力前行。浙江余杭良渚遗址、浙江余姚河姆渡文化遗址群、湖北天门石家河遗址、四川广汉三星堆遗址、四川成都金沙遗址、四川阿坝金川刘家寨遗址、四川甘孜稻城皮洛遗址等考古发现，证实了长江流域埋藏着从青铜器时代上溯到石器时代的文化链。这说明，中华文明具有突出的","choices":[{"id":"A","text":"连续性"},{"id":"B","text":"统一性"},{"id":"C","text":"和平性"},{"id":"D","text":"创新性"}],"answer":["A"],"analysis":{"point":"本题考查中华文明的突出特性。从题干中的“绵延不断”“文化链”等关键词可知，考查的是中华文明的连续性。中华文明具有突出的连续性，这从根本上决定了中华民族必然走自己的路。因此，选项A正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"统一性从根本上决定了中华民族各民族文化融为一体、即使遭遇重大挫折也牢固凝聚，决定了国土不可分、国家不可乱、民族不可散、文明不可断的共同信念，决定了国家统一永远是中国核心利益的核心，故不选。","C":"和平性从根本上决定了中国始终是世界和平的建设者、全球发展的贡献者、国际秩序的维护者，决定了中国不断追求文明交流互鉴而不搞文化霸权，故不选。","D":"创新性从根本上决定了中华民族守正不守旧、尊古不复古的进取精神，故不选。"}}},{"id":"advanced-xisixiang-test1-6","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试一","chapterKey":"综合测试一","n":6,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试一 第 6 题"},"stem":"发达国家和发展中国家处于不同发展阶段，在环境问题上的历史责任和现实能力存在差异。根据国际能源署、世界银行等机构的统计数据，在居民人均消费碳排放方面，发展中国家大多只是“生存型”排放，而发达国家早已是“奢侈型”或“浪费型”排放。必须充分考虑历史责任、各国国情和生态治理能力，坚持各尽所能、国家自主决定贡献的制度安排。这说明建设人与自然和谐共生的地球家园必须","choices":[{"id":"A","text":"坚持科学治理"},{"id":"B","text":"坚持多边主义"},{"id":"C","text":"坚持共同但有区别的责任原则"},{"id":"D","text":"坚持以人为本"}],"answer":["C"],"analysis":{"point":"本题考查共谋全球生态文明建设之路。建设人与自然和谐共生的地球家园，应坚持以人为本，坚持科学治理，坚持多边主义，坚持共同但有区别的责任原则。题干表达的意思是，发达国家和发展中国家应该为生态治理承担不同的责任。因此，选项C正确。","options":{"A":"表述正确，但与题意不符，故不选。","B":"表述正确，但与题意不符，故不选。","C":"（正确选项，分析见“解题思路”）","D":"表述正确，但与题意不符，故不选。"}}},{"id":"advanced-xisixiang-test1-7","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试一","chapterKey":"综合测试一","n":7,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试一 第 7 题"},"stem":"海南博鳌，从一个名不见经传的小镇变成了一个盛会的代名词。从2001年第一届博鳌亚洲论坛举办以来，借助一年一度的年会论坛平台，中国向世界展现了对外开放的勇气和魄力，为应对保护主义和逆全球化挑战作出了表率。我国之所以坚定不移地实施对外开放的基本国策，是因为","choices":[{"id":"A","text":"实事求是是对外开放的根本立足点"},{"id":"B","text":"我国全方位、宽领域、多层次的对外开放格局已彻底形成"},{"id":"C","text":"全面开放是实现国家繁荣富强的根本出路"},{"id":"D","text":"全面对外开放的总目标是完善和发展中国特色社会主义制度、推进国家治理体系和治理能力现代化"}],"answer":["C"],"analysis":{"point":"本题考查对外开放。对外开放是我国的基本国策，以开放促改革、促发展，是我国现代化建设不断取得新成就的重要法宝。全面开放是实现国家繁荣富强的根本出路。因此，选项C正确。","options":{"A":"独立自主、自力更生是我国对外开放的立足点，故不选。","B":"“已彻底形成”的说法过于绝对，一切仍在进行中，故不选。","C":"（正确选项，分析见“解题思路”）","D":"完善和发展中国特色社会主义制度、推进国家治理体系和治理能力现代化是全面深化改革的总目标，故不选。"}}},{"id":"advanced-xisixiang-test1-8","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试一","chapterKey":"综合测试一","n":8,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试一 第 8 题"},"stem":"1919年，李大钊在《再论问题与主义》一文中指出，“一个社会主义者，为使他的主义在世界上发生一些影响，必须要研究怎么可以把他的理想尽量应用于环绕着他的实境”。这说明，在中国马克思主义能否在实践中发挥作用，关键在于","choices":[{"id":"A","text":"是否与中华优秀传统文化具有高度契合性"},{"id":"B","text":"能否把马克思主义基本原理同中国实际和时代特征结合起来"},{"id":"C","text":"能否得到世界各国人民的认可"},{"id":"D","text":"能否运用其科学的世界观和方法论解决中国的问题"}],"answer":["B","D"],"analysis":{"point":"本题考查习近平新时代中国特色社会主义思想是“两个结合”的重大成果相关内容。马克思主义能不能在实践中发挥作用，关键在于能否把马克思主义基本原理同中国实际和时代特征结合起来，关键在于能否运用其科学的世界观和方法论解决中国的问题。因此，选项B、D正确。","options":{"A":"中华优秀传统文化同马克思主义具有高度契合性，是马克思主义可以同中华优秀传统文化相结合的原因，但并不是在回答马克思主义能不能在实践中发挥作用的关键，故不选。","B":"（正确选项，分析见“解题思路”）","C":"说法错误，马克思主义在中国的实践并不需要其他国家人民的认可，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-xisixiang-test1-9","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试一","chapterKey":"综合测试一","n":9,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试一 第 9 题"},"stem":"在漫长的历史长河中，人类创造和发展了多姿多彩的文明，构成了波澜壮阔的文明图谱。中国式现代化是我们党领导全国各族人民在长期探索和实践中历经千辛万苦、付出巨大代价取得的重大成果。中国式现代化","choices":[{"id":"A","text":"是人类社会现代化的最高级形态"},{"id":"B","text":"深深植根于中华优秀传统文化"},{"id":"C","text":"借鉴吸收一切人类优秀文明成果"},{"id":"D","text":"是一种全新的人类文明形态"}],"answer":["B","C","D"],"analysis":{"point":"本题考查中国式现代化。中国式现代化，深深植根于中华优秀传统文化，体现科学社会主义的先进本质，借鉴吸收一切人类优秀文明成果，代表人类文明进步的发展方向，是一种全新的人类文明形态。因此，选项B、C、D正确。","options":{"A":"中国式现代化开辟了人类文明的新形态，但不能说是人类社会现代化的最高级形态。每个国家都有适合自己的现代化模式，并不能说哪种模式是最高级的，故不选。","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-xisixiang-test1-10","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试一","chapterKey":"综合测试一","n":10,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试一 第 10 题"},"stem":"习近平强调：“我们不能等实现了现代化再来解决共同富裕问题，而是要始终把满足人民对美好生活的新期待作为发展的出发点和落脚点，在实现现代化过程中不断地、逐步地解决好这个问题。”实现共同富裕要","choices":[{"id":"A","text":"处理好先富和共富的关系，允许一部分人先富起来，同时要积极推动先富带后富"},{"id":"B","text":"从全局角度来把握共同富裕"},{"id":"C","text":"处理好“党的领导”和“社会主义法治”的关系"},{"id":"D","text":"通过全国人民共同奋斗把“蛋糕”做大做好，把“蛋糕”切好分好"}],"answer":["A","B","D"],"analysis":{"point":"本题考查实现共同富裕。首先，要通过全国人民共同奋斗把“蛋糕”做大做好，然后通过合理的制度安排正确处理增长和分配关系，把“蛋糕”切好分好。其次，要从全局角度来把握共同富裕。最后，要处理好先富和共富的关系，允许一部分人先富起来，同时要积极推动先富带后富。因此，选项A、B、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"“党的领导”和“社会主义法治”的关系是全面依法治国需要处理的关系，而不是共同富裕要处理的问题，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-xisixiang-test1-11","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试一","chapterKey":"综合测试一","n":11,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试一 第 11 题"},"stem":"中国自由贸易试验区（简称“自贸区”）作为国家深化改革、扩大开放的重要“试验田”，自2013年上海自贸试验区设立以来，已走过波澜壮阔的12年。12年间，我国自贸区从上海的“一枝独秀”发展为全国范围的“百花齐放”。截至2025年7月，我国自贸区已形成涵盖22个自贸区的“陆海空一体化”开放网络，形成“1+3+7+N”的梯度布局。我国设立自贸试验区旨在","choices":[{"id":"A","text":"对标国际高标准经贸规则，打造制度型开放高地"},{"id":"B","text":"以制度机制规范创新，提升创新举措“含金量”"},{"id":"C","text":"促进自主创新，推动在“卡脖子”领域实现突破"},{"id":"D","text":"胸怀“国之大者”，服务国家区域重大战略"}],"answer":["A","B","C","D"],"analysis":{"point":"本题考查全面深化改革。我国支持自贸试验区的建设旨在：第一，以制度机制规范创新，提升创新举措“含金量”。第二，对标国际高标准经贸规则，打造制度型开放高地。第三，胸怀“国之大者”，服务国家区域重大战略。第四，促进自主创新，推动在“卡脖子”领域实现突破。第五，扎实发挥“试验田”作用，助力新业态做优做强。因此，选项A、B、C、D正确。\\n无干扰选项。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-xisixiang-test1-12","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试一","chapterKey":"综合测试一","n":12,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试一 第 12 题"},"stem":"广东是改革开放的排头兵、先行地、实验区，在中国式现代化建设的大局中地位重要、作用突出。要锚定强国建设、民族复兴目标，围绕高质量发展这个首要任务和构建新发展格局这个战略任务，在全面深化改革、扩大高水平对外开放等方面继续走在全国前列，在推进中国式现代化建设中走在前列。下列属于我国进一步扩大对外开放的举措有","choices":[{"id":"A","text":"放宽外资市场准入"},{"id":"B","text":"继续增加负面清单"},{"id":"C","text":"完善投资促进和保护、信息报告等制度"},{"id":"D","text":"完善知识产权保护法律体系"}],"answer":["A","C","D"],"analysis":{"point":"本题考查对外开放。中国将不断完善市场化、法治化、国际化的营商环境，放宽外资市场准入，继续缩减负面清单，完善投资促进和保护、信息报告等制度。中国将营造尊重知识价值的环境，完善知识产权保护法律体系，大力强化相关执法，增强知识产权民事和刑事司法保护力度。因此，选项A、C、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"作为利用外资、推进更高水平对外开放提出的具体举措，我国一直致力于缩减负面清单，而不是“增加负面清单”，故不选。","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-xisixiang-test1-13","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试一","chapterKey":"综合测试一","n":13,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试一 第 13 题"},"stem":"2023年年末，“新质生产力”入选“网络热词前十榜单”。2024年的《政府工作报告》提出，大力推进现代化产业体系建设，加快发展新质生产力。形成新质生产力的主阵地是","choices":[{"id":"A","text":"战略性新兴产业"},{"id":"B","text":"未来产业"},{"id":"C","text":"房地产业"},{"id":"D","text":"金融业"}],"answer":["A","B"],"analysis":{"point":"本题考查形成新质生产力的主阵地。2023年9月，习近平总书记在黑龙江考察时提出，整合科技创新资源，引领发展战略性新兴产业和未来产业，加快形成新质生产力。因此，战略性新兴产业和未来产业是形成新质生产力的主阵地。因此，选项A、B正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"虽然新质生产力将在各行各业中体现，但房地产业和金融业并不算主阵地，故不选。","D":"虽然新质生产力将在各行各业中体现，但房地产业和金融业并不算主阵地，故不选。"}}},{"id":"advanced-xisixiang-test1-14","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试一","chapterKey":"综合测试一","n":14,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试一 第 14 题"},"stem":"邓小平同志指出：“我们一定要坚持按劳分配的社会主义原则。按劳分配是按劳动的数量和质量进行分配的。”我们实行按劳分配的理论依据有","choices":[{"id":"A","text":"市场经济条件下各种生产要素存在排他性占有"},{"id":"B","text":"公有制是实行按劳分配的所有制基础"},{"id":"C","text":"生产力发展水平是实行按劳分配的物质基础"},{"id":"D","text":"劳动、资本、技术、管理等生产要素也参与收入分配"}],"answer":["B","C"],"analysis":{"point":"本题考查实行按劳分配的理论依据。按劳分配是社会主义的分配原则，是由社会主义公有制和社会生产力的发展水平决定的。第一，公有制是实行按劳分配的所有制基础。第二，生产力发展水平是实行按劳分配的物质基础。因此，选项B、C正确。","options":{"A":"社会主义初级阶段实行按生产要素分配有其必要性。由于存在多种所有制经济，各种生产要素都是物质财富和使用价值的源泉，是社会生产不可或缺的因素。当它被排他性占有时，实行按生产要素分配的原则，才能有效地利用。这说的是按生产要素分配，不是按劳分配，故不选。","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"实行按生产要素分配，必须健全劳动、资本、技术、管理等生产要素按贡献参与分配的制度，使多种分配方式的实现具有制度保证。这说的是按生产要素分配，不是按劳分配，故不选。"}}},{"id":"advanced-xisixiang-test1-15","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试一","chapterKey":"综合测试一","n":15,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试一 第 15 题"},"stem":"数据显示，2012年我国全部工业增加值突破20万亿元。2024年，我国全部工业增加值完成40.5万亿元，制造业总体规模连续15年保持全球第一。其中，规模以上装备制造业增加值同比增长7.7%，规模以上高技术制造业增加值同比增长8.9%，占全部规模以上工业的比重较2023年提高0.6个百分点。制造业投资保持较快增长，持续向好的积极因素不断累积，这表明","choices":[{"id":"A","text":"制造业成为推动高质量发展的必由之路"},{"id":"B","text":"中国制造强国地位稳固"},{"id":"C","text":"转型升级提质增效成果显著"},{"id":"D","text":"创新是引领发展的第一动力"}],"answer":["C","D"],"analysis":{"point":"本题考查中国制造实现跨越式增长的原因。2025中国制造业企业500强榜单显示，中国制造业大企业以创新突破应对挑战，以结构优化夯实根基，为稳固实体经济发展、推动现代化产业体系建设提供了有力支撑。“十四五”以来，我国制造业产业结构持续优化。一方面，传统产业加速转型升级，不断加大研发投入。另一方面，战略性新兴产业稳步增长，新旧动能加速转换。以科技创新引领的新质生产力，正为中国制造业高质量发展注入强劲动力。因此，选项C、D正确。","options":{"A":"加快实现高水平科技自立自强，是推动高质量发展的必由之路，故不选。","B":"我国当前是制造业大国，正在大踏步走向制造强国，故不选。","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-xisixiang-test1-16","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试一","chapterKey":"综合测试一","n":16,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试一 第 16 题"},"stem":"2024年8月23日，中共中央政治局召开会议，审议《进一步推动西部大开发形成新格局的若干政策措施》。会议指出，西部大开发是党中央作出的重大战略决策，要深刻领会党中央战略意图，准确把握西部大开发在推进中国式现代化中的定位和使命，保持战略定力。之所以推动西部大开发，是因为西部发展有利于","choices":[{"id":"A","text":"提升区域整体实力和可持续发展能力"},{"id":"B","text":"切实维护民族团结和边疆稳定"},{"id":"C","text":"增强西部地区的经济实力、科技实力"},{"id":"D","text":"形成主体功能明显、优势互补、高质量发展的区域经济布局"}],"answer":["A","B","C","D"],"analysis":{"point":"本题考查西部大开发。推动西部大开发，有利于形成主体功能明显、优势互补、高质量发展的区域经济布局，有利于提升区域整体实力和可持续发展能力，有利于增强西部地区的经济实力、科技实力，有利于切实维护民族团结和边疆稳定。因此，选项A、B、C、D正确。\\n无干扰选项。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-xisixiang-test1-17","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试一","chapterKey":"综合测试一","n":17,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试一 第 17 题"},"stem":"2025年是习近平总书记提出“构建以国内大循环为主体、国内国际双循环相互促进的新发展格局”战略构想5周年。5年多来，习近平总书记亲自谋划、亲自指挥、亲自推动构建新发展格局的崭新实践。加快推动构建新发展格局，就是要","choices":[{"id":"A","text":"把握好深化供给侧结构性改革和加强需求侧管理的关系"},{"id":"B","text":"把握好“全国一盘棋”与发挥地方比较优势的关系"},{"id":"C","text":"优先搞好各地的区域小市场和自我小循环"},{"id":"D","text":"更加注重统筹发展和安全，通盘考虑内外部风险挑战"}],"answer":["A","B","D"],"analysis":{"point":"本题考查新发展格局。构建以国内大循环为主体、国内国际双循环相互促进的新发展格局，就是要把握好深化供给侧结构性改革和加强需求侧管理的关系，使供需两端同时发力、协调配合，形成需求牵引供给、供给创造需求的更高水平动态平衡，实现国民经济良性循环；构建新发展格局是以全国统一大市场基础上的国内大循环为主体，不是各地都搞自我小循环，就是要把握好“全国一盘棋”与发挥地方比较优势的关系；安全是发展的保障，就是要更加注重统筹发展和安全，通盘考虑内外部风险挑战。因此，选项A、B、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"构建新发展格局是以全国统一大市场基础上的国内大循环为主体，不是各地都搞自我小循环。以国内大循环为主体，是针对全国而言的，不能各自为政、画地为牢，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-xisixiang-test1-18","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试一","chapterKey":"综合测试一","n":18,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试一 第 18 题"},"stem":"党的二十届三中全会强调“城乡融合发展是中国式现代化的必然要求”，将新型城乡关系提升到一个前所未有的新高度。加快城乡融合发展，必须","choices":[{"id":"A","text":"统筹新型工业化、新型城镇化和乡村全面振兴"},{"id":"B","text":"全面提高城乡规划、建设、治理融合水平"},{"id":"C","text":"坚持城乡归一化，消除城乡差异"},{"id":"D","text":"完善强农惠农富农支持制度，深化土地制度改革"}],"answer":["A","B","D"],"analysis":{"point":"本题考查城乡融合发展。党的二十届三中全会指出，城乡融合发展是中国式现代化的必然要求。必须统筹新型工业化、新型城镇化和乡村全面振兴，全面提高城乡规划、建设、治理融合水平，促进城乡要素平等交换、双向流动，缩小城乡差别，促进城乡共同繁荣发展。要健全推进新型城镇化体制机制，巩固和完善农村基本经营制度，完善强农惠农富农支持制度，深化土地制度改革。因此，选项A、B、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"城乡融合发展并非城乡归一化，要缩小城乡差别，但不能消除城乡差异，城乡之间要“有差异，无差距”，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-xisixiang-test1-19","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试一","chapterKey":"综合测试一","n":19,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试一 第 19 题"},"stem":"70年来，在党的领导下，人民代表大会制度有效保证了我国始终沿着社会主义道路前进，为创造经济快速发展和社会长期稳定两大奇迹提供了重要制度保障，展现出显著政治优势。这些显著政治优势有","choices":[{"id":"A","text":"保证党领导人民依法有效治理国家"},{"id":"B","text":"保证国家政治生活既充满活力又安定有序"},{"id":"C","text":"实现国家各方面工作法治化和保障国家长治久安"},{"id":"D","text":"保障人民当家作主"}],"answer":["A","B","C","D"],"analysis":{"point":"本题考查人民代表大会制度的“五大显著政治优势”。习近平在庆祝全国人民代表大会成立70周年大会上发表的重要讲话中强调，70年来，在党的领导下，人民代表大会制度有效保证了我国始终沿着社会主义道路前进，在保证党领导人民依法有效治理国家、保障人民当家作主、保证国家政治生活既充满活力又安定有序、实现国家各方面工作法治化、保障国家长治久安方面展现出显著政治优势，为创造经济快速发展和社会长期稳定两大奇迹提供了重要制度保障。因此，选项A、B、C、D正确。\\n无干扰选项。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-xisixiang-test1-20","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试一","chapterKey":"综合测试一","n":20,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试一 第 20 题"},"stem":"中国共产党领导的多党合作和政治协商制度是中国共产党、中国人民和各民主党派、无党派人士的伟大政治创造。在人民民主的共同旗帜下，中国共产党与各民主党派长期共存、互相监督、肝胆相照、荣辱与共，形成“共产党领导、多党派合作，共产党执政、多党派参政”这一具有鲜明中国特色的新型政党制度。这一制度","choices":[{"id":"A","text":"具有深厚的文化基础、理论基础、实践基础"},{"id":"B","text":"具有鲜明中国特色和显著政治优势"},{"id":"C","text":"是科学、有效、管用的制度安排"},{"id":"D","text":"是社会主义民主政治建设的基础"}],"answer":["A","B","C"],"analysis":{"point":"本题考查中国共产党领导的多党合作和政治协商制度。2024年9月20日，习近平总书记在庆祝中国人民政治协商会议成立75周年大会上强调：“75年来的实践充分证明，人民政协是中国共产党把马克思列宁主义统一战线理论、政党理论、民主政治理论同中国具体实际相结合、同中华优秀传统文化相结合的伟大成果，是中国共产党领导各民主党派、无党派人士、人民团体和各族各界人士在政治制度上进行的伟大创造，具有深厚的文化基础、理论基础、实践基础，具有鲜明中国特色和显著政治优势，是科学、有效、管用的制度安排，在人类政治制度发展史上具有独特政治价值。”因此，选项A、B、C正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"基层群众自治制度是社会主义民主政治建设的基础，故不选。"}}},{"id":"advanced-xisixiang-test1-21","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试一","chapterKey":"综合测试一","n":21,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试一 第 21 题"},"stem":"习近平总书记在庆祝全国人民代表大会成立70周年大会上指出：“人民代表大会制度是中国共产党领导中国人民艰辛探索长期奋斗的成果，是从中国土壤中生长起来的全新政治制度，是人类政治制度史上的伟大创造。”人民代表大会制度是我国的根本政治制度，这是因为","choices":[{"id":"A","text":"它直接体现我国人民民主专政的国家性质"},{"id":"B","text":"它能从根本上保证人民当家作主的权利"},{"id":"C","text":"它在制定国家其他各种制度中起着决定性的作用"},{"id":"D","text":"它能使广大人民在国家政治生活中直接行使民主权利"}],"answer":["A","B","C"],"analysis":{"point":"本题考查人民代表大会制度。人民代表大会制度是我国的根本政治制度，是符合我国国情和实际、体现社会主义国家性质、保证人民当家作主、保障实现中华民族伟大复兴的好制度，是我们党领导人民在人类政治制度史上的伟大创造。因此，选项A、B、C正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"基层群众自治制度是社会主义民主政治建设的基础，保障人民依法直接行使民主权利，故不选。"}}},{"id":"advanced-xisixiang-test1-22","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试一","chapterKey":"综合测试一","n":22,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试一 第 22 题"},"stem":"2023年是毛泽东等老一辈革命家为雷锋同志题词60周年。60多年来，学雷锋活动在全国持续深入开展，雷锋的名字家喻户晓，雷锋的事迹深入人心，雷锋精神滋养着一代代中华儿女的心灵。实践证明，无论时代如何变迁，雷锋精神永不过时。党中央通过培育先进典型榜样，抓好社会主义精神文明建设的意义在于","choices":[{"id":"A","text":"为实现中华民族伟大复兴的中国梦提供坚实的制度基础"},{"id":"B","text":"为全面建成社会主义现代化强国提供丰润的道德滋养"},{"id":"C","text":"为中国特色社会主义建设提供强大的精神力量"},{"id":"D","text":"为全国各族人民不断前进提供坚强的思想保证"}],"answer":["B","C","D"],"analysis":{"point":"本题考查社会主义文化建设。文化作为上层建筑，先进的文化可以为全面建成社会主义现代化强国提供丰润的道德滋养；为中国特色社会主义建设提供强大的精神力量；为全国各族人民不断前进提供坚强的思想保证。因此，选项B、C、D正确。","options":{"A":"文化建设提供的是精神动力和思想保证，提供不了制度基础，故不选。","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-xisixiang-test1-23","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试一","chapterKey":"综合测试一","n":23,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试一 第 23 题"},"stem":"从2013年3月到2015年7月，李克强总理主持召开了101次国务院常务会议，其中有46次会议部署简政放权，取消和下放了800多项行政审批事项。他还用“大道至简，有权不可任性”“用政府权力的‘减法’换取市场活力的‘乘法’”等生动而深刻的话语回应了公众对简政放权的期待。简政放权旨在","choices":[{"id":"A","text":"处理好政府与市场关系，加快完善社会主义市场经济体制"},{"id":"B","text":"减少审批环节，降低市场交易成本"},{"id":"C","text":"激发市场主体内在活力和社会创造力"},{"id":"D","text":"提高政府治理能力和治理水平"}],"answer":["A","B","C","D"],"analysis":{"point":"本题考查提高社会治理水平。简政放权是为了让政府摆正自身地位，减少审批环节，承担好服务市场的角色，从而激发市场主体的内在活力和社会创造力。这是处理好政府和市场关系的重要表现，也是提高政府治理能力和治理水平的体现。因此，选项A、B、C、D正确。\\n无干扰选项。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-xisixiang-test1-24","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试一","chapterKey":"综合测试一","n":24,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试一 第 24 题"},"stem":"我国已建成世界上规模最大的社会保障体系，接下来还要在推动社会保障事业高质量发展上持续用力，发展多层次、多支柱养老保险体系，把更多人纳入社会保障体系。我国之所以强调完善社会保障体系的建设，是因为","choices":[{"id":"A","text":"增进民生福祉是新时代中国特色社会主义建设的总任务"},{"id":"B","text":"增进民生福祉是我们坚持立党为公、执政为民的本质要求"},{"id":"C","text":"人民对美好生活的向往就是我们的奋斗目标"},{"id":"D","text":"让老百姓过上好日子是我们一切工作的出发点和落脚点"}],"answer":["B","C","D"],"analysis":{"point":"本题考查社会建设。人民对美好生活的向往就是我们的奋斗目标，增进民生福祉是我们坚持立党为公、执政为民的本质要求，让老百姓过上好日子是我们一切工作的出发点和落脚点，补齐民生保障短板、解决好人民群众急难愁盼问题是社会建设的紧迫任务。必须以保障和改善民生为重点加强社会建设，尽力而为、量力而行，使人民获得感、幸福感、安全感更加充实、更有保障、更可持续。因此，选项B、C、D正确。","options":{"A":"新时代中国特色社会主义建设的总任务是实现社会主义现代化和中华民族伟大复兴，故不选。","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-xisixiang-test1-25","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试一","chapterKey":"综合测试一","n":25,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试一 第 25 题"},"stem":"维护河湖健康生命，实现河湖功能永续利用，需要进一步加强河湖管理保护工作，落实属地责任，健全长效机制。2016年11月28日，中共中央办公厅、国务院办公厅联合印发《关于全面推行河长制的意见》。2017年11月20日召开的中央全面深化改革领导小组会议审议通过了《关于在湖泊实施湖长制的指导意见》。全面推行河长制、湖长制是建设生态文明制度体系的重要举措。我国生态文明制度体系建设主要包括","choices":[{"id":"A","text":"完善经济社会发展考核评价体系"},{"id":"B","text":"完善生态环境损害责任终身追究制度"},{"id":"C","text":"完善生态环境保护管理制度"},{"id":"D","text":"完善部门职责分散交叉的环保监督体系"}],"answer":["A","B","C"],"analysis":{"point":"本题考查生态文明建设。我国生态文明制度体系建设主要包括实行最严格的生态环境保护制度，构建产权清晰、多元参与、激励约束并重、系统完整的生态文明制度体系，完善经济社会发展考核评价体系、建立责任终身追究制度、建立健全资源生态环境管理制度。因此，选项A、B、C正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"建立河长制的目的是形成部门职责独立的环保监督体系，而不是职责分散交叉，我们应该尽量避免各部门职责分散交叉，故不选。"}}},{"id":"advanced-xisixiang-test1-26","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试一","chapterKey":"综合测试一","n":26,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试一 第 26 题"},"stem":"绿水青山就是金山银山。这一理念阐明了经济发展和生态环境保护之间的关系，揭示了保护生态环境就是保护生产力、改善生态环境就是发展生产力的道理。因此，要加快划定并严守","choices":[{"id":"A","text":"生态保护红线"},{"id":"B","text":"环境质量底线"},{"id":"C","text":"资源利用上线"},{"id":"D","text":"“双碳”目标承诺高压线"}],"answer":["A","B","C"],"analysis":{"point":"本题考查生态文明建设。习近平总书记在全国生态环境保护大会上指出：“要加快划定并严守生态保护红线、环境质量底线、资源利用上线三条红线。”因此，选项A、B、C正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"2020年，中国向世界作出庄严承诺，力争2030年前实现碳达峰，2060年前实现碳中和。“双碳”目标是中国的庄严承诺，但还没有上升到“高压线”的程度，故不选。"}}},{"id":"advanced-xisixiang-test1-27","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试一","chapterKey":"综合测试一","n":27,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试一 第 27 题"},"stem":"我国之所以强调必须坚定不移贯彻总体国家安全观，把维护国家安全贯穿党和国家工作各方面全过程，确保国家安全和社会稳定，是因为","choices":[{"id":"A","text":"国家安全是民族复兴的根基"},{"id":"B","text":"国家安全是民族振兴的根本出发点"},{"id":"C","text":"发展是安全的基础"},{"id":"D","text":"社会稳定是国家强盛的前提"}],"answer":["A","D"],"analysis":{"point":"本题考查坚持总体国家安全观。习近平总书记在党的二十大报告中强调：“国家安全是民族复兴的根基，社会稳定是国家强盛的前提。必须坚定不移贯彻总体国家安全观，把维护国家安全贯穿党和国家工作各方面全过程，确保国家安全和社会稳定。”因此，选项A、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"人民幸福是国家繁荣、民族振兴的根本出发点和落脚点，而不是国家安全，故不选。","C":"“发展是安全的基础”强调的是“发展”的重要性，而本题问的是确保“国家安全”和“社会稳定”的原因，侧重点不一样，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-xisixiang-test1-28","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试一","chapterKey":"综合测试一","n":28,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试一 第 28 题"},"stem":"初春时节，寒风扑面。“起飞！”随着一声令下，中部战区空军航空兵某旅数架战机接续升空，直扑目标空域。一场惊心动魄的“云端对决”拉开战幕……党的十八大以来，习近平亲抓实抓练兵备战，亲自运筹指挥重大军事行动。全面加强练兵备战的举措包括","choices":[{"id":"A","text":"牢固树立战斗力这个唯一的根本的标准"},{"id":"B","text":"深入推进实战化军事训练"},{"id":"C","text":"把科技作为决定人民军队发展壮大的关键一招"},{"id":"D","text":"大力培育“一不怕苦、二不怕死”的战斗精神"}],"answer":["A","B","D"],"analysis":{"point":"本题考查全面加强练兵备战的举措。全面加强练兵备战的举措：牢固树立战斗力这个唯一的根本的标准；深入推进实战化军事训练，创新军事战略指导；大力培育“一不怕苦、二不怕死”的战斗精神。因此，选项A、B、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"改革是决定人民军队发展壮大、制胜未来的关键一招。科技是核心战斗力，是军事发展中最活跃、最具革命性的因素，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-xisixiang-test1-29","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试一","chapterKey":"综合测试一","n":29,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试一 第 29 题"},"stem":"解决台湾问题是中国人自己的事，要由中国人来决定。我们坚持以最大诚意、尽最大努力争取和平统一的前景，但决不承诺放弃使用武力，保留采取一切必要措施的选项，这针对的是","choices":[{"id":"A","text":"广大台湾同胞"},{"id":"B","text":"极少数“台独”分裂分子及其分裂活动"},{"id":"C","text":"台湾反独促统的政治势力"},{"id":"D","text":"外部势力干涉"}],"answer":["B","D"],"analysis":{"point":"本题考查台湾问题。习近平总书记在党的二十大报告中强调：“我们坚持以最大诚意、尽最大努力争取和平统一的前景，但决不承诺放弃使用武力，保留采取一切必要措施的选项，这针对的是外部势力干涉和极少数‘台独’分裂分子及其分裂活动，绝非针对广大台湾同胞。”因此，选项B、D正确。","options":{"A":"在推进祖国统一大业进程中，广大台湾同胞和台湾反独促统的政治势力都是要积极争取和团结的对象，而不是针对的对象，故不选。","B":"（正确选项，分析见“解题思路”）","C":"在推进祖国统一大业进程中，广大台湾同胞和台湾反独促统的政治势力都是要积极争取和团结的对象，而不是针对的对象，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-xisixiang-test1-30","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试一","chapterKey":"综合测试一","n":30,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试一 第 30 题"},"stem":"《2024年度中国对外直接投资统计公报》显示，截至2024年年底，我国境内投资者共在全球190个国家和地区设立境外企业5.2万家，其中在共建“一带一路”国家设立境外企业1.9万家。2024年我国对外直接投资流量达1 922亿美元，同比增长8.4%。对共建“一带一路”国家的直接投资占当年对外直接投资流量的26.5%，对全球经济的带动作用愈加突出。共建“一带一路”的历程和成果，充分证明","choices":[{"id":"A","text":"只有合作共赢才能办成事、办好事、办大事"},{"id":"B","text":"共建“一带一路”成为深受欢迎的国际公共产品和国际合作平台"},{"id":"C","text":"人类是相互依存的命运共同体"},{"id":"D","text":"共建“一带一路”仅仅是发展中国家实现开放共赢路径的顶层设计"}],"answer":["A","B","C"],"analysis":{"point":"本题考查“一带一路”。共建“一带一路”的主要经验有：人类是相互依存的命运共同体；只有合作共赢才能办成事、办好事、办大事；共建“一带一路”成为深受欢迎的国际公共产品和国际合作平台，成为推动构建人类命运共同体的重要实践平台，开拓出一条造福共建国家、通向共同繁荣的机遇之路。因此，选项A、B、C正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"共建“一带一路”是对中国与世界实现开放共赢路径的顶层设计，并不是仅有发展中国家参与，故不选。"}}},{"id":"advanced-xisixiang-test2-1","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试二","chapterKey":"综合测试二","n":1,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试二 第 1 题"},"stem":"实现现代化是近代以来中国人民孜孜以求的目标。中华人民共和国成立后，中国共产党带领人民搞建设、实行改革开放，朝着现代化目标不断探索实践。特别是党的十八大以来在理论和实践上的创新突破，成功推进和拓展了中国式现代化，实现中华民族伟大复兴进入了不可逆转的历史进程。以下关于中国式现代化的说法正确的是","choices":[{"id":"A","text":"人口规模巨大的现代化是中国式现代化区别于西方现代化的显著标志"},{"id":"B","text":"中国式现代化的发展为人类实现现代化提供了全新选择"},{"id":"C","text":"中国式现代化已经成为发展中国家走向现代化的统一标准"},{"id":"D","text":"实现现代化是当前做好各项工作的根本宗旨"}],"answer":["B"],"analysis":{"point":"本题考查中国式现代化的内容。中国式现代化走上了一条有别于西方殖民掠夺扩张的新道路，为人类实现现代化提供了全新选择。因此，选项B正确。","options":{"A":"中国式现代化是全体人民共同富裕的现代化，这是中国式现代化区别于西方现代化的显著标志，故不选。","B":"（正确选项，分析见“解题思路”）","C":"世界上既不存在定于一尊的现代化模式，也不存在放之四海而皆准的现代化标准，故不选。","D":"当前做好各项工作的根本宗旨是全心全意为人民服务，故不选。"}}},{"id":"advanced-xisixiang-test2-2","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试二","chapterKey":"综合测试二","n":2,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试二 第 2 题"},"stem":"公有制经济是全体人民的宝贵财富，公有制主体地位不能动摇，国有经济主导作用不能动摇，这是我国各族人民共享发展成果的制度性保证，也是巩固党的执政地位、坚持我国社会主义制度的重要保证。下列是公有制与私有制、社会主义与资本主义的区别的是","choices":[{"id":"A","text":"所有制"},{"id":"B","text":"所有制的实现形式"},{"id":"C","text":"具体的经营方式和组织形式"},{"id":"D","text":"混合所有制经济"}],"answer":["A"],"analysis":{"point":"本题考查所有制。所有制作为生产关系的基础，是公有制与私有制、社会主义与资本主义的区别。因此，选项A正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"所有制的实现形式是采取怎样的经营方式和组织形式问题，它不具有“公”与“私”、“社”与“资”的区分。同样的所有制可以采取不同的实现形式，而不同的所有制也可以采取相同的实现形式，故不选。","C":"所有制的实现形式是采取怎样的经营方式和组织形式问题，它不具有“公”与“私”、“社”与“资”的区分。同样的所有制可以采取不同的实现形式，而不同的所有制也可以采取相同的实现形式，故不选。","D":"混合所有制经济是国有资本、集体资本、非公有资本等交叉持股、相互融合的经济，是基本经济制度的重要实现形式，既包括公有制经济成分，也包括非公有制经济成分，故不选。"}}},{"id":"advanced-xisixiang-test2-3","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试二","chapterKey":"综合测试二","n":3,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试二 第 3 题"},"stem":"2016年是“十三五”规划开局之年，也是推进供给侧结构性改革的攻坚之年。推进供给侧结构性改革是适应我国经济发展新常态的重大决策。其根本目的是","choices":[{"id":"A","text":"加快政府职能转变"},{"id":"B","text":"提高供给质量满足需要"},{"id":"C","text":"深化价格、财税、金融、社保等领域基础性改革"},{"id":"D","text":"推进“去产能、去库存、去杠杆、降成本、补短板”"}],"answer":["B"],"analysis":{"point":"本题考查供给侧结构性改革。习近平指出，供给侧结构性改革关系全局、关系长远，一定要切实抓好。要深刻理解时代背景，当前我国经济发展中有周期性、总量性问题，但结构性问题最突出，矛盾的主要方面在供给侧。要准确把握基本要求，供给侧结构性改革的根本目的是提高供给质量满足需要，使供给能力更好满足人民日益增长的物质文化需要。因此，选项B正确。","options":{"A":"“加快政府职能转变”和“深化价格、财税、金融、社保等领域基础性改革”均是深化改革的要求，故不选。","B":"（正确选项，分析见“解题思路”）","C":"“加快政府职能转变”和“深化价格、财税、金融、社保等领域基础性改革”均是深化改革的要求，故不选。","D":"“去产能、去库存、去杠杆、降成本、补短板”是供给侧结构性改革的五大任务，故不选。"}}},{"id":"advanced-xisixiang-test2-4","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试二","chapterKey":"综合测试二","n":4,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试二 第 4 题"},"stem":"2018年9月10日，全国教育大会在北京召开。习近平在讲话中指出，培养什么人，是教育的首要问题。我国是中国共产党领导的社会主义国家，这就决定了我们的教育必须","choices":[{"id":"A","text":"把推进教育现代化作为根本任务"},{"id":"B","text":"把培养社会主义建设者和接班人作为根本任务"},{"id":"C","text":"把全面深化教育体制改革作为根本任务"},{"id":"D","text":"把建设教育强国作为根本任务"}],"answer":["B"],"analysis":{"point":"本题考查教育的根本任务。一方面，这是习近平总书记在2018年全国教育工作会议上提出的新思想、新论断；另一方面，拥有社会主义的共同理想，建设中国特色社会主义、实现中华民族伟大复兴是当代青年人的历史使命，因此教育必须把培养社会主义建设者和接班人作为根本任务。因此，选项B正确。","options":{"A":"题干引用了习近平总书记的话“培养什么人，是教育的首要问题”，也就是说，正确选项应该与“培养什么人”有关，选项A、C、D均没有提到“培养什么人”的问题。此外，题干中还有关键词“中国共产党领导的社会主义国家”，而“教育现代化”“教育体制改革”“教育强国”这些问题是其他制度的国家也面临的问题，并不是中国共产党领导下的社会主义国家所特有的，故不选。","B":"（正确选项，分析见“解题思路”）","C":"题干引用了习近平总书记的话“培养什么人，是教育的首要问题”，也就是说，正确选项应该与“培养什么人”有关，选项A、C、D均没有提到“培养什么人”的问题。此外，题干中还有关键词“中国共产党领导的社会主义国家”，而“教育现代化”“教育体制改革”“教育强国”这些问题是其他制度的国家也面临的问题，并不是中国共产党领导下的社会主义国家所特有的，故不选。","D":"题干引用了习近平总书记的话“培养什么人，是教育的首要问题”，也就是说，正确选项应该与“培养什么人”有关，选项A、C、D均没有提到“培养什么人”的问题。此外，题干中还有关键词“中国共产党领导的社会主义国家”，而“教育现代化”“教育体制改革”“教育强国”这些问题是其他制度的国家也面临的问题，并不是中国共产党领导下的社会主义国家所特有的，故不选。"}}},{"id":"advanced-xisixiang-test2-5","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试二","chapterKey":"综合测试二","n":5,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试二 第 5 题"},"stem":"江山就是人民，人民就是江山。我们要实现好、维护好、发展好最广大人民根本利益，就必须紧紧抓住人民最关心最直接最现实的利益问题。要坚持在发展中保障和改善民生，其中，关乎最基本民生问题的举措是","choices":[{"id":"A","text":"实施就业优先战略"},{"id":"B","text":"健全社会保障体系"},{"id":"C","text":"推进健康中国建设"},{"id":"D","text":"办好人民满意的教育"}],"answer":["A"],"analysis":{"point":"本题考查在发展中保障和改善民生。习近平总书记在党的二十大报告中强调：“就业是最基本的民生。”因此，选项A正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"都是保障和改善民生的具体举措，但不是关乎最基本民生问题的举措，故不选。","C":"都是保障和改善民生的具体举措，但不是关乎最基本民生问题的举措，故不选。","D":"都是保障和改善民生的具体举措，但不是关乎最基本民生问题的举措，故不选。"}}},{"id":"advanced-xisixiang-test2-6","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试二","chapterKey":"综合测试二","n":6,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试二 第 6 题"},"stem":"生态文明建设是重大经济问题，也是关系党的使命宗旨的重大政治问题、关系民生福祉的重大社会问题。习近平指出：“良好的生态环境是最公平的公共产品，是最普惠的民生福祉。”生态环境问题，归根到底是经济发展方式和生活方式问题，是","choices":[{"id":"A","text":"资源过度开发、粗放利用、奢侈消费造成的"},{"id":"B","text":"人口增加和全球资源短缺造成的"},{"id":"C","text":"环境治理体制机制不健全导致的"},{"id":"D","text":"生产力水平低下导致的"}],"answer":["A"],"analysis":{"point":"本题考查加快形成绿色生产方式和生活方式。自然资源是经济社会发展的重要物质基础。“取之有度，用之有节”是生态文明的真谛。习近平总书记指出，生态环境问题，归根到底是资源过度开发、粗放利用、奢侈消费造成的。也可以说，生态环境问题归根到底是经济发展方式和生活方式问题。要解决这个问题，就必须在转变资源利用方式、提高资源利用效率上下功夫。不仅要考虑人类和当代的需要，也要考虑大自然和后人的需要，把握好自然资源开发利用的度，不要突破自然资源承载能力。因此，选项A正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"均不是导致生态环境问题的根本原因，故不选。","C":"均不是导致生态环境问题的根本原因，故不选。","D":"均不是导致生态环境问题的根本原因，故不选。"}}},{"id":"advanced-xisixiang-test2-7","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试二","chapterKey":"综合测试二","n":7,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试二 第 7 题"},"stem":"习近平总书记指出：“如果不坚决纠正不良风气，任其发展下去，就会像一座无形的墙把我们党和人民群众隔开，我们党就会失去根基、失去血脉、失去力量。”这表明","choices":[{"id":"A","text":"艰苦奋斗、勤俭节约是我们党的优良作风"},{"id":"B","text":"全体党员必须同党中央保持高度一致，自觉维护党中央权威"},{"id":"C","text":"党的作风关系人心向背、关系党的生死存亡"},{"id":"D","text":"我们要造就高素质的党员干部队伍"}],"answer":["C"],"analysis":{"point":"本题考查以严的基调强化正风肃纪。习近平总书记指出的是作风问题的核心，即保持党同人民群众的血肉联系。党的作风关系人心向背、关系党的生死存亡。在任何时候任何情况下，与人民同呼吸共命运的立场不能变，全心全意为人民服务的宗旨不能忘，群众是真正英雄的历史唯物主义观点不能丢，始终坚持立党为公、执政为民。因此，选项C正确。","options":{"A":"都不是题干表达的意思，故不选。","B":"都不是题干表达的意思，故不选。","C":"（正确选项，分析见“解题思路”）","D":"都不是题干表达的意思，故不选。"}}},{"id":"advanced-xisixiang-test2-8","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试二","chapterKey":"综合测试二","n":8,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试二 第 8 题"},"stem":"中国特色社会主义进入新时代，我国社会主要矛盾已经转化为人民日益增长的美好生活需要和不平衡不充分的发展之间的矛盾。但是，我国社会主要矛盾的变化没有改变我们对我国社会主义所处历史阶段的判断，其依据是","choices":[{"id":"A","text":"我国仍然是世界上最大的发展中国家"},{"id":"B","text":"我国仍然面临极其复杂的国际环境"},{"id":"C","text":"我国总体上仍处于不发达阶段"},{"id":"D","text":"我国社会主要矛盾的变化只是社会主义初级阶段这个历史阶段中的变化"}],"answer":["A","C","D"],"analysis":{"point":"本题考查我国社会主要矛盾的变化。我国社会主要矛盾的变化没有改变对我国社会主义所处历史阶段的判断，我国仍处于并将长期处于社会主义初级阶段的基本国情没有变，我国是世界上最大发展中国家的国际地位没有变。因此，选项A、C、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"复杂的国际环境任何时候都存在，这并不是判断我国社会主义所处历史阶段的依据，故不选。","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-xisixiang-test2-9","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试二","chapterKey":"综合测试二","n":9,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试二 第 9 题"},"stem":"深圳经济特区是我国改革开放的排头兵和重要窗口。2019年8月，中共中央、国务院印发《关于支持深圳建设中国特色社会主义先行示范区的意见》，要求深圳建设成为高质量发展高地、法治城市示范、城市文明典范、民生幸福标杆、可持续发展先锋。支持深圳建设中国特色社会主义先行示范区，有利于","choices":[{"id":"A","text":"在更高起点、更高层次、更高目标上推进改革开放"},{"id":"B","text":"更好实施粤港澳大湾区战略，丰富“一国两制”事业发展新实践"},{"id":"C","text":"率先探索全面建设社会主义现代化强国新路径"},{"id":"D","text":"破解制约建成小康社会的重点难点问题"}],"answer":["A","B","C"],"analysis":{"point":"本题考查支持深圳建设中国特色社会主义先行示范区的意义。2019年8月，中共中央、国务院印发的《关于支持深圳建设中国特色社会主义先行示范区的意见》强调：中国特色社会主义进入新时代，支持深圳高举新时代改革开放旗帜、建设中国特色社会主义先行示范区，有利于在更高起点、更高层次、更高目标上推进改革开放，形成全面深化改革、全面扩大开放新格局；有利于更好实施粤港澳大湾区战略，丰富“一国两制”事业发展新实践；有利于率先探索全面建设社会主义现代化强国新路径，为实现中华民族伟大复兴的中国梦提供有力支撑。因此，选项A、B、C正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"破解制约建成小康社会的重点难点问题是打赢脱贫攻坚战，故不选。"}}},{"id":"advanced-xisixiang-test2-10","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试二","chapterKey":"综合测试二","n":10,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试二 第 10 题"},"stem":"习近平总书记在党的十八届三中全会上首次提出“国家治理体系和治理能力现代化”这一重大理论命题。党的十九届四中全会专门就坚持和完善中国特色社会主义制度、推进国家治理体系和治理能力现代化作出部署。党的二十届三中全会以经济体制改革为牵引对中国特色社会主义各领域改革作出重要安排，进一步深化了对推进国家治理体系和治理能力现代化的规律性认识。推进国家治理体系和治理能力现代化，必须","choices":[{"id":"A","text":"以全体人民共同富裕的基本实现为前提"},{"id":"B","text":"坚定中国特色社会主义制度自信"},{"id":"C","text":"更好发挥中国特色社会主义制度优势"},{"id":"D","text":"把中国特色社会主义制度优势转化为国家治理效能"}],"answer":["B","C","D"],"analysis":{"point":"本题考查推进国家治理体系和治理能力现代化。推进国家治理体系和治理能力现代化，必须坚定中国特色社会主义制度自信，必须更好发挥中国特色社会主义制度优势，必须把中国特色社会主义制度优势转化为国家治理效能。因此，选项B、C、D正确。","options":{"A":"全体人民共同富裕基本实现的目标规划在21世纪中叶实现，与本题涉及的推进国家治理体系和治理能力现代化之间并没有“前提”的关系，故不选。","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-xisixiang-test2-11","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试二","chapterKey":"综合测试二","n":11,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试二 第 11 题"},"stem":"2015年10月16日，中国铁路总公司牵头组成的中国企业联合体，与印度尼西亚维卡公司牵头的印尼国企联合体正式签署组建中印尼合资公司协议，该公司将负责印度尼西亚雅加达至万隆高速铁路项目的建设和运营。中国高铁走出国门、走向世界表明我国","choices":[{"id":"A","text":"传统产业结构调整得到根本性改变"},{"id":"B","text":"自主创新能力显著提高"},{"id":"C","text":"国际投资合作水平日益提升"},{"id":"D","text":"参与国际竞争能力明显增强"}],"answer":["B","C","D"],"analysis":{"point":"本题考查创新发展战略。高铁“走出去”意味着中国融入世界经济的程度在不断加深，表明中国科技进步，自主创新能力有了显著提高，“走出去”的水平和国际竞争力都有了巨大进步。因此，选项B、C、D正确。","options":{"A":"中国还在进行产业结构调整，转变经济发展方式仍在路上，不能说已经得到根本性改变，故不选。","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-xisixiang-test2-12","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试二","chapterKey":"综合测试二","n":12,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试二 第 12 题"},"stem":"当今世界，开放融通的潮流滚滚向前，经济全球化的历史大势不可逆转。推进高水平对外开放，必须","choices":[{"id":"A","text":"依托我国超大规模市场优势，以国内大循环吸引全球资源要素"},{"id":"B","text":"发展数字贸易，推动货物贸易优化升级，创新服务贸易发展机制"},{"id":"C","text":"全面取消各领域外资准入限制措施，依法保护外商投资权益"},{"id":"D","text":"深度参与全球产业分工和合作，维护多元稳定的国际经济格局和经贸关系"}],"answer":["A","B","D"],"analysis":{"point":"本题考查推进高水平对外开放。围绕“推进高水平对外开放”，党的二十大部署了以下方面：第一，依托我国超大规模市场优势，以国内大循环吸引全球资源要素，增强国内国际两个市场两种资源联动效应，提升贸易投资合作质量和水平；第二，推动货物贸易优化升级，创新服务贸易发展机制，发展数字贸易，加快建设贸易强国；第三，合理缩减外资准入负面清单，依法保护外商投资权益，营造市场化、法治化、国际化一流营商环境；第四，深度参与全球产业分工和合作，维护多元稳定的国际经济格局和经贸关系。因此，选项A、B、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"在“一带一路”八项行动中，有针对“一带一路”国家“全面取消制造业外资准入限制措施”的说法，但这里有限定词“‘一带一路’国家”和“制造业”，取消限定词，范围扩大就成了错误说法，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-xisixiang-test2-13","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试二","chapterKey":"综合测试二","n":13,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试二 第 13 题"},"stem":"在全面深化改革中，我国提出了一系列放活民间投资的普惠政策，如保障民企平等使用土地、减免税收，扩大民间投资在电网、电信、铁路等非竞争性领域的参与力度等。实施这些政策的目的是","choices":[{"id":"A","text":"允许各种所有制经济实行企业员工持股"},{"id":"B","text":"鼓励所有民企建立现代企业制度"},{"id":"C","text":"保证各种所有制经济公开公平公正参与市场竞争"},{"id":"D","text":"保证各种所有制经济依法平等使用生产要素"}],"answer":["C","D"],"analysis":{"point":"本题考查促进非公有制经济发展。中央采取的放活民间投资的普惠政策，有利于保证各种所有制经济公开公平公正参与市场竞争，在市场竞争中依法平等使用生产要素。因此，选项C、D正确。","options":{"A":"“员工持股”是企业为了发展生产而调动员工积极性的一种举措，而题干说的是国家实施政策调动企业的积极性，二者不是一回事，故不选。","B":"说法太绝对，应该是鼓励有条件的民营企业建立现代企业制度，故不选。","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-xisixiang-test2-14","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试二","chapterKey":"综合测试二","n":14,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试二 第 14 题"},"stem":"当前，以人工智能为代表的全球新一轮科技革命和产业变革快速发展，对经济、社会、军事和国际格局带来重要影响，必须推动技术创新和制度转型，巩固传统优势地位和抢占未来发展制高点。因此，在新时代新征程上，构建高水平社会主义市场经济体制是","choices":[{"id":"A","text":"保持经济合理增长，如期实现人均国内生产总值达到中等发达国家水平的必然要求"},{"id":"B","text":"抓住新一轮科技革命和产业变革机遇，加快发展新质生产力的内在要求"},{"id":"C","text":"中国式现代化的重要保障"},{"id":"D","text":"全面建设社会主义现代化国家的首要任务"}],"answer":["A","B","C"],"analysis":{"point":"本题考查构建高水平社会主义市场经济体制。构建高水平社会主义市场经济体制，是保持经济合理增长，如期实现人均国内生产总值达到中等发达国家水平的必然要求；是抓住新一轮科技革命和产业变革机遇，加快发展新质生产力的内在要求；是中国式现代化的重要保障。因此，选项A、B、C正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"说法错误，高质量发展是全面建设社会主义现代化国家的首要任务，故不选。"}}},{"id":"advanced-xisixiang-test2-15","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试二","chapterKey":"综合测试二","n":15,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试二 第 15 题"},"stem":"从统计数据来看，新质生产力在加快形成。2024年前8个月，根据知识产权相关部门数据，我国发明专利授权量同比增长20%以上，量子计算机上线、航天飞行、一些大国重器、一些重大成果在不断涌现。规模以上高技术制造业增加值前三季度同比增长9.1%，比规模以上工业增速高3.3个百分点。信息传输、软件和信息技术服务业增加值前三季度增长11.3%。数字经济加快推进，数字产品制造业增加值较快增长。加快发展新质生产力有利于","choices":[{"id":"A","text":"形成产业集群和产业链优势，进一步提升国家的整体竞争力"},{"id":"B","text":"辅助新型生产工具创造，提高生产效率，创新产品，拓展新赛道"},{"id":"C","text":"推动数字产业化、产业数字化发展，助推经济高质量发展"},{"id":"D","text":"提升教育、医疗、文化等领域的服务水平，让人民群众共享发展成果"}],"answer":["A","B","C","D"],"analysis":{"point":"本题考查发展新质生产力。加快发展新质生产力有利于形成产业集群和产业链优势，进一步提升国家的整体竞争力；有利于提升教育、医疗、文化等领域的服务水平，让人民群众共享发展成果；有利于辅助新型生产工具创造，提高生产效率，创新产品，拓展新赛道；有利于推动数字产业化、产业数字化发展，助推经济高质量发展。因此，选项A、B、C、D正确。\\n无干扰选项。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-xisixiang-test2-16","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试二","chapterKey":"综合测试二","n":16,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试二 第 16 题"},"stem":"实施西部大开发战略，是党中央、国务院总揽全局、面向新世纪作出的重大决策。党中央对新时代推进西部大开发形成新格局作出部署5年来，取得了重大成效，包括","choices":[{"id":"A","text":"区域整体实力和可持续发展能力彻底形成"},{"id":"B","text":"开放型经济格局加快构建"},{"id":"C","text":"基础设施条件大为改观"},{"id":"D","text":"人民生活水平稳步提高"}],"answer":["B","C","D"],"analysis":{"point":"本题考查西部大开发战略实施取得的成效。2024年4月23日，习近平在重庆主持召开新时代推动西部大开发座谈会时强调，党中央对新时代推进西部大开发形成新格局作出部署5年来，西部地区生态环境保护修复取得重大成效，高质量发展能力明显提升，开放型经济格局加快构建，基础设施条件大为改观，人民生活水平稳步提高，如期打赢脱贫攻坚战，同全国一道全面建成小康社会，踏上了全面建设社会主义现代化国家新征程。因此，选项B、C、D正确。","options":{"A":"说法错误，区域整体实力和可持续发展能力尚未彻底形成，故不选。","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-xisixiang-test2-17","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试二","chapterKey":"综合测试二","n":17,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试二 第 17 题"},"stem":"国有企业是中国特色社会主义的重要物质基础和政治基础，是我们党执政兴国的重要支柱和依靠力量。党的二十届三中全会指出，深化国资国企改革，推进国有经济布局优化和结构调整，推动国有资本和国有企业做强做优做大，增强核心功能，提升核心竞争力，明确国有资本重点投资领域和方向。要加快推动国有资本","choices":[{"id":"A","text":"向关系国家安全、国民经济命脉的重要行业和关键领域集中"},{"id":"B","text":"向关系国计民生的公共服务、应急能力、公益性领域等集中"},{"id":"C","text":"向我国金融行业集中"},{"id":"D","text":"向前瞻性战略性新兴产业集中"}],"answer":["A","B","D"],"analysis":{"point":"本题考查国有资本布局的“三个集中”。党的二十届三中全会指出，深化国资国企改革，推进国有经济布局优化和结构调整，推动国有资本向关系国家安全、国民经济命脉的重要行业和关键领域集中，向关系国计民生的公共服务、应急能力、公益性领域等集中，向前瞻性战略性新兴产业集中。因此，选项A、B、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"国企改革不会推动国有资本向金融行业集中，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-xisixiang-test2-18","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试二","chapterKey":"综合测试二","n":18,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试二 第 18 题"},"stem":"2024年9月27日，在喜迎中华人民共和国75周年华诞之际，全国民族团结进步表彰大会在北京召开。习近平指出，100多年来，我们坚持把马克思主义民族理论同中国民族问题具体实际相结合、同中华优秀传统文化相结合，创造性地走出了一条中国特色解决民族问题的正确道路。实践证明，中国特色解决民族问题的道路是完全正确的。这条道路","choices":[{"id":"A","text":"着眼中华民族根本利益和整体利益，最大限度把各民族凝聚起来"},{"id":"B","text":"坚持各民族一律平等，反对民族压迫和民族歧视"},{"id":"C","text":"推动中华民族成为认同度更高、凝聚力更强的命运共同体"},{"id":"D","text":"坚持统一和自治相结合、民族因素和区域因素相结合"}],"answer":["A","B","C","D"],"analysis":{"point":"本题考查我国的民族工作。习近平在全国民族团结进步表彰大会上的讲话中提出，实践证明，中国特色解决民族问题的道路是完全正确的。这条道路着眼中华民族根本利益和整体利益，最大限度把各民族凝聚起来，实现各民族共同团结奋斗、共同繁荣发展；这条道路坚持各民族一律平等，反对民族压迫和民族歧视，确保各族人民真正获得平等政治权利、共同当家做主人；这条道路正确把握维护国家统一和实行民族区域自治的关系，坚持统一和自治相结合、民族因素和区域因素相结合，推动中华民族成为认同度更高、凝聚力更强的命运共同体。因此，选项A、B、C、D正确。\\n无干扰选项。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-xisixiang-test2-19","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试二","chapterKey":"综合测试二","n":19,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试二 第 19 题"},"stem":"“实现民主有多种方式，不可能千篇一律。”从城乡社区里的村（居）民议事会、村（居）民论坛、民主恳谈会、民主听证会到党代表、人大代表、政协委员联合进社区，从“小院议事厅”到“板凳民主”，从线下“圆桌会”到线上“议事群”，这些充满烟火气的民主实现形式","choices":[{"id":"A","text":"保障了基层群众广泛、直接、有效行使民主权利"},{"id":"B","text":"彰显了人民当家作主的广泛性、真实性、有效性"},{"id":"C","text":"为社会长期稳定提供了重要法治保障"},{"id":"D","text":"是全过程人民民主的重要体现"}],"answer":["A","B","D"],"analysis":{"point":"本题考查基层民主的重大意义。基层民主是全过程人民民主的重要体现。基层民主的建立和发展，保障了基层群众广泛、直接、有效行使民主权利，彰显了人民当家作主的广泛性、真实性、有效性。从城乡社区里的村（居）民议事会、村（居）民论坛、民主恳谈会、民主听证会到党代表、人大代表、政协委员联合进社区，从“小院议事厅”到“板凳民主”，从线下“圆桌会”到线上“议事群”，广大人民群众在火热的基层生活中，摸索创造了一个又一个充满烟火气的民主实现形式。人民群众通过这些接地气、聚人气的民主实践，围绕涉及自身利益的实际问题，发表意见建议，进行广泛协商，利益得到协调，矛盾有效化解，为我国社会长期稳定提供了重要政治基础和制度保障。广大人民群众最直接的政治参与主要在基层，最直观的当家作主感受也主要在基层。发展基层民主，是实现人民有效政治参与的重要渠道，是人民当家作主的有效途径，是社会主义民主最广泛的实践。因此，选项A、B、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"虽然民主与法治相伴相生，但二者不能混淆。民主决定了法治的价值和效能，而法治则为民主提供规则和保障。基层民主为我国社会长期稳定提供了重要政治基础和制度保障，而不是“法治保障”，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-xisixiang-test2-20","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试二","chapterKey":"综合测试二","n":20,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试二 第 20 题"},"stem":"中国共产党领导的多党合作和政治协商制度是中国共产党、中国人民和各民主党派、无党派人士的伟大政治创造，是从中国土壤中生长出来的新型政党制度。之所以说它是新型政党制度，是因为","choices":[{"id":"A","text":"它是马克思主义政党理论同中国实际相结合的产物"},{"id":"B","text":"它把各个政党和无党派人士紧密团结起来、为着共同目标而奋斗"},{"id":"C","text":"它有效避免了一党缺乏监督或者多党轮流坐庄、恶性竞争的弊端"},{"id":"D","text":"它通过制度化、程序化、规范化的安排集中各种意见和建议、推动决策科学化民主化"}],"answer":["A","B","C","D"],"analysis":{"point":"本题考查中国共产党领导的多党合作和政治协商制度。中国共产党领导的多党合作和政治协商制度是中国共产党、中国人民和各民主党派、无党派人士的伟大政治创造，是从中国土壤中生长出来的新型政党制度。说它是新型政党制度，新就新在它是马克思主义政党理论同中国实际相结合的产物，能够真实、广泛、持久代表和实现最广大人民根本利益、全国各族各界根本利益，有效避免了旧式政党制度代表少数人、少数利益集团的弊端；新就新在它把各个政党和无党派人士紧密团结起来、为着共同目标而奋斗，有效避免了一党缺乏监督或者多党轮流坐庄、恶性竞争的弊端；新就新在它通过制度化、程序化、规范化的安排集中各种意见和建议、推动决策科学化民主化，有效避免了旧式政党制度囿于党派利益、阶级利益、区域和集团利益决策施政导致社会撕裂的弊端。因此，选项A、B、C、D正确。\\n无干扰选项。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-xisixiang-test2-21","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试二","chapterKey":"综合测试二","n":21,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试二 第 21 题"},"stem":"增进人民福祉、促进人的全面发展是我们党立党为公、执政为民的本质要求。党的十九届四中全会提出“完善覆盖全民的社会保障体系”，建立健全社会保障体系的必要性在于","choices":[{"id":"A","text":"是社会主义市场经济发展的客观需要"},{"id":"B","text":"是实现社会全面进步的需要"},{"id":"C","text":"是转换企业经营机制，搞活企业的需要"},{"id":"D","text":"是保持社会稳定和国家长治久安的需要"}],"answer":["A","B","C","D"],"analysis":{"point":"本题考查建立健全社会保障体系。建立健全社会保障体系的必要性在于：第一，是社会主义市场经济发展的客观需要；第二，是转换企业经营机制，搞活企业的需要；第三，是实现社会全面进步的需要；第四，是保持社会稳定和国家长治久安的需要。因此，选项A、B、C、D正确。\\n无干扰选项。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-xisixiang-test2-22","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试二","chapterKey":"综合测试二","n":22,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试二 第 22 题"},"stem":"建设社会主义文化强国，是我们党准确把握时代和形势发展变化、积极回应各族人民精神文化需求作出的重大战略决策。深化文化体制改革，要坚持公益性文化事业和经营性文化产业协调发展。发展公益性文化事业要","choices":[{"id":"A","text":"加强公共文化服务设施建设"},{"id":"B","text":"实施重点文化惠民工程"},{"id":"C","text":"充分发挥市场配置资源的决定性作用"},{"id":"D","text":"推进城乡公共文化服务体系一体建设"}],"answer":["A","B","D"],"analysis":{"point":"本题考查文化建设。发展文化事业、提升公共文化服务水平，是保障人民文化权益、改善人民生活品质、补齐文化发展短板的重要途径。要坚持政府主导、社会参与、重心下移、共建共享，推进城乡公共文化服务体系一体建设，加强公共文化服务设施建设，实施国家文化数字化战略，提升公共文化服务数字化水平，实施重点文化惠民工程。因此，选项A、B、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"发展公益性文化事业主要以政府为主导，与市场关系不大，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-xisixiang-test2-23","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试二","chapterKey":"综合测试二","n":23,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试二 第 23 题"},"stem":"社会组织是我国社会主义现代化建设的重要力量，是党的工作和群众工作的重要阵地，是党的基层组织建设的重要领域。为此，中共中央办公厅专门印发《关于加强社会组织党的建设工作的意见（试行）》，就加强社会组织党的建设工作提出了要求。加强社会组织党建工作有利于","choices":[{"id":"A","text":"引领社会组织正确发展方向，激发社会组织活力"},{"id":"B","text":"增强党的阶级基础、扩大党的群众基础、夯实党的执政基础"},{"id":"C","text":"促进社会组织在国家治理体系和治理能力现代化进程中更好发挥作用"},{"id":"D","text":"实现社会组织管理层党员化，实现党对社会组织具体事务的直接领导"}],"answer":["A","B","C"],"analysis":{"point":"本题考查社会组织中的党建工作。随着改革开放不断深入，我国社会组织快速发展，已成为社会主义现代化建设的重要力量、党的工作和群众工作的重要阵地。中共中央办公厅印发的《关于加强社会组织党的建设工作的意见（试行）》中指出，加强社会组织党建工作，对于引领社会组织正确发展方向，激发社会组织活力，促进社会组织在国家治理体系和治理能力现代化进程中更好发挥作用；对于把社会组织及其从业人员紧密团结在党的周围，不断扩大党在社会组织的影响力，增强党的阶级基础、扩大党的群众基础、夯实党的执政基础，都具有重要意义。因此，选项A、B、C正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"社会组织中的党建工作主要是政治领导，而不是对所有具体事务的直接领导，不可能取代管理层的领导地位，更不可能架空非党员社会组织负责人的权力，故不选。"}}},{"id":"advanced-xisixiang-test2-24","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试二","chapterKey":"综合测试二","n":24,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试二 第 24 题"},"stem":"习近平指出，环境就是民生，青山就是美丽，蓝天也是幸福。要着力推动生态环境保护，像保护眼睛一样保护生态环境，像对待生命一样对待生态环境。着力解决突出的环境问题，打赢环境治理攻坚战，要求我们","choices":[{"id":"A","text":"强化土壤污染管控和修复"},{"id":"B","text":"加快水污染治理"},{"id":"C","text":"打赢蓝天保卫战"},{"id":"D","text":"持续实施大气污染防治行动"}],"answer":["A","B","C","D"],"analysis":{"point":"本题考查解决突出环境问题的措施。着力解决突出的环境问题，聚焦环境保护的重点，打赢环境治理攻坚战，要求我们坚持全民共治、源头防治，持续实施大气污染防治行动，打赢蓝天保卫战，加快水污染治理，强化土壤污染管控和修复。因此，选项A、B、C、D正确。\\n无干扰选项。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-xisixiang-test2-25","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试二","chapterKey":"综合测试二","n":25,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试二 第 25 题"},"stem":"我国电力供给朝着清洁低碳、安全充裕的方向加速推进。根据《中国电力发展报告2024》，截至2023年年底，全国发电装机容量29.2亿千瓦，同比增长13.9%；全国发电量9.3万亿千瓦时，同比增长6.7%；“西电东送”规模达3亿千瓦，较上年增长约400万千瓦。非化石能源发电装机突破15.7亿千瓦，同比增长23.9%，占全国总装机53.9%，历史性地超过火电装机。我国电力的发展充分表明","choices":[{"id":"A","text":"生态环境问题归根到底是经济发展方式和生活方式问题"},{"id":"B","text":"我国已经广泛形成绿色生产生活方式"},{"id":"C","text":"调整优化经济结构是从源头推动发展方式绿色转型的重要任务"},{"id":"D","text":"推进“双碳”工作是实现可持续发展的迫切需要"}],"answer":["A","C","D"],"analysis":{"point":"本题考查绿色发展。生态环境问题归根到底是经济发展方式和生活方式问题，调整优化经济结构是从源头推动发展方式绿色转型的重要任务。推进“双碳”工作是破解资源环境约束突出问题、实现可持续发展的迫切需要，是一场广泛而深刻的经济社会系统性变革。因此，选项A、C、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"时态错误，广泛形成绿色生产生活方式是我国2035年的目标，故不选。","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-xisixiang-test2-26","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试二","chapterKey":"综合测试二","n":26,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试二 第 26 题"},"stem":"生态兴则文明兴，生态衰则文明衰。党的十八大以来，以习近平同志为核心的党中央以前所未有的力度抓生态文明建设，中国在实现世所罕见的经济快速发展奇迹和社会长期稳定奇迹的同时，取得了举世瞩目的绿色发展奇迹，为全面建成小康社会增添了绿色底色和质量成色。我们之所以高度重视生态环境，是因为","choices":[{"id":"A","text":"生态文明建设是关系党的使命宗旨的重大政治问题"},{"id":"B","text":"良好的生态环境是最普惠的民生福祉"},{"id":"C","text":"生态环境建设是新时代我国经济社会发展的鲜明主题"},{"id":"D","text":"生态环境变化直接影响文明的兴衰演替"}],"answer":["A","B","D"],"analysis":{"point":"本题考查生态文明建设。生态文明建设是关系党的使命宗旨的重大政治问题。良好的生态环境是最普惠的民生福祉，也是人类生存和发展的根基，其变化直接影响文明的兴衰演替。因此，选项A、B、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"高质量发展是新时代我国经济社会发展的鲜明主题，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-xisixiang-test2-27","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试二","chapterKey":"综合测试二","n":27,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试二 第 27 题"},"stem":"2024年是习近平总书记创造性提出总体国家安全观十周年。十年来，总体国家安全观与时俱进、日臻完善，指引新时代国家安全工作取得历史性成就、发生历史性变革。随着实践深入而不断丰富发展，总体国家安全观","choices":[{"id":"A","text":"展现了独具特色的鲜明理论品格"},{"id":"B","text":"彰显出强大的真理力量和实践伟力"},{"id":"C","text":"着眼于全世界各国人民追求和平与发展的梦想"},{"id":"D","text":"指引我国国家安全得到全面加强"}],"answer":["A","B","D"],"analysis":{"point":"本题考查总体国家安全观。十年来，总体国家安全观随着实践深入而不断丰富发展，展现了独具特色的鲜明理论品格，彰显出强大的真理力量和实践伟力，指引我国国家安全得到全面加强，中国特色国家安全道路越走越宽广。因此，选项A、B、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"总体国家安全观是关于中国安全的问题，虽然与世界安全有一定的联系，但并非着眼于全世界各国人民追求和平与发展的梦想，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-xisixiang-test2-28","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试二","chapterKey":"综合测试二","n":28,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试二 第 28 题"},"stem":"“和平统一、一国两制”的构想是充分尊重历史和现实、照顾各方利益、维护民族团结、实现祖国完全统一的科学构想。其具体含义包括","choices":[{"id":"A","text":"以祖国统一为前提"},{"id":"B","text":"国家的主体坚持社会主义制度"},{"id":"C","text":"“九二共识”是台海两岸的选项之一"},{"id":"D","text":"香港、澳门、台湾保持原有的资本主义制度长期不变"}],"answer":["A","B","D"],"analysis":{"point":"本题考查“一国两制”。“和平统一、一国两制”是一个完整的体系，其基本内容就是在祖国统一的前提下，国家的主体坚持社会主义制度，同时在香港、澳门、台湾保持原有的资本主义制度长期不变。因此，选项A、B、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"“九二共识”是台海两岸关系发展的基础和前提，不是选项之一，而是唯一选项，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-xisixiang-test2-29","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试二","chapterKey":"综合测试二","n":29,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试二 第 29 题"},"stem":"“一国两制”是香港、澳门回归后保持长期繁荣稳定的最佳制度安排。中国特色社会主义进入了新时代，意味着“一国两制”事业也进入了新时代。必须准确把握“一国两制”的科学内涵，坚持和完善“一国两制”制度体系，确保“一国两制”行稳致远。下列关于“一国”与“两制”的关系表述正确的有","choices":[{"id":"A","text":"“两制”从属和派生于“一国”"},{"id":"B","text":"“一国”底线越牢，“两制”空间就越大"},{"id":"C","text":"“一国”之内的“两制”是等量齐观、比肩并列的"},{"id":"D","text":"“一国”是实行“两制”的前提和基础"}],"answer":["A","B","D"],"analysis":{"point":"本题考查“一国两制”。“一国”是实行“两制”的前提和基础，“两制”从属和派生于“一国”，并统一于“一国”之内。“一国”底线越牢，“两制”空间就越大。因此，选项A、B、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"表述错误，“一国”之内的“两制”并非等量齐观、比肩并列，国家的主体必须实行社会主义制度，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-xisixiang-test2-30","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试二","chapterKey":"综合测试二","n":30,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试二 第 30 题"},"stem":"“一带一路”倡议提出三年来，已经有100多个国家和国际组织参与其中，我国同沿线30多个国家签署共建合作协议、与20多个国家开展了国际产能合作，一批有影响力的标志性项目逐步落地。截至2016年7月，我国对“一带一路”相关国家的投资累计已达511亿美元，占同期对外直接投资总额的12%，与沿线国家新签承包工程合同1.25万份，累计合同额2 790亿美元。我国推进“一带一路”建设旨在","choices":[{"id":"A","text":"统筹国内国际两个大局"},{"id":"B","text":"打造开放、包容、均衡、普惠的区域经济合作架构"},{"id":"C","text":"促进沿线各国共同繁荣"},{"id":"D","text":"探索国际合作及全球治理新模式"}],"answer":["A","B","C","D"],"analysis":{"point":"本题考查“一带一路”。“一带一路”是统筹国内国际两个大局的重大战略，是扩大和深化对外开放的重大举措，也是加强和亚欧非及世界各国互利合作，促进共同发展，实现共同繁荣、文明互鉴的重大举措。“一带一路”旨在促进经济要素有序自由流动、资源高效配置和市场深度融合，推动沿线各国实现经济政策协调，开展更大范围、更高水平、更深层次的区域合作，共同打造开放、包容、均衡、普惠的区域经济合作架构。共建“一带一路”符合国际社会的根本利益，彰显人类社会共同理想和美好追求，是对国际合作以及全球治理新模式的积极探索。因此，选项A、B、C、D正确。\\n无干扰选项。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-xisixiang-test3-1","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试三","chapterKey":"综合测试三","n":1,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试三 第 1 题"},"stem":"推动更多资金资源“投资于人”、服务于民生，是“坚持以人民为中心”和“发展为了人民”的生动体现。2025年，我国不断强化宏观政策的民生导向，财政对民生领域的投入力度进一步加大。中央财政安排困难群众救助补助资金1 566.8亿元，用于支持各地及时发放救助金，落实对特困人员、低保对象等困难群体的兜底保障政策；基本公共卫生服务经费人均财政补助标准进一步提高，达到每人每年99元；城乡居民医保人均财政补助标准再增加30元，达到每人每年700元，基本医保参保率稳定在95%以上。这些举措体现了","choices":[{"id":"A","text":"初次分配的基础性作用进一步巩固"},{"id":"B","text":"再分配调节作用的精准性显著提高"},{"id":"C","text":"社会充分发挥了第三次分配的作用"},{"id":"D","text":"我国基本实现了共同富裕"}],"answer":["B"],"analysis":{"point":"本题考查完善分配制度。题干中，通过转移支付、社会保障等举措，中央财政有效保障了特定困难群体的基本生活，减轻了人民的医疗负担。这体现了再分配调节作用的精准性显著提高。因此，选项B正确。","options":{"A":"初次分配主要指的是市场按生产要素的贡献决定收入，故不选。","B":"（正确选项，分析见“解题思路”）","C":"第三次分配主要是以社会公益慈善方式进行分配，故不选。","D":"我国到21世纪中叶才能基本实现共同富裕，故不选。"}}},{"id":"advanced-xisixiang-test3-2","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试三","chapterKey":"综合测试三","n":2,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试三 第 2 题"},"stem":"党的二十届三中全会提出，深化国资国企改革，完善管理监督体制机制，增强各有关管理部门战略协同，推进国有经济布局优化和结构调整，推动国有资本和国有企业做强做优做大，增强核心功能，提升核心竞争力。国有经济之所以能够发挥战略支撑作用，从根本上说，是因为国有经济","choices":[{"id":"A","text":"对经济发展起主导作用，关系国家安全和国民经济命脉"},{"id":"B","text":"通过混合所有制改革，增强了市场竞争力和抗风险能力"},{"id":"C","text":"数量众多，贡献了巨大的国内生产总值和税收收入"},{"id":"D","text":"种类丰富，几乎覆盖了国民经济中的所有行业领域"}],"answer":["A"],"analysis":{"point":"本题考查国有经济的主导作用。国有经济之所以能够发挥战略支撑作用，从根本上说，是因为国有经济对经济发展起主导作用，这种主导作用主要体现在对关系国家安全和国民经济命脉的重要行业和关键领域的控制力上。因此，选项A正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"通过混合所有制改革增强市场竞争力和抗风险能力，这并非国有经济能够发挥战略支撑作用的原因，而是为了让其更好发挥战略支撑作用的举措，故不选。","C":"国有经济确实贡献了巨大的国内生产总值和税收收入，但民营经济同样也是国内生产总值和税收收入的重要来源，国有经济的战略支撑作用主要来自其控制力，而非数量规模，故不选。","D":"覆盖所有行业领域不符合当前的国资国企改革方向，党的二十届三中全会提出，推动国有资本向关系国家安全、国民经济命脉的重要行业和关键领域集中，向关系国计民生的公共服务、应急能力、公益性领域等集中，向前瞻性战略性新兴产业集中，故不选。"}}},{"id":"advanced-xisixiang-test3-3","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试三","chapterKey":"综合测试三","n":3,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试三 第 3 题"},"stem":"进入21世纪，党中央根据经济发展的实际情况，进一步提出了继续推进西部大开发、振兴东北老工业基地、促进中部崛起、鼓励东部地区率先发展以及建设长江经济带的战略布局。这是为了","choices":[{"id":"A","text":"转变经济发展方式"},{"id":"B","text":"加快城镇化进程"},{"id":"C","text":"增强自主创新能力"},{"id":"D","text":"促进区域协调发展"}],"answer":["D"],"analysis":{"point":"本题考查区域协调发展。党中央指出，调整经济结构必须以改善需求结构、优化产业结构、促进区域协调发展、推进城镇化为重点，着力解决制约经济持续健康发展的重大结构性问题。为了促进区域协调发展，党中央根据经济发展的实际情况，进一步提出了继续推进西部大开发、振兴东北老工业基地、促进中部崛起、鼓励东部地区率先发展以及建设长江经济带的战略布局。因此，选项D正确。","options":{"A":"与题意不符，故不选。","B":"与题意不符，故不选。","C":"与题意不符，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-xisixiang-test3-4","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试三","chapterKey":"综合测试三","n":4,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试三 第 4 题"},"stem":"多民族是我国的一大特色。在历史演进中，我国各民族之间形成了你中有我、我中有你、谁也离不开谁的多元一体格局。因此，要促进各民族像石榴籽一样紧紧抱在一起，就必须","choices":[{"id":"A","text":"加强各民族交往交流交融，逐渐消除各民族之间的差别"},{"id":"B","text":"倡导各民族独立自治，巩固和发展平等团结互助和谐的社会主义民族关系"},{"id":"C","text":"深化民族团结进步教育，铸牢中华民族共同体意识"},{"id":"D","text":"强化政策激励，促进少数民族同胞优先发展"}],"answer":["C"],"analysis":{"point":"本题考查处理民族问题的基本政策。习近平总书记在党的二十大报告中重申了处理民族问题的基本政策，即“深化民族团结进步教育，铸牢中华民族共同体意识”。因此，选项C正确。","options":{"A":"前半句话“加强各民族交往交流交融”是正确的，但这并不意味着要消除各民族之间的差别，故不选。","B":"后半句话“巩固和发展平等团结互助和谐的社会主义民族关系”是正确的，我国的基本政治制度之一是民族区域自治制度，但绝不是倡导各民族独立自治，故不选。","C":"（正确选项，分析见“解题思路”）","D":"我国各民族的地位是平等的，不存在哪个民族“优先发展”的问题，应该共同团结奋斗、共同繁荣发展，故不选。"}}},{"id":"advanced-xisixiang-test3-5","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试三","chapterKey":"综合测试三","n":5,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试三 第 5 题"},"stem":"基础不牢，地动山摇。习近平指出，基层强则国家强，基层安则天下安，必须抓好基层治理现代化这项基础性工作。基层治理是国家治理的基石，社会治理最基本的单元是","choices":[{"id":"A","text":"城乡社区"},{"id":"B","text":"县级政府"},{"id":"C","text":"市级政府"},{"id":"D","text":"基层党组织"}],"answer":["A"],"analysis":{"point":"本题考查社会治理。基层治理是国家治理的基石，城乡社区是社会治理最基本的单元，是党和政府联系、服务居民群众的“最后一公里”。社会治理的重心必须向基层下移，落实到城乡社区，有效防范化解社会矛盾和风险。因此，选项A正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"与题意不符，故不选。","C":"与题意不符，故不选。","D":"与题意不符，故不选。"}}},{"id":"advanced-xisixiang-test3-6","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试三","chapterKey":"综合测试三","n":6,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试三 第 6 题"},"stem":"产业链供应链是现代经济的重要形态，近年来，我国围绕产业链供应链的韧性和安全水平提升开展一系列补链强链延链工作。但也要看到，我国产业链供应链大而不强、全而不精、韧中有脆，仍存在一系列亟待解决的问题，比如，关键环节创新能力不足、生产要素运输效率不高、数字经济赋能效果有待提升、需求端驱动力不足等。我国之所以聚焦这些短板弱项，打通产业链供应链卡点、堵点、断点，确保产业链供应链安全稳定，是因为","choices":[{"id":"A","text":"只要提升产业链供应链韧性和安全水平就能保证经济安全"},{"id":"B","text":"产业链供应链稳定安全是增强维护国家安全能力的重要环节"},{"id":"C","text":"经济安全是人民群众安全感的晴雨表"},{"id":"D","text":"我国产业链供应链安全问题已经外溢为区域性安全问题"}],"answer":["B"],"analysis":{"point":"本题考查维护重点领域国家安全。提升产业链供应链韧性和安全水平属于维护经济安全的措施，而经济安全属于重点领域国家安全。因此，选项B正确。","options":{"A":"说法错误，经济安全包含很多方面，产业链供应链的安全只是其中之一。","B":"（正确选项，分析见“解题思路”）","C":"说法错误，社会安全与人民群众切身利益关系最密切，是人民群众安全感的晴雨表。","D":"说法错误，与事实不符。"}}},{"id":"advanced-xisixiang-test3-7","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试三","chapterKey":"综合测试三","n":7,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试三 第 7 题"},"stem":"习近平强调：“我们党的执政基础很牢固，但如果作风问题解决不好，也有可能出现‘霸王别姬’这样的时刻。”当前，在全党开展深入贯彻中央八项规定精神学习教育，是我们党加强作风建设的重要抓手。作风问题的核心是","choices":[{"id":"A","text":"马克思主义政党的根本要求"},{"id":"B","text":"党同人民群众的关系问题"},{"id":"C","text":"党性问题"},{"id":"D","text":"党的基础性建设"}],"answer":["B"],"analysis":{"point":"本题考查党的作风建设。作风问题的核心是党同人民群众的关系问题。加强作风建设，必须紧紧围绕保持党同人民群众的血肉联系，增强群众观念和群众感情，不断厚植党执政的群众基础。要锲而不舍落实中央八项规定精神，持续深化纠治形式主义、官僚主义、享乐主义和奢靡之风，反对特权思想和特权现象。要弘扬党的光荣传统和优良作风，涵养“三严三实”、清正廉洁的新风正气，促进党员干部特别是领导干部带头深入调查研究，扑下身子干实事、谋实招、求实效。因此，选项B正确。","options":{"A":"旗帜鲜明讲政治是我们党作为马克思主义政党的根本要求，故不选。","B":"（正确选项，分析见“解题思路”）","C":"作风问题本质上是党性问题，中国共产党人的党性，是党的性质宗旨、理想信念和初心使命的具体体现，是党员干部立身、立业、立言、立德的基石，故不选。","D":"思想建设是党的基础性建设，故不选。"}}},{"id":"advanced-xisixiang-test3-8","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试三","chapterKey":"综合测试三","n":8,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试三 第 8 题"},"stem":"中国特色社会主义进入新时代，人民群众的新期待内容更广泛，不仅关注“有没有”，更关注“好不好”；不仅包括既有的物质文化需求，更包括在此基础上衍生出来的获得感、幸福感、安全感及尊严、权利等新需求。这一变化表明","choices":[{"id":"A","text":"我国社会主要矛盾发生了历史性变化"},{"id":"B","text":"我国已经满足了人民“从有到优”的需求"},{"id":"C","text":"人民群众对日益增长的物质文化需要出现了阶段性新特征"},{"id":"D","text":"我国不平衡不充分的发展已成为制约满足人民需要的主要根源"}],"answer":["A","C","D"],"analysis":{"point":"本题考查新时代我国社会的主要矛盾。党的十九大报告中指出：“中国特色社会主义进入新时代，我国社会主要矛盾已经转化为人民日益增长的美好生活需要和不平衡不充分的发展之间的矛盾。”人民生活水平显著提高，对美好生活的向往更加强烈，不仅对物质文化生活提出了更高要求，而且在民主、法治、公平、正义、安全、环境等方面的要求日益增长。这说明，人民群众日益增长的“物质文化需要”层次更高、内容范围更广，出现了阶段性新特征。同时，我国社会生产力水平总体上显著提高，社会生产能力在很多方面进入世界前列，更加突出的问题是发展不平衡不充分，这已经成为满足人民日益增长的美好生活需要的主要制约因素。必须认识到，我国社会主要矛盾的变化是关系全局的历史性变化，对党和国家工作提出了许多新要求。因此，选项A、C、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"我国现在还没有满足人民从“从有到优”的需求，故不选。","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-xisixiang-test3-9","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试三","chapterKey":"综合测试三","n":9,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试三 第 9 题"},"stem":"习近平明确指出：“在当今中国，没有大于中国共产党的政治力量或其他什么力量。党政军民学，东西南北中，党是领导一切的，是最高的政治领导力量。”这一论断深刻阐明了中国共产党在国家政治生活中的领导核心地位。坚持党作为最高政治领导力量","choices":[{"id":"A","text":"是新时代坚持和发展中国特色社会主义的根本动力"},{"id":"B","text":"对于实现中华民族伟大复兴具有根本性意义"},{"id":"C","text":"是国家和民族兴旺发达的根本所在"},{"id":"D","text":"是全国各族人民幸福安康的根本所在"}],"answer":["B","C","D"],"analysis":{"point":"本题考查中国共产党是最高政治领导力量。坚持党作为最高政治领导力量，是国家和民族兴旺发达的根本所在，是全国各族人民幸福安康的根本所在，对于实现中华民族伟大复兴具有根本性意义。因此，选项B、C、D正确。","options":{"A":"全面深化改革开放，是新时代坚持和发展中国特色社会主义的根本动力，故不选。","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-xisixiang-test3-10","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试三","chapterKey":"综合测试三","n":10,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试三 第 10 题"},"stem":"根据《“十四五”高质量发展答卷》可知，“十四五”期间，我国货物贸易规模连续跨过5万亿美元、6万亿美元两大台阶，2024年达6.16万亿美元，较“十三五”末增长32.4%，连续8年稳居全球第一。五年来，我国外贸在全球变局中逆势上扬，顶住压力、稳中提质，不仅“做大了体量”，也“做强了结构”，更“锻造了韧性”，贸易强国建设步伐加快。我国贸易高质量发展充分说明","choices":[{"id":"A","text":"扩大高水平对外开放是全面建设社会主义现代化国家的首要任务"},{"id":"B","text":"高水平对外开放是促进深层次改革、推动高质量发展的强大动力"},{"id":"C","text":"高水平对外开放是应对外部环境不确定性的战略选择"},{"id":"D","text":"以开放促改革、促发展是我国发展不断取得新成就的重要法宝"}],"answer":["B","C","D"],"analysis":{"point":"本题考查对外开放。开放是中国式现代化的鲜明标识，扩大高水平对外开放是中国经济实现高质量发展的必由之路，以开放促改革、促发展是我国发展不断取得新成就的重要法宝。高水平对外开放是促进深层次改革、推动高质量发展的强大动力。高水平对外开放是应对外部环境不确定性、提升国家安全保障能力的战略选择。因此，选项B、C、D正确。","options":{"A":"高质量发展是新时代我国经济社会发展的鲜明主题，是全面建设社会主义现代化国家的首要任务，故不选。","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-xisixiang-test3-11","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试三","chapterKey":"综合测试三","n":11,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试三 第 11 题"},"stem":"国家治理体系是在党领导下管理国家的制度体系，是一整套紧密相连、相互协调的国家制度；国家治理能力则是运用国家制度管理社会各方面事务的能力。二者的关系主要表现为","choices":[{"id":"A","text":"提高国家治理能力可以充分发挥国家治理体系的效能"},{"id":"B","text":"好的国家治理体系可以提高国家治理能力"},{"id":"C","text":"国家治理体系和治理能力是相辅相成的有机整体"},{"id":"D","text":"国家治理体系越完备，国家治理能力就一定越强"}],"answer":["A","B","C"],"analysis":{"point":"本题考查国家治理体系和治理能力的关系。治理国家，制度是起根本性、全局性和长远性作用的，但没有有效的治理能力，再好的制度也难以发挥作用。好的国家治理体系有利于提高治理能力，好的国家治理能力有利于完善国家治理体系，二者是相辅相成、相互促进的。因此，选项A、B、C正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"错在“一定”二字，完备的国家治理体系有利于提高国家治理能力，但并不是国家治理体系越完备，国家治理能力就一定越强，二者不能简单等同，故不选。"}}},{"id":"advanced-xisixiang-test3-12","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试三","chapterKey":"综合测试三","n":12,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试三 第 12 题"},"stem":"20世纪70年代末，中国在改革的同时开始实行对外开放，并逐步把它作为一项长期坚持的基本国策。在推进全面深化改革中必须坚持扩大开放，这是因为","choices":[{"id":"A","text":"越开放越发展，越发展越开放是世界历史的发展规律"},{"id":"B","text":"一个国家要发展繁荣，必须把握和顺应全球经济的开放大势"},{"id":"C","text":"要想在国际分工和国际竞争中获取最大利益，必须实行更加开放的政策"},{"id":"D","text":"对外开放是融入世界、促进自身快速发展的权宜之计"}],"answer":["A","B","C"],"analysis":{"point":"本题考查在推进全面深化改革中必须坚持扩大开放。这是因为：第一，总结中国发展的历史经验和教训，必须坚持对外开放基本国策，扩大对外开放；第二，把握经济全球化大势和科技发展机遇，必须坚持对外开放基本国策，扩大对外开放。现在的世界是开放的世界，一个国家要发展繁荣，必须把握和顺应世界大势。在以信息化为基础的新技术革命推动下，世界经济联系越发紧密，各国经济相互依赖和利益交融程度进一步加深，为了在国际分工和国际竞争中获取最大利益，各国纷纷实行更加开放的政策。因此，选项A、B、C正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"中国对外开放的大门永远不会关上，不但不会关上，而且会在更大范围、更宽领域、更深层次上开放。因此，中国的对外开放不是权宜之计，而是必须长期坚持的基本国策，故不选。"}}},{"id":"advanced-xisixiang-test3-13","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试三","chapterKey":"综合测试三","n":13,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试三 第 13 题"},"stem":"积极发展混合所有制经济，是完善我国基本经济制度的重要途径。2017年9月11日，我国首条由民营资本控股的高铁——杭绍台高铁项目在浙江杭州签约。该项目预计总投资超过400亿元，其中，民营联合体占比51%，中国铁路总公司占比15%，各级地方政府合计占比34%。本项目坚持风险分担、利益共享原则，构建政府和社会资本都能接受的投资回报机制。这是我国发展混合所有制经济的一个典型案例。发展混合所有制经济有利于","choices":[{"id":"A","text":"各种所有制企业公平参与市场竞争"},{"id":"B","text":"各种所有制资本取长补短、互相促进、共同发展"},{"id":"C","text":"发挥国有资本的带动力和影响力"},{"id":"D","text":"改善企业股权结构和公司治理结构"}],"answer":["A","B","C","D"],"analysis":{"point":"本题考查混合所有制经济。混合所有制经济是基本经济制度的重要实现形式，是坚持公有制主体地位，增强国有经济活力、控制力、影响力的一个有效途径和必然选择。发展国有资本、集体资本、非公有资本等交叉控股、相互融合的混合所有制经济，有利于国有资本放大功能、保值增值、提高竞争力，有利于各种所有制企业公平参与市场竞争，有利于改善企业股权结构和公司治理结构，有利于各种所有制资本取长补短、相互促进、共同发展。因此，选项A、B、C、D正确。\\n无干扰选项。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-xisixiang-test3-14","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试三","chapterKey":"综合测试三","n":14,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试三 第 14 题"},"stem":"党中央对公有制主体地位及其实现形式提出了一系列新的论断和阐述。国有资本、集体资本、非公有资本等交叉持股、相互融合的混合所有制经济，是基本经济制度的重要实现形式，有利于国有资本放大功能、保值增值、提高竞争力，有利于各种所有制资本取长补短、相互促进、共同发展。对此必须","choices":[{"id":"A","text":"实现公有制在经营方式和资产组织形式上的多样化"},{"id":"B","text":"把混合所有制作为公有制的主要实现形式"},{"id":"C","text":"让公有制经济控制所有经济领域和行业"},{"id":"D","text":"将公有制实现形式作为经济制度的本质属性来看待"}],"answer":["A","B"],"analysis":{"point":"本题考查公有制的实现形式。实现形式要解决的是发展生产力的组织形式和经营方式问题，只要有利于生产力的发展，公有制的实现形式可以而且应当多样化，一切反映社会化生产规律的组织形式和经营方式都可以大胆利用，把混合所有制作为公有制的主要实现形式。要根据社会化生产规律的要求，采取多样化的经营方式和资产组织形式，使国有经济在更大的范围获得广阔的发展空间。因此，选项A、B正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"坚持公有制的主体地位，主要体现在两个方面：一是公有资产在社会总资产中占优势；二是国有经济控制国民经济命脉，对经济发展起主导作用。但不是让公有制经济控制所有经济领域和行业。表述错误，故不选。","D":"实现形式与本质属性属于两种概念范畴，所有制的实现形式是采取怎样的经营方式和组织形式问题，不具有“公”与“私”、“社”与“资”的区分。表述错误，故不选。"}}},{"id":"advanced-xisixiang-test3-15","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试三","chapterKey":"综合测试三","n":15,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试三 第 15 题"},"stem":"当前，我国农村消费市场不断扩大，农村消费条件也在逐渐改善。数据显示，2025年上半年，我国农村居民人均可支配收入11 936元，增长5.9%，扣除价格因素，实际增长6.2%；农村居民人均消费支出9 733元，增长5.8%，扣除价格因素，实际增长6.1%，增速远高于城镇。这表明","choices":[{"id":"A","text":"农村消费正成为扩内需、稳增长的重要驱动力量"},{"id":"B","text":"影响农村居民消费持续增长的因素已经消除"},{"id":"C","text":"乡村消费为乡村振兴和城乡融合带来了强劲动力"},{"id":"D","text":"乡村产业振兴业已实现"}],"answer":["A","C"],"analysis":{"point":"本题考查乡村消费对扩大内需和乡村振兴的重大意义。随着一系列提振消费政策出台，农村消费市场活力进一步迸发，农村消费正成为扩内需、稳增长的重要驱动力量。同时，我国乡村消费规模持续扩大，消费潜力加速释放，为扩内需稳增长、助力乡村振兴和城乡融合带来了强劲动力。因此，选项A、C正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"近年来，我国农村基础设施不断完善，农村市场环境持续优化，有效促进了农村经济发展和农村居民消费。但也要看到，农村消费市场扩容与提质升级仍面临不少制约。例如，人口动态变化改变了农村居民消费结构，农村居民消费需求呈现多样化、分众化的新趋势，但未能得到很好的满足；城乡消费市场的结构和质量差异，影响农村居民消费格局；服务供给瓶颈制约农村居民消费升级等。故不选。","C":"（正确选项，分析见“解题思路”）","D":"近年来，我国农村基础设施不断完善，农村市场环境持续优化，有效促进了农村经济发展和农村居民消费。但也要看到，农村消费市场扩容与提质升级仍面临不少制约。例如，人口动态变化改变了农村居民消费结构，农村居民消费需求呈现多样化、分众化的新趋势，但未能得到很好的满足；城乡消费市场的结构和质量差异，影响农村居民消费格局；服务供给瓶颈制约农村居民消费升级等。故不选。"}}},{"id":"advanced-xisixiang-test3-16","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试三","chapterKey":"综合测试三","n":16,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试三 第 16 题"},"stem":"2023年2月，中共中央、国务院印发了《数字中国建设整体布局规划》（简称《规划》）。《规划》明确提出，到2025年，基本形成横向打通、纵向贯通、协调有力的一体化推进格局，数字中国建设取得重要进展。到2035年，数字化发展水平进入世界前列，数字中国建设取得重大成就。建设数字中国是","choices":[{"id":"A","text":"当代中国最显著的特征、最壮丽的气象"},{"id":"B","text":"构筑国家竞争新优势的有力支撑"},{"id":"C","text":"数字时代推进中国式现代化的重要引擎"},{"id":"D","text":"中国特色社会主义制度的最大优势"}],"answer":["B","C"],"analysis":{"point":"本题考查数字中国建设。《数字中国建设整体布局规划》指出，建设数字中国是数字时代推进中国式现代化的重要引擎，是构筑国家竞争新优势的有力支撑。加快数字中国建设，对全面建设社会主义现代化国家、全面推进中华民族伟大复兴具有重要意义和深远影响。因此，选项B、C正确。","options":{"A":"改革开放是当代中国最显著的特征、最壮丽的气象，故不选。","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"中国共产党的领导是中国特色社会主义制度的最大优势，故不选。"}}},{"id":"advanced-xisixiang-test3-17","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试三","chapterKey":"综合测试三","n":17,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试三 第 17 题"},"stem":"党的十八届五中全会提出“创新、协调、绿色、开放、共享”的新发展理念，把创新作为引领发展的第一动力。在这一新发展理念的指导下，2016年5月党中央和国务院颁布了《国家创新驱动发展战略纲要》，把创新作为引领发展的第一动力是","choices":[{"id":"A","text":"分析世界发展历程和总结我国改革开放实践得出的结论"},{"id":"B","text":"引领经济发展新常态的根本之策"},{"id":"C","text":"构建和谐世界的内在要求"},{"id":"D","text":"提高核心竞争力的必然选择"}],"answer":["A","B","D"],"analysis":{"point":"本题考查创新发展理念。坚持创新发展是分析近代以来世界发展历程特别是总结我国改革开放成功实践得出的结论，是应对发展环境变化、增强发展动力、把握发展主动权、更好引领经济发展新常态的根本之策，是提高核心竞争力的必然选择。习近平总书记指出，抓住了创新，就抓住了牵动经济社会发展全局的“牛鼻子”。树立创新发展理念，就必须把创新摆在国家发展全局的核心位置，不断推进理论创新、制度创新、科技创新、文化创新等各方面创新，让创新贯穿党和国家一切工作，让创新在全社会蔚然成风。因此，选项A、B、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"构建和谐世界属于中国外交的重大方针，与题干无关，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-xisixiang-test3-18","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试三","chapterKey":"综合测试三","n":18,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试三 第 18 题"},"stem":"2014年5月22日，习近平在上海召开的外国专家座谈会上指出：“要实行更加开放的人才政策，不唯地域引进人才，不求所有开发人才，不拘一格用好人才。”当前，我们之所以比历史上任何时期都更加强调重视人才、用好人才，是因为人才是","choices":[{"id":"A","text":"第一资源和国家战略资源"},{"id":"B","text":"先进生产力的集中体现"},{"id":"C","text":"国家竞争力的重要体现"},{"id":"D","text":"推进中国特色社会主义事业的关键因素"}],"answer":["A","C","D"],"analysis":{"point":"本题考查加快建设人才强国。中国特色社会主义道路能不能越走越宽广，中华民族能不能实现伟大复兴，要看能不能不断培养造就大批优秀人才，更要看能不能让各方面优秀人才脱颖而出、施展才华。人才是第一资源，是国家发展的战略资源，是国家竞争力的重要体现，是推进中国特色社会主义事业的关键因素。我们要牢固树立科学发展人才观，推动新一轮人才工作思想解放和观念更新，为我国人才发展改革创新提供坚实的思想理论基础和良好的社会氛围。因此，选项A、C、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"科学技术作为第一生产力，是先进生产力的集中体现和主要标志，故不选。","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-xisixiang-test3-19","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试三","chapterKey":"综合测试三","n":19,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试三 第 19 题"},"stem":"民族区域自治制度是中国特色解决民族问题的正确道路的重要内容和制度保障，是中国共产党根据中国历史和现实的特点，运用马克思主义民族理论解决中国民族问题的一项重大创造。西藏60年来的历史性巨变、新疆70年的辉煌成就，充分彰显了社会主义制度的巨大优越性，充分展现了中国特色解决民族问题正确道路的强大生命力，充分证明了新时代党的治藏、治疆方略是完全正确的。新时代坚持和完善民族区域自治制度，要坚持","choices":[{"id":"A","text":"民族因素和区域因素相结合"},{"id":"B","text":"经济自治和政治自决相结合"},{"id":"C","text":"大杂居、小聚居和交错居相结合"},{"id":"D","text":"统一和自治相结合"}],"answer":["A","D"],"analysis":{"point":"本题考查新时代坚持和完善民族区域自治制度应坚持的原则。新时代坚持和完善民族区域自治制度，要坚持统一和自治相结合、民族因素和区域因素相结合，促进各民族共同团结奋斗、共同繁荣发展。因此，选项A、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"我国实行的是民族区域自治，而不是民族自决，故不选。","C":"“大杂居、小聚居和交错居”是少数民族呈现的居住格局，不是坚持和完善民族区域自治制度应坚持的原则，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-xisixiang-test3-20","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试三","chapterKey":"综合测试三","n":20,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试三 第 20 题"},"stem":"宗教是对相当一部分群众有较大影响的社会现象，在社会主义社会中也将长期存在。我们既不能用行政的力量去消灭宗教，也不能用行政的力量去发展宗教，而是实行政教分离的原则。这要求","choices":[{"id":"A","text":"任何宗教都没有超越宪法和法律的特权"},{"id":"B","text":"宗教界人士和信教群众放弃宗教信仰"},{"id":"C","text":"每个公民都不能信仰宗教"},{"id":"D","text":"任何宗教都不能干预国家行政、司法和教育等国家职能的实施"}],"answer":["A","D"],"analysis":{"point":"本题考查我国的宗教政策。我国实行政教分离的原则，任何宗教都没有超越宪法和法律的特权，都不能干预国家行政、司法和教育等国家职能的实施。因此，选项A、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"积极引导宗教与社会主义社会相适应，不是要求宗教界人士和信教群众放弃宗教信仰，而是要求他们热爱祖国，拥护社会主义制度，拥护中国共产党的领导，遵守国家的法律、法规和方针政策，故不选。","C":"尊重和保护公民的宗教信仰自由权利，是我们党维护人民利益、尊重和保护人权的重要体现，也是最大限度团结人民群众的需要。我们一方面要尊重每个公民信仰宗教的自由和不信仰宗教的自由，另一方面又要求宗教必须在宪法和法律规定的权利和义务范围内活动。故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-xisixiang-test3-21","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试三","chapterKey":"综合测试三","n":21,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试三 第 21 题"},"stem":"政治和法治相互依存，相互作用，密不可分。全面依法治国必须正确处理政治和法治的关系，因此","choices":[{"id":"A","text":"党的领导和社会主义法治是一致的"},{"id":"B","text":"社会主义法治必须坚持党的领导"},{"id":"C","text":"党的领导必须依靠社会主义法治"},{"id":"D","text":"依法治国必然虚化、弱化甚至动摇、否定党的领导"}],"answer":["A","B","C"],"analysis":{"point":"本题考查正确处理全面依法治国的重大关系。党和法的关系是政治和法治关系的集中反映，是全面依法治国的一个根本问题。党的领导和社会主义法治是一致的，社会主义法治必须坚持党的领导，党的领导必须依靠社会主义法治。全面依法治国，绝不是要虚化、弱化甚至动摇、否定党的领导，而是为了进一步巩固党的执政地位、改善党的执政方式、提高党的执政能力，更好地完成党的执政使命。因此，选项A、B、C正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"表述错误，故不选。"}}},{"id":"advanced-xisixiang-test3-22","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试三","chapterKey":"综合测试三","n":22,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试三 第 22 题"},"stem":"近年来，我国多地深入挖掘地方历史文化特色，通过创意设计将文物、非遗等元素转化为深受年轻人喜爱的文创 IP，并成功应用于文旅消费场景。积极培育和打造具有影响力的文创 IP 有利于","choices":[{"id":"A","text":"推动中华优秀传统文化创造性转化、创新性发展，增强文化认同和文化自信"},{"id":"B","text":"形成新的消费增长点，发挥消费对经济发展的基础性作用"},{"id":"C","text":"替代传统制造业，成为国民经济的新支柱产业和主导产业"},{"id":"D","text":"提升文化资源利用效率，推动文化产业高质量发展"}],"answer":["A","B","D"],"analysis":{"point":"本题考查建设社会主义文化强国。文创IP的开发是对中华优秀传统文化进行创造性转化和创新性发展的具体实践，让传统文化以新的形式焕发生机，有助于增强人民群众的文化认同和文化自信，这体现了新时代中国特色社会主义文化建设的要求；成功的文创IP能够带动文旅消费，形成新的消费热点，促进消费结构优化升级，这契合了“高质量发展”中关于“增强消费对经济发展的基础性作用”的论述；培育文创IP是发展文化产业的重要举措，有助于优化文化产业结构，丰富文化产品供给，提升文化资源利用效率，推动文化产业高质量发展。因此，选项A、B、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"表述错误，文创IP产业虽然重要，但其规模和就业容量目前还无法替代传统制造业的支柱地位，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-xisixiang-test3-23","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试三","chapterKey":"综合测试三","n":23,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试三 第 23 题"},"stem":"社会治理体系是进行社会治理的基础，也是提高社会治理效能的保障。加快完善社会治理体系，是一项系统性工程，要根据社会治理实际和人民新期待，进一步创新社会治理理念，健全社会治理制度，改进社会治理方式，不断推进社会治理体系和治理能力现代化。完善社会治理体系必须","choices":[{"id":"A","text":"坚持共建共治共享的社会治理理念"},{"id":"B","text":"健全社会治理制度，提升社会治理效能"},{"id":"C","text":"不断创新社会治理方式、途径和手段"},{"id":"D","text":"以制度建设为先导"}],"answer":["A","B","C"],"analysis":{"point":"本题考查完善社会治理体系。理念是完善社会治理体系的先导，必须坚持共建共治共享的社会治理理念。制度是完善社会治理体系的保障，必须健全社会治理制度，提升社会治理效能。方式方法是完善社会治理体系的重要内容，必须不断创新社会治理方式、途径和手段。因此，选项A、B、C正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"理念是完善社会治理体系的先导，而制度是完善社会治理体系的保障，故不选。"}}},{"id":"advanced-xisixiang-test3-24","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试三","chapterKey":"综合测试三","n":24,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试三 第 24 题"},"stem":"习近平指出：“只有实行最严格的制度、最严密的法治，才能为生态文明建设提供可靠保障。”建设生态文明，必须建立系统完整的制度体系。其中，相应的制度保障措施包括","choices":[{"id":"A","text":"完善经济社会发展考核评价体系"},{"id":"B","text":"顺应自然的客观规律，按自然规律办事"},{"id":"C","text":"划定生态保护红线，建立责任追究制度"},{"id":"D","text":"健全法律法规，完善生态环境保护管理制度"}],"answer":["A","C","D"],"analysis":{"point":"本题考查加快生态文明体制改革。建设生态文明，必须建立系统完整的制度体系，用制度保障生态环境、推进生态文明建设。第一，要完善经济社会发展考核评价体系。第二，划定生态保护红线，建立责任追究制度。第三，健全法律法规，完善生态环境保护管理制度。因此，选项A、C、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"顺应自然的客观规律，按自然规律办事是生态文明理念的内容，不属于生态文明制度体系，故不选。","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-xisixiang-test3-25","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试三","chapterKey":"综合测试三","n":25,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试三 第 25 题"},"stem":"习近平总书记指出：“只有实行最严格的制度、最严密的法治，才能为生态文明建设提供可靠保障。”建设生态文明，必须加快构建生态文明体系，加快建立健全","choices":[{"id":"A","text":"以尊重自然、顺应自然、保护自然为重点的基本国策"},{"id":"B","text":"以生态价值观念为准则的生态文化体系"},{"id":"C","text":"以产业生态化和生态产业化为主体的生态经济体系"},{"id":"D","text":"以治理体系和治理能力现代化为保障的生态文明制度体系"}],"answer":["B","C","D"],"analysis":{"point":"本题考查加快生态文明体制改革。习近平强调，要加快构建生态文明体系，加快建立健全以生态价值观念为准则的生态文化体系，以产业生态化和生态产业化为主体的生态经济体系，以改善生态环境质量为核心的目标责任体系，以治理体系和治理能力现代化为保障的生态文明制度体系，以生态系统良性循环和环境风险有效防控为重点的生态安全体系。要加快构建生态文明体系，确保到2035年，生态环境质量实现根本好转，美丽中国目标基本实现。因此，选项B、C、D正确。","options":{"A":"尊重自然、顺应自然、保护自然属于生态文明理念，不是基本国策，故不选。","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-xisixiang-test3-26","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试三","chapterKey":"综合测试三","n":26,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试三 第 26 题"},"stem":"从 1956 年我国建立第一个自然保护区鼎湖山保护区，到目前全国已拥有 2 750 个自然保护区，面积 147 万平方公里，约占陆域国土面积的 15%。自党的十八届三中全会决定“建立国家公园体制”以来，国家公园体制试点快速推进，目前全国共有 10 处国家公园体制试点单位，涉及 12 个省，总面积约 22.29 万平方公里。我国建立以国家公园为主体的自然保护地体系的意义是","choices":[{"id":"A","text":"推进自然生态保护、建设美丽中国"},{"id":"B","text":"保护重要的自然生态系统和独特的自然遗产"},{"id":"C","text":"促进人与自然和谐共生"},{"id":"D","text":"维护国家生态安全"}],"answer":["A","B","C","D"],"analysis":{"point":"本题考查建立以国家公园为主体的自然保护地体系的意义。中共中央办公厅、国务院办公厅印发的《关于建立以国家公园为主体的自然保护地体系的指导意见》强调，我国经过60多年的努力，已建立数量众多、类型丰富、功能多样的各级各类自然保护地，在保护生物多样性、保存自然遗产、改善生态环境质量和维护国家生态安全方面发挥了重要作用；要建立分类科学、布局合理、保护有力、管理有效的以国家公园为主体的自然保护地体系，确保重要自然生态系统、自然遗迹、自然景观和生物多样性得到系统性保护，提升生态产品供给能力，维护国家生态安全，为建设美丽中国、实现中华民族永续发展提供生态支撑。因此，选项A、B、C、D正确。\\n无干扰选项。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-xisixiang-test3-27","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试三","chapterKey":"综合测试三","n":27,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试三 第 27 题"},"stem":"构建新安全格局是应对国家安全形势新变化新趋势的战略选择，是全面贯彻落实总体国家安全观的重大举措。构建统筹各领域安全的新安全格局，必须把维护政治安全作为应对各领域安全风险挑战的首要任务。之所以把维护政治安全放在首要位置，是因为","choices":[{"id":"A","text":"政治安全是人民群众安全感的晴雨表"},{"id":"B","text":"政治安全是一切国家生存和发展的基础条件"},{"id":"C","text":"政治安全涉及国家主权、政权、制度和意识形态的稳固"},{"id":"D","text":"政治安全决定和影响着国家的经济安全、军事安全、社会安全等各个领域的安全"}],"answer":["B","C","D"],"analysis":{"point":"本题考查政治安全。政治安全涉及国家主权、政权、制度和意识形态的稳固，是一个国家最根本的需求，是一切国家生存和发展的基础条件。政治安全决定和影响着国家的经济安全、军事安全、社会安全等各个领域的安全。因此，选项B、C、D正确。","options":{"A":"表述错误，社会安全与人民群众切身利益关系最密切，是人民群众安全感的晴雨表，是社会安定的风向标，故不选。","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-xisixiang-test3-28","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试三","chapterKey":"综合测试三","n":28,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试三 第 28 题"},"stem":"“一国两制”是实现祖国和平统一的一项重要制度，是中国特色社会主义的一个伟大创举。2019 年 11 月，国家主席习近平在巴西利亚出席金砖国家领导人第十一次会晤时，针对香港出现的街头暴力犯罪行为发表重要讲话。习近平指出，香港持续发生的激进暴力犯罪行为，严重践踏法治和社会秩序，严重破坏香港繁荣稳定，严重挑战“一国两制”原则底线。止暴制乱、恢复秩序是香港当前最紧迫的任务。贯彻落实“一国两制”方针，绝不能允许触碰的原则底线是","choices":[{"id":"A","text":"危害国家主权安全"},{"id":"B","text":"干扰内地与香港的民间交流"},{"id":"C","text":"挑战中央权力与香港特别行政区基本法权威"},{"id":"D","text":"利用香港对内地进行渗透破坏"}],"answer":["A","C","D"],"analysis":{"point":"本题考查贯彻落实“一国两制”方针的三条底线。在香港贯彻落实“一国两制”方针，始终要强调“三条底线”不能触碰，这“三条底线”就是：绝对不能允许任何危害国家主权安全、绝对不能允许挑战中央权力和香港特别行政区基本法权威、绝对不能允许利用香港对内地进行渗透破坏的活动。因此，选项A、C、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"属于杜撰选项，故不选。","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-xisixiang-test3-29","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试三","chapterKey":"综合测试三","n":29,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试三 第 29 题"},"stem":"当今世界，各国之间的联系从来没有像今天这样紧密，世界人民对美好生活的向往从来没有像今天这样强烈。但是现行全球治理体系跟不上时代发展，受全球金融危机和反全球化运动的冲击，面临着严重的问题，主要包括","choices":[{"id":"A","text":"在政治领域不平等"},{"id":"B","text":"无法弥合南北差距"},{"id":"C","text":"难以消除自然界与人类社会之间的不和谐关系"},{"id":"D","text":"已不能有效保障世界和平"}],"answer":["A","B","C","D"],"analysis":{"point":"本题考查现行全球治理体系面临的问题。当前，现行全球治理体系面临以下问题：第一，现行全球治理体系在政治领域不平等；第二，现行全球治理体系已不能有效保障世界和平；第三，现行全球治理体系无法弥合南北差距；第四，现行全球治理体系下一些西方国家不能真正包容文化差异；第五，现行全球治理体系难以消除自然界与人类社会之间的不和谐关系。因此，选项A、B、C、D正确。\\n无干扰选项。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-xisixiang-test3-30","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试三","chapterKey":"综合测试三","n":30,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试三 第 30 题"},"stem":"勇于自我革命，是中国共产党区别于其他政党的显著标志，也是我们党最大的优势、最鲜明的品格。一个马克思主义政党，要保持先进性和纯洁性，实现崇高使命，必须始终保持自我革命精神，毫不放松地解决好自身存在的问题，始终跟上时代、实践、人民的要求。我们党之所以勇于自我革命，是因为","choices":[{"id":"A","text":"我们党把勇于自我革命作为自己的初心和使命"},{"id":"B","text":"我们党除了国家、民族、人民的利益，没有任何自己的特殊利益"},{"id":"C","text":"我们党立志于中华民族千秋伟业，始终坚守初心使命"},{"id":"D","text":"我们党有高度的自信，从不讳疾忌医，敢于直面问题，勇于坚持真理、修正错误"}],"answer":["B","C","D"],"analysis":{"point":"本题考查勇于自我革命。我们党之所以勇于自我革命，是因为我们党除了国家、民族、人民的利益，没有任何自己的特殊利益，这是我们党自我革命的勇气之源、底气所在；是因为我们党有高度的自信，从不讳疾忌医，敢于直面问题，勇于坚持真理、修正错误；是因为我们党立志于中华民族千秋伟业，始终坚守初心使命，需要在革命性锻造中永葆青春活力，给党和人民事业发展注入源源不断的强大能量。因此，选项B、C、D正确。","options":{"A":"党的初心和使命是为中国人民谋幸福，为中华民族谋复兴，不是“勇于自我革命”，故不选。","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-xisixiang-test4-1","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试四","chapterKey":"综合测试四","n":1,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试四 第 1 题"},"stem":"75年前，毛泽东同志向世界庄严宣告了中华人民共和国的成立，中国人民从此站起来了。中华人民共和国成立以来，特别是改革开放以来，我们党领导人民创造了世所罕见的两大奇迹，这就是","choices":[{"id":"A","text":"经济快速发展奇迹和生态环境改善奇迹"},{"id":"B","text":"文化繁荣兴盛奇迹和社会长期稳定奇迹"},{"id":"C","text":"文化繁荣兴盛奇迹和生态环境改善奇迹"},{"id":"D","text":"经济快速发展奇迹和社会长期稳定奇迹"}],"answer":["D"],"analysis":{"point":"本题考查改革开放是我们前进的重要法宝。中华人民共和国成立以来，特别是改革开放以来，我们党领导人民创造了世所罕见的两大奇迹：一是经济快速发展奇迹；二是社会长期稳定奇迹。因此，选项D正确。","options":{"A":"生态环境改善进程正在加快，但部分地区依旧发展较慢，故不选。","B":"文化事业在“文革”期间有所影响，属于正在努力实现的目标，故不选。","C":"文化事业在“文革”期间有所影响，属于正在努力实现的目标，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-xisixiang-test4-2","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试四","chapterKey":"综合测试四","n":2,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试四 第 2 题"},"stem":"我国经济由高速增长阶段转向高质量发展阶段，发展要求和发展条件都呈现新特征，特别是人民对美好生活的向往总体上已经从“有没有”转向“好不好”，呈现多样化、多层次、多方面的特点。解决人民日益增长的美好生活需要和不平衡不充分的发展之间的矛盾，必须增加高质量产品和服务供给，满足人民群众需要，推动供需在更高水平上实现良性循环。这段话说明","choices":[{"id":"A","text":"要坚持把协调发展摆在我国现代化建设全局中的核心地位"},{"id":"B","text":"要适应经济发展进入高速增长的发展阶段"},{"id":"C","text":"要坚持扩大内需的战略基点，促进经济良性循环"},{"id":"D","text":"要把改革开放作为引领发展的第一动力"}],"answer":["C"],"analysis":{"point":"本题考查扩大内需的政策。解决人民日益增长的美好生活需要和不平衡不充分的发展之间的矛盾，必须增加高质量产品和服务供给，满足人民群众需要，推动供需在更高水平上实现良性循环，体现了要坚持扩大内需的战略基点，促进经济良性循环。因此，选项C正确。","options":{"A":"我国坚持把创新摆在现代化建设全局中的核心地位，而不是协调发展，故不选。","B":"“高速增长”表述错误，我国经济已转向高质量发展阶段，而非“高速增长”阶段，故不选。","C":"（正确选项，分析见“解题思路”）","D":"创新是引领发展的第一动力，而不是改革开放，故不选。"}}},{"id":"advanced-xisixiang-test4-3","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试四","chapterKey":"综合测试四","n":3,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试四 第 3 题"},"stem":"党的十九大提出实施乡村振兴战略，是以习近平同志为核心的党中央着眼党和国家事业全局，深刻把握现代化建设规律和城乡关系变化特征，顺应亿万农民对美好生活的向往，对“三农”工作作出的重大决策部署，是新时代做好“三农”工作的总抓手。实施乡村振兴战略的根本目的是","choices":[{"id":"A","text":"确保国家粮食安全"},{"id":"B","text":"建立新型土地承包关系"},{"id":"C","text":"转移农村富余劳动力"},{"id":"D","text":"推进农业农村现代化"}],"answer":["D"],"analysis":{"point":"本题考查实施乡村振兴战略的根本目的。党的十九大报告指出，实施乡村振兴战略是为了推进乡村治理体系和治理能力现代化，实现农业农村现代化。因此，选项D正确。","options":{"A":"“确保国家粮食安全”是底线，不是目的，故不选。","B":"“建立新型土地承包关系”和“转移农村富余劳动力”是实施乡村振兴战略的具体举措，不是目的，故不选。","C":"“建立新型土地承包关系”和“转移农村富余劳动力”是实施乡村振兴战略的具体举措，不是目的，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-xisixiang-test4-4","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试四","chapterKey":"综合测试四","n":4,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试四 第 4 题"},"stem":"习近平总书记深刻指出：“意识形态工作是为国家立心、为民族立魂的工作。”之所以要建设具有强大凝聚力和引领力的社会主义意识形态，是因为","choices":[{"id":"A","text":"做好意识形态工作是中国共产党的中心任务"},{"id":"B","text":"意识形态关乎旗帜、关乎道路、关乎国家政治安全，决定文化前进方向和发展道路"},{"id":"C","text":"意识形态领域的矛盾是当前我国社会的主要矛盾"},{"id":"D","text":"做好意识形态工作是全面建设社会主义现代化国家的基础性、战略性支撑"}],"answer":["B"],"analysis":{"point":"本题考查意识形态工作的重要性。习近平总书记在党的二十大报告中强调：“意识形态工作是为国家立心、为民族立魂的工作。”意识形态关乎旗帜、关乎道路、关乎国家政治安全，决定文化前进方向和发展道路。因此，选项B正确。","options":{"A":"中国共产党的中心任务是以中国式现代化全面推进中华民族伟大复兴，而不是做好意识形态工作，故不选。","B":"（正确选项，分析见“解题思路”）","C":"当前我国社会的主要矛盾是人民日益增长的美好生活需要和不平衡不充分的发展之间的矛盾，而不是意识形态领域的矛盾，故不选。","D":"教育、科技、人才是全面建设社会主义现代化国家的基础性、战略性支撑，而不是做好意识形态工作，故不选。"}}},{"id":"advanced-xisixiang-test4-5","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试四","chapterKey":"综合测试四","n":5,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试四 第 5 题"},"stem":"发展是解决民生问题的“总钥匙”，民生是发展的“指南针”。要在发展过程中始终注重民生、保障民生、改善民生，根据经济发展和财力状况，逐步提高人民生活水平，让群众得到更多看得见、摸得着的实惠，不断厚植民生福祉。保障和改善民生的重中之重是","choices":[{"id":"A","text":"打赢脱贫攻坚战，消除绝对贫困"},{"id":"B","text":"坚持人人尽责、人人享有"},{"id":"C","text":"让所有劳动者在推动发展中分享发展成果"},{"id":"D","text":"解决人民群众最关心最直接最现实的利益问题"}],"answer":["D"],"analysis":{"point":"本题考查坚持在发展中增进民生福祉。解决人民群众最关心最直接最现实的利益问题，是保障和改善民生的重中之重。因此，选项D正确。","options":{"A":"我国已于2021年打赢脱贫攻坚战，因此这项工作已不是未来民生工作的重中之重，故不选。","B":"坚持人人尽责、人人享有，让所有劳动者在推动发展中分享发展成果，是保障和改善民生的重要原则，故不选。","C":"坚持人人尽责、人人享有，让所有劳动者在推动发展中分享发展成果，是保障和改善民生的重要原则，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-xisixiang-test4-6","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试四","chapterKey":"综合测试四","n":6,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试四 第 6 题"},"stem":"1979年1月1日，全国人民代表大会常务委员会发表《告台湾同胞书》，郑重宣示争取祖国和平统一的大政方针，揭开了两岸关系发展新的历史篇章。2019年1月2日，习近平在《告台湾同胞书》发表40周年纪念会上的讲话中指出：“在一个中国原则基础上，台湾任何政党、团体同我们的交往都不存在障碍。以对话取代对抗、以合作取代争斗、以双赢取代零和，两岸关系才能行稳致远。”影响两岸关系行稳致远的总根子是","choices":[{"id":"A","text":"两岸长期存在的政治分歧"},{"id":"B","text":"两岸对历史现状缺乏认同"},{"id":"C","text":"“台独”分裂势力的存在"},{"id":"D","text":"外部势力的干涉"}],"answer":["A"],"analysis":{"point":"本题考查影响两岸关系行稳致远的总根子。2019年1月2日，习近平在《告台湾同胞书》发表40周年纪念会上的讲话中就共同推动两岸关系和平发展、推进祖国和平统一进程，提出五点主张。他在第二点中指出，探索“两制”台湾方案，丰富和平统一实践。和平统一，是平等协商、共议统一。两岸长期存在的政治分歧问题是影响两岸关系行稳致远的总根子，总不能一代一代传下去。因此，选项A正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"是杜撰选项，故不选。","C":"“台独”分裂势力是祖国统一的最大障碍，是民族复兴的严重隐患，故不选。","D":"把握两岸关系主导权和主动权，推动两岸关系朝着正确方向发展，要坚决反对外部势力干涉，故不选。"}}},{"id":"advanced-xisixiang-test4-7","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试四","chapterKey":"综合测试四","n":7,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试四 第 7 题"},"stem":"中央宣传部（国务院新闻办公室）会同中央党史和文献研究院、中国外文局编辑的《习近平谈治国理政》第五卷，由外文出版社以中英文版出版，面向海内外发行。该书深刻阐释“两个结合”的丰富内涵和实践要求，全方位呈现习近平新时代中国特色社会主义思想是坚持把马克思主义基本原理同中国具体实际相结合、同中华优秀传统文化相结合取得的重大理论创新成果这一历史性结论。“两个结合”","choices":[{"id":"A","text":"是我们在探索中国特色社会主义道路中得出的规律性认识"},{"id":"B","text":"是我们取得成功的最大法宝"},{"id":"C","text":"是推进马克思主义中国化时代化的根本途径"},{"id":"D","text":"使马克思主义和中华优秀传统文化具有高度契合性"}],"answer":["A","B","C"],"analysis":{"point":"本题考查“两个结合”。“两个结合”是我们在探索中国特色社会主义道路中得出的规律性认识，是我们取得成功的最大法宝，同时也是推进马克思主义中国化时代化的根本途径。因此，选项A、B、C正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"颠倒了因果，“结合”的前提是彼此契合。马克思主义和中华优秀传统文化来源不同，但彼此存在高度的契合性，相互契合才能有机结合。因此，契合性是二者能够“结合”的原因，而非二者“结合”的结果，故不选。"}}},{"id":"advanced-xisixiang-test4-8","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试四","chapterKey":"综合测试四","n":8,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试四 第 8 题"},"stem":"中国式现代化是对西方式现代化理论和实践的重大超越，是一种全新的现代化模式。习近平总书记指出，中国式现代化“是一种全新的人类文明形态”，这主要体现在中国式现代化","choices":[{"id":"A","text":"深深根植于中华优秀传统文化"},{"id":"B","text":"体现科学社会主义的先进本质"},{"id":"C","text":"借鉴吸收一切人类优秀文明成果"},{"id":"D","text":"代表人类文明进步的发展方向"}],"answer":["A","B","C","D"],"analysis":{"point":"本题考查中国式现代化创造了人类文明新形态。习近平在学习贯彻党的二十大精神研讨班开班式上深刻指出：“中国式现代化，深深植根于中华优秀传统文化，体现科学社会主义的先进本质，借鉴吸收一切人类优秀文明成果，代表人类文明进步的发展方向，展现了不同于西方现代化模式的新图景，是一种全新的人类文明形态。”因此，选项A、B、C、D正确。\\n无干扰选项。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-xisixiang-test4-9","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试四","chapterKey":"综合测试四","n":9,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试四 第 9 题"},"stem":"风雨不动安如山，赖有砥柱立中流。毫不动摇坚持和加强党的全面领导，巍巍中国号巨轮就有了应对一切风险挑战的坚定自信和强大底气。关于党的领导，下列说法正确的有","choices":[{"id":"A","text":"保证党的团结统一是党的宗旨"},{"id":"B","text":"坚持党的领导首先要旗帜鲜明讲政治，保证全党服从中央"},{"id":"C","text":"党中央集中统一领导是党的领导的最高原则"},{"id":"D","text":"加强和维护党中央集中统一领导是全党共同的政治责任"}],"answer":["B","C","D"],"analysis":{"point":"本题考查坚持和加强党的领导。改革开放以后，党为加强和改善党的领导进行持续努力，为党和国家事业发展提供了根本政治保证。党明确提出，党的领导是全面的、系统的、整体的，保证党的团结统一是党的生命；党中央集中统一领导是党的领导的最高原则，加强和维护党中央集中统一领导是全党共同的政治责任，坚持党的领导首先要旗帜鲜明讲政治，保证全党服从中央。因此，选项B、C、D正确。","options":{"A":"党的团结统一是党的生命，而不是宗旨，党的宗旨是全心全意为人民服务，故不选。","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-xisixiang-test4-10","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试四","chapterKey":"综合测试四","n":10,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试四 第 10 题"},"stem":"服务贸易是国际贸易的重要组成部分和国际经贸合作的重要领域，在构建新发展格局中具有重要作用。商务部发布的数据显示，2025年上半年，我国服务贸易稳步增长，服务进出口总额38 872.6亿元，同比增长8.0%。其中，出口16 883亿元，增长15.0%；进口21 989.6亿元，增长3.2%。服务贸易逆差5 106.6亿元，比上年同期减少1 522.1亿元。服务贸易的快速发展充分表明","choices":[{"id":"A","text":"加快发展服务贸易是扩大高水平对外开放的必然要求"},{"id":"B","text":"服务贸易已成为中国经济转型的关键因素"},{"id":"C","text":"服务贸易已成为控制国民经济命脉的主导力量"},{"id":"D","text":"服务贸易是中国推动自主性开放的重点所在"}],"answer":["A","B","D"],"analysis":{"point":"本题考查服务贸易。服务贸易是中国推动自主性开放的重点所在。服务贸易不仅是中国高质量发展的重点，也是全球贸易的重点，已成为中国经济转型的关键因素。加快发展服务贸易是扩大高水平对外开放、培育外贸发展新动能的必然要求。因此，选项A、B、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"表述错误，国有经济控制国民经济的命脉，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-xisixiang-test4-11","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试四","chapterKey":"综合测试四","n":11,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试四 第 11 题"},"stem":"全面提高对外开放水平，需要实施更为主动的开放战略。近年来，我国坚持引进来和走出去并重，全面开放进一步深化。据统计，2016年中国企业对外直接投资1 832亿美元，连续两年位列世界第二；中国境外企业销售额1.5万亿美元，向所在国缴纳税费400亿美元，雇佣外方员工150万人；我国高技术服务业实际使用外资超过955亿元人民币，同比增长86%，在全球引资东道主中排名第三位，高附加值以及服务行业的外国直接投资流入量持续增长。这表明","choices":[{"id":"A","text":"我国国际投资合作水平进一步提高"},{"id":"B","text":"我国防范经济风险和外部冲击的能力已经形成"},{"id":"C","text":"我国吸引外资的结构和质量正在不断优化"},{"id":"D","text":"我国对外直接投资已经完全转向高端"}],"answer":["A","C"],"analysis":{"point":"本题考查全面提高对外开放水平。改革开放以来，我国不断提高对外开放水平，当前，我国国际投资合作水平进一步提高，吸引外资的结构和质量正在不断优化，这是我们取得的成就。因此，选项A、C正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"“我国防范经济风险和外部冲击的能力已经形成”的说法过于绝对，应该是“逐步提高”或“正在形成”，而不能说“已经形成”，故不选。","C":"（正确选项，分析见“解题思路”）","D":"“我国对外直接投资已经完全转向高端”的说法错误，事实上我们正在努力向高端转变，而不是已经完成，故不选。"}}},{"id":"advanced-xisixiang-test4-12","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试四","chapterKey":"综合测试四","n":12,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试四 第 12 题"},"stem":"党的十八大以来，规模以上高技术制造业增加值年均增长10.3%，2023年，高技术制造业增加值占规模以上工业增加值比重为15.7%，比2012年提高6.3个百分点。高技术产品也保持快速增长，2023年，我国服务机器人产量达783.3万套，3D打印设备产量278.9万台，比上年分别增长23.3%、36.2%。高技术制造业支撑制造业智能化发展表明","choices":[{"id":"A","text":"我国已建成制造强国、质量强国、科技强国"},{"id":"B","text":"科技创新能够催生新产业、新模式、新动能"},{"id":"C","text":"科技创新是发展新质生产力的核心要素"},{"id":"D","text":"我国科技实力正在从量的积累迈向质的飞跃"}],"answer":["B","C","D"],"analysis":{"point":"本题考查科技创新发展。科技创新能够催生新产业、新模式、新动能，是发展新质生产力的核心要素。我国科技实力正在从量的积累迈向质的飞跃，从点的突破迈向系统能力提升，进入创新型国家行列。因此，选项B、C、D正确。","options":{"A":"时态错误，我国正在加强制造强国、质量强国、科技强国建设，故不选。","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-xisixiang-test4-13","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试四","chapterKey":"综合测试四","n":13,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试四 第 13 题"},"stem":"非公有制经济包括个体经济、私营经济、外资经济、混合所有制经济中的非公有制成分等，是我国社会主义市场经济的重要组成部分。中共十八届三中全会报告特别指出，要激发非公有制经济活力和创造力。这表明，非公有制经济","choices":[{"id":"A","text":"与公有制经济共同推动生产力发展"},{"id":"B","text":"可以与公有制经济共存"},{"id":"C","text":"在国民经济中起主导作用"},{"id":"D","text":"是社会主义市场经济发展的需要"}],"answer":["A","B","D"],"analysis":{"point":"本题考查非公有制经济。在社会主义市场经济条件下，毫不动摇地鼓励、支持、引导非公有制经济发展，是坚持和完善社会主义初级阶段基本经济制度必须遵循的一条基本原则。非公有制经济可以与公有制经济共存，与公有制经济共同推动生产力发展，是社会主义市场经济发展的需要。因此，选项A、B、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"现阶段，在我国国民经济中起主导作用的是国有经济，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-xisixiang-test4-14","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试四","chapterKey":"综合测试四","n":14,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试四 第 14 题"},"stem":"习近平总书记一向高度重视实体经济，作出了“实体经济是我国发展的本钱”“国家强大要靠实体经济”“把实体经济抓上去”等重要论断，体现了对经济发展规律的深刻认识。当前，我们要深刻认识实体经济发展环境新变化，主要包括","choices":[{"id":"A","text":"结构性供需失衡问题被彻底扭转"},{"id":"B","text":"制造业重新成为全球经济竞争的焦点"},{"id":"C","text":"新工业革命给制造业发展带来深刻变革"},{"id":"D","text":"我国制造业提质升级任务日益紧迫"}],"answer":["B","C","D"],"analysis":{"point":"本题考查实体经济发展环境的新变化。我们要深刻认识实体经济发展环境新变化。首先，制造业重新成为全球经济竞争的焦点。其次，新工业革命给制造业发展带来深刻变革。最后，我国制造业提质升级任务日益紧迫。因此，选项B、C、D正确。","options":{"A":"虽然我国已经成为世界制造业第一大国，但与主要工业发达国家的制造业发展水平和制造强国建设目标相比，我国在技术创新、质量品牌、环境友好等方面还存在很大差距，结构性供需失衡问题日益凸显，故不选。","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-xisixiang-test4-15","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试四","chapterKey":"综合测试四","n":15,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试四 第 15 题"},"stem":"近年来，中国混合所有制改革已取得积极进展。2013年以来，央企累计实施混改4 000多项，引入社会资本超过1.5万亿元。央企混合所有制企业的户数占比超过70%，比2012年年底提高近20个百分点。地方国有企业混合所有制户数占比达到54%，引入社会资本超过7 000亿元。实践证明，发展混合所有制经济","choices":[{"id":"A","text":"有利于国有资本放大功能、保值增值、提高竞争力"},{"id":"B","text":"有利于推动企业建立适应市场经济发展的现代企业制度"},{"id":"C","text":"有利于公有制经济控制各行业各领域"},{"id":"D","text":"有利于依托多元产权架构和市场化的运营机制提高国有经济效益"}],"answer":["A","B","D"],"analysis":{"point":"本题考查混合所有制经济。积极发展混合所有制经济，有利于改善国有企业、集体企业和非公有制企业的产权结构，推动企业建立适应市场经济发展的现代企业制度；有利于国有资本放大功能、保值增值、提高竞争力；有利于推动各类所有制企业产权的流动和重组，优化资本配置，使效益最大化；有利于依托多元产权架构和市场化的运营机制提高国有经济或公有经济效益。因此，选项A、B、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"公有制的主体地位指的是公有资产在社会总资产中占优势地位，国有经济控制国民经济命脉并对经济发展起主导作用，而不是对各行业各领域都要绝对控制，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-xisixiang-test4-16","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试四","chapterKey":"综合测试四","n":16,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试四 第 16 题"},"stem":"政府和市场的关系问题，是一个世界性的问题，既是经济理论研究的焦点，也是各国经济发展实践中的难点。回望改革开放的多年历程，我们坚持以发展为第一要务，不断理顺政府和市场的关系，取得了令世人瞩目的巨大成就。前进道路上，我们必须继续充分发挥市场在资源配置中的决定性作用，更好发挥政府作用，激发各类市场主体活力。更好发挥政府作用就要做到","choices":[{"id":"A","text":"保持宏观经济稳定，加强和优化公共服务"},{"id":"B","text":"扩大政府配置资源的范围和力度，实现资源最优配置"},{"id":"C","text":"保障公平竞争，加强市场监管，维护市场秩序"},{"id":"D","text":"推动可持续发展，促进共同富裕，弥补市场失灵"}],"answer":["A","C","D"],"analysis":{"point":"本题考查政府和市场的关系。要更好发挥政府作用，不是简单下达行政命令，而是在尊重市场规律的基础上，用改革激发市场活力，用政策引导市场预期，用规划明确投资方向，用法治规范市场行为。政府的职责和作用主要是保持宏观经济稳定，加强和优化公共服务，保障公平竞争，加强市场监管，维护市场秩序，推动可持续发展，促进共同富裕，弥补市场失灵。因此，选项A、C、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"调控资源配置属于市场的作用，政府应该管那些市场管不了或者管不好的事情，故不选。","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-xisixiang-test4-17","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试四","chapterKey":"综合测试四","n":17,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试四 第 17 题"},"stem":"“中国制造”是中国参与奥运会的另一种方式。“科技与浪漫”交融的乒乓球台、植入芯片的足球内胆、浙江义乌生产的100万个巴黎奥运会官方手环……“中国制造”闪耀巴黎奥运会。这些“中国制造”","choices":[{"id":"A","text":"体现了科技创新对企业高质量发展的关键动力作用"},{"id":"B","text":"体现了不断壮大的产业链和供应链的支撑作用"},{"id":"C","text":"表明中国已经从制造大国变成制造强国"},{"id":"D","text":"表明“中国制造”正稳步迈向“中国智造”"}],"answer":["A","B","D"],"analysis":{"point":"本题考查科技创新的重大意义。科技创新是企业持续发展的关键动力；我国产业链和供应链具有世界规模最大、门类最全、配套最完备的特点，产业链供应链的韧性和安全不断增强，并随着改革的深入不断壮大；随着我国加快推进产业结构调整，完善现代产业体系，积极推进传统产业技术改造，加快发展战略性新兴产业，“中国制造”正稳步迈向“中国智造”。因此，选项A、B、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"说法错误，我国目前依然是制造大国，尚未进入制造强国行列，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-xisixiang-test4-18","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试四","chapterKey":"综合测试四","n":18,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试四 第 18 题"},"stem":"人才是实现民族振兴、赢得国际竞争主动的战略资源。全面建设社会主义现代化国家，必须坚持党管人才原则，尊重劳动、尊重知识、尊重人才、尊重创造，聚天下英才而用之，推动我国由人才大国迈向人才强国。加快建设人才强国的主要举措有","choices":[{"id":"A","text":"培养造就大批德才兼备的高素质人才"},{"id":"B","text":"深化人才发展体制机制改革"},{"id":"C","text":"营造识才爱才敬才用才的环境"},{"id":"D","text":"坚持党对人才工作的全面领导"}],"answer":["A","B","C","D"],"analysis":{"point":"本题考查建设人才强国。实施人才强国战略，要坚持党对人才工作的全面领导，培养造就大批德才兼备的高素质人才，深化人才发展体制机制改革，营造识才爱才敬才用才的环境，把各方面优秀人才集聚到党和国家事业中来，加快建设世界重要人才中心和创新高地，聚天下英才而用之。因此，选项A、B、C、D正确。\\n无干扰选项。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-xisixiang-test4-19","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试四","chapterKey":"综合测试四","n":19,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试四 第 19 题"},"stem":"西藏自治区成立60年来，在中国共产党的坚强领导下，我国的宗教工作取得了举世瞩目的成就，宗教政策得到了充分贯彻。我国宗教政策主要有","choices":[{"id":"A","text":"尊重和保护公民的宗教信仰自由"},{"id":"B","text":"依法管理宗教事务"},{"id":"C","text":"坚持独立自主自办原则"},{"id":"D","text":"积极引导宗教与社会主义社会相适应"}],"answer":["A","B","C","D"],"analysis":{"point":"本题考查我国宗教政策。我国宗教政策主要有：必须坚决贯彻落实新时代党的宗教工作理论和方针政策，坚持我国宗教中国化方向，坚持独立自主自办原则，积极引导宗教与社会主义社会相适应，尊重和保护公民的宗教信仰自由，依法管理宗教事务。因此，选项A、B、C、D正确。\\n无干扰选项。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-xisixiang-test4-20","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试四","chapterKey":"综合测试四","n":20,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试四 第 20 题"},"stem":"习近平强调，新时代我们要巩固和发展最广泛的爱国统一战线，坚持和完善中国共产党领导的多党合作和政治协商制度，不断为事业发展凝聚人心、增添力量。人民政协要建真言、谋良策、出实招，为加快推进社会主义现代化作出新的更大贡献。巩固和发展爱国统一战线就要","choices":[{"id":"A","text":"支持民主党派按照中国特色社会主义参政党要求更好履行职能"},{"id":"B","text":"深化民族团结进步教育，铸牢中华民族共同体意识"},{"id":"C","text":"全面贯彻党的宗教工作基本方针"},{"id":"D","text":"牢牢把握大团结大联合的主题，做好统战工作"}],"answer":["A","B","C","D"],"analysis":{"point":"本题考查巩固和发展爱国统一战线。新时期爱国统一战线的指导方针是“长期共存，互相监督，肝胆相照，荣辱与共”。具体内容主要包括：支持民主党派按照中国特色社会主义参政党要求更好履行职能；深化民族团结进步教育，铸牢中华民族共同体意识；全面贯彻党的宗教工作基本方针；牢牢把握大团结大联合的主题，做好统战工作。因此，选项A、B、C、D正确。\\n无干扰选项。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-xisixiang-test4-21","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试四","chapterKey":"综合测试四","n":21,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试四 第 21 题"},"stem":"习近平总书记强调：“把培育和弘扬社会主义核心价值观作为凝魂聚气、强基固本的基础工程。”这是因为","choices":[{"id":"A","text":"中国特色社会主义需要一个能够被全社会共同接受和认同的价值观来引领"},{"id":"B","text":"核心价值观是一个国家的重要稳定器"},{"id":"C","text":"坚守社会主义核心价值观是实现人民当家作主的根本保证"},{"id":"D","text":"社会主义核心价值观能够内化为人们的精神追求，外化为人们的自觉行动"}],"answer":["A","B","D"],"analysis":{"point":"本题考查社会主义核心价值观。建设和发展中国特色社会主义，需要有一个能够被全社会共同接受和认同的社会主义核心价值体系和核心价值观来引领。核心价值体系和核心价值观，是决定文化性质和方向的最深层次要素，是一个国家的重要稳定器。坚守社会主义核心价值体系和社会主义核心价值观就是通过教育引导、舆论宣传、文化熏陶、实践养成、制度保障等，使社会主义核心价值观内化为人们的精神追求，外化为人们的自觉行动。因此，选项A、B、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"中国共产党的领导是实现人民当家作主和依法治国的根本保证，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-xisixiang-test4-22","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试四","chapterKey":"综合测试四","n":22,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试四 第 22 题"},"stem":"2025年5月，习近平总书记对精神文明建设工作作出重要指示，强调通过推动精神文明建设高质量发展，为强国建设、民族复兴提供强大精神力量。“我们将不断提高人民物质生活和精神生活水平，做到家家仓廪实衣食足，又让人人知礼节明荣辱。”这是人民向往的美好生活，也是新时代中国共产党人的庄严承诺。推动精神文明建设高质量发展，这是基于","choices":[{"id":"A","text":"中国式现代化是物质文明和精神文明相协调的现代化"},{"id":"B","text":"不断增强人民精神力量是社会主义现代化强国的根基"},{"id":"C","text":"精神文明建设为全面建设现代化国家提供更为主动的精神力量"},{"id":"D","text":"文化繁荣兴盛是满足人民日益增长的美好生活需要的内在要求"}],"answer":["A","C","D"],"analysis":{"point":"本题考查文化繁荣兴盛。中国式现代化是物质文明和精神文明相协调的现代化，文化繁荣兴盛是满足人民日益增长的美好生活需要的内在要求。要通过推动精神文明建设高质量发展，为强国建设、民族复兴提供强大精神力量，不断提高人民物质生活和精神生活水平。因此，选项A、C、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"社会主义现代化强国的根基是农业强国，而非不断增强人民精神力量，故不选。","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-xisixiang-test4-23","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试四","chapterKey":"综合测试四","n":23,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试四 第 23 题"},"stem":"就业是最大的民生，关系到千家万户的生活。近年来，我国就业局势保持总体稳定，城镇新增就业年均超过1 300万人，十年累计实现城镇新增就业1.3亿人，调查失业率总体低于预期控制目标。8 000多万高校毕业生总体就业水平保持稳定，农民工总量增至2.9亿人，脱贫劳动力务工规模保持在3 000万人以上。我国实施就业优先战略的主要举措有","choices":[{"id":"A","text":"健全就业公共服务体系"},{"id":"B","text":"健全终身职业技能培训制度"},{"id":"C","text":"统筹城乡就业政策体系"},{"id":"D","text":"完善重点群体就业支持体系"}],"answer":["A","B","C","D"],"analysis":{"point":"本题考查就业优先战略。我国实施就业优先战略的主要举措有：强化就业优先政策；健全就业公共服务体系，完善重点群体就业支持体系；统筹城乡就业政策体系；健全终身职业技能培训制度；健全劳动法律法规，完善劳动关系协商协调机制。因此，选项A、B、C、D正确。\\n无干扰选项。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-xisixiang-test4-24","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试四","chapterKey":"综合测试四","n":24,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试四 第 24 题"},"stem":"习近平指出：“我们既要绿水青山，也要金山银山。宁要绿水青山，不要金山银山，而且绿水青山就是金山银山。”从表面上看，生态环境保护和经济发展是矛盾对立的关系，是鱼和熊掌不可兼得的两难选择。但从根本上讲，二者是辩证统一、相辅相成的关系。绿水青山就是金山银山，这一理念","choices":[{"id":"A","text":"提高了国内各区域开放水平，拓展了对外开放领域"},{"id":"B","text":"阐明了经济发展与生态环境保护之间的关系"},{"id":"C","text":"指明了实现发展和保护协同共生的新路径"},{"id":"D","text":"揭示了保护生态环境就是保护生产力、改善生态环境就是发展生产力的道理"}],"answer":["B","C","D"],"analysis":{"point":"本题考查生态文明建设。绿水青山就是金山银山，这一理念阐明了经济发展与生态环境保护之间的关系，揭示了保护生态环境就是保护生产力、改善生态环境就是发展生产力的道理，指明了实现发展和保护协同共生的新路径。因此，选项B、C、D正确。","options":{"A":"与题意不符，共建“一带一路”，提高了国内各区域开放水平，拓展了对外开放领域，推动了制度型开放，构建了广泛的朋友圈，故不选。","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-xisixiang-test4-25","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试四","chapterKey":"综合测试四","n":25,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试四 第 25 题"},"stem":"“十四五”时期，我国构建起全球最大、发展最快的可再生能源体系。我国强化煤炭兜底保障基础、深挖油气增储上产潜力、加快可再生能源替代，可再生能源发电装机占比由40%提升至60%左右，风光发电年度新增装机进入“亿千瓦级”规模，能源消费“逐绿前行”，全社会用电量中，每3度电就有1度绿电。近10年来，我国助力全球风电和光伏发电项目平均度电成本分别下降60%和80%。出口的风电光伏产品，“十四五”期间累计为其他国家减少碳排放约41亿吨。这证明","choices":[{"id":"A","text":"我国为全球低碳转型作出了重大贡献"},{"id":"B","text":"我国成为世界能源转型的重要推动者"},{"id":"C","text":"我国能源事业取得了突破性进展和历史性成就"},{"id":"D","text":"我国的传统能源已经完全被新能源取代"}],"answer":["A","B","C"],"analysis":{"point":"本题考查“十四五”期间的发展成就。“十四五”以来，我国能源事业取得了突破性进展和历史性成就。“十四五”规划纲要提出的能源综合生产能力和非化石能源占比等主要指标如期完成，我国成为世界能源转型的重要推动者。我国已经构建起全球最大、发展最快的可再生能源体系，为全球低碳转型作出了重大贡献。因此，选项A、B、C正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"表述错误，故不选。"}}},{"id":"advanced-xisixiang-test4-26","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试四","chapterKey":"综合测试四","n":26,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试四 第 26 题"},"stem":"截至2025年4月底，我国可再生能源发电装机已突破20亿千瓦，达到20.17亿千瓦，这约等于90个三峡电站的总装机，同比增长58%。其中，风电、光伏合计装机达到15.3亿千瓦，超过火电装机。2024年，我国可再生能源新增装机3.73亿千瓦，已连续两年突破3亿千瓦，在全球新增装机的占比超过50%。我国可再生能源保持高速发展态势，主要得益于","choices":[{"id":"A","text":"有序推进大型清洁能源基地建设"},{"id":"B","text":"统筹跨省区电力调节和资源互济"},{"id":"C","text":"提升电网智能化水平和运行效率"},{"id":"D","text":"加强对外来入侵物种的防治力度"}],"answer":["A","B","C"],"analysis":{"point":"本题考查加快形成绿色生产方式。题干中，我国可再生能源保持高速发展态势，主要得益于为提升电力系统对新能源的消纳能力而采取的相关措施，如有序推进大型清洁能源基地建设，统筹跨省区电力调节和资源互济，提升电网智能化水平和运行效率等。因此，选项A、B、C正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"属于生物多样性保护的措施，不符合题意，故不选。"}}},{"id":"advanced-xisixiang-test4-27","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试四","chapterKey":"综合测试四","n":27,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试四 第 27 题"},"stem":"党的十九届五中全会把统筹发展和安全纳入“十四五”时期我国经济社会发展的指导思想。党的十九届六中全会再次强调要统筹发展和安全。党的二十大报告提出，以新安全格局保障新发展格局。目前，社会上对统筹发展和安全问题还存在一些误区，必须从理论、实践及战略等层面厘清各种误区，走出统筹发展和安全“更加强调安全，不重视发展”的认识误区。要走出“更加强调安全，不重视发展”的误区，就必须认识到","choices":[{"id":"A","text":"发展就是最大的安全"},{"id":"B","text":"发展解决的是动力问题，是推动国家和民族赓续绵延的根本支撑"},{"id":"C","text":"发展和安全是两件大事，必须统筹发展和安全"},{"id":"D","text":"安全具有基础性、根本性"}],"answer":["A","B","C"],"analysis":{"point":"本题考查构建新安全格局。发展和安全是两件大事。发展解决的是动力问题，是推动国家和民族赓续绵延的根本支撑；安全解决的是保障问题，是确保国家和民族行稳致远的坚强柱石。发展具有基础性、根本性，是解决安全问题的总钥匙，发展就是最大的安全。因此，选项A、B、C正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"说法错误，发展具有基础性、根本性，是解决安全问题的总钥匙，发展就是最大的安全，故不选。"}}},{"id":"advanced-xisixiang-test4-28","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试四","chapterKey":"综合测试四","n":28,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试四 第 28 题"},"stem":"全面准确地理解和把握“一国”与“两制”的关系，应在坚持“一国”基础上，实现“两制”之间的和谐相处、相互促进。为此，必须做到","choices":[{"id":"A","text":"把维护中央权力和保障特别行政区高度自治权有机结合起来"},{"id":"B","text":"把坚持“一国”原则和尊重“两制”差异有机结合起来"},{"id":"C","text":"把利用国际有利条件和发挥港澳优势有机结合起来"},{"id":"D","text":"把发挥祖国内地坚强后盾作用和提高港澳自身竞争力有机结合起来"}],"answer":["A","B","D"],"analysis":{"point":"本题考查“一国”和“两制”的关系。正确把握“一国”和“两制”的关系，应该把维护中央权力和保障特别行政区高度自治权有机结合起来，把坚持“一国”原则和尊重“两制”差异有机结合起来，把发挥祖国内地坚强后盾作用和提高港澳自身竞争力有机结合起来。因此，选项A、B、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"“一国两制”是为了解决国内问题而提出来的，与国际条件无关，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-xisixiang-test4-29","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试四","chapterKey":"综合测试四","n":29,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试四 第 29 题"},"stem":"2025年是联合国成立80周年。80年来，我们始终坚持独立自主的和平外交政策，始终不渝走和平发展道路、奉行互利共赢的开放战略，坚定维护国际关系基本准则，维护国际公平正义。中国坚定不移地奉行独立自主的和平外交政策，走和平发展道路，源于","choices":[{"id":"A","text":"中国共产党性质宗旨和我国社会主义制度"},{"id":"B","text":"对历史、现实、未来的客观判断"},{"id":"C","text":"思想自信和实践自觉的有机统一"},{"id":"D","text":"对中国目前国家实力的现实考量"}],"answer":["A","B","C"],"analysis":{"point":"本题考查和平外交政策。习近平指出：“中国走和平发展道路，不是权宜之计，更不是外交辞令，而是从历史、现实、未来的客观判断中得出的结论，是思想自信和实践自觉的有机统一。”走和平发展道路是由中国共产党性质宗旨和我国社会主义制度决定的。因此，选项A、B、C正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"中国并不是因为目前国家实力不够，无法称霸世界才被迫走和平发展的道路。我们的外交政策是综合自身的性质、地位、历史等方面因素考量出来的，故不选。"}}},{"id":"advanced-xisixiang-test4-30","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试四","chapterKey":"综合测试四","n":30,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试四 第 30 题"},"stem":"近代以来，为了拯救民族危亡，中国人民奋起反抗，仁人志士奔走呐喊，太平天国农民战争、戊戌维新运动、义和团运动、辛亥革命接连而起，各种救国方案轮番出台，但都以失败而告终。在中国人民和中华民族的伟大觉醒中，在马克思列宁主义同中国工人运动的紧密结合中，中国共产党应运而生，最终成为担当民族复兴重任的时代先锋和民族脊梁。党和人民百年奋斗，书写了中华民族几千年历史上最恢宏的史诗。这些重大成就包括","choices":[{"id":"A","text":"浴血奋战、百折不挠，创造了新民主主义革命的伟大成就"},{"id":"B","text":"自力更生、发愤图强，创造了社会主义革命和建设的伟大成就"},{"id":"C","text":"解放思想、锐意进取，创造了改革开放和社会主义现代化建设的伟大成就"},{"id":"D","text":"自信自强、守正创新，创造了新时代中国特色社会主义的伟大成就"}],"answer":["A","B","C","D"],"analysis":{"point":"本题考查党的百年奋斗重大成就。党的十九届六中全会通过的《中共中央关于党的百年奋斗重大成就和历史经验的决议》指出：“一百年来，党领导人民浴血奋战、百折不挠，创造了新民主主义革命的伟大成就；自力更生、发愤图强，创造了社会主义革命和建设的伟大成就；解放思想、锐意进取，创造了改革开放和社会主义现代化建设的伟大成就；自信自强、守正创新，创造了新时代中国特色社会主义的伟大成就。”因此，选项A、B、C、D正确。\\n无干扰选项。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-xisixiang-test5-1","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试五","chapterKey":"综合测试五","n":1,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试五 第 1 题"},"stem":"党的二十届三中全会深刻总结新时代全面深化改革取得的历史性成就，鲜明阐释了进一步全面深化改革的重大原则，明确提出了进一步全面深化改革的牵引是","choices":[{"id":"A","text":"解放和发展社会生产力"},{"id":"B","text":"经济体制改革"},{"id":"C","text":"促进社会公平正义、增进人民福祉"},{"id":"D","text":"对外开放"}],"answer":["B"],"analysis":{"point":"本题考查进一步全面深化改革。党的二十届三中全会提出，进一步全面深化改革，必须以经济体制改革为牵引，以促进社会公平正义、增进人民福祉为出发点和落脚点。因此，选项B正确。","options":{"A":"解放和发展社会生产力是社会主义的根本任务，故不选。","B":"（正确选项，分析见“解题思路”）","C":"促进社会公平正义、增进人民福祉是全面深化改革的出发点和落脚点，故不选。","D":"开放是中国式现代化的鲜明标识，故不选。"}}},{"id":"advanced-xisixiang-test5-2","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试五","chapterKey":"综合测试五","n":2,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试五 第 2 题"},"stem":"习近平明确指出：“非公有制经济在我国经济社会发展中的地位和作用没有变，我们毫不动摇鼓励、支持、引导非公有制经济发展的方针政策没有变，我们致力于为非公有制经济发展营造良好环境和提供更多机会的方针政策没有变。”这是因为，非公有制经济是","choices":[{"id":"A","text":"社会主义经济的重要组成部分"},{"id":"B","text":"社会主义经济制度的基础"},{"id":"C","text":"中国特色社会主义的重要物质基础和政治基础"},{"id":"D","text":"经济持续健康发展的重要力量"}],"answer":["D"],"analysis":{"point":"本题考查非公有制经济。非公有制经济是社会主义市场经济的重要组成部分，是稳定经济的重要基础，是国家税收的重要来源，是就业创业的重要领域，是技术创新的重要主体，是金融发展的重要依托，是经济持续健康发展的重要力量。因此，选项D正确。","options":{"A":"表述错误，非公有制经济是社会主义市场经济的重要组成部分，故不选。","B":"公有制经济是社会主义经济制度的基础，故不选。","C":"国有企业是中国特色社会主义的重要物质基础和政治基础，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-xisixiang-test5-3","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试五","chapterKey":"综合测试五","n":3,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试五 第 3 题"},"stem":"习近平曾这样比喻“卡脖子”风险：“一个互联网企业即便规模再大、市值再高，如果核心元器件严重依赖外国，供应链的‘命门’掌握在别人手里，那就好比在别人的墙基上砌房子，再大再漂亮也可能经不起风雨，甚至会不堪一击。”我国面临的很多“卡脖子”技术问题的根子是","choices":[{"id":"A","text":"原始创新能力较差"},{"id":"B","text":"国家战略科技力量不足"},{"id":"C","text":"基础理论研究跟不上"},{"id":"D","text":"体制机制障碍较多"}],"answer":["C"],"analysis":{"point":"本题考查加快建设科技强国。基础研究是科技创新的源头。我国面临的很多“卡脖子”技术问题，根子是基础理论研究跟不上。因此，选项C正确。","options":{"A":"实现“从0到1”的突破，需要把原始创新摆在更加突出的位置，故不选。","B":"国家战略科技力量是世界科技强国竞争的着力点，故不选。","C":"（正确选项，分析见“解题思路”）","D":"科技领域的改革最紧迫的是要破除体制机制障碍，最大限度解放和激发科技作为第一生产力所蕴藏的巨大潜能，故不选。"}}},{"id":"advanced-xisixiang-test5-4","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试五","chapterKey":"综合测试五","n":4,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试五 第 4 题"},"stem":"新闻舆论工作处在意识形态斗争前沿，是治国理政、定国安邦的大事。意识形态工作的主阵地、主战场、最前沿是","choices":[{"id":"A","text":"互联网"},{"id":"B","text":"精品读物"},{"id":"C","text":"宗教活动"},{"id":"D","text":"传统节日纪念活动"}],"answer":["A"],"analysis":{"point":"本题考查意识形态工作的相关内容。互联网是意识形态工作的主阵地、主战场、最前沿，管好用好互联网是新形势下掌控新闻舆论阵地的关键。因此，选项A正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"并不能作为意识形态工作的主阵地，本题考查固定搭配，故不选。","C":"并不能作为意识形态工作的主阵地，本题考查固定搭配，故不选。","D":"并不能作为意识形态工作的主阵地，本题考查固定搭配，故不选。"}}},{"id":"advanced-xisixiang-test5-5","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试五","chapterKey":"综合测试五","n":5,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试五 第 5 题"},"stem":"习近平总书记指出：“森林是陆地生态系统的主体和重要资源，是人类生存发展的重要生态保障。不可想象，没有森林，地球和人类会是什么样子。”他还强调：“如果仍是粗放发展，即使实现了国内生产总值翻一番的目标，那污染又会是一种什么情况？届时资源环境恐怕完全承载不了。经济上去了，老百姓的幸福感大打折扣，甚至强烈的不满情绪上来了，那是什么形势？所以，我们不能把加强生态文明建设、加强生态环境保护、提倡绿色低碳生活方式等仅仅作为经济问题。这里面有很大的政治。”这表明","choices":[{"id":"A","text":"良好的生态环境是人与社会持续发展的根基"},{"id":"B","text":"环境污染严重、生态系统退化的严峻形势难以逆转"},{"id":"C","text":"人类始终能够凌驾于自然之上"},{"id":"D","text":"我国涉及环境方面的法律法规已十分完善"}],"answer":["A"],"analysis":{"point":"本题考查生态文明建设。习近平总书记的话概括起来就是，如果环境问题不解决，污染持续加重，那么经济建设最终也会受到影响，发展将是不可持续的。因此，选项A正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"说法过于绝对，党和政府正在努力扭转环境污染严重、生态系统退化的严峻形势，故不选。","C":"人对自然应怀有敬畏之心、感恩之心、报恩之心，尊重自然界的创造和存在，绝不能凌驾于自然之上，故不选。","D":"我国涉及环境方面的法律法规还不健全，必须建立系统完善的制度体系，用制度保障生态环境、推进生态文明建设，故不选。"}}},{"id":"advanced-xisixiang-test5-6","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试五","chapterKey":"综合测试五","n":6,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试五 第 6 题"},"stem":"1997年7月1日，中国政府对香港恢复行使主权，香港特别行政区成立，香港特别行政区基本法开始实施。香港进入了“一国两制”、“港人治港”、高度自治的历史新纪元。香港特别行政区的高度自治权是","choices":[{"id":"A","text":"特别行政区的完全自治权"},{"id":"B","text":"中央授权之外的剩余权力"},{"id":"C","text":"特别行政区本身固有的权力"},{"id":"D","text":"中央授予的地方事务管理权"}],"answer":["D"],"analysis":{"point":"本题考查“一国两制”在香港的成功实践。2014年6月10日，国务院新闻办公室发表的《“一国两制”在香港特别行政区的实践》白皮书指出，香港特别行政区的高度自治权的唯一来源是中央授权，高度自治权是中央授予的地方事务管理权。因此，选项D正确。","options":{"A":"香港特别行政区享有的高度自治权不是完全自治权也不是分权，而是中央授予的地方事务管理权，故不选。","B":"高度自治权的限度在于中央授予多少权力，香港特别行政区就享有多少权力，不存在“剩余权力”，故不选。","C":"自治权不是自治地区本身固有的，而是中央授予的，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-xisixiang-test5-7","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试五","chapterKey":"综合测试五","n":7,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试五 第 7 题"},"stem":"在文化传承发展座谈会上，习近平总书记系统总结了中华文明的五大突出特性，科学阐述了“两个结合”的历史逻辑、理论逻辑和实践逻辑。习近平总书记特别指出，“第二个结合”表明","choices":[{"id":"A","text":"我们党对自我革命的认识达到了新高度"},{"id":"B","text":"我们党对中国道路、理论、制度的认识达到了新高度"},{"id":"C","text":"我们党的历史自信、文化自信达到了新高度"},{"id":"D","text":"我们党在传承中华优秀传统文化中推进理论创新的自觉性达到了新高度"}],"answer":["B","C","D"],"analysis":{"point":"本题考查“两个结合”。“两个结合”让中国特色社会主义道路有了更加宏阔深远的历史纵深，拓展了中国特色社会主义道路的文化根基，开辟了广阔的理论和实践创新空间，表明我们党对中国道路、理论、制度的认识达到了新高度，表明我们党的历史自信、文化自信达到了新高度，表明我们党在传承中华优秀传统文化中推进理论创新的自觉性达到了新高度。因此，选项B、C、D正确。","options":{"A":"“自我革命”是党的自身建设问题，而“两个结合”是理论创新与发展的问题，二者不属于一个问题，故不选。","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-xisixiang-test5-8","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试五","chapterKey":"综合测试五","n":8,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试五 第 8 题"},"stem":"2024年7月，党的二十届三中全会审议通过了《中共中央关于进一步全面深化改革、推进中国式现代化的决定》，紧紧围绕推进中国式现代化这个主题擘画进一步全面深化改革战略举措，彰显了以习近平同志为核心的党中央将改革进行到底的坚强决心和强烈使命担当。会议提出，到2035年","choices":[{"id":"A","text":"基本建成高水平社会主义市场经济体制"},{"id":"B","text":"中国特色社会主义制度更加完善"},{"id":"C","text":"基本实现国家治理体系和治理能力现代化"},{"id":"D","text":"基本实现社会主义现代化"}],"answer":["B","C","D"],"analysis":{"point":"本题考查进一步全面深化改革的时间表和路线图。党的二十届三中全会指出，到2035年，全面建成高水平社会主义市场经济体制，中国特色社会主义制度更加完善，基本实现国家治理体系和治理能力现代化，基本实现社会主义现代化，为到21世纪中叶全面建成社会主义现代化强国奠定坚实基础。到2029年中华人民共和国成立80周年时，完成《中共中央关于进一步全面深化改革、推进中国式现代化的决定》提出的改革任务。因此，选项B、C、D正确。","options":{"A":"到2035年，要全面建成高水平社会主义市场经济体制，而不是“基本建成”，故不选。","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-xisixiang-test5-9","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试五","chapterKey":"综合测试五","n":9,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试五 第 9 题"},"stem":"我国社会主义政治制度优越性的一个突出特点是党发挥总揽全局、协调各方的领导核心作用，形象地说是“众星捧月”，这个“月”就是中国共产党。健全党的全面领导制度必须","choices":[{"id":"A","text":"以完善组织建设为党的根本性建设"},{"id":"B","text":"完善党在各种组织中发挥领导作用的制度"},{"id":"C","text":"完善党协调各方的机制"},{"id":"D","text":"完善党领导各项事业的具体制度"}],"answer":["B","C","D"],"analysis":{"point":"本题考查健全党的全面领导制度。第一，必须完善党在各种组织中发挥领导作用的制度。第二，必须完善党协调各方的机制。第三，必须完善党领导各项事业的具体制度。因此，选项B、C、D正确。","options":{"A":"习近平指出，政治建设是党的根本性建设，决定党的建设的方向和效果，故不选。","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-xisixiang-test5-10","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试五","chapterKey":"综合测试五","n":10,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试五 第 10 题"},"stem":"习近平总书记强调：“对外开放是中国的基本国策，中国正在推进高水平对外开放，稳步扩大规则、规制、管理、标准等制度型开放。”2025年，中国外贸承压不小，但交出的成绩单令全球瞩目。上半年，我国出口规模历史同期首次突破13万亿元，同比增长7.2%。同时，我国有进出口实绩的外贸企业数量增至62.8万家，历史同期首次突破60万家，较去年同期增加4.3万家。中国经济稳健前行，表明我国","choices":[{"id":"A","text":"外贸韧性和抗冲击能力跃升"},{"id":"B","text":"国际贸易合作水平显著提高"},{"id":"C","text":"对世界市场的需求逐步减弱"},{"id":"D","text":"为世界经济注入更多稳定性"}],"answer":["A","B","D"],"analysis":{"point":"本题考查扩大高水平对外开放。题干中，我国2025年上半年出口同比增长7.2%，外贸企业数量历史同期首次突破60万家。这有力说明了我国外贸韧性和抗冲击能力跃升，国际贸易合作水平显著提高，中国经济的稳健前行为世界经济注入更多稳定性。因此，选项A、B、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"题干表明中国经济在世界市场的参与度增强，而非需求减弱，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-xisixiang-test5-11","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试五","chapterKey":"综合测试五","n":11,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试五 第 11 题"},"stem":"习近平主席曾经在第三届“一带一路”国际合作高峰论坛开幕式上宣布，全面取消制造业领域外资准入限制措施。党的二十届三中全会指出，合理缩减外资准入负面清单。国家发展改革委于2024年9月6日公布《外商投资准入特别管理措施（负面清单）（2024年版）》，该规章自2024年11月1日起施行。这充分展示了我国坚定不移推动投资自由化便利化的决心和推动全球开放合作的担当。《外商投资准入特别管理措施（负面清单）（2024年版）》的发布表明","choices":[{"id":"A","text":"我国制造业领域外资准入限制措施实现“清零”"},{"id":"B","text":"标志着高水平对外开放再有新进展"},{"id":"C","text":"标志着我国制造业对外开放达到世界领先水平"},{"id":"D","text":"标志着我国实现了高水平科技自立自强"}],"answer":["A","B","C"],"analysis":{"point":"本题考查《外商投资准入特别管理措施（负面清单）（2024年版）》修订的重要意义。《外商投资准入特别管理措施（负面清单）（2024年版）》全面取消了制造业领域外资准入限制措施。这是建设现代化产业体系的重要举措，有助于我国更深层次参与全球产业分工与合作，有利于进一步持续优化引资结构，加快发展新质生产力，将进一步提升营商环境的市场化、法治化、国际化水平。本次负面清单修订后，我国制造业领域外资准入限制措施实施“清零”，标志着高水平对外开放再有新进展，标志着我国制造业对外开放达到世界领先水平。因此，选项A、B、C正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"表述错误，我国将在2035年实现高水平科技自立自强，故不选。"}}},{"id":"advanced-xisixiang-test5-12","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试五","chapterKey":"综合测试五","n":12,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试五 第 12 题"},"stem":"2024年的《政府工作报告》提出，“鼓励和推动消费品以旧换新”；2024年3月，国务院印发了《推动大规模设备更新和消费品以旧换新行动方案》。推动大规模设备更新和消费品以旧换新","choices":[{"id":"A","text":"是加快构建新发展格局、推动高质量发展的重要举措"},{"id":"B","text":"有利于提高国民经济循环质量和运行效率"},{"id":"C","text":"旨在促进进出口贸易稳定增长"},{"id":"D","text":"将有力促进投资和消费"}],"answer":["A","B","D"],"analysis":{"point":"本题考查推动大规模设备更新和消费品以旧换新的重大意义。国务院印发的《推动大规模设备更新和消费品以旧换新行动方案》指出，推动大规模设备更新和消费品以旧换新是加快构建新发展格局、推动高质量发展的重要举措，将有力促进投资和消费，既利当前、更利长远。要统筹扩大内需和深化供给侧结构性改革，实施设备更新、消费品以旧换新、回收循环利用、标准提升四大行动，大力促进先进设备生产应用，推动先进产能比重持续提升，推动高质量耐用消费品更多进入居民生活，畅通资源循环利用链条，大幅提高国民经济循环质量和水平。因此，选项A、B、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"推动大规模设备更新和消费品以旧换新的出发点不是进出口贸易增长问题，而是国内大循环问题，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-xisixiang-test5-13","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试五","chapterKey":"综合测试五","n":13,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试五 第 13 题"},"stem":"习近平明确指出：“非公有制经济在我国经济社会发展中的地位和作用没有变，我们毫不动摇鼓励、支持、引导非公有制经济发展的方针政策没有变，我们致力于为非公有制经济发展营造良好环境和提供更多机会的方针政策没有变。”在我国现存的所有制结构中，私营经济","choices":[{"id":"A","text":"不受公有制经济的影响和制约"},{"id":"B","text":"以生产资料私人占有和雇佣劳动为基础"},{"id":"C","text":"是由社会主义初级阶段的生产力发展状况决定的"},{"id":"D","text":"是社会主义市场经济的重要组成部分"}],"answer":["B","C","D"],"analysis":{"point":"本题考查非公有制经济。毫不动摇地鼓励、支持和引导非公有制经济发展，是坚持和完善社会主义初级阶段基本经济制度必须遵循的一条基本原则。私营经济是以生产资料私人占有和雇佣劳动为基础的经济形式，它是我国社会主义初级阶段基本经济制度的构成内容，是社会主义市场经济的重要组成部分。在我国现阶段，大力发展包括私营经济在内的非公有制经济从根本上讲是由社会主义初级阶段的生产力发展状况决定的。因此，选项B、C、D正确。","options":{"A":"在我国现阶段，坚持以公有制为主体，促进非公有制经济发展，统一于社会主义现代化建设的进程中，私营经济受公有制经济的影响和制约，故不选。","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-xisixiang-test5-14","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试五","chapterKey":"综合测试五","n":14,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试五 第 14 题"},"stem":"新中国成立70多年特别是改革开放40多年来，创造了经济快速发展和社会长期稳定两大奇迹，靠的是中国共产党坚强领导和中国人民团结奋斗，这也离不开国际社会支持帮助，包括在华外资企业作出的贡献。外商来华投资","choices":[{"id":"A","text":"成为社会主义经济的重要组成部分"},{"id":"B","text":"带动了中国经济增长和就业"},{"id":"C","text":"促进了中国技术和管理进步"},{"id":"D","text":"助推了中国改革开放"}],"answer":["B","C","D"],"analysis":{"point":"本题考查外资企业来华投资对我国发展的贡献。2025年3月28日，习近平在北京人民大会堂会见国际工商界代表时强调，新中国成立70多年特别是改革开放40多年来，创造了经济快速发展和社会长期稳定两大奇迹，靠的是中国共产党坚强领导和中国人民团结奋斗，这也离不开国际社会支持帮助，包括在华外资企业作出的贡献。改革开放使中国快速进入世界市场、大踏步赶上时代，重要一条就是积极利用外资。外商来华投资，带动了中国经济增长和就业，促进了中国技术和管理进步，助推了中国改革开放。实践证明，外资企业是中国式现代化的重要参与者，是中国改革开放和创新创造的重要参与者，是中国联通世界、融入经济全球化的重要参与者。在这一过程中，外商普遍得到丰厚回报，企业不断发展壮大，实现了互利共赢，也同中国人民结下深厚友谊。因此，选项B、C、D正确。","options":{"A":"在我国，社会主义经济主要是指公有制经济，包括国有经济和集体经济，还包括混合所有制经济中的国有成分和集体成分。非公有制经济包括个体经济、私营经济、港澳台投资经济、外商投资经济以及混合所有制经济中的非国有成分和非集体成分。外商投资经济是社会主义市场经济的重要组成部分，而不是社会主义经济的重要组成部分，故不选。","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-xisixiang-test5-15","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试五","chapterKey":"综合测试五","n":15,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试五 第 15 题"},"stem":"习近平总书记在《正确认识和把握我国发展重大理论和实践问题》一文中指出，要正确认识和把握资本的特性和行为规律，要为资本设置“红绿灯”。这里的“红绿灯”的作用在于","choices":[{"id":"A","text":"防止有些资本野蛮生长"},{"id":"B","text":"依法加强对资本的有效监管"},{"id":"C","text":"支持和引导资本规范健康发展"},{"id":"D","text":"防止资本主义国家的资本进入"}],"answer":["A","B","C"],"analysis":{"point":"本题考查正确认识和把握资本的特性和行为规律。习近平总书记在《正确认识和把握我国发展重大理论和实践问题》一文中指出，要正确认识和把握资本的特性和行为规律。搞社会主义市场经济是我们党的一个伟大创造。要探索如何在社会主义市场经济条件下发挥资本的积极作用，同时有效控制资本的消极作用。要为资本设置“红绿灯”，依法加强对资本的有效监管，防止有些资本野蛮生长，支持和引导资本规范健康发展。因此，选项A、B、C正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"资本本身无所谓姓“资”还是姓“社”，关键在于我们能否正确引导发挥资本的积极作用，同时有效控制资本的消极作用，不能简单地防止资本主义国家的资本进入，而应该有序规范地加以利用，故不选。"}}},{"id":"advanced-xisixiang-test5-16","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试五","chapterKey":"综合测试五","n":16,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试五 第 16 题"},"stem":"构建新发展格局，涉及我国经济发展的各个方面、各个领域，要准确把握基本要求，加强整体协调和系统布局，推动国内循环和国际循环相互促进、良性互动。要处理好国内循环和国际循环的关系，必须","choices":[{"id":"A","text":"具备强大的国内经济循环体系和稳固的基本盘"},{"id":"B","text":"实施更大范围、更宽领域、更深层次的对外开放"},{"id":"C","text":"提升国内国际双循环的效率和水平"},{"id":"D","text":"始终坚持以国际大循环为主体提升开放水平"}],"answer":["A","B","C"],"analysis":{"point":"本题考查构建新发展格局。要处理好国内循环和国际循环的关系，一方面，必须具备强大的国内经济循环体系和稳固的基本盘，保持国内经济持续健康发展，巩固和发展我国经济的强大竞争力。另一方面，必须实施更大范围、更宽领域、更深层次的对外开放，提升国内国际双循环的效率和水平。要通过参与国际市场竞争，增强我国出口产品和服务竞争力，推动我国产业转型升级。因此，选项A、B、C正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"表述错误，构建新发展格局必须以国内大循环为主体，国内国际双循环相互促进，故不选。"}}},{"id":"advanced-xisixiang-test5-17","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试五","chapterKey":"综合测试五","n":17,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试五 第 17 题"},"stem":"改革开放40年来，我国民营经济从小到大、从弱到强，不断发展壮大。截至2017年年底，我国民营企业数量超过2 700万家，个体工商户超过6 500万户，注册资本超过165万亿元。概括起来说，民营经济具有“五六七八九”的特征，即贡献了50%以上的税收，60%以上的国内生产总值，70%以上的技术创新成果，80%以上的城镇劳动就业，90%以上的企业数量。我国经济发展能够创造中国奇迹，民营经济功不可没。这表明，民营经济已成为","choices":[{"id":"A","text":"建设现代化经济体系的重要主体"},{"id":"B","text":"推动社会主义市场经济发展的重要力量"},{"id":"C","text":"实现中华民族伟大复兴中国梦的重要力量"},{"id":"D","text":"控制国民经济命脉的主导力量"}],"answer":["A","B","C"],"analysis":{"point":"本题考查民营经济的地位。民营经济是我国经济制度的内在要素，是社会主义市场经济发展的重要成果，是推动社会主义市场经济发展的重要力量，是推动供给侧结构性改革、推动高质量发展、建设现代化经济体系的重要主体，也是我党长期执政、团结带领全国各族人民实现“两个一百年”奋斗目标和中华民族伟大复兴中国梦的重要力量。因此，选项A、B、C正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"“控制国民经济命脉的主导力量”是国有经济，而不是民营经济，故不选。"}}},{"id":"advanced-xisixiang-test5-18","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试五","chapterKey":"综合测试五","n":18,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试五 第 18 题"},"stem":"国家创新指数是反映国家综合创新能力的重要指标。2025年3月公布的《国家创新指数报告2024》显示，2024年，中国国家创新指数综合排名世界第十位，相比2012年的第二十位提升了10个位次，是十余年来进步最快的国家，也是唯一进入世界前十行列的中等收入国家。我国创新能力持续提升，主要得益于","choices":[{"id":"A","text":"坚持科技创新和体制机制创新双轮驱动"},{"id":"B","text":"现代化经济体系已经形成"},{"id":"C","text":"基础研究和原始创新不断加强"},{"id":"D","text":"把创新驱动落实到现代化建设整个进程和各个方面"}],"answer":["A","C","D"],"analysis":{"point":"本题考查创新。我国进入创新型国家行列，基础研究和原始创新不断加强，一些关键核心技术实现突破，战略性新兴产业发展壮大，科技事业实现了历史性、整体性、格局性重大变化。创新驱动发展战略，就是要坚持创新是第一动力，把创新驱动落实到现代化建设整个进程和各个方面，坚持科技创新和体制机制创新双轮驱动，以创新推动经济转型发展，全面提升创新能力和效率，把创新发展主动权牢牢掌握在自己手中。因此，选项A、C、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"时态错误，我国正在建设现代化经济体系，故不选。","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-xisixiang-test5-19","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试五","chapterKey":"综合测试五","n":19,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试五 第 19 题"},"stem":"在中国社会主义制度下，有事好商量、众人的事情由众人商量，找到全社会意愿和要求的最大公约数，是人民民主的真谛。习近平总书记指出，社会主义协商民主，是中国社会主义民主政治的特有形式和独特优势。在我国，社会主义协商民主源自","choices":[{"id":"A","text":"中华民族长期形成的优秀政治文化"},{"id":"B","text":"近代以后中国政治发展的现实进程"},{"id":"C","text":"中国共产党领导人民进行革命、建设、改革的长期实践"},{"id":"D","text":"在西方竞争式民主基础上的改良"}],"answer":["A","B","C"],"analysis":{"point":"本题考查协商民主。社会主义协商民主源自中华民族长期形成的天下为公、兼容并蓄、求同存异等优秀政治文化，源自近代以后中国政治发展的现实进程，源自中国共产党领导人民进行革命、建设、改革的长期实践，源自中华人民共和国成立后各党派、各团体、各民族、各阶层、各界人士在政治制度上共同实现的伟大创造，源自改革开放以来中国在政治体制上的不断创新，具有深厚的文化基础、理论基础、实践基础、制度基础。因此，选项A、B、C正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"社会主义协商民主并不是在西方竞争式民主的基础上形成的，相反它具有中国特色，扎根于本土文化，故不选。"}}},{"id":"advanced-xisixiang-test5-20","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试五","chapterKey":"综合测试五","n":20,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试五 第 20 题"},"stem":"与十一届全国人民代表大会相比，十二届全国人民代表大会在代表结构与组成上，呈现“两升一降”的变化：来自一线的工人、农民代表401名，占代表总数的13.42%，提高了5.18个百分点；专业技术人员代表610名，占代表总数的20.42%，提高了1.2个百分点；党政领导干部代表1042名，占代表总数的34.88%，降低了6.93个百分点。提高基层人大代表特别是一线工人、农民、知识分子代表比例，降低党政领导干部代表比例，有利于","choices":[{"id":"A","text":"推动人民群众最关心最直接最现实问题的解决"},{"id":"B","text":"调动基层群众参政议政的积极性和主动性"},{"id":"C","text":"保证人民群众直接参加国家管理"},{"id":"D","text":"更为充分地发挥全国人大的民意反映与监督职能"}],"answer":["A","B","D"],"analysis":{"point":"本题考查社会主义民主。提高基层人大代表特别是一线工人、农民、知识分子代表比例，有利于推动人民群众最关心最直接最现实问题的解决，调动基层群众参政议政的积极性和主动性，更为充分地发挥全国人大的民意反映与监督职能。因此，选项A、B、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"人民群众通过选举人大代表间接参与国家管理，并非直接参加国家管理，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-xisixiang-test5-21","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试五","chapterKey":"综合测试五","n":21,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试五 第 21 题"},"stem":"培育和践行社会主义核心价值观，是推进中国特色社会主义伟大事业、实现中华民族伟大复兴中国梦的战略任务。因为，倡导富强、民主、文明、和谐，倡导自由、平等、公正、法治，倡导爱国、敬业、诚信、友善的社会主义核心价值观","choices":[{"id":"A","text":"与中华优秀传统文化和人类优秀文明成果相承接"},{"id":"B","text":"与中国特色社会主义发展要求相契合"},{"id":"C","text":"强调了全人类道德的普世性"},{"id":"D","text":"是我们党凝聚全党全社会价值共识作出的重要论断"}],"answer":["A","B","D"],"analysis":{"point":"本题考查培育和践行社会主义核心价值观。培育和践行社会主义核心价值观，是推进中国特色社会主义伟大事业、实现中华民族伟大复兴中国梦的战略任务。党的十八大提出，倡导富强、民主、文明、和谐，倡导自由、平等、公正、法治，倡导爱国、敬业、诚信、友善，积极培育和践行社会主义核心价值观。这与中国特色社会主义发展要求相契合，与中华优秀传统文化和人类优秀文明成果相承接，是我们党凝聚全党全社会价值共识作出的重要论断。因此，选项A、B、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"表述错误，普世价值是不存在的，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-xisixiang-test5-22","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试五","chapterKey":"综合测试五","n":22,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试五 第 22 题"},"stem":"新中国成立以来，我国文化进出口规模持续扩大，结构不断优化，中华文化“走出去”步伐加快。据商务部统计，2024年我国文化贸易总额达到1.4万亿元。我国与“一带一路”共建国家和地区文化产品进出口总额由2012年的129.1亿美元增加到2024年的505.3亿美元。新话语、新形式助推文化交流国际化水平进一步提高，国家文化软实力、中华文化感召力、国际传播影响力显著提升。我国文化贸易的快速发展充分表明，文化繁荣兴盛是","choices":[{"id":"A","text":"建设社会主义现代化强国的应有之义"},{"id":"B","text":"社会主义生产的根本目的"},{"id":"C","text":"实现中华民族伟大复兴的精神支撑"},{"id":"D","text":"在世界文化激荡中站稳脚跟的前提基础"}],"answer":["A","C","D"],"analysis":{"point":"本题考查文化繁荣兴盛。文化繁荣兴盛是实现中华民族伟大复兴的精神支撑，是建设社会主义现代化强国的应有之义，是满足人民日益增长的美好生活需要的内在要求，是在世界文化激荡中站稳脚跟的前提基础。因此，选项A、C、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"增进民生福祉是社会主义生产的根本目的，故不选。","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-xisixiang-test5-23","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试五","chapterKey":"综合测试五","n":23,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试五 第 23 题"},"stem":"“民生是最大的政治”，民生是人民幸福之基、政府为政之要、社会和谐之本。习近平总书记强调：“让老百姓过上好日子是我们一切工作的出发点和落脚点。”要在发展过程中始终注重民生、保障民生、改善民生，根据经济发展和财力状况，逐步提高人民生活水平，让群众得到更多看得见、摸得着的实惠，不断厚植民生福祉。这是因为","choices":[{"id":"A","text":"发展是改善民生的物质基础"},{"id":"B","text":"民生连着内需、连着发展"},{"id":"C","text":"抓民生也是抓发展"},{"id":"D","text":"民生和发展是相互牵动、互为条件的关系"}],"answer":["A","B","C","D"],"analysis":{"point":"本题考查发展与民生的关系。发展是改善民生的物质基础，离开发展谈改善民生是无源之水、无本之木。民生连着内需、连着发展。抓民生也是抓发展，持续不断改善民生，能够有效解决群众后顾之忧，调动人们发展生产的积极性，增进社会消费预期，扩大内需，催生新的增长点。要全面把握民生和发展相互牵动、互为条件的关系，使民生改善和经济发展有效对接、相得益彰，形成改善民生与促进发展有机统一的长效机制。因此，选项A、B、C、D正确。\\n无干扰选项。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-xisixiang-test5-24","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试五","chapterKey":"综合测试五","n":24,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试五 第 24 题"},"stem":"2016年7月以来，中央陆续派出环保督察组进驻各地进行现场督察，掀起了一场新的治污问责风暴。环保督察，从环保部门牵头到中央主导，从以查企业为主转变为“查督并举、以督政为主”，这是我国环境监管模式的重大变革和完善生态文明制度体系的重要举措。建立环保督察工作机制有利于","choices":[{"id":"A","text":"处理好政府与市场的关系"},{"id":"B","text":"追究领导责任和监管责任"},{"id":"C","text":"落实环境保护主体责任"},{"id":"D","text":"完善领导干部目标责任考核制度"}],"answer":["B","C","D"],"analysis":{"point":"本题考查生态文明建设。建立环保督察工作机制是建设生态文明的重要抓手，对严格落实环境保护主体责任、完善领导干部目标责任考核制度、追究领导责任和监管责任，具有重要意义。因此，选项B、C、D正确。","options":{"A":"“处理好政府与市场的关系”是经济体制改革的核心问题，与题干无关，故不选。","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-xisixiang-test5-25","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试五","chapterKey":"综合测试五","n":25,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试五 第 25 题"},"stem":"2023年1月19日，国务院新闻办公室发布《新时代的中国绿色发展》白皮书。该白皮书指出，绿色是生命的象征、大自然的底色，良好生态环境是美好生活的基础、人民共同的期盼。绿色发展是顺应自然、促进人与自然和谐共生的发展，是用最少资源环境代价取得最大经济社会效益的发展，是高质量、可持续的发展，已经成为各国共识。我国高度重视生态文明建设的原因在于","choices":[{"id":"A","text":"大自然是人类赖以生存发展的基本条件"},{"id":"B","text":"尊重自然、顺应自然、保护自然，是全面建设社会主义现代化国家的内在要求"},{"id":"C","text":"建设美丽中国是全面建设社会主义现代化国家的首要任务"},{"id":"D","text":"中国承诺必须成为世界上最快实现碳达峰碳中和的国家"}],"answer":["A","B"],"analysis":{"point":"本题考查生态文明建设。党的二十大报告指出：“大自然是人类赖以生存发展的基本条件。尊重自然、顺应自然、保护自然，是全面建设社会主义现代化国家的内在要求。必须牢固树立和践行绿水青山就是金山银山的理念，站在人与自然和谐共生的高度谋划发展。”因此，选项A、B正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"高质量发展是全面建设社会主义现代化国家的首要任务，故不选。","D":"说法违背政治常识，我们的目标不是成为世界上最快实现碳达峰碳中和的国家。事实上，根据我国的实际情况，我们有清晰的规划，即力争2030年前实现碳达峰，2060年前实现碳中和。故不选。"}}},{"id":"advanced-xisixiang-test5-26","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试五","chapterKey":"综合测试五","n":26,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试五 第 26 题"},"stem":"为深入实施国家“江河战略”，全面推进江河保护治理，进一步提升水安全保障能力，2025年6月，中共中央办公厅、国务院办公厅印发《关于全面推进江河保护治理的意见》（简称《意见》）。《意见》从战略和全局高度，对我国江河保护治理进行顶层设计，明确了全面推进江河保护治理的总体要求、主要目标等。全面推进江河保护治理有利于","choices":[{"id":"A","text":"更好适应以高质量发展全面推进中国式现代化的需要"},{"id":"B","text":"加快推进江河保护治理体系和治理能力现代化"},{"id":"C","text":"把生态环境这个最大的民生抓实抓牢"},{"id":"D","text":"形成人水和谐共生的江河保护治理格局"}],"answer":["A","B","D"],"analysis":{"point":"本题考查生态环境建设。全面推进江河保护治理有利于更好适应以高质量发展全面推进中国式现代化的需要，更好满足人民日益增长的美好生活需要；有利于加快推进江河保护治理体系和治理能力现代化，形成江河哺育人民、人民守护江河、人水和谐共生的江河保护治理格局。因此，选项A、B、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"表述错误，就业是最大的民生，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-xisixiang-test5-27","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试五","chapterKey":"综合测试五","n":27,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试五 第 27 题"},"stem":"《新时代的中国国家安全》白皮书指出，新时代的中国国家安全，坚持中国特色国家安全道路，是总体的、系统的、相对的大安全，是以人民安全为宗旨、以政治安全为根本、以国家利益为准则的安全，是","choices":[{"id":"A","text":"服务和促进高质量发展的安全"},{"id":"B","text":"根据经济社会发展动态调整的安全"},{"id":"C","text":"支撑进一步扩大高水平开放的安全"},{"id":"D","text":"在法治轨道上规范运行的安全"}],"answer":["A","B","C","D"],"analysis":{"point":"本题考查新时代的中国国家安全。国务院新闻办公室发布《新时代的中国国家安全》白皮书，旨在全面阐释新时代中国国家安全工作的创新理念、生动实践和建设成果，增进国际社会对中国国家安全的认知和理解。该白皮书指出，新时代的中国国家安全，坚持中国特色国家安全道路，是总体的、系统的、相对的大安全，是以人民安全为宗旨、以政治安全为根本、以国家利益为准则的安全，是服务和促进高质量发展的安全，是根据经济社会发展动态调整的安全，是支撑进一步扩大高水平开放的安全，是在法治轨道上规范运行的安全。因此，选项A、B、C、D正确。\\n无干扰选项。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-xisixiang-test5-28","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试五","chapterKey":"综合测试五","n":28,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试五 第 28 题"},"stem":"“一国两制”是中华民族对人类政治文明的独特贡献。“和平统一、一国两制”构想丰富和发展了马克思主义，具有重大的意义。这表现在“和平统一、一国两制”构想","choices":[{"id":"A","text":"创造性地发展了马克思主义的国家学说"},{"id":"B","text":"有利于争取社会主义现代化建设事业所需要的和平的国际环境与国内环境"},{"id":"C","text":"为解决国际争端和历史遗留问题提供了新的思路"},{"id":"D","text":"创造性地将和平共处原则的精神应用于解决国家内部问题"}],"answer":["A","B","C","D"],"analysis":{"point":"本题考查“和平统一、一国两制”构想的重大意义。其意义包括：第一，“和平统一、一国两制”构想创造性地发展了马克思主义的国家学说。第二，和平共处是处理国际关系必须遵循的普遍准则，“一国两制”构想创造性地将和平共处原则的精神应用于解决一个国家内部不同社会制度的地区之间的关系，以解决祖国统一的问题。第三，“和平统一、一国两制”构想有利于争取社会主义现代化建设事业所需要的和平的国际环境与国内环境。第四，“和平统一、一国两制”构想为解决国际争端和历史遗留问题提供了新的思路。因此，选项A、B、C、D正确。\\n无干扰选项。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-xisixiang-test5-29","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试五","chapterKey":"综合测试五","n":29,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试五 第 29 题"},"stem":"从2013年在莫斯科国际关系学院首次提出，到2015年在联合国大会一般性辩论上明确“五位一体”实现路径，再到2017年在联合国日内瓦总部提出建设“五个世界”的总目标，人类命运共同体重大理念的科学内涵日益丰富拓展。构建人类命运共同体理念直面当今世界最重要的问题，展现出强大影响力、生命力和感召力。下列属于构建人类命运共同体的世界意义的有","choices":[{"id":"A","text":"为国际关系确立新思路"},{"id":"B","text":"为全球治理提供新智慧"},{"id":"C","text":"为民族统战展现新活力"},{"id":"D","text":"为国际交往开创新格局"}],"answer":["A","B","D"],"analysis":{"point":"本题考查人类命运共同体。构建人类命运共同体的世界意义包括：第一，为国际关系确立新思路；第二，为全球治理提供新智慧；第三，为国际交往开创新格局；第四，为美好世界描绘新愿景。因此，选项A、B、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"民族统战属于国内角度，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-xisixiang-test5-30","moduleId":"advanced","subjectId":"xisixiang","chapter":"综合测试五","chapterKey":"综合测试五","n":30,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"习思想 · 综合测试五 第 30 题"},"stem":"党的二十大报告指出，我们开展了史无前例的反腐败斗争，以“得罪千百人、不负十四亿”的使命担当祛疴治乱，“打虎”“拍蝇”“猎狐”多管齐下，反腐败斗争取得压倒性胜利并全面巩固，消除了党、国家、军队内部存在的严重隐患。之所以说反腐败斗争一刻不能停，必须永远吹冲锋号，是因为","choices":[{"id":"A","text":"人民群众最痛恨腐败现象"},{"id":"B","text":"腐败是危害党的生命力和战斗力的最大毒瘤"},{"id":"C","text":"反腐败是党的根本性建设"},{"id":"D","text":"反腐败是最彻底的自我革命"}],"answer":["A","B","D"],"analysis":{"point":"本题考查反腐败斗争。人民群众最痛恨腐败现象是党的十九大报告的内容。习近平总书记在党的二十大报告中再次强调，坚决打赢反腐败斗争攻坚战持久战。腐败是危害党的生命力和战斗力的最大毒瘤，反腐败是最彻底的自我革命。只要存在腐败问题产生的土壤和条件，反腐败斗争就一刻不能停，必须永远吹冲锋号。坚持不敢腐、不能腐、不想腐一体推进，以零容忍态度反腐惩恶，决不姑息。因此，选项A、B、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"党的根本性建设是党的政治建设，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-shigang-test1-1","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试一","chapterKey":"综合测试一","n":1,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试一 第 1 题"},"stem":"近代以来，中华民族面临着争取民族独立、人民解放和实现国家富强、人民幸福两大历史任务。近代中国的历史表明，要争得民族独立和人民解放，必须首先","choices":[{"id":"A","text":"发展教育提高国民素质"},{"id":"B","text":"废除封建地主土地所有制"},{"id":"C","text":"改变经济技术落后的面貌"},{"id":"D","text":"进行反帝反封建的民主革命"}],"answer":["D"],"analysis":{"point":"本题考查近代中国的历史任务。近代中国的社会性质是半殖民地半封建社会，主要矛盾是帝国主义与中华民族的矛盾、封建主义与人民大众的矛盾，要争得民族独立和人民解放必须首先进行反帝反封建的民主革命。因此，选项D正确。","options":{"A":"都属于近代中国救亡图存的具体方式，但都不算“首先”要进行的任务。","B":"都属于近代中国救亡图存的具体方式，但都不算“首先”要进行的任务。","C":"都属于近代中国救亡图存的具体方式，但都不算“首先”要进行的任务。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-shigang-test1-2","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试一","chapterKey":"综合测试一","n":2,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试一 第 2 题"},"stem":"1840年，英国发动侵略中国的鸦片战争，使独立的中国逐步变成半殖民地的中国，封建的中国逐步变成半封建的中国。英国发动侵略中国的鸦片战争的根本原因是","choices":[{"id":"A","text":"资本主义的扩张本性"},{"id":"B","text":"变中国为其殖民地"},{"id":"C","text":"清政府的禁烟运动"},{"id":"D","text":"清王朝的腐朽没落"}],"answer":["A"],"analysis":{"point":"本题考查英国发动侵略中国的鸦片战争的根本原因，属于理解与识记相结合的试题。16世纪至19世纪初，中国还处于封建社会晚期的兴衰更替之时，西方资本主义已经产生、发展，西方殖民主义势力也随之向外扩张。到19世纪末，资本主义进入帝国主义阶段后，资本输出成为殖民主义剥削的重要形式。这也是资本主义发展到一定程度必然走向殖民扩张道路的一个体现。殖民主义是适应西方资本主义的发展要求而产生的，它随着资本主义生产方式的演进而发展，是西方列强对亚洲、非洲、美洲、大洋洲等地区人民的剥削、掠夺和压迫、奴役。它是为资产阶级剥削国内外人民、建立资本主义的世界体系服务的。因此，选项A正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"属于鸦片战争爆发的直接原因和目的，但不是根本原因。","C":"属于鸦片战争爆发的直接原因和目的，但不是根本原因。","D":"属于鸦片战争爆发的直接原因和目的，但不是根本原因。"}}},{"id":"advanced-shigang-test1-3","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试一","chapterKey":"综合测试一","n":3,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试一 第 3 题"},"stem":"太平天国定都天京后，进行了一系列制度建设，并颁布了《天朝田亩制度》。该纲领将农民平均主义思想进行了制度化。但这篇纲领始终只是空想、幻想，这是因为","choices":[{"id":"A","text":"拜上帝教的教义并非科学的指导思想"},{"id":"B","text":"没有从根本上否定封建地主土地所有制"},{"id":"C","text":"发展资本主义的方案在中国行不通"},{"id":"D","text":"在分散的小农经济基础上不可能真正实现均贫富"}],"answer":["D"],"analysis":{"point":"本题考查《天朝田亩制度》的局限性。《天朝田亩制度》并没有超出农民小生产者的狭隘眼界。它所描绘的理想天国，仍然是闭塞的自给自足的自然经济，是小农业和家庭手工业相结合的传统生活方式；同时又是一个没有商品交换的和绝对平均的社会。这种社会理想，具有不切实际的空想的性质。而且，《天朝田亩制度》中的平分土地方案即使在太平军占领地区也并未付诸实施。因此，选项D正确。","options":{"A":"说法正确，但与题干无关，本题问的是“土地平均主义为什么是空想、幻想”，而不是问“指导思想是不是科学的”，故不选。","B":"《天朝田亩制度》提出“凡天下田，天下人同耕”，包含着彻底否定封建地主土地剥削的主张，虽然最终未付诸实施，但是理论上有此主张，故不选。","C":"与题意不符，本题考查《天朝田亩制度》的相关问题，而选项C涉及的是《资政新篇》是否可行的问题，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-shigang-test1-4","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试一","chapterKey":"综合测试一","n":4,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试一 第 4 题"},"stem":"由于民族危机越来越严重，在维新派的推动和策划下，1898年6月11日，光绪皇帝颁布了“明定国是”谕旨，宣布开始变法，并在此后的103天中，接连发布了一系列推行新政的政令，史称戊戌变法，又称“百日维新”。戊戌维新是一场资产阶级性质的改良运动，这是因为变法的政令","choices":[{"id":"A","text":"一定程度上反映了资产阶级的政治和经济诉求"},{"id":"B","text":"采纳了维新派提出的开国会等政治主张"},{"id":"C","text":"触及了封建制度的根本"},{"id":"D","text":"带有彻底性和不妥协性"}],"answer":["A"],"analysis":{"point":"本题考查戊戌维新运动。洋务运动失败以后，中国先进分子意识到中国的落后不只是军事问题和技术问题，更深层次的是制度问题，因此资产阶级维新派发起了以学习西方君主立宪制度为核心内容的改良运动，这场维新运动反映了资产阶级的政治和经济主张。因此，选项A正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"在戊戌维新运动中，维新派提出了开国会的主张，但是并没有被当政者采纳，故排除。","C":"戊戌维新运动把希望寄托在一个没有实权的皇帝身上，期望能走一条自上而下的改良道路，是无法触及封建制度的根本的，故排除。","D":"“彻底性和不妥协性”是指要将反帝反封建的斗争进行到底，不完成任务不能终止。而戊戌维新运动没有明确的反帝纲领，并且也没有触及封建制度的根本，谈不上彻底性和不妥协性，故排除。"}}},{"id":"advanced-shigang-test1-5","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试一","chapterKey":"综合测试一","n":5,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试一 第 5 题"},"stem":"清政府于1906年宣布“预备仿行宪政”，并于1908年颁布《钦定宪法大纲》，但预备立宪并没有能够挽救清王朝，反而激化了社会矛盾，加重了危机。其主要原因在于清政府改革的根本目的是","choices":[{"id":"A","text":"延续其反动统治"},{"id":"B","text":"维护帝国主义的利益"},{"id":"C","text":"改变中国的社会性质"},{"id":"D","text":"救亡图存"}],"answer":["A"],"analysis":{"point":"本题考查清末“新政”的破产。预备立宪并没有能够挽救清王朝，反而激化了社会矛盾，加重了危机。其主要原因在于，清政府改革的根本目的是延续其反动统治。为了巩固皇权，清政府迟迟不答应资产阶级立宪派提出的关于立即召开国会的要求，还镇压了立宪派的国会请愿运动，同时却不断借立宪之名加强皇权。因此，选项A正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"为杜撰选项，故不选。","C":"不可能是其目的，故不选。","D":"救亡图存是其目的之一，但并非根本目的，故不选。"}}},{"id":"advanced-shigang-test1-6","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试一","chapterKey":"综合测试一","n":6,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试一 第 6 题"},"stem":"孙中山在《建国方略》中说，国人对待自己革命的态度，以庚子失败为界，“前后相较，差若天渊”。人们对孙中山倡导革命的态度发生根本变化的主要原因是","choices":[{"id":"A","text":"民族资产阶级革命力量增强"},{"id":"B","text":"清政府完全沦为帝国主义统治中国的工具"},{"id":"C","text":"资产阶级维新派的改革未成功"},{"id":"D","text":"义和团运动的失败"}],"answer":["B"],"analysis":{"point":"本题考查国人对革命的态度发生根本变化的主要原因。八国联军侵华战争发生以后，列强逼迫清政府签订了《辛丑条约》，清政府完全沦为帝国主义统治中国的工具，成为“洋人的朝廷”。人们开始认识到通过点滴的改革解决不了中国的问题，必须进行革命。这是人们对革命的态度发生根本变化的主要原因。因此，选项B正确。","options":{"A":"都是原因，但不是主要原因，故不选。","B":"（正确选项，分析见“解题思路”）","C":"都是原因，但不是主要原因，故不选。","D":"都是原因，但不是主要原因，故不选。"}}},{"id":"advanced-shigang-test1-7","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试一","chapterKey":"综合测试一","n":7,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试一 第 7 题"},"stem":"中国的民族民主革命是无产阶级领导的资产阶级民主革命，但客观上属于世界无产阶级社会主义革命的一部分是在","choices":[{"id":"A","text":"五四运动后"},{"id":"B","text":"中国共产党成立后"},{"id":"C","text":"十月革命后"},{"id":"D","text":"中华人民共和国成立后"}],"answer":["C"],"analysis":{"point":"本题考查中国民主革命的性质。1917年的俄国十月革命改变了整个世界历史的方向，划分了整个世界历史的时代。在这个时代，殖民地、半殖民地国家如果发生反对帝国主义的革命，客观上就成为世界无产阶级社会主义革命的一部分。中国的民族民主革命，在十月革命后就属于世界无产阶级社会主义革命的一部分了。因此，选项C正确。","options":{"A":"与题意不符，五四运动是中国新民主主义革命的开端，故不选。","B":"与题意不符，中国共产党的成立是“开天辟地的大事变”。中国共产党的成立，使中国革命有了坚强的领导力量、科学的指导思想和新的革命方法，加强了中国革命和世界无产阶级革命之间的联系，使中国革命的面貌从此焕然一新。故不选。","C":"（正确选项，分析见“解题思路”）","D":"与题意不符，中华人民共和国的成立，标志着中国新民主主义革命取得基本的胜利，标志着半殖民地半封建社会的结束和新民主主义社会在全国范围内的建立，故不选。"}}},{"id":"advanced-shigang-test1-8","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试一","chapterKey":"综合测试一","n":8,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试一 第 8 题"},"stem":"第一次世界大战，德国战败。1918年12月，陈独秀在《每周评论》的发刊词中说，大战结果是“公理战胜强权”，并把美国总统威尔逊称作“现在世界上第一个好人”。然而，陈独秀在1919年5月4日出版的《每周评论》上的一篇文章中又写道：“什么公理，什么永久和平，什么威尔逊总统十四条宣言，都成了一文不值的空话。”导致陈独秀认识发生变化的直接原因是","choices":[{"id":"A","text":"中国在巴黎和会上外交失败"},{"id":"B","text":"日本对德宣战，出兵山东"},{"id":"C","text":"苏俄宣布废除从前同中国签订的一切不平等条约"},{"id":"D","text":"美国不愿放弃在华种种特权"}],"answer":["A"],"analysis":{"point":"本题考查五四运动的爆发。在1919年上半年召开的巴黎“和平会议”上，中国政府代表提出废除外国在中国的势力范围、撤退外国在中国的军队和巡警、撤销领事裁判权、归还租界、取消中日“二十一条”及换文的陈述书等正义要求，遭到拒绝。同时，会议不顾中国代表的抗议，规定德国应将在中国山东获得的一切特权转交给日本。陈独秀抨击的正是美国总统假惺惺推崇理想主义外交，而实质却奉行强权至上。因此，选项A正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"1914年8月23日，日本对德国宣战，发生在第一次世界大战结束以前，而本题考查第一次世界大战结束以后的1919年陈独秀认识的变化，时间点错误。故不选。","C":"1919年7月25日，俄国苏维埃政府发表第一次对华宣言，宣布废除沙俄同中国签订的不平等条约，废除俄国在中国的特权，该事件发生在巴黎和会之后。故不选。","D":"美国早在鸦片战争后就已经成为侵华的列强之一，始终不放弃在华特权，这与巴黎和会上中国外交的失败并无直接关联。故不选。"}}},{"id":"advanced-shigang-test1-9","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试一","chapterKey":"综合测试一","n":9,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试一 第 9 题"},"stem":"区别新民主主义革命与旧民主主义革命的根本标志是","choices":[{"id":"A","text":"革命的指导思想不同"},{"id":"B","text":"革命的对象不同"},{"id":"C","text":"革命的前途不同"},{"id":"D","text":"革命的领导权不同"}],"answer":["D"],"analysis":{"point":"本题考查新、旧民主主义革命的区别。区分新、旧民主主义革命的根本标志就是看革命的领导权是掌握在资产阶级手中还是无产阶级手中。因此，选项D正确。","options":{"A":"新民主主义革命的指导思想是马克思主义，旧民主主义革命的指导思想是三民主义，它们的指导思想确实不同，但这不是区分两个革命阶段的根本标志，故不选。","B":"新民主主义革命的对象是封建主义、帝国主义和官僚资本主义，旧民主主义革命的对象也是封建主义、帝国主义和官僚资本主义，二者的革命对象相同，故不选。","C":"新民主主义革命的前途是新民主主义社会乃至社会主义社会，旧民主主义革命的前途是资本主义社会，它们的前途确实不同，但这不是区分两个革命阶段的根本标志，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-shigang-test1-10","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试一","chapterKey":"综合测试一","n":10,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试一 第 10 题"},"stem":"大革命失败后，中国共产党开始了武装反抗国民党反动统治的斗争。然而，南昌起义、秋收起义、广州起义却接连失败了，中国共产党从中得出的最深刻教训是","choices":[{"id":"A","text":"必须武装反抗国民党反动统治"},{"id":"B","text":"必须建立党对军队的绝对领导"},{"id":"C","text":"必须建立新型人民军队"},{"id":"D","text":"必须走适合中国国情的革命道路"}],"answer":["D"],"analysis":{"point":"本题考查对中国革命新道路的探索。党把工作重心由城市转移到农村，在农村开展游击战争，深入进行土地革命，建立和发展红色政权，待条件成熟再夺取全国政权，这就是中国革命的新道路。这正是党在攻打南昌、长沙、广州等中心城市惨遭失利后得出的深刻教训。因此，选项D正确。","options":{"A":"是党在大革命中放弃对武装力量的领导权的教训，并非攻打中心城市失败的教训，故不选。","B":"是三湾改编的成果，并非攻打中心城市失败的教训，故不选。","C":"是党实行武装斗争的重要内容，与题干无关，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-shigang-test1-11","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试一","chapterKey":"综合测试一","n":11,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试一 第 11 题"},"stem":"九一八事变后，抗日救亡运动在全国兴起。中国共产党及其领导的工农红军和广大工人、农民是抗日救亡运动的中坚力量。1935年12月，中共中央在陕北瓦窑堡召开政治局扩大会议，提出党的基本策略任务是","choices":[{"id":"A","text":"建立广泛的抗日民族统一战线"},{"id":"B","text":"实行全面的全民族抗战"},{"id":"C","text":"红军必须绝对服从共产党的领导"},{"id":"D","text":"实行工农兵代表大会制度"}],"answer":["A"],"analysis":{"point":"本题考查瓦窑堡会议。1935年12月，中共中央在陕北瓦窑堡召开政治局扩大会议，提出党的基本策略任务是建立广泛的抗日民族统一战线，批评了党内长期存在的“左”倾冒险主义、关门主义错误倾向。因此，选项A正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"1937年8月，中国共产党在陕北洛川召开政治局扩大会议，制定了抗日救国十大纲领，强调要打倒日本帝国主义，关键在于使已经发动的抗战成为全面的全民族抗战。","C":"1929年12月，古田会议规定红军是一个执行革命的政治任务的武装集团，必须绝对服从共产党的领导，必须全心全意为党的纲领、路线和政策而奋斗。","D":"1931年11月，中华苏维埃第一次全国代表大会在江西瑞金召开，决定实行工农兵代表大会制度。"}}},{"id":"advanced-shigang-test1-12","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试一","chapterKey":"综合测试一","n":12,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试一 第 12 题"},"stem":"1938年5月至6月间，毛泽东发表《论持久战》的讲演，总结全民族抗战10个月来的经验，批驳了“亡国论”“速胜论”等错误观点，系统地阐明了持久战方针。毛泽东在这篇著作中提出的重要思想是","choices":[{"id":"A","text":"“马克思主义的中国化”"},{"id":"B","text":"“须知政权是由枪杆子中取得的”"},{"id":"C","text":"“兵民是胜利之本”"},{"id":"D","text":"“没有调查，没有发言权”"}],"answer":["C"],"analysis":{"point":"本题考查《论持久战》。毛泽东在《论持久战》一文中提出的重要思想是“兵民是胜利之本”。因此，选项C正确。","options":{"A":"1938年，毛泽东在党的六届六中全会上明确提出“马克思主义的中国化”命题，故不选。","B":"1927年，毛泽东在八七会议上提出，“须知政权是由枪杆子中取得的”，故不选。","C":"（正确选项，分析见“解题思路”）","D":"1930年，毛泽东在《反对本本主义》一文中，提出“没有调查，没有发言权”的著名论断，故不选。"}}},{"id":"advanced-shigang-test1-13","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试一","chapterKey":"综合测试一","n":13,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试一 第 13 题"},"stem":"1945年8月29日，重庆《大公报》就毛泽东赴重庆谈判发表了《毛泽东先生来了！》的社评，其中写道：“毛泽东先生来了！中国人听了高兴，世界人听了高兴，无疑问的，大家都认为这是中国的一件大喜事。”毛泽东赴重庆谈判的目的是","choices":[{"id":"A","text":"结束国共内战"},{"id":"B","text":"商讨联合抗日"},{"id":"C","text":"寻求外国援助"},{"id":"D","text":"争取和平民主"}],"answer":["D"],"analysis":{"point":"本题考查毛泽东赴重庆谈判的目的。抗日战争结束以后，毛泽东赴重庆谈判的目的是避免内战，争取和平建国。因此，选项D正确。","options":{"A":"重庆谈判时，国共内战还没有爆发，所以重庆谈判不可能是为了结束国共内战，故排除。","B":"重庆谈判发生在日本天皇以广播“终战诏书”的形式宣布接受《波茨坦公告》，抗日战争取得胜利已成定局之后，因此重庆谈判不可能是为了商讨联合抗日，故排除。","C":"重庆谈判是国共两党商讨和平建国的问题，其目的并不是寻求外国援助。在解放战争时期，为了赢得战争才有寻求外国援助的问题，故排除。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-shigang-test1-14","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试一","chapterKey":"综合测试一","n":14,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试一 第 14 题"},"stem":"在解放战争胜利推进的同时，解放区开展了轰轰烈烈的土地改革运动。1946年5月4日，中共中央发布《关于土地问题的指示》（简称“五四指示”）；1947年7月至9月，中国共产党在河北省平山县西柏坡召开全国土地会议，制定和通过了《中国土地法大纲》。“五四指示”和《中国土地法大纲》的共同之处在于","choices":[{"id":"A","text":"削弱封建剥削"},{"id":"B","text":"实行“耕者有其田”"},{"id":"C","text":"保存富农经济"},{"id":"D","text":"试行余粮收集制"}],"answer":["B"],"analysis":{"point":"本题考查解放战争时期的土地政策。《关于土地问题的指示》（简称“五四指示”）将党在抗日战争时期实行的减租减息政策改变为实行“耕者有其田”的政策，标志着解放区在农民土地问题上，开始由抗日战争时期的削弱封建剥削，向变革封建土地关系、废除封建土地剥削制度过渡。《中国土地法大纲》明确规定“废除封建性及半封建性剥削的土地制度，实行耕者有其田的土地制度”。因此，选项B正确。","options":{"A":"抗战时期的减租减息政策是削弱封建剥削，而解放战争时期是废除封建土地剥削制度。","B":"（正确选项，分析见“解题思路”）","C":"保存富农经济是中华人民共和国成立初期的土改政策。","D":"是列宁的战时共产主义政策中的内容。"}}},{"id":"advanced-shigang-test1-15","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试一","chapterKey":"综合测试一","n":15,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试一 第 15 题"},"stem":"1950年6月，朝鲜战争爆发。美国宣布武装援助南朝鲜，同时命令其海军第七舰队开入台湾海峡，“阻止对台湾的任何进攻”，公然干涉中国内政。中国政府在美国把战火烧到鸭绿江边的时候，毅然作出抗美援朝的决策。中朝两国人民及其军队经过艰苦作战以及谈判斗争，终于在1953年7月迫使美国代表在停战协定上签字。抗美援朝战争的伟大胜利","choices":[{"id":"A","text":"实现了中国共产党和中国革命事业从挫折走向胜利的伟大转折"},{"id":"B","text":"实现了中华民族由不断衰落到根本扭转命运、持续走向繁荣富强的伟大飞跃"},{"id":"C","text":"是中华民族有史以来最为广泛而深刻的社会变革"},{"id":"D","text":"是中国人民站起来后屹立于世界东方的宣言书"}],"answer":["D"],"analysis":{"point":"本题考查抗美援朝战争。抗美援朝战争的伟大胜利，是中国人民站起来后屹立于世界东方的宣言书，是中华民族走向伟大复兴的重要里程碑。因此，选项D正确。","options":{"A":"长征实现了中国共产党和中国革命事业从挫折走向胜利的伟大转折。","B":"中华人民共和国的成立、社会主义制度的建立，是中华民族有史以来最为广泛而深刻的社会变革，为当代中国一切发展进步奠定了根本政治前提和制度基础，实现了中华民族由不断衰落到根本扭转命运、持续走向繁荣富强的伟大飞跃。","C":"中华人民共和国的成立、社会主义制度的建立，是中华民族有史以来最为广泛而深刻的社会变革，为当代中国一切发展进步奠定了根本政治前提和制度基础，实现了中华民族由不断衰落到根本扭转命运、持续走向繁荣富强的伟大飞跃。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-shigang-test1-16","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试一","chapterKey":"综合测试一","n":16,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试一 第 16 题"},"stem":"1952年6月，在“三反”“五反”运动即将结束、全国范围内土地改革基本完成之际，毛泽东指出：“在打倒地主阶级和官僚资产阶级以后，中国内部的主要矛盾即是工人阶级与民族资产阶级的矛盾，故不应再将民族资产阶级称为中间阶级。”这说明","choices":[{"id":"A","text":"民族资产阶级不再具有两面性"},{"id":"B","text":"中国的新民主主义社会已经结束"},{"id":"C","text":"明确提出向社会主义过渡的任务已经成为必要"},{"id":"D","text":"民族资产阶级已经上升为最危险的敌人"}],"answer":["C"],"analysis":{"point":"本题考查党在过渡时期的总路线。1952年6月，毛泽东指出：“在打倒地主阶级和官僚资产阶级以后，中国内部的主要矛盾即是工人阶级与民族资产阶级的矛盾，故不应再将民族资产阶级称为中间阶级。”这说明，明确提出向社会主义过渡的任务已经成为必要。因此，选项C正确。","options":{"A":"在社会主义改造时期，民族资产阶级仍然具有两面性，既有剥削工人取得利润的一面，又有拥护中国共产党的领导、拥护宪法、愿意接受社会主义改造的一面，故不选。","B":"1949年中华人民共和国成立至1956年年底社会主义改造基本完成前的中国社会，属于新民主主义社会的性质，故不选。","C":"（正确选项，分析见“解题思路”）","D":"中国共产党与民族资产阶级长期保持着统一战线的关系，这就为将工人阶级和民族资产阶级之间的对抗性的矛盾转化为非对抗性的矛盾并按照人民内部矛盾来处理提供了前提，故不选。"}}},{"id":"advanced-shigang-test1-17","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试一","chapterKey":"综合测试一","n":17,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试一 第 17 题"},"stem":"中国共产党领导人民进行社会主义建设，有改革开放前和改革开放后两个历史时期，这是两个相互联系又有重大区别的时期，但本质上都是","choices":[{"id":"A","text":"中国共产党革命和建设的伟大实践"},{"id":"B","text":"中国共产党领导人民进行社会主义建设的实践探索"},{"id":"C","text":"中国特色社会主义新时代的产物"},{"id":"D","text":"中国特色社会主义理论指导下的伟大实践"}],"answer":["B"],"analysis":{"point":"本题考查中华人民共和国发展的两个历史时期的相互关系。中国共产党领导人民进行社会主义建设，有改革开放前和改革开放后两个历史时期，这是两个相互联系又有重大区别的时期，但本质上都是中国共产党领导人民进行社会主义建设的实践探索。因此，选项B正确。","options":{"A":"本题探讨的是改革开放前后的两个历史时期，与革命时期无关，不能混淆，故不选。","B":"（正确选项，分析见“解题思路”）","C":"党的十八大之后，中国特色社会主义进入新时代，不能说改革开放是新时代的产物，故不选。","D":"改革开放前，还没有中国特色社会主义这个提法，故不选。"}}},{"id":"advanced-shigang-test1-18","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试一","chapterKey":"综合测试一","n":18,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试一 第 18 题"},"stem":"鸦片战争后，资本-帝国主义列强通过发动侵略战争，强迫中国签订一系列不平等条约，破坏中国的领土主权、领海主权、关税主权、司法主权等，中国丧失了完全独立的地位。但列强也没有能够如英国在印度那样，对中国实行直接的殖民统治，这是因为","choices":[{"id":"A","text":"中国人民顽强、持久的反抗"},{"id":"B","text":"列强间争夺中国的矛盾无法协调"},{"id":"C","text":"中国封建势力拒绝与列强合作"},{"id":"D","text":"中国长期以来是一个统一的大国"}],"answer":["A","B","D"],"analysis":{"point":"本题考查中国沦为半殖民地社会的原因。资本-帝国主义列强侵略中国的目的，是要把它变成自己的殖民地。但是由于中国长期以来一直是一个统一的大国，特别是中国人民顽强、持久的反抗，同时也由于帝国主义列强间争夺中国的矛盾无法协调，使得它们中的任何一个国家都无法单独征服中国，也使得它们不可能共同瓜分中国。因此，中国被称作半殖民地。因此，选项A、B、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"在近代中国，中国封建势力与列强是相互勾结而非拒绝合作的。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-shigang-test1-19","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试一","chapterKey":"综合测试一","n":19,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试一 第 19 题"},"stem":"近代以来，中华民族面临着争取民族独立、人民解放和实现国家富强、人民幸福两大历史任务。两大历史任务之间的关系包括","choices":[{"id":"A","text":"后一个任务是前一个任务的最终目的和必然要求"},{"id":"B","text":"两大历史任务的内容不一样、实现方式一样"},{"id":"C","text":"前一个任务为后一个任务创造必要的前提"},{"id":"D","text":"两大历史任务的时代主题一样"}],"answer":["A","C"],"analysis":{"point":"本题考查近代以来中华民族面临的两大历史任务及其相互关系。近代以来，中华民族面临的两大历史任务，就是争取民族独立、人民解放和实现国家富强、人民幸福。两个任务既相互区别又紧密联系。前一个任务为后一个任务扫除障碍，创造必要的前提；后一个任务是前一个任务的最终目的和必然要求。因此，选项A、C正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"表述错误，应为“两大历史任务的内容、实现方式都不一样”。前一个任务是从根本上推翻半殖民地半封建的统治秩序，改变落后的生产关系和上层建筑，主要依靠革命；后一个任务是要改变近代中国经济、文化落后的地位和状况，发展社会生产力，实现中国的现代化，主要依靠建设和改革。故不选。","C":"（正确选项，分析见“解题思路”）","D":"表述错误，两大历史任务的时代主题不一样，前者的时代主题是战争与革命，后者的时代主题是和平与发展。故不选。"}}},{"id":"advanced-shigang-test1-20","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试一","chapterKey":"综合测试一","n":20,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试一 第 20 题"},"stem":"在清政府镇压太平天国农民战争的过程中和第二次鸦片战争战败后，洋务派发起了一场以“自强”“求富”为目标的洋务运动。这场运动","choices":[{"id":"A","text":"对早期工业和民族资本主义的发展起了促进作用"},{"id":"B","text":"实现了中国向近代化转型的目标"},{"id":"C","text":"进一步传播了西方资产阶级社会政治学说"},{"id":"D","text":"冲击了“重农抑商”的传统价值观"}],"answer":["A","D"],"analysis":{"point":"本题考查洋务运动的历史作用，属于分析理解题。洋务派继承了魏源“师夷长技以制夷”的思想，提出了“自强”“求富”的主张，通过所掌握的国家权力集中力量优先发展军事工业，同时试图“稍分洋商之利”，发展若干民用企业，在客观上对中国的早期工业和民族资本主义的发展起了某些促进作用。选项A正确。洋务运动时期，伴随着资本主义生产方式的出现，传统的“重本抑末”、“重义轻利”、商为“四民”之末等传统观念受到冲击，社会风气和价值观念开始变化，工商业者的地位上升。选项D正确。因此，选项A、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"表述错误，中日甲午战争一役，北洋海军全军覆没，标志着洋务运动最终失败，清政府并没有如愿使中国迈向近代化，故不选。","C":"指的是洋务运动失败后维新派和守旧派的论战，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-shigang-test1-21","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试一","chapterKey":"综合测试一","n":21,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试一 第 21 题"},"stem":"孙中山在1905年的《民报》发刊词中认为，“罗马灭亡，民族主义兴，而欧洲各国以独立”。民族主义就是“驱除鞑虏，恢复中华”，推翻清朝统治，并争取独立自主。但这并不能给中国人民的民族斗争指明正确的方向，因为这一主义","choices":[{"id":"A","text":"实际上推行的是君主立宪和开明专制"},{"id":"B","text":"放走了中国人民的首要的、最大的敌人"},{"id":"C","text":"放松了对汉族封建势力的警惕"},{"id":"D","text":"具有相当程度的软弱性"}],"answer":["B","C","D"],"analysis":{"point":"本题考查三民主义。“驱除鞑虏”是指要以革命手段推翻清朝政府，改变它一贯推行的民族歧视和民族压迫政策，但革命派强调了对满族封建势力的清除而放松了对汉族封建势力的警惕，结果就保留了大量封建势力，导致了辛亥革命后封建势力的反扑；“恢复中华”是指追求独立，建立“民族独立的国家”，但是，这并非明确的反帝纲领，放走了中国人民的最大敌人，甚至害怕帝国主义干涉，幻想以承认不平等条约“继续有效”为条件来换取列强对自己的支持。二者明显表现出革命派在反帝反封建这一问题上的软弱性。因此，选项B、C、D正确。","options":{"A":"属于清政府执政末期的“新政”政策，故不选。","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-shigang-test1-22","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试一","chapterKey":"综合测试一","n":22,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试一 第 22 题"},"stem":"新文化运动初期的基本内容：提倡民主和科学，反对专制和迷信盲从；提倡个性解放，反对封建礼教；提倡新文学，反对旧文学，实行文学革命。五四运动以后的新文化运动，并没有中断或取消五四运动以前开始的反封建的思想启蒙工作，相反，其在很大程度上克服了以往启蒙者的弱点，把反封建的启蒙运动有力地推向前进。这主要表现在","choices":[{"id":"A","text":"从反对封建思想入手，进而提出必须反对产生封建思想的社会制度"},{"id":"B","text":"把反封建思想斗争的立足点，从争取个人的个性解放，扩展到争取人民群众的社会解放的高度"},{"id":"C","text":"把反封建的斗争方式，从少数人进行的思想批判，逐步发展为人民群众的革命实践"},{"id":"D","text":"把反封建的斗争与反帝的斗争彻底结合起来"}],"answer":["A","B","C","D"],"analysis":{"point":"本题考查五四运动以后的新文化运动。五四运动以前，新文化运动由陈独秀等人发起，在当时，这些先进的知识分子也被称为资产阶级激进派的代表人物，他们认为中国国民的劣根性与行为的堕落是亡国的根源，因此，必须改造国民性。随着五四运动的发展，陈独秀等人的思想开始发生变化，最终选择了马克思主义。因此，五四运动以后的新文化运动也有了新的发展。①中国的先进分子在接受马克思主义后，继承了五四运动的民主和科学的精神，但赋予其新的含义。②继承反封建的思想，但有所发展。从反对封建思想入手，进而提出必须反对产生封建思想的社会制度；把反封建思想斗争的立足点，从争取个人的个性解放，扩展到争取人民群众的社会解放的高度；把反封建的斗争方式，从少数人进行的思想批判，逐步发展为人民群众的革命实践。因此，总体来说，五四运动以前的新文化运动主要是资产阶级民主主义的新文化反对封建主义的旧文化；五四运动以后的新文化运动，马克思主义开始逐步在思想文化领域中发挥指导作用。加之，五四运动本身就是一场反帝反封建的群众性爱国运动。因此，选项A、B、C、D正确。\\n无干扰选项。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-shigang-test1-23","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试一","chapterKey":"综合测试一","n":23,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试一 第 23 题"},"stem":"胡绳曾说过：“近代中国在20世纪初，处于一个社会大变革时期，中国民主革命实现了由旧民主主义革命向新民主主义革命的转折，这是诸多历史因素共同作用的结果。”这里的“诸多历史因素”包括","choices":[{"id":"A","text":"无产阶级队伍壮大"},{"id":"B","text":"十月革命的胜利给中国送来了马克思列宁主义"},{"id":"C","text":"新文化运动解放了人们的思想"},{"id":"D","text":"民族资产阶级的软弱性和妥协性"}],"answer":["A","B","C","D"],"analysis":{"point":"本题考查旧民主主义革命向新民主主义革命转折的历史因素。民族资产阶级的软弱性，使其无法完成反帝反封建的革命任务。辛亥革命的失败表明，资产阶级共和国的方案在中国行不通，先进的中国人需要进行新的探索，为中国谋求新的出路。新文化运动促进了人们的思想解放，十月革命的胜利给中国送来了马克思列宁主义。1919年的五四运动标志着中国无产阶级开始作为独立的政治力量登上历史舞台，中国革命进入新民主主义革命阶段。因此，选项A、B、C、D正确。\\n无干扰选项。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-shigang-test1-24","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试一","chapterKey":"综合测试一","n":24,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试一 第 24 题"},"stem":"毛泽东指出：“如果不帮助农民推翻封建地主阶级，就不能组成中国革命最强大的队伍而推翻封建主义和帝国主义的统治。”其含义是","choices":[{"id":"A","text":"农民阶级是中国革命最可靠的同盟军"},{"id":"B","text":"农民阶级是中国革命的领导阶级"},{"id":"C","text":"农民阶级反帝反封建的态度最坚决"},{"id":"D","text":"没有农民阶级参加，中国革命难以取得胜利"}],"answer":["A","D"],"analysis":{"point":"本题考查新民主主义革命的动力。在半殖民地半封建的中国，农民占全国总人口的80%，是中国国民经济的主要力量。他们长期在封建阶级的经济剥削和政治压迫下，过着极端贫困和穷苦的生活，因此，农民问题是中国革命的基本问题，农民阶级是中国革命的主要力量。中国的资产阶级革命如果没有农民阶级参加，是绝不能成功的。农民阶级分为贫农、中农、富农三个部分，其中贫农占农村人口的70%，是中国革命最广大的动力，是无产阶级天然的最可靠的同盟军。因此，选项A、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"表述错误，工人阶级是中国革命的领导阶级，反帝反封建的态度最坚决。故不选。","C":"表述错误，工人阶级是中国革命的领导阶级，反帝反封建的态度最坚决。故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-shigang-test1-25","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试一","chapterKey":"综合测试一","n":25,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试一 第 25 题"},"stem":"1927年10月，毛泽东率领湘赣边界秋收起义的工农革命军，开始创建以宁冈为中心的井冈山农村革命根据地，走农村包围城市、武装夺取政权的革命新道路。毛泽东确定在井冈山建立根据地，是因为这个地区","choices":[{"id":"A","text":"有较好的群众基础"},{"id":"B","text":"地势险要且易守难攻"},{"id":"C","text":"易于部队筹款筹粮"},{"id":"D","text":"敌人的统治力量比较薄弱"}],"answer":["A","B","C","D"],"analysis":{"point":"本题考查建立井冈山革命根据地的原因。选项A、B、C、D的说法均符合井冈山当时的情况，也是将井冈山确立为根据地的原因。井冈山地区受过革命的影响，群众基础好，山区地势险要，易守难攻，农业物产丰富易于筹款筹粮，并且国民党的统治主要集中在城市，山区统治比较薄弱。因此，选项A、B、C、D正确。\\n无干扰选项。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-shigang-test1-26","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试一","chapterKey":"综合测试一","n":26,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试一 第 26 题"},"stem":"在瓦窑堡会议上，毛泽东指出：“目前时局的基本特点，就是日本帝国主义要变中国为它的殖民地，中华民族面临着亡国灭种的严重威胁。”因此，抗日民族统一战线是有可能建立的，这是因为","choices":[{"id":"A","text":"工人、农民和小资产阶级是要抗日的"},{"id":"B","text":"民族资产阶级有抗日的可能性"},{"id":"C","text":"亲英美派的地主买办阶级有参加抗日民族统一战线的可能性"},{"id":"D","text":"大地主大资产阶级有可能放弃同无产阶级争夺抗日民族统一战线的领导权"}],"answer":["A","B","C"],"analysis":{"point":"本题考查抗日民族统一战线建立的可能性。在祖国危急存亡的关头，中华儿女表现出了空前的民族觉醒和民族团结意识，不仅工人、农民、小资产阶级以及民族资产阶级要求抗日，而且中小地主、亲英美派大地主大资产阶级以及地方实力派从自身利益出发，也参加了抗日民族统一战线。因此，选项A、B、C正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"表述错误，大地主大资产阶级不可能放弃同无产阶级争夺抗日民族统一战线的领导权。"}}},{"id":"advanced-shigang-test1-27","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试一","chapterKey":"综合测试一","n":27,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试一 第 27 题"},"stem":"1936年12月12日，张学良和杨虎城为了达到劝谏蒋介石改变“攘外必先安内”的既定国策，停止内战，一致抗日的目的，在西安发动“兵谏”；25日，在中共中央和周恩来的主导下，蒋介石接受了“停止内战，联共抗日”的主张，西安事变最终得到和平解决。西安事变的和平解决","choices":[{"id":"A","text":"为抗日民族统一战线的建立提供了必要前提"},{"id":"B","text":"开启了全面的全民族抗战新阶段"},{"id":"C","text":"成为由国内战争走向抗日民族战争的转折点"},{"id":"D","text":"基本实现了国内的和平"}],"answer":["A","C","D"],"analysis":{"point":"本题考查西安事变，属于记忆题。西安事变的和平解决成为时局转换的枢纽，扭转了十年内战的局面，国内和平基本实现。随后，国民党五届三中全会表示同意国共两党进行谈判，并在会议文件上第一次写上了“抗日”的字样。西安事变发生后，中国共产党从民族大义出发，确定促成事变和平解决的基本方针，并派周恩来等到西安参加谈判，迫使蒋介石作出了停止“剿共”、联合红军抗日等六项承诺。这就意味着国共两党即将停止内战，共同携手抗日。这些都是抗日民族统一战线能够建立的前提。因此，选项A、C、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"表述错误。1937年8月，中国共产党在陕北洛川召开政治局扩大会议，制定了抗日救国十大纲领，强调要打倒日本帝国主义，关键在于使已经发动的抗战成为全面的全民族抗战，由此开启了全民族抗战的新阶段。故不选。","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-shigang-test1-28","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试一","chapterKey":"综合测试一","n":28,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试一 第 28 题"},"stem":"中国新民主主义革命的胜利，结束了帝国主义、封建主义和官僚资本主义在中国的统治，建立了人民民主专政的中华人民共和国。这是中国历史上的伟大转折点，标志着中国社会进入了新的时期。新民主主义革命时期开展土地革命的实质是","choices":[{"id":"A","text":"消灭封建地主的土地所有制"},{"id":"B","text":"实现农民的土地所有制"},{"id":"C","text":"实现土地的公有制"},{"id":"D","text":"没收一切土地"}],"answer":["A","B"],"analysis":{"point":"本题考查新民主主义革命时期开展土地革命的实质。新民主主义革命时期，开展土地革命，就是要消灭封建地主的土地所有制，实现农民的土地所有制，使广大农民在政治上得到翻身，使农村生产力得到解放和发展。因此，选项A、B正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"是社会主义改造的最终目的，故不选。","D":"是中国共产党在《井冈山土地法》中提出的不符合中国实际的土地改革政策，故不选。"}}},{"id":"advanced-shigang-test1-29","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试一","chapterKey":"综合测试一","n":29,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试一 第 29 题"},"stem":"1946年1月10日，政治协商会议在重庆开幕，出席会议的有国民党、共产党、民主同盟、青年党和无党派人士的代表38人。会议通过了政府组织案、国民大会案、和平建国纲领、军事问题案、宪法草案案五项协议。按照协议规定建立的政治体制，相当于英国、法国的议会制和内阁制，不是新民主主义性质的，而且国民党在政府中占着明显的优势。对政协的上述协议，共产党表示赞同并决心严格履行，这是因为它有利于","choices":[{"id":"A","text":"推进民主政治的发展和进步"},{"id":"B","text":"打破国民党一党独裁的局面"},{"id":"C","text":"改变国共两党军事力量对比"},{"id":"D","text":"保障解放区政权的合法地位"}],"answer":["A","B","D"],"analysis":{"point":"本题考查重庆政治协商会议。1946年1月10日，国共双方下达停战令。同一天，政治协商会议在重庆开幕。会上，共产党与民主党派和无党派人士的代表密切合作，推动政协会议达成了政府组织案、国民大会案、和平建国纲领、军事问题案、宪法草案案五项协议。这些决议贯彻了和平民主原则，确认了和平建国方针，确定了国会制、内阁制和省自治的政治制度。政协的上述协议以及其他协议，还不是新民主主义性质的，但它有利于冲破蒋介石的独裁统治和实行民主政治，有利于和平建国，因而在相当程度上是有利于人民的。它激起了亿万善良的中国人对于实现和平、民主、团结、统一的热烈期望。宪法草案的一些规定对于解放区民主政权的存在和发展也有一定的保障作用。因此，选项A、B、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"国共两党军事力量对比的改变是在全面内战爆发后。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-shigang-test1-30","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试一","chapterKey":"综合测试一","n":30,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试一 第 30 题"},"stem":"从1979年11月起，在邓小平的主持下，中共中央着手起草《关于建国以来党的若干历史问题的决议》（简称《历史决议》）。经过一年半时间的讨论和修改，1981年6月，中共十一届六中全会通过了这个决议。《历史决议》的起草和通过表明","choices":[{"id":"A","text":"中国共产党是在政治上、理论上成熟的坚强的马克思主义政党"},{"id":"B","text":"党和国家在指导思想上拨乱反正的胜利完成"},{"id":"C","text":"坚持四项基本原则是实现四个现代化的根本前提"},{"id":"D","text":"中国共产党在反省错误、纠正错误的过程中总结新经验、探索新道路的能力"}],"answer":["A","B","D"],"analysis":{"point":"本题考查《关于建国以来党的若干历史问题的决议》（简称《历史决议》）。《历史决议》的起草和通过表明，党和国家在指导思想上拨乱反正的胜利完成；中国共产党是在政治上、理论上成熟的坚强的马克思主义政党；党能够在“文化大革命”结束后不长的时间里作出这样一个经得起历史检验的决议，体现出以邓小平为核心的中共中央领导集体的成熟和远见，体现出中国共产党在反省错误、纠正错误的过程中总结新经验、探索新道路的能力。因此，选项A、B、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"1979年3月30日，邓小平在党的理论工作务虚会上发表的讲话中指出，坚持社会主义道路，坚持人民民主专政，坚持共产党的领导，坚持马克思列宁主义、毛泽东思想。这四项基本原则，“是实现四个现代化的根本前提”。故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-shigang-test2-1","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试二","chapterKey":"综合测试二","n":1,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试二 第 1 题"},"stem":"毛泽东在《论人民民主专政》中指出：“自从1840年鸦片战争失败那时起，先进的中国人，经过千辛万苦，向西方国家寻找真理。”鸦片战争之所以成为中国近代史的起点，是因为","choices":[{"id":"A","text":"中国社会的阶级关系发生了深刻的变动"},{"id":"B","text":"清政府就此开启了挽救统治危机的各项改革"},{"id":"C","text":"各个阶级对国家的出路进行探索，提出了不同的主张和方案"},{"id":"D","text":"中国社会性质的变化引起了社会主要矛盾和历史任务的变化"}],"answer":["D"],"analysis":{"point":"本题考查鸦片战争成为中国近代史起点的原因。随着外国资本主义的入侵，中国的社会性质开始发生质的变化，中国逐步沦为半殖民地半封建社会。中国社会性质的变化引起了社会主要矛盾的变化，中国逐渐开始了反帝反封建的资产阶级民主革命。正因为如此，鸦片战争成为中国近代史的起点。因此，选项D正确。","options":{"A":"都是在近代中国从封建社会逐步沦为半殖民地半封建社会的过程中发生的变化及表现，并不是鸦片战争成为中国近代史的起点的原因，故不选。","B":"都是在近代中国从封建社会逐步沦为半殖民地半封建社会的过程中发生的变化及表现，并不是鸦片战争成为中国近代史的起点的原因，故不选。","C":"都是在近代中国从封建社会逐步沦为半殖民地半封建社会的过程中发生的变化及表现，并不是鸦片战争成为中国近代史的起点的原因，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-shigang-test2-2","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试二","chapterKey":"综合测试二","n":2,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试二 第 2 题"},"stem":"随着外国资本-帝国主义的入侵，独立的中国逐步变成半殖民地的中国，封建的中国逐步变成半封建的中国。近代中国走向经济现代化和政治民主化的主要障碍是","choices":[{"id":"A","text":"新兴的民族资本主义"},{"id":"B","text":"封建地主阶级"},{"id":"C","text":"旧的被统治阶级"},{"id":"D","text":"官僚资产阶级"}],"answer":["B"],"analysis":{"point":"本题考查半殖民地半封建社会的特征。封建地主阶级是以封建制度剥削和压迫农民的阶级，是在政治上、经济上、文化上阻碍中国社会前进而没有丝毫进步作用的阶级，是中国经济现代化和政治民主化的主要障碍。因此，选项B正确。","options":{"A":"中国资产阶级的来源不同，构成比较复杂。其中，有一部分是官僚买办资本家，另一部分是民族资本家。民族资本主义客观上促进了中国的近代化。","B":"（正确选项，分析见“解题思路”）","C":"旧的被统治阶级即农民阶级。近代中国的农民有些成为产业工人的后备军，是中国民主革命的主力军。","D":"官僚资产阶级也是障碍，但是相比于封建地主阶级，并非主要障碍。"}}},{"id":"advanced-shigang-test2-3","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试二","chapterKey":"综合测试二","n":3,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试二 第 3 题"},"stem":"毛泽东在《中国革命和中国共产党》一文中指出：帝国主义列强侵入中国的目的，决不是要把中国变成资本主义的中国，而是与之相反的。帝国主义列强为了这个目的，曾经对中国采用了多种军事的、政治的、经济的和文化的压迫手段……由此可以明白，帝国主义列强侵略中国，在一方面促使中国封建社会解体，促使中国发生了资本主义因素，把一个封建社会变成了一个半封建的社会；但是在另一方面，它们又","choices":[{"id":"A","text":"破坏了自然经济，为资本主义提供了劳动力的市场"},{"id":"B","text":"完全控制了中国，加剧了中国的政治、经济和文化发展的不平衡"},{"id":"C","text":"维护封建统治阶级利益，支持地主阶级继续占有大量的土地"},{"id":"D","text":"残酷地统治了中国，把一个独立的中国变成了一个半殖民地和殖民地的中国"}],"answer":["D"],"analysis":{"point":"本题考查半殖民地半封建的社会性质。帝国主义侵略中国不是要让中国独立地发展资本主义，而是要把中国变成它们的半殖民地和殖民地。为了这个目的，帝国主义采用多种压迫手段，客观上造成中国成为半殖民地半封建社会。题干只指出了“半封建”，所以应选择“半殖民地”。因此，选项D正确。","options":{"A":"与题干描述的是同一个方面，逻辑不符。","B":"说法错误，帝国主义的入侵虽然加剧了中国政治、经济和文化发展的不平衡，但帝国主义并没有完全控制中国。","C":"与题干描述的是同一个方面，逻辑不符。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-shigang-test2-4","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试二","chapterKey":"综合测试二","n":4,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试二 第 4 题"},"stem":"1895年，清政府被迫与日本签订丧权辱国的《马关条约》。该条约的签订极大地加深了中国社会的半殖民地化程度。条约明确规定，允许外国资本在中国通商口岸投资设厂，该条款所产生的最深远影响是","choices":[{"id":"A","text":"标志着帝国主义掀起了瓜分中国的狂潮"},{"id":"B","text":"使列强对华经济侵略由以商品倾销为主转变为以资本输出为主"},{"id":"C","text":"极大地破坏了中国的领土和主权完整"},{"id":"D","text":"刺激了中华民族意识的普遍觉醒和戊戌维新运动的兴起"}],"answer":["B"],"analysis":{"point":"本题考查资本-帝国主义列强对中国的经济掠夺。“允许日本臣民在中国通商口岸设厂”的条款，使外国资本的对华投资合法化，极大地刺激了外国资本涌向中国。此后，各帝国主义国家凭借“片面最惠国待遇”纷纷援引此条款，争相来华开矿、设厂、修路。这标志着列强对中国的经济侵略从以商品输出（倾销商品）为主要特征，进入以资本输出（直接投资，直接剥削中国廉价劳动力和掠夺资源）为主要特征的新阶段，极大地阻碍了中国民族资本主义的发展，加深了中国的经济殖民化。因此，选项B正确。","options":{"A":"属于《马关条约》的影响，但不是“投资设厂”条款的最深远影响。","B":"（正确选项，分析见“解题思路”）","C":"属于《马关条约》的影响，但不是“投资设厂”条款的最深远影响。","D":"属于《马关条约》的影响，但不是“投资设厂”条款的最深远影响。"}}},{"id":"advanced-shigang-test2-5","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试二","chapterKey":"综合测试二","n":5,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试二 第 5 题"},"stem":"1851年1月，洪秀全率拜上帝教教众在广西省桂平县金田村发动起义，建号太平天国。1864年7月，天京被湘军攻破，太平天国农民战争失败。孙中山认为，太平天国“不懂外交”“不北伐”“读书人不赞成”“大家想做皇帝”，是太平天国失败的重要原因。太平天国的这些失误，从根本上说是由于农民阶级","choices":[{"id":"A","text":"没有建立同工人阶级紧密结合的统一战线"},{"id":"B","text":"无法克服小生产者所固有的阶级局限性"},{"id":"C","text":"无法长期保持领导集团的团结"},{"id":"D","text":"无法从根本上提出完整的、正确的政治纲领和社会改革方案"}],"answer":["B"],"analysis":{"point":"本题考查太平天国农民战争失败的根本原因。太平天国农民战争失败的根本原因在于农民阶级不是先进的生产力和生产关系的代表，他们无法克服小生产者所固有的阶级局限性。因此，选项B正确。","options":{"A":"太平天国农民战争时期，工人阶级尚未登上历史舞台。中国共产党诞生后，工人阶级才逐步开始与农民阶级相结合，建立统一战线，并非根本原因。故不选。","B":"（正确选项，分析见“解题思路”）","C":"说法正确，但是这些都属于农民阶级局限性的具体表现，其要表达的意思都被概括在“阶级局限性”当中了，并非最佳答案，故不选。","D":"说法正确，但是这些都属于农民阶级局限性的具体表现，其要表达的意思都被概括在“阶级局限性”当中了，并非最佳答案，故不选。"}}},{"id":"advanced-shigang-test2-6","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试二","chapterKey":"综合测试二","n":6,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试二 第 6 题"},"stem":"为了挽救清政府的统治危机，封建统治阶级中的部分成员主张引进、仿造西方的武器装备和学习西方的科学技术，创设近代企业，兴办洋务，并强调“中学为体，西学为用”。但甲午战争一役，洋务派经营多年的北洋海军全军覆没，标志着以“自强”“求富”为目标的洋务运动的失败。洋务运动失败的根本原因在于","choices":[{"id":"A","text":"西方列强的打压和破坏"},{"id":"B","text":"洋务派力量太弱小"},{"id":"C","text":"洋务运动具有封建性"},{"id":"D","text":"洋务企业的管理具有腐朽性"}],"answer":["C"],"analysis":{"point":"本题考查洋务运动失败的根本原因，属于理解与识记相结合的试题。洋务运动具有封建性是导致其失败的根本原因。洋务运动的指导思想是“中学为体，西学为用”，企图以吸取西方近代生产技术为手段，来达到维护和巩固中国封建统治的目的，这就决定了它必然失败的命运。因为新的生产力是同封建主义的生产关系及上层建筑不相容的，是不可能在封建主义的桎梏下充分地发展起来的。他们既要发展近代企业，却又采取垄断经营、侵吞商股等手段压制民族资本；既想培养洋务人才，又不愿改变封建科举制度。因此，选项C正确。","options":{"A":"不符合题意，故不选。","B":"不符合题意，故不选。","C":"（正确选项，分析见“解题思路”）","D":"不符合题意，故不选。"}}},{"id":"advanced-shigang-test2-7","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试二","chapterKey":"综合测试二","n":7,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试二 第 7 题"},"stem":"维新派的变法维新活动引起封建守旧派和反对改变封建政治制度的洋务派的反对，他们利用自己的地位和权力，对维新思想发动攻击。于是维新派与守旧派之间展开了一场激烈论战。这场论战，实质上","choices":[{"id":"A","text":"开创了中国近代向西方学习的新风"},{"id":"B","text":"是一场前所未有的、空前深刻的思想解放运动"},{"id":"C","text":"是中国人民和中华民族自鸦片战争以来的第一次全面觉醒"},{"id":"D","text":"是资产阶级思想与封建主义思想在中国的第一次正面交锋"}],"answer":["D"],"analysis":{"point":"本题考查维新派与守旧派的论战。这场论战，实质上是资产阶级思想与封建主义思想在中国的第一次正面交锋。因此，选项D正确。","options":{"A":"在《海国图志》中，魏源提出了“师夷长技以制夷”的思想，主张学习外国先进的军事和科学技术，以期富国强兵，抵御外国侵略，开创了中国近代向西方学习的新风。故不选。","B":"新文化运动是一场前所未有的、空前深刻的思想解放运动。故不选。","C":"五四运动改变了以往只有觉悟的革命者而缺少觉醒的人民大众的斗争状况，实现了中国人民和中华民族自鸦片战争以来的第一次全面觉醒。故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-shigang-test2-8","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试二","chapterKey":"综合测试二","n":8,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试二 第 8 题"},"stem":"1904年，孙中山发表了《中国问题的真解决》一文，指出只有推翻清政府的统治，“以一个新的、开明的、进步的政府来代替旧政府”，把过时的封建君主专制政体改变为“中华民国”，才能真正解决中国问题。这表明革命派与改良派的根本不同之处是","choices":[{"id":"A","text":"兴民权，实行君主立宪"},{"id":"B","text":"平均地权，进行社会革命"},{"id":"C","text":"武装起义，推翻清王朝统治"},{"id":"D","text":"推翻帝制，实行共和"}],"answer":["C"],"analysis":{"point":"本题考查革命派与改良派的区别。以孙中山为代表的资产阶级革命派在踏上革命道路之时，就高举民主革命的旗帜，并选择了以武装起义推翻清王朝统治的斗争方式。这是中国资产阶级革命派与改良派的根本不同之处。题干中的“只有推翻清政府的统治”“才能真正解决中国问题”，也证明了这一点。因此，选项C正确。","options":{"A":"兴民权在维新变法时就已经提出了，不是二者的根本不同之处，故不选。","B":"都是革命派与改良派的不同之处，但不是根本不同之处，故不选。","C":"（正确选项，分析见“解题思路”）","D":"都是革命派与改良派的不同之处，但不是根本不同之处，故不选。"}}},{"id":"advanced-shigang-test2-9","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试二","chapterKey":"综合测试二","n":9,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试二 第 9 题"},"stem":"《辛丑条约》被认为是中国近代史上失权最严重的不平等条约，它的签订标志着中国完全沦为半殖民地半封建社会。下列关于《辛丑条约》的说法，正确的是","choices":[{"id":"A","text":"导致中国的海关管理权落入外国人手中"},{"id":"B","text":"引起了列强瓜分中国的狂潮"},{"id":"C","text":"使清政府变成“洋人的朝廷”"},{"id":"D","text":"设置总理衙门专办外交事务"}],"answer":["C"],"analysis":{"point":"本题考查《辛丑条约》的相关内容。《辛丑条约》的签订进一步加强了帝国主义对中国的全面控制和掠夺，表明清政府已经完全成为帝国主义统治中国的工具，是名副其实的“洋人的朝廷”。因此，选项C正确。","options":{"A":"与《辛丑条约》无关。1859年，南洋通商大臣任命英人李泰国为总税务司；1861年，总理衙门成立，统辖总税务司；1865年，李泰国离职回国，总理衙门任命英人赫德为海关总税务司，这是中国的海关管理权落入外国人手中的开端。故不选。","B":"与《辛丑条约》无关，列强瓜分中国的狂潮发生在中日甲午战争之后，故不选。","C":"（正确选项，分析见“解题思路”）","D":"与《辛丑条约》无关，总理衙门成立于1861年，是在《北京条约》签订之后为解决增多的涉外事务而成立的，故不选。"}}},{"id":"advanced-shigang-test2-10","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试二","chapterKey":"综合测试二","n":10,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试二 第 10 题"},"stem":"1894年，孙中山北上京津向李鸿章上书，提出“人能尽其才，地能尽其利，物能尽其用，货能畅其流”的主张，但是李鸿章并没有重视他的意见。孙中山在北上京津的过程中，发现清政府的腐败比他原先了解的要严重得多。这时，他“积渐而知和平之手段不得不稍易以强迫”，决心以革命的方式推翻清朝的统治。1904年，孙中山发表《中国问题的真解决》一文，指出只有推翻清政府的统治，“以一个新的、开明的、进步的政府来代替旧政府”，把过时的封建君主专制政体改变为“中华民国”，才能真正解决中国问题。这表明","choices":[{"id":"A","text":"孙中山倡导的民主革命已经成为中国资产阶级的共识"},{"id":"B","text":"孙中山已经由改良主义者转变为资产阶级革命派"},{"id":"C","text":"孙中山开始意识到成立革命团体的必要性"},{"id":"D","text":"孙中山一直主张武装推翻清王朝的统治"}],"answer":["B"],"analysis":{"point":"本题考查孙中山先生思想的转变，属于理解与识记相结合的试题。从1894年向李鸿章上书，到1904年发表《中国问题的真解决》，表明以孙中山为首的资产阶级革命派逐步转变观念，踏上革命道路，高举起民主革命的旗帜，最终选择了以武装起义推翻清王朝统治的斗争方式。因此，选项B正确。","options":{"A":"民主革命仅仅是民族资产阶级的主张，并不是官僚资产阶级的政治主张，故不选。","B":"（正确选项，分析见“解题思路”）","C":"孙中山意识到成立革命团体的必要性是在19世纪末期，而不是1904年。","D":"从题干可知，孙中山在早期是不主张进行武装革命的。"}}},{"id":"advanced-shigang-test2-11","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试二","chapterKey":"综合测试二","n":11,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试二 第 11 题"},"stem":"毛泽东在谈到辛亥革命时指出，辛亥革命有它胜利的地方，也有它失败的地方。“辛亥革命把皇帝赶跑，这不是胜利了吗？说它失败，是说辛亥革命只把一个皇帝赶跑。”毛泽东这里所说的“只把一个皇帝赶跑”是指","choices":[{"id":"A","text":"没有推翻帝制"},{"id":"B","text":"反帝反封建的革命任务没有完成"},{"id":"C","text":"孙中山没有继续革命"},{"id":"D","text":"袁世凯窃取了胜利果实"}],"answer":["B"],"analysis":{"point":"本题考查辛亥革命的失败。“辛亥革命只把一个皇帝赶跑”具体是指中国虽然结束了封建帝制，但仍旧在帝国主义和封建主义的压迫之下，反帝反封建的革命任务并没有完成。因此，选项B正确。","options":{"A":"辛亥革命结束了统治中国两千多年的封建君主专制制度，建立了中国历史上第一个资产阶级共和政府。","B":"（正确选项，分析见“解题思路”）","C":"辛亥革命失败后，中国资产阶级革命派内部也发生了分化，但以孙中山为代表的革命派仍继续反对封建军阀专制统治，努力挽救共和制度。","D":"袁世凯窃夺辛亥革命胜利的果实，仅仅是反帝反封建任务没有完成的表现之一。"}}},{"id":"advanced-shigang-test2-12","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试二","chapterKey":"综合测试二","n":12,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试二 第 12 题"},"stem":"1919年9月、11月，李大钊发表了《我的马克思主义观》一文，明确地把马克思主义称为“世界改造原动的学说”，并且","choices":[{"id":"A","text":"对马克思的唯物史观、剩余价值学说和阶级斗争理论作了比较系统的介绍"},{"id":"B","text":"深刻揭露了第一次世界大战的本质"},{"id":"C","text":"向中国人民第一次正确地阐述了十月革命的性质"},{"id":"D","text":"喊出了“振兴中华”这个时代的最强音"}],"answer":["A"],"analysis":{"point":"本题考查李大钊的《我的马克思主义观》的内容。1919年9月、11月，李大钊发表了《我的马克思主义观》一文，明确地把马克思主义称为“世界改造原动的学说”，并且对马克思的唯物史观、剩余价值学说和阶级斗争理论作了比较系统的介绍。因此，选项A正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"1918年11月，李大钊相继发表了《庶民的胜利》《Bolshevism的胜利》两篇文章，深刻揭露了第一次世界大战的本质，热情歌颂了十月革命和布尔什维主义的胜利，欢呼“将来的环球，必是赤旗的世界”，故不选。","C":"1918年7月，李大钊发表了《法俄革命之比较观》，该文指出“俄罗斯之革命是二十世纪初期之革命，是立于社会主义上之革命”，向中国人民第一次正确地阐述了十月革命的性质，故不选。","D":"1894年11月，孙中山在创立革命团体兴中会时喊出了“振兴中华”这个时代的最强音，故不选。"}}},{"id":"advanced-shigang-test2-13","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试二","chapterKey":"综合测试二","n":13,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试二 第 13 题"},"stem":"陈独秀认为，中共一大对“党的要求——无产阶级专政——悬在半空”，到中共二大时“就脚踏实地了”。这是指中共二大","choices":[{"id":"A","text":"制定了党的最高纲领"},{"id":"B","text":"决定与国民党合作"},{"id":"C","text":"制定了党的民主革命纲领"},{"id":"D","text":"提出了中国革命的新道路"}],"answer":["C"],"analysis":{"point":"本题考查中共二大。中共二大从中国半殖民地半封建社会的国情出发，制定了反帝反封建的民主革命纲领。因此，选项C正确。","options":{"A":"党的最高纲领是实现共产主义，与题干中的“脚踏实地”不符，故不选。","B":"中共三大决定与国民党合作，共产党员以个人身份加入国民党，故不选。","C":"（正确选项，分析见“解题思路”）","D":"土地革命前期，在发展南方根据地的过程中，中国革命的新道路（即农村包围城市、武装夺取政权）逐渐开始形成，故不选。"}}},{"id":"advanced-shigang-test2-14","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试二","chapterKey":"综合测试二","n":14,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试二 第 14 题"},"stem":"1927年8月7日，中共中央在汉口召开会议，批判并纠正了右倾机会主义错误，确定了土地革命和武装反抗国民党反动派的总方针。这一决策旨在","choices":[{"id":"A","text":"顺应国际共产主义运动最新潮流"},{"id":"B","text":"联合各阶层共同对抗国民党统治"},{"id":"C","text":"实现党的重心由城市转移到农村"},{"id":"D","text":"探寻新的革命策略挽救党和革命"}],"answer":["D"],"analysis":{"point":"本题考查八七会议的内容。1927年大革命失败，中国共产党面临生死存亡危机，八七会议批判错误路线、确定新方针，目的就是探寻新的革命策略挽救党和革命。因此，选项D正确。","options":{"A":"八七会议主要是基于中国国内革命形势的严峻性，如大革命失败、国民党反动派对共产党人的残酷屠杀等现实情况作出决策，并非为了顺应国际共产主义运动最新潮流。","B":"八七会议确定了武装反抗国民党反动派的总方针，表明与国民党反动派彻底决裂，并非联合各阶层力量共同对抗国民党统治。","C":"八七会议并没有明确提出将党的工作重心由城市转向农村，工作重心向农村转移是在秋收起义等一系列武装斗争实践受挫后，逐步认识和实现的。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-shigang-test2-15","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试二","chapterKey":"综合测试二","n":15,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试二 第 15 题"},"stem":"1940年，毛泽东曾指出：“我们所建立的政权……是几个革命阶级联合起来对于汉奸和反动派的民主专政……对于这种政权性质的明确了解和认真执行，将大有助于全国民主化的推动。”毛泽东所说的“政权”","choices":[{"id":"A","text":"促成了国共合作抗日局面的形成"},{"id":"B","text":"成为陕甘宁边区苏维埃革命政府的中枢"},{"id":"C","text":"扩大了全民族抗战的群众基础"},{"id":"D","text":"开创了中国共产党民主建设的先河"}],"answer":["C"],"analysis":{"point":"本题考查全民族抗战。1940年的政权是“几个革命阶级联合”，“将大有助于全国民主化的推动”，从而有利于团结抗日。因此，选项C正确。","options":{"A":"1937年9月22日，国民党中央通讯社发表《中共中央为公布国共合作宣言》；23日，蒋介石发表实际承认共产党合法地位的谈话。以国共两党第二次合作为基础的抗日民族统一战线正式形成。故不选。","B":"抗日战争时期，中国共产党领导下的政权名称为“中华民国陕甘宁边区政府”，不是“苏维埃革命政府”，故不选。","C":"（正确选项，分析见“解题思路”）","D":"开创中国共产党民主建设先河的是井冈山时期的苏维埃政权，故不选。"}}},{"id":"advanced-shigang-test2-16","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试二","chapterKey":"综合测试二","n":16,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试二 第 16 题"},"stem":"在抗日战争战略防御阶段，国民党军队组织了淞沪、忻口、徐州、武汉会战等一系列大战役。尽管国民党政府在抗战初期对日作战比较积极，但是国民党正面战场除台儿庄战役取得大捷外，其他战役几乎都以退却、失败而结束。造成这种状况的主观原因是","choices":[{"id":"A","text":"日本对国民党进行政治诱降"},{"id":"B","text":"蒋介石集团实行的是片面抗战路线"},{"id":"C","text":"在敌我力量对比上，日军占很大的优势"},{"id":"D","text":"蒋介石集团推行消极抗日、积极反共的政策"}],"answer":["B"],"analysis":{"point":"本题考查抗日战争的正面战场。国民党正面战场失利的主观原因是国民党战略指导方针的失误。蒋介石集团实行的是片面抗战路线，即不敢放手发动和武装民众，将希望单纯寄托在政府和正规军的抵抗上。因此，选项B正确。","options":{"A":"在抗日战争战略相持阶段，日本对国民党政府采取以政治诱降为主、军事打击为辅的方针。","B":"（正确选项，分析见“解题思路”）","C":"属于国民党正面战场失利的客观原因。","D":"抗日战争相持阶段到来后，以蒋介石为代表的国民党亲英美派开始推行消极抗日、积极反共的政策。"}}},{"id":"advanced-shigang-test2-17","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试二","chapterKey":"综合测试二","n":17,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试二 第 17 题"},"stem":"解放战争时期，在国民党统治地区，以学生运动为先导的人民民主运动迅速地发展起来，成为配合人民解放战争的第二条战线。第二条战线形成的最主要原因是","choices":[{"id":"A","text":"土地改革与农民的广泛发动"},{"id":"B","text":"国民党的统治不得人心"},{"id":"C","text":"学生运动的高涨"},{"id":"D","text":"第三条道路的幻灭"}],"answer":["B"],"analysis":{"point":"本题考查第二条战线的开辟。国民党政府由于其专制独裁统治和官员们的贪污腐败、大发国难财，抗战后期在大后方便已严重丧失人心。国民党之所以迅速失去民心，主要是由于它违背全国人民迫切要求休养生息、和平建国的意愿，执行反人民的内战政策。因此，选项B正确。","options":{"A":"属于解放区的运动，而第二条战线是在国民党统治区的运动，范围不一样，故不选。","B":"（正确选项，分析见“解题思路”）","C":"属于第二条战线开辟的表现形式，并非原因，故不选。","D":"第三条道路的幻灭是指资产阶级共和国的方案在中国行不通，并非第二条战线的问题，故不选。"}}},{"id":"advanced-shigang-test2-18","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试二","chapterKey":"综合测试二","n":18,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试二 第 18 题"},"stem":"中国的民主党派从成立的时候起，大多同中国共产党建立了不同程度的合作关系，并在斗争实践中逐步地发展了这种合作关系。中国共产党与民主党派的合作之所以能够走到一起，是因为","choices":[{"id":"A","text":"民族资本主义经济的特点决定了民族资产阶级是一个带有两面性的阶级"},{"id":"B","text":"民主党派的领导人始终坚持“中间路线”"},{"id":"C","text":"民主党派的政治纲领同中国共产党的民主革命纲领基本上是一致的"},{"id":"D","text":"民主党派从一开始就毫不犹豫地参加新政协并准备在新中国参政"}],"answer":["C"],"analysis":{"point":"本题考查中国共产党与民主党派的合作。中国各民主党派的政治纲领不尽相同，但都主张爱国、反对卖国，主张民主、反对独裁。在这些方面，各民主党派同中国共产党的新民主主义革命政治纲领基本上是一致的。因此，它们从成立的时候起，大多同中国共产党建立了不同程度的合作关系，并在斗争实践中逐步地发展了这种合作关系。因此，选项C正确。","options":{"A":"说的是民族资产阶级，而题干考查民主党派，二者并不完全等同，故不选。","B":"抗日战争胜利后，某些民主党派的领导人曾经鼓吹“中间路线”，但这并不是他们能与中国共产党走到一起的原因，因为中国共产党并不赞成“中间路线”，故不选。","C":"（正确选项，分析见“解题思路”）","D":"民主党派参加新政协并准备在新中国参政是在1949年才实现的，并非一开始就有此觉悟，故不选。"}}},{"id":"advanced-shigang-test2-19","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试二","chapterKey":"综合测试二","n":19,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试二 第 19 题"},"stem":"1950年6月召开的中共七届三中全会，确定了当时全党和全国人民的中心任务是要在三年左右的时间内，争取国家财政经济状况的基本好转。为此，会议制定了党在新中国成立初期的战略策略方针，即","choices":[{"id":"A","text":"统筹兼顾、适当安排"},{"id":"B","text":"不要四面出击"},{"id":"C","text":"调动一切积极因素为社会主义事业服务"},{"id":"D","text":"既反保守又反冒进、在综合平衡中稳步前进"}],"answer":["B"],"analysis":{"point":"本题考查中共七届三中全会。为了恢复国民经济，为社会主义改造创造条件，中共七届三中全会制定了“不要四面出击”的方针。四面出击，树敌太多，造成全国紧张，而应该集中力量向国民党残余势力、封建地主阶级和帝国主义进攻。因此，选项B正确。","options":{"A":"“统筹兼顾、适当安排”，是1957年毛泽东在《关于正确处理人民内部矛盾的问题》中提出的处理物质利益、分配方面的人民内部矛盾的方针。故不选。","B":"（正确选项，分析见“解题思路”）","C":"“调动一切积极因素为社会主义事业服务”，是1956年毛泽东在《论十大关系》中提出的基本方针。故不选。","D":"“既反保守又反冒进、在综合平衡中稳步前进”，是1956年中共八大提出的经济建设方针。故不选。"}}},{"id":"advanced-shigang-test2-20","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试二","chapterKey":"综合测试二","n":20,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试二 第 20 题"},"stem":"在“中学为体，西学为用”思想的指导下，洋务运动历时30多年，企图以吸取西方近代生产技术为手段，来达到维护和巩固中国封建统治的目的。洋务运动虽然兴办了一批近代企业，建立了海军，但最终没有使中国富强起来。洋务运动的失败表明","choices":[{"id":"A","text":"不改变落后的封建生产关系，就无法真正发展先进的近代生产力"},{"id":"B","text":"要实现国家富强，必须首先完成民族独立和人民解放的历史任务"},{"id":"C","text":"企图通过统治者走自上而下的改良道路来发展资本主义，在旧中国是根本行不通的"},{"id":"D","text":"近代中国贫困落后的根本原因，并不是经济技术的落后，而在于社会制度的腐败"}],"answer":["A","B","D"],"analysis":{"point":"本题考查洋务运动失败的原因。洋务运动的指导思想是“中体西用”，这就决定了它必然失败的命运。因为新的生产力是同封建主义的生产关系及上层建筑不相容的，是不可能在封建主义的桎梏下充分地发展起来的。这就表明不改变落后的封建生产关系，就无法真正发展先进的近代生产力。近代中国贫困落后的根本原因，并不是经济技术的落后，而在于社会制度的腐败。要实现国家富强，必须首先完成民族独立和人民解放的历史任务。因此，选项A、B、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"企图通过统治者走自上而下的改良道路来发展资本主义，在旧中国是根本行不通的，是戊戌维新运动失败的教训。洋务派兴办洋务新政，主要是为了维护封建统治，并不是要使中国朝着独立的资本主义方向发展。故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-shigang-test2-21","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试二","chapterKey":"综合测试二","n":21,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试二 第 21 题"},"stem":"辛亥革命为中国的进步打开了闸门，为中国共产党的诞生准备了客观社会条件。辛亥革命给中国共产党的成立准备了","choices":[{"id":"A","text":"干部条件"},{"id":"B","text":"理论基础"},{"id":"C","text":"阶级基础"},{"id":"D","text":"革命方法"}],"answer":["A","B","C"],"analysis":{"point":"本题考查辛亥革命对中国共产党的影响。辛亥革命促进了民族资本主义的发展，为中国共产党的成立提供了阶级基础；促进了新思想的传播，为中国共产党的成立准备了理论基础；也为中国共产党的成立准备了干部条件。因此，选项A、B、C正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"十月革命一声炮响，为中国送来了马克思主义，也给中国先进知识分子带来了新的革命方法，故不选。"}}},{"id":"advanced-shigang-test2-22","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试二","chapterKey":"综合测试二","n":22,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试二 第 22 题"},"stem":"新文化运动是从1915年9月陈独秀在上海创办《青年杂志》（后改名《新青年》）开始的。以五四运动为界，新文化运动分为五四前后两个时期。五四运动以前的新文化运动在社会上掀起的思想解放潮流，冲决了禁锢人们思想的闸门，但也存在一些局限，其局限性主要表现在","choices":[{"id":"A","text":"完全否定了西方资产阶级民主主义"},{"id":"B","text":"提倡资产阶级民主主义，并不能为人们提供一种有效的思想武器"},{"id":"C","text":"脱离产生封建思想的社会环境来强调改造国民性"},{"id":"D","text":"看待问题的方法过于形式主义"}],"answer":["B","C","D"],"analysis":{"point":"本题考查五四运动以前的新文化运动的局限，属于理解与识记相结合的试题。五四运动以前的新文化运动存在一些局限，主要表现在：第一，新文化运动的倡导者批判孔学，是为了给中国发展资本主义扫清障碍。但是，由于资产阶级共和国的方案在中国行不通，所以从根本上说，提倡资产阶级民主主义，并不能为人们提供一种有效的思想武器去认识中国，去对中国社会进行改造。第二，新文化运动的倡导者把改造国民性置于优先地位。但是，离开改造产生封建思想的社会环境的革命实践，仅仅依靠少数人的呐喊，依靠有限的宣传手段，要根本改造由这种社会环境所产生的思想、所造成的国民性，是不可能的。第三，那时的许多领导人物，还没有马克思主义的批判精神，他们使用的方法，一般还是资产阶级的方法。他们中有的人看问题很片面，坏就是绝对的坏，好就是绝对的好。这种形式主义看问题的方法，影响了运动后来的发展。事实上，在当时的先进分子中，有的人在宣传西方资产阶级民主主义时，就已开始对它有所怀疑和保留了。李大钊在1916年即指出：“代议政治虽今犹在试验之中，其良其否，难以确知，其存其易，亦未可测。”五四运动以后的新文化运动则发展到了一个新阶段，马克思主义开始逐步在思想文化领域中发挥指导作用。因此，选项B、C、D正确。","options":{"A":"表述错误，五四运动以前的新文化运动是提倡资产阶级民主主义的，故不选。","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-shigang-test2-23","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试二","chapterKey":"综合测试二","n":23,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试二 第 23 题"},"stem":"当十月革命给中国送来马克思列宁主义的时候，新文化运动发生了根本的变化，由一个资产阶级文化革命运动转变为一个广泛宣传马克思列宁主义的运动，《新青年》也逐渐变成宣传马克思列宁主义的刊物。五四运动以后的新文化运动的变化包括","choices":[{"id":"A","text":"民主是以劳动群众为主体的民主"},{"id":"B","text":"对于社会的研究来说，科学主要是指马克思主义的科学世界观和社会革命论"},{"id":"C","text":"向封建主义思想文化发起前所未有的猛烈攻击"},{"id":"D","text":"马克思主义开始逐步在思想文化领域发挥指导作用"}],"answer":["A","B","D"],"analysis":{"point":"本题考查五四运动以后的新文化运动的变化。五四运动以后的新文化运动的变化主要表现在：民主，不再是指狭隘的资产阶级民主，而是指多数人的民主、以劳动群众为主体的民主。科学，除自然科学外，就对社会的研究来说，主要是指马克思主义的科学世界观和社会革命论。选项A、B正确。五四运动以前的新文化运动主要是资产阶级民主主义的新文化反对封建主义的旧文化的斗争；五四运动以后的新文化运动，马克思主义开始逐步在思想文化领域中发挥指导作用。选项D正确。因此，选项A、B、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"是五四运动以前的新文化运动的表现，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-shigang-test2-24","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试二","chapterKey":"综合测试二","n":24,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试二 第 24 题"},"stem":"1927年10月，毛泽东率领经“三湾改编”后的秋收起义部队到达井冈山，先后在宁冈、永新、茶陵、遂川等县恢复和建立了党组织，发展武装力量，开展游击战争，领导农民打土豪、分田地，建立红色政权，实行工农武装割据，创立了党领导下的第一个农村革命根据地。井冈山革命根据地创建的意义有","choices":[{"id":"A","text":"点燃了“工农武装割据”的星星之火"},{"id":"B","text":"使中国革命的重心从乡村转移到城市"},{"id":"C","text":"开辟了一条在敌我力量悬殊情况下，保存和发展革命力量的新道路"},{"id":"D","text":"代表了大革命失败后中国革命发展的方向"}],"answer":["A","C","D"],"analysis":{"point":"本题考查井冈山革命根据地创建的意义。毛泽东提出了工农武装割据的革命理论，从理论上处理好了武装斗争、土地革命以及根据地建设三者之间的关系，为中国共产党的发展指明了革命道路和方向，从而摆脱了长期以来对苏联革命道路的依赖，开始走出了一条具有中国特色的革命道路，即农村包围城市、武装夺取政权的革命道路。因此，选项A、C、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"表述错误，当时中国革命的重心是从城市转移到农村，故不选。","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-shigang-test2-25","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试二","chapterKey":"综合测试二","n":25,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试二 第 25 题"},"stem":"忠诚于党、听党指挥是我军的光荣传统。1929年12月下旬，红四军党的第九次代表大会在福建省上杭县古田村召开。这次会议史称古田会议。会议通过的毛泽东起草的决议案，确立了思想建党、政治建军原则，规定红军是一个执行革命的政治任务的武装集团，必须","choices":[{"id":"A","text":"绝对服从共产党的领导"},{"id":"B","text":"担负打仗、筹款和做群众工作的任务"},{"id":"C","text":"加强政治工作"},{"id":"D","text":"实行全国军事的总动员"}],"answer":["A","B","C"],"analysis":{"point":"本题考查古田会议。1929年12月下旬，红四军党的第九次代表大会在福建省上杭县古田村召开，会议通过的《中国共产党红军第四军第九次代表大会决议案》指出，红军是一个执行革命的政治任务的武装集团，除打仗消灭敌人的军事力量之外，还要担负宣传群众、组织群众、武装群众、帮助群众建立革命政权以至于建立共产党的组织等重大任务。决议案要求在部队中进行建军宗旨教育，划清红军和旧军队的界限，肃清一切旧式军队的影响。它批判了不重视根据地建设的流寇思想和不愿做群众工作的错误倾向，指明了红军建设的方向，使红军建设的理论完全建立在马克思列宁主义的基础之上，肯定了党对红军的领导原则。决议案指出，在红军中健全党的各级组织，建立党的领导中枢；厉行集中指导下的民主生活，少数服从多数，一切重大工作，在党内讨论作出决议后，再引导群众去执行。因此，选项A、B、C正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"“实行全国军事的总动员”是抗日战争时期提出的战略，与本题的时间点“1929年”不符，故排除。"}}},{"id":"advanced-shigang-test2-26","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试二","chapterKey":"综合测试二","n":26,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试二 第 26 题"},"stem":"1935年，中国整个时局发生了巨大的变动。日本帝国主义加快了企图独占中国、不断扩大对中国侵略的步伐，使中华民族同日本侵略者之间的民族矛盾急剧上升，全国各地开始掀起抗日救亡运动的新高潮。面对这一严峻局势，1935年12月17日至25日，中共中央在瓦窑堡召开政治局扩大会议。这次会议","choices":[{"id":"A","text":"提出党的基本策略任务是建立广泛的抗日民族统一战线"},{"id":"B","text":"批评了党内长期存在的“左”倾冒险主义、关门主义错误倾向"},{"id":"C","text":"决定用“人民共和国”称号代替“工农共和国”"},{"id":"D","text":"制定了抗日救国十大纲领"}],"answer":["A","B","C"],"analysis":{"point":"本题考查瓦窑堡会议。1935年12月17日至25日，中共中央在瓦窑堡召开政治局扩大会议，提出党的基本策略任务是建立广泛的抗日民族统一战线，批评了党内长期存在的“左”倾冒险主义、关门主义错误倾向，决定用“人民共和国”称号代替“工农共和国”。因此，选项A、B、C正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"1937年8月，中国共产党在陕北洛川召开政治局扩大会议，制定了抗日救国十大纲领。故不选。"}}},{"id":"advanced-shigang-test2-27","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试二","chapterKey":"综合测试二","n":27,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试二 第 27 题"},"stem":"1937年9月22日，国民党中央通讯社发表《中共中央为公布国共合作宣言》；23日，蒋介石发表实际承认共产党合法地位的谈话。至此，以国共两党第二次合作为基础的抗日民族统一战线正式形成。下列关于抗日民族统一战线与国民革命统一战线的说法，正确的有","choices":[{"id":"A","text":"都有固定的组织形式和协商一致的共同纲领"},{"id":"B","text":"并不都是由共产党领导"},{"id":"C","text":"阶级成分不完全一致"},{"id":"D","text":"国共双方都有政权和军队的合作"}],"answer":["B","C"],"analysis":{"point":"本题考查抗日民族统一战线与国民革命统一战线的比较。抗日民族统一战线与国民革命统一战线的区别：第一，领导力量不同。国民革命统一战线时期是共产党员以个人身份加入国民党，属于党内合作，领导权在国民党；抗日民族统一战线时期国共两党各自坚持自己的抗战路线，分别领导两个战场。第二，阶级成分不完全一致。国民革命统一战线时期，国民党为工人、农民、城市小资产阶级以及民族资产阶级的民主革命联盟；抗日民族统一战线是在民族危机空前严重的情况下形成的，不仅工人、农民、小资产阶级以及民族资产阶级要求抗日，而且中小地主、亲英美派大地主大资产阶级以及地方实力派从自身利益出发，也参加了抗日民族统一战线。因此，选项B、C正确。","options":{"A":"表述错误，抗日民族统一战线没有固定的组织形式和协商一致的共同纲领，国共两党各自坚持自己的抗战路线，分别领导两个战场，形成一种不完善的合作局面，故不选。","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"表述错误，国民革命统一战线时期，共产党员以个人身份加入国民党，属于党内合作，不存在国共双方有政权和军队的合作，故不选。"}}},{"id":"advanced-shigang-test2-28","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试二","chapterKey":"综合测试二","n":28,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试二 第 28 题"},"stem":"解放战争时期，为了调动广大农民参与人民解放战争的积极性，解放区开展了轰轰烈烈的土地改革运动。在这场运动中，中国共产党制定了正确的土地和阶级政策，包括","choices":[{"id":"A","text":"“耕者有其田”"},{"id":"B","text":"不侵犯中农土地"},{"id":"C","text":"一般不变动富农土地"},{"id":"D","text":"采用农村中的斗争方法对待城市工商业资本家"}],"answer":["A","B","C"],"analysis":{"point":"本题考查解放战争时期的土地政策。在解放战争胜利发展的同时，解放区开展了轰轰烈烈的土地改革运动。1946年5月4日，中共中央发出《关于土地问题的指示》（史称“五四指示”），其基本内容是要坚决地支持和引导广大农民群众，采取各种适当方法，使地主阶级剥削农民而占有的土地转移到农民手中；用一切方法吸收中农参加运动，绝不可侵犯中农土地；一般不变动富农土地，对富农和地主有所区别；不可将农村中反对封建地主阶级的方法，运用于城市中反对工商业资产阶级的斗争。这就将党在抗日战争时期实行的减租减息政策改变为实行“耕者有其田”的政策。因此，选项A、B、C正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"《关于土地问题的指示》强调，不可将农村中反对封建地主阶级的方法，运用于城市中反对工商业资产阶级的斗争，故不选。"}}},{"id":"advanced-shigang-test2-29","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试二","chapterKey":"综合测试二","n":29,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试二 第 29 题"},"stem":"在国民党统治区，以学生运动为先导的人民民主运动也迅速地发展起来，成为配合人民解放战争的第二条战线。国民党陷入第二条战线的包围的原因包括","choices":[{"id":"A","text":"专制独裁、贪污腐败"},{"id":"B","text":"执行反人民的内战政策"},{"id":"C","text":"物价飞涨、经济濒临崩溃"},{"id":"D","text":"工农业生产严重萎缩"}],"answer":["A","B","C","D"],"analysis":{"point":"本题考查第二条战线的开辟。国民党迅速失去民心，主要是由于它的专制独裁统治和官员们的贪污腐败、大发国难财，执行反人民的内战政策。为了筹措内战经费，国民党政府除对人民征收苛重的捐税外，更无限制地发行纸币。恶性通货膨胀引起的物价飞涨，使人民一次又一次地遭到洗劫，使民族工商业走向破产。国民党统治区的工农业生产严重萎缩，国民经济遭遇深刻的危机。1947年，各地饥民达一亿人以上。公教人员和学生群众的生活也陷入极度的困境。因此，选项A、B、C、D正确。\\n无干扰选项。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-shigang-test2-30","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试二","chapterKey":"综合测试二","n":30,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试二 第 30 题"},"stem":"1981年6月，党的十一届六中全会通过的《关于建国以来党的若干历史问题的决议》，回顾了新中国成立以来党的历史，总结了社会主义革命和建设的历史经验，为开辟中国特色社会主义道路奠定了重要的思想基础。下列关于党的十一届六中全会的表述正确的有","choices":[{"id":"A","text":"提出了毛泽东思想的活的灵魂"},{"id":"B","text":"科学评价了毛泽东和毛泽东思想"},{"id":"C","text":"对我国社会的主要矛盾作出了新的科学表述"},{"id":"D","text":"标志着党在指导思想上的拨乱反正胜利完成"}],"answer":["A","B","C","D"],"analysis":{"point":"本题考查党的十一届六中全会。党的十一届六中全会通过的《关于建国以来党的若干历史问题的决议》，科学评价了毛泽东和毛泽东思想，提出了毛泽东思想的活的灵魂是“实事求是、群众路线、独立自主”，为我们完整准确地理解、坚持和发展毛泽东思想指明了方向，标志着党在指导思想上的拨乱反正胜利完成。会议还指出，在社会主义改造基本完成以后，我国所要解决的主要矛盾是人民日益增长的物质文化需要同落后的社会生产之间的矛盾。因此，选项A、B、C、D正确。\\n无干扰选项。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-shigang-test3-1","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试三","chapterKey":"综合测试三","n":1,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试三 第 1 题"},"stem":"1840年鸦片战争以后，由于资本-帝国主义列强的入侵和清朝封建统治的腐朽，有着5000多年历史的文明古国逐步沦为半殖民地半封建社会，山河破碎，民族危亡。之所以被称为半封建社会，是因为当时的中国","choices":[{"id":"A","text":"已经丧失了完全独立的地位，在相当程度上被殖民地化了"},{"id":"B","text":"成了由殖民主义宗主国直接统治的殖民地"},{"id":"C","text":"出现了资本主义生产关系，但列强不容许中国成为独立的资本主义国家"},{"id":"D","text":"与新兴的西方资本主义国家拉开了很大的差距"}],"answer":["C"],"analysis":{"point":"本题考查近代中国逐步变成半封建社会的原因。一方面，资本-帝国主义列强用武力打开中国的门户，把中国卷入世界资本主义经济体系和世界市场之中。中国出现了资本主义生产关系，已经不是完全的封建社会了。另一方面，资本-帝国主义列强并不容许中国成为独立的资本主义国家。因此，选项C正确。","options":{"A":"属于近代中国被称为半殖民地的原因，不符合题意。","B":"说法错误，近代中国是半殖民地，并未丧失全部主权，这与由殖民主义宗主国直接统治的殖民地有所区别。","C":"（正确选项，分析见“解题思路”）","D":"早在鸦片战争之前，封建社会的中国已经与新兴的西方资本主义国家拉开了很大的差距，这并不是近代中国被称为半封建社会的原因。"}}},{"id":"advanced-shigang-test3-2","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试三","chapterKey":"综合测试三","n":2,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试三 第 2 题"},"stem":"近代以来，世界上的主要资本-帝国主义国家，几乎都曾欺凌过中国。而近代中国的反侵略战争，从1840年反对英国侵略的战争直到抗日战争以前，无不以中国失败、中国政府被迫接受丧权辱国的条约而宣告结束。帝国主义侵略中国的最终目的是","choices":[{"id":"A","text":"改造中国成为民主国家"},{"id":"B","text":"占领中国市场"},{"id":"C","text":"瓜分中国、灭亡中国"},{"id":"D","text":"帮助中国发展资本主义"}],"answer":["C"],"analysis":{"point":"本题考查帝国主义侵略中国的最终目的。帝国主义侵略中国的最终目的，是瓜分中国、灭亡中国。19世纪70至90年代是“世界上最大规模的掠夺领土的时代”。欧洲列强在把非洲瓜分完毕后，也瓜分了亚洲大部分地区。中国这个还保存着名义上独立的半殖民地国家，成了尚未被瓜分的“仅有的富源”中的最重要的部分，于是列强展开了对中国的激烈争夺，致使中国出现了边疆危机与瓜分危机。因此，选项C正确。","options":{"A":"帝国主义常常打着“民主”的幌子侵略他国，故不选。","B":"占领中国市场虽然也是帝国主义侵略中国的目的，但不是最终目的，故不选。","C":"（正确选项，分析见“解题思路”）","D":"帝国主义侵略中国的目的并不是“帮助中国”，故不选。"}}},{"id":"advanced-shigang-test3-3","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试三","chapterKey":"综合测试三","n":3,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试三 第 3 题"},"stem":"1854年，英国外交大臣致函英国驻华公使说：“为了适应外商对农业产品业已增加了的需要……新贸易市场尚待进行。”1856年，法国外长又指令法国驻华代办，强调“商业关系的推广”，并说“这是一个关系至高无上利益的问题”。这段话表明","choices":[{"id":"A","text":"英法企图进一步打开中国市场"},{"id":"B","text":"英法希望加强与中国的贸易往来"},{"id":"C","text":"英法策划提出“修改条约”要求"},{"id":"D","text":"英法决定用战争来扩大在华权益"}],"answer":["A"],"analysis":{"point":"本题考查资本 - 帝国主义列强对中国的侵略。鸦片战争前，清政府实行闭关锁国政策，只允许外国人在广州一地进行贸易活动，但列强并不满足于此。鸦片战争后，帝国主义列强强迫清政府签订条约，开放多处通商口岸，借此来进一步打开中国市场。因此，选项 A 正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"非英法方面的主旨思想，其目的是侵略，故不选。","C":"表述正确，但与题意不符，故不选。","D":"表述正确，但与题意不符，故不选。"}}},{"id":"advanced-shigang-test3-4","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试三","chapterKey":"综合测试三","n":4,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试三 第 4 题"},"stem":"甲午战败后，李鸿章伤感地说：“我办了一辈子事，练兵也，海军也，都是纸糊的老虎……不过勉强涂饰，虚有其表。”从他的话中，我们能看出洋务运动是一次","choices":[{"id":"A","text":"使中国走上了富强道路的运动"},{"id":"B","text":"失败的封建统治者的自救运动"},{"id":"C","text":"失败的资产阶级性质的政治改良运动"},{"id":"D","text":"资产阶级民主革命运动"}],"answer":["B"],"analysis":{"point":"本题考查洋务运动的性质。19 世纪 60 年代初，为了挽救清政府的统治危机，封建统治阶级中的部分成员如奕䜣、曾国藩、李鸿章、左宗棠、张之洞等，主张引进、仿造西方的武器装备并学习西方的科学技术，创设近代企业，兴办洋务。而中日甲午战争一役，洋务派经营多年的北洋海军全军覆没，标志着以“自强”“求富”为目标的洋务运动的失败。因此，洋务运动是一次失败的封建统治者的自救运动。因此，选项 B 正确。","options":{"A":"说法错误，洋务运动是一次失败的封建统治者的自救运动，并未使中国走上富强道路。故不选。","B":"（正确选项，分析见“解题思路”）","C":"说法错误，领导洋务运动的是封建统治阶级，而非资产阶级，戊戌维新运动才是一场资产阶级性质的政治改良运动。故不选。","D":"说法错误，领导洋务运动的并非资产阶级，辛亥革命才是资产阶级领导的、以“反对君主专制制度、建立资产阶级共和国”为目的的革命运动，是一次比较完全意义上的资产阶级民主革命运动。故不选。"}}},{"id":"advanced-shigang-test3-5","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试三","chapterKey":"综合测试三","n":5,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试三 第 5 题"},"stem":"孙中山在回顾辛亥革命的历程并总结有关教训时说过：“曾几何时，已为情势所迫，不得已而与反革命的专制阶级谋妥协。此种妥协，实间接与帝国主义相调和。遂为革命第一次失败之根源。”孙中山所说的“失败之根源”指的是","choices":[{"id":"A","text":"不能建立坚强的革命政党"},{"id":"B","text":"不能充分发动和依靠人民群众"},{"id":"C","text":"没有组建一支革命的军事武装"},{"id":"D","text":"没有提出彻底的反帝反封建的革命纲领"}],"answer":["D"],"analysis":{"point":"本题考查辛亥革命失败的原因和教训。辛亥革命之所以失败，从主观方面来说，在于它的领导者资产阶级革命派本身存在着许多弱点和错误。主要是：第一，没有提出彻底的反帝反封建的革命纲领；第二，不能充分发动和依靠人民群众；第三，不能建立坚强的革命政党，作为团结一切革命力量的强有力的核心。题干中的“与帝国主义相调和”体现了辛亥革命没有反对帝国主义的主张。因此，选项 D 正确。","options":{"A":"均为辛亥革命失败的原因，但题干中没有体现。","B":"均为辛亥革命失败的原因，但题干中没有体现。","C":"均为辛亥革命失败的原因，但题干中没有体现。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-shigang-test3-6","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试三","chapterKey":"综合测试三","n":6,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试三 第 6 题"},"stem":"中国近代思想主要经历了“师夷长技以制夷”“中体西用”“维新变法”“民主共和”“民主与科学”及“马克思主义”的演进过程。这些思想反映的共同主题是","choices":[{"id":"A","text":"发展资本主义"},{"id":"B","text":"救亡图存"},{"id":"C","text":"否定封建文化"},{"id":"D","text":"民族独立、人民解放"}],"answer":["B"],"analysis":{"point":"本题考查中国近代思想的共同主题。随着资本 - 帝国主义的入侵，中国的民族危机和社会危机日益加深，中华民族的生存始终面临着西方列强的威胁，“救亡图存”成为近代中国的头等大事。中国社会各阶级、各阶层从各自的立场出发，对国家的出路进行探索，先后提出了不同的主张和方案。因此，选项B正确。","options":{"A":"仅在“维新变法”和“民主共和”思想中体现，非共同主题，故不选。","B":"（正确选项，分析见“解题思路”）","C":"与“师夷长技以制夷”和“中体西用”思想相悖，非共同主题，故不选。","D":"仅在“民主共和”“民主与科学”和“马克思主义”思想中体现，非共同主题，故不选。"}}},{"id":"advanced-shigang-test3-7","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试三","chapterKey":"综合测试三","n":7,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试三 第 7 题"},"stem":"建立革命统一战线是中国革命发展的客观需要。1923年6月，中共三大明确规定，党必须在政治上、思想上、组织上保持自己的独立性，正式决定","choices":[{"id":"A","text":"共产党员以个人身份加入国民党，以实现国共合作"},{"id":"B","text":"确认了联俄、联共、扶助农工的三大革命政策"},{"id":"C","text":"提出了反帝反封建的民主革命纲领"},{"id":"D","text":"联合全国一切革命党派，联合资产阶级民主派，组成“民主主义的联合战线”"}],"answer":["A"],"analysis":{"point":"本题考查中共三大。1923年6月，中共三大正式决定共产党员以个人身份加入国民党，以实现国共合作，明确规定，党必须在政治上、思想上、组织上保持自己的独立性。因此，选项A正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"1924年国民党一大事实上确认了联俄、联共、扶助农工的三大革命政策。","C":"中共二大第一次提出了反帝反封建的民主革命纲领，还提出必须联合全国一切革命党派，联合资产阶级民主派，组成“民主主义的联合战线”。","D":"中共二大第一次提出了反帝反封建的民主革命纲领，还提出必须联合全国一切革命党派，联合资产阶级民主派，组成“民主主义的联合战线”。"}}},{"id":"advanced-shigang-test3-8","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试三","chapterKey":"综合测试三","n":8,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试三 第 8 题"},"stem":"实行国共合作，建立革命统一战线是中国革命发展的客观需要。1923年1月，孙中山和苏俄代表越飞联名发表《孙文越飞联合宣言》，标志着","choices":[{"id":"A","text":"全国范围的大革命高潮的到来"},{"id":"B","text":"孙中山联俄政策的确立"},{"id":"C","text":"第一次国共合作的正式形成"},{"id":"D","text":"国共合作的政治基础正式形成"}],"answer":["B"],"analysis":{"point":"本题考查第一次国共合作。1923年1月，孙中山和苏俄代表越飞联名发表《孙文越飞联合宣言》，标志着孙中山联俄政策的确立。因此，选项B正确。","options":{"A":"1925年5月，以五卅运动为起点，掀起了全国范围的大革命高潮，故不选。","B":"（正确选项，分析见“解题思路”）","C":"国民党一大的成功召开，标志着第一次国共合作的正式形成，故不选。","D":"新三民主义的政纲同中国共产党在民主革命阶段的纲领基本一致，因而成为国共合作的政治基础，故不选。"}}},{"id":"advanced-shigang-test3-9","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试三","chapterKey":"综合测试三","n":9,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试三 第 9 题"},"stem":"土地革命战争时期，毛泽东指出：“一国之内，在四周白色政权的包围中，有一小块或若干小块红色政权的区域长期地存在，这是世界各国从来没有的事。这种奇事的发生，有其独特的原因。”红色政权能够存在和发展的根本原因是","choices":[{"id":"A","text":"中国是一个政治经济发展极端不平衡的半殖民地半封建大国"},{"id":"B","text":"国民革命的政治影响及良好的群众基础"},{"id":"C","text":"全国革命形势的继续向前发展"},{"id":"D","text":"相当力量正式红军的存在和党的领导的有力量及政策的不错误"}],"answer":["A"],"analysis":{"point":"本题考查红色政权能够存在和发展的根本原因。红色政权能够存在和发展的原因：第一，中国政治经济发展的不平衡性，这是根本原因。近代中国经济发展不平衡，没有统一的资本主义经济，自给自足的地方性农业经济广泛存在，这就为红色政权的存在提供了必要的物质条件；近代中国政治发展不平衡，广大农村是反动统治的薄弱环节，而农民又是革命的主力军，这使红色政权获得了深厚的阶级基础，几个帝国主义国家的间接统治和互相斗争，造成了军阀割据的局面和连绵不断的军阀混战，这使红色政权获得了存在和发展的缝隙；中国是一个大国，革命力量有广泛的回旋余地。第二，良好的群众基础，是红色政权能够存在和发展的必备客观条件。第三，全国革命形势的继续向前发展，是中国红色政权能够存在和发展的重要客观条件。第四，相当力量正式红军的存在，为农村革命根据地的创立、巩固和发展提供了坚强后盾。第五，党的领导的有力量及政策的不错误，为农村革命根据地建设和发展提供了重要的主观条件。因此，选项A正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"是红色政权能够存在和发展的必备客观条件，故不选。","C":"是红色政权能够存在和发展的重要客观条件，故不选。","D":"是红色政权能够存在和发展的主观条件，故不选。"}}},{"id":"advanced-shigang-test3-10","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试三","chapterKey":"综合测试三","n":10,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试三 第 10 题"},"stem":"1928年，毛泽东在《井冈山土地法》中规定“没收一切土地”归政府所有，交农民使用；1929年，在《兴国土地法》中把“没收一切土地”改为“没收一切公共土地及地主阶级的土地”，随后规定“田地归耕种的农民所有”。毛泽东屡次修改根据地土地政策的基本出发点是","choices":[{"id":"A","text":"探索适应当时形势的土地政策"},{"id":"B","text":"彻底废除封建半封建的土地所有制"},{"id":"C","text":"纠正土地革命中的“左”、右倾错误"},{"id":"D","text":"调动农民对生产和革命的积极性"}],"answer":["D"],"analysis":{"point":"本题考查中国共产党在土地革命战争时期的土地政策。《井冈山土地法》是中国共产党在总结1927年冬到1928年冬土地革命斗争经验的基础上制定的第一个土地法，对井冈山土地革命的发展起了一定的推动作用。但是，该土地法同时规定，没收一切土地而不是没收地主土地，没收土地归苏维埃政府所有而不是归农民所有。这些规定不符合当时农民的思想和传统习惯，不利于发展革命力量。于是，1929年4月，毛泽东主持制定了第二个土地法《兴国土地法》，将“没收一切土地”改为“没收一切公共土地及地主阶级的土地”，争取到了中间阶层的支持，随后规定“田地归耕种的农民所有”，由此广大农民群众展开了轰轰烈烈的“打土豪、分田地”的运动，农民得到了梦寐以求、赖以生存的土地，为了保卫来之不易的胜利果实，农民群众参军、参战、保家卫国的积极性被极大调动起来。因此，毛泽东屡次修改根据地土地政策的基本出发点是调动农民对生产和革命的积极性。因此，选项D正确。","options":{"A":"表述正确，但只是修改根据地土地政策的出发点之一，而不是基本出发点，故不选。","B":"是土地改革的最终目标，故不选。","C":"表述正确，但只是修改根据地土地政策的出发点之一，而不是基本出发点，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-shigang-test3-11","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试三","chapterKey":"综合测试三","n":11,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试三 第 11 题"},"stem":"1940年8月至12月初，八路军对日军发动了一场大规模的以破袭敌人交通线为重要目标的战役，这是一次大规模进攻与反“扫荡”战役。它是","choices":[{"id":"A","text":"孟良崮战役"},{"id":"B","text":"豫湘桂战役"},{"id":"C","text":"晋察冀边区反“扫荡”"},{"id":"D","text":"百团大战"}],"answer":["D"],"analysis":{"point":"本题考查百团大战。1940年8月至12月初，八路军总部调集100多个团共20万人，对华北日军发动了一场大规模的以破袭敌人交通线为重要目标的进攻战役，这就是百团大战。因此，选项D正确。","options":{"A":"均为抗日战争时期的重要战役，但与题意不符，故不选。","B":"均为抗日战争时期的重要战役，但与题意不符，故不选。","C":"均为抗日战争时期的重要战役，但与题意不符，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-shigang-test3-12","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试三","chapterKey":"综合测试三","n":12,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试三 第 12 题"},"stem":"1941年，毛泽东分析指出：土地革命战争时期，“一部分同志曾在这个伟大斗争中跌下了或跌下过机会主义的泥坑，这仍然是因为他们不去虚心领会过去的经验，对于中国的历史状况和社会状况、中国革命的特点、中国革命的规律不了解，对于马克思列宁主义的理论和中国革命的实践没有统一的理解而来的”。这说明，中国共产党内反复出现“左”倾错误的思想认识根源是","choices":[{"id":"A","text":"斗争经验不足"},{"id":"B","text":"没有严格遵循马克思列宁主义的理论结论"},{"id":"C","text":"没有科学理论的指导"},{"id":"D","text":"主观主义"}],"answer":["D"],"analysis":{"point":"本题考查中国共产党内反复出现“左”倾错误的思想认识根源。在20世纪30年代前期、中期，中国共产党内屡次出现严重的“左”倾错误，其原因是多方面的。主观主义是中国共产党内反复出现“左”、右倾错误的思想认识根源。主观主义的实质是理论脱离实际，颠倒了认识和实践的关系，是实际工作中的唯心主义。因此，选项D正确。","options":{"A":"“斗争经验不足”是一个原因，但不是出现“左”倾错误的思想认识根源，故不选。","B":"表述错误，马克思主义为我们提供的是世界观和方法论，而不是要求我们严格遵循其理论结论，故不选。","C":"“没有科学理论的指导”与事实不符，中国共产党以马克思主义为指导，这就是科学的理论，当时的中国共产党只是不懂得将马克思主义与中国的具体实际相结合，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-shigang-test3-13","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试三","chapterKey":"综合测试三","n":13,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试三 第 13 题"},"stem":"在中共七届二中全会上，毛泽东强调，“必须用极大的努力去学会管理城市和建设城市”；“从我们接管城市的第一天起，我们的眼睛就要向着这座城市的生产事业的恢复和发展”；城市中的其他一切工作，“都是围绕着生产建设这一中心工作并为这个中心工作服务的”。这清楚地表明","choices":[{"id":"A","text":"中国人民已经夺取了战争胜利，实现了全国解放"},{"id":"B","text":"中国的民主革命任务基本完成"},{"id":"C","text":"中华人民共和国开始由新民主主义社会转变为社会主义社会"},{"id":"D","text":"党开始实行工作重心转移的方针"}],"answer":["D"],"analysis":{"point":"本题考查党的工作重心的转移。题干中，毛泽东同志的这段话的意思是在全国胜利的局面下，采取农村包围城市这样一种工作方式的时期已经完结，党的工作重心必须由乡村转移到城市。因此，选项D正确。","options":{"A":"为中华人民共和国成立的历史意义，故不选。","B":"为中华人民共和国成立的历史意义，故不选。","C":"为社会主义改造的历史意义，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-shigang-test3-14","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试三","chapterKey":"综合测试三","n":14,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试三 第 14 题"},"stem":"1947年6月底，根据中共中央的政策和部署，刘伯承、邓小平率领的晋冀鲁豫野战军主力，实施中央突破，千里跃进大别山；陈毅、粟裕指挥的华东野战军主力为东路，挺进苏鲁豫皖地区；陈赓、谢富治指挥的晋冀鲁豫野战军一部为西路，挺进豫西。三路大军相互策应，机动歼敌，迫使国民党军处于被动地位。这表明","choices":[{"id":"A","text":"人民解放战争进入战略相持阶段"},{"id":"B","text":"人民解放战争战略进攻的序幕由此揭开"},{"id":"C","text":"人民解放军同国民党军队进行战略决战的时机已经成熟"},{"id":"D","text":"人民解放军在数量上已经超过国民党军队"}],"answer":["B"],"analysis":{"point":"本题考查人民解放战争。根据中共中央的政策和部署，刘伯承、邓小平率领的晋冀鲁豫野战军主力，于1947年6月30日突破黄河天险，千里跃进大别山；陈毅、粟裕指挥的华东野战军主力为东路，挺进苏鲁豫皖地区；陈赓、谢富治指挥的晋冀鲁豫野战军一部为西路，挺进豫西。三路大军相互策应，机动歼敌，迫使国民党军处于被动地位。人民解放战争战略进攻的序幕由此揭开。因此，选项B正确。","options":{"A":"1946年6月至1947年6月，人民军队处于战略防御阶段，并没有“战略相持阶段”的说法。","B":"（正确选项，分析见“解题思路”）","C":"1948年秋，人民解放战争进入夺取全国胜利的决定性阶段，人民解放军同国民党军队进行战略决战的时机已经成熟，与题干中战略进攻的时间点不符。","D":"1949年战略决战后，三大战役结束时，人民解放军在数量上超过国民党军队。"}}},{"id":"advanced-shigang-test3-15","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试三","chapterKey":"综合测试三","n":15,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试三 第 15 题"},"stem":"中国共产党对资本主义工商业采取了从初级到高级的国家资本主义的过渡形式。初级形式的国家资本主义是国家对私营工商业实行委托加工、计划订货、统购包销、经销代销等；高级形式的国家资本主义是公私合营。在公私合营期间，合营企业","choices":[{"id":"A","text":"属于半社会主义性质"},{"id":"B","text":"给予资方或原工商业者在经济利益上的照顾"},{"id":"C","text":"由国家和资本家共同占有生产资料"},{"id":"D","text":"始终按照“四马分肥”政策进行利润分配"}],"answer":["B"],"analysis":{"point":"本题考查对资本主义工商业的社会主义改造。个别企业公私合营期间，企业利润的分配采取“四马分肥”的政策，资方红利大体占1/4；全行业公私合营期间，国家按企业资本的股份额，每年拨付给原工商业者5%的定息，开始决定付息7年，后来又延长3年，共计10年。由此可见，资方或原工商业者能够获得相应的经济补偿。因此，选项B正确。","options":{"A":"说法片面，都是指个别企业公私合营期间的企业，没有囊括全行业公私合营期间的企业，故不选。","B":"（正确选项，分析见“解题思路”）","C":"说法片面，都是指个别企业公私合营期间的企业，没有囊括全行业公私合营期间的企业，故不选。","D":"说法片面，都是指个别企业公私合营期间的企业，没有囊括全行业公私合营期间的企业，故不选。"}}},{"id":"advanced-shigang-test3-16","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试三","chapterKey":"综合测试三","n":16,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试三 第 16 题"},"stem":"中国共产党第十二次全国代表大会，是进入改革开放新时期后党召开的第一次全国代表大会。本次大会提出的重大崭新命题，成为指引改革开放和社会主义现代化建设的伟大旗帜。这一重大崭新命题是","choices":[{"id":"A","text":"“公有制基础上的有计划的商品经济”"},{"id":"B","text":"“建设有中国特色的社会主义”"},{"id":"C","text":"“市场经济不等于资本主义”"},{"id":"D","text":"提出“邓小平理论”这一概念"}],"answer":["B"],"analysis":{"point":"本题考查党的十二大的历史贡献，属于识记性试题。1982年9月1日至11日，中国共产党第十二次全国代表大会在北京举行。邓小平在开幕词中响亮提出：“把马克思主义的普遍真理同我国的具体实际结合起来，走自己的道路，建设有中国特色的社会主义。”“建设有中国特色的社会主义”的重大崭新命题，回答了进入改革开放新时期后走什么样的道路这一全党和全国人民最为关心的重大问题，成为指引改革开放和社会主义现代化建设的伟大旗帜。因此，选项B正确。","options":{"A":"是党的十二届三中全会提出的。","B":"（正确选项，分析见“解题思路”）","C":"属于邓小平南方谈话的内容。","D":"是党的十五大正式提出的。"}}},{"id":"advanced-shigang-test3-17","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试三","chapterKey":"综合测试三","n":17,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试三 第 17 题"},"stem":"2012年11月8日至14日，中国共产党第十八次全国代表大会在北京举行。中共十八大的召开","choices":[{"id":"A","text":"进一步全面阐明了科学发展观的客观依据和科学内涵"},{"id":"B","text":"明确了中国跨世纪发展的战略部署"},{"id":"C","text":"形成了习近平新时代中国特色社会主义思想"},{"id":"D","text":"开启了中国特色社会主义新时代"}],"answer":["D"],"analysis":{"point":"本题考查中共十八大。中共十八大的召开，标志着中国已经进入全面建成小康社会的决定性阶段，开启了中国特色社会主义新时代。因此，选项D正确。","options":{"A":"中共十七大进一步全面阐明了科学发展观的客观依据和科学内涵，故不选。","B":"中共十五大明确了中国跨世纪发展的战略部署，故不选。","C":"中共十九大形成了习近平新时代中国特色社会主义思想，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-shigang-test3-18","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试三","chapterKey":"综合测试三","n":18,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试三 第 18 题"},"stem":"1894年，日本以突然袭击清朝陆海军的方式挑起了第一次大规模的侵华战争，史称甲午战争。甲午战争是日本对外侵略扩张，“开拓万里波涛，布国威于四方”的必然产物，清朝在战争中惨败。甲午战争的惨败","choices":[{"id":"A","text":"造成了新的民族危机，激发了新的民族觉醒"},{"id":"B","text":"使中国陷入“边疆危机”"},{"id":"C","text":"掀起了列强瓜分中国的狂潮"},{"id":"D","text":"标志着以“自强”“求富”为目标的洋务运动的失败"}],"answer":["A","C","D"],"analysis":{"point":"本题考查中日甲午战争。甲午战争的惨败，标志着以“自强”“求富”为目标的洋务运动的失败，掀起了列强瓜分中国的狂潮，造成了新的民族危机，激发了新的民族觉醒。因此，选项A、C、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"19世纪70至80年代，列强从侵占中国周边邻国发展到蚕食中国边疆地区，使中国陷入“边疆危机”。","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-shigang-test3-19","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试三","chapterKey":"综合测试三","n":19,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试三 第 19 题"},"stem":"在向西方学习的过程中，戊戌维新运动与洋务运动的不同点在于","choices":[{"id":"A","text":"学习西方的科学技术"},{"id":"B","text":"学习西方的政治制度"},{"id":"C","text":"批判封建的伦理道德"},{"id":"D","text":"主张采取君主立宪制"}],"answer":["B","C","D"],"analysis":{"point":"本题考查戊戌维新运动与洋务运动的不同点。戊戌维新运动是一场资产阶级性质的政治改良运动。维新派突破洋务派“中体西用”思想的局限，主张改革君主专制制度。他们鼓吹民权并提出设议院的主张，也就是要用君主立宪制取代君主专制制度。戊戌维新运动更是一场思想启蒙运动。在维新运动期间，维新派大力传播西方资产阶级的社会政治学说和自然科学知识，宣传自由平等、社会进化观念，批判封建君权和封建纲常伦理，从而将顽固的封建主义思想壁垒打开了一个缺口，有利于民主思想在中国的传播，有利于人们的思想解放。洋务派虽认为西方的军事和技术可以学习，但坚持封建的政治制度、科举八股，尤其不能触动“三纲五常”。因此，选项B、C、D正确。","options":{"A":"是戊戌维新运动与洋务运动的相同点，故不选。","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-shigang-test3-20","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试三","chapterKey":"综合测试三","n":20,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试三 第 20 题"},"stem":"毛泽东说：“民国元年的《中华民国临时约法》，在那个时期是一个比较好的东西。”《中华民国临时约法》作为第一部具有资产阶级共和国宪法性质的法典，其进步性表现在","choices":[{"id":"A","text":"确认了资产阶级共和国的政治制度"},{"id":"B","text":"带有鲜明的革命性、民主性"},{"id":"C","text":"不承认清政府与列强所签订的一切不平等条约"},{"id":"D","text":"制定了满足农民土地要求的政策和措施"}],"answer":["A","B"],"analysis":{"point":"本题考查《中华民国临时约法》（简称《临时约法》）。《临时约法》的进步性：第一，《临时约法》以根本大法的形式废除了2 000多年来的封建君主专制制度，确认了资产阶级共和国的政治制度。第二，《临时约法》是革命的产物，带有鲜明的革命性、民主性。它不仅具有现实的进步意义，在中国宪政史上也占有重要的地位。因此，选项A、B正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"南京临时政府也有它的局限性：第一，在《告友邦书》中，南京临时政府就企图用承认清政府与列强所签订的一切不平等条约和清政府所欠的一切外债，来换取列强承认中华民国。第二，南京临时政府也没有提出任何可以满足农民土地要求的政策和措施，反而以保护私有财产为借口，去维护封建土地制度以及官僚、地主所占有的土地和财产。故不选。","D":"南京临时政府也有它的局限性：第一，在《告友邦书》中，南京临时政府就企图用承认清政府与列强所签订的一切不平等条约和清政府所欠的一切外债，来换取列强承认中华民国。第二，南京临时政府也没有提出任何可以满足农民土地要求的政策和措施，反而以保护私有财产为借口，去维护封建土地制度以及官僚、地主所占有的土地和财产。故不选。"}}},{"id":"advanced-shigang-test3-21","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试三","chapterKey":"综合测试三","n":21,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试三 第 21 题"},"stem":"1915年9月，陈独秀在上海创办《青年杂志》（后改名《新青年》），吹响了新文化运动的号角。新文化运动高举民主和科学两面大旗，向封建主义思想文化发起了前所未有的猛烈冲击。新文化运动的历史意义表现在它","choices":[{"id":"A","text":"是中国历史上一次前所未有的启蒙运动"},{"id":"B","text":"在社会上掀起了一股思想解放的潮流"},{"id":"C","text":"为马克思主义在中国的传播创造了有利条件"},{"id":"D","text":"彻底否定了孔学的历史作用"}],"answer":["A","B","C"],"analysis":{"point":"本题考查新文化运动。新文化运动是中国历史上一次前所未有的启蒙运动和空前深刻的思想解放运动。正是在新文化运动的推动和影响下，中国涌现了一批青年革命民主主义者。其中的先进分子受俄国十月革命的影响，为马克思主义在中国的广泛传播准备了思想的和文化的条件。因此，选项A、B、C正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"新文化运动的思想家们对孔学的批判是充满理性的，并不是彻底否定，故不选。"}}},{"id":"advanced-shigang-test3-22","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试三","chapterKey":"综合测试三","n":22,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试三 第 22 题"},"stem":"1915年兴起的新文化运动，在中国社会掀起了一股思想解放的潮流。但五四运动以前的新文化运动存在一定的弱点，正如毛泽东后来指出的：“那时的许多领导人物，还没有马克思主义的批判精神，他们使用的方法，一般地还是资产阶级的方法，即形式主义的方法。”五四运动以前的新文化运动的局限主要有","choices":[{"id":"A","text":"割裂了封建思想与产生封建思想的社会制度"},{"id":"B","text":"脱离工农大众，仅仅依靠少数人的呐喊"},{"id":"C","text":"对孔学和中国的传统文化采取了否定一切的态度"},{"id":"D","text":"未能认识到西方资产阶级文化的历史局限性和阶级局限性"}],"answer":["A","B","D"],"analysis":{"point":"本题考查五四运动以前的新文化运动的局限。新文化运动的倡导者把改造国民性置于优先地位，但是，离开改造产生封建思想的社会环境的革命实践，仅仅依靠少数人的呐喊，是不可能的；新文化运动的倡导者批判孔学，是为了给中国发展资本主义扫清障碍，但是提倡资产阶级民主主义，并不能为人们提供一种有效的思想武器去认识中国和改造中国。因此，选项A、B、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"说法错误，新文化运动的倡导者对孔学的批判是充满理性的，并没有因为批判孔学就否定中国的全部传统文化。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-shigang-test3-23","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试三","chapterKey":"综合测试三","n":23,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试三 第 23 题"},"stem":"1931年11月，中华苏维埃第一次全国代表大会在江西瑞金召开。大会通过了《中华苏维埃共和国宪法大纲》以及土地法令、劳动法等，选举产生了中华苏维埃共和国中央执行委员会，成立了中华苏维埃共和国临时中央政府，毛泽东当选为主席。中华苏维埃共和国","choices":[{"id":"A","text":"在工作人员分配上实行“三三制”原则"},{"id":"B","text":"一定程度上加强了对处于被分割状态的各根据地的中枢指挥作用"},{"id":"C","text":"是中国共产党在局部地区执政的重要尝试"},{"id":"D","text":"是中国历史上第一个全国性的工农民主政权"}],"answer":["B","C","D"],"analysis":{"point":"本题考查中华苏维埃共和国。中华苏维埃共和国是中国历史上第一个全国性的工农民主政权，是中国共产党在局部地区执政的重要尝试，扩大了党和红色政权的影响，一定程度上加强了对处于被分割状态的各根据地的中枢指挥作用，推动了各根据地的政权、经济、文化教育和党的自身建设，开创了土地革命战争新局面。因此，选项B、C、D正确。","options":{"A":"抗日根据地政权建设采取“三三制”原则，而本题考查的是土地革命战争时期。故不选。","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-shigang-test3-24","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试三","chapterKey":"综合测试三","n":24,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试三 第 24 题"},"stem":"南昌起义，是1927年8月1日在江西南昌由中国共产党领导的军队针对中国国民党的分共政策而发起的武装反抗事件。南昌起义的历史意义包括","choices":[{"id":"A","text":"打响了武装反抗国民党反动统治的第一枪"},{"id":"B","text":"成为中国共产党独立领导革命战争、创建人民军队和武装夺取政权的伟大开端"},{"id":"C","text":"是从大革命失败到土地革命战争兴起的转折点"},{"id":"D","text":"开辟了农村包围城市的道路"}],"answer":["A","B"],"analysis":{"point":"本题考查南昌起义的历史意义。1927年8月1日，周恩来、贺龙、叶挺、朱德、刘伯承等人率领由共产党掌握或影响的2万多北伐军在南昌举行起义，打响了武装反抗国民党反动统治的第一枪。这是中国共产党独立领导革命战争、创建人民军队和武装夺取政权的伟大开端。中国革命由此发展到了一个新的阶段，即土地革命战争时期，或称十年内战时期。因此，选项A、B正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"是八七会议的意义，而不是南昌起义的意义，故不选。","D":"是在建立井冈山革命根据地以后，故不选。"}}},{"id":"advanced-shigang-test3-25","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试三","chapterKey":"综合测试三","n":25,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试三 第 25 题"},"stem":"1937年夏，毛泽东在延安抗日军事政治大学讲授《实践论》和《矛盾论》，总结中国共产党的历史经验。关于《实践论》和《矛盾论》，下列说法正确的有","choices":[{"id":"A","text":"深入论证了马克思列宁主义基本原理同中国具体实际相结合的原则"},{"id":"B","text":"揭露和批评了党内的主观主义尤其是教条主义错误"},{"id":"C","text":"系统地解决了党的政治路线上的问题"},{"id":"D","text":"科学地阐明了党的马克思主义的思想路线"}],"answer":["A","B","D"],"analysis":{"point":"本题考查《实践论》和《矛盾论》。这两篇文章从马克思主义认识论的高度，总结中国共产党的历史经验，揭露和批评党内的主观主义尤其是教条主义错误，深入论证马克思列宁主义基本原理同中国具体实际相结合的原则，科学地阐明了党的马克思主义的思想路线。因此，选项A、B、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"1935年12月，毛泽东作了《论反对日本帝国主义的策略》的报告，阐明党的抗日民族统一战线的新政策，批判党内的关门主义和对于革命的急性病，系统地解决了党的政治路线上的问题，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-shigang-test3-26","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试三","chapterKey":"综合测试三","n":26,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试三 第 26 题"},"stem":"1938年5月至6月，毛泽东发表《论持久战》的讲演，总结抗战10个月以来的经验，集中全党智慧，系统地阐明了持久抗战的总方针。这一方针","choices":[{"id":"A","text":"成为中国共产党指导抗日战争的纲领"},{"id":"B","text":"揭示了抗日战争的发展规律"},{"id":"C","text":"指明了坚持抗战和争取抗战胜利必须实行的战略方针"},{"id":"D","text":"坚定了坚持抗战的信念，对全国抗战的战略指导产生了积极的影响"}],"answer":["B","C","D"],"analysis":{"point":"本题考查持久抗战的总方针。1938年，毛泽东发表《论持久战》，阐明了持久抗战的战略思想，揭示了抗日战争的发展规律和坚持抗战、争取抗战胜利必须实行的战略方针，对全国抗战的战略指导产生了积极的影响。因此，选项B、C、D正确。","options":{"A":"与题意不符，1937年8月，中国共产党在陕北洛川召开政治局扩大会议，制定了抗日救国十大纲领，这个纲领全面概括了中国共产党在抗日战争时期的基本政治主张，故不选。","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-shigang-test3-27","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试三","chapterKey":"综合测试三","n":27,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试三 第 27 题"},"stem":"在解放战争胜利推进的同时，解放区开展了轰轰烈烈的土地改革运动。1946年5月4日，中共中央发布《关于土地问题的指示》（简称“五四指示”）；1947年7月至9月，中国共产党在河北省平山县召开全国土地会议，制定和通过了《中国土地法大纲》。“五四指示”和《中国土地法大纲》的共同之处在于","choices":[{"id":"A","text":"主要目的是削弱封建剥削"},{"id":"B","text":"核心政策是实行“耕者有其田”"},{"id":"C","text":"改变了抗战时期的土地政策"},{"id":"D","text":"保存了富农经济"}],"answer":["B","C"],"analysis":{"point":"本题考查“五四指示”和《中国土地法大纲》的相同点。“五四指示”的基本内容：要坚决地支持和引导广大农民群众，采取各种适当方法，使地主阶级剥削农民而占有的土地转移到农民手中；用一切方法吸收中农参加运动，绝不可侵犯中农土地；一般不变动富农土地，对富农和地主有所区别；不可将农村中反对封建地主阶级的方法，运用于城市中反对工商业资产阶级的斗争。这就将党在抗日战争时期实行的减租减息政策改变为实行“耕者有其田”的政策。这一政策的提出，标志着解放区在农民土地问题上，开始由抗日战争时期的削弱封建剥削，向变革封建土地关系、废除封建剥削制度过渡。《中国土地法大纲》的基本内容：“废除封建性及半封建性剥削的土地制度，实行耕者有其田的土地制度”“乡村中一切地主的土地及公地，由乡村农会接收”，分配给无地或少地的农民。这个大纲指引着在封建制度压迫下的亿万农民群众，将自己的力量汇入民主革命的洪流。因此，选项B、C正确。","options":{"A":"表述错误，《中国土地法大纲》不是为了削弱封建剥削，而是要废除封建剥削，故不选。","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"表述错误，保存富农经济是在《中华人民共和国土地改革法》中提出的土地政策，故不选。"}}},{"id":"advanced-shigang-test3-28","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试三","chapterKey":"综合测试三","n":28,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试三 第 28 题"},"stem":"1949年3月5日至13日，中共七届二中全会在河北省平山县西柏坡村举行。中共七届二中全会是解放战争时期中国共产党召开的唯一一次中央全会，这次会议","choices":[{"id":"A","text":"指出了党的工作重心必须由乡村转移到城市"},{"id":"B","text":"指出了中国由新民主主义社会转变为社会主义社会的发展方向"},{"id":"C","text":"提出了“两个务必”的思想"},{"id":"D","text":"标志着中国的新型政党制度的确立"}],"answer":["A","B","C"],"analysis":{"point":"本题考查中共七届二中全会。中共七届二中全会，规定了党在全国胜利后在政治、经济、外交方面应当采取的基本政策，指出了党的工作重心必须由乡村转移到城市，指出了中国由农业国转变为工业国、由新民主主义社会转变为社会主义社会的发展方向，提出了“两个务必”的思想，即“务必使同志们继续地保持谦虚、谨慎、不骄、不躁的作风，务必使同志们继续地保持艰苦奋斗的作风”。因此，选项A、B、C正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"人民政协会议的召开，标志着中国的新型政党制度——中国共产党领导的多党合作和政治协商制度的确立。"}}},{"id":"advanced-shigang-test3-29","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试三","chapterKey":"综合测试三","n":29,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试三 第 29 题"},"stem":"1957年2月，毛泽东在最高国务会议上发表《关于正确处理人民内部矛盾的问题》的讲话，他强调指出","choices":[{"id":"A","text":"社会主义社会的基本矛盾仍然是生产关系和生产力之间、上层建筑和经济基础之间的矛盾"},{"id":"B","text":"社会主义社会的主要矛盾是工人阶级和资产阶级的矛盾"},{"id":"C","text":"社会主义社会的矛盾可以通过社会主义制度本身得到解决"},{"id":"D","text":"把正确处理人民内部矛盾作为国家政治生活的主题"}],"answer":["A","C","D"],"analysis":{"point":"本题考查《关于正确处理人民内部矛盾的问题》。该讲话系统论述了社会主义社会矛盾的理论。毛泽东指出：“在社会主义社会中，基本的矛盾仍然是生产关系和生产力之间的矛盾，上层建筑和经济基础之间的矛盾。”毛泽东强调，在我们面前有两类社会矛盾，这就是敌我矛盾和人民内部矛盾，这是两类性质完全不同的矛盾。社会主义社会的矛盾可以通过社会主义制度本身得到解决。毛泽东强调，关于正确处理人民内部矛盾的问题是社会主义国家政治生活的主题。因此，选项A、C、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"表述错误，当时我们国内的主要矛盾已经不是工人阶级和资产阶级的矛盾，而是人民对于经济文化迅速发展的需要同当前经济文化不能满足人民需要的状况之间的矛盾。","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-shigang-test3-30","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试三","chapterKey":"综合测试三","n":30,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试三 第 30 题"},"stem":"1987年10月25日至11月1日，中国共产党第十三次全国代表大会在北京举行。中共十三大的突出贡献有","choices":[{"id":"A","text":"比较系统地阐述了关于社会主义初级阶段的理论"},{"id":"B","text":"确立了社会主义市场经济体制的改革目标"},{"id":"C","text":"明确概括了党在社会主义初级阶段的基本路线"},{"id":"D","text":"阐述了关于社会主义本质论的思想"}],"answer":["A","C"],"analysis":{"point":"本题考查中共十三大。中共十三大的突出贡献是比较系统地阐述了关于社会主义初级阶段的理论，明确概括了党在社会主义初级阶段的基本路线。因此，选项A、C正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"中共十四大确立了社会主义市场经济体制的改革目标，故不选。","C":"（正确选项，分析见“解题思路”）","D":"南方谈话系统阐述了社会主义本质论，即解放生产力，发展生产力，消灭剥削，消除两极分化，最终达到共同富裕，故不选。"}}},{"id":"advanced-shigang-test4-1","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试四","chapterKey":"综合测试四","n":1,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试四 第 1 题"},"stem":"1894年11月，孙中山指出：“方今强邻环列，虎视鹰瞵，久垂涎于中华五金之富，物产之饶。蚕食鲸吞，已效尤于接踵；瓜分豆剖，实堪虑于目前。有心人不禁大声疾呼，亟拯斯民于水火，切扶大厦之将倾。”由此，孙中山组建的第一个革命团体是","choices":[{"id":"A","text":"华兴会"},{"id":"B","text":"兴中会"},{"id":"C","text":"同盟会"},{"id":"D","text":"国民党"}],"answer":["B"],"analysis":{"point":"本题考查孙中山领导的革命活动。1894年11月，孙中山到檀香山组建了第一个革命团体兴中会，立誓“驱除鞑虏，恢复中国，创立合众政府”。因此，选项B正确。","options":{"A":"华兴会是中国近代民主革命团体，于1904年在湖南长沙成立，故不选。","B":"（正确选项，分析见“解题思路”）","C":"1905年8月20日，孙中山和黄兴、宋教仁等人以兴中会和华兴会为基础，在日本东京成立中国同盟会，故不选。","D":"1912年，同盟会改组为国民党，故不选。"}}},{"id":"advanced-shigang-test4-2","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试四","chapterKey":"综合测试四","n":2,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试四 第 2 题"},"stem":"近代中国，一些爱国人士提出过工业救国、教育救国、科学救国等主张，并为此进行过努力，但这些主张并不能从根本上给濒临危亡的中国指明正确的出路，这是因为他们没有认识到","choices":[{"id":"A","text":"争取民族独立和人民解放是实现民族复兴的前提"},{"id":"B","text":"中国已经被卷入世界资本主义经济体系和世界市场中"},{"id":"C","text":"中国是一个经济政治发展不平衡的国家"},{"id":"D","text":"资本主义制度已经过时"}],"answer":["A"],"analysis":{"point":"本题考查旧民主主义革命的失败。近代以来中华民族面临的两大历史任务，就是争取民族独立、人民解放和实现国家富强、人民幸福。前一个任务为后一个任务扫除障碍，创造必要的前提；后一个任务是前一个任务的最终目的和必然要求。工业救国、教育救国、科学救国等主张实际上属于第二个任务，这是中华人民共和国成立后的历史任务，在当时半殖民地半封建社会的条件下，应当先完成第一个任务。因此，选项A正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"说的是中国的客观情况，当时的人们也意识到了中国的情况，只不过这并不是失败的根源。故不选。","C":"说的是中国的客观情况，当时的人们也意识到了中国的情况，只不过这并不是失败的根源。故不选。","D":"“资本主义制度已经过时”的说法是错误的，确切地说，在今天都不算过时。故不选。"}}},{"id":"advanced-shigang-test4-3","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试四","chapterKey":"综合测试四","n":3,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试四 第 3 题"},"stem":"19世纪60年代到90年代，清朝统治阶级内部的洋务派兴办近代企业，建立新式海陆军，创办新式学堂，派遣留学生。洋务派兴办洋务新政的主要目的是","choices":[{"id":"A","text":"发展资本主义"},{"id":"B","text":"维护封建统治"},{"id":"C","text":"对抗顽固派"},{"id":"D","text":"迎合帝国主义"}],"answer":["B"],"analysis":{"point":"本题考查洋务运动。洋务运动是封建地主阶级引进近代工业，仿造洋枪洋炮，以期富国强兵，延续封建统治而兴起的一场运动。洋务运动的指导思想是“中体西用”，就是仍然以中国封建伦理纲常所维护的统治秩序为主体，辅之以西方的近代工业和技术，所以，洋务派兴办洋务新政的主要目的是维护封建统治。因此，选项B正确。","options":{"A":"发展资本主义不是封建阶级的主张，而是资产阶级维新派和革命派的主张，故排除。","B":"（正确选项，分析见“解题思路”）","C":"表述错误。在中国近代史上，提到顽固派的说法有两处：一处是洋务运动时期，指那些对世界发展形势一无所知、因循守旧、愚昧无知、盲目排外、仇视一切外国事物、幻想恢复“闭关锁国”局面的极端腐朽的贵族和官僚；另一处是抗日战争时期，指以蒋介石集团为代表的国民党亲英美派。该选项所指的是前者。该选项的错误在于逻辑颠倒，正因为洋务派要兴办洋务运动，才有顽固派进行反对，所以洋务运动最主要的目的肯定不是对抗顽固派。故排除。","D":"从帝国主义的利益角度看，它们也希望看到中国向它们学习，并且不断从西方购买机器设备和军事武器。但是兴办洋务新政的最主要的目的肯定不是迎合帝国主义，而是从自身利益出发，维护封建阶级的统治。故排除。"}}},{"id":"advanced-shigang-test4-4","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试四","chapterKey":"综合测试四","n":4,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试四 第 4 题"},"stem":"旧民主主义革命是由资产阶级领导的，以建立资本主义社会和资产阶级专政的国家为目的，反对外国侵略和本国封建统治的革命。资产阶级领导的旧民主主义革命的接连失败说明","choices":[{"id":"A","text":"中国缺乏民主革命的条件"},{"id":"B","text":"资产阶级不能领导中国革命走向胜利"},{"id":"C","text":"中国社会主要矛盾的变化"},{"id":"D","text":"资产阶级的革命性不断退化"}],"answer":["B"],"analysis":{"point":"本题考查旧民主主义革命失败的原因。资产阶级领导的旧民主主义革命的接连失败，从根本上说是因为在帝国主义时代，在半殖民地半封建的中国，资本主义的建国方案是行不通的。从主观方面来说，作为领导者的资产阶级革命派本身具有软弱性，没有提出彻底的反帝反封建的革命纲领；不能充分发动和依靠人民群众；不能建立坚强的革命政党，成为团结一切革命力量的强有力的核心，无法领导反帝反封建的中国革命走向胜利。因此，选项B正确。","options":{"A":"表述错误。“清末新政”中奖励实业的政策刺激了民族资本主义的发展，为民主革命运动提供了物质基础。人民群众的反帝反封建斗争风起云涌，为资产阶级民主革命运动提供了群众基础。随着资产阶级队伍的壮大，资产阶级民主革命思潮得到了广泛传播，为革命奠定了思想基础。所以，当时的中国并不缺乏民主革命的条件。故不选。","B":"（正确选项，分析见“解题思路”）","C":"表述错误，中国半殖民地半封建社会的主要矛盾，仍然是帝国主义和中华民族的矛盾、封建主义和人民大众的矛盾，故不选。","D":"表述错误。民族资产阶级具有两面性——革命性和妥协性。民族资产阶级的这种两面性，决定了它们在一定时期内和一定程度上能够参加反对帝国主义和反对官僚军阀政府的革命，成为革命的一种力量。而在另一时期，民族资产阶级也有跟随买办大资产阶级，作为反革命助手的危险。旧民主主义革命时期，民族资产阶级在革命与妥协中反复，其革命性并不是不断退化的。故不选。"}}},{"id":"advanced-shigang-test4-5","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试四","chapterKey":"综合测试四","n":5,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试四 第 5 题"},"stem":"古语云：“六十年一甲子。”1851年的金田起义与1911年的武昌起义，虽然同属辛亥年，但历史境遇迥异。面对太平天国，汉族官僚自募乡勇，奋起抵抗；而面对辛亥革命，各地官绅却无人救难，作壁上观。如果让当时的有识之士抉择，在大清帝国与太平天国之间，他们或许仍会选择前者；而在大清帝国与中华民国之间，他们则更倾向后者。造成这种历史差异的主要原因在于，辛亥革命","choices":[{"id":"A","text":"提出了推翻清政府统治的目标"},{"id":"B","text":"制定了彻底的反帝反封建纲领"},{"id":"C","text":"描绘了资产阶级共和国的方案"},{"id":"D","text":"否定了封建地主的土地所有制"}],"answer":["C"],"analysis":{"point":"本题考查太平天国农民战争和辛亥革命的区别。太平天国农民战争是中国旧式农民战争的最高峰，主张通过平均分配土地的方式，建立“无处不均匀，无人不饱暖”的理想社会，但这种社会理想在很大程度上具有不切实际的空想性质，未能付诸实施。而辛亥革命是一次比较完全意义上的资产阶级民主革命，主张推翻封建君主专制制度，建立资产阶级民主共和国，这不仅集中反映了中国民族资产阶级的愿望和利益，在相当程度上也符合广大中国人民的利益，因而更能够吸引当时的有识之士。因此，选项C正确。","options":{"A":"太平天国农民战争和辛亥革命都提出了推翻清政府统治的目标，这并非二者的区别。","B":"辛亥革命制定的三民主义是一个不彻底的反帝反封建纲领。","C":"（正确选项，分析见“解题思路”）","D":"辛亥革命制定的“平均地权”的主张，没有正面触及封建地主的土地所有制。"}}},{"id":"advanced-shigang-test4-6","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试四","chapterKey":"综合测试四","n":6,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试四 第 6 题"},"stem":"中国共产党的成立是“开天辟地的大事变”，它给中国革命带来了新的革命方法和新的指导思想。其中，新的革命方法是指","choices":[{"id":"A","text":"农村包围城市、武装夺取政权"},{"id":"B","text":"马克思主义"},{"id":"C","text":"广泛发动和组织群众"},{"id":"D","text":"彻底地开展反帝反封建的斗争"}],"answer":["C"],"analysis":{"point":"本题考查中国共产党成立的伟大意义。中国共产党成立后，开始采取民族资产阶级、小资产阶级的政党和政治派别没有采取过、也不可能采取的革命方法，即群众路线的方法。因此，选项C正确。","options":{"A":"是大革命失败后中国共产党开辟的中国革命新道路，不是革命方法，故不选。","B":"“马克思主义”不是中国革命的革命方法，而是指导思想，故不选。","C":"（正确选项，分析见“解题思路”）","D":"不是在中国共产党成立时提出的，而是在1922年召开的中共二大上第一次提出了彻底的反帝反封建的民主革命纲领，为中国人民指出了明确的斗争目标。故不选。"}}},{"id":"advanced-shigang-test4-7","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试四","chapterKey":"综合测试四","n":7,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试四 第 7 题"},"stem":"“党的一切运动都必须深入到广大的群众里面去”，都“必须是不离开群众的”。提出这一路线的会议是","choices":[{"id":"A","text":"中共一大"},{"id":"B","text":"国民党一大"},{"id":"C","text":"中共三大"},{"id":"D","text":"中共二大"}],"answer":["D"],"analysis":{"point":"本题考查中国共产党采取的革命方法。中共二大于1922年7月16日至23日在上海召开。大会根据列宁关于民族和殖民地问题的理论和中国半殖民地半封建的社会性质，制定了党的最高纲领和最低纲领。中共二大在对中国社会各阶级的状况进行初步分析的基础上指出，为了实现反帝反军阀的革命目标，必须组成“民主主义的联合战线”，并要采取全新的革命方法，即发动和依靠群众的方法。中共二大指出，“我们共产党，不是‘知识者所组织的马克思学会’，也不是‘少数共产主义者离开群众之空想的革命团体’”，“我们既然是为无产群众奋斗的政党，我们便要‘到群众中去’，要组成一个大的‘群众党’”。因此，选项D正确。","options":{"A":"与题意不符，中共一大正式宣告了中国共产党的诞生，并通过了党纲，故不选。","B":"与题意不符，国民党一大的成功召开，标志着第一次国共合作正式形成，故不选。","C":"与题意不符，中共三大确定了建立国共合作革命统一战线的策略，促进了第一次国共合作的实现，使共产党活动的政治舞台迅速扩大，加速了中国革命的步伐，为波澜壮阔的第一次大革命作了准备，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-shigang-test4-8","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试四","chapterKey":"综合测试四","n":8,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试四 第 8 题"},"stem":"在八七会议上，毛泽东批评了党的领导人加入国民党不是去做主人而只是做客人，始终无当主人的决心。这主要是","choices":[{"id":"A","text":"批评陈独秀的右倾机会主义错误"},{"id":"B","text":"批评当时的“左”倾关门主义"},{"id":"C","text":"指责共产国际不了解中国国情"},{"id":"D","text":"谴责武汉国民政府的背叛"}],"answer":["A"],"analysis":{"point":"本题考查第一次国共合作。当时的中共中央犯了以陈独秀为代表的右倾机会主义的错误，主张放弃无产阶级的领导权，完全依赖于资产阶级。这种情况正是题干中毛泽东所说的“不是去做主人而只是做客人”。因此，选项A正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"第一次国共合作时期，共产党内右倾错误比较严重，并没有明显的“左”倾错误倾向，故不选。","C":"“共产国际不了解中国国情”说法正确，但这并不是题干中毛泽东所要表达的意思，故不选。","D":"武汉国民政府确实背叛了革命，但是题干中毛泽东表达的更多的是自我批评，而不是谴责国民党，故不选。"}}},{"id":"advanced-shigang-test4-9","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试四","chapterKey":"综合测试四","n":9,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试四 第 9 题"},"stem":"党在吸收大革命失败的教训后，先后发动了南昌起义、秋收起义和广州起义，中国革命由此发展到了一个新的阶段，即土地革命战争时期。较之党在大革命失败前进行的诸多斗争，之所以将这一时期称为“新的阶段”，是因为我们党","choices":[{"id":"A","text":"开始独立领导革命武装夺权"},{"id":"B","text":"首次发动了工农群众"},{"id":"C","text":"首次明确了民主革命的任务"},{"id":"D","text":"首次解决了敌友问题的区分"}],"answer":["A"],"analysis":{"point":"本题考查土地革命战争时期的开端。大革命失败后，1927年8月1日，南昌起义爆发，中国共产党打响了武装反抗国民党反动统治的第一枪。这是中国共产党独立领导革命战争、创建人民军队和武装夺取政权的开端。经过南昌起义、秋收起义和广州起义，中国革命由此发展到了一个新的阶段，即土地革命战争时期。因此，选项A正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"中国共产党成立后，党的工作重点在发展工人运动方面。从1922年1月香港海员罢工到1923年2月京汉铁路工人罢工，在中国共产党的领导、组织、推动下，中国掀起了第一个工人运动的高潮。与此同时，中国共产党也开始从事发动农民的工作。大革命时期，以湖南为中心，广大农村掀起了大革命的风暴，工人运动也迅速走向高涨。与题意不符，故不选。","C":"早在1922年召开的中共二大上，党就提出了反帝反封建的民主革命纲领，即“打倒军阀；推翻国际帝国主义的压迫；统一中国为真正民主共和国”，明确了民主革命的任务，故不选。","D":"早在大革命时期，毛泽东在《中国社会各阶级的分析》中就提出，分清敌友是革命的首要问题，当时就解决了敌友问题的区分，故不选。"}}},{"id":"advanced-shigang-test4-10","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试四","chapterKey":"综合测试四","n":10,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试四 第 10 题"},"stem":"在20世纪30年代前期、中期，中国共产党内屡次出现严重的“左”倾错误，其原因是多方面的，主要在于","choices":[{"id":"A","text":"共产国际对中国革命的错误指导"},{"id":"B","text":"中华苏维埃共和国实行工农兵代表大会制度"},{"id":"C","text":"党内一直存在着浓厚的“左”倾情绪始终没有得到认真清理"},{"id":"D","text":"党还不善于把马克思列宁主义与中国实际全面地、正确地结合起来"}],"answer":["D"],"analysis":{"point":"本题考查出现“左”倾错误的主要原因。中国共产党内屡次出现严重的“左”倾错误，主要在于党的马克思主义理论准备不足，缺乏实践经验，对中国的历史状况和社会状况、中国革命的特点、中国革命的规律不甚了解，不善于把马克思列宁主义与中国实际全面地、正确地结合起来。因此，选项D正确。","options":{"A":"属于党内屡次出现严重的“左”倾错误的原因，但不是主要原因。故不选。","B":"中华苏维埃共和国实行工农兵代表大会制度有利于工农群众行使当家作主的权利，与题意不符，故不选。","C":"属于党内屡次出现严重的“左”倾错误的原因，但不是主要原因。故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-shigang-test4-11","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试四","chapterKey":"综合测试四","n":11,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试四 第 11 题"},"stem":"1928年10月和11月，毛泽东写了《中国的红色政权为什么能够存在？》和《井冈山的斗争》两篇文章，明确地指出以农业为主要经济的中国革命，以军事发展暴动，是一种特征；同时还科学地阐述了共产党领导的土地革命、武装斗争与根据地建设这三者之间的辩证统一关系，强调","choices":[{"id":"A","text":"“须知政权是由枪杆子中取得的”"},{"id":"B","text":"工农武装割据的思想"},{"id":"C","text":"“没有调查，没有发言权”"},{"id":"D","text":"“农村工作是第一步，城市工作是第二步”"}],"answer":["B"],"analysis":{"point":"本题考查工农武装割据的思想。毛泽东在《中国的红色政权为什么能够存在？》和《井冈山的斗争》两篇文章中，明确地指出以农业为主要经济的中国革命，以军事发展暴动，是一种特征；还科学地阐述了共产党领导的土地革命、武装斗争与根据地建设这三者之间的辩证统一关系，强调工农武装割据的思想是共产党和割据地方的工农群众必须具备的一个重要思想。因此，选项B正确。","options":{"A":"在1927年8月7日召开的八七会议上，毛泽东强调党“以后要非常注意军事，须知政权是由枪杆子中取得的”，故不选。","B":"（正确选项，分析见“解题思路”）","C":"1930年5月，毛泽东在《反对本本主义》一文中，提出了“没有调查，没有发言权”，故不选。","D":"1930年，以毛泽东为书记的中共红四军前敌委员会明确提出了“农村工作是第一步，城市工作是第二步”的思想，故不选。"}}},{"id":"advanced-shigang-test4-12","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试四","chapterKey":"综合测试四","n":12,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试四 第 12 题"},"stem":"1936年12月12日，张学良、杨虎城发动“兵谏”，扣留了蒋介石。这就是震惊中外的西安事变。事变发生后，中共中央确定了促成事变和平解决的基本方针，其原因是中国共产党","choices":[{"id":"A","text":"不赞成张学良、杨虎城的主张"},{"id":"B","text":"为了团结国民党共同抗日"},{"id":"C","text":"工作重心转向城市斗争"},{"id":"D","text":"接受了共产国际的指示"}],"answer":["B"],"analysis":{"point":"本题考查西安事变。中共中央力促西安事变和平解决是为了团结国民党蒋介石共同抗日，结成更广泛的抗日民族统一战线。因此，选项B正确。","options":{"A":"笼统地说中国共产党不赞成张学良、杨虎城的主张是不对的，至少在“逼蒋抗日”这一点上二者是有共识的，故排除。","B":"（正确选项，分析见“解题思路”）","C":"“工作重心转向城市斗争”是在中华人民共和国成立前夕召开的中共七届二中全会的主要决定，与本题的抗日战争时期不符，故排除。","D":"1936年12月13日，中共中央政治局常委会召开扩大会议，讨论如何认识和应对刚刚发生的西安事变。会前，并未收到共产国际的“复电”，因此，说中国共产党对待西安事变的态度形成的原因是接受了共产国际的指示是不正确的。并且，西安事变共产国际的态度与中共中央的主张表面上相近，但是在根本出发点和指导思想上是不同的，故排除。"}}},{"id":"advanced-shigang-test4-13","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试四","chapterKey":"综合测试四","n":13,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试四 第 13 题"},"stem":"毛泽东在《论持久战》中，科学地预见到抗日战争将经过战略防御、战略相持、战略反攻三个阶段。其中，战略相持阶段的时间将相当长，遇到的困难也将最多，然而它是整个战争转变的枢纽。在战略相持阶段","choices":[{"id":"A","text":"敌后游击战争成为主要的抗日作战方式"},{"id":"B","text":"国民党正面战场的正规战是主要的"},{"id":"C","text":"游击战只是一个战术选择问题"},{"id":"D","text":"运动战上升到战略位置"}],"answer":["A"],"analysis":{"point":"本题考查游击战争的战略地位和作用，属于理解与识记相结合的试题。在全民族抗战中，游击战被提到战略地位，具有全局性意义。在战略防御阶段，从全局看，国民党正面战场的正规战是主要的，敌后游击战是辅助的。但是，游击战在敌后的广泛开展和敌后抗日根据地的开辟，迫使敌人不得不把用于进攻的兵力抽调回来保守其占领区，从而对阻止日军进攻、减轻正面战场压力、使战争转入相持阶段起了关键性作用。在战略相持阶段，敌后游击战争成为主要的抗日作战方式。日军逐步将主要兵力用于打击敌后战场的人民军队，以保持和巩固其占领地。1939年至1940年，仅华北地区的日军出动千人以上对敌后抗日根据地的大“扫荡”就有109次，使用总兵力50万人以上。为打击日本侵略者，人民军队在有利条件下也进行过运动战，如1940年8月至翌年1月，八路军总部在华北发动了一次大规模的对日军的进攻，陆续参战部队达105个团20余万人，史称百团大战。但是，人民军队在大部分时间里所进行的主要是游击战。削弱敌人、壮大自己，逐步改变敌强我弱态势，为实行战略反攻准备条件，这个任务主要是由人民军队进行的游击战来完成的。因此，选项A正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"在战略防御阶段，国民党正面战场的正规战是主要的。","C":"表述错误，在战略相持阶段，游击战被提到战略地位，不是战术选择问题。","D":"在战略相持阶段，游击战被提到战略地位，而不是运动战。"}}},{"id":"advanced-shigang-test4-14","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试四","chapterKey":"综合测试四","n":14,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试四 第 14 题"},"stem":"1949年6月30日，毛泽东发表了《论人民民主专政》一文。文中指出，历史的经验表明，资产阶级共和国的方案在中国是行不通的。总结我们的经验，集中到一点，就是","choices":[{"id":"A","text":"民族资产阶级应当在国家政权中占主要地位"},{"id":"B","text":"调动一切积极因素为社会主义事业服务"},{"id":"C","text":"工人阶级（经过共产党）领导的以工农联盟为基础的人民民主专政"},{"id":"D","text":"利用一切于国计民生有利而不是有害的城乡资本主义因素"}],"answer":["C"],"analysis":{"point":"本题考查《论人民民主专政》的内容。1949年，毛泽东发表《论人民民主专政》一文，明确指出，总结我们的经验，集中到一点，就是工人阶级（经过共产党）领导的以工农联盟为基础的人民民主专政。因此，选项C正确。","options":{"A":"表述错误，应该是“民族资产阶级不应当在国家政权中占主要地位”，故不选。","B":"是1956年毛泽东在《论十大关系》中提出的一个基本方针，故不选。","C":"（正确选项，分析见“解题思路”）","D":"是《论人民民主专政》中提到的具体做法，而不是集中到一点的经验，故不选。"}}},{"id":"advanced-shigang-test4-15","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试四","chapterKey":"综合测试四","n":15,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试四 第 15 题"},"stem":"1954年9月15日至28日，第一届全国人民代表大会第一次会议在北京召开，审议通过了《中华人民共和国宪法》，标志着","choices":[{"id":"A","text":"我国开始进入社会主义初级阶段"},{"id":"B","text":"我国开始进入新民主主义社会"},{"id":"C","text":"中国特色新型政党制度正式确立"},{"id":"D","text":"人民代表大会制度正式建立"}],"answer":["D"],"analysis":{"point":"本题考查人民代表大会制度正式建立的标志。1954年9月，第一届全国人民代表大会第一次会议审议通过了《中华人民共和国宪法》，标志着人民代表大会制度这一国家根本政治制度正式建立。因此，选项D正确。","options":{"A":"随着社会主义改造的完成，以生产资料公有制、按劳分配和计划经济体制为特征的社会主义经济制度建立起来，这是中国进入社会主义社会最主要的标志。","B":"我国进入新民主主义社会的标志是新中国的成立。","C":"中国人民政治协商会议第一届全体会议的召开，标志着新型政党制度正式确立。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-shigang-test4-16","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试四","chapterKey":"综合测试四","n":16,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试四 第 16 题"},"stem":"李大钊在评价义和团运动时曾指出：“时至近日，吾人所当努力者，惟在如何吸取西洋文明之长，以济吾东洋文明之穷。断不许以义和团的思想，欲以吾陈死寂灭之气象腐化世界。”李大钊所说的“陈死寂灭之气象”主要是指义和团运动","choices":[{"id":"A","text":"不懂得发动广大群众"},{"id":"B","text":"存在着笼统的排外主义的错误"},{"id":"C","text":"存在着许多迷信、落后的倾向"},{"id":"D","text":"粉碎了列强瓜分中国的图谋"}],"answer":["B","C"],"analysis":{"point":"本题考查义和团运动的局限性。其局限性表现在：由于当时中国人民对帝国主义的认识还停留在感性认识阶段，义和团运动存在着笼统的排外主义的错误；由于还没有认识到帝国主义联合中国封建地主阶级压迫中国人民的实质，义和团曾经蒙受封建统治者的欺骗；由于小生产者的局限性，义和团运动中还存在着许多迷信、落后的倾向。因此，选项B、C正确。","options":{"A":"表述错误，义和团运动由贫苦农民、手工业者、城市贫民、小商贩等群众组成，故不选。","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"是义和团运动的进步性，与题意不符，故不选。"}}},{"id":"advanced-shigang-test4-17","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试四","chapterKey":"综合测试四","n":17,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试四 第 17 题"},"stem":"魏源在其所著的《海国图志》一书中提出了“师夷长技以制夷”的思想，19世纪60年代开始的洋务运动则提出了“自强”“求富”的口号。二者的相同点包括","choices":[{"id":"A","text":"有内在的一致性和继承性"},{"id":"B","text":"都有抵御外来侵略的意图"},{"id":"C","text":"主要体现了地主阶级的要求"},{"id":"D","text":"意识到了中国落后挨打的根本原因"}],"answer":["A","B","C"],"analysis":{"point":"本题考查对中国出路的早期探索。秉持“师夷长技以制夷”思想的是林则徐、魏源等人，他们是鸦片战争后第一批地主阶级的代表人物；提出“自强”“求富”主张的是以李鸿章为代表的洋务派领袖们，他们也是地主阶级的代表人物。所以，他们的主张有内在的一致性和继承性，而且都有抵御外来侵略的意图。因此，选项A、B、C正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"表述错误，中国落后挨打的根本原因是社会制度的腐败。无论是魏源等人，还是洋务派，他们都只强调学习西方的技术，而没有意识到改变封建专制制度的重要性。因此，不能说他们意识到了中国落后挨打的根本原因。故不选。"}}},{"id":"advanced-shigang-test4-18","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试四","chapterKey":"综合测试四","n":18,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试四 第 18 题"},"stem":"维新派的变法活动遭到了封建守旧派和反对改变封建制度的洋务派的抵制。他们利用自己的地位和权力，对维新思想发起攻击，于是维新派与守旧派之间展开了一场激烈论战。这场论战","choices":[{"id":"A","text":"进一步开阔了新型知识分子的眼界"},{"id":"B","text":"使民主共和的观念开始深入人心"},{"id":"C","text":"划清了革命与改良的界限"},{"id":"D","text":"使西方资产阶级社会政治学说在中国得到进一步传播"}],"answer":["A","D"],"analysis":{"point":"本题考查维新派与守旧派的论战。维新派与守旧派的论战涉及的领域十分广泛，进一步开阔了新型知识分子的眼界，解放了人们长期受到束缚的思想。通过论战，西方资产阶级社会政治学说在中国得到进一步传播，戊戌维新运动的帷幕随之拉开。因此，选项A、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"是辛亥革命的历史意义，与题意不符，故不选。","C":"是革命派与改良派论战的意义，与题意不符，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-shigang-test4-19","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试四","chapterKey":"综合测试四","n":19,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试四 第 19 题"},"stem":"南京临时政府的资产阶级共和国性质体现在","choices":[{"id":"A","text":"从政权组成人员看，资产阶级革命派在这个政权中占有领导地位和主体地位"},{"id":"B","text":"从制定的政策看，各项政策措施集中代表和反映了中国民族资产阶级的愿望和利益"},{"id":"C","text":"从革命彻底性看，没有旧官僚参与政权"},{"id":"D","text":"从对外关系看，对帝国主义的不妥协性"}],"answer":["A","B"],"analysis":{"point":"本题考查南京临时政府的性质。南京临时政府具有一定的资产阶级共和国性质，从政权组成人员看，资产阶级革命派在这个政权中占有领导地位和主体地位；从制定的政策看，各项政策措施集中代表和反映了中国民族资产阶级的愿望和利益。因此，选项A、B正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"表述过于绝对，南方多数省区独立是由原来的旧官僚推动的，这些旧官僚后来就成了新政府的参与者，故不选。","D":"说法错误，事实上，孙中山为了获取帝国主义对革命政权的支持，对帝国主义采取妥协的态度，甚至向很多国家许诺过利益，故不选。"}}},{"id":"advanced-shigang-test4-20","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试四","chapterKey":"综合测试四","n":20,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试四 第 20 题"},"stem":"五四运动是中国新民主主义革命的开端，对后来中国历史的发展产生了深远的影响，下列关于五四运动的叙述，正确的有","choices":[{"id":"A","text":"五四运动是一场以先进青年知识分子为先锋、广大人民群众参加的彻底反帝反封建的伟大爱国革命运动"},{"id":"B","text":"五四运动是一场中国人民为拯救民族危亡、捍卫民族尊严、凝聚民族力量而掀起的伟大社会革命运动"},{"id":"C","text":"五四运动是一场传播新思想新文化新知识的伟大思想启蒙运动和新文化运动"},{"id":"D","text":"五四运动是一场以武装斗争为主要形式的伟大革命运动"}],"answer":["A","B","C"],"analysis":{"point":"本题考查五四运动的意义。五四运动是一场以先进青年知识分子为先锋、广大人民群众参加的彻底反帝反封建的伟大爱国革命运动，是一场中国人民为拯救民族危亡、捍卫民族尊严、凝聚民族力量而掀起的伟大社会革命运动，是一场传播新思想新文化新知识的伟大思想启蒙运动和新文化运动，以磅礴之力鼓动了中国人民和中华民族实现民族复兴的志向和信心。因此，选项A、B、C正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"五四运动是一场以和平抗争为主要形式的伟大革命运动。"}}},{"id":"advanced-shigang-test4-21","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试四","chapterKey":"综合测试四","n":21,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试四 第 21 题"},"stem":"毛泽东在《论人民民主专政》一文中指出：“十月革命一声炮响，给中国送来了马克思列宁主义。”这是说","choices":[{"id":"A","text":"十月革命以后，马克思主义才开始在中国传播"},{"id":"B","text":"十月革命给予中国人一个启示，即经济文化落后的国家也可以用社会主义思想指引自己走向解放之路"},{"id":"C","text":"十月革命推动中国的先进分子把自己的目光从西方转向东方，从资产阶级民主主义转向社会主义"},{"id":"D","text":"资本主义制度并不是永恒的，无产阶级和其他劳动群众完全可以依靠自身的力量创造出维护绝大多数人利益的崭新的社会制度"}],"answer":["B","C","D"],"analysis":{"point":"本题考查十月革命对中国的影响。1917年俄国爆发的十月革命是一个具有划时代意义的世界性的历史事件。它推动中国的先进分子把目光从西方转向东方，从资产阶级民主主义转向社会主义。它昭示着资本主义制度并不是永恒的，无产阶级和其他劳动群众一旦觉醒、组织起来，完全可以依靠自身的力量创造出维护绝大多数人利益的崭新的社会制度，经济文化落后的国家也可以用社会主义思想指引自己走向解放之路。因此，选项B、C、D正确。","options":{"A":"马克思主义自19世纪末传入中国，20世纪初得到传播，在五四运动后，得到进一步广泛传播，并不是“十月革命以后，马克思主义才开始在中国传播”。不符合史实，故不选。","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-shigang-test4-22","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试四","chapterKey":"综合测试四","n":22,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试四 第 22 题"},"stem":"1930年5月，为反对当时中国工农红军中的教条主义思想，毛泽东撰写了重要著作《反对本本主义》。这是毛泽东最早的一篇马克思主义哲学著作。在这篇著作中，他提出了","choices":[{"id":"A","text":"“没有调查，没有发言权”"},{"id":"B","text":"工农武装割据的思想"},{"id":"C","text":"“中国革命斗争的胜利要靠中国同志了解中国情况”"},{"id":"D","text":"“须知政权是由枪杆子中取得的”"}],"answer":["A","C"],"analysis":{"point":"本题考查《反对本本主义》。1930年5月，毛泽东在《反对本本主义》一文中，阐明了坚持辩证唯物主义的思想路线，即坚持理论与实际相结合原则的极端重要性，提出了“没有调查，没有发言权”和“中国革命斗争的胜利要靠中国同志了解中国情况”的重要思想，表现出毛泽东开辟新道路、创造新理论的革命首创精神。因此，选项A、C正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"1928年10月和11月，毛泽东撰写了《中国的红色政权为什么能够存在？》和《井冈山的斗争》两篇文章，论证了红色政权能够长期存在并发展的主客观条件，提出了工农武装割据的思想，故不选。","C":"（正确选项，分析见“解题思路”）","D":"毛泽东在八七会议上着重阐述了党必须依靠农民和掌握枪杆子的思想，强调党“以后要非常注意军事，须知政权是由枪杆子中取得的”，故不选。"}}},{"id":"advanced-shigang-test4-23","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试四","chapterKey":"综合测试四","n":23,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试四 第 23 题"},"stem":"“暴动，打倒国民政府！”“暴动，杀土豪劣绅！”“暴动，组织革命委员会！”“暴动，农民夺取土地！”暴动的口号山鸣谷应，起义的烽火势欲燎原，迅速席卷了湘东赣西的广阔原野。相较于南昌起义，1927年湘赣边界秋收起义的特点有","choices":[{"id":"A","text":"不再由国共两党合作领导，而是由共产党独立领导"},{"id":"B","text":"不再用国民革命军的名义，而是公开打出了“工农革命军”的旗帜"},{"id":"C","text":"不以攻打中心城市为目标，而以建立农村根据地为目标"},{"id":"D","text":"不仅是军队的行动，而且有数量众多的工农武装参加"}],"answer":["B","D"],"analysis":{"point":"本题考查湘赣边界秋收起义。秋收起义与南昌起义相比，最明显的特点在于：①它不仅是军队的行动，而且有数量众多的工农武装参加。②它第一次公开打出了“工农革命军”的旗帜。③这次起义虽然在开始时也是以攻占大城市为目标，但在起义遭到严重挫折后，及时从进攻大城市转移向农村进军，这是人民革命史中具有决定意义的新起点。起义部队在农村中从小到大地开展游击战争，为后来各地工农红军和农村革命根据地的大规模发展奠定了基础。秋收起义和井冈山道路，是毛泽东农村包围城市思想的起点。④三湾改编，把党的支部建在连上，铸就了人民军队的灵魂——永远听从党的指挥。因此，选项B、D正确。","options":{"A":"是秋收起义与南昌起义的相同点，是与北伐战争的区别，故不选。","B":"（正确选项，分析见“解题思路”）","C":"表述错误，秋收起义的进攻方向是长沙，同南昌起义一样，都是在中心城市的暴动。在起义遭遇挫折后，部队才决定南下，向敌人控制比较薄弱的农村区域转移。故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-shigang-test4-24","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试四","chapterKey":"综合测试四","n":24,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试四 第 24 题"},"stem":"中国的持久抗战，对日本侵略者的彻底覆灭起到了决定性作用，有力配合、支援了欧洲战场和太平洋战场作战。在抗战烽火的洗礼下，中国共产党迅速走向成熟壮大，一次次挽狂澜于既倒，对抗战的最终胜利起到了中流砥柱、不可替代的作用，成为引领民族复兴的核心力量。下列关于抗日战争的表述正确的有","choices":[{"id":"A","text":"在战略相持阶段，敌后游击战争成为主要的抗日作战方式"},{"id":"B","text":"文化建设与干部教育成为抗日根据地建设的首要的、根本的任务"},{"id":"C","text":"抗日民族统一战线的巩固、发展和壮大，是夺取抗日战争最后胜利的根本保证"},{"id":"D","text":"在抗战情况下，民族斗争高于阶级斗争"}],"answer":["A","C","D"],"analysis":{"point":"本题考查抗日战争的基本内容。在全民族抗战中，游击战被提到战略地位，具有全局性意义。在战略相持阶段，敌后游击战争成为主要的抗日作战方式。1937年9月，以第二次国共合作为基础的抗日民族统一战线建立起来。抗日民族统一战线的巩固、发展和壮大，是夺取抗日战争最后胜利的根本保证。在抗战情况下，全国人民同仇敌忾，民族斗争高于阶级斗争。因此，选项A、C、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"加强政权建设，是抗日根据地建设的首要的、根本的任务，故不选。","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-shigang-test4-25","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试四","chapterKey":"综合测试四","n":25,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试四 第 25 题"},"stem":"毛泽东同志曾指出：“我们在十年内战时期的土地政策，到抗日战争时期必须改变，否则就不能缓和国内矛盾和根据地内部的矛盾，发展中国人民自己的力量，共同打日本。”这是因为抗战时期的土地政策","choices":[{"id":"A","text":"有利于争取地主阶级的大多数参加抗日民族统一战线"},{"id":"B","text":"可以适当调节和照顾各抗日阶层的利益"},{"id":"C","text":"彻底解决了农村土地剥削问题"},{"id":"D","text":"能够调动广大农民的抗日积极性"}],"answer":["A","B","D"],"analysis":{"point":"本题考查中国共产党在抗日战争时期的土地政策。减租减息是中国共产党在抗日根据地为适当调节各抗日阶层的利益而实行的土地政策。一方面，地主要减租减息以改善农民的生活；另一方面，农民要交租交息以照顾地主富农的利益。实行这个政策既调动了广大农民的抗日积极性，又有利于争取地主阶级的大多数站在抗日民族统一战线一边。因此，选项A、B、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"说法错误，减租减息政策是允许地主拥有土地的，并未变革农村土地剥削关系，彻底解决农村土地剥削问题是在解放战争时期和中华人民共和国成立初期的土地改革中。故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-shigang-test4-26","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试四","chapterKey":"综合测试四","n":26,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试四 第 26 题"},"stem":"从1921年中国共产党诞生至1949年中华人民共和国成立的这一时期，中国主要存在着三种政治力量，他们分别提出了三种不同的建国方案，但实际上中国人民可选择的方案只有两种，即大地主、大资产阶级的军事独裁统治和人民共和国，而资产阶级共和国方案在中国行不通，其原因在于","choices":[{"id":"A","text":"从民族资产阶级自身来看，民族资本主义经济实力弱，民族资产阶级具有“两面性”"},{"id":"B","text":"从当时的时代条件来看，帝国主义列强不允许中国成为一个独立、富强的资本主义国家"},{"id":"C","text":"从中国的革命形势来看，国民党当局一直阻挠"},{"id":"D","text":"从帝国主义之间的关系来看，帝国主义之间矛盾复杂"}],"answer":["A","B","C"],"analysis":{"point":"本题考查资产阶级共和国方案在中国行不通的原因。资产阶级共和国方案在中国行不通的原因：首先，从民族资产阶级自身来看，民族资本主义经济的特点决定了民族资产阶级没有勇气和能力领导人民进行反帝反封建的革命斗争，不能为资产阶级共和国扫清障碍。其次，从当时的时代条件来看，帝国主义列强不可能使中国成为一个独立、富强的资本主义国家。最后，从中国的革命形势来看，国民党当局不允许任何阻止其一党专政的力量存在。因此，选项A、B、C正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"与题干无关，故不选。"}}},{"id":"advanced-shigang-test4-27","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试四","chapterKey":"综合测试四","n":27,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试四 第 27 题"},"stem":"1949年1月22日，应中共中央的号召，李济深、沈钧儒等民主党派的领导人和著名的无党派民主人士55人联合发表《对时局的意见》，一致认定中国共产党提出的关于召开政治协商会议、成立联合政府的主张“符合于全国人民大众的要求”。同年春，毛泽东提出民主党派应“积极参政，共同建设新中国”。这表明","choices":[{"id":"A","text":"中国各民主党派和无党派民主人士自愿接受中国共产党的领导"},{"id":"B","text":"各民主党派的政纲与中国共产党的新民主主义革命纲领基本上一致"},{"id":"C","text":"民主党派的地位发生根本的变化"},{"id":"D","text":"民主党派将和共产党一道担负起管理国家和建设国家的历史重任"}],"answer":["A","C","D"],"analysis":{"point":"本题考查中国共产党领导的多党合作、政治协商格局的形成。《对时局的意见》的发表表明了中国各民主党派和无党派民主人士自愿接受中国共产党的领导，决心走人民革命的道路，拥护建立人民民主的新中国。选项A正确。民主党派参加新政协并将在新中国参政，标志着民主党派地位的根本变化。它们不再是旧中国反动政权下的在野党，而成为中国人民民主专政的参加者，在中国共产党的领导下，民主党派将和共产党一道担负起管理国家和建设国家的历史重任。选项C、D正确。因此，选项A、C、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"表述正确，但与题意不符，本题问的是民主党派和共产党“共同建设新中国”表明了什么，并不是问为什么在革命年代能合作，故不选。","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-shigang-test4-28","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试四","chapterKey":"综合测试四","n":28,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试四 第 28 题"},"stem":"1956年中共八大前后，毛泽东在探索中国自己的社会主义建设道路中提出的重要思想有","choices":[{"id":"A","text":"“两个务必”重要思想"},{"id":"B","text":"把国内外一切积极因素调动起来，为社会主义事业服务"},{"id":"C","text":"中国共产党同各民主党派长期共存、互相监督"},{"id":"D","text":"正确区分和处理两类不同性质的矛盾"}],"answer":["B","C","D"],"analysis":{"point":"本题考查毛泽东在探索社会主义建设道路中的思想成果。1956年9月召开的中共八大提出，生产资料私有制的社会主义改造基本完成以后，国内的主要矛盾不再是工人阶级和资产阶级之间的矛盾，而是人民对于建立先进的工业国的要求同落后的农业国的现实之间的矛盾，是人民对于经济文化迅速发展的需要同当前经济文化不能满足人民需要的状况之间的矛盾。这一矛盾的实质，在中国社会主义制度已经建立的情况下，也就是先进的社会主义制度同落后的社会生产之间的矛盾。解决这个矛盾的办法是发展社会生产力，实行大规模的经济建设。为此，大会作出了党和国家的工作重点必须转移到社会主义建设上来的重大战略决策。大会在总结中国第一个五年计划实施经验的基础上，继续坚持既反保守又反冒进，即在综合平衡中稳步前进的经济建设方针。此外，大会还提出中国共产党同各民主党派长期共存、互相监督，要调动国内外一切积极因素为社会主义事业服务，反对个人崇拜等方针。因此，选项B、C、D正确。","options":{"A":"“两个务必”重要思想是在中华人民共和国成立前夕提出的，本题限定中共八大前后，即1956年前后，故不选。","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-shigang-test4-29","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试四","chapterKey":"综合测试四","n":29,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试四 第 29 题"},"stem":"从开始全面建设社会主义到1976年，中国尽管经历过严重的曲折，但从总体上说，社会主义建设取得的成就是巨大的。其中，建立起独立的、比较完整的工业体系和国民经济体系是中国经济发展的重要里程碑。其重要意义有","choices":[{"id":"A","text":"使中国在赢得政治上的独立后赢得了经济上的独立"},{"id":"B","text":"从根本上解决了工业化中“从无到有”的问题"},{"id":"C","text":"为中国以后的发展奠定了牢固的物质技术基础"},{"id":"D","text":"为中国在平等互利的原则下发展对外贸易和经济往来创建了前提"}],"answer":["A","B","C","D"],"analysis":{"point":"本题考查全面建设社会主义时期的成就。独立的、比较完整的工业体系和国民经济体系的建立，从根本上解决了工业化中“从无到有”的问题，使中国在赢得政治上的独立后赢得了经济上的独立，为中国以后的发展奠定了牢固的物质技术基础，而且为中国同包括西方发达国家在内的世界各国在平等互利的原则下发展对外贸易和经济往来创建了前提。因此，选项A、B、C、D正确。\\n无干扰选项。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-shigang-test4-30","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试四","chapterKey":"综合测试四","n":30,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试四 第 30 题"},"stem":"1992年年初，在关乎中国改革开放和社会主义现代化建设前途命运的关键时刻，邓小平在视察武昌、深圳、珠海、上海等地时，发表了重要谈话。谈话的主要内容有","choices":[{"id":"A","text":"计划多一点还是市场多一点，不是社会主义与资本主义的本质区别"},{"id":"B","text":"不坚持社会主义，不改革开放，不发展经济，不改善人民生活，只能是死路一条"},{"id":"C","text":"走社会主义道路，就是要逐步实现共同富裕"},{"id":"D","text":"革命是解放生产力，改革也是解放生产力"}],"answer":["A","B","C","D"],"analysis":{"point":"本题考查邓小平南方谈话。四个选项的表述均是邓小平南方谈话的内容。因此，选项A、B、C、D正确。\\n无干扰选项。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-shigang-test5-1","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试五","chapterKey":"综合测试五","n":1,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试五 第 1 题"},"stem":"1843年，魏源编成《海国图志》。他在书中写道：“是书何以作？曰：为以夷攻夷而作，为以夷款夷而作，为师夷长技以制夷而作。”魏源所说的夷之“长技”主要是指西方的","choices":[{"id":"A","text":"宗教和思想文化"},{"id":"B","text":"教育和人才培养"},{"id":"C","text":"军事和科学技术"},{"id":"D","text":"民主和政治制度"}],"answer":["C"],"analysis":{"point":"本题考查师夷长技以制夷。魏源的观点是中国应学习西方的先进军事和科学技术，反制西方。因此，选项C正确。","options":{"A":"早期封建阶级改良派并不主张学习西方的思想文化，到新文化运动时期才主张学习西方的思想文化。","B":"属于“长技”的相关内容，但并非主要内容。","C":"（正确选项，分析见“解题思路”）","D":"属于制度层面，封建阶级本身并不主张学习西方制度。"}}},{"id":"advanced-shigang-test5-2","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试五","chapterKey":"综合测试五","n":2,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试五 第 2 题"},"stem":"洋务派继承了魏源“师夷长技以制夷”的思想，提出“自强”“求富”的主张，通过所掌握的国家权力，集中力量优先发展军事工业，同时也试图“稍分洋商之利”，发展若干民用企业。这在客观上","choices":[{"id":"A","text":"否定了封建社会的基础即封建土地所有制"},{"id":"B","text":"是一场资产阶级性质的政治改良运动"},{"id":"C","text":"给予中国的先进分子以新的革命方法的启示"},{"id":"D","text":"对中国的早期工业和民族资本主义的发展起了某些促进作用"}],"answer":["D"],"analysis":{"point":"本题考查洋务运动。洋务运动在客观上对中国的早期工业和民族资本主义的发展起了某些促进作用。因此，选项D正确。","options":{"A":"《天朝田亩制度》从根本上否定了封建社会的基础即封建土地所有制，故不选。","B":"戊戌维新运动是一场资产阶级性质的政治改良运动，故不选。","C":"十月革命中俄国工人、农民和士兵群众的广泛发动并由此赢得胜利的事实，给予中国的先进分子以新的革命方法的启示，推动他们去研究这个革命所遵循的主义，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-shigang-test5-3","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试五","chapterKey":"综合测试五","n":3,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试五 第 3 题"},"stem":"《中华文明史》写道：“作为一场政治运动，百日维新短命而败，但作为一场更广阔意义上的社会文化运动，自有其成功之处。”戊戌维新运动的成功之处在于","choices":[{"id":"A","text":"改变了封建君主专制体制"},{"id":"B","text":"是一场广泛的群众运动"},{"id":"C","text":"在社会上起到了思想启蒙的作用"},{"id":"D","text":"阻止了民族危机的加深"}],"answer":["C"],"analysis":{"point":"本题考查戊戌维新运动。维新派突破洋务派“中体西用”思想的局限，主张改革君主专制制度。他们鼓吹民权并提出设议院的主张，也就是要用君主立宪制取代君主专制制度。虽然戊戌维新运动未能成功地建立起资本主义的君主立宪制度，但其更是一场思想启蒙运动。在戊戌维新运动期间，维新派大力传播西方资产阶级的社会政治学说和自然科学知识，宣传自由平等、社会进化观念，批判封建君权和封建纲常伦理，从而把顽固的封建主义思想壁垒打开了一个缺口，有利于民主思想在中国的传播，有利于人们的思想解放。因此，选项C正确。","options":{"A":"表述错误，戊戌维新运动未能改变封建君主专制体制，故不选。","B":"表述错误，戊戌维新运动没有广泛地发动群众，故不选。","C":"（正确选项，分析见“解题思路”）","D":"表述错误，戊戌维新运动并未阻止民族危机的加深，也没有改变近代中国衰败的历史进程，故不选。"}}},{"id":"advanced-shigang-test5-4","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试五","chapterKey":"综合测试五","n":4,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试五 第 4 题"},"stem":"1914年至1918年的第一次世界大战，是一场空前残酷的大屠杀。它改变了世界政治的格局，也改变了各帝国主义国家在中国的利益格局，对中国产生了巨大的影响。大战使中国的先进分子","choices":[{"id":"A","text":"对中国传统文化产生怀疑"},{"id":"B","text":"对西方资产阶级民主主义产生怀疑"},{"id":"C","text":"认识到工人阶级的重要作用"},{"id":"D","text":"认识到必须优先改造国民性"}],"answer":["B"],"analysis":{"point":"本题考查第一次世界大战对中国的影响。第一次世界大战期间，西方列强为了争夺利益彼此兵戎相见，暴露了西方民主制度的虚伪，中国的先进分子对西方资产阶级民主主义产生了怀疑。因此，选项B正确。","options":{"A":"第一次世界大战的爆发同中国知识分子对中国传统文化的怀疑并无直接关联。故不选。","B":"（正确选项，分析见“解题思路”）","C":"中国的先进分子认识到工人阶级的重要作用是在五四运动后。故不选。","D":"必须优先改造国民性是新文化运动初期中国知识分子的共识，主要针对的是北洋政府尊孔复古的政策，同第一次世界大战的爆发无直接关联。故不选。"}}},{"id":"advanced-shigang-test5-5","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试五","chapterKey":"综合测试五","n":5,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试五 第 5 题"},"stem":"1915年9月，陈独秀在上海创办《青年杂志》（后改名《新青年》），吹响了新文化运动的号角。新文化运动的倡导者以进化论观点和个性解放思想为主要武器，通过批判孔学，动摇了封建正统思想的统治地位，在中国社会掀起一股思想解放的潮流。早期新文化运动的倡导者批判孔学是为了","choices":[{"id":"A","text":"给中国发展资本主义扫清障碍"},{"id":"B","text":"宣传新民主主义思想"},{"id":"C","text":"传播社会主义思想"},{"id":"D","text":"传播马克思主义思想"}],"answer":["A"],"analysis":{"point":"本题考查新文化运动。五四运动以前的新文化运动具有局限性，虽然新文化运动的倡导者批判孔学，但主要是为了给中国发展资本主义扫清障碍。因此，选项A正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"1939年12月，毛泽东在《中国革命和中国共产党》一文中，第一次提出了“新民主主义革命”的科学概念。在此之前，没有“新民主主义”这一概念，新文化运动的倡导者批判孔学并不是为了宣传新民主主义思想。故不选。","C":"1917年11月的十月革命推动了中国先进分子把目光从西方转向东方，从资产阶级民主主义转向社会主义。在此之前，新文化运动的倡导者批判孔学并不是为了传播社会主义思想。故不选。","D":"1919年9月、11月，李大钊发表《我的马克思主义观》一文，比较系统地介绍了马克思主义理论，标志着马克思主义在中国进入比较系统的传播阶段。在此之前，新文化运动的倡导者批判孔学并不是为了传播马克思主义思想。故不选。"}}},{"id":"advanced-shigang-test5-6","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试五","chapterKey":"综合测试五","n":6,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试五 第 6 题"},"stem":"宋庆龄说：“孙中山与中国共产党之间具有历史意义的合作不是偶然的，它是当时的国际局势和中国本身的内部条件造成的。”其“内部条件”是指","choices":[{"id":"A","text":"第一次世界大战后，中国民族工业重新受到列强压制"},{"id":"B","text":"“打倒列强，除军阀”成为全国人民的共同愿望"},{"id":"C","text":"中国共产党总结了经验教训，正在积极寻找同盟者"},{"id":"D","text":"国民党是比较革命的民主派"}],"answer":["B"],"analysis":{"point":"本题考查第一次国共合作。从题干中可以看出，宋庆龄所说的“合作”是指孙中山与中国共产党的合作，即第一次国共合作。而“内部条件”是相对于“国际局势”而言的国内形势。当时中国国内的形势是，第一次世界大战结束后，帝国主义势力卷土重来，国内各派军阀之间的纷争也进一步扩大，社会矛盾日益加深，人民生活更趋恶化，“打倒列强，除军阀”成为全国人民的共同愿望。因此，选项B正确。","options":{"A":"第一次世界大战以后，列强对中国民族工业进行压制，这属于外部力量对中国的影响，本题说的是“内部条件”，与题意不符，故不选。","B":"（正确选项，分析见“解题思路”）","C":"表述的是国共两党的具体情况，但本题说的是“内部条件”，与题意不符，故不选。","D":"表述的是国共两党的具体情况，但本题说的是“内部条件”，与题意不符，故不选。"}}},{"id":"advanced-shigang-test5-7","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试五","chapterKey":"综合测试五","n":7,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试五 第 7 题"},"stem":"大革命失败后，在一片白色恐怖中、血雨腥风下，党员数量从近六万名锐减至一万余名。在南昌起义、秋收起义和广州起义均遭到失败，秋收起义军余部不足千人的情况下，井冈山斗争毅然展开。在大革命失败、白色恐怖极其严重的条件下，中国革命之所以能够得到坚持和发展，根本原因就在于中国共产党","choices":[{"id":"A","text":"将准备城市工人的总同盟罢工作为党最主要的任务"},{"id":"B","text":"提出了坚决打击富农和“地主不分田，富农分坏田”的主张"},{"id":"C","text":"将民族资产阶级视为中国革命最危险的敌人"},{"id":"D","text":"紧紧地依靠农民，领导农民进行了土地制度的革命"}],"answer":["D"],"analysis":{"point":"本题考查土地革命。在大革命失败、白色恐怖极其严重的条件下，中国革命之所以能够得到坚持和发展，根本原因就在于中国共产党紧紧地依靠农民，领导农民进行了土地制度的革命。因此，选项D正确。","options":{"A":"均属于土地革命战争时期“左”倾错误的表现，故不选。","B":"均属于土地革命战争时期“左”倾错误的表现，故不选。","C":"均属于土地革命战争时期“左”倾错误的表现，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-shigang-test5-8","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试五","chapterKey":"综合测试五","n":8,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试五 第 8 题"},"stem":"毛泽东曾经指出：“三次‘左’倾路线，都是在十年内战时期产生的……第三次是王明路线，时间最长，统治全党达四年之久。这条路线是共产国际制造的。当时，王明发展了李立三的错误，在军事、政治、组织等一系列问题上，坚持错误的冒险主义，结果把南方根据地丢掉了，只好两条腿走路。一万二千五百公里的长征是光荣的，但实际上是由于犯了路线错误，被敌人追赶得不得不走的。”中国共产党当时犯“路线错误”最主要的原因是","choices":[{"id":"A","text":"八七会议以后党内一直存在着浓厚的“左”倾情绪始终没有得到认真清理"},{"id":"B","text":"共产国际对中国共产党内部事务的错误干预和瞎指挥"},{"id":"C","text":"当时党的马克思主义中国化的水平还不高"},{"id":"D","text":"王明等人破坏党的民主集中制、压制党内民主，大搞宗派主义"}],"answer":["C"],"analysis":{"point":"本题考查中国共产党内反复出现“左”倾错误的原因。中国共产党犯“路线错误”的原因是多方面的，除八七会议以后党内一直存在着浓厚的“左”倾情绪始终没有得到认真清理，共产国际对中国共产党内部事务的错误干预和瞎指挥以外，最主要的原因在于，全党的马克思主义理论准备不足，理论素养不高，实践经验也很缺乏，对于中国的历史状况和社会状况、中国革命的特点、中国革命的规律不了解，对于马克思列宁主义的理论和中国革命的实践没有统一的理解，即不善于把马克思列宁主义与中国实际全面地、正确地结合起来。因此，选项C正确。","options":{"A":"均为主要原因，但不是最主要的原因，故不选。","B":"均为主要原因，但不是最主要的原因，故不选。","C":"（正确选项，分析见“解题思路”）","D":"均为主要原因，但不是最主要的原因，故不选。"}}},{"id":"advanced-shigang-test5-9","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试五","chapterKey":"综合测试五","n":9,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试五 第 9 题"},"stem":"1941年，皖南事变发生后，党内有人认为皖南事变是第二个“四一二反革命政变”，国民党集团将投降日本，国共合作面临再次破裂。毛泽东针对这一观点指出，皖南事变与“四一二反革命政变”不同，只要中国共产党实行正确的策略，就能继续维持国共合作，维护抗日民族统一战线。毛泽东作出这一结论的主要依据是","choices":[{"id":"A","text":"民族矛盾仍是当时的主要矛盾"},{"id":"B","text":"盟国不赞同国共两党分道扬镳"},{"id":"C","text":"国民党有放弃反共政策的可能性"},{"id":"D","text":"国共两党的力量对比发生了根本性变化"}],"answer":["A"],"analysis":{"point":"本题考查抗日民族统一战线。近代国共两党的关系，一直随着中国国内主要矛盾的变化而变化。抗日战争时期，日本灭亡中国的基本方针始终没有改变，因此，中日的民族矛盾决定了两党的合作关系。因此，选项A正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"当时，中国共产党早已在政治上从幼稚走向成熟，能够独立自主地作出决策。此外，盟国的态度并没有也不会成为毛泽东作出该结论的主要依据。故不选。","C":"国民党在1939年召开的五届五中全会上就确定了“防共、限共、溶共、反共”的方针。到1941年皖南事变的发生，国民党将第二次反共浪潮推向高峰。之后国民党对于中国共产党到底采取何种态度是不可预判的，这不可能成为毛泽东作出该结论的主要依据。故不选。","D":"在抗日战争时期，国共两党的力量对比并没有发生根本性的变化，直到解放战争时期的“三大战役”之后，国民党赖以维持其反动统治的主要军事力量基本被摧毁，国共两党的力量对比才发生了根本性变化。故不选。"}}},{"id":"advanced-shigang-test5-10","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试五","chapterKey":"综合测试五","n":10,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试五 第 10 题"},"stem":"1942年1月28日，中共中央政治局通过了《关于抗日根据地土地政策的决定》（简称《决定》），制定了抗日战争时期土地政策的三项基本原则，即减租减息、交租交息和鼓励富农发展生产。《决定》的附件还规定了具体政策和办法：第一，不论任何租地、任何租佃形式均照抗战前租额减低25%，在游击区及敌占点线附近，可少于二五减租，只减二成、一成五或一成。第二，只对于抗战前成立的借贷关系，以一分半为计息标准，如付息超过原本一倍者停利还本，超过二倍者本利停付。这一《决定》表明","choices":[{"id":"A","text":"抗日根据地的土地剥削有所减轻"},{"id":"B","text":"当时革命的主要对象是封建地主阶级"},{"id":"C","text":"党在农村根据地废除了封建剥削制度"},{"id":"D","text":"抗日民主政府充分团结了党外进步人士和中间派"}],"answer":["A"],"analysis":{"point":"本题考查抗日战争时期的土地政策。根据题干可知，减租减息政策减轻了农民交租交息的负担，所以，土地剥削有所减轻。因此，选项A正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"当时革命的主要对象是日本帝国主义，因此，减租减息政策实际上给予了地主阶级土地所有权，以便团结地主阶级抗日，故不选。","C":"交租交息本身就是允许农村中存在剥削，党在农村根据地废除封建剥削制度是从解放战争时期解放区的土地改革开始的，直到中华人民共和国成立初期的新解放区土地改革，故不选。","D":"减租减息政策，一方面改善了农民的生活，团结了农民；另一方面照顾了地主的利益，团结了地主。与中间势力无关，故不选。"}}},{"id":"advanced-shigang-test5-11","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试五","chapterKey":"综合测试五","n":11,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试五 第 11 题"},"stem":"1938年，在中国共产党召开的六届六中全会上，毛泽东强调：“离开中国特点来谈马克思主义，只是抽象的空洞的马克思主义……即是说，按照中国的特点去应用它，成为全党亟待了解并亟待解决的问题。”由此可知，党的六届六中全会","choices":[{"id":"A","text":"确立了毛泽东思想在全党的领导地位"},{"id":"B","text":"推动马克思主义中国化进入了新阶段"},{"id":"C","text":"系统论述了中国革命的性质与对象"},{"id":"D","text":"彻底纠正了党在思想上的“左”倾教条主义错误"}],"answer":["B"],"analysis":{"point":"本题考查党的六届六中全会。根据题干可知，党的六届六中全会讲的是马克思主义基本原理与中国实际相结合，进而将“马克思主义的中国化”推入了一个新阶段。因此，选项B正确。","options":{"A":"毛泽东思想成为党的指导思想是在中共七大，故不选。","B":"（正确选项，分析见“解题思路”）","C":"《新民主主义论》的发表指明了中国革命的性质、对象、任务、动力和前途，故不选。","D":"彻底纠正党在思想上的“左”倾教条主义错误，是在延安整风运动，而不是在党的六届六中全会，故不选。"}}},{"id":"advanced-shigang-test5-12","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试五","chapterKey":"综合测试五","n":12,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试五 第 12 题"},"stem":"1941年5月，毛泽东在党的高级干部会议上作《改造我们的学习》的报告，整风运动首先在党的高级干部中进行。反对主观主义以整顿学风是延安整风运动最主要的任务，这是因为遵义会议以后，思想上主观主义的遗毒仍然存在，这种主观主义同实事求是的马克思主义是相对抗的，是实际工作中的唯心主义。为此，毛泽东强调","choices":[{"id":"A","text":"“须知政权是由枪杆子中取得的”"},{"id":"B","text":"“一切无原则的派别斗争，都要清除干净”"},{"id":"C","text":"“兵民是胜利之本”"},{"id":"D","text":"“加强调查研究是转变党的作风的基础一环”"}],"answer":["D"],"analysis":{"point":"本题考查延安整风运动。主观主义是理论脱离实际的错误，而调查研究是把理论和实际结合起来的不可或缺的中间环节。因此，毛泽东在整风运动期间特别强调了调查研究的重要性。因此，选项D正确。","options":{"A":"是在八七会议上提出的，与延安整风运动的内容无关。故不选。","B":"出自延安整风运动时期的《整顿党的作风》，是针对反对宗派主义提出的。故不选。","C":"是在《论持久战》中提出的，与延安整风运动的内容无关。故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-shigang-test5-13","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试五","chapterKey":"综合测试五","n":13,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试五 第 13 题"},"stem":"1944年5月21日至1945年4月20日，中共扩大的六届七中全会在延安召开。会议原则通过了《关于若干历史问题的决议》（简称《决议》），对建党以后特别是党的六届四中全会至遵义会议前这一段党的历史及其经验教训进行了总结，对党的若干重大历史问题作出结论。该《决议》","choices":[{"id":"A","text":"论述了中国由新民主主义社会转变为社会主义社会的任务及其主要途径"},{"id":"B","text":"科学地评价了毛泽东和毛泽东思想的历史地位"},{"id":"C","text":"标志着党在政治上思想上组织上走向成熟"},{"id":"D","text":"使全党特别是党的高级干部对中国革命基本问题的认识达到了一致"}],"answer":["D"],"analysis":{"point":"本题考查中共六届七中全会。中共扩大的六届七中全会原则通过了《关于若干历史问题的决议》（简称《决议》），该《决议》使全党特别是党的高级干部对中国革命基本问题的认识达到了一致。因此，选项D正确。","options":{"A":"1949年3月，中共七届二中全会决议分析了新民主主义社会的经济状况和基本矛盾，论述了中国从农业国转变为工业国、由新民主主义社会转变为社会主义社会的任务及其主要途径。故不选。","B":"1981年6月，党的十一届六中全会通过的《关于建国以来党的若干历史问题的决议》科学地评价了毛泽东和毛泽东思想的历史地位。故不选。","C":"中共七大标志着党在政治上思想上组织上走向成熟。故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-shigang-test5-14","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试五","chapterKey":"综合测试五","n":14,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试五 第 14 题"},"stem":"陈旭麓认为，辛亥革命、国民革命、解放战争分别推翻了清政府、北洋政府、国民党政府，构成了近代中国民主革命的三次高潮。这三次高潮的相同点是","choices":[{"id":"A","text":"领导阶级和革命前途相同"},{"id":"B","text":"革命结果与指导思想相同"},{"id":"C","text":"革命性质和革命任务相同"},{"id":"D","text":"革命对象与领导阶级相同"}],"answer":["C"],"analysis":{"point":"本题考查近代中国民主革命的三次高潮。辛亥革命、国民革命、解放战争构成了近代中国民主革命的三次高潮。这三次高潮都是民主主义革命性质的，其任务都是反帝反封建。因此，选项C正确。","options":{"A":"辛亥革命是资产阶级领导的，国民革命是国共双方共同领导的，解放战争是无产阶级领导的。","B":"辛亥革命和国民革命失败了，解放战争则成功了。辛亥革命的指导思想是三民主义，国民革命的指导思想是新三民主义，解放战争的指导思想是马克思列宁主义和毛泽东思想。","C":"（正确选项，分析见“解题思路”）","D":"辛亥革命要推翻清朝的腐朽统治，国民革命要推翻北洋军阀的反动独裁统治，解放战争要推翻国民党的统治。"}}},{"id":"advanced-shigang-test5-15","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试五","chapterKey":"综合测试五","n":15,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试五 第 15 题"},"stem":"1949年3月，在中国共产党七届二中全会上，毛泽东告诫全党：“务必使同志们继续地保持谦虚、谨慎、不骄、不躁的作风，务必使同志们继续地保持艰苦奋斗的作风。”其原因主要是","choices":[{"id":"A","text":"中国将由新民主主义社会进入社会主义社会"},{"id":"B","text":"中国共产党即将成为执政党"},{"id":"C","text":"解放战争即将全面胜利"},{"id":"D","text":"党的根本宗旨即将改变"}],"answer":["B"],"analysis":{"point":"本题考查“两个务必”的提出。1949年3月5日至13日，在人民解放军取得三大战役胜利、继续高歌猛进之际，中国共产党在河北省平山县西柏坡村举行七届二中全会，研究夺取全国胜利以及筹建新中国事宜。会议提出党和军队的工作重心必须从农村转移到城市，必须用极大的努力去学会管理和建设城市；阐明了全国胜利后党在政治、经济、外交方面应当采取的基本政策，指出了中国由农业国转变为工业国、由新民主主义社会转变为社会主义社会的发展方向。面对即将取得的全国胜利，党应当保持怎样的一种精神状态？在报告结尾部分，毛泽东专门论述党的作风建设，告诫全党，夺取全国胜利，这只是万里长征走完了第一步，中国的革命是伟大的，但革命以后的路更长，工作更伟大、更艰苦。据此，他提出了“两个务必”。这也是毛泽东首次明确提出执政党建设问题。因此，选项B正确。","options":{"A":"与事实不符，当时新中国还未成立，新民主主义社会尚未建立。故不选。","B":"（正确选项，分析见“解题思路”）","C":"属于召开中共七届二中全会的背景，并非提出“两个务必”的直接原因。故不选。","D":"党自成立起就确立了“全心全意为人民服务”的根本宗旨，这一根本宗旨是不会改变的。故不选。"}}},{"id":"advanced-shigang-test5-16","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试五","chapterKey":"综合测试五","n":16,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试五 第 16 题"},"stem":"1956年，随着社会主义改造的基本完成，中国继建立社会主义基本政治制度之后，社会主义基本经济制度也建立起来了。社会主义基本制度的全面确立，标志着中国","choices":[{"id":"A","text":"半殖民地半封建社会的结束"},{"id":"B","text":"进入开始全面建设社会主义的历史阶段"},{"id":"C","text":"新民主主义革命取得基本胜利"},{"id":"D","text":"社会主义工业化已经初步实现"}],"answer":["B"],"analysis":{"point":"本题考查社会主义基本制度的全面确立。社会主义基本制度的全面确立标志着中国进入了全面建设社会主义的历史阶段。因此，选项B正确。","options":{"A":"中华人民共和国的成立标志着半殖民地半封建社会的结束和新民主主义革命取得基本胜利。","B":"（正确选项，分析见“解题思路”）","C":"中华人民共和国的成立标志着半殖民地半封建社会的结束和新民主主义革命取得基本胜利。","D":"社会主义工业化并不是在1956年实现的，而是在1956年之后的一系列五年规划的努力中逐步实现的。"}}},{"id":"advanced-shigang-test5-17","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试五","chapterKey":"综合测试五","n":17,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试五 第 17 题"},"stem":"1853年3月，太平天国占领南京，定为首都，改名天京，正式宣告太平天国农民政权的建立。太平天国定都天京后，先后进行了北伐、西征和天京城外的破围战。到1856年上半年，除北伐失利外，太平军在湖北、江西、安徽和天津附近等战场都取得了重大胜利，控制了大片地区，达到了军事上的全盛时期。关于太平天国农民战争，下列说法正确的有","choices":[{"id":"A","text":"动摇了清王朝封建统治的基础"},{"id":"B","text":"明确地提出了反对帝国主义的要求"},{"id":"C","text":"无法长期保持领导集团的团结"},{"id":"D","text":"未能正确地对待儒学"}],"answer":["A","C","D"],"analysis":{"point":"本题考查太平天国农民战争。太平天国农民战争历时14载，建立了与清王朝对峙的政权，动摇了清王朝封建统治的基础，显示了农民阶级的反抗精神和战斗力量。选项A正确。无法长期保持领导集团的团结，是农民阶级作为小生产者的局限性之一，农民阶级的局限性是太平天国农民战争失败的根本原因。选项C正确。太平天国农民战争失败的原因还有：没有科学理论的指导；未能正确地对待儒学；对于西方资本主义侵略者缺乏理性认识。选项D正确。因此，选项A、C、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"说法错误，太平天国的领导者们虽然不承认不平等条约，但是他们不能把西方的侵略者与人民群众区别开来，而是笼统地把信奉天父上帝的西方人都视为“洋兄弟”，故不选。","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-shigang-test5-18","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试五","chapterKey":"综合测试五","n":18,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试五 第 18 题"},"stem":"洋务运动历时30多年，虽然办起了一批企业，建立了海军，却没有使中国富强起来。甲午战争一役，洋务派经营多年的北洋海军全军覆没，标志着以“自强”“求富”为目标的洋务运动的失败。洋务运动失败的原因主要有","choices":[{"id":"A","text":"洋务运动对列强具有依赖性"},{"id":"B","text":"洋务企业的管理具有腐朽性"},{"id":"C","text":"封建统治阶级的反对"},{"id":"D","text":"洋务运动具有封建性"}],"answer":["A","B","D"],"analysis":{"point":"本题考查洋务运动失败的主要原因。洋务运动失败的原因主要有：首先，洋务运动具有封建性。其次，洋务运动对列强具有依赖性。最后，洋务企业的管理具有腐朽性。正因为如此，洋务运动不可能为中国摆脱贫弱找到出路，也不可能避免最终失败的命运。因此，选项A、B、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"兴办洋务是为了挽救清政府的统治危机，其代表人物主要是封建统治阶级中的部分成员，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-shigang-test5-19","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试五","chapterKey":"综合测试五","n":19,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试五 第 19 题"},"stem":"甲午，对中国人民和中华民族具有特殊含义，在我国近代史上也具有特殊含义。1894年7月，日本发动甲午战争，清朝在战争中战败。这场战争对中国的影响主要有","choices":[{"id":"A","text":"台湾被日本侵占"},{"id":"B","text":"中国人开始有了普遍的民族意识的觉醒"},{"id":"C","text":"帝国主义列强掀起瓜分中国的狂潮"},{"id":"D","text":"中国海关的行政权落入外国人手中"}],"answer":["A","B","C"],"analysis":{"point":"本题考查中日甲午战争。中日《马关条约》规定把台湾及其附属岛屿、澎湖列岛和辽东半岛割让给日本。俄国认为，日本割取辽东半岛损害了俄国在中国的侵略利益，便联合法国和德国共同干涉还辽，迫使日本放弃了割占辽东半岛的要求。俄、德、法三国以干涉还辽“有功”为理由，要求租借中国港湾作为报酬。由此，德、俄、英、法、日等国于1898年至1899年竞相租借港湾和划分势力范围，掀起了瓜分中国的狂潮。中国在中日甲午战争中的失败，对中国人的刺激极大。中日甲午战争以后，在中华民族面临生死存亡的关头，中国人才开始有了普遍的民族意识的觉醒。因此，选项A、B、C正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"“中国海关的行政权落入外国人手中”是在鸦片战争后，比中日甲午战争爆发的时间要早。"}}},{"id":"advanced-shigang-test5-20","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试五","chapterKey":"综合测试五","n":20,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试五 第 20 题"},"stem":"袁世凯窃夺辛亥革命的果实之后，建立了代表大地主和买办资产阶级利益的北洋军阀反动政权。袁世凯当权时，北洋政府统治下的中国在形式上是统一的。在1916年袁世凯称帝败亡之后，连这种形式上的统一也维持不住了，中国陷入了军阀割据的局面。形成这种局面的原因有","choices":[{"id":"A","text":"当时中国的军事科学技术落后于西方"},{"id":"B","text":"当时我国没有形成统一的资本主义市场"},{"id":"C","text":"当时中国主要是地方性的农业经济"},{"id":"D","text":"帝国主义国家在中国采取划分势力范围的分裂剥削政策"}],"answer":["B","C","D"],"analysis":{"point":"本题考查北洋军阀的专制统治。袁世凯败亡后，中国陷入了军阀割据的局面。这种局面的形成有其深刻的原因：一方面，中国主要是地方性的农业经济而没有形成统一的资本主义市场；另一方面，帝国主义国家在中国采取划分势力范围的分裂剥削政策。因此，选项B、C、D正确。","options":{"A":"中国的军事科学技术落后于西方是近代中国反侵略战争失败的原因，而不是军阀割据的原因。","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-shigang-test5-21","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试五","chapterKey":"综合测试五","n":21,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试五 第 21 题"},"stem":"1919年爆发的五四运动，是中国旧民主主义革命走向新民主主义革命的转折点，是中国新民主主义革命的开端，在近代以来中华民族追求民族独立和发展进步的历史进程中具有里程碑意义。五四运动成为中国新民主主义革命的开端的原因在于","choices":[{"id":"A","text":"它促进了马克思主义在中国的传播"},{"id":"B","text":"它促进了马克思主义同中国工人运动的结合"},{"id":"C","text":"它为中国共产党的成立作了思想上干部上的准备"},{"id":"D","text":"它为新的革命力量、革命文化、革命斗争登上历史舞台创造了条件"}],"answer":["A","B","C","D"],"analysis":{"point":"本题考查五四运动的历史意义。五四运动以彻底反帝反封建的革命性、追求救国强国真理的进步性、各族各界群众积极参与的广泛性，推动了中国社会进步，促进了马克思主义在中国的传播，促进了马克思主义同中国工人运动的结合，为中国共产党的成立作了思想上干部上的准备，为新的革命力量、革命文化、革命斗争登上历史舞台创造了条件。因此，五四运动成为中国新民主主义革命的开端。因此，选项A、B、C、D正确。\\n无干扰选项。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-shigang-test5-22","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试五","chapterKey":"综合测试五","n":22,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试五 第 22 题"},"stem":"全国高校第一家红船精神研究机构——嘉兴大学（原嘉兴学院）红船精神研究中心，地理位置距浙江嘉兴南湖只有十几分钟车程。对中国共产党早期组织成员的研究，恰好是红船精神研究中心在党史研究领域填补的空白之一。20世纪20年代初，中国共产党早期组织的活动有","choices":[{"id":"A","text":"研究和宣传马克思主义，研究中国实际问题"},{"id":"B","text":"第一次提出反帝反封建的民主革命纲领"},{"id":"C","text":"起草《中国共产党宣言》"},{"id":"D","text":"成立上海机器工会"}],"answer":["A","C","D"],"analysis":{"point":"本题考查中国共产党早期组织的活动。中国共产党早期组织的活动主要有：第一，研究和宣传马克思主义，研究中国实际问题，如1920年8月，陈望道翻译的《共产党宣言》中文全译本公开出版；第二，到工人中去进行宣传和组织工作，如1920年11月，共产党早期组织领导的第一个工会——上海机器工会宣告成立；第三，进行关于建党问题的讨论和实际组织工作，如上海共产主义小组于1920年11月起草《中国共产党宣言》。因此，选项A、C、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"党的二大第一次提出反帝反封建的民主革命纲领，不属于中国共产党早期组织的活动。","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-shigang-test5-23","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试五","chapterKey":"综合测试五","n":23,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试五 第 23 题"},"stem":"红军和根据地的存在和发展，使国民党反动派感到恐慌。从1930年10月起，蒋介石集重兵向南方各革命根据地的红军发动了大规模“围剿”。在毛泽东同志的直接指挥下，红军接连取得了三次反“围剿”的胜利，其主要原因有","choices":[{"id":"A","text":"在根据地实行“三三制”原则"},{"id":"B","text":"土地革命在各根据地的开展"},{"id":"C","text":"贯彻了积极防御的作战方针"},{"id":"D","text":"实行了“诱敌深入”“避敌主力、打其虚弱”等战术"}],"answer":["B","C","D"],"analysis":{"point":"本题考查反“围剿”战争。首先，土地革命在各根据地的开展，力求让广大农民在政治上得到翻身，提高了农民阶级的积极性，让红军获得了不少人力、物力支援。其次，积极防御的作战方针是指在战略防御的形式下，灵活运用多种作战形式，积极进行攻势作战，逐步改变战略形势，最终夺取战争胜利或挫败敌人的进攻，迫其停战求和，结束战争的战术。最后，红军在毛泽东、朱德等指挥下，贯彻积极防御的方针，实行“诱敌深入”“避敌主力、打其虚弱”等一整套行之有效的战术，连续粉碎了国民党军队的三次“围剿”。因此，选项B、C、D正确。","options":{"A":"属于抗日战争时期根据地政权建设的主要内容。","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-shigang-test5-24","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试五","chapterKey":"综合测试五","n":24,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试五 第 24 题"},"stem":"《中国共产党的七十年》中指出：“从大革命失败到抗日战争前夕这十年，是中国共产党在极端困难的条件下坚持斗争并达到政治上成熟的时期。”这一时期中国共产党政治上“成熟”的表现包括","choices":[{"id":"A","text":"根据中国的国情，提出了彻底的民主革命纲领"},{"id":"B","text":"找到了一条引领中国革命走向胜利的唯一正确的道路"},{"id":"C","text":"形成了独立自主地解决本国革命实际问题的领导核心"},{"id":"D","text":"根据国内社会主要矛盾的变化，正确处理国共两党之间的关系"}],"answer":["B","C","D"],"analysis":{"point":"本题考查中国共产党政治上“成熟”的表现。题干限定“从大革命失败到抗日战争前夕这十年”，即1927年到1937年这段时期。农村包围城市、武装夺取政权的理论，是对1927年大革命失败后中国共产党领导的红军和根据地斗争经验的科学概括，指明了中国革命胜利的唯一正确道路；1935年1月，遵义会议确立了毛泽东在全党的实际领导地位，开始形成了独立自主地解决本国革命实际问题的领导核心；1935年12月25日，中共中央在陕北瓦窑堡召开政治局扩大会议，根据国内社会主要矛盾的变化，提出了建立抗日民族统一战线的方针，使国共两党达成一致抗日的共识。因此，选项B、C、D正确。","options":{"A":"1922年，中国共产党第二次全国代表大会第一次提出了彻底的民主革命纲领。与题意不符，故不选。","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-shigang-test5-25","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试五","chapterKey":"综合测试五","n":25,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试五 第 25 题"},"stem":"1945年4月23日，在党的历史上具有重要里程碑意义的中国共产党第七次全国代表大会在延安杨家岭中央大礼堂开幕。党的七大是党在新民主主义革命时期召开的一次极其重要的全国代表大会，为党后来不断从胜利走向胜利指明了正确方向、开辟了正确道路。这次会议","choices":[{"id":"A","text":"制定了新民主主义国家在政治、经济、文化方面的纲领"},{"id":"B","text":"使实事求是的思想路线在全党范围确立起来"},{"id":"C","text":"标志着党在政治上思想上组织上走向成熟"},{"id":"D","text":"把党在长期奋斗中形成的优良作风概括为三大作风"}],"answer":["A","C","D"],"analysis":{"point":"本题考查中共七大。中共七大制定了新民主主义国家在政治、经济、文化方面的纲领，提出实现中国工业化的宏伟任务。中共七大把党在长期奋斗中形成的优良作风概括为三大作风，即理论和实践相结合的作风、和人民群众紧密联系在一起的作风、自我批评的作风。中共七大在党的历史上具有重要里程碑意义，标志着党在政治上思想上组织上走向成熟。因此，选项A、C、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"1941—1945年的延安整风运动是一次深刻的马克思主义思想教育运动，使实事求是的思想路线在全党范围确立起来。","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-shigang-test5-26","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试五","chapterKey":"综合测试五","n":26,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试五 第 26 题"},"stem":"在抗日战争爆发后不久，毛泽东同志就指出：“凡属正义的革命的战争，其力量是很大的，它能改造很多事物，或为改造事物开辟道路……中华民族的解放将从这个战争中得来。”中国人民抗日战争是“正义的革命的战争”，因为这场胜利","choices":[{"id":"A","text":"赢得了民族独立和人民解放，中国人民从此翻身做了主人"},{"id":"B","text":"是近代以来中华民族反抗外敌入侵第一次取得完全胜利的民族解放战争"},{"id":"C","text":"促进了中华民族的觉醒和大团结，弘扬了中华民族的伟大精神"},{"id":"D","text":"对世界各国夺取反法西斯战争的胜利产生了巨大影响"}],"answer":["B","C","D"],"analysis":{"point":"本题考查抗日战争胜利的历史意义。中国人民抗日战争，是近代以来中华民族反抗外敌入侵第一次取得完全胜利的民族解放战争。它促进了中华民族的觉醒，使中国人民在精神上、组织上的进步达到了前所未有的高度；促进了中华民族的大团结，弘扬了中华民族的伟大精神；对世界各国夺取反法西斯战争的胜利、维护世界和平的伟大事业产生了巨大影响。因此，选项B、C、D正确。","options":{"A":"属于新中国成立的历史意义，故不选。","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-shigang-test5-27","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试五","chapterKey":"综合测试五","n":27,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试五 第 27 题"},"stem":"1949年9月21日，中国人民政治协商会议第一届全体会议隆重开幕，会议通过了《中国人民政治协商会议共同纲领》。可以说，完成创建中华人民共和国的任务，是由中国人民政治协商会议来承担的。此次政协会议同1946年重庆政治协商会议有着根本区别，主要表现在","choices":[{"id":"A","text":"由中国共产党领导"},{"id":"B","text":"以国共合作为基础"},{"id":"C","text":"容纳多党派参加"},{"id":"D","text":"属于新民主主义性质"}],"answer":["A","D"],"analysis":{"point":"本题考查中国人民政治协商会议与重庆政治协商会议的根本区别。重庆政治协商会议指的是1946年中国国民党、中国共产党以及各民主党派（民盟、青年党等）为抗战后的和平建国大业在重庆召开的会议，会上达成的五项协议及其他协议还不是新民主主义性质的。中国人民政治协商会议第一届全体会议指的是1949年9月中国共产党及各民主党派、人民团体和无党派民主人士的代表为宣告中华人民共和国成立召开的会议，会上制定的《中国人民政治协商会议共同纲领》规定：“中华人民共和国为新民主主义即人民民主主义的国家。”因此，选项A、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"以国共合作为基础的是重庆政治协商会议，故不选。","C":"容纳多党派参加是两次会议的共同点，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-shigang-test5-28","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试五","chapterKey":"综合测试五","n":28,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试五 第 28 题"},"stem":"没收封建地主阶级的土地归农民所有，是中国革命运动的重要一环，也是中国民主革命的一项基本任务。1950年至1953年春，新解放区进行了我国历史上规模最大，也是进行得最好的一次土地改革运动。这次土地改革运动","choices":[{"id":"A","text":"使农民获得了翻身解放"},{"id":"B","text":"解放了农村生产力，发展了农业生产"},{"id":"C","text":"消灭了富农经济"},{"id":"D","text":"促进了民主革命遗留任务的完成"}],"answer":["A","B","D"],"analysis":{"point":"本题考查中华人民共和国成立后进行的土地改革运动。1950年至1953年春，我国在新解放区进行土地改革运动。《中华人民共和国土地改革法》规定了这次土地改革运动的目的，是废除地主阶级封建剥削的土地所有制，实行农民的土地所有制，解放农村生产力，发展农业生产，为中华人民共和国的工业化开辟道路。土地改革运动中对待富农的政策，由解放战争时期的征收富农多余土地财产改为保存富农经济。这次土地改革运动是我国历史上规模最大，也是历次土地改革运动中进行得最好的一次，极大地促进了民主革命遗留任务的完成。因此，选项A、B、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"土地改革运动中对待富农的政策，由解放战争时期征收富农多余土地财产改为保存富农经济，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-shigang-test5-29","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试五","chapterKey":"综合测试五","n":29,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试五 第 29 题"},"stem":"新民主主义社会在经济上实行国营经济领导下的合作社经济、个体经济、私人资本主义经济和国家资本主义经济五种经济成分并存的经济制度。其中，三种基本的经济成分及与之相应的三种基本的阶级力量之间的矛盾，集中表现为","choices":[{"id":"A","text":"无产阶级与资产阶级的矛盾"},{"id":"B","text":"新中国与帝国主义的矛盾"},{"id":"C","text":"敌我矛盾和人民内部矛盾"},{"id":"D","text":"社会主义与资本主义的矛盾"}],"answer":["A","D"],"analysis":{"point":"本题考查新民主主义社会的主要矛盾。在新民主主义社会，三种基本的经济成分及与之相对应的三种基本的阶级力量（工人阶级、农民及其他小资产阶级、资产阶级）之间的矛盾，集中表现为无产阶级与资产阶级的矛盾、社会主义与资本主义的矛盾。因此，选项A、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"新中国与帝国主义的矛盾并非三种基本的经济成分及与之相对应的三种基本的阶级力量之间的矛盾，故不选。","C":"敌我矛盾和人民内部矛盾是社会主义社会中两类不同性质的社会矛盾，与题意不符，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-shigang-test5-30","moduleId":"advanced","subjectId":"shigang","chapter":"综合测试五","chapterKey":"综合测试五","n":30,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"史纲 · 综合测试五 第 30 题"},"stem":"从开始全面建设社会主义到1976年，我国尽管经历过严重的曲折，但从总体上说，社会主义建设取得的成就是巨大的，主要表现在","choices":[{"id":"A","text":"中华人民共和国恢复在联合国的合法席位"},{"id":"B","text":"成功发射了第一颗人造地球卫星"},{"id":"C","text":"成功爆炸了第一颗原子弹、氢弹"},{"id":"D","text":"普遍实行“统分结合”的家庭联产承包责任制"}],"answer":["A","B","C"],"analysis":{"point":"本题考查全面建设社会主义的成就。1964年10月，中国成功爆炸了第一颗原子弹。1967年6月，中国成功爆炸了第一颗氢弹。1970年1月，中国第一枚中远程导弹发射成功，同年4月，中国第一颗人造地球卫星发射成功。1971年10月，中国在亚、非、拉广大发展中国家支持下，排除美国的干预、阻挠，恢复了在联合国的一切合法权利。因此，选项A、B、C正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"属于改革开放后的成就，故不选。"}}},{"id":"advanced-sixiu-test1-1","moduleId":"advanced","subjectId":"sixiu","chapter":"综合测试一","chapterKey":"综合测试一","n":1,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"思修 · 综合测试一 第 1 题"},"stem":"人生观决定着人们实践活动的目标、人生道路的方向，也决定着人们行为选择的价值取向和对待生活的态度。其中，判别什么样的人生才有意义的是","choices":[{"id":"A","text":"人生价值"},{"id":"B","text":"人生态度"},{"id":"C","text":"人生目的"},{"id":"D","text":"人生道路"}],"answer":["A"],"analysis":{"point":"本题考查人生观。人生观是人们关于人生目的、人生态度和人生价值等问题的总观点和总看法。其中人生价值是一种特殊的价值，是人的生命及实践活动对于社会和个人所具有的作用和意义。一个人之所以以这样或那样的方式对待生活，是因为在他看来，他所选择的生活方式是有意义的。因此，选项A正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"人生态度表明人应当如何活着，故不选。","C":"人生目的回答人为什么活着，故不选。","D":"不符合题意，故不选。"}}},{"id":"advanced-sixiu-test1-2","moduleId":"advanced","subjectId":"sixiu","chapter":"综合测试一","chapterKey":"综合测试一","n":2,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"思修 · 综合测试一 第 2 题"},"stem":"习近平同青年大学生座谈时强调：“要树立正确的世界观、人生观、价值观，掌握了这把总钥匙，再来看看社会万象、人生历程，一切是非、正误、主次，一切真假、善恶、美丑，自然就洞若观火、清澈明了，自然就能作出正确判断、作出正确选择。”下列关于人生观的表述，正确的有①人生观决定着人生道路的方向②人生观决定世界观③人生观决定着人们行为选择的价值取向④人生观决定用什么样的方式对待实际生活","choices":[{"id":"A","text":"①②③"},{"id":"B","text":"①③④"},{"id":"C","text":"①②④"},{"id":"D","text":"②③④"}],"answer":["B"],"analysis":{"point":"本题考查人生观。人生观决定着人生道路的方向，也决定着人们行为选择的价值取向和用什么样的方式对待实际生活。因此，选项B正确。","options":{"A":"②逻辑颠倒，正确表述是“世界观决定人生观”，故不选。","B":"（正确选项，分析见“解题思路”）","C":"②逻辑颠倒，正确表述是“世界观决定人生观”，故不选。","D":"②逻辑颠倒，正确表述是“世界观决定人生观”，故不选。"}}},{"id":"advanced-sixiu-test1-3","moduleId":"advanced","subjectId":"sixiu","chapter":"综合测试一","chapterKey":"综合测试一","n":3,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"思修 · 综合测试一 第 3 题"},"stem":"中国农民说，吃饭靠“两平”，一靠邓小平（责任制），二靠袁隆平（杂交水稻）。西方世界称，杂交水稻是“东方魔稻”。袁隆平的成果不仅在很大程度上解决了中国人的吃饭问题，而且被认为是解决21世纪世界性饥饿问题的法宝。国际上甚至把杂交水稻当作中国继“四大发明”之后的“第五大发明”，将其誉为“第二次绿色革命”。社会给予袁隆平高度评价，是因为他","choices":[{"id":"A","text":"实现了个人理想"},{"id":"B","text":"树立了为人民服务的人生观"},{"id":"C","text":"通过劳动对社会和他人作出了巨大贡献"},{"id":"D","text":"从社会中获得了极大满足"}],"answer":["C"],"analysis":{"point":"本题考查评价人生价值的根本尺度。评价人生价值的根本尺度，是看一个人的实践活动是否符合社会发展的客观规律，是否通过实践促进了历史的进步。劳动以及通过劳动对社会和他人作出的贡献，是社会评价一个人的人生价值的普遍标准。一个人对社会和他人所作的贡献越大，他在社会中获得的人生价值的评价就越高。劳动和贡献的尺度作为社会评价人生价值的基本尺度，正是对评价人生价值的根本尺度的一种具体化。因此，选项C正确。","options":{"A":"题干没有涉及袁隆平实现个人理想的过程，故不选。","B":"题干没有直接涉及为人民服务的人生观，故不选。","C":"（正确选项，分析见“解题思路”）","D":"题干表述的是袁隆平对社会和他人作出的巨大贡献，而非索取，故不选。"}}},{"id":"advanced-sixiu-test1-4","moduleId":"advanced","subjectId":"sixiu","chapter":"综合测试一","chapterKey":"综合测试一","n":4,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"思修 · 综合测试一 第 4 题"},"stem":"信念是认知、情感和意志的有机统一体，是人们在一定的认识基础上确立的对某种思想或事物坚信不疑并身体力行的精神状态。信念是人们追求理想目标的强大动力，决定事业的成败。信念有不同的层次和类型，其中","choices":[{"id":"A","text":"高层次的信念决定低层次的信念"},{"id":"B","text":"低层次的信念代表了一个人的基本信仰"},{"id":"C","text":"相同社会环境中生活的人们的信念始终一致"},{"id":"D","text":"各种信念没有科学与非科学之分"}],"answer":["A"],"analysis":{"point":"本题考查信念的含义与特征。信念同理想一样，也是人类特有的一种精神现象。信念是认知、情感和意志的有机统一体，是人们在一定的认识基础上确立的对某种思想或事物坚信不疑并身体力行的精神状态。同一个人的不同信念之间常常具有内在联系并由此构成其信念体系。其中高层次的信念决定低层次的信念，低层次的信念服从于高层次的信念；由于最高层次的信念具有最大的统摄力，因而它就代表了一个人的基本信仰。信仰是信念最集中、最高层次的表现形式。因此，选项A正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"信仰是最高层次的信念，不可能由低层次的信念代表，故排除。","C":"意识具有相对独立性，相同社会环境中生活的人们，信念不一定始终一致，故排除。","D":"信仰可分为两种类型：一种是对虚幻的世界、不切实际的观念、荒谬的理论等对象的迷信、狂热崇拜；另一种是在社会实践活动中对以事物发展规律的正确认识为基础的思想见解或理论主张的坚信不疑并身体力行的精神状态。后者就是我们所主张的科学信仰。故排除。"}}},{"id":"advanced-sixiu-test1-5","moduleId":"advanced","subjectId":"sixiu","chapter":"综合测试一","chapterKey":"综合测试一","n":5,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"思修 · 综合测试一 第 5 题"},"stem":"爱国主义在不同的历史时期和文化背景下有着不同的内涵和特点。在新民主主义革命时期，爱国主义主要表现为致力于推翻帝国主义、封建主义和官僚资本主义的反动统治，把黑暗的旧中国改造成光明的新中国。在现阶段，爱国主义主要表现为心系国家的前途和命运，献身于社会主义现代化事业，献身于祖国统一大业。这表明","choices":[{"id":"A","text":"爱国主义是主观的、现实的"},{"id":"B","text":"爱国主义是历史的、具体的"},{"id":"C","text":"爱国主义是客观的、抽象的"},{"id":"D","text":"爱国主义是客观的、具体的"}],"answer":["B"],"analysis":{"point":"本题考查爱国主义的基本内涵。爱国主义不是人类亘古不变的情感，在不同的历史条件和文化背景下所形成的爱国主义，总是具有不同的内涵和特点。爱国主义是历史的、具体的，不是抽象的。因此，选项B正确。","options":{"A":"从历史唯物主义的角度来看，爱国主义并非一种完全“主观”的存在，故不选。","B":"（正确选项，分析见“解题思路”）","C":"爱国主义是具体的，而不是抽象的，故不选。","D":"爱国主义是客观的，但是题干指出不同历史时期爱国主义的内涵和特点不同，显然强调的是“历史的”这个特点。故不选。"}}},{"id":"advanced-sixiu-test1-6","moduleId":"advanced","subjectId":"sixiu","chapter":"综合测试一","chapterKey":"综合测试一","n":6,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"思修 · 综合测试一 第 6 题"},"stem":"恩格斯曾经指出，道德“或者为统治阶级的统治和利益辩护，或者当被压迫阶级变得足够强大时，代表被压迫者对这个统治的反抗和他们的未来利益”。这主要说明","choices":[{"id":"A","text":"道德可以保障人们正常的生活和交往"},{"id":"B","text":"道德是影响社会生产力发展的一种重要力量"},{"id":"C","text":"道德能够保护或者破坏一定阶级的政治统治"},{"id":"D","text":"道德对其他意识形态的存在和发展具有重大影响"}],"answer":["C"],"analysis":{"point":"本题考查道德的作用。道德的作用主要表现在：道德为经济基础的形成、巩固和发展服务；道德对其他社会意识形态的存在和发展有着重大影响；道德是影响社会生产力发展的一种重要精神力量；道德通过调整人们之间的关系维护社会秩序和稳定；道德是提高人的精神境界、促进人的自我完善、推动人的全面发展的内在动力。在阶级社会中，道德是调节阶级矛盾和对立阶级之间开展阶级斗争的重要工具。当道德为统治阶级辩护时，是对政治统治的保护；当道德代表被压迫者反抗统治阶级时，是在破坏政治统治。因此，选项C正确。","options":{"A":"是道德在人际交往中的作用，与题干表述的道德反映统治阶级意志的作用不符，故不选。","B":"是道德对生产力发展及上层建筑的作用，没有体现题干表述的道德反映统治阶级意志的作用，故不选。","C":"（正确选项，分析见“解题思路”）","D":"是道德对生产力发展及上层建筑的作用，没有体现题干表述的道德反映统治阶级意志的作用，故不选。"}}},{"id":"advanced-sixiu-test1-7","moduleId":"advanced","subjectId":"sixiu","chapter":"综合测试一","chapterKey":"综合测试一","n":7,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"思修 · 综合测试一 第 7 题"},"stem":"我国自古就有“君子成人之美”“为善最乐”“博施济众”等广为流传的格言，今天我们的社会公德要求助人为乐。这说明社会公德具有","choices":[{"id":"A","text":"继承性"},{"id":"B","text":"广泛性"},{"id":"C","text":"基础性"},{"id":"D","text":"简明性"}],"answer":["A"],"analysis":{"point":"本题考查社会公德的基本特征。社会公德是指人们在社会交往和公共生活中应当遵守的行为准则。题干中的关键词是从“古”至“今”，体现了继承性。因此，选项A正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"社会公德的广泛性体现在全体社会成员都必须遵守道德规范，其具有最广泛的群众基础和适用范围。任何一个社会成员，无论具有何种身份、职业和地位，都必须在公共生活中遵守社会公德。与题意不符，故不选。","C":"社会公德的基础性体现在它是社会道德体系的基础层次，是每个社会成员都应遵守的最起码的道德准则，是社会为维护公共生活而提出的最基本的道德要求。与题意不符，故不选。","D":"社会公德的简明性体现在社会公德大多是生活经验的积累和风俗习惯的提炼，往往不需要做更多的说明就能被人们理解。与题意不符，故不选。"}}},{"id":"advanced-sixiu-test1-8","moduleId":"advanced","subjectId":"sixiu","chapter":"综合测试一","chapterKey":"综合测试一","n":8,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"思修 · 综合测试一 第 8 题"},"stem":"曾子曰：“吾日三省吾身，为人谋而不忠乎？与朋友交而不信乎？传不习乎？”这属于中国传统道德修养方法中的","choices":[{"id":"A","text":"省察克治"},{"id":"B","text":"陶冶情操"},{"id":"C","text":"慎独自律"},{"id":"D","text":"积善成德"}],"answer":["A"],"analysis":{"point":"本题考查道德修养的方法。题干的意思为，曾子说：“我每天多次反省自己，为别人办事是不是尽心竭力了？同朋友交往是不是做到诚实可信了？老师传授给我的知识是不是复习了？”这属于道德修养方法中的省察克治。因此，选项A正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"陶冶情操不符合题干中的“三省吾身”，故不选。","C":"慎独自律虽然属于道德修养的方法，但题干中的“三省吾身”不等于慎独自律，故不选。","D":"积善成德多由“勿以恶小而为之，勿以善小而不为”所反映，故不选。"}}},{"id":"advanced-sixiu-test1-9","moduleId":"advanced","subjectId":"sixiu","chapter":"综合测试一","chapterKey":"综合测试一","n":9,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"思修 · 综合测试一 第 9 题"},"stem":"据《史记·齐太公世家》记载，管仲病情严重时，齐桓公曾询问易牙、开方、竖刁三人能否继承相国之位，管仲均给予了否定，理由是此三人的行为均突破了人情实际，突破了人之为人的底线。易牙“杀子以适君，非人情”；开方“倍亲以适君，非人情”；竖刁“自宫以适君，非人情”。管仲死后，齐桓公最终没有采纳管仲的意见，导致齐国由此三人专权。这给我们的启示是","choices":[{"id":"A","text":"“天行健，君子以自强不息”"},{"id":"B","text":"“德者，才之帅也”"},{"id":"C","text":"“礼之用，和为贵”"},{"id":"D","text":"“己所不欲，勿施于人”"}],"answer":["B"],"analysis":{"point":"本题考查道德修养的重要性。题干故事中，易牙、开方、竖刁三人的行为均突破了道德底线，是德性有亏的表现。养大德者方可成大业。“德者，才之帅也”的意思是德是才的统领，这是司马光根据历史上乱臣败子多是“才有余而德不足”的事实而得出的结论，符合题意。因此，选项B正确。","options":{"A":"意思是自然的运动刚强劲健，与此相应，君子处世应像天一样，力求自我进步，刚毅坚卓，发愤图强，永不停息，没有提及“德”的重要性。与题意不符，故不选。","B":"（正确选项，分析见“解题思路”）","C":"意思是礼的作用在于使人际关系和谐，“礼”属于道德范畴，但没有提及德才兼备。与题意不符，故不选。","D":"意思是如果某个结果是自己不想要或不喜欢的，就不要强加给别人。与题意不符，故不选。"}}},{"id":"advanced-sixiu-test1-10","moduleId":"advanced","subjectId":"sixiu","chapter":"综合测试一","chapterKey":"综合测试一","n":10,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"思修 · 综合测试一 第 10 题"},"stem":"法律不是从来就有的，也不是永恒存在的。它随着私有制、阶级和国家的产生而产生，也将随着私有制、阶级和国家的消亡而消亡。法律产生的基础是","choices":[{"id":"A","text":"社会风俗、心理和习惯"},{"id":"B","text":"自然地理环境"},{"id":"C","text":"社会物质生活条件"},{"id":"D","text":"人口因素"}],"answer":["C"],"analysis":{"point":"本题考查法律的起源。法律不是凭空产生的，而是产生于特定时代的物质生活条件基础之上的。因此，选项C正确。","options":{"A":"社会风俗、心理和习惯属于社会意识的内容，它们对法律的产生有能动的影响作用，但是不能作为基础，故不选。","B":"自然地理环境和人口因素属于社会存在的内容，它们对法律的产生和发展起影响作用，但不是决定性的方面，其基础性地位不如“社会物质生活条件”，故不选。","C":"（正确选项，分析见“解题思路”）","D":"自然地理环境和人口因素属于社会存在的内容，它们对法律的产生和发展起影响作用，但不是决定性的方面，其基础性地位不如“社会物质生活条件”，故不选。"}}},{"id":"advanced-sixiu-test1-11","moduleId":"advanced","subjectId":"sixiu","chapter":"综合测试一","chapterKey":"综合测试一","n":11,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"思修 · 综合测试一 第 11 题"},"stem":"法律的运行指的是法律从创制、实施到实现的过程。在这个过程中，属于法律最经常、最大量的工作是","choices":[{"id":"A","text":"法律制定"},{"id":"B","text":"法律执行"},{"id":"C","text":"法律适用"},{"id":"D","text":"法律遵守"}],"answer":["B"],"analysis":{"point":"本题考查法律执行。法律的运行是一个非常重要的知识点，其中法律执行在狭义上也被称为行政执法，行政执法是法律实施和实现的重要环节，必须坚持合法性、合理性、信赖保护、效率等基本原则。我国大部分法律法规是由行政机关执行的，行政执法是最经常、最大量的工作。因此，选项B正确。","options":{"A":"法律制定是指有立法权的国家机关，依照法定职权和程序，制定规范性法律文件的活动，是法律运行的起始性和关键性环节。与题意不符，故不选。","B":"（正确选项，分析见“解题思路”）","C":"法律适用是指国家司法机关及其公职人员依照法定职权和程序适用法律处理案件的专门活动。与题意不符，故不选。","D":"法律遵守是指国家机关、社会组织和公民个人依照法律规定行使权力或权利以及履行职责或义务的活动。与题意不符，故不选。"}}},{"id":"advanced-sixiu-test1-12","moduleId":"advanced","subjectId":"sixiu","chapter":"综合测试一","chapterKey":"综合测试一","n":12,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"思修 · 综合测试一 第 12 题"},"stem":"在我国国家机构体系中，行使国家立法权、决定国家重大事项、监督其他国家机关工作等职权的是","choices":[{"id":"A","text":"国务院"},{"id":"B","text":"国家主席"},{"id":"C","text":"中央军事委员会"},{"id":"D","text":"全国人民代表大会"}],"answer":["D"],"analysis":{"point":"本题考查国家机构体系。全国人民代表大会是最高国家权力机关，它的职权有立法权、决定权、任免权和监督权。立法权就是制定和修改法律的权力。决定权就是决定国家重大事件的权力。任免权就是对国家机关的重要领导人的选举、任命、罢免的权力，包括中华人民共和国主席的选举，等等。监督权就是监督宪法和法律的实施，监督“一府两院一委”的工作。因此，选项D正确。","options":{"A":"国务院是中央级别“一府两院一委”中的“一府”。与题意不符，故不选。","B":"中华人民共和国主席是我国国家机构的重要组成部分，代表中华人民共和国进行国事活动。与题意不符，故不选。","C":"我国宪法规定：“中华人民共和国中央军事委员会领导全国武装力量。”中央军事委员会是全国武装力量的最高领导机关。中央军委实行主席负责制，由主席向全国人大和全国人大常委会负责。与题意不符，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-sixiu-test1-13","moduleId":"advanced","subjectId":"sixiu","chapter":"综合测试一","chapterKey":"综合测试一","n":13,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"思修 · 综合测试一 第 13 题"},"stem":"习近平总书记在《关于〈中共中央关于全面推进依法治国若干重大问题的决定〉的说明》中引用英国哲学家培根的一段话：“一次不公正的审判，其恶果甚至超过十次犯罪。因为犯罪虽是无视法律——好比污染了水流，而不公正的审判则毁坏法律——好比污染了水源。”这说明公正司法的重要性。公正司法是","choices":[{"id":"A","text":"社会公正的唯一标准"},{"id":"B","text":"社会公正的最终目标"},{"id":"C","text":"维护社会公平正义的最后一道防线"},{"id":"D","text":"维护社会公平正义的决定因素"}],"answer":["C"],"analysis":{"point":"本题考查全面依法治国基本格局中的公正司法。全面依法治国的基本格局：科学立法、严格执法、公正司法、全民守法。其中，公正是法治的生命线，是司法活动最高的价值追求，公正司法是维护社会公平正义的最后一道防线。因此，选项C正确。","options":{"A":"社会公正包含很多方面的内容，除司法公正外，还有执法公正，故排除。","B":"公正司法不是社会公正的最终目标，而是达到社会公正的手段之一，逻辑颠倒，故排除。","C":"（正确选项，分析见“解题思路”）","D":"公正司法是维护社会公平正义的引领性因素，而不是决定因素，故排除。"}}},{"id":"advanced-sixiu-test1-14","moduleId":"advanced","subjectId":"sixiu","chapter":"综合测试一","chapterKey":"综合测试一","n":14,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"思修 · 综合测试一 第 14 题"},"stem":"宪法是治国安邦的总章程，是党和人民意志的集中体现，是中国特色社会主义法律体系的核心，在全面依法治国中具有突出地位和重要作用。我国宪法对中国共产党领导地位和执政地位的规定，是对国家性质和根本制度的确认，集中体现了党的主张和人民意志的高度统一。这体现了宪法基本原则中的","choices":[{"id":"A","text":"党的领导原则"},{"id":"B","text":"人民当家作主原则"},{"id":"C","text":"尊重和保障人权原则"},{"id":"D","text":"社会主义法治原则"}],"answer":["A"],"analysis":{"point":"本题考查宪法的基本原则。党的领导原则体现在：我国宪法对中国共产党领导地位和执政地位的规定，既是对中国共产党领导人民在革命、建设、改革各个历史时期奋斗成果的确认，也是对国家性质和根本制度的确认，集中体现了党的主张和人民意志的高度统一。因此，选项A正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"都属于我国宪法的基本原则，但不符合题干的具体描述。故不选。","C":"都属于我国宪法的基本原则，但不符合题干的具体描述。故不选。","D":"都属于我国宪法的基本原则，但不符合题干的具体描述。故不选。"}}},{"id":"advanced-sixiu-test1-15","moduleId":"advanced","subjectId":"sixiu","chapter":"综合测试一","chapterKey":"综合测试一","n":15,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"思修 · 综合测试一 第 15 题"},"stem":"法律至上是指在国家或社会的所有规范中，法律是地位最高、效力最广、强制力最大的规范。所有国家机关、社会组织和公民个人都必须遵守法律，依法享有和行使法定职权与权利，承担和履行法定职责与义务，这体现法律至上的","choices":[{"id":"A","text":"优先适用性"},{"id":"B","text":"不可违抗性"},{"id":"C","text":"公平正义性"},{"id":"D","text":"普遍适用性"}],"answer":["D"],"analysis":{"point":"本题考查法律至上。法律至上具体表现为法律的普遍适用性、优先适用性和不可违抗性。其中，法律的普遍适用性，是指法律在本国主权范围内对所有人具有普遍的约束力。所有国家机关、社会组织和个人都必须遵守法律，依法享有和行使法定职权与权利，承担和履行法定职责与义务。因此，选项D正确。","options":{"A":"法律的优先适用性，是指当同一项社会关系同时受到多种社会规范的调整而多种社会规范又相互矛盾时，要优先考虑法律规范的适用。与题意不符，故不选。","B":"法律的不可违抗性，是指法律必须遵守，违反法律要受到惩罚。任何人不论权力大小、职位高低，只要有违法犯罪行为，就要受到法律制裁。与题意不符，故不选。","C":"法治思维主要包括法律至上、权力制约、公平正义、权利保障、程序正当等内容。公平正义是指社会的政治利益、经济利益和其他利益在全体社会成员之间合理、平等分配和占有。一般来讲，公平正义主要包括权利公平、机会公平、规则公平和救济公平。与题意不符，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-sixiu-test1-16","moduleId":"advanced","subjectId":"sixiu","chapter":"综合测试一","chapterKey":"综合测试一","n":16,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"思修 · 综合测试一 第 16 题"},"stem":"思想道德和法律都是调节人们思想行为、协调人际关系、维护社会秩序的重要手段。中国特色社会主义思想道德为法治建设提供思想指引和价值基础，主要表现在","choices":[{"id":"A","text":"社会主义思想道德为社会主义法律的制定、发展和完善提供价值准则"},{"id":"B","text":"社会主义思想道德能够促进人们自觉尊法学法守法用法，维护法律权威"},{"id":"C","text":"社会主义思想道德调整社会关系的范围和方式更加广泛灵活，与法治建设共同促进良好社会秩序的形成"},{"id":"D","text":"法治建设为中国特色社会主义思想道德建设提供制度支撑和法律保障"}],"answer":["A","B","C"],"analysis":{"point":"本题考查思想道德与法律的辩证关系。中国特色社会主义思想道德为法治建设提供思想指引和价值基础，主要表现在：第一，社会主义思想道德为社会主义法律的制定、发展和完善提供价值准则，是社会主义法律正当性和合理性的重要基础；第二，社会主义思想道德能够促进人们自觉尊法学法守法用法，维护法律权威；第三，社会主义思想道德调整社会关系的范围和方式更加广泛灵活，与法治建设共同促进良好社会秩序的形成。因此，选项A、B、C正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"属于法治建设对社会主义思想道德的作用，故不选。"}}},{"id":"advanced-sixiu-test1-17","moduleId":"advanced","subjectId":"sixiu","chapter":"综合测试一","chapterKey":"综合测试一","n":17,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"思修 · 综合测试一 第 17 题"},"stem":"走好人生之路，创造有价值的人生，需要协调好个人与社会的关系。下列关于个人与社会关系的说法，正确的有","choices":[{"id":"A","text":"个人完全由社会决定，对社会不具有能动作用"},{"id":"B","text":"个人应在社会发展中认识自我，调整和充实自我"},{"id":"C","text":"社会是个人生存和发展的基础，个人是构成社会的条件"},{"id":"D","text":"个人承担社会责任、履行社会义务是社会存在和发展必不可少的前提"}],"answer":["B","C","D"],"analysis":{"point":"本题考查个人与社会的辩证关系。从生物本能上看，人只有在社会中才能获得生命生存和延续的条件。从自我价值的实现上看，人只有在社会关系中才能找到实现自我价值的途径和可能。从道德要求上看，不能把享受个人权利作为承担社会责任与义务的先决条件。个人承担社会责任，履行社会义务，为社会作贡献，是社会存在和发展必不可少的前提。因此，选项B、C、D正确。","options":{"A":"社会不能完全决定个人，个人对社会具有能动作用，可以加速或延缓社会的发展，故不选。","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-sixiu-test1-18","moduleId":"advanced","subjectId":"sixiu","chapter":"综合测试一","chapterKey":"综合测试一","n":18,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"思修 · 综合测试一 第 18 题"},"stem":"周恩来就读东关模范学校时，正值中国社会发生剧烈变动的时期。校长亲自为学生上修身课，题目是“立命”。校长讲到精彩处突然停顿下来，问道：“诸生为何读书啊？”有人回答为名利而读书，有人回答为做官而读书。12岁的周恩来响亮地回答：“为中华之崛起而读书。”校长赞叹道：“有志者，当效周生啊！”周总理的故事告诉我们，要正确处理好个人理想和社会理想的关系，就要认识到","choices":[{"id":"A","text":"要坚持个人理想与社会理想的统一，在为实现社会理想而奋斗的过程中实现个人理想"},{"id":"B","text":"个人理想以社会理想为指引，社会理想是对个人理想的凝练和升华"},{"id":"C","text":"社会理想是最根本、最重要的，个人理想从属于社会理想"},{"id":"D","text":"社会理想的实现必须以个人理想的实现为前提和基础"}],"answer":["A","B","C"],"analysis":{"point":"本题考查个人理想与社会理想的辩证关系。摆正个人理想同社会理想的关系，要坚持个人理想与社会理想的统一，坚持个人奋斗目标与国家、民族的奋斗目标相统一，把个人理想融入社会理想之中，在为实现社会理想而奋斗的过程中实现个人理想。个人理想以社会理想为指引，社会理想是对个人理想的凝练和升华。在整个理想体系中，社会理想是最根本、最重要的，个人理想从属于社会理想。因此，选项A、B、C正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"个人理想的实现必须以社会理想的实现为前提和基础，故不选。"}}},{"id":"advanced-sixiu-test1-19","moduleId":"advanced","subjectId":"sixiu","chapter":"综合测试一","chapterKey":"综合测试一","n":19,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"思修 · 综合测试一 第 19 题"},"stem":"崇尚精神是中华民族的优秀传统。古人云：“一箪食，一瓢饮，在陋巷，人不堪其忧，回也不改其乐。”下列古文中，与这句话的含义大体一致的是","choices":[{"id":"A","text":"“自天子以至于庶人，壹是皆以修身为本”"},{"id":"B","text":"“为天地立心，为生民立命”"},{"id":"C","text":"“不义而富且贵，于我如浮云”"},{"id":"D","text":"“道德当身，故不以物惑”"}],"answer":["C","D"],"analysis":{"point":"本题考查中华民族崇尚精神的优秀传统。中华民族崇尚精神的优秀传统，首先表现为对物质生活与精神生活相互关系的独到理解，也表现为对理想的不懈追求，亦表现为对品格养成的重视。中华民族的先人们向往物质生活充实无忧、道德境界充分升华的大同世界。在对物质生活与精神生活相互关系的独到理解上，古圣先贤认为，人之所以异于禽兽，在于人有道德，有精神追求。物质生活固然为人所必需，但如果沉溺于物欲而不能自拔，则无异于禽兽。题干更加强调精神追求高于物质需要。因此，选项C、D正确。","options":{"A":"体现了“对品格养成的重视”，故不选。","B":"体现了“对理想的不懈追求”，故不选。","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-sixiu-test1-20","moduleId":"advanced","subjectId":"sixiu","chapter":"综合测试一","chapterKey":"综合测试一","n":20,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"思修 · 综合测试一 第 20 题"},"stem":"早在改革开放之初，邓小平同志就针对有人提出的“爱国可以不爱社会主义”的观点尖锐地指出：“有人说‘不爱社会主义不等于不爱国’，难道祖国是抽象的吗？不爱共产党领导的社会主义新中国，爱什么呢？港澳、台湾、海外的爱国同胞，不能要求他们都拥护社会主义，但是至少也不能反对社会主义的新中国，否则怎么叫爱祖国呢？至于对中华人民共和国领导下的每一个公民，每一个青年，我们的要求当然要更高一些。”这段话充分说明","choices":[{"id":"A","text":"爱国主义与爱社会主义是一致的"},{"id":"B","text":"爱国主义与拥护祖国统一是一致的"},{"id":"C","text":"大陆同胞和港澳台同胞可以求维护祖国统一之同，存意识形态之异"},{"id":"D","text":"中华儿女的任何一分子都不能损害社会主义祖国的利益"}],"answer":["A","B","C","D"],"analysis":{"point":"本题考查新时代的爱国主义。在当代中国，爱国主义首先体现在对社会主义中国的热爱上，这是中华人民共和国每一个公民必须坚持的立场和态度。爱国主义与拥护祖国统一也是一致的，这不仅是对生活在中国大陆的中国公民的要求，而且是对全体中华儿女包括港澳台同胞以及海外侨胞的基本要求。港澳、台湾、海外的中华儿女，不一定生活在社会主义制度下，但却不能损害社会主义祖国的利益，不能不拥护祖国统一。因此，选项A、B、C、D正确。\\n无干扰选项。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-sixiu-test1-21","moduleId":"advanced","subjectId":"sixiu","chapter":"综合测试一","chapterKey":"综合测试一","n":21,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"思修 · 综合测试一 第 21 题"},"stem":"人类社会的每一次跃进，人类文明的每一次升华，都伴随着文化的历史性进步，价值观也更加先进、完善，更加符合人类共同的价值追求。社会主义核心价值观具有超越以往一切社会核心价值观的先进性，主要表现在","choices":[{"id":"A","text":"倡导普遍适用、永恒存在的价值"},{"id":"B","text":"集中体现了社会主义的本质属性"},{"id":"C","text":"扎根于中华优秀传统文化的土壤"},{"id":"D","text":"吸收借鉴了一切人类优秀文化的先进价值"}],"answer":["B","C","D"],"analysis":{"point":"本题考查社会主义核心价值观。社会主义核心价值观具有超越以往一切社会核心价值观的先进性，它集中体现了社会主义的本质属性，扎根于中华优秀传统文化的土壤，吸收借鉴了一切人类优秀文化的先进价值，是反映人类社会发展进步的价值理念。因此，选项B、C、D正确。","options":{"A":"“普世价值”即普遍适用、永恒存在的价值。事实上，西方国家所谓的“普世价值”并非指人类道德评价、审美评价的普遍性或共性，而是特指资本主义价值观。故不选。","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-sixiu-test1-22","moduleId":"advanced","subjectId":"sixiu","chapter":"综合测试一","chapterKey":"综合测试一","n":22,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"思修 · 综合测试一 第 22 题"},"stem":"“道德作为一种特殊的社会意识形态，归根到底是由经济基础决定的，是社会经济关系的反映。”下列对这句话的理解，正确的有","choices":[{"id":"A","text":"社会经济关系的性质决定着各种道德体系的性质"},{"id":"B","text":"社会经济关系所表现出来的利益决定着各种道德的基本原则和主要规范"},{"id":"C","text":"在阶级社会中，道德必然带有阶级属性"},{"id":"D","text":"社会经济关系的变化必然引起道德的变化"}],"answer":["A","B","C","D"],"analysis":{"point":"本题考查道德的本质。道德作为一种特殊的社会意识形态，归根到底是由经济基础决定的，是社会经济关系的反映。首先，社会经济关系的性质决定着各种道德体系的性质；其次，社会经济关系所表现出来的利益决定着各种道德的基本原则和主要规范；再次，在阶级社会中，社会经济关系主要表现为阶级关系，因此，道德也必然带有阶级属性；最后，社会经济关系的变化必然引起道德的变化。因此，选项A、B、C、D正确。\\n无干扰选项。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-sixiu-test1-23","moduleId":"advanced","subjectId":"sixiu","chapter":"综合测试一","chapterKey":"综合测试一","n":23,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"思修 · 综合测试一 第 23 题"},"stem":"中国革命道德是对中华传统美德的继承和发展。传承和发扬中国革命道德，是弘扬中华传统美德的应有之义，是加强社会主义道德建设的客观需要，也是激励青年大学生锤炼优良道德品质的必然要求。中国革命道德和中华传统美德是一脉相承的，这表现在","choices":[{"id":"A","text":"中国革命道德是对中国优良传统道德的继承和发展"},{"id":"B","text":"中华传统美德是中国革命道德的渊源之一"},{"id":"C","text":"中国革命道德是中华传统美德新的升华和质的飞跃"},{"id":"D","text":"中国革命道德是马克思主义与中国革命、建设和改革伟大实践相结合的产物"}],"answer":["A","B","C"],"analysis":{"point":"本题考查中国革命道德和中华传统美德的相关性。中华传统美德是中国革命道德的渊源之一，从一定意义上说，没有中华传统美德的长期发展和丰厚积淀，就不可能有中国革命道德的形成和发展。中国革命道德继承了中国传统道德的精华，摒弃了中国传统道德的糟粕，是对中国优良传统道德的延续和发展，是超越了中华传统美德的时代局限而形成的一种崭新的道德。因此，选项A、B、C正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"说法正确，但题干讲的是“中国革命道德”与“中华传统美德”的关系，而选项D讲的是“中国革命道德”的实践基础，与“中华传统美德”无关，故不选。"}}},{"id":"advanced-sixiu-test1-24","moduleId":"advanced","subjectId":"sixiu","chapter":"综合测试一","chapterKey":"综合测试一","n":24,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"思修 · 综合测试一 第 24 题"},"stem":"一心为公、毫不利己、专门利人、无私奉献是为人民服务；顾全大局、先公后私、爱岗敬业、办事公道是为人民服务；热心公益、助人为乐、见义勇为、扶贫济困、帮残助残是为人民服务；诚实劳动、获取正当的个人利益也是为人民服务。这说明，为人民服务","choices":[{"id":"A","text":"是人类社会各阶级普遍的道德要求"},{"id":"B","text":"包含着社会主义道德的不同层次的要求"},{"id":"C","text":"只是对共产党员和一切先进分子的要求"},{"id":"D","text":"体现着社会主义道德建设先进性要求和广泛性要求的统一"}],"answer":["B","D"],"analysis":{"point":"本题考查为人民服务的概念。为人民服务是社会主义经济基础和人际关系的客观要求。各行各业的劳动者和建设者，只有社会分工的不同，没有高低贵贱之分。在以公有制为主体的经济基础上，在全体人民共同利益的基础上，在整个社会生产和生活的过程中，逐步形成了团结互助、平等友爱、共同进步的人际关系。因此，选项B、D正确。","options":{"A":"在资本主义国家，是为资产阶级服务，不存在为人民服务，故不选。","B":"（正确选项，分析见“解题思路”）","C":"虽然为人民服务是中国共产党践行的根本宗旨，但在社会主义国家，为人民服务是对每个人的要求，是社会主义道德的核心，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-sixiu-test1-25","moduleId":"advanced","subjectId":"sixiu","chapter":"综合测试一","chapterKey":"综合测试一","n":25,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"思修 · 综合测试一 第 25 题"},"stem":"在发展社会主义市场经济、构建社会主义和谐社会的过程中，更加需要大力倡导诚实守信的美德。这是因为诚实守信","choices":[{"id":"A","text":"是市场经济条件下经济活动的一项基本道德准则"},{"id":"B","text":"是职业道德的一项基本要求"},{"id":"C","text":"可以使利润最大化"},{"id":"D","text":"是做人的一项基本道德准则"}],"answer":["A","B","D"],"analysis":{"point":"本题考查诚实守信。在发展社会主义市场经济、构建社会主义和谐社会的过程中，更加需要大力倡导诚实守信的美德。这是因为：①诚实守信是市场经济条件下经济活动的一项基本道德准则。市场经济是讲究信用的经济，我国实行的是社会主义市场经济，更要注重发挥包括诚信在内的社会主义道德对推动社会主义市场经济健康发展的巨大作用。②诚实守信是职业道德的一项基本要求。它要求各行各业的从业人员在自己的工作岗位上，都要诚实劳动、实事求是，杜绝弄虚作假、虚报浮夸现象。③诚实守信是做人的一项基本道德准则。它要求公民为人诚恳、待人诚实、做事实在、追求信誉等。因此，选项A、B、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"不是提倡诚实守信的原因，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-sixiu-test1-26","moduleId":"advanced","subjectId":"sixiu","chapter":"综合测试一","chapterKey":"综合测试一","n":26,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"思修 · 综合测试一 第 26 题"},"stem":"法律的运行是一个从创制、实施到实现的过程。这个过程主要包括法律制定、法律执行、法律适用、法律遵守等环节。其中，把法定的权利和义务转化为现实的权利和义务，把文本上的法律转化为现实中的法律，属于","choices":[{"id":"A","text":"法律制定"},{"id":"B","text":"法律执行"},{"id":"C","text":"法律适用"},{"id":"D","text":"法律遵守"}],"answer":["B","C","D"],"analysis":{"point":"本题考查法律运行。法律制定是国家对权利和义务，即社会利益和负担进行的权威性分配；法律的执行、适用、遵守则是把法定的权利和义务转化为现实的权利和义务，把文本上的法律转化为现实中的法律。因此，选项B、C、D正确。","options":{"A":"法律制定是国家对权利和义务，即社会利益和负担进行的权威性分配，故不选。","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-sixiu-test1-27","moduleId":"advanced","subjectId":"sixiu","chapter":"综合测试一","chapterKey":"综合测试一","n":27,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"思修 · 综合测试一 第 27 题"},"stem":"我国法律文化有悠久的历史和传承，据《说文解字》阐释，汉语中“法”的古体是“灋”。“灋，刑也，平之如水，从水；廌，所以触不直者去之，从去。”在古代，“法”主要表现为“刑”或“刑律”，“刑”既有刑戮、罚罪之意，也有规范之意；“廌”也称“獬豸”，是神话中的独角兽，它公正不阿，善断是非曲直。上述材料表明，在传统文化中人们对法律的理解和诉求是","choices":[{"id":"A","text":"法律具有至高无上的地位"},{"id":"B","text":"法律体现了君权神授的思想"},{"id":"C","text":"法律富含着公平如水、正义神圣的深刻意蕴"},{"id":"D","text":"法律寄托着惩恶扬善、匡扶正义的价值追求"}],"answer":["C","D"],"analysis":{"point":"本题考查对法律的理解。考生要重点关注的是，这是一道具有代表性的多项选择题，作答这类题型一定要符合两个依据：一是紧扣材料；二是紧扣知识点。中国是一个文明古国，对法律有着深刻的认识和理解，题干中对“法”字的内涵作了详细解释。“法”分为了“水”“廌”，分别体现了中国古代法律思想中“公平正义”“惩恶扬善”的朴素价值。因此，选项C、D正确。","options":{"A":"没有紧扣题干，也不符合常识，法律至高无上是当今的思想，在我国封建社会中还没有这种思想，故不选。","B":"没有紧扣题干，题干中并没有强调有关君权神授的内容，故不选。","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-sixiu-test1-28","moduleId":"advanced","subjectId":"sixiu","chapter":"综合测试一","chapterKey":"综合测试一","n":28,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"思修 · 综合测试一 第 28 题"},"stem":"马克思、恩格斯在《共产党宣言》中指出：“你们的观念本身是资产阶级的生产关系和所有制关系的产物，正像你们的法不过是被奉为法律的你们这个阶级的意志一样，而这种意志的内容是由你们这个阶级的物质生活条件来决定的。”这句话深刻地揭示了法律的本质，即“法律是统治阶级意志的体现”。下列对这句话的理解，正确的有","choices":[{"id":"A","text":"法律所体现的是统治阶级的整体意志"},{"id":"B","text":"法律是专门为被统治阶级制定的"},{"id":"C","text":"法律所体现的统治阶级意志，并不是统治阶级意志的全部"},{"id":"D","text":"统治阶级的意志就是法律"}],"answer":["A","C"],"analysis":{"point":"本题考查法律的本质。法律是统治阶级意志的体现。法律所体现的统治阶级意志具有整体性，不是统治阶级内部个别人的意志，也不是统治者个人意志的简单相加。法律所体现的统治阶级意志，并不是统治阶级意志的全部，仅仅是上升为国家意志的那部分意志。除了法律，统治阶级的意志还体现在国家政策、统治阶级的道德、最高统治者的言论等形式中。因此，选项A、C正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"法律维护的是统治阶级的整体利益，统治阶级也要遵守法律，故不选。","C":"（正确选项，分析见“解题思路”）","D":"法律不是统治阶级意志的全部，还包括国家政策、道德等形式，故不选。"}}},{"id":"advanced-sixiu-test1-29","moduleId":"advanced","subjectId":"sixiu","chapter":"综合测试一","chapterKey":"综合测试一","n":29,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"思修 · 综合测试一 第 29 题"},"stem":"中国特色社会主义法治道路本质上是中国特色社会主义道路在法治领域的具体体现。既要立足当前，运用法治思维和法治方式解决经济社会发展面临的深层次问题；又要着眼长远，筑法治之基、行法治之力、积法治之势，促进各方面制度更加成熟更加定型，为党和国家事业发展提供长期性的制度保障。走中国特色社会主义法治道路是","choices":[{"id":"A","text":"由我国社会主义国家性质决定的"},{"id":"B","text":"由我国当前面临的复杂国际形势决定的"},{"id":"C","text":"立足我国基本国情的必然选择"},{"id":"D","text":"历史的必然结论"}],"answer":["A","C","D"],"analysis":{"point":"本题考查坚持走中国特色社会主义法治道路。走中国特色社会主义法治道路，是历史的必然结论，是由我国社会主义国家性质决定的，是立足我国基本国情的必然选择。因此，选项A、C、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"走中国特色社会主义法治道路是中国法治的发展方向，不是由国际形势决定的，故不选。","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-sixiu-test1-30","moduleId":"advanced","subjectId":"sixiu","chapter":"综合测试一","chapterKey":"综合测试一","n":30,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"思修 · 综合测试一 第 30 题"},"stem":"我国在建设社会主义法治国家的道路上不断探索，继2011年宣布中国特色社会主义法律体系已经形成之后，2014年又提出“建设中国特色社会主义法治体系”的目标。从“法律体系”到“法治体系”的变化体现在","choices":[{"id":"A","text":"法治体系不仅有法律规范体系，还包括法治实施体系、法治监督体系、法治保障体系和党内法规体系"},{"id":"B","text":"法治体系强调科学立法、严格执法、公正司法、全民守法"},{"id":"C","text":"法治体系既要有法律的制定，也要保证法律的落实"},{"id":"D","text":"法治体系不仅仅是静态的法律文本，而且也是动态的法的实现过程"}],"answer":["A","B","C","D"],"analysis":{"point":"本题考查中国特色社会主义法治体系。建设中国特色社会主义法治体系就是在中国共产党的领导下，坚持中国特色社会主义制度，形成完备的法律规范体系、高效的法治实施体系、严密的法治监督体系、有力的法治保障体系，形成完善的党内法规体系，坚持依法治国、依法执政、依法行政共同推进，坚持法治国家、法治政府、法治社会一体建设，实现科学立法、严格执法、公正司法、全民守法，促进国家治理体系和治理能力现代化。由此可以看出，法治体系既有法律的制定，也有法律的落实。法律体系只是具体的制度内容，是静态的法律文本，没有强调法律的落实。而法治体系不仅仅是静态的法律文本，而且也是动态的法的实现过程。因此，选项A、B、C、D正确。\\n无干扰选项。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-sixiu-test2-1","moduleId":"advanced","subjectId":"sixiu","chapter":"综合测试二","chapterKey":"综合测试二","n":1,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"思修 · 综合测试二 第 1 题"},"stem":"马克思说：“在选择职业时，我们应该遵循的主要指针是人类的幸福和我们自身的完美。”在这里，马克思所说的以“我们自身的完美”为主要指针，就是追求我们自身的人格高尚、才智发展、生活幸福。这是","choices":[{"id":"A","text":"人生的现实境遇"},{"id":"B","text":"人生的存在状态"},{"id":"C","text":"人生的自我价值"},{"id":"D","text":"人生的社会价值"}],"answer":["C"],"analysis":{"point":"本题考查人生的自我价值。人生的自我价值，是个体的人生活动对自己的生存和发展所具有的价值，主要表现为对自身物质和精神需要的满足程度。题干中的“人格高尚、才智发展、生活幸福”就是自我价值的体现。因此，选项C正确。","options":{"A":"均是指个人所面临的实际条件和实际生存状态，题干要求选出人生应该追求的内容，而并非现状，故不选。","B":"均是指个人所面临的实际条件和实际生存状态，题干要求选出人生应该追求的内容，而并非现状，故不选。","C":"（正确选项，分析见“解题思路”）","D":"人生的社会价值，是指个体的实践活动对社会、他人所具有的价值，而题干表述的是对个人人格、才智以及生活的追求，故不选。"}}},{"id":"advanced-sixiu-test2-2","moduleId":"advanced","subjectId":"sixiu","chapter":"综合测试二","chapterKey":"综合测试二","n":2,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"思修 · 综合测试二 第 2 题"},"stem":"社会主义核心价值观，为人们确定和实现人生价值提供了基本遵循。人生价值评价主要是看一个人的实践活动是否符合社会发展的客观规律，其评价的根本尺度是","choices":[{"id":"A","text":"历史标准"},{"id":"B","text":"经济标准"},{"id":"C","text":"政治标准"},{"id":"D","text":"文化标准"}],"answer":["A"],"analysis":{"point":"本题考查评价人生价值的根本尺度。无论从唯物史观的角度，还是从人生价值评价的角度，评价人生价值的根本尺度都是看一个人的实践活动是否符合社会发展的客观规律，是否促进了历史的进步。所以，评价人生价值的根本尺度是历史标准。因此，选项A正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"经济标准、政治标准、文化标准，三者都属于历史标准的构成维度，选择三者中的任意一项均过于片面。故排除。","C":"经济标准、政治标准、文化标准，三者都属于历史标准的构成维度，选择三者中的任意一项均过于片面。故排除。","D":"经济标准、政治标准、文化标准，三者都属于历史标准的构成维度，选择三者中的任意一项均过于片面。故排除。"}}},{"id":"advanced-sixiu-test2-3","moduleId":"advanced","subjectId":"sixiu","chapter":"综合测试二","chapterKey":"综合测试二","n":3,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"思修 · 综合测试二 第 3 题"},"stem":"“宝剑锋从磨砺出，梅花香自苦寒来。”奋斗是艰辛的，艰难困苦、玉汝于成。这要求我们在生活中要树立正确的","choices":[{"id":"A","text":"苦乐观"},{"id":"B","text":"顺逆观"},{"id":"C","text":"得失观"},{"id":"D","text":"荣辱观"}],"answer":["A"],"analysis":{"point":"本题考查辩证对待人生矛盾。苦与乐既对立又统一，在一定条件下相互转化。由题干可知，真正的快乐只能由奋斗的艰辛转化而来。青年在成长过程中，要准确把握苦与乐的辩证关系，努力做迎难而上、艰苦奋斗的开拓者。因此，选项A正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"无论是顺境还是逆境，对人生的作用都是双重的，关键是怎样去认识和对待它们。与题意不符，故不选。","C":"得失观要求我们不要拘泥于个人利益的得失，不要满足于一时的“得”，也不要惧怕一时的“失”。与题意不符，故不选。","D":"荣辱观对个人的思想行为具有鲜明的导向和调节作用，阐述的是是非善恶、荣辱美丑的选择。与题意不符，故不选。"}}},{"id":"advanced-sixiu-test2-4","moduleId":"advanced","subjectId":"sixiu","chapter":"综合测试二","chapterKey":"综合测试二","n":4,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"思修 · 综合测试二 第 4 题"},"stem":"每一代人有每一代人的理想，每一代人有每一代人的使命。习近平总书记曾经在致全国青联与全国学联的信中强调：“士不可以不弘毅，任重而道远。国家的前途，民族的命运，人民的幸福，是当代中国青年必须和必将承担的重任。一代青年有一代青年的历史际遇。只有同人民一起梦想，青春才能无悔。”从这段论述来看，理想具有","choices":[{"id":"A","text":"实践性"},{"id":"B","text":"时代性"},{"id":"C","text":"超越性"},{"id":"D","text":"执着性"}],"answer":["B"],"analysis":{"point":"本题考查理想的特征。题干中习近平总书记的话，“国家的前途，民族的命运，人民的幸福，是当代中国青年必须和必将承担的重任。一代青年有一代青年的历史际遇。只有同人民一起梦想，青春才能无悔”，体现了理想的时代性，理想同任何一种社会意识形式一样，都是一定时代的产物，都带着特定历史时代的烙印。因此，选项B正确。","options":{"A":"实践性强调的是理想与主体行为之间的关系，故不选。","B":"（正确选项，分析见“解题思路”）","C":"超越性是指理想源于现实又超越现实，故不选。","D":"执着性属于信念的特征，故不选。"}}},{"id":"advanced-sixiu-test2-5","moduleId":"advanced","subjectId":"sixiu","chapter":"综合测试二","chapterKey":"综合测试二","n":5,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"思修 · 综合测试二 第 5 题"},"stem":"“现实是此岸，理想是彼岸。中间隔着湍急的河流，行动则是架在川上的桥梁。”这句话形象地说明了","choices":[{"id":"A","text":"理想就是现实"},{"id":"B","text":"理想不能成为现实"},{"id":"C","text":"理想是可以自发实现的"},{"id":"D","text":"理想的实现必须落实在行动上"}],"answer":["D"],"analysis":{"point":"本题考查理想的实现途径。现实是理想的基础，理想是未来的现实。一方面，现实中包含着理想的因素，孕育着理想的发展；另一方面，理想中也包含着现实，既包含着现实中必然发展的因素，又包含着由理想转化为现实的条件，在一定条件下，理想可以转化为未来的现实。脱离现实谈理想，理想就会成为空想。因此，理想的实现必须落实在行动上。因此，选项D正确。","options":{"A":"不能将理想与现实等同，故不选。","B":"在一定条件下，理想可以转化为未来的现实，故不选。","C":"理想的实现依靠实践，而实践是具有能动性的，理想不可能自发实现，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-sixiu-test2-6","moduleId":"advanced","subjectId":"sixiu","chapter":"综合测试二","chapterKey":"综合测试二","n":6,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"思修 · 综合测试二 第 6 题"},"stem":"《朱子语类》中记录了朱熹这样一段名言：“人所以异者，以其有仁义礼智。若为子而孝，为弟而悌，禽兽岂能之哉？”这说明中华民族自古就","choices":[{"id":"A","text":"重视整体利益，强调责任奉献"},{"id":"B","text":"提倡人伦价值，重视道德义务"},{"id":"C","text":"追求精神境界，向往理想人格"},{"id":"D","text":"强调道德修养，注重道德践履"}],"answer":["B"],"analysis":{"point":"本题考查中华民族崇尚精神的优秀传统。朱熹这段名言的意思是，人同动物的区别在于人是有仁义礼智精神、注重人伦道德的，而禽兽则没有。在四个选项中，只有选项B最符合题意。因此，选项B正确。","options":{"A":"都是中华传统美德的内容，但是与题干中朱熹的话不符，故不选。","B":"（正确选项，分析见“解题思路”）","C":"都是中华传统美德的内容，但是与题干中朱熹的话不符，故不选。","D":"都是中华传统美德的内容，但是与题干中朱熹的话不符，故不选。"}}},{"id":"advanced-sixiu-test2-7","moduleId":"advanced","subjectId":"sixiu","chapter":"综合测试二","chapterKey":"综合测试二","n":7,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"思修 · 综合测试二 第 7 题"},"stem":"中国人民始终革故鼎新、自强不息，开发和建设了祖国辽阔秀丽的大好河山，开拓了波涛万顷的辽阔海疆，开垦了物产丰富的广袤粮田，治理了桀骜不驯的千百条大江大河，中国人民拥有的一切都凝聚着中国人的聪明才智，浸透着中国人的辛勤汗水，蕴含着中国人的巨大牺牲。这体现了中华民族的","choices":[{"id":"A","text":"伟大创造精神"},{"id":"B","text":"伟大奋斗精神"},{"id":"C","text":"伟大团结精神"},{"id":"D","text":"伟大梦想精神"}],"answer":["B"],"analysis":{"point":"本题考查伟大民族精神。习近平总书记在第十三届全国人大一次会议上的重要讲话中，深刻阐述了中国人民的伟大创造精神、伟大奋斗精神、伟大团结精神、伟大梦想精神，赋予了伟大民族精神以新的时代内涵。在做这种类型的题目时，考生应当留意以下辨析方法：如果题干强调中华民族一直以来创造了大量的物质文明与精神文明，则体现了伟大创造精神；如果题干强调中华民族克服了种种困难发展到今天，则体现了伟大奋斗精神；如果题干强调中华民族团结一致、各民族共同繁荣，则体现了伟大团结精神；如果题干强调中华民族始终心怀梦想、不懈追求，一定能够实现中华民族伟大复兴，则体现了伟大梦想精神。因此，选项B正确。","options":{"A":"伟大创造精神强调的是创造，故不选。","B":"（正确选项，分析见“解题思路”）","C":"伟大团结精神强调的是团结，故不选。","D":"伟大梦想精神强调的是梦想，故不选。"}}},{"id":"advanced-sixiu-test2-8","moduleId":"advanced","subjectId":"sixiu","chapter":"综合测试二","chapterKey":"综合测试二","n":8,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"思修 · 综合测试二 第 8 题"},"stem":"中国特色社会主义进入新时代，为了大力弘扬爱国主义精神，中共中央、国务院印发了《新时代爱国主义教育实施纲要》，明确规定新时代爱国主义的鲜明主题是","choices":[{"id":"A","text":"坚持爱国和爱党、爱社会主义高度统一"},{"id":"B","text":"对民族和文化的归属感、认同感的统一"},{"id":"C","text":"实现中华民族伟大复兴的中国梦"},{"id":"D","text":"坚持维护祖国统一和民族团结"}],"answer":["C"],"analysis":{"point":"本题考查新时代的爱国主义。实现中华民族伟大复兴的中国梦是新时代爱国主义的鲜明主题。因此，选项C正确。","options":{"A":"当代中国，爱国主义的本质是坚持爱国和爱党、爱社会主义高度统一。","B":"爱国主义是人们对自已故土家园、民族和文化的归属感、认同感、尊严感与荣誉感的统一。","C":"（正确选项，分析见“解题思路”）","D":"新时代爱国主义教育的着力点是坚持维护祖国统一和民族团结。"}}},{"id":"advanced-sixiu-test2-9","moduleId":"advanced","subjectId":"sixiu","chapter":"综合测试二","chapterKey":"综合测试二","n":9,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"思修 · 综合测试二 第 9 题"},"stem":"任何一种价值观都不可能凭空产生，总有其特定的历史底色和精神脉络。牢固的核心价值观，都有其固有的根本。抛弃传统、丢掉根本，就等于割断了自己的精神命脉。社会主义核心价值观的历史底蕴是","choices":[{"id":"A","text":"中华优秀传统文化"},{"id":"B","text":"中国特色社会主义建设实践"},{"id":"C","text":"先进性、人民性和真实性"},{"id":"D","text":"外国的先进文化"}],"answer":["A"],"analysis":{"point":"本题考查社会主义核心价值观的相关内容。中华优秀传统文化是社会主义核心价值观历史底蕴的集中体现，是涵养社会主义核心价值观的重要源泉，是中华民族的精神命脉。因此，选项A正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"中国特色社会主义建设实践是社会主义核心价值观的现实基础，故不选。","C":"先进性、人民性和真实性是社会主义核心价值观的道义力量，故不选。","D":"社会主义核心价值观是中国的，不是外国的。对于外国的先进文化，我们可以有所借鉴，但不能说其是社会主义核心价值观的历史底蕴。故不选。"}}},{"id":"advanced-sixiu-test2-10","moduleId":"advanced","subjectId":"sixiu","chapter":"综合测试二","chapterKey":"综合测试二","n":10,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"思修 · 综合测试二 第 10 题"},"stem":"早在1939年毛泽东就提出，区别革命道德和一切剥削阶级道德的根本分界线是","choices":[{"id":"A","text":"革命利益"},{"id":"B","text":"全心全意为人民服务"},{"id":"C","text":"集体主义原则"},{"id":"D","text":"中国优良道德传统"}],"answer":["B"],"analysis":{"point":"本题考查中国革命道德。全心全意为人民服务作为贯穿中国革命道德始终的一根红线，是中国共产党在中国革命实践中的一个伟大创造，对中国的革命、建设和改革事业产生了极其重大的推动作用。因此，选项B正确。","options":{"A":"共产党人和革命者从事革命活动是为革命利益而奋斗，始终把革命利益放在首位。与题意不符，故不选。","B":"（正确选项，分析见“解题思路”）","C":"集体主义是社会主义道德的原则。与题意不符，故不选。","D":"中国优良道德传统是中华传统文化中不可分割的组成部分，是人类文明发展的重要精神财富，是我国社会主义道德建设的源头活水。与题意不符，故不选。"}}},{"id":"advanced-sixiu-test2-11","moduleId":"advanced","subjectId":"sixiu","chapter":"综合测试二","chapterKey":"综合测试二","n":11,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"思修 · 综合测试二 第 11 题"},"stem":"毛泽东曾说：“我们这个民族有数千年的历史，有它的特点，有它的许多珍贵品质。对于这些，我们还是小学生。今天的中国是历史的中国的一个发展；我们是马克思主义的历史唯物主义者，我们不应当割断历史。从孔夫子到孙中山，我们应当给以总结，继承这一份珍贵的遗产。”根据这一说法，中国特色社会主义道德建设应当","choices":[{"id":"A","text":"与国际社会相接轨"},{"id":"B","text":"与社会主义法律相协调"},{"id":"C","text":"与中华民族传统美德相承接"},{"id":"D","text":"与社会主义市场经济相适应"}],"answer":["C"],"analysis":{"point":"本题考查社会主义道德建设的内容。正确对待中华民族传统道德，要坚持马克思主义的立场、观点和方法，既不能全盘肯定、全面照搬，也不能全盘否定、全面抛弃。继承和弘扬优良的中华民族传统道德，特别是那些反映普遍性、共同性和一般性的道德要求，对我们今天的道德实践仍然具有借鉴意义。因此，选项C正确。","options":{"A":"与题干无关，题干问的是如何对待数千年的中华民族文明史，应该秉承马克思主义的批判精神对中华民族传统道德加以继承，故不选。","B":"社会主义法律是社会主义道德的支撑，故不选。","C":"（正确选项，分析见“解题思路”）","D":"经济基础决定上层建筑，但题干没有涉及社会主义市场经济和社会主义道德的关系，故不选。"}}},{"id":"advanced-sixiu-test2-12","moduleId":"advanced","subjectId":"sixiu","chapter":"综合测试二","chapterKey":"综合测试二","n":12,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"思修 · 综合测试二 第 12 题"},"stem":"法律制定就是指有立法权的国家机关依照法定职权和程序制定规范性法律文件的活动，是法律运行的起始性和关键性环节。根据我国宪法、立法法等法律的规定，负责制定行政法规的主体是","choices":[{"id":"A","text":"全国人民代表大会"},{"id":"B","text":"全国人民代表大会常务委员会"},{"id":"C","text":"国务院"},{"id":"D","text":"国务院各部门"}],"answer":["C"],"analysis":{"point":"本题考查法律制定。根据我国宪法、立法法等法律的规定，全国人民代表大会及其常务委员会行使国家立法权，负责宪法和法律的制定、修改、废止和解释工作。国务院有权根据宪法和法律，制定行政法规。国务院各部门可以根据宪法、法律和行政法规，在本部门的权限范围内，制定部门规章。中央军委有权根据宪法和法律制定军事法规。省、自治区、直辖市的人民代表大会及其常委会根据本行政区域的具体情况和实际需要，在不同宪法、法律和行政法规相抵触的前提下，可以制定地方性法规。因此，选项C正确。","options":{"A":"全国人民代表大会和全国人民代表大会常务委员会行使国家立法权，负责宪法和法律的制定、修改、废止和解释工作，故不选。","B":"全国人民代表大会和全国人民代表大会常务委员会行使国家立法权，负责宪法和法律的制定、修改、废止和解释工作，故不选。","C":"（正确选项，分析见“解题思路”）","D":"国务院各部门可以根据宪法、法律和行政法规，在本部门的权限范围内，制定部门规章，故不选。"}}},{"id":"advanced-sixiu-test2-13","moduleId":"advanced","subjectId":"sixiu","chapter":"综合测试二","chapterKey":"综合测试二","n":13,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"思修 · 综合测试二 第 13 题"},"stem":"在广义上，法律执行是指国家机关及其公职人员，在国家和公共事务管理中依照法定职权和程序，贯彻和实施法律的活动。下列说法正确的是","choices":[{"id":"A","text":"在狭义上，法律执行是指国家立法机关执行法律的活动"},{"id":"B","text":"我国所有的法律法规都是由行政机关执行的"},{"id":"C","text":"法律执行必须坚持合法性、合理性、信赖保护、效率等基本原则"},{"id":"D","text":"我国行政执法的主体仅限于两类：一是中央和地方各级政府；二是各级政府中享有执法权的下属行政机构"}],"answer":["C"],"analysis":{"point":"本题考查法律执行的相关内容。行政执法是法律实施和实现的重要环节，必须坚持合法性、合理性、信赖保护、效率等基本原则。因此，选项C正确。","options":{"A":"狭义的法律执行是指国家行政机关及其公职人员执行法律的活动，而不是立法机关。故不选。","B":"我国大部分的法律法规是由行政机关执行的，而不是所有的法律法规。故不选。","C":"（正确选项，分析见“解题思路”）","D":"我国行政执法的主体大体分为两类：一是中央和地方各级政府；二是各级政府中享有执法权的下属行政机构。此外，法律授权的社会组织、行政机关依法委托的社会组织也可以在一定范围内执行法律并承担相应的法律责任。表述不完整，故不选。"}}},{"id":"advanced-sixiu-test2-14","moduleId":"advanced","subjectId":"sixiu","chapter":"综合测试二","chapterKey":"综合测试二","n":14,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"思修 · 综合测试二 第 14 题"},"stem":"建设中国特色社会主义法治体系是全面依法治国的总抓手。建设中国特色社会主义法治体系，就是要形成完备的法律规范体系、高效的法治实施体系、严密的法治监督体系、有力的法治保障体系，形成完善的党内法规体系。其中，建设中国特色社会主义法治体系的重点是","choices":[{"id":"A","text":"形成完备的法律规范体系"},{"id":"B","text":"建设有力的法治保障体系"},{"id":"C","text":"形成完善的党内法规体系"},{"id":"D","text":"建设高效的法治实施体系"}],"answer":["D"],"analysis":{"point":"本题考查建设中国特色社会主义法治体系的重点。建设中国特色社会主义法治体系，就是要形成完备的法律规范体系、高效的法治实施体系、严密的法治监督体系、有力的法治保障体系，形成完善的党内法规体系。形成完备的法律规范体系，是中国特色社会主义法治体系的前提，是法治国家、法治政府、法治社会的制度基础；建设高效的法治实施体系，是建设中国特色社会主义法治体系的重点；形成严密的法治监督体系，是宪法法律有效实施的重要保障；建设有力的法治保障体系，是全面依法治国的重要依托；形成完善的党内法规体系，是中国特色社会主义法治体系的本质要求和重要内容。因此，选项D正确。","options":{"A":"并不是建设中国特色社会主义法治体系的重点，上述解析中已作了说明，故不选。","B":"并不是建设中国特色社会主义法治体系的重点，上述解析中已作了说明，故不选。","C":"并不是建设中国特色社会主义法治体系的重点，上述解析中已作了说明，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-sixiu-test2-15","moduleId":"advanced","subjectId":"sixiu","chapter":"综合测试二","chapterKey":"综合测试二","n":15,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"思修 · 综合测试二 第 15 题"},"stem":"法安天下，德润人心。习近平总书记多次以德治与法治为关键词，重申形成风清气正的政治生态。他强调，要将法治和德治并举，下大力气拔“烂树”、治“病树”、正“歪树”，治树护林。思想道德与法律相辅相成，共同服务于一定的经济基础，其中","choices":[{"id":"A","text":"思想道德为法律体系提供价值基础"},{"id":"B","text":"法律为社会主义思想道德提供制度保障"},{"id":"C","text":"既要发挥法律的教化和引领作用，也要发挥思想道德的规范和强制作用"},{"id":"D","text":"思想道德和法律在调节领域、调节方式、调节目标等方面存在很大不同"}],"answer":["A","B","D"],"analysis":{"point":"本题考查思想道德与法律的辩证关系。思想道德为法律体系提供价值基础，能够为法律的制定、发展和完善提供价值准则，是社会主义法律正当性和合理性的重要基础。选项A正确。法律为思想道德提供制度保障，社会主义法律通过对社会主义思想道德的基本原则加以确认，为思想道德建设提供国家强制力的保障。选项B正确。思想道德和法律都是调节人们思想行为、协调人际关系、维护社会秩序的重要手段，但二者在调节领域、调节方式、调节目标等方面存在很大不同。选项D正确。因此，选项A、B、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"混淆了思想道德和法律发挥作用的方式，国家和社会治理需要思想道德和法律共同发挥作用，既要发挥法律的规范和强制作用，又要发挥思想道德的教化和引领作用。表述错误，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-sixiu-test2-16","moduleId":"advanced","subjectId":"sixiu","chapter":"综合测试二","chapterKey":"综合测试二","n":16,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"思修 · 综合测试二 第 16 题"},"stem":"马克思主义作为我们立党立国的根本指导思想，是近代以来中国历史发展的必然结果，是中国人民长期探索的历史选择。当代青年只有确立马克思主义的科学信仰，才能真正确立崇高的理想信念，在错综复杂的社会现象中看清本质、明确方向，为服务人民、奉献社会作出更大的贡献。青年要确立马克思主义信仰，是因为马克思主义是","choices":[{"id":"A","text":"我们认识世界、改造世界的强大思想武器"},{"id":"B","text":"科学的理论，创造性地揭示了人类社会发展规律"},{"id":"C","text":"人民的理论，第一次创立了人民实现自身解放的思想体系"},{"id":"D","text":"跨越一切阶级、不带有任何阶级立场的包容性理论"}],"answer":["A","B","C"],"analysis":{"point":"本题考查马克思主义信仰。青年要确立马克思主义信仰的原因：第一，马克思主义是我们认识世界、改造世界的强大思想武器；第二，马克思主义是科学的理论，创造性地揭示了人类社会发展规律；第三，马克思主义是人民的理论，第一次创立了人民实现自身解放的思想体系；第四，马克思主义是实践的理论，指引着人民改造世界的行动；第五，马克思主义是不断发展的开放的理论，始终站在时代前沿。因此，选项A、B、C正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"说法错误，马克思主义是具有阶级属性的，它是为无产阶级服务的，是带有人民立场的。故不选。"}}},{"id":"advanced-sixiu-test2-17","moduleId":"advanced","subjectId":"sixiu","chapter":"综合测试二","chapterKey":"综合测试二","n":17,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"思修 · 综合测试二 第 17 题"},"stem":"1992年，心怀报国之志的黄大年被公派到英国攻读博士。2009年，他毅然放弃国外优越的条件，回到母校吉林大学从事科研和教学工作。他为实现强国梦想奉献全部，经常工作到凌晨两三点钟，几乎没有休过寒暑假和节假日，无私忘我工作到生命最后一息。他平均每年出差130余天，最多的一年出差160余天，3次累倒在工作岗位上。黄大年的先进事迹对我们的启示有","choices":[{"id":"A","text":"自强不息是中华民族生生不息的力量源泉"},{"id":"B","text":"一个人只有先爱岗敬业，才能做到奉献社会"},{"id":"C","text":"科学没有国界，但科学家是有祖国的"},{"id":"D","text":"爱国行为与爱国思想、情感是一致的"}],"answer":["A","B","C","D"],"analysis":{"point":"本题考查爱国主义精神。黄大年的先进事迹告诉我们，爱国行为要始终与爱国思想、情感一致。科学研究需要脚踏实地的精神，也需要自强不息的民族精神。职业道德最基本的要求是爱岗敬业，最高层次的要求是奉献社会。因此，选项A、B、C、D正确。\\n无干扰选项。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-sixiu-test2-18","moduleId":"advanced","subjectId":"sixiu","chapter":"综合测试二","chapterKey":"综合测试二","n":18,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"思修 · 综合测试二 第 18 题"},"stem":"爱国主义是一个古老而又现实的话题。在处理个人与祖国的关系问题上，爱国主义是重要的道德要求。古人描绘爱国主义优良传统的诗句有","choices":[{"id":"A","text":"“臣心一片磁针石，不指南方不肯休”"},{"id":"B","text":"“一片丹心图报国，两行清泪为忠家”"},{"id":"C","text":"“一身报国有万死，双鬓向人无再青”"},{"id":"D","text":"“愿得此身长报国，何须生入玉门关”"}],"answer":["A","B","C","D"],"analysis":{"point":"本题考查爱国主义的优良传统。“臣心一片磁针石，不指南方不肯休”，诗人以指南针比喻自己的忠忱，表明自己对南宋王朝的忠心至死不变。“一片丹心图报国，两行清泪为忠家”，戍边御敌是为了保卫国家，而保卫国家就不能在父母膝前尽孝，不能与亲朋好友共欢乐，故因思亲而流泪。“一身报国有万死，双鬓向人无再青”是爱国诗人陆游对时光不再、壮志难酬、报国无门的慨叹。陆游十分爱国，想以身报国，万死不辞，无奈两鬓斑白，故发感慨。“愿得此身长报国，何须生入玉门关”出自戴叔伦的《塞上曲二首·其二》，诗人愿以自己的身躯报效国家，不在乎是否能活着回到玉门关，表明了诗人有视死如归的情怀。因此，选项A、B、C、D正确。\\n无干扰选项。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-sixiu-test2-19","moduleId":"advanced","subjectId":"sixiu","chapter":"综合测试二","chapterKey":"综合测试二","n":19,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"思修 · 综合测试二 第 19 题"},"stem":"实现中华民族伟大复兴的中国梦，必须弘扬中国精神，就是以爱国主义为核心的民族精神和以改革创新为核心的时代精神。其中，时代精神","choices":[{"id":"A","text":"是一个民族赖以生存和发展的精神支撑"},{"id":"B","text":"是中华民族的精神独立性得以保持的重要保证"},{"id":"C","text":"是中国精神引领时代前行、拥有强大生命力的重要根源"},{"id":"D","text":"随着历史的变迁逐步融入民族精神的长河之中"}],"answer":["A","C","D"],"analysis":{"point":"本题考查时代精神。时代精神与民族精神紧密关联，都是一个民族赖以生存和发展的精神支撑。一切时代精神都将随着历史的变迁逐步融入民族精神的长河之中。时代精神赋予中国精神以时代内涵，是中国精神引领时代前行、拥有鲜明时代性和强大生命力的重要根源。因此，选项A、C、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"中华民族的精神独立性得以保持的重要保证是民族精神，而不是时代精神，故不选。","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-sixiu-test2-20","moduleId":"advanced","subjectId":"sixiu","chapter":"综合测试二","chapterKey":"综合测试二","n":20,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"思修 · 综合测试二 第 20 题"},"stem":"当今世界，兵戎相见时有发生，冷战思维和强权政治阴魂不散，恐怖主义、难民危机、重大传染性疾病、气候变化等非传统安全威胁持续蔓延。种种景象深刻启示我们：没有国家安全的基础，任何美好蓝图都是空中楼阁。习近平总书记高度重视国家安全问题，多次强调要增强国家安全意识。为此，必须","choices":[{"id":"A","text":"深入了解中华民族“多元一体”的发展历史"},{"id":"B","text":"确立总体国家安全观"},{"id":"C","text":"增强国防意识"},{"id":"D","text":"履行维护国家安全的义务"}],"answer":["B","C","D"],"analysis":{"point":"本题考查增强国家安全意识。增强国家安全意识，需要：第一，确立总体国家安全观；第二，增强国防意识；第三，履行维护国家安全的义务。因此，选项B、C、D正确。","options":{"A":"属于“促进民族团结”的举措，不符合题意，故不选。","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-sixiu-test2-21","moduleId":"advanced","subjectId":"sixiu","chapter":"综合测试二","chapterKey":"综合测试二","n":21,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"思修 · 综合测试二 第 21 题"},"stem":"党的十八大提出，要倡导富强、民主、文明、和谐，倡导自由、平等、公正、法治，倡导爱国、敬业、诚信、友善，积极培育和践行社会主义核心价值观。这是中国共产党凝聚全党全社会价值共识作出的重要论断。社会主义核心价值观倡导的平等是","choices":[{"id":"A","text":"兼顾效率与公平的平等"},{"id":"B","text":"实实在在的平等"},{"id":"C","text":"“不患寡而患不均”的绝对平均主义"},{"id":"D","text":"落在法律文本上的“形式上的平等”"}],"answer":["A","B"],"analysis":{"point":"本题考查社会主义核心价值观。社会主义核心价值观倡导的平等，是兼顾效率与公平的平等，不是“不患寡而患不均”的绝对平均主义；是实实在在的平等，不是落在法律文本上的“形式上的平等”；是要让人人都能公平行使社会权利、履行社会义务、分享社会成果，政治上平等参与、经济上共同富裕、文化上共建共享，同祖国和时代一起成长进步。因此，选项A、B正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"表述错误，上述解析中已经作了解释，故不选。","D":"表述错误，上述解析中已经作了解释，故不选。"}}},{"id":"advanced-sixiu-test2-22","moduleId":"advanced","subjectId":"sixiu","chapter":"综合测试二","chapterKey":"综合测试二","n":22,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"思修 · 综合测试二 第 22 题"},"stem":"社会主义道德建设与社会主义市场经济的关系是","choices":[{"id":"A","text":"社会主义道德建设与社会主义市场经济相适应"},{"id":"B","text":"社会主义道德建设是一个独立的系统，与社会主义市场经济没有必然的联系"},{"id":"C","text":"社会主义道德建设为社会主义市场经济体制的发展和完善提供道德价值导向"},{"id":"D","text":"社会主义道德建设会束缚社会主义市场经济的发展"}],"answer":["A","C"],"analysis":{"point":"本题考查社会主义道德建设与社会主义市场经济的关系。社会主义道德建设为社会主义市场经济体制的发育和完善提供道德价值导向，保证和促进市场经济沿着社会主义方向健康发展，同时，社会主义道德促进社会主义制度优越性和市场经济优势的发挥。所以，社会主义道德建设与在社会主义基本经济制度基础上实行的社会主义市场经济相适应。因此，选项A、C正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"社会主义道德建设和社会主义市场经济有着必然联系。表述错误，故不选。","C":"（正确选项，分析见“解题思路”）","D":"社会主义制度的优越性和市场经济优势的发挥离不开社会主义道德建设的积极作用。表述错误，故不选。"}}},{"id":"advanced-sixiu-test2-23","moduleId":"advanced","subjectId":"sixiu","chapter":"综合测试二","chapterKey":"综合测试二","n":23,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"思修 · 综合测试二 第 23 题"},"stem":"个人品德是通过社会道德教育和个人自觉的道德修养所形成的稳定的心理状态和行为习惯。它是个体对某种道德要求认同和践履的结果，集中体现了道德认知、道德情感、道德意志和道德行为的内在统一。这表明个人品德是","choices":[{"id":"A","text":"在实践活动中锤炼而成的一种特殊品性"},{"id":"B","text":"在实践活动中表现出来的行为的稳定倾向"},{"id":"C","text":"偶然的、短暂的道德行为现象"},{"id":"D","text":"个人行为的统一整体及知、情、意、行的综合体现"}],"answer":["A","B","D"],"analysis":{"point":"本题考查个人品德。个人品德的特点：实践性、稳定性、综合性。因此，选项A、B、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"个人品德是一种稳定的心理状态和行为习惯，并非偶然的、短暂的道德行为现象。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-sixiu-test2-24","moduleId":"advanced","subjectId":"sixiu","chapter":"综合测试二","chapterKey":"综合测试二","n":24,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"思修 · 综合测试二 第 24 题"},"stem":"习近平总书记指出：“我们坚持法律面前人人平等，把尊重和保障人权贯穿立法、执法、司法、守法各个环节，加快完善权利公平、机会公平、规则公平的法律制度，保障公民人身权、财产权、人格权，保障公民参与民主选举、民主协商、民主决策、民主管理、民主监督等基本政治权利，保障公民经济、文化、社会、环境等各方面权利，不断提升人权法治化保障水平。”其中，平等是","choices":[{"id":"A","text":"社会主义法律的基本属性"},{"id":"B","text":"社会主义法治的基本要求"},{"id":"C","text":"全面依法治国的重要依托"},{"id":"D","text":"全面依法治国的前提"}],"answer":["A","B"],"analysis":{"point":"本题考查坚持中国特色社会主义法治道路必须遵循的原则。平等是社会主义法律的基本属性，是社会主义法治的基本要求。坚持法律面前人人平等，对于坚持走中国特色社会主义法治道路具有十分重要的意义。因此，选项A、B正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"有力的法治保障体系是全面依法治国的重要依托，故不选。","D":"科学立法是全面依法治国的前提，故不选。"}}},{"id":"advanced-sixiu-test2-25","moduleId":"advanced","subjectId":"sixiu","chapter":"综合测试二","chapterKey":"综合测试二","n":25,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"思修 · 综合测试二 第 25 题"},"stem":"法治思维是指以法治价值和法治精神为导向，运用法律原则、法律规则、法律方法思考和处理问题的思维模式。下列关于法治思维的说法，正确的有","choices":[{"id":"A","text":"蕴含着公正、平等、民主、人权等法治理念，是一种正当性思维"},{"id":"B","text":"由国家强制力保障实施，是一种暴力性思维"},{"id":"C","text":"以法律手段与法律方法为依托分析问题、处理问题、解决纠纷，是一种逻辑思维"},{"id":"D","text":"是一种符合规律、尊重事实的科学思维"}],"answer":["A","C","D"],"analysis":{"point":"本题考查法治思维。法治思维包括以下四层含义：第一，法治思维以法治价值和法治精神为指导，蕴含着公正、平等、民主、人权等法治理念，是一种正当性思维；第二，法治思维以法律原则和法律规则为依据指导人们的社会行为，是一种规范性思维；第三，法治思维以法律手段与法律方法为依托分析问题、处理问题、解决纠纷，是一种逻辑思维；第四，法治思维是一种符合规律、尊重事实的科学思维。因此，法治思维是一种融法律的价值属性和工具理性于一体的特殊的高级法律意识。因此，选项A、C、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"法律虽然是由国家强制力保障实施的，但这并不代表法治思维是一种暴力性思维。法治思维下，解决问题首先应该通过法律的途径，而不是使用暴力。故不选。","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-sixiu-test2-26","moduleId":"advanced","subjectId":"sixiu","chapter":"综合测试二","chapterKey":"综合测试二","n":26,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"思修 · 综合测试二 第 26 题"},"stem":"中国特色社会主义法治道路的一个鲜明特点，就是坚持依法治国和以德治国相结合。法治和德治，是治国理政不可或缺的两种方式。这是因为法治和德治","choices":[{"id":"A","text":"发挥作用的方式不同"},{"id":"B","text":"调整范围不同"},{"id":"C","text":"所处地位不同"},{"id":"D","text":"实现途径不同"}],"answer":["A","B","C","D"],"analysis":{"point":"本题考查法治和德治的辩证关系。第一，法治和德治的地位。法治是治国理政的基本方略，德治是治国理政的重要方式。第二，法治和德治的作用。法治和德治对社会成员都具有约束作用，法治发挥作用要以国家强制力为后盾，德治发挥作用要通过人们的内心信念、传统习俗、社会舆论等进行道德教化。第三，法治和德治的实现途径。法治和德治的实现方式和实施载体不同。第四，法律与道德的调控范围。法律是道德的底线，法律与道德在社会的不同领域，不同程度地发挥着各自不同的作用。因此，选项A、B、C、D正确。\\n无干扰选项。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-sixiu-test2-27","moduleId":"advanced","subjectId":"sixiu","chapter":"综合测试二","chapterKey":"综合测试二","n":27,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"思修 · 综合测试二 第 27 题"},"stem":"法律权威性是保证法律得以运行和实施的基础。如果失去权威，那法律是什么呢？列宁形象地称之为“那不过是毫无意义的空气振动而已”。尊重社会主义法律权威的重要意义在于","choices":[{"id":"A","text":"是社会主义法治观念的核心要求和建设社会主义法治国家的前提条件"},{"id":"B","text":"对于推进国家治理体系和治理能力现代化、实现国家的长治久安极为重要"},{"id":"C","text":"是实现人民意志、维护人民利益、保障人民权利的基本途径"},{"id":"D","text":"是维护个人合法权益的根本保障"}],"answer":["A","B","C","D"],"analysis":{"point":"本题考查尊重和维护法律权威的意义。全体社会成员尊重社会主义法律权威，不仅是保证法律发挥作用的基本前提和要求，也是保障个人平安幸福的底线和红线。尊重和维护法律权威，对全面依法治国至关重要。第一，是社会主义法治观念的核心要求和建设社会主义法治国家的前提条件。第二，对于推进国家治理体系和治理能力现代化、实现国家的长治久安极为重要。法律权威是国家治理的坚实基础和关键。第三，是实现人民意志、维护人民利益、保障人民权利的基本途径。第四，是维护个人合法权益的根本保障。因此，选项A、B、C、D正确。\\n无干扰选项。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-sixiu-test2-28","moduleId":"advanced","subjectId":"sixiu","chapter":"综合测试二","chapterKey":"综合测试二","n":28,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"思修 · 综合测试二 第 28 题"},"stem":"1763年，老威廉·皮特在《论英国人个人居家安全的权利》的演讲中说：“即使最穷的人，在他的小屋里也能够对抗国王的权威。屋子可能很破旧，屋顶可能摇摇欲坠；风可以吹进这所房子，雨可以淋进这所房子，但是国王不能踏进这所房子，他的千军万马也不敢跨过这间破房子的门槛。”这段话后来被浓缩成“风能进，雨能进，国王不能进”。这凸显了权力和权利的关系是","choices":[{"id":"A","text":"权力应当以权利为界限"},{"id":"B","text":"权力决定权利"},{"id":"C","text":"权力必须受到权利的制约"},{"id":"D","text":"权力优先于权利"}],"answer":["A","C"],"analysis":{"point":"本题考查权利与权力的关系。二者的关系表现为：第一，权力来源于权利；第二，权力服务于权利；第三，权力应当以权利为界限；第四，权力必须受到权利的制约。因此，选项A、C正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"说法本身欠妥，故排除。","C":"（正确选项，分析见“解题思路”）","D":"说法本身欠妥，故排除。"}}},{"id":"advanced-sixiu-test2-29","moduleId":"advanced","subjectId":"sixiu","chapter":"综合测试二","chapterKey":"综合测试二","n":29,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"思修 · 综合测试二 第 29 题"},"stem":"法律权利和法律义务的关系，就像一枚硬币的两面，密不可分。二者之间关系的正确表述是","choices":[{"id":"A","text":"法律权利与法律义务是相互依存的关系"},{"id":"B","text":"法律权利与法律义务是目的与手段的关系"},{"id":"C","text":"法律权利与法律义务具有顺序性"},{"id":"D","text":"有些法律权利与法律义务具有复合性的关系"}],"answer":["A","B","D"],"analysis":{"point":"本题考查法律权利和法律义务之间的关系。第一，法律权利与法律义务是相互依存的关系。法律权利的实现必须以相应法律义务的履行为条件，法律义务的设定和履行也必须以法律权利的行使为根据。第二，法律权利与法律义务是目的与手段的关系。离开了法律权利，法律义务就失去了履行的价值和动力。离开了法律义务，法律权利也形同虚设。第三，有些法律权利和法律义务具有复合性的关系，即一个行为可以同时是权利行为和义务行为。因此，选项A、B、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"表述错误，法律权利和法律义务之间没有“顺序性”，故排除。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-sixiu-test2-30","moduleId":"advanced","subjectId":"sixiu","chapter":"综合测试二","chapterKey":"综合测试二","n":30,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"思修 · 综合测试二 第 30 题"},"stem":"住宅安全权是公民的一项基本权利。下列属于侵犯公民住宅安全权的行为有","choices":[{"id":"A","text":"陌生男子闯入了老王的家"},{"id":"B","text":"陌生男子查封了老王的家"},{"id":"C","text":"国家机关为侦查犯罪进入老王的家"},{"id":"D","text":"陌生男子闯入老王临时居住的宾馆"}],"answer":["A","B","D"],"analysis":{"point":"本题考查对住宅安全权的理解。住宅安全权也称住宅不受侵犯权，是指公民居住、生活、休息的场所不受非法侵入或搜查的权利。住宅安全权包括以下内容：任何公民的住宅不得非法侵入，任何公民的住宅不得随意搜查，任何公民的住宅不得随意查封。这里的“住宅”既包括固定居住的住宅，也包括临时性的住所。因此，选项A、B、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"为合法行为，我国法律规定为了维护公共利益，必要时可以对住宅安全权进行限制，如国家机关为侦查犯罪，可依法对公民住宅进行搜查。故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-sixiu-test3-1","moduleId":"advanced","subjectId":"sixiu","chapter":"综合测试三","chapterKey":"综合测试三","n":1,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"思修 · 综合测试三 第 1 题"},"stem":"马克思说：“人只有为同时代人的完美、为他们的幸福而工作，自己才能达到完美。如果一个人只为自己劳动，他也许能够成为著名的学者、伟大的哲人、卓越的诗人，然而他永远不能成为完美的、真正伟大的人物。”这表明","choices":[{"id":"A","text":"实现自我价值是创造社会价值的原因"},{"id":"B","text":"个人价值的实现取决于他人的认可"},{"id":"C","text":"人生社会价值可以代替自我价值"},{"id":"D","text":"人生价值是自我价值和社会价值的统一"}],"answer":["D"],"analysis":{"point":"本题考查人生的自我价值和社会价值的辩证关系。自我价值是实现个人发展的重要条件，但人生的自我价值是在社会价值实现的基础上实现的，自我价值与社会价值是对立统一的。因此，选项D正确。","options":{"A":"“实现自我价值是创造社会价值的原因”说法错误，自我价值和社会价值没有这种因果关系，故排除。","B":"个人价值指的是个体对自身需要的满足，这与他人的评价没有关系，故排除。","C":"人生的社会价值和自我价值是对立统一的，它们既相互区别又相互联系，但不能相互取代，故排除。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-sixiu-test3-2","moduleId":"advanced","subjectId":"sixiu","chapter":"综合测试三","chapterKey":"综合测试三","n":2,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"思修 · 综合测试三 第 2 题"},"stem":"人的生命是有限的，但生命的意义和价值却可以不同。实现人生价值的根本途径是","choices":[{"id":"A","text":"培养积极进取的人生态度"},{"id":"B","text":"自觉提高自我的主体素质和能力"},{"id":"C","text":"正确认识自我价值和社会价值的关系"},{"id":"D","text":"进行有意识、有目的的创造性实践活动"}],"answer":["D"],"analysis":{"point":"本题考查实现人生价值的根本途径。人生之所以有价值，是因为人能够自觉地、有意识地认识和改造客观世界与主观世界，创造物质财富和精神财富，通过创造性的社会实践把人生提升到一个更高的境界。人生价值目标的实现是一个实践的过程，人生价值的评价就是对实践及其成果的评价。因此，选项D正确。","options":{"A":"具备正确的人生态度和正确认识自我价值和社会价值的关系或许能实现人生的自我价值和社会价值，但如果没有实践根本无法实现人生价值，故不选。","B":"在实现人生价值的实践过程中，应该自觉提高自身能力，但这不是实现人生价值的根本途径，故不选。","C":"具备正确的人生态度和正确认识自我价值和社会价值的关系或许能实现人生的自我价值和社会价值，但如果没有实践根本无法实现人生价值，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-sixiu-test3-3","moduleId":"advanced","subjectId":"sixiu","chapter":"综合测试三","chapterKey":"综合测试三","n":3,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"思修 · 综合测试三 第 3 题"},"stem":"中国特色社会主义共同理想与共产主义远大理想有着内在的联系，它们之间的关系是","choices":[{"id":"A","text":"阶段性理想和最高理想的关系"},{"id":"B","text":"生活理想和道德理想的关系"},{"id":"C","text":"个人理想和社会理想的关系"},{"id":"D","text":"可能实现的理想和根本不可能实现的空想的关系"}],"answer":["A"],"analysis":{"point":"本题考查理想的分类。我国的最高纲领是实现共产主义远大理想，最低纲领即现阶段理想是建设中国特色社会主义。二者具有明显的前后关系，是阶段性理想和最高理想的关系。因此，选项A正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"理想按照内容不同可以分为生活理想、道德理想、政治理想等，故不选。","C":"社会理想是对个人理想的凝练和升华，代表和反映着人们的共同愿望和根本利益，当社会理想同个人理想有矛盾冲突时，有志气、有抱负的人可以作出最大的自我牺牲，使个人的理想服从于全社会的共同理想。故不选。","D":"理想与现实是可以转化的，勇于实践、艰苦奋斗，最终一定会实现中国特色社会主义共同理想即最高理想，故不选。"}}},{"id":"advanced-sixiu-test3-4","moduleId":"advanced","subjectId":"sixiu","chapter":"综合测试三","chapterKey":"综合测试三","n":4,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"思修 · 综合测试三 第 4 题"},"stem":"“立志当高远，立志做大事。”大量的事实告诉我们，那些在事业上取得伟大成就、对人类作出卓越贡献的人，都是在青年时期就立下了鸿鹄之志，并为之坚持不懈、努力奋斗。下列名言能体现这一说法的是","choices":[{"id":"A","text":"“功崇惟志，业广惟勤”"},{"id":"B","text":"“夙夜在公”"},{"id":"C","text":"“己所不欲，勿施于人”"},{"id":"D","text":"“己欲立而立人，己欲达而达人”"}],"answer":["A"],"analysis":{"point":"本题考查立志当高远。题干中“在青年时期就立下了鸿鹄之志，并为之坚持不懈、努力奋斗”强调的是一个人要有志向。“功崇惟志，业广惟勤”的意思是能取得伟大功业，是因为有伟大的志向，完成伟大的功业，在于辛勤不懈地工作。因此，选项A正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"“夙夜在公”的意思是从早到晚，勤于公务，故不选。","C":"“己所不欲，勿施于人”的意思是如果某个结果是自已不想要或不喜欢的，就不要强加给别人，故不选。","D":"“己欲立而立人，己欲达而达人”的意思是自己想要站稳，也要让别人站稳，自己想要腾达，也要让别人腾达，故不选。"}}},{"id":"advanced-sixiu-test3-5","moduleId":"advanced","subjectId":"sixiu","chapter":"综合测试三","chapterKey":"综合测试三","n":5,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"思修 · 综合测试三 第 5 题"},"stem":"习近平在欧美同学会成立100周年庆祝大会上的讲话中说：“希望广大留学人员继承和发扬留学报国的光荣传统，做爱国主义的坚守者和传播者，秉持‘先天下之忧而忧，后天下之乐而乐’的人生理想，始终把国家富强、民族振兴、人民幸福作为努力志向，自觉使个人成功的果实结在爱国主义这棵常青树上。”个人成功的果实之所以应该结在爱国主义这棵常青树上，是因为爱国主义是","choices":[{"id":"A","text":"个人实现人生价值的力量源泉"},{"id":"B","text":"个人实现人生价值的直接条件"},{"id":"C","text":"个人成功的根本保障"},{"id":"D","text":"个人成功的决定性因素"}],"answer":["A"],"analysis":{"point":"本题考查爱国主义的时代价值。爱国主义是中华民族继往开来的精神支柱，是维护祖国统一和民族团结的纽带，是实现中华民族伟大复兴的动力，是个人实现人生价值的力量源泉。因此，选项A正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"个人能否获得成功以及人生价值能否实现，取决于社会实践。故不选。","C":"个人能否获得成功以及人生价值能否实现，取决于社会实践。故不选。","D":"个人能否获得成功以及人生价值能否实现，取决于社会实践。故不选。"}}},{"id":"advanced-sixiu-test3-6","moduleId":"advanced","subjectId":"sixiu","chapter":"综合测试三","chapterKey":"综合测试三","n":6,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"思修 · 综合测试三 第 6 题"},"stem":"习近平在纪念五四运动100周年大会上的讲话中指出：“爱国主义是我们民族精神的核心，是中华民族团结奋斗、自强不息的精神纽带。”“对每一个中国人来说，爱国是本分，也是职责，是心之所系、情之所归。对新时代中国青年来说，热爱祖国是立身之本、成才之基。”当代中国爱国主义的本质就是","choices":[{"id":"A","text":"坚持爱国和爱党、爱社会主义高度统一"},{"id":"B","text":"维护社会和谐和民族平等的统一"},{"id":"C","text":"对民族和文化的归属感、认同感的统一"},{"id":"D","text":"坚持立足民族和面向世界的统一"}],"answer":["A"],"analysis":{"point":"本题考查当代中国爱国主义的本质。爱国主义体现了人们对自己祖国的深厚感情，揭示了个人对祖国的依存关系，是人们对自己家园以及民族和文化的归属感、认同感、尊严感与荣誉感的统一。坚持爱国和爱党、爱社会主义的高度统一是当代中国爱国主义的本质。因此，选项A正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"是当代弘扬爱国主义必须坚持的，但不是当代中国爱国主义的本质。","C":"是当代弘扬爱国主义必须坚持的，但不是当代中国爱国主义的本质。","D":"是当代弘扬爱国主义必须坚持的，但不是当代中国爱国主义的本质。"}}},{"id":"advanced-sixiu-test3-7","moduleId":"advanced","subjectId":"sixiu","chapter":"综合测试三","chapterKey":"综合测试三","n":7,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"思修 · 综合测试三 第 7 题"},"stem":"古往今来，无论是那些对历史作出过较大贡献的政治家、思想家、军事家、文学艺术家，还是那些在祖国历史发展过程中起着决定作用的千千万万普通劳动群众，启迪、指引他们谱写壮丽人生的一个共同思想因素是","choices":[{"id":"A","text":"爱国主义"},{"id":"B","text":"集体主义"},{"id":"C","text":"自由主义"},{"id":"D","text":"社会主义"}],"answer":["A"],"analysis":{"point":"本题考查爱国主义。爱国主义是指个人或集体对自身所属国家的一种积极认同的态度和行为。爱国主义是中华民族继往开来的精神支柱，是维护祖国统一和民族团结的纽带，是实现中华民族伟大复兴的动力，是个人实现人生价值的力量源泉。因此，选项A正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"集体主义是社会主义道德的原则。在社会主义道德体系中，集体主义是指导人们行为选择的主导性原则。这是社会主义经济、政治、文化、社会、生态文明建设的必然要求，故不选。","C":"自由主义夸大了个人的行为准则，忽略了个人行为对社会及他人所造成的影响，不可能是“谱写壮丽人生”的思想因素，故不选。","D":"社会主义不是思想因素的概念，而是意识形态的概念，故不选。"}}},{"id":"advanced-sixiu-test3-8","moduleId":"advanced","subjectId":"sixiu","chapter":"综合测试三","chapterKey":"综合测试三","n":8,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"思修 · 综合测试三 第 8 题"},"stem":"“名非天造，必从其实。”任何一种价值观，如果只是停留在口头上，不管多么动听，也终将被历史抛弃。这说明社会主义核心价值观之所以具有强大的道义力量，最重要的是因为它具有","choices":[{"id":"A","text":"先进性"},{"id":"B","text":"科学性"},{"id":"C","text":"人民性"},{"id":"D","text":"真实性"}],"answer":["D"],"analysis":{"point":"本题考查社会主义核心价值观的显著特征。社会主义核心价值观不仅真正地与社会主义制度相契合，与保障人民的根本利益相一致，而且因其真实可信而具有强大的道义力量。因此，选项D正确。","options":{"A":"社会主义核心价值观体现社会主义的本质属性、扎根中华优秀传统文化土壤、吸纳世界文明有益成果，这是其先进性的体现。与题意不符，故不选。","B":"社会主义核心价值观是科学的价值观，但与本题关联度较低，故不选。","C":"社会主义核心价值观尊重人民群众历史主体地位、体现以人民为中心的价值导向，这是其人民性的体现。与题意不符，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-sixiu-test3-9","moduleId":"advanced","subjectId":"sixiu","chapter":"综合测试三","chapterKey":"综合测试三","n":9,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"思修 · 综合测试三 第 9 题"},"stem":"在东西方传统文化中，都有重视荣誉的思想观念。莎士比亚曾说：“生命是每一个人所重视的，可是高贵的人重视荣誉远过于生命。”下列格言中，与这句话含义一致的是","choices":[{"id":"A","text":"“礼之用，和为贵”"},{"id":"B","text":"“宁可毁人，不可毁誉”"},{"id":"C","text":"“己所不欲，勿施于人”"},{"id":"D","text":"“三人行，必有我师焉”"}],"answer":["B"],"analysis":{"point":"本题考查道德修养。选项B的意思是个人的声誉比生命更重要，与题干中“高贵的人重视荣誉远过于生命”相符。因此，选项B正确。","options":{"A":"意思是礼的作用在于使人际关系和谐。与题意不符，故不选。","B":"（正确选项，分析见“解题思路”）","C":"意思是如果某个结果是自己不想要或不喜欢的，就不要强加给别人。与题意不符，故不选。","D":"意思是几个人同行，其中必定有可以作为我的老师的人。与题意不符，故不选。"}}},{"id":"advanced-sixiu-test3-10","moduleId":"advanced","subjectId":"sixiu","chapter":"综合测试三","chapterKey":"综合测试三","n":10,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"思修 · 综合测试三 第 10 题"},"stem":"鲁国宰相公孙仪喜欢吃鱼，许多人争着买鱼给他吃，他一条也不接受。其弟子问：“夫子嗜鱼而不受者，何也？”公孙仪说：“夫唯嗜鱼，故不受也。夫即受鱼，心有下人之色，有下人之色，将枉于法，枉于法，则免于相。”“公孙仪嗜鱼而不受”给我们的启示是","choices":[{"id":"A","text":"从业人员应该诚实劳动、合法经营、信守承诺、讲求信誉"},{"id":"B","text":"从业人员要热爱自己的工作岗位，敬重自己所从事的职业"},{"id":"C","text":"从业人员在职业活动中应做到不谋私利、不徇私情"},{"id":"D","text":"从业人员在自己的工作岗位上应树立奉献社会的职业精神"}],"answer":["C"],"analysis":{"point":"本题考查职业道德。鲁国宰相公仪休“嗜鱼而不受”的故事，千百年来之所以被人们传为美谈，就是因为公孙仪能够清醒地认识个人好恶与事业兴衰成败之间的关系，始终做到管住小节，抵制诱惑，慎其所好，不谋私利，不徇私情。因此，选项C正确。","options":{"A":"题干不涉及诚实守信的问题，故不选。","B":"题干并非在谈爱岗敬业，故不选。","C":"（正确选项，分析见“解题思路”）","D":"题干没有涉及奉献社会，故不选。"}}},{"id":"advanced-sixiu-test3-11","moduleId":"advanced","subjectId":"sixiu","chapter":"综合测试三","chapterKey":"综合测试三","n":11,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"思修 · 综合测试三 第 11 题"},"stem":"任何公民只要违反了法律，都必须受到追究，法律面前人人平等。这体现的是我国社会主义法治基本要求中的","choices":[{"id":"A","text":"有法可依的含义"},{"id":"B","text":"有法必依的含义"},{"id":"C","text":"执法必严的含义"},{"id":"D","text":"违法必究的含义"}],"answer":["D"],"analysis":{"point":"本题考查社会主义法治的基本要求。违法必究就是对一切违法犯罪行为都要按照“以事实为依据，以法律为准绳”的原则，给予惩处。法律面前人人平等，不容许任何组织和个人有超越宪法和法律的特权。因此，选项D正确。","options":{"A":"有法可依就是要建立统一、完备、科学的法律体系和制度，即立法能够适应不断发展的经济、政治、文化和社会生活的需要，及时对各种社会关系进行规范。与题意不符，故不选。","B":"有法必依就是要保证法律效力的普遍性和有效性，即尽量排除和杜绝立法、执法、司法、守法和法律监督中的随意性、偶然性和腐败现象；坚持法律面前人人平等，任何组织和个人都不能有超越宪法和法律的特权。与题意不符，故不选。","C":"执法必严就是要确保严格、公正的执法和司法。司法机关应当独立、公正地行使司法权，不受其他机关、社会团体和个人的非法干预。与题意不符，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-sixiu-test3-12","moduleId":"advanced","subjectId":"sixiu","chapter":"综合测试三","chapterKey":"综合测试三","n":12,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"思修 · 综合测试三 第 12 题"},"stem":"在中国古典小说中常有“杀富济贫”“大义灭亲”“替天行道”等充满传统道义的故事，但在现代法治社会中，以上行为是不可取的。因为我们不仅要弘扬道德规范，更要遵守法律规范。这体现的法治思维是","choices":[{"id":"A","text":"权力制约"},{"id":"B","text":"公平正义"},{"id":"C","text":"权利保障"},{"id":"D","text":"法律至上"}],"answer":["D"],"analysis":{"point":"本题考查对法治思维的理解。法律至上是指在国家或社会的所有规范中，法律是地位最高、效力最广、强制力最大的规范。现代国家会有很多规范，如宗教规范、道德规范、团体规范和行业规范等，法律至上要求这些规范都不得超越法律规范，都不得与法律规范相抵触，都必须遵守和服从法律规范。所以，当传统道德与法律相冲突时，要坚持法律至上。因此，选项D正确。","options":{"A":"权力制约是指国家机关的权力必须受到法律的规制和约束，也就是要把权力关进制度的笼子里。与题意不符，故不选。","B":"公平正义是指社会的政治利益、经济利益和其他利益在全体社会成员之间合理、平等分配和占有。一般来讲，公平正义主要包括权利公平、机会公平、规则公平和救济公平。与题意不符，故不选。","C":"权利的法律保障包括宪法保障、立法保障、行政保障和司法保障。宪法保障是权利保障的前提和基础。与题意不符，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-sixiu-test3-13","moduleId":"advanced","subjectId":"sixiu","chapter":"综合测试三","chapterKey":"综合测试三","n":13,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"思修 · 综合测试三 第 13 题"},"stem":"我国宪法规定了公民的基本权利和义务。下列既属于公民权利，又属于公民义务的是","choices":[{"id":"A","text":"劳动"},{"id":"B","text":"政治自由"},{"id":"C","text":"人身自由"},{"id":"D","text":"依法纳税"}],"answer":["A"],"analysis":{"point":"本题考查宪法规定的我国公民的基本权利和义务。我国宪法规定我国公民享有下列基本权利：①平等权；②选举权与被选举权；③言论、出版、集会、结社、游行、示威的自由；④宗教信仰自由；⑤人身自由、人格尊严、住宅不受侵犯和通信自由；⑥劳动权；⑦受教育权；等等。我国宪法规定的公民的基本义务：①维护国家统一和全国各民族团结；②遵守宪法和法律、保守国家秘密、爱护公共财产、遵守劳动纪律、遵守公共秩序、尊重社会公德；③维护祖国安全、荣誉和利益；④劳动的义务；⑤受教育的义务；⑥保卫祖国、抵抗侵略、依法服兵役和参加民兵组织；⑦依法纳税；等等。因此，选项A正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"属于权利范畴，不属于义务范畴，故不选。","C":"属于权利范畴，不属于义务范畴，故不选。","D":"属于义务范畴，不属于权利范畴，故不选。"}}},{"id":"advanced-sixiu-test3-14","moduleId":"advanced","subjectId":"sixiu","chapter":"综合测试三","chapterKey":"综合测试三","n":14,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"思修 · 综合测试三 第 14 题"},"stem":"我国宪法规定，公民的基本义务主要有：遵守宪法和法律；维护国家统一和全国各民族团结；维护祖国安全、荣誉和利益；保守国家秘密，爱护公共财产，遵守劳动纪律、公共秩序，尊重社会公德；依法服兵役；依法纳税；等等。其中，我国公民的最高法律义务是","choices":[{"id":"A","text":"依法纳税和依法服兵役"},{"id":"B","text":"遵守宪法和法律"},{"id":"C","text":"维护祖国安全、荣誉和利益"},{"id":"D","text":"维护国家统一和全国各民族团结"}],"answer":["D"],"analysis":{"point":"本题考查我国公民的基本义务。我国宪法规定：“中华人民共和国公民有维护国家统一和全国各民族团结的义务。”国家的统一和民族的团结是我国社会安定和谐的前提和保证，是我国公民的最高法律义务。因此，选项D正确。","options":{"A":"均属于公民的基本义务，但不是最高法律义务，故不选。","B":"均属于公民的基本义务，但不是最高法律义务，故不选。","C":"均属于公民的基本义务，但不是最高法律义务，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-sixiu-test3-15","moduleId":"advanced","subjectId":"sixiu","chapter":"综合测试三","chapterKey":"综合测试三","n":15,"kindLabel":"单项选择题","kind":"single","source":{"book":"徐涛《优题库·拔高篇》","location":"思修 · 综合测试三 第 15 题"},"stem":"人格尊严是人之为人所应当享有的地位、待遇或尊重的总和，集中表现为人的自尊心和自爱心，是人身权利的重要组成部分。下列不属于公民人格尊严权的是","choices":[{"id":"A","text":"荣誉权"},{"id":"B","text":"隐私权"},{"id":"C","text":"肖像权"},{"id":"D","text":"通信自由权"}],"answer":["D"],"analysis":{"point":"本题考查人格尊严权。人格尊严权，即与人身有密切联系的名誉、姓名、肖像等不容侵犯的权利。人格尊严的基本内容有姓名权、肖像权、名誉权、荣誉权、隐私权等。通讯自由权与人格尊严权同属于人身权利，二者是逻辑上平行的子概念，因此通信自由权不属于人格尊严权。因此，选项D正确。","options":{"A":"都属于人格尊严权，故不选。","B":"都属于人格尊严权，故不选。","C":"都属于人格尊严权，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-sixiu-test3-16","moduleId":"advanced","subjectId":"sixiu","chapter":"综合测试三","chapterKey":"综合测试三","n":16,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"思修 · 综合测试三 第 16 题"},"stem":"我国民法通则、合同法、物权法中，都有要求民事主体在进行民事活动时应当尊重社会公德，不得损害公共利益和经济秩序的内容，已经具有“公序良俗”的含义。2017年10月1日起施行的民法总则明确规定“民事主体从事民事活动，不得违反法律，不得违背公序良俗”，从民法基本原则的高度确立了禁止违反公序良俗的原则。这一规定体现了","choices":[{"id":"A","text":"依法治国和以德治国的有机统一"},{"id":"B","text":"对传统民法公序良俗原则的继承和发展"},{"id":"C","text":"法律为道德建设提供制度保障"},{"id":"D","text":"思想道德为法律提供价值基础"}],"answer":["A","B","C","D"],"analysis":{"point":"本题考查思想道德与法律的辩证关系。思想道德支撑法律，为法律提供价值基础。民法总则的公序良俗原则是对传统民法公序良俗原则的继承和发展，是法律为思想道德提供制度保障的重要表现，体现了依法治国和以德治国的有机统一。因此，选项A、B、C、D正确。\\n无干扰选项。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-sixiu-test3-17","moduleId":"advanced","subjectId":"sixiu","chapter":"综合测试三","chapterKey":"综合测试三","n":17,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"思修 · 综合测试三 第 17 题"},"stem":"2019年10月，中共中央、国务院印发的《新时代公民道德建设实施纲要》是在中国特色社会主义进入新时代的背景下，推动我国精神文明建设再上新高度、为实现中华民族伟大复兴中国梦凝心铸魂的指导性文件。新时代公民道德建设的重点任务是","choices":[{"id":"A","text":"筑牢理想信念之基"},{"id":"B","text":"培育和践行社会主义核心价值观"},{"id":"C","text":"传承中华传统美德"},{"id":"D","text":"弘扬民族精神和时代精神"}],"answer":["A","B","C","D"],"analysis":{"point":"本题考查新时代公民道德建设的重点任务。中共中央、国务院印发的《新时代公民道德建设实施纲要》强调，新时代公民道德建设的重点任务是筑牢理想信念之基、培育和践行社会主义核心价值观、传承中华传统美德、弘扬民族精神和时代精神。因此，选项A、B、C、D正确。\\n无干扰选项。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-sixiu-test3-18","moduleId":"advanced","subjectId":"sixiu","chapter":"综合测试三","chapterKey":"综合测试三","n":18,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"思修 · 综合测试三 第 18 题"},"stem":"党的二十大站在党和国家事业发展全局的战略高度，把“弘扬伟大建党精神”写进大会主题，强调“弘扬以伟大建党精神为源头的中国共产党人精神谱系”。中国共产党人的精神谱系，由一个个鲜明具体的“坐标”组成，犹如鲜活生动的历史链条，展示了中国共产党人崇高的精神风范。这一精神谱系","choices":[{"id":"A","text":"集中体现了党的坚定信念、根本宗旨、优良作风"},{"id":"B","text":"深深融入党、国家、民族、人民的血脉之中"},{"id":"C","text":"是马克思主义中国化时代化的理论创新成果"},{"id":"D","text":"凝聚着中国共产党人艰苦奋斗、牺牲奉献、开拓进取的伟大品格"}],"answer":["A","B","D"],"analysis":{"point":"本题考查中国共产党人的精神谱系。中国共产党人的精神谱系，集中体现了党的坚定信念、根本宗旨、优良作风，凝聚着中国共产党人艰苦奋斗、牺牲奉献、开拓进取的伟大品格，深深融入党、国家、民族、人民的血脉之中，极大丰富了中国精神的内涵，鼓舞和激励中国人民攻坚克难，不断从胜利走向新的胜利。因此，选项A、B、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"马克思主义中国化时代化的理论创新成果是毛泽东思想、中国特色社会主义理论体系和习近平新时代中国特色社会主义思想，而不是中国共产党人的精神谱系。故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-sixiu-test3-19","moduleId":"advanced","subjectId":"sixiu","chapter":"综合测试三","chapterKey":"综合测试三","n":19,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"思修 · 综合测试三 第 19 题"},"stem":"在中国共产党的领导下，走中国特色社会主义道路，实现中华民族伟大复兴，是现阶段我国各族人民的共同理想。这个共同理想","choices":[{"id":"A","text":"是人类最崇高的理想境界"},{"id":"B","text":"是人类迈向共产主义最高理想的唯一道路"},{"id":"C","text":"集中体现了我国工人、农民、知识分子和其他劳动者、建设者和爱国者的利益和愿望"},{"id":"D","text":"是保证全体人民在政治上、道义上和精神上团结一致，争取胜利的强大精神武器"}],"answer":["C","D"],"analysis":{"point":"本题考查现阶段我国各族人民的共同理想。建设和发展中国特色社会主义、实现中华民族伟大复兴，是现阶段我国各族人民的共同理想。这个共同理想集中体现了我国工人、农民、知识分子和其他劳动者、建设者和爱国者的利益和愿望，是保证全体人民团结奋斗、克服困难、争取胜利的强大精神武器。因此，选项C、D正确。","options":{"A":"人类最崇高的理想是实现共产主义，故不选。","B":"各国都有选择自己道路的权利，中国特色社会主义道路适合中国，但不是人类迈向共产主义的唯一道路，故不选。","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-sixiu-test3-20","moduleId":"advanced","subjectId":"sixiu","chapter":"综合测试三","chapterKey":"综合测试三","n":20,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"思修 · 综合测试三 第 20 题"},"stem":"个人品德是通过社会道德教育和个人自觉的道德修养所形成的稳定的心理状态和行为习惯。在现实生活中，个人品德的作用主要表现为","choices":[{"id":"A","text":"个人品德是维护社会成员之间最基本的社会关系秩序的最起码的道德要求"},{"id":"B","text":"个人品德对道德和法律作用的发挥具有重要的推动作用"},{"id":"C","text":"个人品德是个人实现自我完善的内在根据"},{"id":"D","text":"个人品德是经济社会发展进程中重要的主体精神力量"}],"answer":["B","C","D"],"analysis":{"point":"本题考查个人品德。在现实生活中，个人品德的作用主要表现为三个方面：其一，个人品德对道德和法律作用的发挥具有重要的推动作用。社会道德和法律要求只有内化为个人品德，才能成为现实的规范力量。同时，个人品德提升的过程也是能动地作用于社会道德和法律的过程，它能够为社会道德和法律的发展进步创造条件、提供动力。其二，个人品德是个人实现自我完善的内在根据。一个人在行为过程中整合行为动机、确定行为目标、自觉调控行为过程等都是个人品德功能和作用的体现。其三，个人品德是经济社会发展进程中重要的主体精神力量。作为劳动主体的人，是经济社会发展的核心动力，而个人品德是决定人的综合素质的核心要素。因此，选项B、C、D正确。","options":{"A":"公共生活中的道德规范即社会公德，是指人们在社会交往和公共生活中应该遵守的行为准则，是维护社会成员之间最基本的社会关系秩序、保证社会和谐稳定的最起码的道德要求，涵盖了人与人、人与社会、人与自然之间的关系。表述有误，故不选。","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-sixiu-test3-21","moduleId":"advanced","subjectId":"sixiu","chapter":"综合测试三","chapterKey":"综合测试三","n":21,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"思修 · 综合测试三 第 21 题"},"stem":"新冠肺炎疫情是对国家公共卫生体系的一次大考，改变了人们很多日常公共生活习惯，如就餐使用公筷、排队保持社交距离、出入公共场合要戴口罩、不随地吐痰等。有序的公共生活对于社会的价值包括","choices":[{"id":"A","text":"是社会生产活动的重要基础"},{"id":"B","text":"是提高社会成员生活质量的基本保障"},{"id":"C","text":"必须以牺牲个人利益为前提来维护"},{"id":"D","text":"是社会文明的重要标志"}],"answer":["A","B","D"],"analysis":{"point":"本题考查有序的公共生活的重要意义。公共秩序是由一定规则维系的人们公共生活的一种有序化状态，如工作秩序、教学秩序、营业秩序、交通秩序、娱乐秩序、网络秩序等。有序的公共生活是社会生产活动的重要基础，是提高社会成员生活质量的基本保障，更是社会文明的重要标志。因此，选项A、B、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"有序的公共生活是对个人生活的保障，符合个人利益，二者的利益是一致的。表述错误，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-sixiu-test3-22","moduleId":"advanced","subjectId":"sixiu","chapter":"综合测试三","chapterKey":"综合测试三","n":22,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"思修 · 综合测试三 第 22 题"},"stem":"鲍卫忠24年坚守在边疆基层执法办案的第一线、服务群众的最前沿，将法治的“刚性”与德治的“柔性”相结合。在良法善治之间，鲍卫忠这位温良的法律人，在大山深处、村村寨寨种下了规则、种下了德行、种下了善意春风，他护卫了佤山正义，收获了百姓心中万亩良田。鲍卫忠的法治实践，为“法治”与“德治”相结合的实现，提供了诸多方法论的启示。推动法治和德治的相互促进需要做到","choices":[{"id":"A","text":"强化道德对法治的支撑作用"},{"id":"B","text":"把道德要求贯彻到法治建设中"},{"id":"C","text":"法治与德治在本质上是一致的"},{"id":"D","text":"运用法治手段解决道德领域突出问题"}],"answer":["A","B","D"],"analysis":{"point":"本题考查法治与德治的关系。推动法治和德治的相互促进：一是强化道德对法治的支撑作用；二是把道德要求贯彻到法治建设中；三是运用法治手段解决道德领域突出问题。因此，选项A、B、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"法治与德治在本质上是不一致的，法治的核心在于法律规范，德治的核心在于道德规范，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-sixiu-test3-23","moduleId":"advanced","subjectId":"sixiu","chapter":"综合测试三","chapterKey":"综合测试三","n":23,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"思修 · 综合测试三 第 23 题"},"stem":"建设高效的法治实施体系，是建设中国特色社会主义法治体系的重点。高效的法治实施体系是指执法、司法、守法等各个环节有效衔接、协调高效运转、持续共同发力，实现效果最大化的法治实施系统。其中，司法发挥着影响深远、不可或缺的重要作用。下列关于司法的说法，正确的有","choices":[{"id":"A","text":"公正司法是维护社会公平正义的最后一道防线"},{"id":"B","text":"法律执行是国家行政机关及其公职人员执行法律的活动"},{"id":"C","text":"我国的司法机关包括人民法院和人民检察院"},{"id":"D","text":"公民在法律面前一律平等是一项司法原则"}],"answer":["A","C","D"],"analysis":{"point":"本题考查司法的相关内容。公正是法治的生命线，是司法活动的最高价值追求，公正司法是维护社会公平正义的最后一道防线。选项A正确。司法又称法律适用，是指国家司法机关及其公职人员依照法定职权和程序适用法律处理案件的专门活动。我国的司法机关是指国家检察机关和审判机关，即人民检察院和人民法院。选项C正确。司法原则主要有：司法公正；公民在法律面前一律平等；以事实为依据，以法律为准绳；司法机关依法独立行使司法权。选项D正确。因此，选项A、C、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"狭义的法律执行又称行政执法，是指国家行政机关及其公职人员执行法律的活动。与题意不符，故不选。","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-sixiu-test3-24","moduleId":"advanced","subjectId":"sixiu","chapter":"综合测试三","chapterKey":"综合测试三","n":24,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"思修 · 综合测试三 第 24 题"},"stem":"法律规定公民有表达权，但权利要依法行使，尤其是自媒体时代，人人都有“麦克风”、处处都是“直播间”。这支“麦克风”并不是可以随心所欲使用的，应以法律的相关规定为界限。对行使法律权利界限的正确理解是","choices":[{"id":"A","text":"权利行使要有目的的正当性"},{"id":"B","text":"权利行使的方式具有唯一性"},{"id":"C","text":"权利行使不能超过法定的限度"},{"id":"D","text":"权利行使要遵循程序正当的原则"}],"answer":["A","C","D"],"analysis":{"point":"本题考查依法行使法律权利。依法行使法律权利要求公民行使权利时应严格依据法律进行，以法律的相关规定为界限，如权利行使目的的正当性、必须依照法律规定的限度来行使权利、权利行使方式的法定性、权利行使要有正当程序等。因此，选项A、C、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"权利行使的方式有口头方式、书面方式和行为方式等，不具有唯一性。","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-sixiu-test3-25","moduleId":"advanced","subjectId":"sixiu","chapter":"综合测试三","chapterKey":"综合测试三","n":25,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"思修 · 综合测试三 第 25 题"},"stem":"确保权力正确行使，必须让权力在阳光下运行，加强对权力的制约和监督。完善法治监督体系应该形成全面覆盖、常态有效的监督合力，包括","choices":[{"id":"A","text":"党内监督"},{"id":"B","text":"民主监督"},{"id":"C","text":"人大监督"},{"id":"D","text":"舆论监督"}],"answer":["A","B","C","D"],"analysis":{"point":"本题考查严密的法治监督体系。完善法治监督体系的重点内容包括发挥党内监督、人大监督、民主监督、行政监督、司法监督、审计监督、社会监督、舆论监督的合力。因此，选项A、B、C、D正确。\\n无干扰选项。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-sixiu-test3-26","moduleId":"advanced","subjectId":"sixiu","chapter":"综合测试三","chapterKey":"综合测试三","n":26,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"思修 · 综合测试三 第 26 题"},"stem":"公共生活中个人权利与他人权利发生冲突在所难免，比如学生宿舍里有人看书，有人休息，有人要听音乐……对解决权利冲突要有正确的认识，虽然每个人都有行使个人权利的自由，但也要尊重他人的权利。这是因为","choices":[{"id":"A","text":"尊重他人权利是公民权利意识的重要内容"},{"id":"B","text":"尊重他人权利既是一项法律义务，也是一项道德义务"},{"id":"C","text":"权利实现的内在动力是人们彼此之间对各自权利的相互尊重"},{"id":"D","text":"不尊重他人权利，就可能丧失自己的权利"}],"answer":["A","B","C","D"],"analysis":{"point":"本题考查个人权利与社会责任的关系。个人的权利是在社会中获得的，没有社会，个人的权利就无从谈起。离开了个人对社会所承担的责任，个人的权利也就无从实现。因此，享受个人的权利与承担社会的责任是统一的，这既是道德要求，也是法律规范。每个人都希望自己的权利得到尊重，这种内在动力会驱使我们同样尊重别人的权利，不尊重他人权利，就可能丧失自己的权利。因此，选项A、B、C、D正确。\\n无干扰选项。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-sixiu-test3-27","moduleId":"advanced","subjectId":"sixiu","chapter":"综合测试三","chapterKey":"综合测试三","n":27,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"思修 · 综合测试三 第 27 题"},"stem":"法治思维是在丰富的法律实践中训练、培养和应用的思维方式。脱离法治建设的生动实践，难以养成法治思维方式。参与法治实践的方式和途径有","choices":[{"id":"A","text":"参与法律问题讨论"},{"id":"B","text":"旁听司法审判"},{"id":"C","text":"进行法律监督"},{"id":"D","text":"参与立法讨论"}],"answer":["A","B","C","D"],"analysis":{"point":"本题考查参与法治实践的方式和途径。如今，人们参与法治实践的方式和途径越来越多。具体包括：一是参与立法讨论；二是依法行使监督权；三是旁听司法审判；四是参与模拟法庭等实践活动。因此，选项A、B、C、D正确。\\n无干扰选项。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-sixiu-test3-28","moduleId":"advanced","subjectId":"sixiu","chapter":"综合测试三","chapterKey":"综合测试三","n":28,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"思修 · 综合测试三 第 28 题"},"stem":"国家税务总局制定了《营业税改征增值税跨境应税行为增值税免税管理办法（试行）》，自2016年5月1日起施行之后，各地税务局就新规定进行了宣讲、审查等多方面工作保证规章实施。在这个过程中，部分企业受到处罚，绝大多数企业学习并接受了新的免税管理办法。在这个事例中包括的法律运行环节有","choices":[{"id":"A","text":"法律制定"},{"id":"B","text":"法律执行"},{"id":"C","text":"法律适用"},{"id":"D","text":"法律遵守"}],"answer":["A","B","D"],"analysis":{"point":"本题考查法律运行的过程。法律的运行是一个从创制、实施到实现的过程。这个过程主要包括法律制定（立法）、法律执行（执法）、法律适用（司法）、法律遵守（守法）等环节。题干中国家税务总局制定的《营业税改征增值税跨境应税行为增值税免税管理办法（试行）》，体现了法律的制定；税务局组织宣讲、审查等工作以及企业学习并接受新的免税管理办法，体现了法律的遵守；部分企业受到处罚，体现了法律的执行。因此，选项A、B、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"（正确选项，分析见“解题思路”）","C":"属于法律运行的环节之一，但题干中并没有提及司法部门或司法环节，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-sixiu-test3-29","moduleId":"advanced","subjectId":"sixiu","chapter":"综合测试三","chapterKey":"综合测试三","n":29,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"思修 · 综合测试三 第 29 题"},"stem":"马克思曾说：“法律应当以社会为基础，法律应该是社会共同的、由一定的物质生产方式所产生的利益和需要的表现。”我国社会主义法律的本质特征是","choices":[{"id":"A","text":"统一性和层次性的统一"},{"id":"B","text":"阶级性与人民性的统一"},{"id":"C","text":"继承性和创造性的统一"},{"id":"D","text":"科学性和先进性的统一"}],"answer":["B","D"],"analysis":{"point":"本题考查社会主义法律的本质特征。从体现的意志看，我国社会主义法律是中国共产党的主张和人民共同意志的体现，是阶级性与人民性的统一；从实质内容看，我国社会主义法律是社会历史发展规律和自然规律的反映，是科学性和先进性的统一。因此，选项B、D正确。","options":{"A":"是社会主义法律体系的特征，但不是社会主义法律的本质特征。与题意不符，故不选。","B":"（正确选项，分析见“解题思路”）","C":"是社会主义法律体系的特征，但不是社会主义法律的本质特征。与题意不符，故不选。","D":"（正确选项，分析见“解题思路”）"}}},{"id":"advanced-sixiu-test3-30","moduleId":"advanced","subjectId":"sixiu","chapter":"综合测试三","chapterKey":"综合测试三","n":30,"kindLabel":"多项选择题","kind":"multi","source":{"book":"徐涛《优题库·拔高篇》","location":"思修 · 综合测试三 第 30 题"},"stem":"党的领导是中国特色社会主义最本质的特征，是社会主义法治最根本的保证。社会主义法治必须坚持党的领导，党的领导必须依靠社会主义法治。坚持党的领导，不是一句空的口号，必须体现在党","choices":[{"id":"A","text":"领导立法"},{"id":"B","text":"带头执法"},{"id":"C","text":"支持司法"},{"id":"D","text":"带头守法"}],"answer":["A","C","D"],"analysis":{"point":"本题考查坚持走中国特色社会主义法治道路的相关内容。坚持党的领导必须体现在党领导立法、保证执法、支持司法、带头守法上。因此，选项A、C、D正确。","options":{"A":"（正确选项，分析见“解题思路”）","B":"表述错误，执法机关主要指国家的行政机关，而党组织只是保证执法机关正常履行职能，本身不能执法，故不选。","C":"（正确选项，分析见“解题思路”）","D":"（正确选项，分析见“解题思路”）"}}}]`);export{e as default};